/* =========================================================================
   أدوار الإدارة
   -------------------------------------------------------------------------
   كان الدورُ الإداريُّ واحداً — «مشرف» — ونطاقُه وحده هو ما يفرّق بين من
   يدير مجمّعاً ومن يدير مسجداً. فصار لكلٍّ دورُه باسمه:

     complexManager — مدير المجمّع: مجمّعُه ومساجدُه ومدراؤها
     mosqueManager  — مدير المسجد: مسجدُه وحلقاتُه لا غير

   و supervisor يبقى معترفاً به: حساباتُ العملاء القائمة تحمله، وحذفُه من
   الفحوص يقطع الكتابةَ عن أصحابها في اللحظة التي يُنشر فيها هذا الملف.
   يُقرأ كمدير مسجدٍ حتى يُرحَّل، ولا يُعرض في قائمة الأدوار للحسابات
   الجديدة — فلا يزيد عددُه بعد اليوم.

   وكلُّ فحصٍ كان يقول role === "supervisor" صار يقول isMgrRole(role):
   الأدوارُ الثلاثة إداريّة، والذي يفرّق بينها هو canDo لا هذه الفحوص.
   ========================================================================= */
const MGR_ROLES = ["supervisor", "complexManager", "mosqueManager"];

function isMgrRole(r) {
  return MGR_ROLES.indexOf(String(r || "")) > -1;
}

/* الدورُ الإداريُّ ومستواه — يُقرأ من الدور لا من النطاق وحده */
function isComplexMgr(r) { return String(r || "") === "complexManager"; }
function isMosqueMgr(r)  {
  const s = String(r || "");
  return s === "mosqueManager" || s === "supervisor";
}

/* =========================================================
   PAGE HEADER HELPER
   ========================================================= */
function pageHead(title, sub, actions) {
  return `<div class="page-head"><div><h2>${esc(title)}</h2>${sub ? `<div class="sub">${esc(sub)}</div>` : ""}</div>${actions ? `<div class="page-head-actions">${actions}</div>` : ""}</div>`;
}
function addBtn(label, action) { return `<button class="btn btn-primary" data-action="${action}">${ic("plus", 16)} ${esc(label)}</button>`; }

/* =========================================================================
   تصديرُ أيِّ تقريرٍ إلى PDF
   -------------------------------------------------------------------------
   المواصفات: «أريد جعل أي تقارير من السهل أن تكون PDF».
   لا مكتبةَ PDF في المشروع ولا خطوةَ بناءٍ تُضيفها، فالتصديرُ عبر مطبعة
   المتصفّح: «حفظ كـ PDF» في نافذة الطباعة — وهي تُخرج نصاً عربياً حقيقياً
   يُبحث فيه ويُنسخ، بخلاف صورةٍ تُلتقط للصفحة.
   وكانت أزرارُ PDF الموجودةُ تستدعي window.print مباشرةً بلا ورقةِ طباعةٍ
   عامّةٍ في المشروع، فتُطبع معها القائمةُ الجانبيةُ والشريطان والأزرار.
   فأُضيفت الورقةُ في styles.css، وهذا المساعدُ يضع ترويسةَ التقرير فوقه
   (اسمُ النظام والعنوانُ والمنشأةُ وتاريخُ الإصدار هجرياً) ثمّ ينزعها بعد
   الطباعة فلا يراها أحدٌ على الشاشة.
   ========================================================================= */
const PDF_ICON = '<svg viewBox="0 0 32 32" width="26" height="26" fill="none">' +
  '<path d="M7 3.6h11.4L25 10.2V27a1.4 1.4 0 01-1.4 1.4H7A1.4 1.4 0 015.6 27V5A1.4 1.4 0 017 3.6z" fill="#fff" stroke="#d64541" stroke-width="1.7"/>' +
  '<path d="M18.4 3.6V10h6.6" stroke="#d64541" stroke-width="1.7" stroke-linejoin="round"/>' +
  '<rect x="4" y="16.4" width="20" height="8" rx="1.6" fill="#d64541"/>' +
  '<text x="14" y="22.6" font-size="6" font-weight="700" fill="#fff" text-anchor="middle" font-family="Arial">PDF</text>' +
  '</svg>';

/* زرُّ التصدير — واحدٌ لكلّ الشاشات، بالشكل المعتمد في تقارير الإدارة */
function pdfBtn(title) {
  return `<button class="rep-exp e-pdf" title="تصدير PDF"
    onclick="window.pdfPrint('${jsAttr(title || "")}')">${PDF_ICON}</button>`;
}
window.pdfBtn = pdfBtn;

window.pdfPrint = function (title) {
  const root = document.getElementById("pageContent") || document.body;
  let t = String(title || "");
  if (!t) {
    const h = root.querySelector(".page-head h2");
    t = h ? h.textContent.trim() : "تقرير";
  }
  let fac = "";
  try {
    const c = typeof currentComplex === "function" ? currentComplex() : null;
    fac = c ? String(c.name || "") : "";
  } catch (e) {}

  const old = document.getElementById("pdfHead");
  if (old) { try { old.remove(); } catch (e) {} }
  const oldS = document.getElementById("pdfPage");
  if (oldS) { try { oldS.remove(); } catch (e) {} }

  /* الجداولُ العريضةُ لا تسع الورقةَ قائمةً: تُقلب الورقةُ عرضياً ثمّ
     يُصغَّر المحتوى بقدر ما يُدخله في عرضها. وبلا هذا كان الجدولُ يُقصّ
     عند حافّة الورقة فتضيع أعمدتُه بلا إشعار. العرضُ المطبوعُ من A4:
     ١٩٠مم قائمةً و٢٧٧مم عرضيةً، وهي بالبكسل ٧١٨ و١٠٤٧ تقريباً. */
  let wide = 0;
  try {
    root.querySelectorAll("table").forEach(function (tb) {
      wide = Math.max(wide, tb.scrollWidth || 0, tb.offsetWidth || 0);
    });
  } catch (e) {}
  const land = wide > 718;
  const fitW = land ? 1047 : 718;
  const fit = wide > fitW ? Math.round(fitW / wide * 100) / 100 : 1;
  /* ولا يُصغَّر إلى ما لا يُقرأ: دون ذلك يُقصّ الجدولُ ويُنبَّه صاحبُه
     ليُقلّل الأعمدةَ من «الأعمدة» — خيرٌ من ورقةٍ لا يُقرأ سطرُها. */
  const zoom = Math.max(0.4, fit);
  if (fit < 0.4) {
    try { showToast("الجدولُ أعرضُ من الورقة — قلّل الأعمدة من «الأعمدة» ليظهر كاملاً", "warn"); } catch (e) {}
  }
  const st = document.createElement("style");
  st.id = "pdfPage";
  st.textContent = "@page{size:A4 " + (land ? "landscape" : "portrait") +
    ";margin:10mm 8mm}" +
    (zoom < 1 ? "@media print{#pageContent{zoom:" + zoom + "}}" : "");
  document.head.appendChild(st);

  const head = document.createElement("div");
  head.id = "pdfHead";
  head.className = "pdf-head";
  head.innerHTML =
    `<div class="pdfh-top"><strong>ذات القرآنية</strong>
       <span>نظام إدارة الحلقات القرآنية</span></div>
     <div class="pdfh-title">${esc(t)}</div>
     <div class="pdfh-meta">${fac ? esc(fac) + " · " : ""}تاريخ الإصدار: ${
       esc(typeof hijriOf === "function" ? (hijriOf(todayISO(), true) || todayISO()) : todayISO())}</div>`;
  root.insertBefore(head, root.firstChild);

  const done = function () {
    try { head.remove(); } catch (e) {}
    try { st.remove(); } catch (e) {}
    window.removeEventListener("afterprint", done);
  };
  window.addEventListener("afterprint", done);
  /* مهلةٌ قصيرةٌ ليُرسم العنصرُ قبل فتح نافذة الطباعة، ونزعٌ احتياطيٌّ
     بعدها لمتصفّحٍ لا يُطلق afterprint. */
  setTimeout(function () {
    try { window.print(); } catch (e) {}
    setTimeout(done, 1200);
  }, 40);
};

/* =========================================================
   COMPLEXES HELPERS (المجمعات)
   ========================================================= */
function currentComplex() {
  return DB.complexes.find(x => x.id == STATE.complexId) || null;
}
/* =========================================================================
   أسماءُ ارتباط الطالب من معرّفاته (٤٥٥)
   -------------------------------------------------------------------------
   جدولُ الطلاب كان يعرض المسجدَ والحلقةَ والمعلّمَ من الحقول النصّية
   (mosque · circle · teacher): فالطالبُ الذي يحمل mosqueId بلا اسمٍ نصّيّ
   يظهر «بلا مسجد» — ومنهم من أُكمل مسجدُه بالمعرّف — وبعد تغيير اسم المسجد
   أو الحلقة يبقى الاسمُ القديمُ معروضاً. والقاعدةُ في المشروع «الربطُ
   بالمعرّفات لا بالنصوص». يُقرأ الاسمُ من السجلّ المرتبط، وإلا فالنصُّ كما كان.
   للعرض وحده: لا يُكتب شيء.
   ========================================================================= */
function stuLinkName(st) {
  const s = st || {};
  const txt = v => (v && v !== "—" ? String(v) : "");
  const byId = (c, id) => (id == null || id === "") ? null
    : (Array.isArray(DB[c]) ? DB[c] : []).find(x => x && String(x.id) === String(id)) || null;
  const cRec = byId("circles", s.circleId);
  const mRec = byId("mosques", s.mosqueId) || (cRec ? byId("mosques", cRec.mosqueId) : null);
  const tRec = byId("teachers", s.teacherId) || (cRec ? byId("teachers", cRec.teacherId) : null);
  return {
    mosque:  (mRec && mRec.name) || txt(s.mosque),
    circle:  (cRec && cRec.name) || txt(s.circle),
    teacher: (tRec && tRec.name) || (cRec && txt(cRec.teacher)) || txt(s.teacher)
  };
}
function complexName(id) {
  const cx = DB.complexes.find(x => x.id == id);
  return cx ? cx.name : "—";
}

/* =========================================================================
   حلّ الاسم إلى معرّف — أساس الربط بالمفاتيح لا بالنصوص
   -------------------------------------------------------------------------
   قوائم النماذج (المسجد · الحلقة · المعلم) تُبنى من الأسماء وتُرجع أسماءً،
   فكانت السجلات تُربط بنصّ الاسم وحده. أي تعديل لاسم مسجد أو حلقة كان يقطع
   الرابط بصمت. الآن نحلّ الاسم إلى معرّف ونخزّن الاثنين معاً:
   المعرّف هو المرجع، والاسم يبقى للعرض وللتوافق مع السجلات القديمة.
   ========================================================================= */
function recByName(coll, name) {
  const list = Array.isArray(DB[coll]) ? DB[coll] : [];
  const n = String(name == null ? "" : name).trim();
  if (!n || n === "—") return null;
  return list.find(x => String(x.name || "").trim() === n) || null;
}
function idByName(coll, name) {
  const rec = recByName(coll, name);
  return rec ? String(rec.id) : "";
}

/* =========================================================================
   حلقةُ الطالب في قائمة الاختيار — حلقتُه هو لا أوّلُ القائمة
   -------------------------------------------------------------------------
   «عدمُ التطابق بين المعلّم والمدير»: قائمةُ الحلقات في بطاقة الطالب تُبنى
   من حلقات نطاق العرض (cur)، فإن لم تكن حلقةُ الطالب فيه — مجمّعٌ آخرُ
   مختارٌ في الأعلى مثلاً — لم تُعلَّم، فظهرت أوّلُ حلقةٍ في القائمة مختارةً
   («النور» والطالبُ في «الإخلاص»)، والبطاقةُ تقول «٠ حلقات». فإن حُفظت
   البطاقةُ نُقل الطالبُ إلى تلك الحلقة بلا قصد — وذلك نقلٌ تلقائيٌّ ممنوع.

   فحلقتُه تُضاف إلى القائمة إن غابت، وتُعلَّم بمعرّفها لا باسمها (فلا
   يلتبس اسمان متشابهان في مسجدين). ومن لا حلقةَ له يُعرض له «— بلا
   حلقة —» مختاراً، فلا يُسند إلى أوّل حلقةٍ بحفظ البطاقة.
   ========================================================================= */
function stuCircleOpts(st) {
  const list = (cur("circles") || []).slice();
  const own = st && st.circleId
    ? (Array.isArray(DB.circles) ? DB.circles : []).find(c => String(c.id) === String(st.circleId)) : null;
  if (own && !list.some(c => String(c.id) === String(own.id))) list.unshift(own);
  const isSel = c => own ? String(c.id) === String(own.id)
                         : !!(st && st.circle && st.circle !== "—" && c.name === st.circle);
  const any = list.some(isSel);
  return (any ? "" : `<option value="—" selected>— بلا حلقة —</option>`) +
    list.map(c => `<option${isSel(c) ? " selected" : ""}>${esc(c.name)}</option>`).join("");
}

/* سجلُّ الحلقة المختارة باسمها — حلقةُ الطالب نفسُه أوّلاً إن كان الاسمُ اسمَها */
function stuCircleRec(st, name) {
  const n = String(name == null ? "" : name).trim();
  if (!n || n === "—") return null;
  const own = st && st.circleId
    ? (Array.isArray(DB.circles) ? DB.circles : []).find(c => String(c.id) === String(st.circleId)) : null;
  if (own && String(own.name || "").trim() === n) return own;
  return (cur("circles") || []).find(c => String(c.name || "").trim() === n) || recByName("circles", n);
}

/* =========================================================
   ADMIN — 0. COMPLEXES
   ========================================================= */
/* =========================================================================
   عرض موحّد للمنشآت (مجمعات + مساجد) — نفس الكارت والتولبار وفورم التعديل
   بدون تكرار: adminComplexes و adminMosques يستخدمان نفس الدوال.
   ========================================================================= */
function facStats(item, coll) {
  /* المصدرُ واحدٌ مع صفحة المنشأة: كانت هذه الدالّة تعدّ من DB مباشرةً
     بقواعدها الخاصّة، والصفحةُ تعدّ من facStudents و facChildren و
     facilityTeachers — فيقول ظاهرُ البطاقة رقماً وباطنُها رقماً آخر.
     وكانت تعدّ المدراء مع المعلّمين بعد أن فُصلوا عنهم بحقل staffRole.
     تُقرأ الآن من الدوالّ نفسِها، فما على البطاقة هو ما في الداخل. */
  if (!item) return { students: 0, teachers: 0, circles: 0, mosques: 0 };
  var kind = coll === "mosques" ? "mosque" : "complex";
  var alive = function (r) { return r && r.status !== "متوقف"; };
  /* «في هذه البطاقات عايز يظهر لي كم مسجد تابع للمجمّع»: عددُ مساجده من
     facChildren — وهي المصدرُ الذي تعدّ منه صفحةُ المجمّع نفسُها، فلا
     يختلف ظاهرُ البطاقة عن باطنها. والمسجدُ لا مساجدَ له فيبقى صفراً. */
  return {
    students: facStudents(item, coll).filter(alive).length,
    teachers: facilityTeachers(kind, item.id).filter(alive).length,
    circles:  facCircleCount(item, coll),
    mosques:  coll === "mosques" ? 0
      : (typeof facChildren === "function"
          ? facChildren(item, coll).filter(alive).length : 0)
  };
}

/* حلقاتُ المنشأة عدداً. لا تُؤخذ من facChildren لأنها تُرجع مساجدَ المجمّع
   لا حلقاتِه — والبطاقةُ تقول «حلقة»، فيصير عددُ المساجد حلقاتٍ. */
function facCircleCount(item, coll) {
  if (!item) return 0;
  var all = Array.isArray(DB.circles) ? DB.circles : [];
  if (coll === "mosques") {
    return all.filter(function (c) { return String(c.mosqueId) === String(item.id); }).length;
  }
  var mIds = (Array.isArray(DB.mosques) ? DB.mosques : [])
    .filter(function (m) { return String(m.complexId) === String(item.id); })
    .map(function (m) { return String(m.id); });
  return all.filter(function (c) {
    return String(c.complexId) === String(item.id) || mIds.indexOf(String(c.mosqueId)) > -1;
  }).length;
}

/* صفوف بطاقة المنشأة — المسجد يعرض مشرفه ورقمه وتبعيته، والمجمع مديره */
function facRows(item, coll) {
  if (coll !== "mosques") {
    return `<div class="fac-row"><span class="fac-lbl">المدير</span>` +
           `<span class="fac-val">${esc(item.manager || "—")}</span></div>`;
  }

  const sup = mosqueSupervisor(item);
  const phone = String(sup.phone || "—");
  const cxName = item.complexId ? complexName(item.complexId) : "";

  return `
    <div class="fac-row"><span class="fac-lbl">المشرف</span>
      <span class="fac-val">${esc(sup.name)}</span></div>
    <div class="fac-row"><span class="fac-lbl">رقم المشرف</span>
      <span class="fac-val" dir="ltr">${phone === "—" ? "—"
        : `<a href="tel:${esc(phone)}" style="color:inherit;text-decoration:none">${esc(phone)}</a>`}</span></div>
    <div class="fac-row"><span class="fac-lbl">التبعية</span>
      ${cxName
        ? `<span class="fac-badge on">${esc(cxName)}</span>`
        : `<span class="fac-badge indep">مسجد مستقل</span>`}</div>`;
}

function facCard(item, coll) {
  const single = coll === "mosques" ? "mosque" : "complex";
  /* كان المجمع يذهب إلى switch-complex التي تبدّل المجمع النشط وتعرض
     إشعاراً فقط، فيبدو الزر معطّلاً لأن الصفحة لا تتغيّر. ولوحة التفاصيل
     panelComplex كانت مبنية أصلاً وموصولة بـ panel-complex لكن لا شيء
     يستدعيها. الآن يفتح الزر التفاصيل في المنشأتين على نحو متسق. */
  const enterAction = "fac-open";
  const st = facStats(item, coll);
  const active = item.status === "نشط";
  /* شعار المنشأة؛ وإن لم يوجد فرسم مسجد مفصّل مطابق للنموذج */
  const logo = item.photo ? `<img src="${esc(item.photo)}" alt="">` : '<svg class="fac-mosque" viewBox="0 0 64 64" width="72" height="72" fill="none"><path d="M32 4c2.6 2.6 4 5 4 7.4 0 2.6-1.8 4.2-4 6-2.2-1.8-4-3.4-4-6C28 9 29.4 6.6 32 4z" fill="#118488"/><circle cx="32" cy="2.4" r="1.6" fill="#118488"/><path d="M32 18c7.6 0 13.4 5.4 13.4 12.4V34H18.6v-3.6C18.6 23.4 24.4 18 32 18z" fill="#118488"/><rect x="18.6" y="34" width="26.8" height="24" fill="#f2fafa" stroke="#0d5254" stroke-width="1.6"/><path d="M32 40c2.8 0 5 2.2 5 5v13H27V45c0-2.8 2.2-5 5-5z" fill="#118488"/><path d="M10 26c2 0 3.4 1.6 3.4 3.6V58H6.6V29.6C6.6 27.6 8 26 10 26z" fill="#118488"/><path d="M54 26c2 0 3.4 1.6 3.4 3.6V58h-6.8V29.6c0-2 1.4-3.6 3.4-3.6z" fill="#118488"/><circle cx="10" cy="23.4" r="2.2" fill="#118488"/><circle cx="54" cy="23.4" r="2.2" fill="#118488"/><rect x="22" y="38" width="4.6" height="7" rx="2.3" fill="#118488"/><rect x="37.4" y="38" width="4.6" height="7" rx="2.3" fill="#118488"/><rect x="4" y="58" width="56" height="3" fill="#0d5254"/></svg>';
  return `<div class="fac-card" data-id="${item.id}" data-name="${esc(item.name)}" data-active="${active ? 1 : 0}">
    <div class="fac-head">
      <button class="fac-check" onclick="window.facToggleSel(this)" aria-label="تحديد"><svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6L9 17l-5-5"/></svg></button>
      <div class="fac-logo">${logo}</div>
      <div class="fac-title">${esc(item.name)}<span class="fac-type">${single === "mosque" ? "مسجد" : "مجمع"}</span></div>
    </div>
    <div class="fac-stats${single === "complex" ? " fac-stats-4" : ""}">
      <div class="fac-stat"><b>${st.students}</b><span>طالب/ة</span></div>
      <div class="fac-stat"><b>${st.teachers}</b><span>معلم</span></div>
      <div class="fac-stat"><b>${st.circles}</b><span>حلقة</span></div>
      ${single === "complex"
        ? `<div class="fac-stat"><b>${st.mosques}</b><span>مسجد</span></div>` : ""}
    </div>
    ${facRows(item, coll)}
    <div class="fac-row"><span class="fac-lbl">الحالة</span><span class="fac-badge ${active ? "on" : "off"}">${active ? "فعال" : "متوقف"}</span></div>
    <div class="fac-actions">
      <button class="fac-btn" data-action="edit-${single}" data-id="${item.id}">تعديل</button>
      <button class="fac-btn" data-action="${enterAction}" data-id="${item.id}" data-coll="${coll}">دخول</button>
    </div>
  </div>`;
}

/* فرز التبعية — بنفس نمط زر «فعال» في شريط الأدوات */
function mqAffiliationFilter(CH) {
  const f = mqFilter();
  const all = cur("mosques");
  const nLinked = all.filter(m => m.complexId).length;
  const nIndep  = all.length - nLinked;

  const label = f.kind === "linked" ? "تابع لمجمع (" + nLinked + ")"
              : f.kind === "indep"  ? "مستقل (" + nIndep + ")"
              : f.kind === "one"    ? complexName(f.complexId)
              : "كل المساجد (" + all.length + ")";

  const cxWith = (cur("complexes"))
    .filter(c => all.some(m => String(m.complexId || "") === String(c.id)));

  return `<div class="fac-filter-wrap">
    <div class="fac-filter" onclick="window.mqFilterOpen()"><span>${esc(label)}</span>${CH}</div>
    <div class="tb-panel" id="mqFilterPanel" style="display:none">
      <div class="tb-opt" data-action="mq-filter" data-kind="all">كل المساجد <span class="tb-n">${all.length}</span></div>
      <div class="tb-opt" data-action="mq-filter" data-kind="linked">تابع لمجمع <span class="tb-n">${nLinked}</span></div>
      <div class="tb-opt" data-action="mq-filter" data-kind="indep">مستقل <span class="tb-n">${nIndep}</span></div>
      ${cxWith.length ? `<div class="tb-sep">حسب المجمع</div>` : ""}
      ${cxWith.map(c => `<div class="tb-opt" data-action="mq-filter" data-kind="one" data-id="${esc(String(c.id))}">${esc(c.name || "—")}
        <span class="tb-n">${all.filter(m => String(m.complexId) === String(c.id)).length}</span></div>`).join("")}
    </div>
  </div>`;
}

window.mqFilterOpen = function () {
  const pan = document.getElementById("mqFilterPanel");
  if (pan) pan.style.display = pan.style.display === "block" ? "none" : "block";
};

function facToolbar(coll, presetCount, opt) {
  opt = opt || {};
  /* =========================================================================
     أعدادُ الفرز من القائمة المعروضة نفسِها
     -------------------------------------------------------------------------
     «يظهر أنّ هناك حسابين موقوفين، أضغط عليه فلا يوجد أحد — ويوسف فقط،
     وكذلك في الكل».

     وهذا الشريطُ يخدم شاشتين: بطاقاتِ المنشآت وجداولَ الأشخاص. وكان يعدّ
     من DB.complexes دائماً إلّا في المساجد — فصفحةُ المدراء تقرأ أعدادَها
     من **المجمّعات**: «الكل (٣)» عددُ المجمّعات، و«متوقف (٢)» الفرقُ
     بينها وبين الفعّال. فيقول الشريطُ ما لا علاقة له بالجدول تحته.

     فصارت الأعدادُ من القائمة التي تُعرض فعلاً متى مُرِّرت (opt.list)،
     وبمقياس الحالة نفسِه الذي يُرسم به الصفّ. وبطاقاتُ المنشآت على حالها.
     ========================================================================= */
  /* ومن نطاق المستخدم لا من النظام كلِّه (٤٥٢): كانت DB.mosques، فيقرأ مديرُ
     المجمّع «متوقف مؤقتاً (٥) · الكل (٧)» — مساجدَ النظام — وبطاقاتُه اثنتان. */
  const list = opt.list ? opt.list
    : (coll === "mosques" ? cur("mosques") : cur("complexes"));
  /* كان الزر مثبّتاً على «إضافة مجمع» مهما كانت الصفحة، فصفحة المدراء
     — وهي تستعمل هذا الشريط — كانت تفتح نافذة المجمع بدل نافذة المدير. */
  const addAction = opt.addAction ||
    (coll === "mosques" ? "modal-mosque" : coll === "teachers" ? "modal-teacher" : "modal-complex");
  const addTitle = opt.addLabel ||
    (coll === "mosques" ? "إضافة مسجد" : coll === "teachers" ? "إضافة مدير" : "إضافة مجمع");
  const onTest = opt.list
    ? (x => x && x.active !== false && x.status !== "متوقف")
    : (x => x && x.status === "نشط");
  const activeCount = presetCount != null ? presetCount : list.filter(onTest).length;
  /* ========================================================================
     وزرُّ الفرز يُنادي الفارزَ الذي يفهم ما تحته
     ------------------------------------------------------------------------
     facFilter تُخفي بطاقاتِ #facGrid وحدَها. وصفحةُ المدراء جدولٌ صفوفُه
     في #ptBody، فكانت النقرةُ تُضيء الزرَّ ولا تُحرّك صفّاً — فيُقال
     «ضغطتُ فلا يوجد أحد». فلها فارزُها ptFilter، وللبطاقات فارزُها.
     ======================================================================== */
  const fx = opt.list ? "ptFilter" : "facFilter";
  /* الأيقونات مطابقة للنموذج المرجعي: دائرة محيطة بكل رمز */
  const A = '<svg viewBox="0 0 24 24" width="21" height="21" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"><circle cx="12" cy="12" r="9"/><path d="M12 8.2v7.6M8.2 12h7.6"/></svg>';
  const D = '<svg viewBox="0 0 24 24" width="20" height="20" fill="currentColor"><path d="M9.4 3h5.2c.5 0 .9.4.9.9V5h4.1c.5 0 .9.4.9.9s-.4.9-.9.9h-.9v12.4c0 1-.8 1.8-1.8 1.8H7.1c-1 0-1.8-.8-1.8-1.8V6.8h-.9c-.5 0-.9-.4-.9-.9S3.9 5 4.4 5h4.1V3.9c0-.5.4-.9.9-.9zm.9 2h3.4v-.2h-3.4V5zM9.6 9.1c-.4 0-.7.3-.7.7v7.4c0 .4.3.7.7.7s.7-.3.7-.7V9.8c0-.4-.3-.7-.7-.7zm4.8 0c-.4 0-.7.3-.7.7v7.4c0 .4.3.7.7.7s.7-.3.7-.7V9.8c0-.4-.3-.7-.7-.7z"/></svg>';
  const S = '<svg viewBox="0 0 24 24" width="21" height="21" fill="none" stroke="currentColor" stroke-width="1.7"><circle cx="12" cy="12" r="9"/><rect x="8.8" y="8.8" width="6.4" height="6.4" rx="1.2" fill="currentColor" stroke="none"/></svg>';
  const P = '<svg viewBox="0 0 24 24" width="21" height="21" fill="none" stroke="currentColor" stroke-width="1.7"><circle cx="12" cy="12" r="9"/><path d="M10.2 8.3l6 3.7-6 3.7z" fill="currentColor" stroke="none"/></svg>';
  const SR = '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="8"/><path d="M21 21l-4.3-4.3"/></svg>';
  const MQ = '<svg viewBox="0 0 24 24" width="21" height="21" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3l2.2 2.8M6 10c0-1.2 6-2.4 6-2.4s6 1.2 6 2.4M6 10v10M18 10v10M6 20h12M10 20v-3.6a2 2 0 014 0V20"/></svg>';
  const CH = '<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M6 9l6 6 6-6"/></svg>';
  return `<div class="fac-toolbar">
    <!-- الفرزُ أزرارٌ ظاهرةٌ بأعدادها، كما في جدول الأشخاص، فلا يختلف
         شكلُ الفرز بين شاشةٍ وأخرى. -->
    <div class="pt-tabs">
      <button type="button" class="pt-tab on" data-ptfilter="on"
        onclick="window.${fx}('on')">فعال <b>(${activeCount})</b></button>
      <button type="button" class="pt-tab" data-ptfilter="off"
        onclick="window.${fx}('off')">متوقف مؤقتاً <b>(${Math.max(0, (list || []).length - activeCount)})</b></button>
      <button type="button" class="pt-tab" data-ptfilter="all"
        onclick="window.${fx}('all')">الكل <b>(${(list || []).length})</b></button>
    </div>
    ${coll === "mosques" && !facCtxComplexId() ? mqAffiliationFilter(CH) : ""}
    ${opt.search === false ? "" : `<div class="fac-searchbox">${SR}<input placeholder="ابحث.." oninput="window.facSearch(this.value)"></div>`}
    <div class="fac-tools">
      <button class="fac-tbtn play" onclick="window.facBulk('play','${coll}')" title="تشغيل المحدد">${P}</button>
      <button class="fac-tbtn stop" onclick="window.facBulk('stop','${coll}')" title="إيقاف المحدد">${S}</button>
      <button class="fac-tbtn del" onclick="window.facBulk('delete','${coll}')" title="حذف المحدد">${D}</button>
      ${coll === "complexes" && !mayCreateComplex() ? "" : `<button class="fac-tbtn add" data-action="${addAction}" title="${esc(addTitle)}">${A}</button>`}
    </div>
  </div>`;
}


/* =========================================================================
   تفاصيل المنشأة — عرض كامل بلغة لوحة التحكم البصرية
   -------------------------------------------------------------------------
   كان زر «دخول» يفتح لوحة جانبية ضيّقة. هذا العرض يستعمل نفس مكوّنات لوحة
   التحكم (صفوف الحضور · بطاقات الأعداد · حلقة الإنجاز) لكن محصورة بمنشأة
   واحدة، ويُرسم داخل نفس الصفحة بلا ملف جديد ولا تغيير في التوجيه:
   STATE.facilityView يُقرأ في adminFacilities فيرسم التفاصيل بدل الشبكة.

   وأرقام الحضور هنا حقيقية — تُحسب من مجموعة attendance التي صارت تُكتب
   فعلاً من صفحة تحضير المعلم، بخلاف لوحة التحكم التي ما زالت تعرض أصفاراً.
   ========================================================================= */

/* أبناء المنشأة: مساجد المجمع، أو حلقات المسجد */
function facChildren(item, coll) {
  if (coll === "mosques") {
    return DB.circles.filter(c => c.mosqueId == item.id);
  }
  return DB.mosques.filter(m => m.complexId == item.id);
}

/* طلاب المنشأة — المجمع يشمل طلاب مساجده */
/* طلابُ المنشأة — تُحيل إلى facilityStudents.
   كانت تفحص mosqueId وحده، والطالبُ يُنسب إلى مسجده بحلقته غالباً ولا
   يُكتب في ملفّه — فيختفي من مسجده وهو فيه. */
function facStudents(item, coll) {
  if (!item) return [];
  return facilityStudents(coll === "mosques" ? "mosque" : "complex", item.id);
}

/* =========================================================================
   كادرُ المنشأة — معلّموها ومشرفوها
   -------------------------------------------------------------------------
   كانت الشاشةُ تقول «سبعة معلمين» ولا تقول من هم، والمشرفُ لا يُذكر فيها
   أصلاً وإنما في بطاقة المسجد وحدها. والمنشأةُ الواحدة يعمل فيها المعلّمون
   عدداً — والبنيةُ تحتمل ذلك منذ البدء: سجلُّ المعلّم يحمل complexId و
   mosqueId و circleId، وحسابُ المشرف يحمل scopeIds. فلا حقلَ جديدٌ ولا
   ترحيلَ بيانات، وإنّما عرضٌ لما هو مخزونٌ أصلاً.

   ويُقرأ الانتماءُ على ثلاث درجات كما في facilityStudents سواءً بسواء:
   المنشأةُ مباشرةً، أو مسجدٌ تابعٌ لها، أو حلقةٌ في أحدهما.
   ========================================================================= */

/* مفاتيحُ الحلقات: المعرّفُ في السجلات الجديدة والاسمُ في القديمة — يُقرآن
   معاً وإلّا سقط المعلّمُ القديمُ من حلقته وهو فيها. */
function facCircleKeys(list) {
  const ids = {}, names = {};
  (list || []).forEach(function (c) {
    if (!c) return;
    ids[String(c.id)] = 1;
    const n = String(c.name || "").trim();
    if (n && n !== "—") names[n] = 1;
  });
  return { ids: ids, names: names };
}

function facInCircles(rec, keys) {
  if (!rec) return false;
  if (rec.circleId && keys.ids[String(rec.circleId)]) return true;
  const n = String(rec.circle || "").trim();
  return !!(n && keys.names[n]);
}

/* =========================================================================
   تمييزُ المدير من المعلّم داخل سجلّ الكادر
   -------------------------------------------------------------------------
   مجموعةُ teachers سجلُّ الكادر كلِّه: المعلّمُ ومديرُ المنشأة فيها سواء،
   ولا حقلَ يفرّق بينهما — فيُعَدُّ المديرُ معلّماً في كلّ إحصاء.
   الحقلُ staffRole يفصلهما. والسجلاتُ القديمة بلا حقل تُعَدُّ معلّمين:
   هو الغالبُ في المجموعة، والمديرُ يُعلَّم يدوياً من نموذج التعديل —
   وهذا أسلمُ من تخمينٍ يقلب صفةَ من لم يُسأل عنه.
   ========================================================================= */
function isStaffManager(rec) {
  return !!rec && String(rec.staffRole || "") === "manager";
}

function staffRoleLabel(rec) {
  return isStaffManager(rec) ? "مدير" : "معلّم";
}

/* مدراءُ المنشأة من سجلّ الكادر — نظيرُ facilityTeachers */
function facilityManagers(kind, id) {
  return facilityStaff(kind, id).filter(isStaffManager);
}

function facilityTeachers(kind, id) {
  return facilityStaff(kind, id).filter(function (t) { return !isStaffManager(t); });
}

/* كلُّ الكادر: معلّمين ومدراء — تُبنى عليها الدالّتان أعلاه */
function facilityStaff(kind, id) {
  if (!id) return [];
  const all = (cur("teachers") || []).filter(function (x) {
    return x && x.status !== "متوقف";
  });

  if (kind === "mosque") {
    const keys = facCircleKeys((cur("circles") || []).filter(function (c) {
      return c && String(c.mosqueId || "") === String(id);
    }));
    return all.filter(function (t) {
      return String(t.mosqueId || "") === String(id) || facInCircles(t, keys);
    });
  }

  if (kind === "complex") {
    const mids = {};
    (cur("mosques") || []).forEach(function (m) {
      if (m && String(m.complexId || "") === String(id)) mids[String(m.id)] = 1;
    });
    const keys = facCircleKeys((cur("circles") || []).filter(function (c) {
      return c && (mids[String(c.mosqueId || "")] ||
                   String(c.complexId || "") === String(id));
    }));
    return all.filter(function (t) {
      return String(t.complexId || "") === String(id) ||
             mids[String(t.mosqueId || "")] ||
             facInCircles(t, keys);
    });
  }

  return [];
}

/* مشرفو المنشأة — أكثرُ من واحد، ومشرفو مساجدِ المجمّع منهم.
   النطاقُ يُقرأ بـ userScopeIds لا بالحقل المفرد: هي تعرف scopeIds المتعدّد
   وتشتقُّ النطاقَ من السجل المرتبط إن خلا الحسابُ منه. */
function facilitySupervisors(kind, id) {
  if (!id) return [];
  const keys = {};
  keys[facKey(kind, id)] = 1;
  if (kind === "complex") {
    (cur("mosques") || []).forEach(function (m) {
      if (m && String(m.complexId || "") === String(id)) keys[facKey("mosque", m.id)] = 1;
    });
  }
  return (Array.isArray(DB.users) ? DB.users : []).filter(function (u) {
    if (!u || !isMgrRole(u.role)) return false;
    return userScopeIds(u).some(function (k) { return !!keys[String(k)]; });
  });
}

/* اسمُ نطاقِ الحساب نصّاً: اسمُ المسجد أو المجمّع أو الاثنان معاً */
function facScopeLabel(u) {
  const out = userScopeIds(u).map(function (k) {
    const p = String(k).split(":");
    if (p[0] === "mosque") {
      const m = (cur("mosques") || []).find(function (x) { return String(x.id) === String(p[1]); });
      return m ? (m.name || "") : "";
    }
    if (p[0] === "complex") return complexName(p[1]);
    return "";
  }).filter(Boolean);
  return out.length ? out.join(" · ") : "—";
}

/* =========================================================================
   إجراءات المسجد — من داخله
   -------------------------------------------------------------------------
   كان الطالبُ يُضاف من صفحة الطلاب ثمّ يُختار مسجدُه من قائمة، والخطةُ
   تُبنى من بابٍ آخر. ومن فتح مسجداً ليعمل فيه لا يريد أن يغادره.

   الزرّان يفتحان النموذجين المبنيّين مع ملء المسجد مسبقاً — لا نموذجَ
   جديدٌ يُخترع ويفترق عن أصله.
   ========================================================================= */
window.facStuSearch = function (v) {
  STATE.facStuQ = String(v || "");
  mount();
};

/* =========================================================================
   تبويبا المنشأة — الطلاب والكادر
   -------------------------------------------------------------------------
   كان الجدولان يُعرضان معاً تحت بعضهما، فيطول التمرير في منشأةٍ فيها مئة
   طالبٍ حتى يُبلغ المعلّمون. وهما شأنان لا يُنظر فيهما معاً غالباً.

   التبويبُ حالةٌ في STATE لا في الـDOM: mount تعيد بناء الصفحة كاملةً،
   فما يُكتب في العنصر وحده يضيع عند أوّل إعادة رسم.
   ========================================================================= */
/* أقسامُ المنشأة بعد الدخول إليها. كانا تبويبين فوق الجدول، وصارا قائمةً
   جانبيةً تحلّ محلَّ قائمة النظام ما دام المستخدم داخل المنشأة — فالمنشأة
   عالمٌ قائمٌ بذاته لا شاشةٌ واحدة. المفاتيحُ ثابتةٌ تقرؤها shell.js. */
var FAC_SECTIONS = [
  { k: "dashboard", label: "لوحة التحكم", icon: "pie" },

  { g: "students", label: "الطلاب / ات", icon: "users", children: [
    { k: "students",  label: "الرئيسية" },
    { to: "reports.html?r=students",   label: "تقرير الطلاب / ات" },
    { to: "attendance.html",           label: "سجل الطالب / ة اليومي" },
    { to: "reports.html?r=recitation", label: "التسميع السابق" },
    { k: "stu-edit",  label: "تحديث معلومات الطالب" }
  ]},

  { k: "teachers", label: "المعلمين / ات", icon: "teacher" },

  { g: "managers", label: "المديرين / ات", icon: "person", children: [
    { k: "mgr-complex", label: "مدير مجمع" },
    { k: "mgr-mosque",  label: "مدير مسجد" }
  ]},

  { g: "circles", label: "الحلقات", icon: "grid", children: [
    { k: "circles",  label: "الرئيسية" },
    { to: "attendance.html",           label: "التقرير اليومي" },
    { to: "reports.html?r=circles",    label: "تقرير الحلقات" },
    { k: "circle-progress", label: "مؤشر إنجاز الحلقة" },
    { to: "reports.html?r=recitation", label: "سجل التسميع" }
  ]},

  { g: "compete", label: "الشاشة التنافسية", icon: "bars", children: [
    { to: "statistics.html?s=all",     label: "الإحصائيات الشاملة" },
    { to: "statistics.html?s=circles", label: "إحصائيات الحلقات" }
  ]},

  { g: "points", label: "النقاط والمتجر", icon: "gift", children: [
    { to: "soon.html?p=points",          label: "لوحة التحكم" },
    { to: "soon.html?p=pts-students",    label: "تقرير نقاط الطلاب / ات" },
    { to: "soon.html?p=pts-student",     label: "تقرير نقاط طالب / ة" },
    { to: "soon.html?p=pts-redeem",      label: "الاستبدال من المتجر" },
    { to: "soon.html?p=pts-settings",    label: "إعدادات النقاط" }
  ]},

  { g: "exams", label: "الاختبارات", icon: "exam", children: [
    { to: "soon.html?p=exams-home",     label: "لوحة التحكم" },
    { to: "soon.html?p=exams-record",   label: "رصد الاختبارات" },
    { to: "soon.html?p=exams-sheet",    label: "كشف اختبارات الطلاب / ات" },
    { to: "soon.html?p=exams-log",      label: "سجل اختبار طالب / ة" },
    { to: "soon.html?p=exams-rewards",  label: "كشوف المكافآت" },
    { to: "soon.html?p=exams-settings", label: "إعدادات الاختبارات" }
  ]},

  { g: "bulk", label: "إدارة العمليات الجماعية", icon: "swap", children: [
    { to: "soon.html?p=bulk-plans",     label: "تعديل خطط التسميع" },
    { to: "soon.html?p=move-circles",   label: "نقل وتعديل المستوى" },
    { to: "soon.html?p=move-students",  label: "نقل الطلاب" },
    { to: "soon.html?p=bulk-levels",    label: "تعديل المستويات" }
  ]},

  { to: "settings.html", label: "الإعدادات", icon: "settings" }
];

/* المفاتيحُ التي تُرسم داخل صفحة المنشأة — ما عداها ينتقل إلى شاشته */
var FAC_KEYS = ["dashboard", "students", "stu-edit", "teachers",
                "mgr-complex", "mgr-mosque", "circles", "circle-progress"];

function facDetailCurTab() {
  var v = String(STATE.facTab || "");
  if (FAC_KEYS.indexOf(v) > -1) return v;
  /* "staff" اسمٌ قديمٌ للقسم قبل تقسيمه إلى معلّمين ومشرفين */
  return v === "staff" ? "teachers" : "dashboard";
}

window.facDetailTab = function (k) {
  var v = String(k || "");
  if (FAC_KEYS.indexOf(v) < 0) v = "dashboard";
  if (facDetailCurTab() === v) return;
  STATE.facTab = v;
  /* بحثُ الطلاب لا يعني شيئاً خارج قسمهم — يُصفَّر لئلا يعود
     المستخدمُ إلى قائمةٍ مصفّاةٍ لا يذكر أنه صفّاها. */
  if (v !== "students") STATE.facStuQ = "";
  mount();
  /* القائمةُ الجانبية تُبرز القسم الحالي، فتُعاد بناؤها بعد كلّ تنقّل */
  if (typeof window.__adminBuildNav === "function") window.__adminBuildNav();
};

/* ملءُ حقلَي المنشأة في نموذجٍ مفتوح.
   الترتيبُ مقصود: يُضبط المجمّعُ أوّلاً ثمّ يُعاد بناءُ قائمة مساجده بـ
   facCxChange ثمّ يُختار المسجد — فضبطُ القيمة برمجياً لا يُطلق onchange،
   وقائمةُ المساجد تبقى بلا تصفية لو عُكس الترتيب. */
function facFillForm(idCx, idMq, cxId, mqId) {
  const cx = document.getElementById(idCx);
  const mq = document.getElementById(idMq);

  if (cx && cxId) {
    cx.value = String(cxId);
    if (typeof window.facCxChange === "function") {
      try { window.facCxChange(idCx, idMq); } catch (e) {}
    }
  }
  if (mq && mqId) mq.value = String(mqId);
}

/* إضافةُ طالبٍ من داخل المنشأة — من مسجدٍ أو من مجمّع.
   والمجمّعُ لا يُلزِم بمسجد: نموذجُ الطالب فيه خيار «بلا مسجد» أصلاً،
   و facilityStudents تعرف الطالبَ المنسوبَ إلى مجمّعٍ رأساً. */
window.facAddStudent = function (facId, kind) {
  if (typeof modalStudent !== "function") return;

  const isMq = kind !== "complex";
  const m = isMq ? (cur("mosques") || []).find(x => String(x.id) === String(facId)) : null;
  const c = isMq
    ? (m && m.complexId
        ? (cur("complexes") || []).find(x => String(x.id) === String(m.complexId)) : null)
    : (cur("complexes") || []).find(x => String(x.id) === String(facId));

  modalStudent();

  /* الحقولُ تُملأ بعد فتح النافذة: عناصرُها غير موجودةٍ قبلها */
  setTimeout(function () {
    try { facFillForm("s_cx", "s_mosque", c ? c.id : "", m ? m.id : ""); } catch (e) {}
  }, 0);
};

/* إضافةُ معلّمٍ من داخل المنشأة.
   والمعلّمُ يلزمه مسجدٌ بعينه: هو يقوم على حلقةٍ في مسجدٍ لا على مجمّعٍ فيه
   عشرة. فإن فُتحت من مجمّعٍ ضُبط المجمّعُ وتُرك المسجدُ لاختيار المستخدم،
   ولزم اختيارُه قبل الحفظ. */
window.facAddTeacher = function (facId, kind) {
  if (typeof modalTeacher !== "function") return;

  const isMq = kind !== "complex";
  const m = isMq ? (cur("mosques") || []).find(x => String(x.id) === String(facId)) : null;
  const c = isMq
    ? (m && m.complexId
        ? (cur("complexes") || []).find(x => String(x.id) === String(m.complexId)) : null)
    : (cur("complexes") || []).find(x => String(x.id) === String(facId));

  /* بلا مسجدٍ في المجمّع لا موضعَ للمعلّم — يُقال السببُ بدل فتح نموذجٍ
     لا يمكن حفظُه. */
  if (!isMq) {
    const has = (cur("mosques") || []).some(x => String(x.complexId || "") === String(facId));
    if (!has) {
      showToast("لا مساجد في هذا المجمّع بعد — أضف مسجداً أوّلاً", "warn");
      return;
    }
  }

  modalTeacher();
  /* modalTeacher تصفّر العلَم عند كل فتح، فيُرفع بعدها لا قبلها */
  window.__facTeacherNeedsMosque = !isMq;

  setTimeout(function () {
    try { facFillForm("t_cx", "t_mosque", c ? c.id : "", m ? m.id : ""); } catch (e) {}
  }, 0);
};

window.facBuildPlan = function (facId, kind) {
  const isMq = kind !== "complex";
  const m = (isMq ? cur("mosques") : cur("complexes"))
    .find(x => String(x.id) === String(facId));

  /* بلا طلابٍ لا خطّة: يُقال السببُ بدل فتح بانٍ فارغ */
  const kids = facilityStudents(isMq ? "mosque" : "complex", facId);

  if (!kids.length) {
    showToast("لا طلاب في " + ((m && m.name) || (isMq ? "المسجد" : "المجمّع")) +
      " — أضف طالباً أوّلاً", "warn");
    return;
  }
  if (!(cur("programs") || []).length) {
    showToast("لا برامج بعد — أنشئ برنامجاً من الإعدادات", "warn");
    return;
  }

  /* بانِي الخطط يفتح على طلاب هذا المسجد */
  /* بانِي الخطط تبويبٌ في صفحة الخطط: يُفتح بضبط التبويب لا بدالّةٍ خاصّة.
     والنطاقُ يُمرَّر فتُعرض طلابُه وحدهم في خطوة الاختيار. */
  STATE.planMosque  = isMq ? String(facId) : "";
  STATE.planComplex = isMq ? "" : String(facId);
  STATE.facilityView = null;

  /* النمطُ يُهيّأ على المنشأة: من فتح الباني من مسجدٍ يريده لمسجده */
  try {
    builderState.scope = isMq ? "mosque" : "complex";
    builderState.scopeId = String(facId);
    builderState.scopeKind = "";
    builderState.student = "";
  } catch (e) {}

  STATE.planId = null;
  try { builderState.step = 0; } catch (e) {}
  if (!STATE.tab) STATE.tab = {};
  STATE.tab.plans = "new";
  go("plans");
};

/* عرضُ منشأةٍ بعينها قد يُطلَب من صفحةٍ أخرى — بطاقةٌ في لوحة التحكم
   مثلاً. و STATE يبدأ من جديد مع كلّ صفحة، فيُمرَّر الطلبُ عبر الجلسة
   ويُقرأ مرّةً واحدة ثمّ يُمحى، فلا يعلق على الصفحة كلّما فُتحت. */
function takePendingFacility() {
  if (STATE.facilityView) return STATE.facilityView;
  try {
    var raw = sessionStorage.getItem("__facView");
    if (raw) {
      sessionStorage.removeItem("__facView");
      var v = JSON.parse(raw);
      if (v && v.id) { STATE.facilityView = v; return v; }
    }
  } catch (e) {}
  return null;
}

function facilityDetail(coll, id) {
  const list = coll === "mosques" ? DB.mosques : DB.complexes;
  const item = list.find(x => String(x.id) === String(id));
  const kind = coll === "mosques" ? "مسجد" : "مجمع";

  if (!item) {
    return `<div class="page">
      ${pageHead("تفاصيل المنشأة", "", `<button class="btn btn-ghost btn-sm" data-action="fac-back">رجوع</button>`)}
      <div class="card">${emptyState("المنشأة غير موجودة", "ربما حُذفت. ارجع للقائمة.")}</div></div>`;
  }

  const st       = facStats(item, coll);
  const students = facStudents(item, coll);
  const children = facChildren(item, coll);

  /* الكادرُ: معلّمو المنشأة ومشرفوها. يُقرآن من مصدرٍ واحد فتتّفق البطاقةُ
     والجدول، ولا يقول العدُّ رقماً يخالف ما تحته من أسماء. */
  const staffKind = coll === "mosques" ? "mosque" : "complex";
  const teachers  = facilityTeachers(staffKind, item.id);
  /* مدراءُ المنشأة من سجلّ الكادر — غيرُ المشرفين الذين لهم حسابات دخول */
  const facMgrs   = facilityManagers(staffKind, item.id);
  const sups      = facilitySupervisors(staffKind, item.id);

  /* ---- الحضور اليوم من سجلات فعلية ---- */
  const ids = {}; students.forEach(s => { ids[String(s.id)] = 1; });
  const today = todayISO();
  const recs = (Array.isArray(DB.attendance) ? DB.attendance : [])
    .filter(r => String(r.date) === today && ids[String(r.studentId)]);
  const n = s => recs.filter(r => r.status === s).length;
  const present = n("حاضر"), late = n("متأخر"), excused = n("مستأذن"), absent = n("غائب");
  const total = students.length;
  const pct = v => total ? Math.round(v / total * 100) : 0;

  const attRows = [
    { cls: "att-present", ico: "check", label: "الحضور", num: present, pct: pct(present), head: true },
    { cls: "att-late",    ico: "eye",   label: "التأخير", num: late,    pct: pct(late) },
    { cls: "att-excused", ico: "eye",   label: "مستأذن",  num: excused, pct: pct(excused) },
    { cls: "att-absent",  ico: "x",     label: "غياب",    num: absent,  pct: pct(absent) }
  ].map(r => `<div class="att-row ${r.cls}${r.head ? " att-row-head" : ""}">
      <div class="ar-right"><span class="ar-ico">${ic(r.ico, r.head ? 22 : 20)}</span><span class="ar-label">${r.label}</span><span class="ar-count">(${r.num})</span></div>
      <span class="ar-pct">${r.pct}%</span>
    </div>`).join("");

  /* البطاقاتُ أزرارٌ تنقل إلى صفحتها: كانت div بـ cursor:default فيضغطها
     الناظرُ ولا يحدث شيء. وسياقُ المنشأة محفوظٌ في الجلسة فتبقى القائمةُ
     الجانبيةُ وفرزُ المساجد على المنشأة نفسِها بعد الانتقال. */
  const cards = [
    { tint: "t-teal",   icon: coll === "mosques" ? "grid" : "mosque",
      num: children.length, label: coll === "mosques" ? "الحلقات" : "المساجد",
      page: coll === "mosques" ? "circles" : "mosques" },
    { tint: "t-blue",   icon: "teacher", num: teachers.length, label: "المعلمين", page: "teachers" },
    { tint: "t-green",  icon: "grid",    num: st.circles,  label: "الحلقات", page: "circles" },
    { tint: "t-purple", icon: "users",   num: total,       label: "الطلاب",  page: "students" }
  ].map(f => `<button type="button" class="facility-card ${f.tint}"
      data-action="nav" data-page="${f.page}" title="فتح ${esc(f.label)}">
      <div class="fc-num">${f.num}</div>
      <div class="fc-body"><span class="fc-ico">${ic(f.icon, 22)}</span><span class="fc-label">${f.label}</span></div>
    </button>`).join("");

  /* نسبة تسجيل التحضير اليوم — مؤشر واقعي بدل رقم ثابت */
  const marked = recs.length;
  const achievement = total ? Math.round(marked / total * 100) : 0;
  const circ = 2 * Math.PI * 52;
  const donut = `<div class="donut-wrap">
    <svg class="donut" viewBox="0 0 130 130">
      <circle cx="65" cy="65" r="52" fill="none" stroke="var(--border-soft)" stroke-width="12"/>
      <circle cx="65" cy="65" r="52" fill="none" stroke="var(--brand-main)" stroke-width="12" stroke-linecap="round" stroke-dasharray="${circ.toFixed(1)}" stroke-dashoffset="${(circ * (1 - achievement / 100)).toFixed(1)}" transform="rotate(-90 65 65)"/>
      <text class="donut-num" x="65" y="72" text-anchor="middle">${achievement}%</text>
    </svg>
    <div class="donut-label">تحضير اليوم</div>
  </div>`;

  /* البياناتُ الأساسية: كانت أربعةَ سطورٍ في عمودٍ واحد، وتُخفي المنطقةَ
     عن المسجد لأن مكانَها أُعطي للمجمّع التابع له. وهي الآن شبكةٌ تعرض
     كلَّ حقلٍ موجودٍ في المستند، ويُحذف الحقلُ الفارغ فلا يمتلئ الجدولُ
     بشُرَطٍ لا تفيد. */
  const infoPairs = [
    ["النوع", kind],
    coll === "mosques" ? ["المجمع التابع له", item.complexId ? complexName(item.complexId) : "مستقل"] : null,
    coll === "complexes" ? ["تصنيف المنشأة", item.facClass] : null,
    coll === "complexes" ? ["نوع الحلقات", item.facType] : null,
    ["المنطقة", item.region],
    /* المديرُ من حسابه لا من حقلٍ نصّيّ: حقلُ manager يُكتب باليد عند
       إنشاء المسجد ولا يتغيّر بعده، فيبقى اسمُ من كُتب أوّلاً حتى بعد
       تعيين مديرٍ حقيقيّ. mosqueSupervisor تقرأ الحسابَ المرتبطَ فعلاً
       بالمسجد — وهي المصدرُ نفسُه الذي تعرضه البطاقة، فلا يختلفان. */
    ["المدير", coll === "mosques" ? mosqueSupervisor(item).name : item.manager],
    ["رقم التواصل", item.phone],
    ["الحالة", item.status || "نشط"]
  ].filter(r => r && r[1] !== undefined && r[1] !== null && String(r[1]).trim() !== "");

  const info = `<div class="fac-info-grid">${infoPairs.map(r =>
    `<div class="kv"><span>${esc(r[0])}</span><strong${r[0] === "رقم التواصل" ? ' dir="ltr"' : ""}>${esc(String(r[1]))}</strong></div>`
  ).join("")}</div>`;

  /* مساجدُ المجمّع بطاقاتٌ لا سطوراً: هي منشآتٌ تُدخَل ويُنظر في أرقامها،
     فتُعرض ببطاقة facCard نفسِها المستعملة في صفحة المساجد — بأرقامها
     وزرَّي التعديل والدخول. أما حلقاتُ المسجد فتبقى سطوراً: ليست منشأةً
     تُدخَل ولا بطاقةَ لها في النظام. */
  const childRows = !children.length
    ? `<div class="muted" style="padding:14px;text-align:center">${coll === "mosques" ? "لا توجد حلقات في هذا المسجد بعد." : "لا توجد مساجد في هذا المجمع بعد."}</div>`
    : coll === "complexes"
      ? `<div class="fac-grid">${children.map(m => facCard(m, "mosques")).join("")}</div>`
      : children.map(c => `<div class="list-row">
        <div class="mini-avatar">${ic("grid", 15)}</div>
        <div style="flex:1"><strong style="font-size:13.5px">${esc(c.name || "—")}</strong>
          <div class="muted" style="font-size:12px">${esc(c.region || c.mosque || c.teacher || "—")}</div></div>
        ${statusBadge(c.status || "نشط")}
      </div>`).join("");

  /* =======================================================================
     طلاب المنشأة — جدولٌ ببياناتهم
     -----------------------------------------------------------------------
     كانت قائمةً بالاسم والحلقة، مقطوعةً عند الثاني عشر: «و٣٤ طالباً آخر»
     — لا يُعرفون ولا يُبحث عنهم ولا تُعرف خططهم.
     ======================================================================= */
  const stuQ = STATE.facStuQ || "";
  const shown = stuQ
    ? students.filter(x => String(x.name || "").indexOf(stuQ) > -1)
    : students;

  const studentRows = students.length
    ? `<div class="pt-wrap"><div class="pt-scroll"><table class="ptable">
        <thead><tr>
          <th>الطالب</th><th>الحلقة</th><th>المعلّم</th>
          <th>المستوى</th><th>وليّ الأمر</th><th>اليوم</th><th></th>
        </tr></thead>
        <tbody>${shown.map(x => {
          const r  = recs.find(v => String(v.studentId) === String(x.id));
          const pl = (cur("plans") || []).find(v => String(v.studentId) === String(x.id));
          const c  = (cur("circles") || []).find(v => String(v.id) === String(x.circleId));

          return `<tr>
            <td><div style="display:flex;align-items:center;gap:9px">
              <div class="mini-avatar">${initials(x.name)}</div>
              <div><strong style="font-size:13px">${esc(x.name || "—")}</strong>
                ${x.idNo ? `<div class="muted" style="font-size:11px" dir="ltr">${esc(x.idNo)}</div>` : ""}
              </div></div></td>
            <td class="muted">${esc(x.circle || (c && c.name) || "—")}</td>
            <td class="muted">${esc((c && c.teacher) || x.teacher || "—")}</td>
            <td>${pl ? esc(pl.level || "—")
              : x.attOnly ? `<span class="chip t-blue">تحضير فقط</span>`
              : `<span class="chip t-amber">بلا خطة</span>`}</td>
            <td class="muted" dir="ltr" style="font-size:12px">${esc(x.parentPhone || x.phone || "—")}</td>
            <td>${r ? `<span class="chip ${ATT_TINT[r.status] || ""}">${esc(r.status)}</span>`
                    : `<span class="muted" style="font-size:12px">لم يُسجَّل</span>`}</td>
            <td class="pt-actions">
              <button class="row-btn" data-action="edit-student" data-id="${esc(x.id)}"
                title="تعديل">${ic("edit", 14)}</button>
            </td>
          </tr>`;
        }).join("") || `<tr><td colspan="7" class="muted"
          style="text-align:center;padding:22px">لا نتائج للبحث</td></tr>`}</tbody>
      </table></div></div>`
    : `<div class="muted" style="padding:14px;text-align:center">لا يوجد طلاب مسجّلون.</div>`;

  /* =======================================================================
     صفوفُ الكادر — المعلّمون والمشرفون في جدولٍ واحدٍ يفرّق بينهم عمودُ الدور
     -----------------------------------------------------------------------
     المشرفُ أوّلاً لأنه المسؤولُ عن المنشأة، ثمّ المعلّمون. وزرُّ التعديل
     يذهب بكلٍّ إلى موضعه: المعلّمُ إلى نموذجه، والمشرفُ إلى صفحة الحسابات
     لأنه مستخدمٌ لا سجلَّ منفصلاً له — ولا يظهر الزرُّ لمن لا يملك الصلاحية.
     ======================================================================= */
  const canUsers = typeof canDo !== "function" || canDo("users");
  const mqNameOf = mid => {
    const m = (cur("mosques") || []).find(x => String(x.id) === String(mid));
    return m ? (m.name || "") : "";
  };

  const staffLine = o => `<tr>
      <td><div style="display:flex;align-items:center;gap:9px">
        <div class="mini-avatar">${initials(o.name)}</div>
        <strong style="font-size:13px">${esc(o.name || "—")}</strong></div></td>
      <td><span class="chip ${o.tint}">${esc(o.role)}</span></td>
      <td class="muted">${esc(o.fac || "—")}</td>
      <td class="muted">${esc(o.circle || "—")}</td>
      <td class="muted" dir="ltr" style="font-size:12px">${esc(o.phone || "—")}</td>
      <td>${statusBadge(o.status)}</td>
      <td class="pt-actions">${o.btn || ""}</td>
    </tr>`;

  const supLines =
    sups.map(u => staffLine({
      name: u.name, role: "مشرف", tint: "t-amber",
      fac: facScopeLabel(u), circle: "—",
      phone: u.phone || u.whatsapp || "",
      status: u.active === false ? "متوقف" : "نشط",
      btn: canUsers
        ? `<button class="row-btn" onclick="window.go('admin/users')"
            title="إدارة الحسابات">${ic("edit", 14)}</button>` : ""
    })).join("");

  const teacherLines =
    teachers.map(t => staffLine({
      name: t.name, role: "معلم", tint: "t-blue",
      fac: t.mosque || mqNameOf(t.mosqueId) ||
           (t.complexId ? complexName(t.complexId) : ""),
      circle: t.circle, phone: t.phone,
      status: t.status || "نشط",
      btn: `<button class="row-btn" data-action="edit-teacher" data-id="${esc(String(t.id))}"
            title="تعديل">${ic("edit", 14)}</button>`
    })).join("");

  const tab = facDetailCurTab();

  /* أرقامُ القائمة الجانبية — تُقرأ في shell.js فتظهر جنب كلّ قسم */
  STATE.facCounts = {
    students: total, teachers: teachers.length,
    supervisors: sups.length, circles: children.length
  };

  const actions = `
    <button class="btn btn-ghost btn-sm" data-action="fac-back">${ic("arrowLeft", 15)} رجوع للقائمة</button>
    <button class="btn btn-ghost btn-sm" data-action="edit-${coll === "mosques" ? "mosque" : "complex"}" data-id="${item.id}">${ic("edit", 15)} تعديل البيانات</button>
    ${coll === "complexes" && String(item.id) !== String(STATE.complexId)
      ? `<button class="btn btn-primary btn-sm" data-action="switch-complex" data-id="${item.id}">${ic("swap", 15)} التبديل إلى هذا المجمع</button>` : ""}`;

  /* ---- أقسامُ المنشأة: يُعرض قسمٌ واحد بحسب اختيار القائمة الجانبية ---- */
  /* الأرقامُ أوّلاً ثمّ البياناتُ الأساسية: الاسمُ والحالةُ في الترويسة
     أعلى الصفحة فيُعرف الموضعُ منها، وما يُنظر فيه كلَّ يومٍ هو الأرقام. */
  const secDashboard = `
    <div class="dash-top">
      <div class="card att-summary-wrap"><div class="att-rows">${attRows}</div></div>
      <div class="card facility-wrap"><div class="facility-grid">${cards}</div></div>
      <div class="card gauge-wrap">${donut}</div>
    </div>
    <div class="card" style="margin-top:16px">
      <div class="section-head"><h3>البيانات الأساسية</h3>${statusBadge(item.status || "نشط")}</div>
      ${info}
    </div>`;

  const secCircles = `
    <div ${coll === "complexes" ? 'style="margin-top:0"' : 'class="card"'}>
      <div class="section-head"><h3>${coll === "mosques" ? "حلقات المسجد" : "مساجد المجمع"}</h3>
        <span class="badge b-gold">${toArabicDigits(children.length)}</span></div>
      ${childRows}
    </div>`;

  /* المعلّمون والمشرفون: الجدولُ واحدٌ والصفوفُ تُبنى مرّةً أعلاه، ويُعرض
     من كلٍّ صفُّه في قسمه — فلا يُكتب الجدولُ مرّتين ولا يختلف شكلُه. */
  const staffTable = body => body
    ? `<div class="pt-wrap"><div class="pt-scroll"><table class="ptable">
        <thead><tr><th>الاسم</th><th>الدور</th><th>المنشأة</th><th>الحلقة</th>
          <th>الجوال</th><th>الحالة</th><th></th></tr></thead>
        <tbody>${body}</tbody></table></div></div>`
    : `<div class="muted" style="padding:14px;text-align:center">لا سجلات في هذا القسم بعد.</div>`;

  const secTeachers = `
    <div class="section-head"><h3>المعلمين / ات</h3>
      <span class="badge b-gold">${toArabicDigits(teachers.length)}</span></div>
    <div class="fac-toolbar" style="gap:8px;flex-wrap:wrap">
      <button class="btn btn-primary btn-sm"
        onclick="window.facAddTeacher('${jsAttr(item.id)}','${staffKind}')">
        ${ic("plus", 14)} إضافة معلم</button>
    </div>
    <div class="list-card">${staffTable(teacherLines)}</div>`;

  const secSups = `
    <div class="section-head"><h3>المشرفين / ات</h3>
      <span class="badge b-gold">${toArabicDigits(sups.length)}</span></div>
    <div class="list-card">${staffTable(supLines)}</div>`;

  const secStudents = `
    <div class="section-head"><h3>الطلاب وحالة تحضير اليوم</h3>
      <span class="badge b-gold">${marked} / ${total}</span></div>
    <div class="fac-toolbar" style="gap:8px;flex-wrap:wrap">
      <input class="mig-dest" placeholder="ابحث عن طالب" style="max-width:190px"
        value="${esc(stuQ)}" oninput="window.facStuSearch(this.value)">
      <button class="btn btn-primary btn-sm"
        onclick="window.facAddStudent('${jsAttr(item.id)}','${staffKind}')">
        ${ic("plus", 14)} إضافة طالب</button>
      <button class="btn btn-soft btn-sm"
        onclick="window.facBuildPlan('${jsAttr(item.id)}','${coll === "mosques" ? "mosque" : "complex"}')">
        ${ic("plan", 14)} بناء خطة ${coll === "mosques" ? "للمسجد" : "للمجمّع"}</button>
      <span class="muted" style="font-size:12px;margin-inline-start:auto">
        ${toArabicDigits(shown.length)} من ${toArabicDigits(total)}</span>
    </div>
    <div class="list-card">${studentRows}</div>`;

  /* الإحصائيات: أرقامُ المنشأة مجموعةً في مكانٍ واحد — من facStats نفسِها
     التي تغذّي البطاقات، فلا رقمَ يخالف رقماً. */
  const secStats = `
    <div class="section-head"><h3>الإحصائيات الشاملة</h3></div>
    ${sGrid([
      sCard(coll === "mosques" ? "الحلقات" : "المساجد", toArabicDigits(children.length), SC.teal,  coll === "mosques" ? "grid" : "mosque"),
      sCard("الطلاب",   toArabicDigits(total),           SC.purple, "users"),
      sCard("المعلمون", toArabicDigits(teachers.length), SC.blue,   "teacher"),
      sCard("المشرفون", toArabicDigits(sups.length),     SC.gold,   "person")
    ], 4)}
    <div style="height:16px"></div>
    <div class="grid g-2" style="align-items:start">
      <div class="card">
        <div class="section-head"><h3>حضور اليوم</h3><span class="badge b-gray">${marked} / ${total}</span></div>
        <div class="att-rows">${attRows}</div>
      </div>
      <div class="card"><div class="section-head"><h3>نسبة تسجيل التحضير</h3></div>${donut}</div>
    </div>`;

  /* المديرون: قائمةُ المشرفين نفسُها مفروزةً بالدور، فلا مصدرَ ثانياً
     للأسماء ولا رقمٌ يخالف رقماً. */
  const isRole = (u, r) => String(u.role || "") === r;
  const supsComplex = sups.filter(u => isRole(u, "complexManager"));
  const supsMosque  = sups.filter(u => isRole(u, "mosqueManager") || isRole(u, "supervisor"));
  const lineOf = arr => arr.map(u => staffLine({
    name: u.name, role: u.role === "complexManager" ? "مدير مجمع" : "مدير مسجد",
    tint: u.role === "complexManager" ? "t-teal" : "t-amber",
    fac: facScopeLabel(u), circle: "—",
    phone: u.phone || u.whatsapp || "",
    status: u.active === false ? "متوقف" : "نشط",
    btn: canUsers ? `<button class="row-btn" onclick="window.go('admin/users')"
          title="إدارة الحسابات">${ic("edit", 14)}</button>` : ""
  })).join("");

  const secMgr = (title, arr) => `
    <div class="section-head"><h3>${title}</h3>
      <span class="badge b-gold">${toArabicDigits(arr.length)}</span></div>
    <div class="list-card">${staffTable(lineOf(arr))}</div>
    ${facMgrs.length ? `
      <div class="section-head" style="margin-top:18px"><h3>مدراء مسجّلون في الكادر</h3>
        <span class="badge b-gray">${toArabicDigits(facMgrs.length)}</span></div>
      <div class="list-card">${staffTable(facMgrs.map(t => staffLine({
        name: t.name, role: "مدير", tint: "t-teal",
        fac: t.mosque || facScopeLabel(t), circle: "—",
        phone: t.phone || "", status: t.status || "نشط",
        btn: `<button class="row-btn" data-action="edit-teacher" data-id="${jsAttr(t.id)}"
              title="تعديل">${ic("edit", 14)}</button>`
      })).join(""))}</div>` : ""}`;

  /* تحديث معلومات الطالب: الجدولُ نفسُه وزرُّ التعديل فيه يفتح النموذج —
     شاشةٌ ثانيةٌ للتحرير تعني نموذجين لبياناتٍ واحدة. */
  const secStuEdit = `
    <div class="section-head"><h3>تحديث معلومات الطالب / ة</h3>
      <span class="badge b-gray">${toArabicDigits(total)}</span></div>
    <div class="fac-toolbar" style="gap:8px;flex-wrap:wrap">
      <input class="mig-dest" placeholder="ابحث عن طالب" style="max-width:190px"
        value="${esc(stuQ)}" oninput="window.facStuSearch(this.value)">
      <span class="muted" style="font-size:12px;margin-inline-start:auto">
        اضغط زرّ التعديل في الصف لفتح بيانات الطالب</span>
    </div>
    <div class="list-card">${studentRows}</div>`;

  /* مؤشرُ إنجاز الحلقة: نسبةُ من سُجِّل له تحضيرٌ اليوم في كلّ حلقة —
     من سجلّات الحضور نفسِها التي تغذّي البطاقات أعلاه. */
  const circleList = coll === "mosques" ? children : (cur("circles") || []);
  const progRows = circleList.length
    ? circleList.map(c => {
        const inC = students.filter(x => String(x.circleId) === String(c.id));
        const done = inC.filter(x => recs.find(r => String(r.studentId) === String(x.id))).length;
        const p = inC.length ? Math.round(done / inC.length * 100) : 0;
        return `<div class="list-row">
          <div style="flex:1"><strong style="font-size:13.5px">${esc(c.name || "—")}</strong>
            <div class="muted" style="font-size:12px">${toArabicDigits(done)} من ${toArabicDigits(inC.length)} طالباً</div></div>
          <div style="flex:1;max-width:220px"><div class="progress green"><span style="width:${p}%"></span></div></div>
          <strong style="font-size:13px;min-width:44px;text-align:left">${p}%</strong>
        </div>`;
      }).join("")
    : `<div class="muted" style="padding:14px;text-align:center">لا توجد حلقات بعد.</div>`;

  const secProgress = `
    <div class="section-head"><h3>مؤشر إنجاز الحلقة</h3>
      <span class="badge b-gray">تحضير اليوم</span></div>
    <div class="list-card">${progRows}</div>`;

  const SECTION = {
    dashboard: secDashboard, students: secStudents, teachers: secTeachers,
    supervisors: secSups, circles: secCircles, stats: secStats,
    "stu-edit": secStuEdit, "mgr-complex": secMgr("مدراء المجمعات", supsComplex),
    "mgr-mosque": secMgr("مدراء المساجد", supsMosque),
    "circle-progress": secProgress
  };

  let secLabel = "";
  FAC_SECTIONS.forEach(sc => {
    if (sc.k === tab) secLabel = sc.label;
    (sc.children || []).forEach(ch => { if (ch.k === tab) secLabel = ch.label; });
  });
  if (!secLabel) secLabel = "لوحة التحكم";

  return `<div class="page">
    ${pageHead(item.name || "—",
      kind + (item.status === "نشط" ? " · فعال" : " · متوقف") + " · " + secLabel, actions)}
    ${SECTION[tab] || secDashboard}
  </div>`;
}



/* ---------------------------------------------------------------
   المنشآت التعليمية — المجمعات وحدها.
   كانت الصفحة تخلط المجمعات والمساجد في شبكة واحدة، فيصعب تمييز
   البنية الهرمية. المساجد صار لها صفحتها المستقلة بفرز التبعية.
   --------------------------------------------------------------- */
/* =========================================================================
   المنشآت — المجمّعات والمساجد في شاشةٍ واحدة
   -------------------------------------------------------------------------
   كانا زرَّين في القائمة وشاشتين متجاورتين، حتى إنّ نصّ إحداهما يحيل إلى
   الأخرى: «أضف إليه المساجد من صفحة المساجد». وهما شيءٌ واحد: منشآتٌ
   تعليمية، بعضُها يحوي بعضاً.

   تبويبان في شاشةٍ واحدة، وأدواتُ كلٍّ كما كانت — لا يُفقد شيء.
   ========================================================================= */
/* التبويبُ يُعرف من المسار الجاري لا من حالةٍ محفوظة: الحالةُ قد تخالف
   ما هو معروضٌ فعلاً فتتصادم الشاشتان. */
function facCurTab() {
  const p = String((STATE && STATE.page) || location.pathname || "");
  return /mosques/.test(p) ? "mosques" : "complexes";
}

window.facTab = function (k) {
  /* go معرَّفةٌ عالمياً في هذا الملفّ — تُنادى مباشرةً */
  go(k === "mosques" ? "admin/mosques" : "admin/complexes");
};

function facTabs() {
  const curTab = facCurTab();
  /* داخل مجمّع: العددُ عددُ مساجده هو. كان يعرض عدد مساجد النظام كلِّه
     بينما الشبكةُ تحته تعرض مساجدَه وحدها، فيتناقض الرقمُ مع ما تحته. */
  const _cx = facCtxComplexId();
  const cxN = _cx ? 1 : cur("complexes").length;
  const mqN = _cx
    ? cur("mosques").filter(m => String(m.complexId || "") === _cx).length
    : cur("mosques").length;

  /* داخل مجمّع: تبويبُ «المجمّعات» يعرض المجمّعَ الذي نحن فيه وحده،
     فزرٌّ لا ينقل إلى شيء. يبقى تبويبُ المساجد وحده. */
  /* ومديرُ المجمّع كذلك: مجمّعُه واحد، فتبويبُ «المجمّعات» لا ينقل إلى شيء —
     «شيل زرّ المجمّعات من زرّ المساجد». وصفحةُ المجمّعات نفسُها باقية. */
  const _isCx = typeof isComplexMgr === "function" &&
                isComplexMgr(((STATE && STATE.user) || {}).role || "");
  const tabs = (_cx || _isCx)
    ? [["mosques", "المساجد", mqN, "mosque"]]
    : [["complexes", "المجمّعات", cxN, "building"],
       ["mosques",   "المساجد",   mqN, "mosque"]];

  return `<div class="fac-tabs">
    ${tabs.map(([k, h, n, i]) =>
      `<button type="button" class="fac-tab${curTab === k ? " on" : ""}"
        onclick="window.facTab('${k}')">
        ${ic(i, 17)}<span>${esc(h)}</span>
        <b>${n}</b>
      </button>`).join("")}
  </div>`;
}

function adminFacilities() {
  /* عرض التفاصيل داخل الصفحة نفسها — لا ملف HTML جديد ولا مسار جديد */
  var _fv = takePendingFacility();
  if (_fv) return facilityDetail(_fv.coll, _fv.id);

  const cx = cur("complexes");

  if (!cx.length) {
    return `<div class="page">${pageHead("المنشآت التعليمية", "المجمعات التعليمية", (mayCreateComplex() ? addBtn("إضافة مجمع", "modal-complex") : ""))}
      ${facTabs()}
      <div class="card">${emptyState("لا توجد مجمعات بعد",
        "ابدأ بإضافة مجمع، ثمّ أضف إليه المساجد من تبويب المساجد أعلاه.")}</div></div>`;
  }

  const activeCount = cx.filter(x => x.status === "نشط").length;
  const mqN = (cur("mosques")).length;

  return `<div class="page">
    ${pageHead("المنشآت التعليمية",
      "المجمعات التعليمية — " + cx.length + " مجمع",
      mayCreateComplex() ? addBtn("إضافة مجمع", "modal-complex") : "")}
    ${facTabs()}
    ${facToolbar("complexes", activeCount)}
    <div class="fac-grid" id="facGrid" data-coll="complexes">
      ${cx.map(x => facCard(x, "complexes")).join("")}
    </div>
  </div>`;
}

function adminComplexes() { return adminFacilities(); }
/* =========================================================================
   المساجد — صفحة مستقلة تجمع مساجد النظام
   -------------------------------------------------------------------------
   الملف mosques.html كان موجوداً بلا أي رابط يفتحه في القائمة الجانبية،
   وكان يعرض شبكة بطاقات لا تُظهر المشرف ولا رقمه ولا تبعية المسجد.
   ========================================================================= */

/* المشرف المسؤول: يُفضَّل حساب مشرف مرتبط بالمسجد، وإلا حقل «المدير» فيه */
function mosqueSupervisor(m) {
  /* المشرفون قد يكونون عدداً — البطاقةُ تعرض أوّلَهم وتُلمِح إلى البقية،
     وتُقرأ من facilitySupervisors فيتّفق ما في البطاقة وما في جدول الكادر. */
  const sups = facilitySupervisors("mosque", m.id);
  if (sups.length) {
    const s = sups[0];
    return {
      name: (s.name || "—") + (sups.length > 1 ? " (+" + (sups.length - 1) + ")" : ""),
      phone: s.phone || m.phone || "—", linked: true, count: sups.length
    };
  }
  /* السجلاتُ القديمة: مديرٌ إداريٌّ مربوطٌ بالمسجد بحقلٍ مفرد */
  const u = (Array.isArray(DB.users) ? DB.users : []).find(x =>
    x && (isMgrRole(x.role) || x.role === "admin") &&
    String(x.mosqueId || "") === String(m.id));
  if (u) return { name: u.name || "—", phone: u.phone || m.phone || "—", linked: true, count: 1 };
  return { name: m.manager || "—", phone: m.phone || "—", linked: false, count: 0 };
}

/* ---- مساعدات مشتركة: تحديد / بحث / إجراءات جماعية ---- */
window.facToggleSel = function (btn) {
  var card = btn.closest(".fac-card");
  if (card) { card.classList.toggle("sel"); btn.classList.toggle("on"); }
};
window.facSearch = function (q) {
  q = (q || "").trim();
  var cards = document.querySelectorAll("#facGrid .fac-card");
  for (var i = 0; i < cards.length; i++) {
    var n = cards[i].getAttribute("data-name") || "";
    cards[i].style.display = (!q || n.indexOf(q) !== -1) ? "" : "none";
  }
};
window.facBulk = function (kind, coll) {
  coll = coll || "complexes";
  var nodes = document.querySelectorAll("#facGrid .fac-card.sel");
  var ids = []; for (var i = 0; i < nodes.length; i++) ids.push(nodes[i].getAttribute("data-id"));
  if (!ids.length) { showToast("حدد عنصراً واحداً على الأقل", "warn"); return; }
  /* المجمّعاتُ: الحذفُ للمدير، والتشغيلُ والإيقافُ لمن يعدّل المجمّع (٤٥٤) */
  if (coll === "complexes") {
    const okAll = kind === "delete" ? mayCreateComplex()
      : ids.every(id => mayEditComplex((DB.complexes || []).find(x => x.id == id)));
    if (!okAll) { showToast("هذا الإجراءُ على المجمّعات لمدير النظام ومدير المجمّع", "warn"); return; }
  }
  if (kind === "delete") {
    window.__facDelIds = ids; window.__facDelColl = coll;
    openModal("حذف المحدد", "تأكيد الحذف",
      noteCard("سيتم حذف <strong>" + ids.length + "</strong> عنصر نهائياً. لا يمكن التراجع."),
      '<button class="btn btn-danger" onclick="window.facBulkDelete()">نعم، احذف</button><button class="btn btn-ghost" data-action="close-modal">إلغاء</button>');
    return;
  }
  var status = kind === "play" ? "نشط" : "متوقف";
  var list = coll === "mosques" ? DB.mosques : DB.complexes;
  ids.forEach(function (id) {
    var it = list.find(function (x) { return x.id == id; });
    if (it) { it.status = status; persistSet(coll, it); }
  });
  mount();
  showToast(kind === "play" ? "تم تشغيل المحدد" : "تم إيقاف المحدد");
};
window.facBulkDelete = function () {
  var ids = window.__facDelIds || [];
  var coll = window.__facDelColl || "complexes";
  if (coll === "complexes" && !mayCreateComplex()) { showToast("حذفُ المجمّعات لمدير النظام", "warn"); return; }
  ids.forEach(function (id) {
    if (coll === "mosques") DB.mosques = DB.mosques.filter(function (x) { return x.id != id; });
    else DB.complexes = DB.complexes.filter(function (x) { return x.id != id; });
    persistDelete(coll, id);
  });
  window.__facDelIds = [];
  if (typeof closeModal === "function") closeModal();
  if (typeof renderComplexSelect === "function") renderComplexSelect();
  if (typeof renderNav === "function") renderNav();
  mount();
  showToast("تم حذف المحدد");
};
/* =========================================================
   ADMIN — 1. DASHBOARD
   ========================================================= */
/* =========================================================================
   مخطّط الأداء — منحنى الشهور
   -------------------------------------------------------------------------
   اللوحة كانت أرقاماً وأشرطة بلا خطٍّ زمنيّ: يُعرف حالُ اليوم ولا يُعرف
   أيصعد الأداء أم ينحدر. والمنحنى يقول ذلك بنظرة.

   يُرسم SVG بلا مكتبة: المنحنى ناعمٌ بمنحنيات بيزيه، وتحته تدرّجٌ يخفت.
   ========================================================================= */
function perfSeries(months) {
  const n = Math.max(3, Number(months) || 7);
  const out = [];
  const now = new Date();

  for (let k = n - 1; k >= 0; k--) {
    const d = new Date(now.getFullYear(), now.getMonth() - k, 1);
    const from = d.toISOString().slice(0, 10);
    const to = new Date(d.getFullYear(), d.getMonth() + 1, 0).toISOString().slice(0, 10);

    const att = (cur("attendance") || []).filter(a =>
      a && !a.staffId && String(a.date) >= from && String(a.date) <= to);
    const here = att.filter(a => a.status === "حاضر" || a.status === "متأخر").length;

    out.push({
      label: ["يناير","فبراير","مارس","أبريل","مايو","يونيو",
              "يوليو","أغسطس","سبتمبر","أكتوبر","نوفمبر","ديسمبر"][d.getMonth()],
      pct: att.length ? Math.round(here * 100 / att.length) : 0
    });
  }
  return out;
}

function perfChart(months) {
  const data = perfSeries(months);
  /* العرض قريبٌ من عرض البطاقة الفعليّ: كان ٦٤٠ يُمدّ إلى ١١٠٠ بالتمطيط،
     فتتباعد النقاط ويرقّ الخطّ ويتشوّه النصّ. */
  const W = 1080, H = 260, PL = 56, PR = 24, PT = 22, PB = 40;
  const iw = W - PL - PR, ih = H - PT - PB;

  /* المدى يبدأ من الصفر: بدؤه من أدنى قيمةٍ يضخّم فروقاً يسيرة */
  const max = 100;
  const px = i => PL + (data.length < 2 ? iw / 2 : (iw * i) / (data.length - 1));
  const py = v => PT + ih - (ih * v) / max;

  const pts = data.map((d, i) => [px(i), py(d.pct)]);

  /* منحنى ناعم بنقطتَي تحكّمٍ أفقيّتين. وشدّةُ الانحناء تخفّ كلّما اشتدّ
     الفرق بين النقطتين: القفزةُ من صفرٍ إلى مئةٍ كانت تُرسم صعوداً شبهَ
     عموديّ يشوّه القراءة. */
  let line = "M " + pts[0][0] + " " + pts[0][1];
  for (let i = 1; i < pts.length; i++) {
    const [x0, y0] = pts[i - 1], [x1, y1] = pts[i];
    const dy = Math.abs(y1 - y0) / ih;                 /* 0 إلى 1 */
    const k = 0.5 - Math.min(0.28, dy * 0.30);         /* الفرق الكبير يُسطَّح */
    const c0 = x0 + (x1 - x0) * k;
    const c1 = x1 - (x1 - x0) * k;
    line += " C " + c0 + " " + y0 + ", " + c1 + " " + y1 + ", " + x1 + " " + y1;
  }
  const area = line + " L " + pts[pts.length - 1][0] + " " + (PT + ih) +
               " L " + pts[0][0] + " " + (PT + ih) + " Z";

  const grid = [0, 25, 50, 75, 100].map(v =>
    `<line x1="${PL}" y1="${py(v)}" x2="${W - PR}" y2="${py(v)}"
       stroke="var(--border-soft)" stroke-width="1" stroke-dasharray="4 7"/>
     <text x="${PL - 14}" y="${py(v) + 4}" text-anchor="end"
       font-size="12.5" fill="var(--text-faint)">${toArabicDigits(v)}٪</text>`).join("");

  const labels = data.map((d, i) =>
    `<text x="${px(i)}" y="${H - 12}" text-anchor="middle"
       font-size="13" fill="var(--text-faint)">${esc(d.label)}</text>`).join("");

  const dots = pts.map(([x, y], i) =>
    `<circle cx="${x}" cy="${y}" r="5" fill="var(--surface)"
       stroke="var(--brand-main)" stroke-width="3"/>
     <title>${esc(data[i].label)}: ${toArabicDigits(data[i].pct)}٪</title>`).join("");

  return `<div class="perf-card">
    <div class="section-head"><h3>ملخّص الأداء</h3>
      <span class="badge b-teal">${toArabicDigits(data[data.length - 1].pct)}٪ هذا الشهر</span></div>
    <svg viewBox="0 0 ${W} ${H}" class="perf-svg" preserveAspectRatio="xMidYMid meet">
      <defs>
        <linearGradient id="perfFill" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%"   stop-color="var(--brand-main)" stop-opacity=".26"/>
          <stop offset="100%" stop-color="var(--brand-main)" stop-opacity="0"/>
        </linearGradient>
      </defs>
      ${grid}
      <path d="${area}" fill="url(#perfFill)"/>
      <path d="${line}" fill="none" stroke="var(--brand-main)"
            stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>
      ${dots}
      ${labels}
    </svg>
  </div>`;
}

/* =========================================================================
   لوحة المشرف
   -------------------------------------------------------------------------
   لوحةُ المدير تعرض إحصاءَ المجمّع كلِّه وأرقامَه المالية، والمشرفُ لا
   يعنيه ذلك: يفتح النظام ليعرف ما يحتاج تدخّلَه اليوم في مساجده.

   قسمان: ما ينتظره، ثمّ حالُ حلقاته. ولا مالَ فيهما.
   ========================================================================= */
/* =========================================================================
   لوحةُ مدير المجمّع — بالشكل المطلوب
   -------------------------------------------------------------------------
   «أريد نفس هذا الشكل في مدير المجمّعات فقط، لكن زرّ المنشآت خلِّ اسمه
   المساجد، وتأكّد أنّ الأزرار كلَّها تعمل.»

   ثلاثُ بطاقاتٍ في الصدر: مؤشّرُ الإنجاز · بطاقاتُ المساجد والمعلّمين
   والحلقات والطلاب · الحضورُ والتأخّرُ والاستئذانُ والغياب. وتحتها أوجهُ
   الحفظ وأوجهُ المراجعة لكلّ مسجدٍ من مساجد المجمّع.

   كلُّ رقمٍ من سجلّاتٍ فعليّةٍ في نطاقه (cur)، وكلُّ بطاقةٍ زرٌّ ينقل إلى
   شاشتها. ولا كتابةَ هنا ألبتّة. ومديرُ المسجد والمشرفُ ومديرُ النظام
   تبقى لوحاتُهم كما هي.
   ========================================================================= */
/* ولوحةُ مدير المسجد بالشكل نفسه (mode="mosque"): «أريد مثل هذه في مدير
   المسجد». ثلاثُ بطاقاتٍ بلا «المساجد»، وتحت المؤشّر «حلقات بدأت» و«حلقات
   لم تبدأ» اليوم، والأوجهُ لكلّ معلّمٍ من معلّمي مسجده لا لكلّ مسجد. */
function cxMgrDashboard(mode) {
  const MQ = mode === "mosque";
  const d = typeof attDate === "function" ? attDate() : todayISO();
  const mosques  = cur("mosques")  || [];
  const teachers = (cur("teachers") || []).filter(x => !(typeof isStaffManager === "function" && isStaffManager(x)));
  const circles  = cur("circles")  || [];
  const students = (cur("students") || []).filter(s => s && s.status !== "متوقف");
  const total = students.length;
  const n2 = x => toArabicDigits(x);

  /* ---------- الحضور في اليوم المختار ---------- */
  const map = typeof attMap === "function" ? attMap(d) : {};
  const cnt = st => students.filter(x => ((map[String(x.id)] || {}).status) === st).length;
  const present = cnt("حاضر"), late = cnt("متأخر"), excused = cnt("مستأذن"), absent = cnt("غائب");
  const pct = v => total ? Math.round(v / total * 100) : 0;
  /* كلُّ صفٍّ زرٌّ يفتح قائمةَ طلاب حالته (cxdAttOpen) */
  const attRows = [
    { cls: "att-present", ico: "check", label: "الحضور",   num: present, head: true, st: "حاضر" },
    { cls: "att-late",    ico: "eye",   label: "التأخر",   num: late,    st: "متأخر" },
    { cls: "att-excused", ico: "eye",   label: "الاستئذان", num: excused, st: "مستأذن" },
    { cls: "att-absent",  ico: "x",     label: "الغياب",   num: absent,  st: "غائب" }
  ].map(r => `<button type="button" class="att-row ${r.cls}${r.head ? " att-row-head" : ""}" data-st="${r.st}"
      onclick="window.cxdAttOpen('${r.st}')" title="طلاب ${r.label}">
      <div class="ar-right"><span class="ar-ico">${ic(r.ico, r.head ? 22 : 20)}</span>
        <span class="ar-label">${r.label}</span><span class="ar-count">(${n2(r.num)})</span></div>
      <span class="ar-pct">${n2(pct(r.num))}%</span></button>`).join("");

  /* ---------- البطاقاتُ الأربع — كلٌّ زرٌّ إلى شاشته ---------- */
  const cards = [
    MQ ? null :
    { tint: "t-green",  icon: "mosque",  num: mosques.length,  label: "المساجد",  go: "mosques" },
    { tint: "t-teal",   icon: "teacher", num: teachers.length, label: "المعلمين", go: "teachers" },
    { tint: "t-green",  icon: "grid",    num: circles.length,  label: "الحلقات",  go: "circles" },
    { tint: "t-purple", icon: "users",   num: total,           label: "الطلاب",   go: "students" }
  ].filter(Boolean).map(f => `<button type="button" class="facility-card ${f.tint}" data-go="${f.go}"
      onclick="window.go('${f.go}')" title="فتح ${esc(f.label)}">
      <div class="fc-num">${n2(f.num)}</div>
      <div class="fc-body"><span class="fc-ico">${ic(f.icon, 22)}</span><span class="fc-label">${f.label}</span></div>
    </button>`).join("");

  /* ---------- مؤشّرُ الإنجاز: متوسّطُ تقدّم خطط الطلاب ---------- */
  const prog = total ? Math.round(students.reduce((a, x) => a + (Number(x.progress) || 0), 0) / total) : 0;
  const circ = 2 * Math.PI * 52;
  const donut = `<button type="button" class="donut-wrap cxd-donut" data-go="students"
      onclick="window.go('students')" title="تقدّم الطلاب">
    <svg class="donut" viewBox="0 0 130 130">
      <circle cx="65" cy="65" r="52" fill="none" stroke="var(--border-soft)" stroke-width="12"/>
      <circle cx="65" cy="65" r="52" fill="none" stroke="var(--brand-main)" stroke-width="12" stroke-linecap="round" stroke-dasharray="${circ.toFixed(1)}" stroke-dashoffset="${(circ * (1 - prog / 100)).toFixed(1)}" transform="rotate(-90 65 65)"/>
      <text class="donut-num" x="65" y="72" text-anchor="middle">${n2(prog)}%</text>
    </svg>
    <div class="donut-label">مؤشر الإنجاز</div>
  </button>`;

  /* ---------- مدير المسجد: حلقاتٌ بدأت اليوم وحلقاتٌ لم تبدأ ----------
     «بدأت» = حلقةٌ فيها تحضيرُ طالبٍ في اليوم المختار؛ والباقي «لم تبدأ». */
  let mqGauge = "";
  if (MQ) {
    const live = circles.filter(c => c && c.status !== "متوقف");
    const att = (cur("attendance") || []).filter(a => a && !a.staffId && String(a.date) === d);
    const started = live.filter(c => att.some(a => String(a.circleId) === String(c.id))).length;
    const gRow = (ico, label, n, cls) => `<button type="button" class="mqd-crow ${cls}" data-go="attendance"
        onclick="window.go('attendance')" title="${label}">
        <span class="mqd-cico">${ic(ico, 16)}</span><span class="mqd-clabel">${label}</span>
        <span class="mqd-cnum">${n2(n)}</span><span class="mqd-arrow">←</span></button>`;
    mqGauge = `<div class="mqd-crows">
        ${gRow("check", "حلقات بدأت", started, "mqd-started")}
        ${gRow("clock", "حلقات لم تبدأ", live.length - started, "mqd-pending")}
      </div>`;
  }

  /* ---------- أوجهُ الحفظ والمراجعة لكلّ مسجد (الفترة النشطة) ----------
     وعند مدير المسجد: لكلّ معلّم — معلّمُ الطالب معلّمُ حلقته. */
  const byMq = {};
  if (MQ) {
    teachers.forEach(t => { byMq[String(t.id)] = { name: "الشيخ / " + (t.name || "—"), hd: 0, ht: 0, rd: 0, rt: 0 }; });
  } else {
    mosques.forEach(m => { byMq[String(m.id)] = { name: m.name || "—", hd: 0, ht: 0, rd: 0, rt: 0 }; });
  }
  const cById = {};
  circles.forEach(c => { if (c) cById[String(c.id)] = c; });
  const keyOf = s => MQ
    ? String(((cById[String(s.circleId || "")] || {}).teacherId) || s.teacherId || "")
    : String(s.mosqueId || "");
  const tot = { hd: 0, ht: 0, rd: 0, rt: 0 };
  students.forEach(s => {
    let t = null;
    try { t = typeof planTally === "function" ? planTally({ studentId: s.id }) : null; } catch (e) { t = null; }
    if (!t) return;
    const row = byMq[keyOf(s)];
    [["hd", "hifzDone"], ["ht", "hifzTotal"], ["rd", "revDone"], ["rt", "revTotal"]].forEach(([k, f]) => {
      const v = Number(t[f]) || 0;
      tot[k] += v;
      if (row) row[k] += v;
    });
  });
  const r1 = x => Math.round(x * 10) / 10;
  const bar = (done, all) => {
    const w = all ? Math.min(100, Math.round(done / all * 100)) : 0;
    return `<div class="cxd-bar"><i style="width:${w}%"></i></div>`;
  };
  const facesCol = (title, dk, tk) => `<div class="cxd-col">
      <div class="cxd-head"><strong>${title}</strong>${bar(tot[dk], tot[tk])}
        <span class="cxd-sum">${n2(r1(tot[dk]))} / ${n2(r1(tot[tk]))}</span></div>
      ${Object.keys(byMq).length ? Object.keys(byMq)
        .sort((a, b) => MQ ? (byMq[b][dk] - byMq[a][dk]) : 0).map(id => {
        const m = byMq[id];
        const g = MQ ? "teachers" : "mosques";
        return `<button type="button" class="cxd-row" data-go="${g}"
            onclick="window.go('${g}')" title="${esc(m.name)}">
          <span class="cxd-name">${esc(m.name)}</span>${bar(m[dk], m[tk])}
          <span class="cxd-num">${n2(r1(m[dk]))}</span></button>`;
      }).join("") : `<div class="muted" style="padding:12px;text-align:center">${MQ ? "لا معلّمين في مسجدك بعد" : "لا مساجد في مجمّعك بعد"}</div>`}
    </div>`;

  return `<div class="page cxd${MQ ? " mqd" : ""}">
    ${pageHead("لوحة التحكم", "")}
    <div class="dash-top">
      <div class="card gauge-wrap">${donut}${mqGauge}</div>
      <div class="card facility-wrap"><div class="facility-grid">${cards}</div></div>
      <div class="card att-summary-wrap cxd-att"><div class="att-rows">${attRows}</div></div>
    </div>
    <div class="card cxd-faces">
      ${facesCol("أوجه الحفظ", "hd", "ht")}
      ${facesCol("أوجه المراجعة", "rd", "rt")}
    </div>
  </div>`;
}

/* =========================================================================
   قائمةُ طلاب الحالة من بطاقة الحضور — ورسائلُ التنبيه
   -------------------------------------------------------------------------
   «لمّا أضغط على أيّ زرٍّ من أزرار الحضور يجيبلي الطلاب، وكمان يكون في
   رسائل تنبيه للغايبين — بنفس الشكل».

   نافذةٌ واحدة: بحثٌ · تحديدُ الكلّ · تصفيةٌ بالحلقة · «حالة التحضير»
   تبدّل القائمة · زرُّ رسالةٍ يفتح «إرسال رسالة إلى الطلاب / ات» · وزرُّ
   تنبيهٍ يرسل قالبَ الغياب المحفوظ في الإعدادات إلى المحدَّدين.

   القراءةُ من cur() (نطاقُ صاحب اللوحة)، والكتابةُ رسائلُ في
   site_messages عبر persistSet وحدَها — لا يُمَسّ تحضيرٌ ولا ارتباط.
   ========================================================================= */
const CXD_ATT_ST = [["حاضر", "حضور"], ["متأخر", "تأخر"], ["مستأذن", "استئذان"], ["غائب", "غياب"]];
const CXD_ATT_TITLE = { "حاضر": "الحضور", "متأخر": "التأخر", "مستأذن": "الاستئذان", "غائب": "الغياب" };
let CXD_ATT = { st: "غائب", q: "", circle: "", flt: false, sel: {} };

function cxdAttStudents(st) {
  const d = typeof attDate === "function" ? attDate() : todayISO();
  const map = typeof attMap === "function" ? attMap(d) : {};
  const cById = {};
  (cur("circles") || []).forEach(c => { if (c) cById[String(c.id)] = c; });
  const tName = id => ((cur("teachers") || []).find(t => t && String(t.id) === String(id)) || {}).name || "";
  return (cur("students") || [])
    .filter(s => s && s.status !== "متوقف" && ((map[String(s.id)] || {}).status) === st)
    .map(s => {
      const c = cById[String(s.circleId || "")] || {};
      return { s, circleId: String(s.circleId || ""), circle: c.name || s.circle || "—",
               teacher: tName(c.teacherId || s.teacherId) || s.teacher || "" };
    });
}

/* اسمُ حلقة الطالب من سجلّها بالمعرّف، والاسمُ المنسوخ احتياطٌ */
function cxdCircleName(s) {
  const c = (cur("circles") || []).find(x => x && String(x.id) === String((s || {}).circleId || ""));
  return (c && c.name) || (s && s.circle) || "";
}

function cxdAttRowsHTML() {
  const all = cxdAttStudents(CXD_ATT.st);
  const q = String(CXD_ATT.q || "").trim();
  const list = all.filter(x => (!CXD_ATT.circle || x.circleId === CXD_ATT.circle) &&
    (!q || String(x.s.name || "").indexOf(q) > -1 || String(x.circle).indexOf(q) > -1));
  if (!list.length) return `<div class="cxa-empty">${ic("list", 46)}<strong>لا توجد بيانات</strong></div>`;
  return list.map(x => {
    const id = String(x.s.id);
    return `<label class="cxa-row">
      <input type="checkbox" class="cxa-ck" value="${esc(id)}" ${CXD_ATT.sel[id] ? "checked" : ""}
        onchange="window.cxdAttSel(this)">
      <span class="cxa-av">${esc(String(x.s.name || "؟").trim().charAt(0))}</span>
      <span class="cxa-who"><b>${esc(x.s.name || "—")}</b>
        <small>${esc(x.circle)}${x.teacher ? " · " + esc(x.teacher) : ""}</small></span>
    </label>`;
  }).join("");
}

function cxdAttPaint() {
  const box = document.getElementById("cxaList");
  if (box) box.innerHTML = cxdAttRowsHTML();
  const n = cxdAttStudents(CXD_ATT.st).length;
  const h = document.querySelector("#modalRoot .modal-head h3");
  if (h) h.textContent = CXD_ATT_TITLE[CXD_ATT.st] + " (" + toArabicDigits(n) + ")";
  const all = document.getElementById("cxaAll");
  const cks = [].slice.call(document.querySelectorAll("#cxaList .cxa-ck"));
  if (all) all.checked = cks.length > 0 && cks.every(c => c.checked);
  const cnt = document.getElementById("cxaSelN");
  const k = Object.keys(CXD_ATT.sel).length;
  if (cnt) cnt.textContent = k ? "محدَّد " + toArabicDigits(k) : "";
}

window.cxdAttOpen = function (st) {
  CXD_ATT = { st: CXD_ATT_TITLE[st] ? st : "غائب", q: "", circle: "", flt: false, sel: {} };
  const circles = (cur("circles") || []).filter(c => c && c.status !== "متوقف");
  const n = cxdAttStudents(CXD_ATT.st).length;
  openModal(CXD_ATT_TITLE[CXD_ATT.st] + " (" + toArabicDigits(n) + ")", "",
    `<div class="cxa">
      <div class="cxa-search">${ic("search", 18)}
        <input id="cxaQ" placeholder="ابحث هنا.." oninput="CXD_ATT.q=this.value; cxdAttPaint();"></div>
      <div class="cxa-bar">
        <label class="cxa-all"><input type="checkbox" id="cxaAll" onchange="window.cxdAttAll(this.checked)">
          <span>تحديد الكل</span></label>
        <span class="cxa-seln" id="cxaSelN"></span>
        <div class="cxa-tools">
          <button type="button" class="cxa-tool t-flt" title="تصفية بالحلقة" onclick="window.cxdAttFlt()">${ic("filter", 18)}</button>
          <button type="button" class="cxa-tool t-msg" title="إرسال رسالة" onclick="window.cxdMsgOpen()">${ic("send", 18)}</button>
          <button type="button" class="cxa-tool t-bell" title="إرسال تنبيه" onclick="window.cxdAttNotify()">${ic("bell", 18)}</button>
        </div>
      </div>
      <div class="cxa-flt" id="cxaFlt" hidden>
        <label>الحلقة</label>
        <select id="cxaCircle" onchange="CXD_ATT.circle=this.value; cxdAttPaint();">
          <option value="">كل الحلقات</option>
          ${circles.map(c => `<option value="${esc(String(c.id))}">${esc(c.name || "—")}</option>`).join("")}
        </select>
      </div>
      <div class="cxa-field"><label>حالة التحضير</label>
        <select id="cxaSt" onchange="window.cxdAttSt(this.value)">
          ${CXD_ATT_ST.map(([v, t]) => `<option value="${v}" ${v === CXD_ATT.st ? "selected" : ""}>${t}</option>`).join("")}
        </select></div>
      <div class="cxa-list" id="cxaList">${cxdAttRowsHTML()}</div>
    </div>`, "");
  const m = document.querySelector("#modalRoot .modal");
  if (m) m.classList.add("cxa-modal");
  cxdAttPaint();
};

window.cxdAttSt = function (v) { CXD_ATT.st = v; CXD_ATT.sel = {}; cxdAttPaint(); };
window.cxdAttFlt = function () {
  const f = document.getElementById("cxaFlt");
  if (f) f.hidden = !f.hidden;
  const b = document.querySelector(".cxa-tool.t-flt");
  if (b && f) b.classList.toggle("on", !f.hidden);
};
window.cxdAttSel = function (el) {
  if (el.checked) CXD_ATT.sel[el.value] = true; else delete CXD_ATT.sel[el.value];
  cxdAttPaint();
};
window.cxdAttAll = function (on) {
  document.querySelectorAll("#cxaList .cxa-ck").forEach(c => {
    c.checked = on;
    if (on) CXD_ATT.sel[c.value] = true; else delete CXD_ATT.sel[c.value];
  });
  cxdAttPaint();
};

/* المحدَّدون — وإن لم يُحدَّد أحدٌ فطلابُ القائمة الظاهرة كلُّهم */
function cxdAttPicked() {
  const ids = Object.keys(CXD_ATT.sel);
  const all = cxdAttStudents(CXD_ATT.st).map(x => x.s);
  return ids.length ? all.filter(s => ids.indexOf(String(s.id)) > -1) : [];
}

/* رسالةٌ داخل النظام إلى طالب — السجلُّ نفسُه الذي يكتبه msgSend */
function cxdMsgRec(s, title, text) {
  const u = (STATE && STATE.user) || {};
  return {
    id: "m" + Date.now() + Math.floor(Math.random() * 100000),
    title, text, ts: Date.now(),
    toId: String(s.id), toUid: String(s.uid || s.id || ""),
    toEmail: String(s.email || "").toLowerCase(), toName: s.name || "",
    fromId: String(u.uid || u.id || ""), fromEmail: String(u.email || "").toLowerCase(),
    fromName: u.name || "", read: false, type: "info"
  };
}

function cxdSendAll(list, title, textOf) {
  if (!Array.isArray(DB.site_messages)) DB.site_messages = [];
  const recs = list.map(s => cxdMsgRec(s, title, textOf(s)));
  recs.forEach(r => DB.site_messages.push(r));
  return Promise.all(recs.map(r => Promise.resolve(persistSet("site_messages", r)).catch(() => false)))
    .then(res => res.filter(Boolean).length);
}

/* تنبيهُ الغياب: قالبُ «غياب بدون عذر» من الإعدادات بأسماء الطلاب */
window.cxdAttNotify = function () {
  const list = cxdAttPicked();
  if (!list.length) { showToast("حدّد طالباً واحداً على الأقلّ", "warn"); return; }
  const d = typeof attDate === "function" ? attDate() : todayISO();
  const ev = typeof msgEvent === "function" ? msgEvent(CXD_ATT.st === "متأخر" ? "late" : "absent") : {};
  const body = ev.body || "ابنكم {الطالب} لم يحضر حلقة {الحلقة} اليوم {التاريخ}. نرجو المتابعة.";
  const textOf = s => msgFill(body, { "الطالب": s.name || "", "الحلقة": cxdCircleName(s), "التاريخ": d });
  openModal("إرسال تنبيه", CXD_ATT_TITLE[CXD_ATT.st] + " · " + toArabicDigits(list.length) + " طالب",
    `<div class="cxa-note">${ic("bell", 18)}<div>
       <b>سيصل كلَّ طالبٍ محدَّدٍ تنبيهٌ داخل النظام بهذا النصّ:</b>
       <p>${esc(textOf(list[0]))}</p>
       <small>النصُّ من «الرسائل التلقائية» في الإعدادات، ويُملأ باسم كلّ طالب.</small></div></div>`,
    `<button class="btn btn-primary" id="cxaNotifyGo">${ic("bell", 16)} إرسال التنبيه</button>
     <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
  const go = document.getElementById("cxaNotifyGo");
  if (go) go.onclick = function () {
    go.disabled = true; go.textContent = "جارٍ الإرسال…";
    cxdSendAll(list, "تنبيه " + CXD_ATT_TITLE[CXD_ATT.st], textOf).then(n => {
      closeModal();
      showToast(n === list.length ? "أُرسل التنبيه إلى " + toArabicDigits(n) + " طالب"
        : "وصل " + toArabicDigits(n) + " من " + toArabicDigits(list.length) + " — تحقّق من الاتصال",
        n === list.length ? "success" : "warn");
    });
  };
};

/* ---------- «إرسال رسالة إلى الطلاب / ات» ---------- */
let CXD_MSG = { circles: [], kids: [], via: "site" };

function cxdMsgPool() {
  const set = CXD_MSG.circles;
  return (cur("students") || []).filter(s => s && s.status !== "متوقف" &&
    (!set.length || set.indexOf(String(s.circleId || "")) > -1));
}

function cxdMsgPaint() {
  const cs = (cur("circles") || []);
  const nm = id => ((cs.find(c => String(c.id) === id) || {}).name) || "—";
  const chips = document.getElementById("cxmChips");
  if (chips) chips.innerHTML = CXD_MSG.circles.length
    ? CXD_MSG.circles.map(id => `<span class="cxm-chip">${esc(nm(id))}
        <button type="button" title="إزالة" onclick="window.cxdMsgUnC('${jsAttr(id)}')">${ic("x", 12)}</button></span>`).join("")
    : `<span class="muted">كل الحلقات</span>`;
  const cn = document.getElementById("cxmCN");
  if (cn) cn.textContent = "(" + toArabicDigits(CXD_MSG.circles.length) + ")";
  const pool = cxdMsgPool();
  const ok = new Set(pool.map(s => String(s.id)));
  CXD_MSG.kids = CXD_MSG.kids.filter(id => ok.has(id));
  const list = document.getElementById("cxmKids");
  if (list) list.innerHTML = pool.length ? pool.map(s => `<label class="cxm-kid">
      <input type="checkbox" value="${esc(String(s.id))}" ${CXD_MSG.kids.indexOf(String(s.id)) > -1 ? "checked" : ""}
        onchange="window.cxdMsgKid(this)"><span>${esc(s.name || "—")}</span>
      <small>${esc(cxdCircleName(s))}</small></label>`).join("")
    : `<div class="muted" style="padding:10px;text-align:center">لا طلاب</div>`;
  const kn = document.getElementById("cxmKN");
  if (kn) kn.textContent = "( " + toArabicDigits(pool.length) + " / " + toArabicDigits(CXD_MSG.kids.length) + " )";
  const sum = document.getElementById("cxmKSum");
  if (sum) sum.textContent = CXD_MSG.kids.length
    ? pool.filter(s => CXD_MSG.kids.indexOf(String(s.id)) > -1).map(s => s.name).slice(0, 3).join("، ")
      + (CXD_MSG.kids.length > 3 ? " و" + toArabicDigits(CXD_MSG.kids.length - 3) + " غيرهم" : "")
    : "إختر";
  document.querySelectorAll(".cxm-via").forEach(b => b.classList.toggle("on", b.dataset.via === CXD_MSG.via));
}

window.cxdMsgOpen = function () {
  const picked = cxdAttPicked();
  const base = picked.length ? picked : cxdAttStudents(CXD_ATT.st).map(x => x.s);
  const cids = [];
  base.forEach(s => { const c = String(s.circleId || ""); if (c && cids.indexOf(c) < 0) cids.push(c); });
  CXD_MSG = { circles: cids, kids: picked.map(s => String(s.id)), via: "site" };
  const circles = (cur("circles") || []).filter(c => c && c.status !== "متوقف");
  openModal("إرسال رسالة إلى الطلاب / ات", "",
    `<div class="cxm">
      <div class="cxm-f"><label>إختر الحلقات <span id="cxmCN"></span></label>
        <div class="cxm-box">
          <div class="cxm-chips" id="cxmChips"></div>
          <select class="cxm-add" onchange="window.cxdMsgAddC(this)">
            <option value="">+ إضافة حلقة</option>
            ${circles.map(c => `<option value="${esc(String(c.id))}">${esc(c.name || "—")}</option>`).join("")}
          </select></div></div>
      <div class="cxm-f cxm-row2"><label>الطلاب / ات <small id="cxmKN"></small></label>
        <details class="cxm-dd"><summary><span id="cxmKSum">إختر</span>${ic("arrowDown", 16)}</summary>
          <div class="cxm-ddtools">
            <button type="button" onclick="window.cxdMsgKids(true)">تحديد الكل</button>
            <button type="button" onclick="window.cxdMsgKids(false)">إلغاء التحديد</button></div>
          <div class="cxm-kids" id="cxmKids"></div></details></div>
      <div class="cxm-f"><label>الرسالة</label>
        <textarea id="cxmText" rows="6" placeholder="اكتب رسالتك هنا…"></textarea></div>
      <div class="cxm-hint">${ic("info", 16)} لإضافة اسم الطالب داخل الرسالة اكتب {الطالب} — ويُستبدل باسم كلّ طالب</div>
      <div class="cxm-f"><label>نوع الإرسال</label>
        <div class="cxm-vias">
          <button type="button" class="cxm-via" data-via="site" onclick="window.cxdMsgVia('site')">${ic("building", 16)} داخل النظام</button>
          <button type="button" class="cxm-via" data-via="wa" onclick="window.cxdMsgVia('wa')">${ic("phone", 16)} الواتس</button>
        </div></div>
    </div>`,
    `<button class="btn btn-primary cxm-send" id="cxmGo">${ic("send", 16)} إرسال</button>
     <button class="btn btn-ghost cxm-cancel" data-action="close-modal">إلغاء</button>`);
  const m = document.querySelector("#modalRoot .modal");
  if (m) m.classList.add("cxa-modal", "cxm-modal");
  const go = document.getElementById("cxmGo");
  if (go) go.onclick = window.cxdMsgSend;
  cxdMsgPaint();
};

window.cxdMsgAddC = function (sel) {
  const v = sel.value; sel.value = "";
  if (v && CXD_MSG.circles.indexOf(v) < 0) CXD_MSG.circles.push(v);
  cxdMsgPaint();
};
window.cxdMsgUnC = function (id) { CXD_MSG.circles = CXD_MSG.circles.filter(x => x !== id); cxdMsgPaint(); };
window.cxdMsgKid = function (el) {
  CXD_MSG.kids = CXD_MSG.kids.filter(x => x !== el.value);
  if (el.checked) CXD_MSG.kids.push(el.value);
  cxdMsgPaint();
};
window.cxdMsgKids = function (on) { CXD_MSG.kids = on ? cxdMsgPool().map(s => String(s.id)) : []; cxdMsgPaint(); };
window.cxdMsgVia = function (v) { CXD_MSG.via = v === "wa" ? "wa" : "site"; cxdMsgPaint(); };

/* رقمُ الواتس: جوالُ الطالب المسجَّل بمفتاحه (phone/phoneCC)، وإلا رقمُ
   وليّه (parent/parentCC). المفتاحُ المكتوبُ في الرقم أصدق، ثمّ المحفوظ
   بجانبه، ثمّ مفتاحُ النظام (waNumber). */
function cxdWaNum(s) {
  const pick = (v, cc) => {
    let raw = String(v == null ? "" : v).trim();
    if (!raw || raw === "—" || raw.replace(/\D+/g, "").length < 6) return "";
    if (raw.charAt(0) !== "+" && raw.indexOf("00") !== 0 && cc && /^\+?\d+$/.test(String(cc).trim())) {
      raw = "+" + String(cc).replace(/\D+/g, "") + raw.replace(/\D+/g, "").replace(/^0+/, "");
    }
    return typeof waNumber === "function" ? waNumber(raw) : raw.replace(/\D+/g, "");
  };
  return pick(s && s.phone, s && s.phoneCC) || pick(s && (s.parent || s.parentPhone), s && s.parentCC);
}

window.cxdMsgSend = function () {
  const text = String((document.getElementById("cxmText") || {}).value || "").trim();
  const list = cxdMsgPool().filter(s => CXD_MSG.kids.indexOf(String(s.id)) > -1);
  if (!list.length) { showToast("اختر طالباً واحداً على الأقلّ", "warn"); return; }
  if (!text) { showToast("نصّ الرسالة مطلوب", "warn"); return; }
  const textOf = s => msgFill(text, { "الطالب": s.name || "", "الحلقة": cxdCircleName(s) });

  if (CXD_MSG.via === "wa") {
    /* الرقمُ الذي سُجِّل به الطالب (جوالُه بمفتاح دولته)، ثمّ رقمُ وليّه
       إن لم يكن له رقم. ولطالبٍ واحدٍ تُفتح المحادثةُ مباشرةً؛ ولعدّةٍ
       قائمةٌ بزرٍّ لكلٍّ منهم — المتصفّحُ يمنع فتحَ عدّة نوافذَ دفعةً. */
    if (list.length === 1) {
      const n1 = cxdWaNum(list[0]);
      if (!n1) { showToast("لا رقمَ مسجَّلٌ للطالب " + (list[0].name || ""), "warn"); return; }
      window.open("https://wa.me/" + n1 + "?text=" + encodeURIComponent(textOf(list[0])), "_blank");
      closeModal();
      return;
    }
    const rows = list.map(s => {
      const n = cxdWaNum(s);
      return `<div class="cxw-row"><span><b>${esc(s.name || "—")}</b><small>${esc(cxdCircleName(s))}${n ? ` · <bdi dir="ltr">+${esc(n)}</bdi>` : ""}</small></span>
        ${n ? `<a class="btn btn-primary btn-sm" target="_blank" rel="noopener" href="https://wa.me/${esc(n)}?text=${esc(encodeURIComponent(textOf(s)))}">${ic("phone", 14)} فتح الواتس</a>`
            : `<span class="muted">لا رقم مسجَّل</span>`}</div>`;
    }).join("");
    openModal("الإرسال عبر الواتس", toArabicDigits(list.length) + " طالب — اضغط لكلّ طالب",
      `<div class="cxw">${rows}</div>`, `<button class="btn btn-ghost" data-action="close-modal">إغلاق</button>`);
    return;
  }
  const go = document.getElementById("cxmGo");
  if (go) { go.disabled = true; go.textContent = "جارٍ الإرسال…"; }
  cxdSendAll(list, "رسالة من الإدارة", textOf).then(n => {
    closeModal();
    showToast(n === list.length ? "أُرسلت الرسالة إلى " + toArabicDigits(n) + " طالب"
      : "وصلت إلى " + toArabicDigits(n) + " من " + toArabicDigits(list.length) + " — تحقّق من الاتصال",
      n === list.length ? "success" : "warn");
  });
};

function supervisorDashboard() {
  const sc = myScope();
  const day = attDate();

  const myMosques  = (cur("mosques") || []);
  const myCircles  = (cur("circles") || []).filter(c => c && c.status !== "متوقف");
  const myStuds    = (cur("students") || []).filter(s => s && s.status !== "متوقف");
  const myTeachers = (cur("teachers") || []).filter(t => t && t.active !== false);

  /* ---------- ما ينتظر تدخّله ---------- */
  const pend = [];

  /* حلقاتٌ لم تُحضَّر بعد */
  const notTaken = myCircles.filter(c => {
    const kids = myStuds.filter(s => String(s.circleId) === String(c.id));
    if (!kids.length) return false;
    if (typeof isDutyDay === "function" && !kids.some(k => isDutyDay(k, day))) return false;
    return !(cur("attendance") || []).some(a =>
      !a.staffId && String(a.date) === day && String(a.circleId) === String(c.id));
  });
  if (notTaken.length) pend.push({
    n: notTaken.length, h: "حلقات لم تُحضَّر اليوم",
    d: notTaken.slice(0, 3).map(c => c.name).join(" · "),
    go: "admin/attendance", tint: "warn", ico: "attend"
  });

  /* معلّمون غائبون */
  const absTeachers = (cur("attendance") || []).filter(a =>
    a && a.staffId && String(a.date) === day && a.status === "غائب");
  if (absTeachers.length) pend.push({
    n: absTeachers.length, h: "معلّمون غائبون اليوم",
    d: absTeachers.slice(0, 3).map(a => a.staff || a.student || "").filter(Boolean).join(" · "),
    go: "admin/duty", tint: "danger", ico: "person"
  });

  /* طلاب ينتظرون اعتماد الترقية */
  const awaiting = (cur("plans") || []).filter(p => p && p.awaitingPromotion);
  if (awaiting.length) pend.push({
    n: awaiting.length, h: "طلاب أنهوا مستواهم",
    d: awaiting.slice(0, 3).map(p => p.student).filter(Boolean).join(" · "),
    go: "admin/plans", tint: "info", ico: "target"
  });

  /* حسابات تنتظر الاعتماد */
  const newUsers = (cur("users") || []).filter(u =>
    u && (u.pending || u.active === false) && u.role !== "owner");
  if (newUsers.length) pend.push({
    n: newUsers.length, h: "حسابات تنتظر الاعتماد",
    d: newUsers.slice(0, 3).map(u => u.name).filter(Boolean).join(" · "),
    go: "admin/users", tint: "info", ico: "person"
  });

  /* طلاب بلا خطة — لا يُولَّد لهم واجب. ومن وُضع على «تحضير فقط» قصداً
     لا يُعدّ منهم: وضعُه اختيارٌ لا نقصٌ يُنبَّه عليه كلَّ يوم. */
  const noPlan = myStuds.filter(st => st.circleId && !st.attOnly &&
    !(cur("plans") || []).some(p => String(p.studentId) === String(st.id)));
  if (noPlan.length) pend.push({
    n: noPlan.length, h: "طلاب بلا خطة",
    d: noPlan.slice(0, 3).map(s => s.name).join(" · "),
    go: "admin/plans", tint: "warn", ico: "book"
  });

  const pendCards = pend.length
    ? pend.map(p => `<button type="button" class="sup-task ${p.tint}"
        onclick="window.go('${p.go}')">
        <span class="st-ico">${ic(p.ico, 20)}</span>
        <span class="st-body">
          <b>${toArabicDigits(p.n)}</b>
          <strong>${esc(p.h)}</strong>
          ${p.d ? `<small>${esc(p.d)}</small>` : ""}
        </span>
      </button>`).join("")
    : `<div class="sup-clear">${ic("check", 22)}
        <div><strong>لا شيء ينتظرك</strong>
        <small>حلقاتُك حُضّرت، ولا طلبَ معلَّقاً.</small></div></div>`;

  /* ---------- حال الحلقات ---------- */
  const rows = myCircles.map(c => {
    const kids = myStuds.filter(s => String(s.circleId) === String(c.id));
    const att = (cur("attendance") || []).filter(a =>
      !a.staffId && String(a.date) === day && String(a.circleId) === String(c.id));
    const here = att.filter(a => a.status === "حاضر" || a.status === "متأخر").length;
    const pct = kids.length ? Math.round(here * 100 / kids.length) : 0;

    const rec = (cur("recitations") || []).filter(r =>
      r && String(r.date) === day && String(r.circleId) === String(c.id)).length;

    const sess = typeof sessionOf === "function" ? sessionOf(day, c.id) : null;

    return `<tr>
      <td><strong>${esc(c.name || "—")}</strong>
        <div class="muted" style="font-size:11.5px">${esc(c.mosque || "")}</div></td>
      <td class="muted">${esc(c.teacher || "—")}</td>
      <td class="pt-num">${toArabicDigits(kids.length)}</td>
      <td>${att.length
        ? `<div class="sup-bar"><i style="width:${pct}%"></i></div>
           <span class="sup-pct">${toArabicDigits(pct)}٪</span>`
        : `<span class="muted" style="font-size:12px">لم يُحضَّر</span>`}</td>
      <td class="pt-num">${toArabicDigits(rec)}</td>
      <td>${sess ? badge("معتمدة", "b-green") : badge("مفتوحة", "b-gray")}</td>
    </tr>`;
  }).join("");

  return `<div class="page">
    ${pageHead("لوحة المشرف",
      toArabicDigits(myMosques.length) + " منشأة · " +
      toArabicDigits(myCircles.length) + " حلقة · " +
      toArabicDigits(myStuds.length) + " طالباً")}

    <div class="grid g-4" style="margin-bottom:18px">
      ${[["الحلقات", myCircles.length, "circles"],
         ["المعلّمون", myTeachers.length, "person"],
         ["الطلاب", myStuds.length, "people"],
         ["المنشآت", myMosques.length, "mosque"]].map(([h, n, i2]) =>
        `<div class="fc-body"><div class="fc-ico">${ic(i2, 20)}</div>
          <div class="fc-num">${toArabicDigits(n)}</div>
          <div class="fc-label">${h}</div></div>`).join("")}
    </div>

    <div class="card" style="margin-bottom:18px">
      <div class="fac-toolbar">
        <div><strong style="font-size:15px">ما ينتظرك اليوم</strong>
          <div class="muted" style="font-size:11.5px;margin-top:2px">
            اضغط أيّها لتذهب إليه</div></div>
      </div>
      <div class="sup-tasks">${pendCards}</div>
    </div>

    <div class="card">
      <div class="fac-toolbar">
        <div><strong style="font-size:15px">حال حلقاتك اليوم</strong></div>
      </div>
      <div class="pt-wrap"><div class="pt-scroll"><table class="ptable">
        <thead><tr><th>الحلقة</th><th>المعلّم</th><th>الطلاب</th>
          <th>الحضور</th><th>سُمّع</th><th>الجلسة</th></tr></thead>
        <tbody>${rows || `<tr><td colspan="6" class="muted"
          style="text-align:center;padding:24px">لا حلقات في نطاقك</td></tr>`}</tbody>
      </table></div></div>
    </div>
  </div>`;
}

function adminDashboard() {
  /* لوحةُ مدير النظام: إحصاءاتٌ عامّة لا غير.
     كانت تعرض بطاقاتِ المجمّعات والمساجد، وهي عينُ ما تعرضه صفحةُ
     «المنشآت التعليمية» — فشاشتان لشيءٍ واحد. البطاقاتُ بقيت في مكانها
     هناك، وهذه صارت للأرقام: ما في النظام، وحضورُ اليوم. */
  const complexes = cur("complexes");
  const mosques   = cur("mosques");
  const circles   = cur("circles");
  const students  = cur("students");
  const staff     = cur("teachers");
  const teachers  = staff.filter(x => !isStaffManager(x));
  const managers  = staff.filter(isStaffManager);

  const counts = sGrid([
    sCard("المجمعات",  toArabicDigits(complexes.length), SC.teal,   "building"),
    sCard("المساجد",   toArabicDigits(mosques.length),   SC.blue,   "mosque"),
    sCard("الحلقات",   toArabicDigits(circles.length),   SC.green,  "grid"),
    sCard("الطلاب",    toArabicDigits(students.length),  SC.purple, "users"),
    sCard("المعلمون",  toArabicDigits(teachers.length),  SC.cyan,   "teacher"),
    sCard("المدراء",   toArabicDigits(managers.length),  SC.gold,   "person")
  ], 3);

  /* حضورُ اليوم من سجلّات فعلية، لا أرقامٌ ثابتة */
  const ids = {}; students.forEach(x => { ids[String(x.id)] = 1; });
  const today = todayISO();
  const recs = (Array.isArray(DB.attendance) ? DB.attendance : [])
    .filter(r => String(r.date) === today && ids[String(r.studentId)]);
  const cnt = k => recs.filter(r => r.status === k).length;
  const marked = recs.length, total = students.length;
  const pct = total ? Math.round(marked / total * 100) : 0;

  const ATT_IC = { "حاضر": "check", "متأخر": "clock", "مستأذن": "eye", "غائب": "x" };
  /* صفوفُ الحضور أزرارٌ تفتح صفحةَ المتابعة: كانت div بلا فعل، فيضغطها
     الناظرُ ولا يحدث شيء. والشكلُ هو .att-row نفسُه كي لا تختلف الصفوف. */
  const attRows = ATT_STATES.map(k => {
    const n = cnt(k), p = total ? Math.round(n / total * 100) : 0;
    return `<button type="button" class="att-row ${ATT_TINT[k] || ""}"
      data-action="nav" data-page="attendance" title="فتح متابعة الحضور">
      <span class="att-ico">${ic(ATT_IC[k] || "check", 17)}</span>
      <span class="att-name">${esc(k)}</span>
      <span class="att-count">(${toArabicDigits(n)})</span>
      <span class="att-pct">${p}%</span></button>`;
  }).join("");

  /* أكبرُ المجمّعات عدداً — قراءةٌ سريعة لا تكرارَ فيها للبطاقات */
  const rank = complexes.map(c => ({
    name: c.name || "—",
    mosques: mosques.filter(m => String(m.complexId) === String(c.id)).length,
    students: students.filter(x => String(x.complexId) === String(c.id)).length
  })).sort((a, b) => b.students - a.students).slice(0, 6);

  const rankRows = rank.length
    ? rank.map(r => `<div class="list-row">
        <div class="mini-avatar">${ic("building", 15)}</div>
        <div style="flex:1"><strong style="font-size:13.5px">${esc(r.name)}</strong>
          <div class="muted" style="font-size:12px">${toArabicDigits(r.mosques)} مسجداً</div></div>
        <strong style="font-size:13px">${toArabicDigits(r.students)} طالباً</strong>
      </div>`).join("")
    : `<div class="muted" style="padding:14px;text-align:center">لا توجد مجمعات بعد.</div>`;

  return `<div class="page">
    ${pageHead("لوحة التحكم", "إحصاءات النظام العامة", "")}
    ${dataBanner()}
    ${counts}
    <div style="height:18px"></div>
    <div class="grid g-2" style="align-items:start">
      <div class="card">
        <div class="section-head"><h3>حضور اليوم</h3>
          <span class="badge b-gray">${toArabicDigits(marked)} / ${toArabicDigits(total)}</span></div>
        <div class="att-rows">${attRows}</div>
        <div style="margin-top:12px"><span class="muted" style="font-size:12px">نسبة تسجيل التحضير</span>
          ${progressRow(pct)}</div>
      </div>
      <div class="card">
        <div class="section-head"><h3>المجمعات الأكبر</h3>
          <button class="btn btn-ghost btn-sm" data-action="nav" data-page="complexes">${ic("eye", 15)} فتح الصفحة</button></div>
        <div class="list-card">${rankRows}</div>
      </div>
    </div>
  </div>`;
}

/* فرز المساجد: الكل · تابع لمجمع · مستقل · مجمع بعينه */
/* المنشأةُ التي دخلها المستخدم — محفوظةٌ في الجلسة من زرّ «دخول»، تُقرأ
   في كلّ صفحةٍ لأن STATE يبدأ من جديد مع كلّ انتقال. */
/* =========================================================================
   شعارُ المنشأة مكانَ شعار النظام
   -------------------------------------------------------------------------
   القائمةُ الجانبية تحمل شعار «ذات» ثابتاً في كلّ صفحة. فمن كان داخل مسجدٍ
   أو مجمّعٍ له صورة، عُرضت صورتُه مكانَه — فيعرف أينَ هو من نظرة. ومن لا
   صورةَ لمنشأته، أو كان خارج أيّ منشأة، بقي شعارُ «ذات» كما هو.

   الصورةُ من حقل photo في سجلّ المنشأة — وهو الحقلُ نفسُه المعروضُ في
   بطاقتها، فلا حقلَ جديد ولا نموذجَ يُعدَّل.
   ========================================================================= */
function brandFacility() {
  const find = (coll, id) => id
    ? (Array.isArray(DB[coll]) ? DB[coll] : []).find(x => x && String(x.id) === String(id))
    : null;

  /* أوّلاً: المنشأةُ التي دخلناها من شاشة المنشآت */
  const fc = typeof facCtx === "function" ? facCtx() : null;
  if (fc && fc.id) {
    const r = find(fc.coll === "complexes" ? "complexes" : "mosques", fc.id);
    if (r) return r;
  }
  /* ثمّ منشأةُ الحساب نفسِه: مسجدُه أوّلاً فهو الأخصّ، ثمّ مجمّعُه */
  const u = (STATE && STATE.user) || {};
  return find("mosques", u.mosqueId) || find("complexes", u.complexId) || null;
}

function brandLogoSync() {
  const wrap = document.querySelector(".brand .brand-logo-wrap");
  if (!wrap) return;
  const img = wrap.querySelector(".brand-logo-img");
  if (!img) return;

  /* الأصلُ يُحفظ مرّةً فيُرجَع إليه متى زالت الصورة */
  if (!img.dataset.zatSrc) img.dataset.zatSrc = img.getAttribute("src") || "";

  const f = brandFacility();
  const photo = f && f.photo ? String(f.photo) : "";
  const want = photo || img.dataset.zatSrc;
  if (img.getAttribute("src") !== want) img.setAttribute("src", want);

  /* صورةُ المنشأة تُقصّ في إطارها، وشعارُ «ذات» يبقى على حاله */
  wrap.classList.toggle("brand-has-photo", !!photo);
  img.style.display = "";
  const fb = wrap.querySelector(".brand-fallback");
  if (fb) fb.style.display = "none";
  img.setAttribute("alt", photo ? (f.name || "شعار المنشأة") : "شعار ذات القرآنية");
}

function facCtx() {
  try {
    var raw = sessionStorage.getItem("__facCtx");
    return raw ? JSON.parse(raw) : null;
  } catch (e) { return null; }
}

/* معرّفُ المجمّع الذي نحن داخله — أو "" إن كنّا خارج أي مجمّع */
function facCtxComplexId() {
  var c = facCtx();
  return (c && c.coll === "complexes" && c.id) ? String(c.id) : "";
}

function mqFilter() {
  if (!STATE.mqFilter) {
    /* الداخلُ إلى مجمّعٍ يريد مساجدَه هو: كانت الصفحةُ تفتح على «كل
       المساجد» فيرى مساجدَ غيره ويظنّها تابعةً له. */
    var _cx = facCtxComplexId();
    STATE.mqFilter = _cx ? { kind: "one", complexId: _cx } : { kind: "all", complexId: "" };
    /* فرزٌ قادمٌ من بطاقة لوحة التحكم — يُقرأ مرّةً ثمّ يُمحى، فلا يعلق
       على الصفحة كلّما فُتحت بعد ذلك. */
    try {
      var q = sessionStorage.getItem("__mqFilter");
      if (q) { STATE.mqFilter.kind = q; sessionStorage.removeItem("__mqFilter"); }
    } catch (e) {}
  }
  return STATE.mqFilter;
}

window.mqPickComplex = function (id) {
  const f = mqFilter();
  f.complexId = String(id || "");
  f.kind = f.complexId ? "one" : "all";
  mount();
};

/* تبويبُ المساجد — كان شاشةً مستقلّة، وبقيت أدواتُه كما هي */
function facilitiesMosques() {
  var _fv = takePendingFacility();
  if (_fv) return facilityDetail(_fv.coll, _fv.id);

  const all = cur("mosques");
  const f = mqFilter();

  const linked = all.filter(m => m.complexId);
  const indep  = all.filter(m => !m.complexId);

  let list = all;
  if (f.kind === "linked") list = linked;
  else if (f.kind === "indep") list = indep;
  else if (f.kind === "one") list = all.filter(m => String(m.complexId || "") === String(f.complexId));

  if (!all.length) {
    return `<div class="page">${pageHead("المنشآت التعليمية", "", addBtn("إضافة مسجد", "modal-mosque"))}
      ${facTabs()}
      <div class="card">${emptyState("لا توجد مساجد بعد",
        "أضف أول مسجد من زر الإضافة، واختر تبعيته لمجمع أو اجعله مستقلاً.")}</div></div>`;
  }

  const sub = f.kind === "indep" ? "المساجد المستقلة بإدارتها الخاصة"
            : f.kind === "linked" ? "المساجد التابعة لمجمعات تعليمية"
            : f.kind === "one" ? "مساجد " + complexName(f.complexId)
            : "كل مساجد النظام";

  const grid = list.length
    ? `<div class="fac-grid" id="facGrid" data-coll="mosques">${list.map(x => facCard(x, "mosques")).join("")}</div>`
    : `<div class="card">${emptyState("لا توجد مساجد في هذا الفرز", "جرّب فرزاً آخر من الأزرار أعلاه.")}</div>`;

  return `<div class="page">
    ${pageHead("المنشآت التعليمية", sub, addBtn("إضافة مسجد", "modal-mosque"))}
    ${facTabs()}
    ${facToolbar("mosques", list.filter(x => x.status === "نشط").length)}
    ${grid}
  </div>`;
}

/* adminMosques تبقى مُحيلةً: مساراتٌ قديمة وأزرارٌ في شاشاتٍ أخرى تناديها */
/* adminMosques كانت تُفوّض إلى adminFacilities، وهي تُفوّض إلى
   facilitiesMosques — تفويضٌ متبادلٌ شلّ الصفحة. صارت الشاشةُ مستقلّةً
   بذاتها، والتبويباتُ تنقل بين مسارين لا بين حالتين في مسارٍ واحد. */
function adminMosques() { return facilitiesMosques(); }
/* =========================================================
   ADMIN — 2. MOSQUES
   ========================================================= */
/* adminMosques مُعرّفة ضمن العرض الموحّد للمنشآت أعلى الملف */
/* =========================================================
   ADMIN — 3. CIRCLES
   ========================================================= */
/* =========================================================================
   الحلقات — بنفس مكوّن جداول الطلاب والمعلمين (personTable)
   -------------------------------------------------------------------------
   كانت الصفحة جدولاً يدوياً بشريط فلاتر معطّل: القوائم الثلاث بلا معالج،
   والبحث بلا معالج، ولا تحديد ولا لوحة إجراءات. وكانت تقرأ DB.circles
   مباشرة بلا cur()، فيرى المعلّم أو المشرف حلقات المنشآت الأخرى.
   ========================================================================= */
function circleAvatar(c) {
  if (c.photo) return `<img src="${esc(c.photo)}" alt="">`;
  return ic("book", 18);
}

function adminCircles() {
  const list = cur("circles");     /* محصورة بالمنشأة والدور */

  return personTable({
    rowPanel: "edit-circle",
    list, title: "الحلقات", showCount: true, toolbar: "add",
    addLabel: "إضافة حلقة", addAction: "modal-circle", actionsPanel: true,
    searchHint: "إبحث عن حلقة",
    empty: "أضف أول حلقة من زر الإضافة، بعد إضافة المسجد والمعلم.",
    cols: [
      { h: "الصورة", cell: c => `<td class="pt-photo"><span class="pt-avatar">${circleAvatar(c)}</span></td>` },
      { h: "الاسم", cell: c => `<td class="pt-name">${esc(c.name || "—")}</td>` },
      { h: "الحالة", cell: (c, a) => `<td><span class="pt-badge ${a ? "on" : "off"}">${a ? "فعال" : "متوقف"}</span></td>` },
      { h: "التصنيف", cell: c => `<td class="${c.level ? "" : "pt-muted"}">${esc(c.level || "بدون تصنيف")}</td>` },
      { h: "النوع", cell: c => `<td>${esc(c.type || "حلقة قرآنية")}</td>` },
      { h: "الطلاب", cell: c => {
          /* العدّ الحيّ من سجلات الطلاب لا من حقل students المخزَّن،
             فذاك يتقادم كلما نُقل طالب أو حُذف. */
          const n = cur("students").filter(st =>
            String(st.circleId || "") === String(c.id) ||
            String(st.circle || "") === String(c.name || "")).length;
          return `<td class="pt-num">${n}</td>`;
        } },
      { h: "الوقت", cell: c => `<td class="pt-num" dir="ltr">${esc(c.start || "—")}${c.end ? " — " + esc(c.end) : ""}</td>` },
      { h: "المعلم", cell: c => `<td class="${c.teacher ? "" : "pt-muted"}">${esc(c.teacher || "بدون معلم")}</td>` },
      /* عمودُ الإجراءات حُذف: التعديلُ بالنقر على الصفّ، والحذفُ والإيقافُ
         في لوحة الإجراءات جانباً — فلا يتكرّر الفعلُ في موضعين. */
    ]
  });
}

function modalEditCircle(id) {
  const c = DB.circles.find(x => x.id == id);
  if (!c) { showToast("الحلقة غير موجودة", "warn"); return; }
  openModal("تعديل بيانات الحلقة", "عدّل بيانات الحلقة ثم احفظ",
    `<div class="form-grid">
      <div class="field full"><label>اسم الحلقة</label><input id="ec_name" value="${esc(c.name)}"></div>
      ${photoField("ec_photo", c.photo || "", "شعار الحلقة أو صورتها")}
      ${facTwoFields("ec_cx", "ec_mosque", c.complexId || "", c.mosqueId || "")}
      <!-- المعلم لم يكن في نموذج التعديل: لو غادر معلم الحلقة فلا سبيل
           لتغييره، وهو الحقل الذي يرثه كل طلابها -->
      <div class="field"><label>المعلم المسؤول</label>
        ${(() => {
          /* بالمعرّف لا بالاسم، ومعها «—» (٤٣١): كانت القائمةُ بالأسماء وبلا
             خيارٍ فارغ، فحلقةٌ لا يطابق نصُّ معلّمها اسماً في القائمة تُختار
             لها أوّلُ معلّمٍ تلقائياً — وأيُّ حفظٍ بعدها ينقل طلابَها إليه. */
          const tl = (cur("teachers") || []).slice();
          const own = c.teacherId ? (DB.teachers || []).find(t2 => String(t2.id) === String(c.teacherId)) : null;
          if (own && !tl.some(t2 => String(t2.id) === String(own.id))) tl.unshift(own);
          const selId = own ? String(own.id)
            : String(((c.teacher && c.teacher !== "—") ? (tl.find(t2 => t2.name === c.teacher) || {}).id : "") || "");
          return `<select id="ec_teacher" data-orig="${esc(selId)}">
            <option value="" ${selId ? "" : "selected"}>—</option>${tl.map(t2 =>
              `<option value="${esc(String(t2.id))}"${String(t2.id) === selId ? " selected" : ""}>${esc(t2.name)}</option>`).join("")}</select>`;
        })()}</div>

      <!-- معلّمٌ ثانٍ يعمل في الحلقة كالأصيل -->
      <div class="field"><label>المعلّمون المساعدون</label>
        <button type="button" class="btn btn-ghost btn-sm" style="width:100%"
          onclick="window.asstOpen('${jsAttr(c.id)}')">${
          (c.assistants || []).length
            ? toArabicDigits((c.assistants || []).length) + " مساعد — تعديل"
            : "إسناد مساعد"}</button>
        ${(c.assistants || []).length ? `<small style="font-size:11px;color:var(--text-faint)">${
          esc(assistantsOf(c).map(t => t.name).join(" · "))}</small>` : ""}</div>

      <div class="field"><label>نوع الحلقة</label><select id="ec_type">${
        circleTypeOptions(c.mosqueId, c.complexId).map(o =>
          `<option ${o === c.type ? "selected" : ""}>${esc(o)}</option>`).join("")}</select></div>
      <div class="field"><label>الحد الأقصى للطلاب</label>
        <input id="ec_cap" type="number" min="0" value="${esc(c.capacity || "")}" placeholder="بلا حد">
        <small style="font-size:11px;color:var(--text-faint)">المسجّلون الآن: ${
          toArabicDigits(circleCount(c))}</small></div>
      ${(() => {
        const tr = (cur("terms") || []).filter(x => x.status !== "منتهية" || String(x.id) === String(c.termId));
        return tr.length ? `<div class="field"><label>الفترة الدراسية</label>
          <select id="ec_term"><option value="">— بلا فترة —</option>
          ${tr.map(x => `<option value="${esc(x.id)}"${String(c.termId) === String(x.id)
            ? " selected" : ""}>${esc(x.name)}</option>`).join("")}</select></div>` : "";
      })()}
      <div class="field"><label>جهة التحضير</label>
        <select id="ec_attwho"><option value="">حسب الإعداد العام (${esc((ATT_WHO.find(x => x.k === attCfg().who) || {}).h || "")})</option>
          ${ATT_WHO.map(x => `<option value="${x.k}"${c.attWho === x.k ? " selected" : ""}>${esc(x.h)}</option>`).join("")}</select></div>
      <!-- رابط غرفة المقرأة لهذه الحلقة — يسبق رابط المسجد العام -->
      <div class="field full"><label>رابط المقرأة (اختياري)</label>
        <input id="ec_maq" dir="ltr" value="${esc(c.maqraahUrl || "")}"
          placeholder="يُترك فارغاً ليُستعمل رابط المسجد"></div>

      ${daysPicker("ec_days", c.days)}
      <div class="field full"><label>توقيت الحلقة</label>
        <select id="ec_mode" onchange="window.circleTimeMode('ec',this.value)">
          <option value="fixed"${c.anchor ? "" : " selected"}>وقت ثابت</option>
          <option value="anchor"${c.anchor ? " selected" : ""}>مرتبط بأذان</option>
        </select>
        ${c.anchor ? `<small style="font-size:11px;color:var(--text-faint)">${
          esc(circleTimeText(c))}</small>` : ""}</div>

      <div class="field" id="ec_fixedA"${c.anchor ? ' style="display:none"' : ""}>
        <label>وقت البداية</label><input id="ec_start" inputmode="numeric" maxlength="5"
        value="${esc(c.start)}" oninput="window.clockMask(this)" onblur="window.clockMask(this, true)"></div>
      <div class="field" id="ec_fixedB"${c.anchor ? ' style="display:none"' : ""}>
        <label>وقت النهاية</label><input id="ec_end" inputmode="numeric" maxlength="5"
        value="${esc(c.end)}" oninput="window.clockMask(this)" onblur="window.clockMask(this, true)"></div>

      <div class="field" id="ec_anchA"${c.anchor ? "" : ' style="display:none"'}>
        <label>تبدأ بعد</label>
        <select id="ec_anchor">${PRAYERS.map(p2 =>
          `<option value="${esc(p2.k)}"${c.anchor === p2.k ? " selected" : ""}>${esc(p2.h)}</option>`).join("")}</select></div>
      <div class="field" id="ec_anchB"${c.anchor ? "" : ' style="display:none"'}>
        <label>بـ (دقيقة)</label>
        <input id="ec_offset" type="number" min="0" max="180" dir="ltr" value="${esc(c.offset || 0)}"></div>
      <div class="field" id="ec_anchC"${c.anchor ? "" : ' style="display:none"'}>
        <label>تنتهي بأذان</label>
        <select id="ec_endAnchor"><option value="">— بلا —</option>${PRAYERS.map(p2 =>
          `<option value="${esc(p2.k)}"${c.endAnchor === p2.k ? " selected" : ""}>${esc(p2.h)}</option>`).join("")}</select></div>
      <div class="field"><label>الحالة</label><select id="ec_status">${["معتمدة", "قيد العمل", "لم تعتمد"].map(o => `<option ${o === c.status ? "selected" : ""}>${o}</option>`).join("")}</select></div>
    </div>`,
    `<button class="btn btn-primary" data-action="save-edit-circle" data-id="${id}">${ic("check", 16)} حفظ التعديلات</button>
     <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
}

