function selField(label, opts, req) {
  return `<div class="field"><label>${esc(label)}${req ? ' <span class="req">*</span>' : ""}</label><select>${opts.map(o => `<option>${esc(o)}</option>`).join("")}</select></div>`;
}


const DOW = ["السبت", "الأحد", "الإثنين", "الثلاثاء", "الأربعاء", "الخميس", "الجمعة"];
const DUTY_META = {
  "حفظ جديد": { cls: "d-memorize", color: "var(--danger)", short: "حفظ" },
  "مراجعة":   { cls: "d-review",   color: "var(--brand-main)", short: "مراجعة" },
  "تثبيت":    { cls: "d-fix",      color: "var(--gold)", short: "تثبيت" },
  "تلاوة":    { cls: "d-recite",   color: "var(--info)", short: "تلاوة" },
  "تعويض":    { cls: "d-comp",     color: "var(--purple)", short: "تعويض" }
};
const HEALTH = {
  healthy: { label: "صحية", cls: "b-green", tint: "t-green", ic: "checkCircle" },
  review:  { label: "تحتاج مراجعة", cls: "b-amber", tint: "t-amber", ic: "alert" },
  blocked: { label: "محظورة", cls: "b-red", tint: "t-red", ic: "lock" },
  frozen:  { label: "مجمدة", cls: "b-gray", tint: "t-purple", ic: "freeze" }
};

let PLAN_EXTRA = {};
const SAMPLE_PLAN_EXTRA = {};

function planAttType(p) {
  const s = DB.students.find(x => x.name === p.student);
  return s ? s.attType : "دوام كامل";
}

/* معرّفُ الخطة كما في data-id: رقمٌ لما أنشأته النماذج، ونصٌّ («pl…») لما
   أُسنِد بالقالب — وكان يُقرأ بـ +t.dataset.id فيصير NaN فتقول الإجراءاتُ
   «الخطة غير موجودة» (٤٣٢). يُرجع سجلَّ الخطة أو null. */
function planOfDs(raw) {
  const k = String(raw == null ? "" : raw);
  return (DB.plans || []).find(x => x && String(x.id) === k) || null;
}
function getPlan(id) {
  const p = DB.plans.find(x => x.id == id);
  if (!p) return null;
  let ext = PLAN_EXTRA[id];
  if (!ext) ext = defaultExtra(p);
  return Object.assign({}, p, { ext });
}
function defaultExtra(p) {
  const partial = planAttType(p) === "دوام جزئي";
  const days = partial ? ["الأحد", "الثلاثاء"] : ["السبت", "الأحد", "الإثنين", "الثلاثاء", "الأربعاء", "الخميس"];
  const sched = {};
  DOW.forEach(d => { sched[d] = days.includes(d) ? ["حفظ جديد", "مراجعة", "تثبيت"] : []; });
  const map = { "نشطة": "healthy", "تحتاج مراجعة": "review", "متوقفة": "frozen" };
  const health = p.delays > 0 ? "blocked" : (map[p.status] || "healthy");
  return {
    health,
    healthReason: "خطة جديدة تم إنشاؤها للتو من باني الخطط.",
    healthAction: "تابع أول جلسة تسميع لتقييم سير الخطة.",
    sched,
    rules: { tilawah: true, fixation: true, lowEval: true, absence: true, partial: true, openBlocks: true },
    transition: { mode: "supervisor", test: false, noDelays: true, minScore: 7 },
    history: [{ by: USER_NAME[STATE.iface] || "مدير النظام", role: "مدير النظام", dt: "الآن", field: "إنشاء الخطة", before: "—", after: "خطة نشطة", reason: "إنشاء عبر باني الخطط" }],
    requests: [],
    today: [
      { type: "حفظ جديد", range: p.current, why: "اليوم من أيام الحفظ المجدولة.", status: "لم يبدأ" },
      { type: "مراجعة", range: "المقطع السابق", why: "مراجعة دورية مجدولة.", status: "لم يبدأ" }
    ],
    tomorrow: [{ type: "حفظ جديد", range: "المقطع التالي", why: "تقدم متوقع بعد اجتياز تسميع اليوم." }]
  };
}

function adminPlans() {
  if (STATE.planId != null) return planDetailPage(STATE.planId);
  const tabs = [
    { id: "active", label: "الخطط النشطة" },
    { id: "new", label: "باني الخطة" },
    { id: "comp", label: "المتأخرات والتعويض" },
    { id: "review", label: "مراجعة الخطط" }
  ];
  const cur = STATE.tab.plans || "active";
  const tabBar = `<div class="tabs">${tabs.map(t => `<button class="tab ${t.id === cur ? "active" : ""}" data-action="tab" data-group="plans" data-tab="${t.id}">${esc(t.label)}</button>`).join("")}</div>`;
  return `<div class="page">
    ${pageHead("خطط الطلاب القرآنية", "قلب النظام: خطط مرنة بمسارات وقواعد ومراحل قابلة للتخصيص بالكامل")}
    ${(cur === "active" && (DB.plans || []).length)
      ? `<div style="margin-bottom:14px"><button class="btn btn-primary btn-sm"
          onclick="window.bulkAssign()">${ic("users", 15)} إسناد خطة لعدّة طلاب</button></div>`
      : ""}
    ${tabBar}
    <div id="plansPanel">${plansTab(cur)}</div>
  </div>`;
}
function plansTab(id) {
  if (id === "new") return planBuilder();
  if (id === "comp") return planCompTab();
  if (id === "review") return planReviewTab();
  return planActiveTab();
}
function rerenderPlansPanel() {
  const panel = document.querySelector("#plansPanel");
  if (panel) { panel.innerHTML = plansTab(STATE.tab.plans || "active"); runAnimations(panel); }
}

function planActiveTab() {
  if (!DB.plans.length) {
    return `<div class="tab-panel"><div class="card">${emptyState("لا توجد خطط بعد", "أنشئ أول خطة من تبويب «باني الخطة». يلزم وجود طالب واحد وبرنامج واحد على الأقل.")}</div></div>`;
  }
  const rows = DB.plans.filter(p => p && p.superseded !== true).map(p => {
    const pl = getPlan(p.id);
    const h = HEALTH[pl.ext.health];
    return `<tr>
    <td><div class="td-name"><div class="mini-avatar">${initials(p.student)}</div><div><div class="td-strong">${esc(p.student)}</div><div class="muted" style="font-size:11.5px">${esc(p.circle)}</div></div></div></td>
    <td style="font-size:12.5px">${esc(p.program)}<div class="muted" style="font-size:11.5px">${esc(p.level)}</div></td>
    <td style="font-size:12px">${esc(p.start)} ← <strong>${esc(p.current)}</strong> ← ${esc(p.end)}</td>
    <td style="min-width:115px">${progressRow(p.progress)}</td>
    <td class="center">${p.delays > 0 ? badge(p.delays, "b-red") : badge("0", "b-gray")}</td>
    <td>${badge(h.label, h.cls)}</td>
    <td><div class="row-actions">
      <button class="btn btn-soft btn-sm" data-action="plan-open" data-id="${p.id}">${ic("eye", 15)} عرض الخطة</button>
    </div></td>
  </tr>`;
  }).join("");
  return `<div class="tab-panel">
    <div class="table-wrap"><div class="table-scroll"><table class="data">
      <thead><tr><th>الطالب</th><th>البرنامج والمستوى</th><th>مسار الخطة</th><th>التقدم</th><th>متأخرات</th><th>صحة الخطة</th><th></th></tr></thead>
      <tbody>${rows}</tbody>
    </table></div></div>
  </div>`;
}

function planDetailPage(id) {
  const pl = getPlan(id);
  if (!pl) { STATE.planId = null; return adminPlans(); }
  const h = HEALTH[pl.ext.health];
  const frozen = planIsFrozen(pl);
  const blocked = pl.ext.health === "blocked";

  return `<div class="page">
    <div style="margin-bottom:16px"><button class="btn btn-ghost btn-sm" data-action="plan-back">${ic("arrowLeft", 15)} رجوع لقائمة الخطط</button></div>

    <div class="plan-hero">
      <div class="plan-hero-main">
        <div style="display:flex;gap:13px;align-items:center">
          <div class="avatar" style="width:52px;height:52px;font-size:18px">${initials(pl.student)}</div>
          <div>
            <h2 style="font-size:21px;font-weight:800">${esc(pl.student)}</h2>
            <div class="muted" style="font-size:13px">${esc(pl.circle)} · ${esc(pl.program)} — ${esc(pl.level)}</div>
          </div>
        </div>
        <div class="plan-path">
          <div class="pp-node"><small>البداية</small><strong>${esc(pl.start)}</strong></div>
          <div class="pp-line">${ic("arrowLeft", 16)}</div>
          <div class="pp-node cur"><small>الموضع الحالي</small><strong>${esc(pl.current)}</strong></div>
          <div class="pp-line">${ic("arrowLeft", 16)}</div>
          <div class="pp-node"><small>النهاية</small><strong>${esc(pl.end)}</strong></div>
        </div>
        <div style="margin-top:14px;max-width:420px">
          <div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:5px"><span class="muted">نسبة الإنجاز</span><strong style="color:var(--brand-dark)">${pl.progress}%</strong></div>
          ${progressRow(pl.progress, "gold")}
        </div>
      </div>
      <div class="plan-health ${h.tint}">
        <div class="ph-badge">${ic(h.ic, 18)} ${h.label}</div>
        <div class="ph-row"><span>المقدار اليومي</span><strong>${esc(pl.amount)} (${esc(pl.unit)})</strong></div>
        <div class="ph-row"><span>المتأخرات</span><strong>${pl.delays > 0 ? pl.delays + " مفتوحة" : "لا يوجد"}</strong></div>
        <div class="ph-reason"><strong>السبب:</strong> ${esc(pl.ext.healthReason)}</div>
        <div class="ph-reason action"><strong>الإجراء الموصى به:</strong> ${esc(pl.ext.healthAction)}</div>
      </div>
    </div>

    <div class="plan-actions">
      <button class="btn btn-primary btn-sm" data-action="modal-edit-path" data-id="${id}">${ic("edit", 15)} تعديل المسار</button>
      <button class="btn ${frozen ? "btn-soft" : "btn-ghost"} btn-sm" data-action="modal-freeze" data-id="${id}">${ic("freeze", 15)} ${frozen ? "إعادة التفعيل" : "تجميد الخطة"}</button>
      <button class="btn btn-ghost btn-sm" data-action="modal-add-comp" data-id="${id}">${ic("plus", 15)} إضافة تعويض</button>
      <button class="btn btn-gold btn-sm" data-action="modal-promote" data-id="${id}">${ic("trophy", 15)} اعتماد ترقية</button>
      <button class="btn btn-ghost btn-sm" data-action="modal-daily-duties" data-id="${id}">${ic("book", 15)} معاينة واجبات اليوم</button>
    </div>

    ${blocked ? `<div class="block-banner">${ic("lock", 18)} <div><strong>الخطة محظورة من التقدم.</strong> يوجد تعويض مفتوح يمنع توليد واجبات جديدة حتى إغلاقه أو تأجيله.</div></div>` : ""}

    <div class="grid g-2" style="align-items:start;margin-bottom:6px">
      <div class="section"><div class="section-head"><h3>قواعد الخطة</h3></div>${planRulesCard(pl)}</div>
      <div class="section"><div class="section-head"><h3>قواعد الانتقال للمستوى</h3></div>${transitionCard(pl)}</div>
      <div class="section"><div class="section-head"><h3>تكرار السورة والمستوى</h3></div>${planRepeatCard(pl)}</div>
    </div>

    <div class="section"><div class="section-head"><h3>معاينة الجدول الأسبوعي</h3>
      <span class="muted" style="font-size:12px">${planAttType(pl) === "دوام جزئي" ? "طالب دوام جزئي — الأيام غير المجدولة محايدة" : "دوام كامل"}</span></div>
      ${planTimeline(pl)}
    </div>

    <div class="section"><div class="section-head"><h3>الواجبات المولّدة من الخطة</h3></div>
      ${dailyDutiesContent(pl)}
    </div>

    <div class="section"><div class="section-head"><h3>طلبات تعديل الخطة</h3>
      <span class="badge ${pl.ext.requests.filter(r => r.status === "pending").length ? "b-amber" : "b-gray"} no-dot">${pl.ext.requests.filter(r => r.status === "pending").length} قيد الانتظار</span></div>
      ${planRequests(pl)}
    </div>

    <div class="section"><div class="section-head"><h3>سجل تغييرات الخطة</h3></div>
      ${planHistory(pl)}
    </div>
  </div>`;
}

/* =========================================================================
   قواعد الخطة — من قاعدة البيانات لا من الذاكرة
   -------------------------------------------------------------------------
   كانت تُقرأ من PLAN_EXTRA: كائنٍ في الذاكرة بقيمٍ ثابتة مكتوبة في الكود.
   تُعرض «مفعّلة» أبداً ولا سبيل لتعطيلها، وتضيع مع كل إعادة تحميل.
   ========================================================================= */
/* =========================================================================
   التجميد: مصدر واحد
   -------------------------------------------------------------------------
   نظامان تجمَّدت بهما الخطة: القديم ext.health="frozen" في الذاكرة يكتبه
   زر «تجميد» في بطاقة الصحة، والجديد p.frozen في قاعدة البيانات يقرؤه
   محرّك الواجبات. فيُجمَّد بأحدهما ويظلّ المحرّك يولّد الواجبات.

   الحقل المحفوظ هو الحكم — والذاكرة تتبعه. */
/* =========================================================================
   إسناد خطة واحدة لعدّة طلاب
   -------------------------------------------------------------------------
   كانت الخطة واحداً لواحد: studentId مفرد، فمن أراد خطةً لعشرين طالباً
   أنشأها عشرين مرة، وأيّ تعديل عليها يُعاد عشرين مرة.

   الحلّ: الخطة تصير قالباً يُنسخ. لكلّ طالبٍ نسخته — لأن موضعه يتقدّم
   وحده وتقييمه يخصّه — وتبقى مربوطةً بالقالب عبر templateId، فتعديل
   القالب يسري على من لم يبدأ بعد، ومن بدأ يبقى على موضعه.

   نسخةٌ لكلٍّ لا سجلٌّ مشترك: المشترك يعني أن تقدّم طالبٍ يزحزح البقية.
   ========================================================================= */

const BULK = { plan: "", picked: {}, filterCircle: "", q: "" };

window.bulkPick = function (id, on) { BULK.picked[String(id)] = !!on; };
window.bulkSet = function (k, v) { BULK[k] = String(v || ""); bulkRender(); };

window.bulkAll = function (on) {
  bulkCandidates().forEach(s => { BULK.picked[String(s.id)] = !!on; });
  bulkRender();
};

/* من يصلح للإسناد: النشطون بلا خطة، أو بخطةٍ من قالبٍ آخر */
function bulkCandidates() {
  let list = (cur("students") || []).filter(s => s && s.status !== "متوقف");

  if (BULK.filterCircle) {
    list = list.filter(s => String(s.circleId) === String(BULK.filterCircle) ||
                            String(s.circle) === String(BULK.filterCircle));
  }
  if (BULK.q) list = list.filter(s => String(s.name || "").indexOf(BULK.q) > -1);

  return list;
}

function bulkPlanOf(st) {
  return (cur("plans") || []).find(p =>
    String(p.studentId) === String(st.id) ||
    (p.student && nameKey(p.student) === nameKey(st.name))) || null;
}

/* الفتح من زر في صفحة الخطط */
window.bulkAssign = function (planId) {
  const plans = (cur("plans") || []).filter(p => p);
  if (!plans.length) { showToast("أنشئ خطةً أولاً لتُسند لغيره", "warn"); return; }

  BULK.plan = String(planId || (plans[0] && plans[0].id) || "");
  BULK.picked = {};
  bulkRender();
};

function bulkRender() {
  const plans = (cur("plans") || []).filter(p => p);
  const src = plans.find(p => String(p.id) === String(BULK.plan));
  const cands = bulkCandidates();
  const circles = cur("circles") || [];

  const n = cands.filter(s => BULK.picked[String(s.id)]).length;

  const rows = cands.map(s => {
    const has = bulkPlanOf(s);
    const same = has && src && String(has.templateId || has.id) === String(src.templateId || src.id);
    return `<tr>
      <td class="pt-check"><label class="switch">
        <input type="checkbox"${BULK.picked[String(s.id)] ? " checked" : ""}
          onchange="window.bulkPick('${jsAttr(s.id)}',this.checked)">
        <span class="slider"></span></label></td>
      <td><strong>${esc(s.name || "—")}</strong></td>
      <td class="muted">${esc(s.circle || "—")}</td>
      <td>${same ? '<span class="pt-badge on">عليها بالفعل</span>'
        : has ? `<span class="pt-badge off">له خطة: ${esc(has.program || has.level || "—")}</span>`
        : (s.attOnly ? '<span class="chip t-blue">تحضير فقط</span>'
                     : '<span class="muted">بلا خطة</span>')}</td>
    </tr>`;
  }).join("");

  openModal("إسناد خطة لعدّة طلاب",
    "نسخةٌ لكلّ طالب — يتقدّم كلٌّ بموضعه",
    `<div class="form-grid">
       <div class="field full"><label>الخطة المصدر</label>
         <select onchange="window.bulkSet('plan',this.value)">
           ${plans.map(p => `<option value="${esc(p.id)}"${
             String(BULK.plan) === String(p.id) ? " selected" : ""}>${
             esc(p.student || "—")} — ${esc(p.program || "")}${
             p.level ? " · " + esc(p.level) : ""}</option>`).join("")}
         </select></div>

       <div class="field"><label>تصفية بالحلقة</label>
         <select onchange="window.bulkSet('filterCircle',this.value)">
           <option value="">كل الحلقات</option>
           ${circles.map(c => `<option value="${esc(c.id)}"${
             BULK.filterCircle === String(c.id) ? " selected" : ""}>${esc(c.name)}</option>`).join("")}
         </select></div>

       <div class="field"><label>بحث</label>
         <input value="${esc(BULK.q)}" placeholder="اسم الطالب"
           oninput="window.bulkSet('q',this.value)"></div>
     </div>

     ${src ? noteCard(`تُنسخ إعدادات خطة <strong>${esc(src.student || "")}</strong>:
       البرنامج والمستوى والمقدار والوحدة وموضع البداية.
       <br>من له خطة سابقة تُستبدل — وتقدّمه المرصود لا يُحذف.`) : ""}

     <div style="display:flex;gap:8px;margin:10px 0">
       <button class="btn btn-ghost btn-sm" onclick="window.bulkAll(true)">تحديد الكل</button>
       <button class="btn btn-ghost btn-sm" onclick="window.bulkAll(false)">إلغاء الكل</button>
       <span class="muted" style="margin-inline-start:auto;font-size:12.5px;align-self:center">
         ${toArabicDigits(n)} محدَّد من ${toArabicDigits(cands.length)}</span>
     </div>

     <div class="pt-wrap" style="max-height:320px;overflow:auto">
       <table class="ptable"><thead><tr><th></th><th>الطالب</th>
         <th>الحلقة</th><th>الحالة</th></tr></thead>
         <tbody>${rows || '<tr><td colspan="5" class="muted" style="text-align:center;padding:20px">لا طلاب</td></tr>'}</tbody>
       </table></div>`,

    `<button class="btn btn-primary" onclick="window.bulkAssignDo()">
       إسناد لـ${toArabicDigits(n)} طالباً</button>
     <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
}

window.bulkAssignDo = function () {
  const src = (cur("plans") || []).find(p => String(p.id) === String(BULK.plan));
  if (!src) { showToast("اختر الخطة المصدر", "warn"); return; }

  const ids = Object.keys(BULK.picked).filter(k => BULK.picked[k]);
  if (!ids.length) { showToast("لم تحدّد طلاباً", "warn"); return; }

  /* القالب: الخطة المصدر نفسها إن لم تكن نسخةً من قالبٍ آخر */
  const tid = String(src.templateId || src.id);
  if (!src.templateId) { src.templateId = tid; persistSet("plans", src); }

  let made = 0, replaced = 0;

  ids.forEach((sid, i) => {
    const st = (cur("students") || []).find(x => String(x.id) === String(sid));
    if (!st) return;

    const old = bulkPlanOf(st);
    /* عليها بالفعل: لا يُنسخ فوق نفسه فيضيع تقدّمه */
    if (old && String(old.templateId || old.id) === tid) return;

    const rec = {
      id: old ? old.id : ("pl" + Date.now() + "-" + i),
      templateId: tid,
      complexId: st.complexId || "",
      studentId: String(st.id), student: st.name || "",
      circle: st.circle || "", circleId: st.circleId || "",

      /* المنسوخ من القالب */
      program: src.program || "", programId: src.programId || "",
      level: src.level || "", levelId: src.levelId || "",
      amount: src.amount, unit: src.unit,
      direction: src.direction || "forward",
      weeks: src.weeks || 0,
      fixLessons: src.fixLessons,
      hifzFromS: src.hifzFromS, hifzFromA: src.hifzFromA,
      start: src.start, current: src.start, end: src.end,

      /* لكلٍّ تقدّمه: لا يُنسخ من المصدر */
      progress: 0, delays: 0, status: "نشطة",
      frozen: false,
      ts: Date.now(),
      termId: typeof activeTermId === "function" ? activeTermId() : ""
    };

    if (old) {
      /* الاستبدال يحفظ ما أُنجز: التقدّم المرصود في assignments لا يُمسّ */
      rec.progress = old.progress || 0;
      rec.delays = old.delays || 0;
      replaced++;
    } else made++;

    if (!Array.isArray(DB.plans)) DB.plans = [];
    const k = DB.plans.findIndex(x => String(x.id) === String(rec.id));
    if (k > -1) DB.plans[k] = rec; else DB.plans.unshift(rec);
    persistSet("plans", rec);

    /* قواعد القالب تُنسخ كما هي */
    try {
      const srcRules = (cur("planRules") || []).find(r => String(r.planId) === String(src.id));
      if (srcRules) {
        const pr = { id: "pr_" + rec.id, planId: String(rec.id),
                     rules: Object.assign({}, srcRules.rules || {}), ts: Date.now() };
        if (!Array.isArray(DB.planRules)) DB.planRules = [];
        const q = DB.planRules.findIndex(x => String(x.planId) === String(rec.id));
        if (q > -1) DB.planRules[q] = pr; else DB.planRules.push(pr);
        persistSet("planRules", pr);
      }
    } catch (e) {}

    /* الخطةُ المُسنَدة منهجُه: موضعُها هو القولُ الأحدث، وبطاقتُه تتبعها —
       فلا تُرجعه سورتُه القديمةُ في البطاقة عند حفظها التالي */
    stuCurriculumWins(rec, null);
    persistSet("plans", rec);
    stuCardFollowPlan(st, rec);

    /* سجل الطالب يتبع خطته */
    if (rec.levelId) {
      st.levelId = rec.levelId; st.level = rec.level;
      st.program = rec.program;
      persistSet("students", st);
    }
  });

  closeModal();
  showToast("أُسندت الخطة: " + toArabicDigits(made) + " جديد" +
            (replaced ? " · " + toArabicDigits(replaced) + " مُستبدَل" : ""), "success");
  mount();
};

/* =========================================================================
   تعديل القالب يسري على نسخه
   ------------------------------------------------------------------------- */
function planSiblings(pl) {
  if (!pl) return [];
  const tid = String(pl.templateId || pl.id);
  return (cur("plans") || []).filter(p =>
    p && String(p.templateId || "") === tid && String(p.id) !== String(pl.id));
}

window.planSyncTemplate = function (planId) {
  const src = (cur("plans") || []).find(p => String(p.id) === String(planId));
  if (!src) return;

  const sibs = planSiblings(src);
  if (!sibs.length) { showToast("لا نسخ أخرى من هذه الخطة", "info"); return; }

  openModal("تعميم التعديل", src.student || "",
    noteCard(`تُنسخ إعدادات هذه الخطة إلى <strong>${toArabicDigits(sibs.length)}</strong>
      خطةً أخرى من القالب نفسه: البرنامج والمستوى والمقدار والوحدة والاتجاه.
      <br><strong>لا يُنسخ</strong> موضع كلّ طالب ولا تقدّمه — يبقى كلٌّ حيث وقف.`),
    `<button class="btn btn-primary" onclick="window.planSyncDo('${jsAttr(planId)}')">
       تعميم على ${toArabicDigits(sibs.length)}</button>
     <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
};

window.planSyncDo = function (planId) {
  const src = (cur("plans") || []).find(p => String(p.id) === String(planId));
  if (!src) return;

  const keys = ["program", "programId", "level", "levelId", "amount", "unit",
                "direction", "weeks", "fixLessons"];
  let n = 0;

  planSiblings(src).forEach(p => {
    keys.forEach(k => { if (src[k] !== undefined) p[k] = src[k]; });
    persistSet("plans", p);
    n++;
  });

  closeModal();
  showToast("عُمّم التعديل على " + toArabicDigits(n) + " خطة", "success");
  mount();
};

/* =========================================================================
   مكتبة الخطط والمناهج
   -------------------------------------------------------------------------
   المواصفات: «الخطط قوالبٌ ثابتة في النظام، يجب أن تكون مستقلّةً عن
   الدورات. يُنشأ مكتبةٌ عامة تسمى مكتبة الخطط والمناهج، وفي الدورة الجديدة
   كلّ ما على الإدارة فعله الدخول على الطالب واختيار قالب الخطة المناسب من
   المكتبة مباشرة».

   والوظيفة كاملةٌ في النظام — templateId و bulkAssign و planSiblings —
   لكنها موزّعة بلا شاشةٍ تجمعها، فتُبحث القوالب في قائمة الخطط بين مئات
   خطط الطلاب. المكتبة تجمعها في موضعٍ واحد يُقصد.
   ========================================================================= */
function planTemplates() {
  const plans = cur("plans") || [];
  const seen = {};

  plans.forEach(p => {
    if (!p) return;
    const tid = String(p.templateId || "");
    if (!tid) return;
    if (!seen[tid]) {
      /* الأصل: الخطة التي معرّفها هو معرّف القالب، وإلا أقدم نسخة */
      const src = plans.find(x => String(x.id) === tid) || p;
      seen[tid] = { id: tid, src, uses: 0, students: [] };
    }
    seen[tid].uses++;
    if (p.student) seen[tid].students.push(p.student);
  });

  return Object.keys(seen).map(k => seen[k])
    .sort((a, b) => b.uses - a.uses);
}

/* خططٌ مفردة لم تُجعل قوالب بعد — يُعرض للإدارة أن تجعلها */
function soloPlans() {
  return (cur("plans") || []).filter(p => p && !p.templateId);
}

window.tplMake = function (planId) {
  const p = (cur("plans") || []).find(x => String(x.id) === String(planId));
  if (!p) return;

  openModal("جعلها قالباً", p.student || "",
    noteCard(`ستصير خطة <strong>${esc(p.student || "")}</strong> قالباً في المكتبة،
      فتُسند لغيره بضغطة دون إعادة كتابة تفاصيلها.
      <br>خطة الطالب نفسه لا تتغيّر.`),
    `<button class="btn btn-primary" onclick="window.tplMakeDo('${jsAttr(planId)}')">جعلها قالباً</button>
     <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
};

window.tplMakeDo = function (planId) {
  const p = (cur("plans") || []).find(x => String(x.id) === String(planId));
  if (!p) return;
  p.templateId = String(p.id);
  p.templateName = p.program || p.level || p.student || "قالب";
  persistSet("plans", p);
  closeModal();
  showToast("صارت قالباً — أسندها من المكتبة", "success");
  mount();
};

window.tplRename = function (tid) {
  const t = planTemplates().find(x => x.id === tid);
  if (!t) return;

  openModal("تسمية القالب", "",
    `<input type="hidden" id="tp_id" value="${esc(tid)}">
     <div class="form-grid"><div class="field full"><label>اسم القالب</label>
       <input id="tp_name" value="${esc(t.src.templateName || t.src.program || "")}"
         placeholder="مثال: خطة حفظ جزء عمّ"></div></div>
     ${noteCard("الاسم يظهر في المكتبة وعند الإسناد — يُختار به القالب.")}`,
    `<button class="btn btn-primary" onclick="window.tplRenameDo()">حفظ</button>
     <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
};

window.tplRenameDo = function () {
  const tid = val("#tp_id");
  const name = (val("#tp_name") || "").trim();
  if (!name) { showToast("الاسم مطلوب", "warn"); return; }

  /* الاسم يُكتب في كلّ نسخ القالب: البحث عنه يجري بها جميعاً */
  (DB.plans || []).forEach(p => {
    if (String(p.templateId || "") !== String(tid)) return;
    p.templateName = name;
    persistSet("plans", p);
  });

  closeModal();
  showToast("سُمّي القالب", "success");
  mount();
};

/* شاشة المكتبة */
