/* =========================================================================
   الافتراضيُّ العامُّ للصلاحيات — شاشة «إدارة الصلاحيات» في الإعدادات
   -------------------------------------------------------------------------
   كانت الصلاحياتُ تُضبط في بطاقة كلّ معلّمٍ وحدَها، فمن أراد قاعدةً تسري
   على الجميع فتحها واحداً واحداً.

   تُحفظ هنا في settings.teacherPerms، ويقرأها teacherCan بعد صلاحية
   الحساب نفسِه: ما ضُبط في بطاقة المعلّم صراحةً يغلب، وما لم يُضبط يرث
   هذا الافتراضيَّ، وما لم يُذكر في الاثنين فمسموح — فلا يُفاجأ معلّمٌ قائم
   بقفل صلاحيةٍ لم تُعطَّل.
   ========================================================================= */
function permsDefaults() {
  return ((DB.settings || {}).teacherPerms) || {};
}

/* صلاحيةُ الضبط: قاعدةُ الخادم تقصر الكتابة في settings على المدير */
function canPermsSetup() { return typeof isTopAdmin === "function" && isTopAdmin(); }

/* =========================================================================
   الافتراضيُّ العامُّ للصلاحيات — شاشة «إدارة الصلاحيات» في الإعدادات
   -------------------------------------------------------------------------
   كانت الصلاحياتُ تُضبط في بطاقة كلّ معلّمٍ وحدَها، فمن أراد قاعدةً تسري
   على الجميع فتحها واحداً واحداً.

   تُحفظ هنا في settings.teacherPerms، ويقرأها teacherCan بعد صلاحية
   الحساب نفسِه: ما ضُبط في بطاقة المعلّم صراحةً يغلب، وما لم يُضبط يرث
   هذا الافتراضيَّ، وما لم يُذكر في الاثنين فمسموح — فلا يُفاجأ معلّمٌ قائم
   بقفل صلاحيةٍ لم تُعطَّل.
   ========================================================================= */
function permsDefaults() {
  return ((DB.settings || {}).teacherPerms) || {};
}

/* صلاحيةُ الضبط: مديرُ النظام، والمعلّمُ بطلبٍ صريح من الإدارة.
   -------------------------------------------------------------------------
   وهي مطابقةٌ لقاعدة الخادم حرفاً بحرف (firestore.rules ← match /settings):
     allow write: if isAdmin();
     allow write: if docId == "teacherPerms" && isTeacher() && …
   ومديرُ المسجد والمشرف خارجَهما عمداً: لو فُتحت لهما هنا وحدَهما لرأيا
   رسالةَ نجاحٍ ثمّ يردّ الخادمُ الكتابةَ فتعود القيمةُ كما كانت — وشاشةٌ
   تكذب أسوأُ من شاشةٍ تمنع. توسيعُها إليهما يبدأ من القاعدة لا من هنا. */
function canPermsSetup() {
  if (typeof isTopAdmin === "function" && isTopAdmin()) return true;
  const r = typeof myRoleNow === "function" ? myRoleNow() : "";
  if (typeof isMgrRole === "function" && isMgrRole(r)) return true;
  return r === "teacher";
}

function permsField(u, hidden) {
  const p = (u && u.perms) || {};
  const on = k => p[k] !== false;

  return `<div class="field full perm-wrap"${hidden ? ' style="display:none"' : ""}>
    <label>صلاحيات المعلم</label>
    <div class="perm-box">
      ${TEACHER_PERMS.map(item => {
        if (item.g) return `<div class="perm-group">${esc(item.g)}</div>`;
        return `<label class="perm-row ${on(item.k) ? "on" : ""}">
          <input type="checkbox" data-perm="${esc(item.k)}" ${on(item.k) ? "checked" : ""}
            onchange="window.permToggle(this)">
          <span class="perm-txt">
            <strong>${esc(item.h)}</strong>
            ${item.d ? `<span class="perm-d">${esc(item.d)}</span>` : ""}
          </span>
          <span class="perm-state">${on(item.k) ? "مفعّلة" : "معطّلة"}</span>
        </label>`;
      }).join("")}
    </div>
    <div class="hint">الصلاحيات المفعّلة افتراضياً — عطّل ما لا تريد إتاحته لهذا المعلم.</div>
  </div>`;
}

window.permToggle = function (cb) {
  const row = cb.closest(".perm-row");
  if (!row) return;
  row.classList.toggle("on", cb.checked);
  const st = row.querySelector(".perm-state");
  if (st) st.textContent = cb.checked ? "مفعّلة" : "معطّلة";
};

function permsValue() {
  const out = {};
  const box = document.querySelector(".perm-box");
  if (!box) return null;                 /* الحقل غير معروض: لا تُمسّ القيم */
  Array.prototype.forEach.call(box.querySelectorAll("input[data-perm]"), function (cb) {
    out[cb.dataset.perm] = !!cb.checked;
  });
  return out;
};

/* إظهار الحقل عند اختيار دور «معلم» وإخفاؤه لغيره */
window.roleChanged = function (selEl) {
  const wrap = document.querySelector(".perm-wrap");
  if (wrap) wrap.style.display = selEl.value === "teacher" ? "" : "none";

  /* حقلُ «الأبناء» يحلّ محلّ «أماكن الإشراف» لوليّ الأمر، وهما يُبنيان
     مع النموذج. فتبديلُ الدور يستلزم إعادةَ بنائه — وإلا بقي الحقلُ
     الأوّل ظاهراً ولم يجد المستخدمُ موضعاً يربط به الأبناء. */
  const wasParent = !!document.getElementById("usKidBox");
  const nowParent = selEl.value === "parent";
  if (wasParent === nowParent) return;

  const id = val("#usId");
  const keep = {
    name: val("#usName"), phone: val("#usPhone"),
    email: val("#usEmail"), nat: val("#usNat"), gender: val("#usGender")
  };

  window.userForm(id, selEl.value);

  /* ما كُتب لا يضيع بتبديل الدور */
  setTimeout(function () {
    const set = (k, v) => { const e = document.getElementById(k); if (e && v) e.value = v; };
    set("usName", keep.name); set("usPhone", keep.phone);
    set("usEmail", keep.email); set("usNat", keep.nat); set("usGender", keep.gender);
    const r = document.getElementById("usRole");
    if (r) r.value = selEl.value;
  }, 0);
};

window.userForm = function (id, presetRole) {
  const u = id ? (cur("users") || []).find(x => String(x.id) === String(id)) : null;
  const facs = cur("complexes").concat(cur("mosques"));
  const role = u ? u.role : (presetRole || "mosqueManager");

  /* حالة منتقي الأبناء تُهيّأ من الحساب: المفتوحُ بعد آخرَ لا يرث اختياره.
     ويُبدأ بما رُبط فعلاً، فإن لم يُربط بعدُ فبما رُجّح من طلب تسجيله. */
  USK.q = ""; USK.circle = "";
  USK.picked = (u && Array.isArray(u.studentIds) && u.studentIds.length)
    ? u.studentIds.map(String)
    : (u && u.studentId ? [String(u.studentId)] : []);

  if (!USK.picked.length && u && Array.isArray(u.kidsRequested)) {
    u.kidsRequested.forEach(k => {
      const g = typeof matchKid === "function" ? matchKid(k) : null;
      if (g) USK.picked.push(String(g.id));
    });
  }
  openModal(u ? "تعديل بيانات المستخدم" : "إضافة مشرف", "",
    `<input type="hidden" id="usId" value="${u ? esc(u.id) : ""}">
     <div class="form-grid">
      ${photoField("us_photo", u ? (u.photo || "") : "", "الصورة الشخصية")}
      <div class="field full"><label>الاسم <span class="req">*</span></label>
        <input id="usName" value="${u ? esc(u.name || "") : ""}" placeholder="الاسم الكامل"></div>
      <div class="field"><label>رقم الهوية <span class="req">*</span></label>
        <input id="usUser" inputmode="numeric" maxlength="10" dir="ltr" placeholder="1110071212"
          value="${u ? esc(u.username || "") : ""}"
          oninput="this.value = this.value.replace(/[^0-9]/g, '').slice(0,10)"></div>
      <div class="field"><label>البريد الإلكتروني</label>
        <div class="us-mail">
          <input id="usEmail" dir="ltr" placeholder="name@domain"
            value="${u ? esc(String(u.email || "").replace(/\.com$/i, "")) : ""}">
          <span class="us-suffix">.com</span>
        </div></div>
      <div class="field"><label>رقم الواتس</label>
        <input id="usPhone" inputmode="numeric" dir="ltr" placeholder="9665xxxxxxxx" maxlength="15"
          value="${u ? esc(u.phone || "") : ""}"
          oninput="this.value = this.value.replace(/[^0-9]/g, '').slice(0,15)"></div>
      <div class="field"><label>الجنسية</label>
        <input id="usNat" value="${u ? esc(u.nationality || "المملكة العربية السعودية") : "المملكة العربية السعودية"}"></div>
      <div class="field"><label>الجنس</label>
        <select id="usGender">
          <option value="ذكر"${!u || u.gender !== "أنثى" ? " selected" : ""}>ذكر</option>
          <option value="أنثى"${u && u.gender === "أنثى" ? " selected" : ""}>أنثى</option>
        </select></div>
      <div class="field"><label>الدور <span class="req">*</span></label>
        <select id="usRole" onchange="window.roleChanged(this)">${assignableRoles(u && u.role).map(r =>
          `<option value="${r.k}"${r.k === role ? " selected" : ""}>${esc(r.h)}</option>`).join("")}
        ${role === "supervisor" ? `<option value="supervisor" selected>مشرف / ة (دور قديم)</option>` : ""}</select></div>
      ${permsField(u, role !== "teacher")}
      <!-- أجر المشرف: المسيّرات تقرأ salary من ملفّه، ولم يكن له حقلٌ
           يكتبه — فيُحسب مسيّره صفراً وإن عمل الشهر كلّه. -->
      ${isMgrRole(role) || role === "admin" ? `
      <div class="field"><label>نوع الأجر</label>
        <select id="usPayType" onchange="window.teacherPayType('us')">
          ${[["monthly", "راتب شهري"], ["daily", "أجر يومي"],
             ["hourly", "أجر بالساعة"], ["volunteer", "متطوّع — بلا أجر"]]
            .map(x => `<option value="${x[0]}"${
              ((u && u.payType) || "monthly") === x[0] ? " selected" : ""}>${x[1]}</option>`).join("")}
        </select></div>
      <div class="field" id="us_payWrap"${
        u && u.payType === "volunteer" ? ' style="display:none"' : ""}>
        <label>المبلغ</label>
        <input id="usPay" type="number" min="0" step="50" dir="ltr"
          value="${u ? esc(u.salary || u.wage || u.hourRate || "") : ""}"></div>` : ""}

      ${role === "parent" ? `
      <!-- وليُّ الأمر لا يشرف على منشأة: يتابع أبناءه. وحقلُ «أماكن الإشراف»
           كان يظهر له بلا معنى، ولا يجد موضعاً يربط به أولاده. -->
      <div class="field full"><label>الأبناء المتابَعون <span class="req">*</span></label>
        <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px">
          <select class="mig-dest" onchange="window.usKidFilter(this.value)" style="max-width:170px">
            <option value="">كلّ الحلقات</option>
            ${(cur("circles") || []).filter(c => c.status !== "متوقف").map(c =>
              `<option value="${esc(c.id)}">${esc(c.name)}</option>`).join("")}
          </select>
          <input class="mig-dest" placeholder="ابحث بالاسم" style="max-width:150px"
            oninput="window.usKidSearch(this.value)">
          <span id="usKidCount" class="muted"
            style="font-size:12px;align-self:center;margin-inline-start:auto"></span>
        </div>
        <div class="pick-box" id="usKidBox"></div>
        <div class="hint">اختر ابناً أو أكثر. ومن لم تختره لن يظهر لوليّه.</div>
      </div>

      ${Array.isArray(u && u.kidsRequested) && u.kidsRequested.length ? `
      <div class="field full">
        ${noteCard("طلب عند التسجيل: " +
          u.kidsRequested.map(k => esc(k.name) + (k.idNo ? " · " + esc(k.idNo) : "")).join(" · "))}
      </div>` : ""}
      ` : `
      <div class="field full"><label>أماكن الإشراف</label>
        ${facPickField("usFacs", u)}
        <div class="hint">اختر منشأة أو أكثر. ترك الاختيار فارغاً يعني <strong>كل المنشآت</strong>.</div>
      </div>`}
      <div class="field full">
        <div class="toggle-row"><div class="tr-text"><strong>الحساب فعّال</strong>
          <small>عند الإيقاف لا يستطيع المستخدم تسجيل الدخول</small></div>
          <label class="switch"><input type="checkbox" id="usActive" ${!u || u.active !== false ? "checked" : ""}>
            <span class="slider"></span></label></div>
      </div>
     </div>`,
    `<button class="btn btn-primary" data-action="user-save">${u ? "حفظ" : "إضافة"}</button>
     <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);

  /* المنتقي يُرسم بعد فتح النافذة: عناصره غير موجودةٍ قبلها */
  setTimeout(function () { if (typeof usKidRender === "function") usKidRender(); }, 0);
};

window.userSave = function () {
  /* منح owner من نموذج المستخدم يمرّ من هنا: يُحرس كما يُحرس الاعتماد */
  if (val("#usRole") === "owner" && !isTopAdmin()) {
    showToast("دور المالك لا يمنحه إلا مالكٌ قائم", "warn"); return;
  }

  const name = (val("#usName") || "").trim();
  if (!name) { showToast("الاسم مطلوب", "warn"); return; }
  const uid = (val("#usUser") || "").replace(/[^0-9]/g, "");
  if (!uid) { showToast("رقم الهوية مطلوب (أرقام فقط)", "warn"); return; }
  if (uid.length !== 10) { showToast("رقم الهوية يجب أن يكون 10 أرقام", "warn"); return; }
  let email = (val("#usEmail") || "").trim().replace(/\.com$/i, "");
  if (email && email.indexOf("@") < 1) { showToast("البريد الإلكتروني غير صحيح", "warn"); return; }
  if (email) email += ".com";

  if (!Array.isArray(DB.users)) DB.users = [];
  const id = val("#usId");
  const el = x => document.getElementById(x);
  const scopeIds = facPickValue("usFacs");
  /* أول مسجد وأول مجمع يُكتبان في الحقلين المفردين للتوافق الخلفي */
  const firstMq = scopeIds.filter(k => k.indexOf("mosque:") === 0)[0];
  const firstCx = scopeIds.filter(k => k.indexOf("complex:") === 0)[0];
  /* =======================================================================
     القائمتان الجمعيّتان: بهما وحدَهما يعرف الخادمُ نطاقَ الحساب كاملاً
     -----------------------------------------------------------------------
     كان يُكتب scopeIds (وهو ما يقرؤه المتصفّح) والحقلان المفردان وحدَهما.
     و firestore.rules لا تقرأ scopeIds أصلاً: نطاقُها
     mosqueIds + complexIds + الحقلان المفردان. فمن أُسنِد إلى مسجدين
     يرى الاثنين ولا يكتب إلا في الأوّل — يفتح الطالبَ ويحرّره ثمّ يُردّ
     عند الحفظ. تُكتب القائمتان الآن، فيتطابق ما يراه بما يكتبه.
     ولا توسيعَ في الصلاحية: هي عينُ ما أُسنِد في scopeIds لا غير.
     ======================================================================= */
  const mosqueIds  = scopeIds.filter(k => k.indexOf("mosque:")  === 0).map(k => k.split(":")[1]);
  const complexIds = scopeIds.filter(k => k.indexOf("complex:") === 0).map(k => k.split(":")[1]);
  const u0 = id ? DB.users.find(x => String(x.id) === String(id)) : null;

  /* لا يُمنح دورٌ أعلى من دور المانح — وإلّا أنشأ مديرُ المجمّع مديرَ
     نظامٍ ودخل به. حارسٌ في الواجهة، ومثلُه في قواعد Firestore. */
  const wantRole = val("#usRole") || "mosqueManager";
  if (!canGrantRole(wantRole)) {
    showToast("لا تملك منح هذا الدور", "warn"); return;
  }
  const data = {
    name, username: uid, email,
    loginEmail: email || (uid + "@mirath.id"),   /* الدخول برقم الهوية */
    phone: (val("#usPhone") || "").replace(/[^0-9]/g, ""), nationality: val("#usNat") || "المملكة العربية السعودية",
    gender: val("#usGender") || "ذكر", role: val("#usRole") || "mosqueManager",

    /* أبناءُ وليّ الأمر: يُكتبان معاً — المتعدّد للاستعمال، والمفرد
       للتوافق مع ما بُني قبل تعدّد الأبناء. */
    ...((val("#usRole") || "") === "parent" ? {
      studentIds: USK.picked.slice(),
      studentId: USK.picked.length === 1 ? USK.picked[0] : ""
    } : {}),
    /* أجر المشرف — payFields تكتبه في حقله وحده */
    ...(document.getElementById("usPayType")
      ? payFields(val("#usPayType", "monthly"), val("#usPay")) : {}),
    photo: photoVal("us_photo", u0 ? (u0.photo || "") : ""),
    perms: (function () {
      const pv = permsValue();
      /* الحقل يظهر للمعلم وحده، فلا تُمسّ صلاحيات غيره */
      return pv || (u0 && u0.perms) || {};
    })(),
    scopeIds: scopeIds,
    mosqueId:  firstMq ? firstMq.split(":")[1] : "",
    complexId: firstCx ? firstCx.split(":")[1] : "",
    mosqueIds: mosqueIds, complexIds: complexIds,
    active: !!(el("usActive") && el("usActive").checked)
  };


  /* الحسابُ الذي يُنشأ موقوفاً طلبٌ ينتظر الاعتماد: يُعلَّم بـ pending
     فيظهر في «طلبات إضافة مستخدم»، وكان يُكتب موقوفاً فلا يراه أحد.
     والتفعيلُ يمحو العلامة فلا يعود الموقوفُ بعدها «طلباً». */
  data.pending = !data.active;
  data.createdByName = ((STATE && STATE.user) || {}).name ||
                       ((STATE && STATE.user) || {}).email || "الإدارة";

  /* ---- تعديل: لا مساس بحساب الدخول ---- */
  if (id) {
    const u = DB.users.find(x => String(x.id) === String(id));
    if (u) {
      Object.assign(u, data); persistSet("users", u);
      syncTeacherRecord(u); syncStudentRecord(u);
      /* «تم تعديل بيانات حسابك» — لصاحب الحساب لا لمن عدّله */
      try {
        const meId = String(((STATE && STATE.user) || {}).id || "");
        if (String(u.id) !== meId) notifyUser(u.id, "accountEdited",
          "عدّلت الإدارةُ بياناتِ حسابك.");
      } catch (e) {}
    }
    photoReset("us_photo");
    showToast("حُفظت البيانات", "success");
    closeModal(); mount();
    return;
  }

  /* ---- إضافة: يُنشأ حساب دخول حقيقي، ومعرّف المستند = uid ---- */
  /* مديرُ المنشأة لا يُنشئ معلّماً أو مديراً «لكلّ المنشآت» (٤٣٥): الحسابُ بلا
     نطاقٍ يكتب في كلّ منشأة، والقاعدةُ تردّ ملفَّه — بعد أن يكون حسابُ الدخول
     قد أُنشئ فيبقى يتيماً. فيُطلب الاختيارُ قبل الإنشاء. */
  if (!isTopAdmin() && !scopeIds.length && ["student", "parent"].indexOf(data.role) === -1) {
    showToast("اختر في «أماكن الإشراف» منشأةً واحدةً على الأقلّ من منشآتك", "warn"); return;
  }
  if (DB.users.some(x => String(x.username) === uid)) { showToast("رقم الهوية مسجَّل بالفعل", "warn"); return; }
  const dup = DB.users.some(x => data.email && String(x.email).toLowerCase() === data.email.toLowerCase());
  if (dup) { showToast("البريد الإلكتروني مستخدم بالفعل", "warn"); return; }

  const btn = document.querySelector('[data-action="user-save"]');
  if (btn) { btn.disabled = true; btn.textContent = "جارٍ إنشاء الحساب…"; }

  createAuthUser({ email: data.email, username: uid })
    .then(res => {
      const u = Object.assign({ id: res.uid, uid: res.uid, loginEmail: res.loginEmail, createdAt: Date.now() }, data);
      DB.users.push(u);
      /* رفضُ الملفّ بعد إنشاء حساب الدخول يُقال بعينه (٤٣٥): يبقى حسابُ دخولٍ
         بلا ملفّ. وشاشةُ «الحسابات اليتيمة» في js/accounts.js غيرُ محمَّلة،
         فيُدلّ على الموضع الذي يُحذف منه فعلاً، باسم الحساب (٤٤٠). */
      Promise.resolve(persistSet("users", u)).then(ok => {
        if (ok === false) showToast("أُنشئ حساب الدخول ورفض الخادمُ حفظَ ملفّه — يبقى حسابُ دخولٍ بلا ملفّ: يحذفه مديرُ النظام من Firebase Console ← Authentication (" + (res.loginEmail || "") + ")", "warn");
      });
      syncTeacherRecord(u);   /* يظهر فوراً في صفحة المعلمين وقوائم الحلقات */
      syncStudentRecord(u);   /* وكذلك الطالب في صفحة الطلاب */
      closeModal(); mount();
      showToast("أُضيف " + (USER_ROLES.find(r => r.k === data.role) || {}).h, "success");
      showCredentials(res, data.name);
    })
    .catch(err => {
      console.warn("createAuthUser:", err);
      showToast(authErrMsg(err), "warn");
      if (btn) { btn.disabled = false; btn.textContent = "إضافة"; }
    });
};

/* =========================================================================
   المستخدمون والحسابات
   -------------------------------------------------------------------------
   الصفحة كانت بلا دالة أصلاً: admin/users.html موجودة، ولا مفتاح لها في
   PAGES ولا دالة تبنيها — فتُفتح فارغة. وكانت تُحمّل admin/users.js وهو
   نسخة قديمة كاملة من app.js (٦٣٥ كيلوبايت) تُحمَّل بعده فتلغي دواله.

   لا شيء جديد هنا: personTable و USER_ROLES و userForm و createAuthUser
   كلها قائمة وتعمل — ينقص الجدول الذي يجمعها.
   ========================================================================= */
/* =========================================================================
   بطاقة المستخدم — عرض كامل وتعديل
   -------------------------------------------------------------------------
   صفوف الجدول كانت بلا نقر: البيانات تُعرض مبتورة في أعمدة، ومن أراد
   البقية أو التعديل لم يجد له سبيلاً. userForm للتعديل موجودة أصلاً،
   وينقص عرضٌ يجمع كل الحقول قبلها.
   ========================================================================= */
/* =========================================================================
   بطاقة الحساب في الشريط العلوي
   -------------------------------------------------------------------------
   كانت عرضاً جامداً: اسم وبريد ودور بلا نقر، فمن أراد ملفّه لم يجد سبيلاً.
   تُربط هنا لا في ملفات HTML الستة عشر، فالربط واحد يكفيها كلّها.
   ========================================================================= */
window.myProfile = function () {
  const u = (STATE && STATE.user) || {};
  const uid = String(u.uid || u.id || "");
  const mail = String(u.email || "").toLowerCase();

  /* الحساب قد يُسجَّل بمعرّف Auth أو بمعرّف المستند — يُلتمس بالاثنين ثم بالبريد */
  const rec = (cur("users") || []).find(x =>
    String(x.uid || "") === uid || String(x.id) === uid ||
    (mail && String(x.email || "").toLowerCase() === mail));

  if (rec) { window.userView(rec.id); return; }

  /* لا مستند: تُعرض بيانات الجلسة بدل رسالة خطأ لا تفيد */
  /* الدور بمستواه: «مدير المسجد» لا «مدير» — الفرق بينهما صلاحيّات */
  const role = roleTitle(u) || (USER_ROLES.find(r => r.k === u.role) || {}).h || u.role || "—";
  openModal(u.name || "حسابي", role,
    `<div class="uv">
      <div class="uv-top">
        <span class="uv-avatar">${esc((u.name || "؟").trim()[0] || "؟")}</span>
        <div class="uv-id"><strong>${esc(u.name || "—")}</strong>
        <span class="pt-badge on">فعال</span></div>
      </div>
      <div class="uv-body">
        <div class="uv-row"><span>الدور</span><strong>${esc(role)}</strong></div>
        ${u.email ? `<div class="uv-row"><span>البريد</span>
          <strong dir="ltr">${esc(u.email)}</strong></div>` : ""}
      </div>
      <div class="note-card" style="margin-top:12px"><p>حسابك غير مرتبط بسجل في
      «المستخدمون والحسابات»، فلا تظهر بياناته كاملة. أبلغ الإدارة لربطه.</p></div>
    </div>`,
    '<button class="btn btn-ghost" data-action="close-modal">إغلاق</button>');
};

/* =========================================================================
   صورة الحساب في الشريط العلوي
   -------------------------------------------------------------------------
   applyUserToTopbar في auth.js تضع الحرف الأول من الاسم فقط:
     avEl.textContent = initials(ctx.name);
   ولا تقرأ حقل photo أصلاً، فالصورة تُحفظ ولا تظهر. وهي تعمل قبل تحميل
   المستخدمين من قاعدة البيانات، فلا سبيل لها إلى الصورة وقتها.

   تُقرأ هنا بعد اكتمال التحميل، وتُعاد عند كل رسم لأن مغادرة الصفحة
   قد تُعيد بناء الشريط.
   ========================================================================= */
window.refreshTopbarPhoto = function () {
  const av = document.querySelector(".user-chip .avatar");
  if (!av) return;

  const u = (STATE && STATE.user) || {};
  const uid = String(u.uid || u.id || "");
  const mail = String(u.email || "").toLowerCase();

  const rec = (cur("users") || []).find(x =>
    String(x.uid || "") === uid || String(x.id) === uid ||
    (mail && String(x.email || "").toLowerCase() === mail));

  const photo = (rec && rec.photo) || u.photo || "";

  if (!photo) {
    /* لا صورة: يبقى الحرف الأول كما وضعته auth.js */
    if (av.querySelector("img")) {
      av.innerHTML = "";
      av.textContent = (typeof initials === "function")
        ? initials(u.name || "") : String(u.name || "؟").trim()[0] || "؟";
    }
    return;
  }

  const img = av.querySelector("img");
  if (img) { if (img.getAttribute("src") !== photo) img.setAttribute("src", photo); return; }

  av.textContent = "";
  const el = document.createElement("img");
  el.src = photo;
  el.alt = "";
  /* صورة تالفة أو رابط منقطع: يعود الحرف الأول بدل مربّع فارغ */
  el.onerror = function () {
    av.innerHTML = "";
    av.textContent = (typeof initials === "function")
      ? initials(u.name || "") : String(u.name || "؟").trim()[0] || "؟";
  };
  av.appendChild(el);
};

/* بطاقة الشريط تُرسم في HTML قبل تحميل الحساب، فتُربط بعد الإقلاع */
(function bindUserChip() {
  const tries = { n: 0 };
  const t = setInterval(function () {
    const chip = document.querySelector(".user-chip");
    if (chip && !chip.dataset.bound) {
      chip.dataset.bound = "1";
      chip.setAttribute("role", "button");
      chip.setAttribute("tabindex", "0");
      chip.setAttribute("title", "ملفي الشخصي");
      chip.addEventListener("click", function () { window.myProfile(); });
      window.refreshTopbarPhoto();
      chip.addEventListener("keydown", function (e) {
        if (e.key === "Enter" || e.key === " ") { e.preventDefault(); window.myProfile(); }
      });
      clearInterval(t);
      return;
    }
    if (++tries.n > 60) clearInterval(t);   /* ثلاثون ثانية ثم يتوقف */
  }, 500);
})();

/* =========================================================================
   اعتماد الحساب من بطاقته
   -------------------------------------------------------------------------
   كان الاعتماد في شاشة الطلبات وحدها، وهي تشترط الحقل selfSignup:
     .filter(u => u && u.selfSignup && u.active === false)
   فالحساب الذي تُنشئه الإدارة لا يحمله، ولا يظهر في الطلبات، ولا سبيل
   لاعتماده — يبقى «بانتظار الاعتماد» أبداً ولا يستطيع صاحبه الدخول.
   ========================================================================= */
/* ترجيحُ طالبٍ لاسمٍ كتبه وليُّ الأمر: رقمُ الهوية يحسم، ثمّ المطابقةُ
   التامّة للاسم، ثمّ تطابقُ الاسم الأوّل والأخير. */
function matchKid(k) {
  if (!k || !k.name) return null;
  const list = (cur("students") || []).filter(x => x && x.status !== "متوقف");

  if (k.idNo) {
    const byId = list.find(x => String(x.idNo || "") === String(k.idNo));
    if (byId) return byId;
  }

  const norm = t => String(t || "").replace(/\s+/g, " ").trim();
  const exact = list.find(x => norm(x.name) === norm(k.name));
  if (exact) return exact;

  /* الأوّل والأخير: «محمد أحمد السالم» يطابق «محمد السالم» */
  const p = norm(k.name).split(" ").filter(Boolean);
  if (p.length >= 2) {
    const first = p[0], last = p[p.length - 1];
    const near = list.filter(x => {
      const q = norm(x.name).split(" ").filter(Boolean);
      return q.length >= 2 && q[0] === first && q[q.length - 1] === last;
    });
    /* واحدٌ فقط يُرجَّح: التعدّدُ التباسٌ تحسمه الإدارة */
    if (near.length === 1) return near[0];
  }
  return null;
}

/* =========================================================================
   منتقي أبناء وليّ الأمر
   -------------------------------------------------------------------------
   كالمنتقي في الجوائز: بحثٌ وتصفيةٌ لأن القائمة قد تبلغ مئات، والمختارُ
   يبقى ظاهراً وإن صُفّيت القائمة عنه — فمن اختار ابناً ثمّ بدّل الحلقة
   لا يفقد اختياره بلا أثر.
   ========================================================================= */
const USK = { q: "", circle: "", picked: [] };

window.usKidFilter = function (v) { USK.circle = String(v || ""); usKidRender(); };
window.usKidSearch = function (v) { USK.q = String(v || ""); usKidRender(); };

window.usKidPick = function (id, on) {
  const i = USK.picked.indexOf(String(id));
  if (on && i === -1) USK.picked.push(String(id));
  if (!on && i > -1) USK.picked.splice(i, 1);
  usKidRender();
};

function usKidList() {
  let l = (cur("students") || []).filter(x => x && x.status !== "متوقف");
  if (USK.circle) l = l.filter(x => String(x.circleId) === String(USK.circle));
  if (USK.q) l = l.filter(x => String(x.name || "").indexOf(USK.q) > -1);
  return l;
}

function usKidRender() {
  const box = document.getElementById("usKidBox");
  const cnt = document.getElementById("usKidCount");
  if (!box) return;

  const list = usKidList();
  const shown = new Set(list.map(x => String(x.id)));

  /* المختارون خارج التصفية يُلحقون آخراً موسومين */
  const extra = USK.picked
    .filter(id => !shown.has(id))
    .map(id => (cur("students") || []).find(x => String(x.id) === String(id)))
    .filter(Boolean);

  box.innerHTML = (list.concat(extra).map(st => {
    const on = USK.picked.indexOf(String(st.id)) > -1;
    const out = !shown.has(String(st.id));
    return `<label class="pick${on ? " on" : ""}${out ? " out" : ""}"
        title="${out ? "خارج التصفية الحالية" : esc(st.circle || "")}">
        <input type="checkbox"${on ? " checked" : ""}
          onchange="window.usKidPick('${jsAttr(st.id)}',this.checked)">
        <span>${esc(st.name || "—")}</span></label>`;
  }).join("")) || '<span class="muted">لا طلاب</span>';

  if (cnt) {
    cnt.textContent = USK.picked.length
      ? toArabicDigits(USK.picked.length) + " ابناً"
      : "لم يُختر أحد";
  }
}

function canApproveUsers() {
  const r = ((STATE && STATE.user) || {}).role || "";
  return r === "admin" || r === "owner" || isMgrRole(r);
}

window.userApprove = function (id) {
  if (!canApproveUsers()) { showToast("الاعتماد للإدارة", "warn"); return; }
  const u = (DB.users || []).find(x => String(x.id) === String(id));
  if (!u) { showToast("لم يُعثر على الحساب", "warn"); return; }

  const roles = assignableRoles().map(r =>
    `<option value="${esc(r.k)}"${(u.requestedRole || u.role) === r.k ? " selected" : ""}>${esc(r.h)}</option>`).join("");

  /* أبناءُ وليّ الأمر المطلوب ربطُهم: يُقترح لكلٍّ طالبٌ يطابقه، وتُراجع
     الإدارة. وبلا هذا الربط يدخل الحسابُ ولا يجد شيئاً. */
  const kidsReq = Array.isArray(u.kidsRequested) ? u.kidsRequested : [];
  const kidsBlock = kidsReq.length ? `
    <div class="field full" style="margin-top:6px">
      <div class="fld-sep">أبناؤه — اربط كلّاً بطالبه</div></div>
    ${kidsReq.map((k, i) => {
      const guess = matchKid(k);
      return `<div class="field full">
        <label>${esc(k.name)}${k.idNo ? " · " + esc(k.idNo) : ""}</label>
        <select id="ua_kid${i}">
          <option value="">— لم يُربط —</option>
          ${(cur("students") || []).filter(x => x.status !== "متوقف").map(x =>
            `<option value="${esc(x.id)}"${
              guess && String(guess.id) === String(x.id) ? " selected" : ""}>${
              esc(x.name)}${x.circle ? " · " + esc(x.circle) : ""}</option>`).join("")}
        </select>
        ${guess ? `<small style="font-size:11px;color:var(--brand-dark)">
          رُجّح: ${esc(guess.name)}${guess.circle ? " · " + esc(guess.circle) : ""}</small>`
          : `<small style="font-size:11px;color:#a8302f">
          لم يُعثر على مطابقٍ — اختر يدوياً</small>`}
      </div>`;
    }).join("")}` : "";

  openModal("اعتماد الحساب", u.name || "",
    `<div class="form-grid">
       <div class="field full"><label>الدور</label>
         <select id="ua_role">${roles}</select></div>
       ${kidsBlock}
     </div>
     ${noteCard(`بعد الاعتماد يصير الحساب فعّالاً ويستطيع
       <strong>${esc(u.name || "صاحبه")}</strong> الدخول فوراً بالدور المختار.` +
       (kidsReq.length ? `<br>ومن لم تربطه لن يراه.` : ""))}`,
    `<button class="btn btn-primary" onclick="window.userApproveDo('${jsAttr(id)}')">اعتماد</button>
     <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
};

window.userApproveDo = function (id) {
  const u = (DB.users || []).find(x => String(x.id) === String(id));
  if (!u) return;

  const wanted = val("#ua_role") || u.requestedRole || u.role || "student";

  /* الحارس في الدالة لا في القائمة: ترشيح الخيارات لا يمنع نداءها،
     ومنح owner تجاوزٌ لكلّ حصرٍ في النظام. */
  if (wanted === "owner" && !isTopAdmin()) {
    showToast("دور المالك لا يمنحه إلا مالكٌ قائم", "warn"); return;
  }
  if (!canEditUser(u)) {
    showToast("حساب المالك لا يُعدَّل إلا من مالك", "warn"); return;
  }

  /* منح دور المالك حركةٌ مصيرية: تُرصد بنصٍّ صريح لا كتعديل حقلٍ عاديّ */
  if (wanted === "owner" && u.role !== "owner") {
    try {
      const me = (STATE && STATE.user) || {};
      const rec = {
        id: "lg" + Date.now() + "-own",
        ts: Date.now(), byUid: String(((STATE && STATE.user) || {}).uid || ""), act: "update", coll: "users", collAr: "المستخدمون",
        docId: String(u.id), subject: u.name || "",
        by: me.name || me.email || "—", role: logRoleAr(me.role),
        changes: [{ k: "role", h: "الدور", from: u.role || "—", to: "مالك النظام" }],
        text: "منح " + (logRoleAr(me.role) || "") + " (" + (me.name || "—") +
              ") دورَ مالك النظام لـ(" + (u.name || "") + ")"
      };
      if (!Array.isArray(DB.auditLog)) DB.auditLog = [];
      DB.auditLog.push(rec);
      const db = typeof FDB === "function" ? FDB() : null;
      if (db) db.collection("auditLog").doc(rec.id).set(rec).catch(e => sideFail("auditLog", e));
    } catch (e) {}
  }

  /* ربطُ الأبناء عند الاعتماد: بدونه يدخل وليُّ الأمر ولا يجد شيئاً */
  if (Array.isArray(u.kidsRequested) && u.kidsRequested.length) {
    const picked = [];
    u.kidsRequested.forEach((k, i) => {
      const sel = val("#ua_kid" + i);
      if (sel) picked.push(String(sel));
    });
    u.studentIds = picked;
    if (picked.length === 1) u.studentId = picked[0];
    u.kidsLinkedAt = Date.now();

    if (!picked.length) {
      showToast("لم تُربط أبناؤه — سيدخل ولا يجد شيئاً", "warn");
    }
  }

  u.role = wanted;
  u.active = true;
  u.pending = false;
  /* المنشأةُ المطلوبةُ تُنشأ ويُسنَد إليها كما في شاشة الطلبات (٤٣٢) */
  try { urqApplyFacility(u); } catch (e) { console.warn("userApprove facility:", e); }
  u.approvedAt = Date.now();
  u.approvedBy = ((STATE && STATE.user) || {}).email || "";
  delete u.selfSignup;          /* يخرج من قائمة الطلبات بعد البتّ */
  delete u.requestedRole;
  /* الاعتمادُ إجراءٌ صريحٌ يُسنِد المنشأة — يُعلَن لحارس الارتباط (٤٣٢) */
  window.linkChange(() => persistSet("users", u));

  /* سجلّا المعلّم والطالب يُنشآن هنا كما في مسار الطلبات، وإلا صار
     الحساب فعّالاً بلا سجلٍّ يربطه بحلقة أو خطة. */
  try { if (typeof syncTeacherRecord === "function") syncTeacherRecord(u); } catch (e) {}
  try { if (typeof syncStudentRecord === "function") syncStudentRecord(u); } catch (e) {}

  closeModal();
  showToast("اعتُمد حساب " + (u.name || "") + " — يستطيع الدخول الآن", "success");
  mount();
};

window.userReject = function (id) {
  if (!canApproveUsers()) return;
  const u = (DB.users || []).find(x => String(x.id) === String(id));
  if (!u) return;

  openModal("رفض الحساب", u.name || "",
    noteCard(`سيبقى حساب <strong>${esc(u.name || "")}</strong> موقوفاً فلا يستطيع الدخول.
      لا يُحذف، ويمكن اعتماده لاحقاً.`),
    `<button class="btn btn-danger" onclick="window.userRejectDo('${jsAttr(id)}')">رفض</button>
     <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
};

window.userRejectDo = function (id) {
  const u = (DB.users || []).find(x => String(x.id) === String(id));
  if (!u) return;
  u.active = false;
  u.pending = false;
  u.rejectedAt = Date.now();
  delete u.selfSignup;
  persistSet("users", u);
  closeModal();
  showToast("رُفض الحساب", "info");
  mount();
};

window.userView = function (id) {
  const u = (cur("users") || []).find(x => String(x.id) === String(id));
  if (!u) { showToast("لم يُعثر على المستخدم", "warn"); return; }

  /* الدور بمستواه: «مدير المسجد» لا «مدير» — الفرق بينهما صلاحيّات */
  const role = roleTitle(u) || (USER_ROLES.find(r => r.k === u.role) || {}).h || u.role || "—";
  const login = u.email || u.loginEmail ||
    (u.username ? u.username + "@mirath.id" : "");

  /* أسماء المنشآت من معرّفاتها — المعرّف وحده لا يقول شيئاً للقارئ */
  const facName = fid => {
    const f = cur("complexes").concat(cur("mosques"))
      .find(x => String(x.id) === String(fid));
    return f ? (f.name || "") : "";
  };

  const row = (label, val, dir) => val
    ? `<div class="uv-row"><span>${esc(label)}</span>
       <strong${dir ? ' dir="ltr"' : ""}>${esc(val)}</strong></div>`
    : "";

  const pending = u.pending || (u.active === false && !u.approvedAt);
  const active = u.active !== false;

  openModal(u.name || "المستخدم", role,
    `<div class="uv">
      <div class="uv-top">
        <span class="uv-avatar">${personAvatar(u)}</span>
        <div class="uv-id">
          <strong>${esc(u.name || "—")}</strong>
          <span class="pt-badge ${pending ? "off" : active ? "on" : "off"}">
            ${pending ? "بانتظار الاعتماد" : active ? "فعال" : "متوقف"}</span>
        </div>
      </div>

      <div class="uv-body">
        ${row("الدور", role)}
        ${row("بريد الدخول", login, 1)}
        ${row("رقم الهوية", u.username, 1)}
        ${row("الجوال", u.phone, 1)}
        ${row("الجنس", u.gender)}
        ${row("المجمع", facName(u.complexId))}
        ${row("المسجد", facName(u.mosqueId))}
        ${row("التصنيف", u.category)}
        ${row("تاريخ الإنشاء", u.createdAt
            ? new Date(u.createdAt).toLocaleDateString("ar-EG") : "")}
        ${row("اعتمده", u.approvedBy)}
        ${row("ملاحظات", u.note)}
      </div>

      ${login ? "" : `<div class="note-card" style="margin-top:12px">
        <p>لا بريد دخول لهذا الحساب، فلا يستطيع تسجيل الدخول. 
        أضِف بريداً أو رقم هوية من التعديل.</p></div>`}
    </div>`,

    `${pending && canApproveUsers() ? `<button class="btn btn-primary"
        onclick="window.userApprove('${jsAttr(u.id)}')">اعتماد الحساب</button>
       <button class="btn btn-danger" onclick="window.userReject('${jsAttr(u.id)}')">رفض</button>` : ""}
     <button class="btn btn-${pending ? 'ghost' : 'primary'}" onclick="window.userForm('${jsAttr(u.id)}')">
       تعديل البيانات</button>
     <button class="btn btn-ghost" data-action="close-modal">إغلاق</button>`);
};

function adminUsers() {
  const list = cur("users");

  const roleName = u => (USER_ROLES.find(r => r.k === u.role) || {}).h || (u.role || "—");

  /* بريد الدخول: الحقيقي إن وُجد، وإلا الاصطناعي من رقم الهوية */
  const loginOf = u => u.email || u.loginEmail ||
    (u.username ? u.username + "@mirath.id" : "");

  return personTable({
    list, title: "المستخدمون والحسابات", showCount: true,
    toolbar: "add", addLabel: "إضافة مستخدم", addAction: "modal-user",
    searchHint: "إبحث بالاسم أو البريد", actionsPanel: true,
    empty: "لا حسابات بعد. أضِف مستخدماً ليُنشأ له حساب دخول.",
    cols: [
      colPhoto(),
      /* الاسم زرّ يفتح البطاقة — أقرب ما تصل إليه يد القارئ */
      { h: "الاسم", cell: u => `<td class="pt-name"><button class="uv-link"
          onclick="window.userView('${jsAttr(u.id)}')">${esc(u.name || "—")}</button></td>` },
      colState(),
      { h: "الدور", cell: u => `<td>${esc(roleName(u))}</td>` },
      { h: "بريد الدخول", cell: u => {
          const m = loginOf(u);
          return `<td dir="ltr" style="font-size:12px">${m ? esc(m)
            : '<span class="muted">بلا حساب دخول</span>'}</td>`;
        } },
      { h: "رقم الهوية", cell: u => `<td dir="ltr" class="pt-num">${esc(u.username || "—")}</td>` },
      { h: "الحالة", cell: u => {
          /* الحساب المعلّق ينتظر اعتماد الإدارة، ولا يستطيع الدخول */
          if (u.pending || (u.active === false && !u.approvedAt))
            return '<td><span class="pt-badge off">بانتظار الاعتماد</span></td>';
          return `<td><span class="pt-badge on">معتمد</span></td>`;
        } },
      colPhone(),
      { h: "", cell: u => `<td class="pt-actions">
          <button class="row-btn" onclick="window.userView('${jsAttr(u.id)}')"
            title="عرض البيانات">${ic("eye", 15)}</button>
          <button class="row-btn" onclick="window.userForm('${jsAttr(u.id)}')"
            title="تعديل">${ic("pen", 15)}</button>
          ${(u.pending || (u.active === false && !u.approvedAt)) && canApproveUsers()
            ? `<button class="row-btn ok" onclick="window.userApprove('${jsAttr(u.id)}')"
                title="اعتماد الحساب">${ic("check", 15)}</button>` : ""}</td>` }
    ]
  });
}

/* =========================================================================
   مدراءُ المساجد في عين مدير المجمّع: مساجدُ مجمّعِه وحدَها
   -------------------------------------------------------------------------
   «أكِّد أنّ مدراء المساجد الذين عنده يكونون التابعين للمجمّع الذي هو
   مديرُه فقط.»

   والقراءةُ المصفّاة (cur) كانت تُبقي في القائمة كلَّ دورٍ إداريٍّ في
   نطاقه: نفسَه، ومديرَ مجمّعٍ آخرَ يشاركه المجمّع، ومن أُسنِد إلى المجمّع
   كلِّه لا إلى مسجدٍ منه. فيُحصر هنا صراحةً — لا على النطاق وحده:
     • الدورُ مديرُ مسجد (أو «مشرف» القديم الذي يُقرأ مديرَ مسجد)
     • ومسجدُه من مساجد مجمّعِ مدير المجمّع
   ولا يُمَسّ حسابٌ ولا نطاق: هذا عرضٌ لا كتابة.
   ========================================================================= */
function cxMgrMosqueIds() {
  const me = (STATE && STATE.user) || {};
  const cxs = [];
  (typeof userScopeIds === "function" ? userScopeIds(me) : []).forEach(k => {
    const p = String(k).split(":");
    if (p[0] === "complex" && p[1]) cxs.push(String(p[1]));
  });
  if (me.complexId && cxs.indexOf(String(me.complexId)) < 0) cxs.push(String(me.complexId));
  if (Array.isArray(me.complexIds)) me.complexIds.forEach(c => {
    if (c && cxs.indexOf(String(c)) < 0) cxs.push(String(c)); });
  return (Array.isArray(DB.mosques) ? DB.mosques : [])
    .filter(m => m && cxs.indexOf(String(m.complexId || "")) > -1)
    .map(m => String(m.id));
}
function cxMgrOwnsMosqueMgr(u) {
  if (!u || !isMosqueMgr(u.role)) return false;
  const me = (STATE && STATE.user) || {};
  const myId = String(me.id || me.uid || "");
  if (myId && (String(u.id) === myId || String(u.uid || "") === myId)) return false;
  const mine = cxMgrMosqueIds();
  if (!mine.length) return false;
  const theirs = [];
  if (u.mosqueId) theirs.push(String(u.mosqueId));
  (Array.isArray(u.mosqueIds) ? u.mosqueIds : []).forEach(x => theirs.push(String(x)));
  (typeof userScopeIds === "function" ? userScopeIds(u) : []).forEach(k => {
    const p = String(k).split(":");
    if (p[0] === "mosque" && p[1]) theirs.push(String(p[1]));
  });
  return theirs.some(x => mine.indexOf(x) > -1);
}

function adminSupervisors() {
  /* الفترةُ المعروضةُ تحصر القائمة إن كانت فترةً تبدأ خالية */
  let list = trmSupsIn(cur("users").filter(u => isMgrRole(u.role)));
  /* ومديرُ المجمّع لا يرى إلّا مدراءَ مساجد مجمّعِه */
  const _r = ((STATE && STATE.user) || {}).role || "";
  if (isComplexMgr(_r)) list = list.filter(cxMgrOwnsMosqueMgr);
  return personTable({
    list, title: "المشرفين / ات", showCount: true,
    toolbar: "add", addLabel: "إضافة مشرف", addAction: "modal-user",
    searchHint: "إبحث عن مشرف", actionsPanel: true,
    /* النقرُ على الصفّ يفتح بطاقةَ الحساب — كانت الصفحةُ بلا مدخلٍ إلى
       التفاصيل أصلاً، فلا بطاقةَ ولا تعديلَ إلا من صفحةِ المستخدمين. */
    rowPanel: "panel-user",
    empty: "المشرف هو مستخدم دوره «مشرف». أضِفه من صفحة المستخدمون والحسابات.",
    cols: [ colPhoto(), colName(), colState(),
      { h: "عدد الطلاب/ات", cell: p2 => `<td class="pt-num">${cur("students").filter(st => String(st.supervisorId) === String(p2.id)).length}</td>` },
      { h: "عدد الحلقات",  cell: p2 => `<td class="pt-num">${cur("circles").filter(c => String(c.supervisorId) === String(p2.id)).length}</td>` },
      { h: "الجنس", cell: p2 => `<td>${esc(p2.gender || "ذكر")}</td>` },
      colPhone()
    ]
  });
}

