window.examTab = function (t) { EXAM_STATE.tab = t; EXAM_STATE.kpi = ""; mount(); };
window.examKpi = function (k) { EXAM_STATE.kpi = EXAM_STATE.kpi === k ? "" : k; mount(); };
window.examSearch = function (v) {
  EXAM_STATE.q = String(v || "").trim();
  document.querySelectorAll("#examGrid .ex-card").forEach(c => {
    c.style.display = !EXAM_STATE.q || (c.dataset.name || "").indexOf(EXAM_STATE.q) > -1 ? "" : "none";
  });
};
window.examSize = function (n) { EXAM_STATE.size = Number(n) || 15; mount(); };
/* =========================================================================
   فتح بطاقات لوحة الاختبارات
   -------------------------------------------------------------------------
   كانت الدالة سطراً واحداً يُظهر إشعاراً «لم تُسجَّل اختبارات بعد» ثم يقف،
   فتبدو كل بطاقات اللوحة معطّلة. وأسوأ من التعطّل أن الإشعار يوحي بأن
   العلّة في البيانات، والزرّ أصلاً غير موصول بشيء.

   الوجهات كلها شاشات قائمة: الرصد وسجل الاختبارات وبنك الأسئلة.
   ========================================================================= */
window.examOpen = function (kind, id) {
  /* كانت تُظهر إشعاراً «لم تُسجَّل اختبارات بعد» ثم تقف، فتبدو كل بطاقات
     اللوحة معطّلة — والإشعار يلوم البيانات والزرّ أصلاً غير موصول. */
  const DEST = {
    exam:    "exams-record",
    student: "exams-record",
    circle:  "exams-record",
    fac:     "exams-record",
    part:    "exams-sheet",
    pass:    "exams-log",
    fail:    "exams-log",
    log:     "exams-log"
  };

  const dest = DEST[kind];
  if (dest) { go(dest); return; }
  showToast("لا شاشة مرتبطة بهذا الزر بعد", "warn");
};

/* بطاقة مؤشر: التسمية والأيقونة يمين، الرقم في مربّع ملوّن يسار — والكل زر */
function exKpi(label, val, colour, tint, icon, key) {
  const on = EXAM_STATE.kpi === key;
  return `<button type="button" class="ex-kpi${on ? " on" : ""}" style="--c:${colour};--t:${tint}"
    onclick="window.examKpi('${key}')" title="تصفية حسب ${esc(label)}">
      <span class="ex-kpi-num">${val}</span>
      <span class="ex-kpi-lab">${esc(label)}${EXAM_ICONS[icon]}</span>
    </button>`;
}
function exMini(label, val, icon, tone) {
  return `<button type="button" class="ex-mini${tone ? " " + tone : ""}" onclick="window.examOpen('${icon}')">
    <span class="ex-mini-l">${esc(label)}</span><span class="ex-mini-v">${val}</span></button>`;
}

