/* =========================================================================
   سجل اختبارات الطلاب / ات — تقرير لطالب بعينه
   القوائم متسلسلة: المنشأة تحصر الحلقات، والحلقة تحصر الطلاب.
   ========================================================================= */
const LOG_STATE = { fac: "", circle: "", student: "" };

function logCircles() {
  const all = cur("circles");
  if (!LOG_STATE.fac) return all;
  return all.filter(c => String(c.mosqueId) === LOG_STATE.fac || String(c.complexId) === LOG_STATE.fac);
}
function logStudents() {
  const all = cur("students");
  if (LOG_STATE.circle) return all.filter(x => String(x.circleId) === LOG_STATE.circle);
  const ids = logCircles().map(c => String(c.id));
  return LOG_STATE.fac ? all.filter(x => ids.indexOf(String(x.circleId)) > -1) : all;
}
function logExams() {
  const ex = cur("exams") || [];
  if (LOG_STATE.student) return ex.filter(e => String(e.studentId) === LOG_STATE.student);
  const ids = logStudents().map(x => String(x.id));
  return ex.filter(e => ids.indexOf(String(e.studentId)) > -1);
}

window.logPick = function (what, v) {
  if (what === "fac")     { LOG_STATE.fac = v; LOG_STATE.circle = ""; LOG_STATE.student = ""; }
  if (what === "circle")  { LOG_STATE.circle = v; LOG_STATE.student = ""; }
  if (what === "student") { LOG_STATE.student = v; }
  mount();
};
window.logPrint = function () {
  if (!LOG_STATE.student) { showToast("اختر الطالب أولاً لطباعة سجله", "warn"); return; }
  window.pdfPrint();
};

function adminExamsLog() {
  const facs = cur("complexes").concat(cur("mosques"));
  const circles = logCircles(), studs = logStudents(), exams = logExams();
  const stu = cur("students").find(x => String(x.id) === LOG_STATE.student);

  const teachers = new Set(exams.map(e => String(e.examinerId)).filter(Boolean));
  const circleIds = new Set(exams.map(e => String(e.circleId)).filter(Boolean));

  const dates = exams.map(e => e.date).filter(Boolean).sort();
  const today = new Date().toISOString().slice(0, 10).replace(/-/g, "/");

  const CH  = '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M6 9l6 6 6-6"/></svg>';
  const CAL = '<svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M8 3v4M16 3v4"/></svg>';
  const PDFI= '<svg viewBox="0 0 32 32" width="24" height="24" fill="none"><path d="M7 3.6h11.4L25 10.2V27a1.4 1.4 0 01-1.4 1.4H7A1.4 1.4 0 015.6 27V5A1.4 1.4 0 017 3.6z" fill="#fff" stroke="#d64541" stroke-width="1.7"/><path d="M18.4 3.6V10h6.6" stroke="#d64541" stroke-width="1.7" stroke-linejoin="round"/><rect x="4" y="16.4" width="20" height="8" rx="1.6" fill="#d64541"/><text x="14" y="22.6" font-size="6" font-weight="700" fill="#fff" text-anchor="middle" font-family="Arial">PDF</text></svg>';

  const sel = (label, count, key, value, options, placeholder) => `
    <div class="lg-pick">
      <label>${esc(label)} (${count})</label>
      <div class="lg-sel">
        <select onchange="window.logPick('${key}', this.value)">
          <option value="">${esc(placeholder)}</option>
          ${options.map(o => `<option value="${o.id}"${String(o.id) === value ? " selected" : ""}>${esc(o.name || "—")}</option>`).join("")}
        </select>${CH}
      </div>
    </div>`;

  const photo = stu && stu.photo
    ? `<img src="${esc(stu.photo)}" alt="" onerror="this.replaceWith(Object.assign(document.createElement('span'),{className:'lg-initials',textContent:'${jsAttr(initials(stu.name || "?"))}'}))">`
    : `<span class="lg-initials">${stu ? esc(initials(stu.name || "?")) : "—"}</span>`;

  return `<div class="page">
    ${pageHead("سجل اختبارات الطلاب / ات", "", backArrow())}


    <div class="lg-tools">
      <button type="button" class="sh-btn pdf" onclick="window.logPrint()">تحميل${PDFI}</button>
    </div>

    <div class="lg-picks">
      ${sel("إختر المنشأة", facs.length, "fac", LOG_STATE.fac, facs, "كل المنشآت")}
      ${sel("إختر الحلقة", circles.length, "circle", LOG_STATE.circle, circles,
            LOG_STATE.circle ? "" : "الحلقات المختارة (" + circles.length + ")")}
      ${sel("إختر الطالب", studs.length, "student", LOG_STATE.student, studs, "إختر")}
    </div>

    <div class="lg-header">
      <div class="lg-logo"><img src="/logo-mark.svg" alt="" onerror="this.remove()"></div>
      <div class="lg-photo">${photo}</div>
      <div class="lg-dates">
        <strong>تاريخ بداية ونهاية التقرير</strong>
        <span>${dates.length ? esc(dates[0].replace(/-/g, "/")) : "- -"}</span>
        <span>${dates.length ? esc(dates[dates.length - 1].replace(/-/g, "/")) : today}</span>
      </div>
    </div>

    ${stu ? `<div class="lg-who">سجل الطالب: <strong>${esc(stu.name || "—")}</strong></div>` : ""}

    <div class="ex-kpis lg-kpis">
      ${exKpi("الأختبارات", exams.length,      "#9a07be", "#f1dcf6", "test", "exam")}
      ${exKpi("الحلقات",    circleIds.size,    "#cd6141", "#f8e7e3", "circ", "circle")}
      ${exKpi("المعلمين",   teachers.size,     "#16aeb3", "#e9f6ef", "stud", "student")}
    </div>

    ${exams.length ? `<div class="pt-wrap"><div class="pt-scroll"><table class="ptable rec-table">
      <thead><tr><th>التاريخ</th><th>المنهج</th><th>الدرجة</th><th>النتيجة</th><th>المُختبِر</th><th>المرحلة</th></tr></thead>
      <tbody>${exams.map(e => {
        const t = cur("teachers").find(x => String(x.id) === String(e.examinerId));
        const st2 = EXAM_STAGES.find(x => x.k === (e.stage || "await-sup"));
        return `<tr><td class="pt-num">${esc(e.date || "—")}</td><td>${esc(e.part || "—")}</td>
          <td class="pt-num">${esc(e.score == null ? "—" : e.score)}</td>
          <td>${esc(e.result || "—")}</td><td>${esc(t ? t.name : "—")}</td>
          <td>${esc(st2 ? st2.h : "—")}</td></tr>`;
      }).join("")}</tbody></table></div></div>`
    : `<div class="card"><div class="rep-empty" style="display:block;height:auto;padding:34px 0">
        <svg viewBox="0 0 24 24" width="54" height="54" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">
          <ellipse cx="10" cy="5.5" rx="7" ry="2.8"/><path d="M3 5.5v5c0 1.5 3.1 2.8 7 2.8s7-1.3 7-2.8v-5"/>
          <path d="M3 10.5v5c0 1.5 3.1 2.8 7 2.8 .6 0 1.2 0 1.8-.1"/>
          <circle cx="17.5" cy="17" r="4.6" fill="currentColor" stroke="none"/>
          <path d="M16 15.5l3 3M19 15.5l-3 3" stroke="#fff" stroke-width="1.7"/></svg>
        <span>${LOG_STATE.student ? "لا توجد اختبارات لهذا الطالب" : "اختر الطالب لعرض سجله"}</span></div></div>`}
  </div>`;
}


/* =========================================================================
   كشوف المكافآت
   ========================================================================= */
const RWD_STATE = { kind: "all", layer: "", status: "", merge: false, size: 10, sel: {} };

const RWD_KINDS = [
  { k: "all",      h: "جميع المكافآت" },
  { k: "student",  h: "مكافآت الطلاب" },
  { k: "teacher",  h: "مكافآت المعلمين" },
  { k: "manager",  h: "مكافآت المدراء" }
];
const RWD_STATUS = [
  { k: "",         h: "الكل" },
  { k: "new",      h: "جديدة" },
  { k: "progress", h: "تحت الاجراء" },
  { k: "paid",     h: "تم الصرف" },
  { k: "canceled", h: "ملغاة" }
];
const RWD_COLS = [
  { k: "person",   h: "اسم الطالب" },
  { k: "phone",    h: "رقم هاتف الطالب" },
  { k: "guardian", h: "رقم هاتف ولي أمر الطالب" },
  { k: "nameEn",   h: "الاسم بالانجليزي" },
  { k: "username", h: "اسم المستخدم" },
  { k: "email",    h: "البريد الإلكتروني" },
  { k: "birth",    h: "تاريخ الميلاد" },
  { k: "amount",   h: "المكافأة" },
  { k: "statusAr", h: "الحالة" }
];

function rwdRows() {
  let list = (cur("rewards") || []).slice();
  if (RWD_STATE.kind !== "all")  list = list.filter(r => (r.kind || "student") === RWD_STATE.kind);
  if (RWD_STATE.status)          list = list.filter(r => (r.status || "new") === RWD_STATE.status);
  if (RWD_STATE.layer)           list = list.filter(r => String(r.layerId) === RWD_STATE.layer);
  list = list.map(r => Object.assign({}, r, {
    statusAr: (RWD_STATUS.find(x => x.k === (r.status || "new")) || {}).h || "جديدة"
  }));

  /* دمج المكافآت: سطر واحد لكل شخص بمجموع مبالغه */
  if (RWD_STATE.merge) {
    const m = {};
    list.forEach(r => {
      const k = String(r.personId || r.person);
      if (!m[k]) m[k] = Object.assign({}, r, { amount: 0, _n: 0 });
      m[k].amount += Number(r.amount) || 0;
      m[k]._n++;
      m[k].id = "merge-" + k;
      m[k].statusAr = m[k]._n > 1 ? "مدمجة (" + m[k]._n + ")" : m[k].statusAr;
    });
    list = Object.values(m);
  }
  return list;
}

window.rwdKind   = function (k) { RWD_STATE.kind = k; RWD_STATE.sel = {}; mount(); };
window.rwdLayer  = function (v) { RWD_STATE.layer = v; RWD_STATE.sel = {}; mount(); };
window.rwdStatus = function (v) { RWD_STATE.status = v; RWD_STATE.sel = {}; mount(); };
window.rwdMerge  = function () { RWD_STATE.merge = !RWD_STATE.merge; RWD_STATE.sel = {}; mount(); };
window.rwdSize   = function (n) { RWD_STATE.size = Number(n) || 10; mount(); };
window.rwdToggle = function (btn, id) {
  btn.classList.toggle("on");
  const on = btn.classList.contains("on");
  if (on) RWD_STATE.sel[id] = true; else delete RWD_STATE.sel[id];
  const tr = btn.closest("tr"); if (tr) tr.classList.toggle("sel", on);
};
window.rwdToggleAll = function (btn) {
  const on = btn.classList.toggle("on");
  RWD_STATE.sel = {};
  document.querySelectorAll("#rwdBody tr[data-id]").forEach(tr => {
    const b = tr.querySelector(".pt-box");
    if (b) { b.classList.toggle("on", on); tr.classList.toggle("sel", on); }
    if (on) RWD_STATE.sel[tr.dataset.id] = true;
  });
};
const rwdSel = () => Object.keys(RWD_STATE.sel);

/* ---- تحويل الحالة ---- */
window.rwdMove = function (to) {
  const ids = rwdSel();
  if (!ids.length) { showToast("حدّد مكافأة واحدة على الأقل", "warn"); return; }
  if (RWD_STATE.merge) { showToast("أوقف «دمج المكافآت» قبل تغيير الحالة", "warn"); return; }
  const name = (RWD_STATUS.find(x => x.k === to) || {}).h || to;
  let n = 0;
  ids.forEach(id => {
    const r = (DB.rewards || []).find(x => String(x.id) === String(id));
    if (r) { r.status = to; r.statusAt = Date.now(); persistSet("rewards", r); n++; }
  });
  RWD_STATE.sel = {};
  showToast("حُوِّل " + n + " إلى: " + name, "success");
  mount();
};

window.rwdExport = function (kind) {
  const rows = rwdRows();
  if (!rows.length) { showToast("لا توجد بيانات للتصدير", "warn"); return; }
  if (kind === "print") { window.pdfPrint(); return; }
  const head = RWD_COLS.map(c => c.h);
  const body = rows.map(r => RWD_COLS.map(c => r[c.k] == null ? "" : String(r[c.k])));
  if (kind === "copy") {
    const txt = [head].concat(body).map(r => r.join("\t")).join("\n");
    if (navigator.clipboard) navigator.clipboard.writeText(txt)
      .then(() => showToast("نُسخ " + rows.length + " صفاً", "success"))
      .catch(() => showToast("تعذّر النسخ", "warn"));
    return;
  }
  const csv = "\uFEFF" + [head].concat(body).map(r => r.map(c => '"' + c.replace(/"/g, '""') + '"').join(",")).join("\n");
  const a = document.createElement("a");
  a.href = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8;" }));
  a.download = "كشوف-المكافآت-" + new Date().toISOString().slice(0, 10) + ".csv";
  document.body.appendChild(a); a.click(); a.remove();
  showToast("تم تنزيل الملف", "success");
};

function adminExamsRewards() {
  const all = rwdRows();
  const rows = all.slice(0, RWD_STATE.size);
  const facs = cur("complexes").concat(cur("mosques"));
  const total = all.reduce((n, r) => n + (Number(r.amount) || 0), 0);

  const CHK = '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="3.4" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6L9 17l-5-5"/></svg>';
  const CH  = '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M6 9l6 6 6-6"/></svg>';
  const CAL = '<svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M8 3v4M16 3v4"/></svg>';
  const PAID= '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M20 7H8a3 3 0 010-6h9v6M4 7v12a3 3 0 003 3h13V7"/><path d="M15.5 14.5l1.6 1.6 3.4-3.4"/></svg>';
  const CLK = '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3.4 2"/></svg>';
  const INFO= '<svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 11v5M12 7.6h.01"/></svg>';
  const PDFI= '<svg viewBox="0 0 32 32" width="23" height="23" fill="none"><path d="M7 3.6h11.4L25 10.2V27a1.4 1.4 0 01-1.4 1.4H7A1.4 1.4 0 015.6 27V5A1.4 1.4 0 017 3.6z" fill="#fff" stroke="#d64541" stroke-width="1.7"/><path d="M18.4 3.6V10h6.6" stroke="#d64541" stroke-width="1.7" stroke-linejoin="round"/><rect x="4" y="16.4" width="20" height="8" rx="1.6" fill="#d64541"/><text x="14" y="22.6" font-size="6" font-weight="700" fill="#fff" text-anchor="middle" font-family="Arial">PDF</text></svg>';
  const XLS = '<svg viewBox="0 0 32 32" width="23" height="23" fill="none"><path d="M9 3.6h10.4L26 10.2V27a1.4 1.4 0 01-1.4 1.4H9A1.4 1.4 0 017.6 27V5A1.4 1.4 0 019 3.6z" fill="#fff" stroke="#1c7578" stroke-width="1.7"/><path d="M19.4 3.6V10H26" stroke="#1c7578" stroke-width="1.7" stroke-linejoin="round"/><rect x="3" y="11" width="14" height="14" rx="2" fill="#1c7578"/><path d="M7 14.6l6 6.8M13 14.6l-6 6.8" stroke="#fff" stroke-width="1.9" stroke-linecap="round"/></svg>';
  const CPY = '<svg viewBox="0 0 32 32" width="23" height="23" fill="none"><rect x="5.4" y="4.6" width="9.6" height="22.8" rx="2.4" fill="#fff" stroke="#239fa3" stroke-width="1.8"/><rect x="16.4" y="4.6" width="9.6" height="22.8" rx="2.4" fill="#e7fbfc" stroke="#239fa3" stroke-width="1.8"/><path d="M25.6 15.4l4.2 4.2-6.4 6.4-4.4.4.4-4.4z" fill="#239fa3"/></svg>';

  const head = `<tr>
    <th class="pt-check"><button class="pt-box" onclick="window.rwdToggleAll(this)" aria-label="تحديد الكل">${CHK}</button></th>
    ${RWD_COLS.map(c => `<th>${esc(c.h)}</th>`).join("")}<th>إجراءات</th></tr>`;

  const body = rows.length ? rows.map(r => `<tr data-id="${r.id}">
      <td class="pt-check"><button class="pt-box" onclick="window.rwdToggle(this,'${jsAttr(r.id)}')" aria-label="تحديد">${CHK}</button></td>
      ${RWD_COLS.map(c => {
        if (c.k === "statusAr") {
          const st = r.status || "new";
          const tone = st === "paid" ? "on" : st === "progress" ? "warn" : st === "canceled" ? "off" : "new";
          return `<td><span class="rwd-badge ${tone}">${esc(r.statusAr)}</span></td>`;
        }
        if (c.k === "amount") return `<td class="pt-num">${esc(r.amount == null ? "—" : r.amount)}</td>`;
        return `<td class="${c.k === "person" ? "pt-name" : ""}">${esc(r[c.k] == null ? "—" : r[c.k])}</td>`;
      }).join("")}
      <td class="pt-actions">
        <button class="row-btn" onclick="window.rwdMove('paid')" title="تم الصرف">${ic("check", 14)}</button>
      </td></tr>`).join("")
    : `<tr><td colspan="${RWD_COLS.length + 2}" class="rep-empty">
        <svg viewBox="0 0 24 24" width="54" height="54" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">
          <ellipse cx="10" cy="5.5" rx="7" ry="2.8"/><path d="M3 5.5v5c0 1.5 3.1 2.8 7 2.8s7-1.3 7-2.8v-5"/>
          <path d="M3 10.5v5c0 1.5 3.1 2.8 7 2.8 .6 0 1.2 0 1.8-.1"/>
          <circle cx="17.5" cy="17" r="4.6" fill="currentColor" stroke="none"/>
          <path d="M16 15.5l3 3M19 15.5l-3 3" stroke="#fff" stroke-width="1.7"/></svg>
        <span>لا توجد بيانات</span></td></tr>`;

  return `<div class="page">
    ${pageHead("كشوف المكافآت", "", backArrow())}


    <div class="rwd-kinds">${RWD_KINDS.map(k =>
      `<button type="button" class="rwd-kind${RWD_STATE.kind === k.k ? " on" : ""}" onclick="window.rwdKind('${k.k}')">${esc(k.h)}</button>`).join("")}</div>

    <div class="rwd-filter">
      <div class="lg-pick">
        <label>حسب الطبقة</label>
        <div class="lg-sel"><select onchange="window.rwdLayer(this.value)">
          <option value="">الفرع (${esc(complexName(STATE.complexId) || "كل المنشآت")})</option>
          ${facs.map(f => `<option value="${f.id}"${String(f.id) === RWD_STATE.layer ? " selected" : ""}>${esc(f.name || "—")}</option>`).join("")}
        </select>${CH}</div>
      </div>
      <div class="lg-pick">
        <label>حالات للمكافاة</label>
        <div class="lg-sel"><select onchange="window.rwdStatus(this.value)">
          ${RWD_STATUS.map(x => `<option value="${x.k}"${x.k === RWD_STATE.status ? " selected" : ""}>${esc(x.h)}</option>`).join("")}
        </select>${CH}</div>
      </div>
      <button type="button" class="rwd-merge${RWD_STATE.merge ? " on" : ""}" onclick="window.rwdMerge()"
        title="يدمج مكافآت الشخص الواحد في سطر واحد بمجموع المبالغ">
        <span class="rwd-sw"><i></i></span>
        <span>دمج المكافآت</span>${INFO}
      </button>
    </div>

    <div class="rwd-title">تفاصيل المكافآت ${all.length ? `<b>(${all.length}${total ? " · " + total + " ريال" : ""})</b>` : ""}</div>

    <div class="rc-tools rwd-tools">
      <button type="button" class="rwd-btn paid" onclick="window.rwdMove('paid')">تحويل إلى تم الصرف${PAID}</button>
      <button type="button" class="rwd-btn prog" onclick="window.rwdMove('progress')">تحويل إلى تحت الاجراء${CLK}</button>
      <button type="button" class="rc-ic" onclick="window.rwdExport('print')" title="تحميل PDF">${PDFI}</button>
      <button type="button" class="rc-ic xls" onclick="window.rwdExport('csv')" title="تصدير Excel">${XLS}</button>
      <button type="button" class="rc-ic cpy" onclick="window.rwdExport('copy')" title="نسخ الكشف">${CPY}</button>
      <select class="rep-size" onchange="window.rwdSize(this.value)">
        ${[10, 25, 50, 100].map(n => `<option value="${n}"${n === RWD_STATE.size ? " selected" : ""}>${n}</option>`).join("")}
      </select>
    </div>

    <div class="pt-wrap"><div class="pt-scroll"><table class="ptable rec-table">
      <thead>${head}</thead><tbody id="rwdBody">${body}</tbody>
    </table></div></div>
  </div>`;
}


