  my:'<rect width="24" height="16" fill="#cc0001"/><rect y="2" width="24" height="2" fill="#fff"/><rect y="6" width="24" height="2" fill="#fff"/><rect y="10" width="24" height="2" fill="#fff"/><rect y="14" width="24" height="2" fill="#fff"/><rect width="12" height="9" fill="#0b585b"/>',
