/* =========================================================================
   إحصاء الخطة — يُشتقّ من الواجبات
   -------------------------------------------------------------------------
   التقارير تقرأ hifzTotal و hifzDone و revTotal... من الخطة، ولا يكتبها شيءٌ
   في النظام كلّه: صفر مواضع. فالنِّسَب أصفارٌ دائماً وشاشات التقارير
   والإحصاءات تعرض جداول فارغةً وإن عمل الطالب شهراً.

   تُشتقّ هنا من الواجبات المرصودة — مصدرٌ واحد لا نسختان تتناقضان.
   ========================================================================= */
function planTally(plan) {
  const out = { hifzTotal: 0, hifzDone: 0, revTotal: 0, revDone: 0,
                fixTotal: 0, fixDone: 0 };
  if (!plan || !plan.studentId) return out;

  const mine = asgTermOf(plan.studentId);

  mine.forEach(a => {
    const k = String(a.kind).replace("_makeup", "");
    const bucket = k.indexOf("hifz") === 0 ? "hifz"
                 : k.indexOf("fix") === 0 ? "fix"
                 : k.indexOf("rev") === 0 || k.indexOf("tilawah") === 0 ? "rev"
                 : "rev";                       /* الأنواع المخصَّصة مراجعةٌ حكماً */

    const want = Number(a.qty) || 0;
    /* المنجز: ما سُمّع فعلاً — الجلسات الجزئية بمقدارها لا بمطلوبها */
    const got = a.status === "done"
      ? (a.doneQty != null ? Number(a.doneQty) : want)
      : (Number(a.doneQty) || 0);

    out[bucket + "Total"] += want;
    out[bucket + "Done"] += got;
  });

  return out;
}

/* =========================================================================
   اختيارُ المنشآت والحلقات في التقارير (٤٢٧)
   -------------------------------------------------------------------------
   زرّا «إختر المنشأة» و«إختر الحلقة» كانا بشكل قائمةٍ منسدلة ولا يفعلان
   شيئاً، والتقريرُ يشمل الجميعَ دائماً. يفتح كلٌّ منهما الآن قائمةً
   بالخانات، ويُرشَّح التقريرُ بما يُختار. المحفوظُ هو المُستبعَد، فالأصلُ
   «الكلّ» كما كان، ويعود إليه بإعادة فتح الصفحة.
   ========================================================================= */
const REP_PICK = { fac: {}, cir: {} };
function repFacList() {
  return cur("complexes").map(x => ({ k: "c:" + x.id, n: x.name }))
    .concat(cur("mosques").map(x => ({ k: "m:" + x.id, n: x.name })));
}
function repCirOk(c) {
  if (!c || REP_PICK.cir[String(c.id)]) return false;
  const m = cur("mosques").find(x => String(x.id) === String(c.mosqueId));
  if (m && REP_PICK.fac["m:" + m.id]) return false;
  const cx = c.complexId || (m && m.complexId);
  if (cx != null && cx !== "" && REP_PICK.fac["c:" + cx]) return false;
  return true;
}
function repStuOk(st) {
  const c = cur("circles").find(x => String(x.id) === String(st && st.circleId));
  if (c) return repCirOk(c);
  /* طالبٌ بلا حلقة يظهر ما دام لا ترشيح */
  return !Object.keys(REP_PICK.fac).length && !Object.keys(REP_PICK.cir).length;
}
function repPicks(facs, cirs) {
  const fOn = repFacList().filter(f => !REP_PICK.fac[f.k]).length;
  const cOn = cur("circles").filter(repCirOk).length;
  return [
    { k: "fac", label: "إختر المنشأة", count: facs, value: "المنشآت المختارة (" + fOn + ")" },
    { k: "cir", label: "إختر الحلقة",  count: cirs, value: "الحلقات المختارة (" + cOn + ")" }
  ];
}
window.repPickOpen = function (kind) {
  const isFac = kind === "fac";
  const list = isFac ? repFacList()
    : cur("circles").map(c => ({ k: String(c.id), n: c.name, off: !repCirOk(Object.assign({}, c, { id: "\u0000" })) }));
  const hid = REP_PICK[isFac ? "fac" : "cir"];
  const rows = list.map(it => `<label class="rep-pk-row${it.off ? " off" : ""}">
      <input type="checkbox" data-rp-item="${esc(it.k)}"${hid[it.k] ? "" : " checked"}>
      <span>${esc(it.n || "—")}</span>${it.off ? `<small>منشأتُها غير مختارة</small>` : ""}</label>`).join("");
  const body = list.length
    ? `<label class="rep-pk-row rep-pk-all"><input type="checkbox"${Object.keys(hid).length ? "" : " checked"}
         onchange="document.querySelectorAll('[data-rp-item]').forEach(b => { b.checked = this.checked; })">
         <span>تحديد الكل</span></label><div class="rep-pk-list">${rows}</div>`
    : emptyState(isFac ? "لا توجد منشآت" : "لا توجد حلقات", "");
  openModal(isFac ? "إختر المنشأة" : "إختر الحلقة", "يُرشَّح التقرير بما تختاره", body,
    `<button type="button" class="btn btn-primary" onclick="window.repPickApply('${isFac ? "fac" : "cir"}')">تطبيق</button>
     <button type="button" class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
};
window.repPickApply = function (kind) {
  const boxes = Array.from(document.querySelectorAll("[data-rp-item]"));
  if (boxes.length && !boxes.some(b => b.checked)) { showToast("اختر واحداً على الأقلّ", "warn"); return; }
  const hid = {};
  boxes.forEach(b => { if (!b.checked) hid[b.dataset.rpItem] = true; });
  REP_PICK[kind === "fac" ? "fac" : "cir"] = hid;
  try { closeModal(); } catch (e) {}
  mount();
};

function repStuRows() {
  const zero = 0;
  return cur("students").filter(repStuOk).map(st => {
    const c  = cur("circles").find(x => String(x.id) === String(st.circleId)) || {};
    const t  = cur("teachers").find(x => String(x.id) === String(c.teacherId)) || {};
    const fac = cur("mosques").find(m => String(m.id) === String(c.mosqueId))
             || cur("complexes").find(m => String(m.id) === String(c.complexId)) || {};
    const pl = cur("plans").find(x => String(x.studentId) === String(st.id)) || {};
    const pr = cur("programs").find(x => String(x.id) === String(pl.programId)) || {};
    const pct = (d, tt) => tt > 0 ? Math.round((Number(d) || 0) * 100 / tt) : null;

    /* المحفوظ في الخطة إن وُجد، وإلا المشتقّ من الواجبات — والثاني هو
       الواقع، إذ لا شيء يكتب الأوّل. */
    const ty = planTally(pl);
    const hifz = Number(pl.hifzTotal) || ty.hifzTotal, hifzDone = Number(pl.hifzDone) || ty.hifzDone;
    const rev  = Number(pl.revTotal)  || ty.revTotal,  revDone  = Number(pl.revDone)  || ty.revDone;
    const fix  = Number(pl.fixTotal)  || ty.fixTotal,  fixDone  = Number(pl.fixDone)  || ty.fixDone;
    const avg  = pct(hifzDone + revDone + fixDone, hifz + rev + fix);
    /* العجزُ يُقرأ من الواجبات لا من حقلٍ مخزَّن، فلا يتناقض مع مصدره */
    const _def = deficitOf(st.id);

    const att  = (cur("attendance") || []).filter(a => String(a.studentId) === String(st.id));
    const cnt  = k => att.filter(a => a.status === k).length;
    const present = cnt("حاضر"), late = cnt("متأخر"), exc = cnt("مستأذن"), abs = cnt("غائب");

    const age = st.birth ? Math.max(0, Math.floor((Date.now() - new Date(st.birth).getTime()) / 31557600000)) : null;
    const grade = v => kpiGrade(v);

    return {
      name: st.name || "—", nameEn: st.nameEn || "--",
      facility: fac.name || "—", facType: fac.type || "مدرسة قرآنية",
      circleCat: c.category || "بدون تصنيف",
      gender: st.gender || "ذكر", nationality: st.nationality || "المملكة العربية السعودية",
      birth: st.birth || "—", age: age, username: st.username || st.email || "—",
      phone: st.phone || "—", guardianPhone: st.guardianPhone || "—",
      deficitFaces: _def.faces, deficitPages: _def.pages, deficitDays: _def.days,
      joined: st.joined || st.createdAt || "—",
      category: st.category || "بدون تصنيف",
      state: st.active === false || st.status === "متوقف" ? "متوقف" : "فعال",
      circle: c.name || "—", circleType: c.type || "حلقة تحفيظ", teacher: t.name || "—",
      circleTime: c.time || "—", circleDays: Array.isArray(c.days) ? c.days.join("، ") : (c.days || "—"),
      recitePlan: pl.reciteMode || "—", hifzStart: pl.hifzFrom || "—", revStart: pl.revFrom || "—",
      program: pr.name || "—", level: pl.level || "—", progress: avg,
      hifzPart: pl.hifzPart || "—", revPart: pl.revPart || "—",
      hifzDir: pl.hifzDir || "—", revDir: pl.revDir || "—",
      levelStart: pl.levelStart || "—", levelsDone: Number(pl.levelsDone) || zero,
      planAvg: avg, daysLeft: Number(pl.daysLeft) || zero, levelPct: pct(pl.levelDone, pl.levelTotal),
      planHifz: pct(hifzDone, hifz), planRev: pct(revDone, rev), planFix: pct(fixDone, fix),
      hifz, hifzPages: pl.hifzPages || "—", rev, revPages: pl.revPages || "—", fix,
      hifzDone, fixDone, revDone,
      recHifz: zero, recRev: zero, recFix: zero, recNone: zero, recRepeat: zero,
      pillars: zero, pillarsDone: zero, lessonsHifz: zero, lessonsRev: zero,
      qPerf: avg == null ? zero : avg, qPerfText: grade(avg),
      qHifz: pct(hifzDone, hifz) || zero, qHifzText: grade(pct(hifzDone, hifz)),
      qRev: pct(revDone, rev) || zero,   qRevText: grade(pct(revDone, rev)),
      qFix: pct(fixDone, fix) || zero,   qFixText: grade(pct(fixDone, fix)),
      errors: zero,
      attTotal: att.length, attDays: present, lateDays: late,
      absNoExcuse: abs, absExcuse: exc, attPct: pct(present, att.length),
      cardGold: zero, cardSilver: zero, cardBronze: zero, cardGreen: zero,
      cardBlue: zero, cardWhite: zero, cardYellow: zero, cardOrange: zero,
      cardRed: zero, cardBlack: zero,
      points: zero, balance: zero, rank: zero
    };
  });
}

function adminRepStudents() {
  const facs = cur("complexes").length + cur("mosques").length;
  return repRender({
    title: "تقرير الطلاب", unit: "طالب/ة", cols: REP_STU_COLS, rows: repStuRows,
    picks: repPicks(facs, cur("circles").length)
  });
}

