function repCirRows() {
  const zero = 0;
  return cur("circles").filter(repCirOk).map(c => {
    const mosque = cur("mosques").find(m => String(m.id) === String(c.mosqueId));
    const cx = cur("complexes").find(x => String(x.id) === String(c.complexId || (mosque && mosque.complexId)));
    const fac = mosque || cx || {};
    const t = cur("teachers").find(x => String(x.id) === String(c.teacherId)) || {};
    const students = cur("students").filter(st => String(st.circleId) === String(c.id));
    const plans = cur("plans").filter(pl => students.some(st => String(st.id) === String(pl.studentId)));

    const sum = (a, f) => a.reduce((x, y) => x + (Number(f(y)) || 0), 0);
    const hifz = sum(plans, x => x.hifzTotal), hifzDone = sum(plans, x => x.hifzDone);
    const fix  = sum(plans, x => x.fixTotal),  fixDone  = sum(plans, x => x.fixDone);
    const rev  = sum(plans, x => x.revTotal),  revDone  = sum(plans, x => x.revDone);
    const pct  = (d, tt) => tt > 0 ? Math.round(d * 100 / tt) : null;
    const avg  = pct(hifzDone + fixDone + revDone, hifz + fix + rev);

    const att = (cur("attendance") || []).filter(a => String(a.circleId) === String(c.id));
    const cnt = k => att.filter(a => a.status === k).length;
    const present = cnt("حاضر");
    const dates = [...new Set(att.map(a => a.date))].sort();
    const grade = v => kpiGrade(v);
    const days = Array.isArray(c.days) ? c.days : (c.days ? String(c.days).split(/[،,]/) : []);

    return {
      name: c.name || "—",
      facility: fac.name || "—",
      branch: cx ? cx.name : (fac.name || "—"),
      manager: fac.manager || "—",
      managerPhone: fac.phone || fac.managerPhone || "—",
      teacher: t.name || "—",
      time: c.time || "—",
      days: days.length ? days.join("، ") : "—",
      daysCount: days.length,
      cap: Number(c.capacity || c.max) || zero,
      type: c.type || "حلقة تحفيظ",
      category: c.category || "بدون تصنيف",
      enrolled: students.length,
      attend: present,
      attendAvg: dates.length ? Math.round(present / dates.length) : zero,
      attendPct: pct(present, att.length),
      late: cnt("متأخر"), absent: cnt("غائب"), excused: cnt("مستأذن"),
      realDays: dates.length, workDays: days.length * 4,
      lastAtt: dates.length ? dates[dates.length - 1] : "—",
      hifz, hifzDone, fix, fixDone, rev, revDone, revTotal: fixDone + revDone,
      achieve: avg, planAvg: avg,
      planHifz: pct(hifzDone, hifz), planRev: pct(revDone, rev), planFix: pct(fixDone, fix),
      recHifz: zero, recRev: zero, recFix: zero, recNone: zero, recRepeat: zero,
      levelsDone: sum(plans, x => x.levelsDone),
      programs: [...new Set(plans.map(x => x.programId).filter(Boolean))].length,
      levels: [...new Set(plans.map(x => x.level).filter(Boolean))].length,
      quality: avg == null ? zero : avg, qualityText: grade(avg),
      errors: zero, exams: zero, examStudents: zero, examParts: zero, examAvg: zero
    };
  });
}

