/* =========================================================================
   عتبات التقدير
   -------------------------------------------------------------------------
   كانت ٨٥ و ٧٠ و ٥٠ مكتوبة بخطّ اليد في أربعة مواضع، فلا تستطيع الإدارة
   تغييرها. تُقرأ الآن من الإعدادات، وتسقط على القيم الأصلية إن لم تُضبط.
   ========================================================================= */
function kpiThreshold(k, d) {
  const v = (typeof DB !== "undefined" && DB.settings) ? Number(DB.settings[k]) : NaN;
  return isFinite(v) && v > 0 && v <= 100 ? v : d;
}

function kpiGrade(v) {
  if (v == null || v === "") return "—";
  v = Number(v);
  if (!isFinite(v)) return "—";
  return v >= kpiThreshold("kpiTop", 85)  ? "ممتاز"
       : v >= kpiThreshold("kpiGood", 70) ? "جيد جداً"
       : v >= kpiThreshold("kpiFair", 50) ? "جيد" : "يحتاج متابعة";
}

/* =========================================================================
   درجة التسميع: نصّاً كانت أو رقماً
   -------------------------------------------------------------------------
   شاشة التسميع تحفظ الدرجة تقديراً نصّياً:  grade: "ممتاز"
   وتقرير «سجل التسميع» كان يقرؤها رقماً:   Number(r.grade) → NaN
   فتُفلتر كل الدرجات ويبقى عمود الأداء صفراً مهما رُصد من جلسات.

   السلّم هنا يحوّل التقدير إلى نسبة. والتقدير غير المعروف يُهمل ولا
   يُحتسب صفراً، كي لا يهبط متوسط الطالب بسبب تقدير لم نفهمه.
   ========================================================================= */
const RECITE_SCALE = {
  "ممتاز مرتفع": 98, "ممتاز": 95, "متقن": 95,
  "جيد جداً": 80, "جيد جدا": 80,
  "جيد": 65, "مقبول": 55, "ناجح": 70,
  "ضعيف": 35, "غير متقن": 40,
  "لم يسمّع": 0, "لم يسمع": 0, "راسب": 0
};

function reciteScore(r) {
  if (!r) return null;

  /* حقل score الرقمي إن وُجد، وإلا grade — وقد يكون رقماً أيضاً */
  const raw = r.score != null && r.score !== "" ? r.score : r.grade;
  const n = Number(raw);
  if (isFinite(n) && String(raw).trim() !== "") return n;

  const w = String(r.grade || "").trim();
  return RECITE_SCALE[w] != null ? RECITE_SCALE[w] : null;
}

/* =========================================================================
   فلتر الفترة في التقارير
   -------------------------------------------------------------------------
   التقارير كانت تجمع كل السجلات مهما تباعدت فتراتها، فيختلط إنجاز فصلٍ
   بفصل ويظهر متوسّط لا يصف شيئاً. الفراغ يعني «كل الفترات» عمداً — فمن
   أراد المجموع التراكمي وجده.
   ========================================================================= */
const REPT = { term: "" };

window.repTermSet = function (v) { REPT.term = String(v || ""); mount(); };

/* يُنادى من التقارير: يُرشِّح أي قائمة سجلات بالفترة المختارة */
function byTerm(list) {
  if (!REPT.term) return list || [];
  return (list || []).filter(r => inTerm(r, REPT.term));
}

/* شريط الاختيار — يُعرض فوق التقرير */
function repTermBar() {
  const terms = cur("terms") || [];
  if (terms.length < 2) return "";     /* فترة واحدة: لا معنى للفرز */

  const act = activeTerm();
  return `<div class="rep-terms">
    <span class="rep-terms-lbl">الفترة</span>
    <button type="button" class="rep-term${!REPT.term ? " on" : ""}"
      onclick="window.repTermSet('')">الكل</button>
    ${terms.map(t => `<button type="button" class="rep-term${
      String(REPT.term) === String(t.id) ? " on" : ""}"
      onclick="window.repTermSet('${jsAttr(t.id)}')">${esc(t.name)}${
      act && String(act.id) === String(t.id) ? " ●" : ""}</button>`).join("")}
  </div>`;
}

function repRecRows() {
  /* الفترة المختارة وحدها: كان التقرير يجمع كل الفترات فيختلط إنجاز
     فصلٍ بفصل ويظهر متوسّط لا يصف شيئاً. */
  const recs = byTerm(curAll("recitations"));
  return cur("students").filter(repStuOk).map(st => {
    const pl = cur("plans").find(x => String(x.studentId) === String(st.id)) || {};
    const mine = recs.filter(r => String(r.studentId) === String(st.id));
    const pct = (d, t) => t > 0 ? Math.round((Number(d) || 0) * 100 / t) : null;

    const hifz = Number(pl.hifzTotal) || 0, hifzDone = Number(pl.hifzDone) || 0;
    const rev  = Number(pl.revTotal)  || 0, revDone  = Number(pl.revDone)  || 0;
    const fix  = Number(pl.fixTotal)  || 0, fixDone  = Number(pl.fixDone)  || 0;
    const avg  = pct(hifzDone + revDone + fixDone, hifz + rev + fix);

    const att = byTerm(curAll("attendance") || []).filter(a => String(a.studentId) === String(st.id));
    const cnt = k => att.filter(a => a.status === k).length;
    const dates = att.filter(a => a.status === "حاضر").map(a => a.date).sort();
    const grade = v => kpiGrade(v);
    /* كان: Number(r.grade) — والدرجة نصّ، فتُفلتر كلها ويبقى الأداء صفراً */
    const marks = mine.map(reciteScore).filter(v => v != null);
    const perf = marks.length ? Math.round(marks.reduce((a, b) => a + b, 0) / marks.length) : null;

    return {
      student: st.name || "—", level: pl.level || "—", progress: avg,
      attDays: cnt("حاضر"), lateDays: cnt("متأخر"), excDays: cnt("مستأذن"), absDays: cnt("غائب"),
      attTotal: att.length, lastAtt: dates.length ? dates[dates.length - 1] : "—",
      hifz, hifzDone, fix, fixDone, rev, revDone, revTotal: fixDone + revDone,
      planHifz: pct(hifzDone, hifz), planRev: pct(revDone, rev),
      planFix: pct(fixDone, fix), planAvg: avg,
      lessons: mine.length,
      perf: perf == null ? 0 : perf,
      quality: avg == null ? 0 : avg, qualityText: grade(avg),
      levelsDone: Number(pl.levelsDone) || 0
    };
  });
  /* كان هنا فلتر يحذف كل طالب بلا تسميع ولا خطة ولا حضور، فإن كان
     الجميع كذلك ظهر الجدول فارغاً بلا سبب. الصفر المكتوب يُقرأ،
     والصفّ المحذوف لا يُفرّق بين «لا بيانات» و«لا طلاب». */
}

