    const r = ((STATE && STATE.user) || {}).role || "";
    /* مديرُ المجمّع وحدَه له لوحتُه بالشكل المطلوب، وغيرُه كما كان */
    if (isComplexMgr(r)) return cxMgrDashboard();
    /* ومديرُ المسجد بالشكل نفسه — والمشرفُ ومديرُ النظام كما كانا */
