/* =========================================================
   COMPLEX SELECT (الشريط العلوي)
   ========================================================= */
function renderComplexSelect() {
  const sel = document.querySelector("#orgSelect");
  if (!sel) return;

  /* =======================================================================
     غير الإداريين: منشأة واحدة لا قائمة اختيار
     -----------------------------------------------------------------------
     كان المعلم يرى قائمة منسدلة بكل مجمعات النظام ويستطيع التنقّل بينها،
     وهذا تسريب لأسماء المنشآت الأخرى وإن حُصرت بياناتها. يعرض له الآن اسم
     مسجده — أو مجمعه إن لم يُربط بمسجد — نصاً واحداً غير قابل للتغيير.
     ======================================================================= */
  const u = (STATE && STATE.user) || {};
  const role = u.role || "";
  if (role && role !== "admin" && !isMgrRole(role)) {
    const lbl = document.querySelector(".org-label");
    let name = "—";

    /* يقرأ النطاق المشتقّ لا الحقلين المفردين، فيظهر اسم المنشأة حتى لو
       لم تُملأ في حساب المستخدم ما دام ملف الطالب أو المعلم مسنَداً. */
    const ids = userScopeIds(u);
    const mqId = (ids.filter(k => k.indexOf("mosque:")  === 0)[0] || "").split(":")[1];
    const cxId = (ids.filter(k => k.indexOf("complex:") === 0)[0] || "").split(":")[1];

    if (mqId) {
      const m = (DB.mosques || []).find(x => String(x.id) === String(mqId));
      if (m) { name = m.name || "—"; if (lbl) lbl.textContent = "المسجد"; }
    }
    if (name === "—" && cxId) {
      const c = (DB.complexes || []).find(x => String(x.id) === String(cxId));
      if (c) { name = c.name || "—"; if (lbl) lbl.textContent = "المجمع"; }
    }
    if (name === "—" && lbl) lbl.textContent = "المنشأة";
    if (name === "—") sel.title = "حسابك غير مرتبط بمنشأة — راجع الإدارة";
    if (cxId) STATE.complexId = cxId;

    sel.innerHTML = `<option>${esc(name)}</option>`;
    sel.disabled = true;
    sel.classList.add("org-fixed");
    return;
  }

  /* =======================================================================
     المجمّعات المعروضة: ما يراه صاحب الجلسة لا ما في النظام
     -----------------------------------------------------------------------
     كانت القائمة تُبنى من DB.complexes رأساً، والشرط أعلاه يستثني الإداريين
     كلَّهم — فمديرُ المسجد ومديرُ المجمّع يريان في الشريط العلويّ أسماءَ
     مجمّعات النظام كلِّها، ويبدّلان بينها بنقرة.

     وهو أظهرُ تسريبٍ في النظام: يقع في الشريط الذي لا يفارق الشاشة.
     ======================================================================= */
  const cxList = (typeof cur === "function" ? cur("complexes") : DB.complexes) || [];

  if (!cxList.length) {
    sel.innerHTML = `<option>لا توجد مجمعات — أضف مجمعاً</option>`;
    STATE.complexId = null;
    return;
  }

  /* المجمّع المحفوظ إن خرج عن النطاق لا يُبقى عليه: يُبدَّل إلى أوّل ما يُرى */
  if (!STATE.complexId || !cxList.some(x => x.id == STATE.complexId)) {
    STATE.complexId = cxList[0].id;
  }

  /* مجمّعٌ واحدٌ لا قائمةَ له: نصٌّ ثابتٌ كما لغير الإداريين */
  if (cxList.length === 1) {
    sel.innerHTML = `<option>${esc(cxList[0].name || "—")}</option>`;
    sel.disabled = true;
    sel.classList.add("org-fixed");
    return;
  }

  sel.innerHTML = cxList.map(cx =>
    `<option value="${cx.id}" ${cx.id == STATE.complexId ? "selected" : ""}>${esc(cx.name)}</option>`
  ).join("");

  if (!sel.dataset.bound) {
    sel.dataset.bound = "1";
    sel.addEventListener("change", () => {
      STATE.complexId = sel.value;
      STATE.planId = null;
      renderNav(); mount();
      showToast("تم التبديل إلى " + complexName(STATE.complexId), "info");
    });
  }
}

/* =========================================================
   NAV RENDER + ROUTER
   ========================================================= */
/* =========================================================================
   شريط التنقّل السفليّ — للجوّال
   -------------------------------------------------------------------------
   القائمةُ الجانبية على الجوّال درجٌ يُفتح بزرّ، فكلُّ تنقّلٍ ضغطتان: زرُّ
   القائمة ثمّ البند. والمعلّمُ يتنقّل بين شاشاته عشراتِ المرّات في الحلقة.

   أربعةُ بنودٍ في متناول الإبهام أسفلَ الشاشة: الأكثرُ استعمالاً لكلّ دور.
   والباقي في الدرج كما كان — لا يُفقد شيء.
   ========================================================================= */
const TABBAR = {
  /* الأربعةُ التي نصّت عليها الوثيقة. و«حلقة اليوم» و«التحضير» و«التسميع»
     لم تُحذف — شاشاتُها باقيةٌ في PAGES وفي قائمة NAV.teacher، وإعادتُها
     إلى الشريط سطرٌ واحدٌ هنا. */
  teacher: [
    { id: "dashboard", label: "الرئيسية",     icon: "grid" },
    { id: "messages",  label: "المحادثات",    icon: "chat" },
    { id: "report",    label: "تقرير المعلم", icon: "report" },
    { id: "settings",  label: "الإعدادات",    icon: "settings" }
  ],
  /* النوافذُ الخمس التي نصّت عليها مواصفاتُ موقع الطالب. و«واجب اليوم»
     و«سير الخطة» لم يُحذفا — هما في القائمة الجانبية كما كانا. */
  student: [
    { id: "dashboard", label: "الرئيسية",        icon: "grid" },
    { id: "mushaf",    label: "المصحف التفاعلي", icon: "book" },
    { id: "reports",   label: "التقارير",        icon: "report" },
    { id: "store",     label: "المتجر",          icon: "gift" },
    { id: "settings",  label: "الإعدادات",       icon: "settings" }
  ],
  parent: [
    { id: "dashboard", label: "الرئيسية",        icon: "grid" },
    { id: "mushaf",    label: "المصحف التفاعلي", icon: "book" },
    { id: "reports",   label: "التقارير",        icon: "report" },
    { id: "store",     label: "المتجر",          icon: "gift" },
    { id: "settings",  label: "الإعدادات",       icon: "settings" }
  ]
};

/* القائمةُ الجانبية (Hamburger) تُخفى حيث يكون التنقّلُ بالشريط السفليّ:
   نصّت الوثيقةُ على ألّا تُستعمل للتنقّل الرئيسيّ في تطبيق المعلم. وهي
   إخفاءٌ لا حذف — الشاشاتُ كلُّها باقيةٌ وتُفتح من الشريط ومن الروابط. */
function hideSideNavFor(iface) {
  const bar = document.querySelector(".sidebar");
  const btn = document.getElementById("menuToggle");
  /* يُخفى الشريطُ متى لم يكن لواجهته بنود — وللمعلّم بنودٌ بطلبٍ صريح
     (حلقاتي · المصحف · طلبات الاختبارات · الإعدادات · الخروج) فيظهر. */
  const items = (typeof navFor === "function" ? navFor(iface) : (NAV[iface] || [])) || [];
  const off = !items.length;
  /* زرُّ الخروج في ذيل الشريط (يضعه auth.js لكلّ الأدوار) يُخفى متى صار
     الخروجُ بنداً في القائمة نفسِها — فلا يتكرّر أمام المعلّم. */
  try {
    const lo = document.getElementById("logoutBtn");
    if (lo) lo.style.display = items.some(x => x && x.act === "tchLogout") ? "none" : "";
  } catch (e) {}
  if (bar) bar.classList.toggle("nav-off", off);
  if (btn) btn.style.display = off ? "none" : "";
  try { document.body.classList.toggle("nav-off", off); } catch (e) {}
  /* وسمُ الواجهة على <body>: التنسيقُ يبني عليه ما يخصُّ واجهةً بعينها —
     كرفع الشريط العلويّ عن الطالب وحدَه دون أن يُمسّ شريطُ غيره. */
  try { document.body.setAttribute("data-iface", String(iface || "")); } catch (e) {}
}

function renderTabBar() {
  try { hideSideNavFor(STATE.iface); } catch (e) {}
  /* الشريطُ يُنشأ إن لم يكن في الصفحة: نسخةُ index.html المخزَّنةُ في
     عامل الخدمة قد تكون قديمةً بلا <nav id="tabbar">، فيختفي الشريطُ
     السفليُّ في الجوّال ولا سبيلَ إلى شاشاته. */
  let el = document.getElementById("tabbar");
  if (!el) {
    try {
      el = document.createElement("nav");
      el.id = "tabbar";
      el.className = "tabbar";
      el.setAttribute("aria-label", "التنقّل السريع");
      document.body.appendChild(el);
    } catch (e) { return; }
  }
  if (!el) return;

  const items = TABBAR[STATE.iface];
  if (!items) { el.innerHTML = ""; el.style.display = "none"; return; }

  /* ما لا شاشةَ له يُطرح: المتجرُ مثلاً قد يكون مطفأً في الإعدادات.
     وما منعته الإدارةُ في «تطبيق الطالب» يُطرح كذلك — للطالب ووليّ أمره
     وحدَهما، فلا يُمسّ شريطُ المعلّم. */
  const stu = STATE.iface === "student" || STATE.iface === "parent";
  const live = items.filter(it => PAGES[STATE.iface + "/" + it.id] &&
    (!stu || typeof stuAppOn !== "function" || stuAppOn("show." + it.id) ||
     ["dashboard", "settings"].indexOf(it.id) > -1));
  if (!live.length) { el.innerHTML = ""; el.style.display = "none"; return; }

  el.style.display = "";
  /* صنفُ المعلّم: شكلُ الشريط السفليّ المطلوب — المفعَّلُ وحدَه باسمه */
  try { el.classList.toggle("tb-teacher", STATE.iface === "teacher"); } catch (e) {}

  el.innerHTML = live.map(it =>
    `<button type="button" class="tb-item${it.id === STATE.page ? " on" : ""}"
      data-action="nav" data-page="${it.id}">
      ${ic(it.icon, 21)}<span>${esc(it.label)}</span>
    </button>`).join("");
}

/* أرقامُ المعلّم تحت اسمه في القائمة الجانبية — بطلبٍ صريح:
   عددُ حلقاته وطلابه ومساجده وتخصّصُه. والمساجدُ تُحصى من حلقاته
   لا من سجلّه، فمن له حلقاتٌ في مسجدين يرى اثنين. */
/* اسمُ البرنامج في صدر الشريط: منشأةُ المعلّم كما هي في سجلّه —
   مسجدُه، وإلا مجمّعُه، وإلا اسمُ النظام. */
function tchFacilityName() {
  try {
    const t = (typeof myTeacherRecord === "function") ? myTeacherRecord() : null;
    if (t && t.mosque) return String(t.mosque);
    if (t && t.mosqueId) {
      const m = (cur("mosques") || []).find(x => String(x.id) === String(t.mosqueId));
      if (m && m.name) return String(m.name);
    }
    const cx = (typeof complexName === "function")
      ? complexName((t && t.complexId) || (STATE && STATE.complexId)) : "";
    if (cx) return String(cx);
  } catch (e) {}
  return "ذات القرآنية";
}
window.tchFacilityName = tchFacilityName;

/* الشريطُ العلويُّ عند المعلّم: اسمُ البرنامج والتنبيهاتُ والتحضيرُ فقط —
   بطلبٍ صريح. وما عداه يُخفى له وحدَه ويعود لغيره كما كان (إخفاءٌ لا حذف). */
const TCH_TOP_HIDE = ["#menuToggle", ".org-select", "#topFilters",
                      "#btnMsg", "#btnRefresh", ".user-chip"];

function tchTopbarTrim() {
  try {
    const bar = document.querySelector(".topbar");
    if (!bar) return;
    const on = !!(STATE && STATE.iface === "teacher");
    /* الصنفُ يدفع كتلةَ الأزرار إلى أقصى اليسار، فالتنبيهاتُ يساراً بطلبٍ صريح */
    try { bar.classList.toggle("tch-top-min", on); } catch (e) {}
    /* =====================================================================
       الواجهةُ تُحفظ على الجهاز ليُطبَّق تقليمُها قبل أوّل رسم
       ---------------------------------------------------------------------
       هذا التقليمُ يجري في آخر أوّل رسم — بعد المصادقة وقراءة الملفّ
       وتحميل البيانات — فيرى المعلّمُ ثوانيَ شريطَ الإدارة كاملاً ثمّ
       يختفي أمامه. فتُحفظ واجهتُه هنا، وتقرؤها ترويسةُ index.html قبل
       أوّل رسمٍ فتضع الوسمَ، ويُخفي التنسيقُ ما سيُخفى على كلّ حال.
       والوسمُ يُنزع هنا لغير المعلّم، فلا يُحجب عن أحدٍ ما هو له.
       ===================================================================== */
    try {
      const de = document.documentElement;
      if (de) de.classList.toggle("tch-boot", on);
      localStorage.setItem("mirath_iface", on ? "teacher" : "");
    } catch (e) {}

    TCH_TOP_HIDE.forEach(sel => {
      const list = bar.querySelectorAll(sel);
      for (let i = 0; i < list.length; i++) list[i].style.display = on ? "none" : "";
    });

    let b = document.getElementById("tchBrand");
    if (!on) { if (b && b.parentNode) b.parentNode.removeChild(b); return; }
    if (!b) {
      b = document.createElement("span");
      b.id = "tchBrand";
      b.className = "tch-brand";
      /* يُدرج في الشريط نفسِه لا داخل كتلةٍ منه، فيتوسّط بينها وبين
         كتلة الأزرار بلا تراكبٍ على الشاشات الضيّقة. */
      const left = bar.querySelector(".topbar-left");
      if (left) bar.insertBefore(b, left); else bar.appendChild(b);
    }
    /* الاسمُ هو منشأةُ المعلّم لا اسمَ النظام: مسجدُه، وإلا مجمّعُه */
    b.textContent = tchFacilityName();
  } catch (e) {}
}
window.tchTopbarTrim = tchTopbarTrim;
/* زرُّ التحضير في الشريط العلويّ بجوار جرس التنبيهات — بطلبٍ صريح.
   يُركَّب للمعلّم وحدَه ويُنزع لغيره، وحالتُه تُراجَع مع كلّ رسم فيظهر
   «حضوري مسجَّل» فور التسجيل بلا إعادة تحميل. */
function tchTopCheckBtn() {
  try {
    const bar = document.querySelector(".topbar .topbar-left");
    let b = document.getElementById("tchCheckTop");

    if (!bar || !STATE || STATE.iface !== "teacher") {
      if (b && b.parentNode) b.parentNode.removeChild(b);
      return;
    }

    if (!b) {
      b = document.createElement("button");
      b.id = "tchCheckTop";
      b.type = "button";
      b.className = "icon-btn tch-top-check";
      b.onclick = function () { if (window.tchCheckIn) window.tchCheckIn(); };
      const bell = document.getElementById("btnNotif");
      if (bell && bell.parentNode === bar) bar.insertBefore(b, bell);
      else bar.insertBefore(b, bar.firstChild);
    }

    const done = (typeof tchMyAtt === "function") && !!tchMyAtt(todayISO());
    b.classList.toggle("done", done);
    b.title = done ? "حضوري مسجَّل" : "التحضير";
    b.setAttribute("aria-label", b.title);
    b.innerHTML = ic("attend", 20);
  } catch (e) {}
}
window.tchTopCheckBtn = tchTopCheckBtn;

function navWhoStats() {
  try {
    const t = (typeof myTeacherRecord === "function") ? myTeacherRecord() : null;
    if (!t) return "";

    const mine = (cur("circles") || []).filter(c => c &&
      (String(c.teacherId) === String(t.id) ||
        (Array.isArray(c.assistants) && c.assistants.indexOf(String(t.id)) > -1)));

    const kids = (cur("students") || []).filter(s => s && s.status !== "متوقف" &&
      mine.some(c => String(c.id) === String(s.circleId))).length;

    const msq = {};
    mine.forEach(c => { const m = String(c.mosqueId || ""); if (m) msq[m] = 1; });
    if (!Object.keys(msq).length && t.mosqueId) msq[String(t.mosqueId)] = 1;

    const rows = [
      ["عدد الحلقات", toArabicDigits(mine.length)],
      ["عدد الطلاب",  toArabicDigits(kids)],
      ["عدد المساجد", toArabicDigits(Object.keys(msq).length)],
      ["التخصص",      t.spec || t.qual || "—"]
    ];
    return `<div class="nav-who-bits">${rows.map(([h, v]) =>
      `<div><span>${esc(h)}</span><b>${esc(String(v))}</b></div>`).join("")}</div>`;
  } catch (e) { return ""; }
}
window.navWhoStats = navWhoStats;

function renderNav() {
  const nav = $("#nav");
  if (!nav) return;
  /* البنود التي لا يُتيحها مستواه تُخفى: من رأى زرّاً ثمّ مُنع ظنّ العطل */
  const items = navFor(STATE.iface);
  try { renderTabBar(); } catch (e) {}

  /* اسمُ المعلّم وصورتُه تحت شعار «ذات» في صدر القائمة — بطلبٍ صريح.
     والرسمُ الفعليُّ في index.html من auth.js، وفيه مثلُه. */
  let who = "";
  try {
    const u = (STATE || {}).user || {};
    const nm = String(u.name || "");
    if (STATE.iface === "teacher" && nm) {
      const t = (typeof myTeacherRecord === "function") ? myTeacherRecord() : null;
      const ph = (t && t.photo) || u.photo || "";
      who = `<div class="nav-who"><span class="nav-who-av">${
        ph ? `<img src="${esc(ph)}" alt="">` : ic("person", 26)
      }</span><strong>${esc(nm)}</strong></div>` + navWhoStats();
    }
  } catch (e) { who = ""; }

  nav.innerHTML = who + items.map(it => {
    /* العدّادُ يُنادى في حارس: دالّةٌ ترمي خطأً كانت تُسقط رسمَ القائمة
       كلِّها، فتختفي البنودُ جميعاً — والسببُ عدّادٌ في بندٍ واحد. */
    let cnt = "";
    try {
      if (it.count) cnt = `<span class="nav-count">${it.count()}</span>`;
    } catch (e) { cnt = ""; }
    /* بندٌ ينادي فعلاً لا يفتح شاشة — كتسجيل الخروج */
    if (it.act) {
      return `<button class="nav-item nav-act" onclick="window.${esc(it.act)}()">${
        ic(it.icon, 19)}<span>${esc(it.label)}</span></button>`;
    }
    return `<button class="nav-item ${it.id === STATE.page ? "active" : ""}" data-action="nav" data-page="${it.id}">${ic(it.icon, 19)}<span>${esc(it.label)}</span>${cnt}</button>`;
  }).join("");
}

/* الواجهة المسموح بها لدور الحساب — لا تُشتقّ من زر ولا من نداء يدوي */
/* =========================================================================
   فصل أدوار المجمّع عن المسجد
   -------------------------------------------------------------------------
   المواصفات تفرّق بين ستّة أدوار في مستويين:

     المجمّع: مدير — مشرف — داعم   (نطاقه: المجمّع ومساجده)
     المسجد: مدير — مشرف — داعم   (نطاقه: مسجده وحلقاته)

   وكان الدور واحداً للمستويين: admin لمدير المجمّع ومدير المسجد معاً، فمدير
   مسجدٍ يملك صلاحيات مدير المجمّع كاملة — يضيف مساجد ويعدّل حسابات غيره.

   والحلّ ليس بتغيير مفاتيح الأدوار: admin و supervisor مقروءان في سبعة عشر
   موضعاً وفي قواعد Firestore، وتغييرهما يقفل كلّ الحسابات القائمة.

   الحلّ: الدور يحدّد الوظيفة، والنطاق يحدّد المستوى. من ملفّه mosqueId فهو
   على مستوى المسجد، ومن له complexId وحده فهو على مستوى المجمّع. وهذا
   ما تقرؤه قواعد Firestore أصلاً — فيتّسق الحصر في الواجهة مع الحصر فيها.
   ========================================================================= */

/* مستوى المستخدم: system · complex · mosque */
/* =========================================================================
   نطاق المشرف — مساجدُ عدّة لا واحد
   -------------------------------------------------------------------------
   كان الحصر يقرأ mosqueId و complexId المفردين، والمشرفُ على مسجدين
   يُسجَّل على أحدهما فيرى الأوّل ولا يرى الثاني — وهو مشرفٌ عليهما.

   scopeIds[] موجودٌ في ملفّه من نموذج المستخدمين، لكنّ المرشّحات لم تكن
   تقرؤه. تُقرأ هنا مرّةً وتُشتقّ منها المساجدُ والحلقات، فيصير الحصر
   واحداً في كلّ الشاشات.
   ========================================================================= */
function myScope(u) {
  const p = u || (STATE && STATE.user) || {};
  const out = { mosques: new Set(), complexes: new Set(), circles: new Set(), open: false };

  if (isTopAdmin(p)) { out.open = true; return out; }

  /* scopeIds: "mosque:ID" أو "complex:ID" */
  (Array.isArray(p.scopeIds) ? p.scopeIds : []).forEach(k => {
    const v = String(k || "");
    if (v.indexOf("mosque:") === 0) out.mosques.add(v.slice(7));
    else if (v.indexOf("complex:") === 0) out.complexes.add(v.slice(8));
  });

  /* الحقول المفردة للتوافق مع ما سُجّل قبل التعدّد */
  if (p.mosqueId) out.mosques.add(String(p.mosqueId));
  if (p.complexId) out.complexes.add(String(p.complexId));

  /* مساجدُ المجمّعات المُسنَدة تدخل في النطاق */
  (Array.isArray(DB.mosques) ? DB.mosques : []).forEach(m => {
    if (m && out.complexes.has(String(m.complexId || ""))) out.mosques.add(String(m.id));
  });

  /* حلقاتُ ما سبق */
  (Array.isArray(DB.circles) ? DB.circles : []).forEach(c => {
    if (!c) return;
    if (out.mosques.has(String(c.mosqueId || "")) ||
        out.complexes.has(String(c.complexId || ""))) out.circles.add(String(c.id));
  });

  /* بلا إسنادٍ أصلاً: من لم يُسنَد إليه شيءٌ لا يُشرف على كلّ شيء */
  if (!out.mosques.size && !out.complexes.size) {
    out.open = (!isMgrRole(p.role) && p.role !== "donor");
  }

  return out;
}

/* هل يقع هذا السجلّ في نطاقي؟ */
function inScope(x, how) {
  const sc = myScope();
  if (sc.open) return true;
  if (!x) return false;

  if (x.mosqueId && sc.mosques.has(String(x.mosqueId))) return true;
  if (x.complexId && sc.complexes.has(String(x.complexId))) return true;
  if (how === "circle" && x.circleId && sc.circles.has(String(x.circleId))) return true;

  /* المساجدُ والمجمّعاتُ أنفسُها */
  if (x.id && sc.mosques.has(String(x.id))) return true;
  if (x.id && sc.complexes.has(String(x.id))) return true;

  /* الطالبُ بلا مسجدٍ يُنسب عبر حلقته */
  if (x.circleId && sc.circles.has(String(x.circleId))) return true;

  return false;
}

function scopeLevel(u) {
  const p = u || (STATE && STATE.user) || {};
  if (isTopAdmin(p)) return "system";           /* المالك والمدير: بلا حصر */

  /* الدورُ يحكم المستوى قبل النطاق: مديرُ المسجد الذي أُسنِد إليه
     complexId خطأً كان يُقرأ مستواه «مجمّع» فيرى مساجدَ ليست له.
     ومديرُ المجمّع لا ينزل إلى مستوى المسجد وإن حمل mosqueId. */
  if (isComplexMgr(p.role)) return "complex";
  if (p.role === "mosqueManager") return "mosque";

  if (p.mosqueId) return "mosque";
  if (p.complexId) return "complex";

  /* المشرف بلا نطاقٍ في ملفّه كان يُعدّ على مستوى النظام فيرى كلّ شيء —
     وهو عكس المقصود: من لم يُسنَد إليه شيءٌ لا يُشرف على كلّ شيء.
     يُعامَل بأضيق نطاقٍ حتى يُسنَد إليه مسجدُه أو مجمّعه. */
  if (isMgrRole(p.role) || p.role === "donor") return "mosque";

  return "system";
}





/* الاسم المعروض للدور بمستواه */
function roleTitle(u) {
  const p = u || (STATE && STATE.user) || {};
  const lvl = scopeLevel(p);
  const at = lvl === "mosque" ? "المسجد" : lvl === "complex" ? "المجمّع" : "النظام";

  const M = {
    owner: "مالك النظام",
    admin: "مدير " + at,
    complexManager: "مدير المجمّع",
    mosqueManager: "مدير المسجد",
    supervisor: "مشرف " + at,
    donor: "داعم " + at,
    teacher: "معلّم", student: "طالب", parent: "ولي أمر"
  };
  return M[p.role] || p.role || "";
}

/* =========================================================================
   ما يُتاح لكلّ مستوى
   -------------------------------------------------------------------------
   المواصفات: مدير المجمّع «يدير حسابات المشرفين والداعمين والمساجد التابعة»،
   ومدير المسجد «في نطاق مسجده وحلقاته فقط» — لا ينشئ مساجد ولا يمسّ إعدادات
   النظام.
   ========================================================================= */

/* أعمالٌ تخصّ مستوى المجمّع فما فوق.
   البرامجُ والمسيّراتُ خرجتا منها بقرار الإدارة: مديرُ المسجد يبني
   مناهجَ حلقاته ويرى مسيّرَ مسجده — ونطاقُه يحصر ما يراه في الحالين. */
const COMPLEX_ONLY = [
  "complexes",      /* إنشاء المجمّعات والمساجد */
  "mosques",
  "supervisors",    /* حسابات مدراء المساجد والداعمين */
  "users",
  "terms"           /* الفترات الدراسية للمجمّع كلّه */
];

/* أعمالٌ تخصّ مستوى النظام وحده */
const SYSTEM_ONLY = ["audit", "settings-core"];

/* =========================================================================
   ما يُمنع عن المشرف مهما اتّسع نطاقه
   -------------------------------------------------------------------------
   إدارةُ الحسابات والصلاحيات شأنُ المدير: من ملك إنشاءَ الحسابات وتعديلَ
   أدوارها ملك النظام كلَّه — يرقّي نفسه أو يفتح حساباً بصلاحيةٍ أوسع.

   وكانت "users" في COMPLEX_ONLY، فتُمنع على مستوى المسجد وحده. ومشرفُ
   المجمّع كان يراها.
   ========================================================================= */
/* ما يُمنع عن مدير المسجد والداعم مهما اتّسع نطاقهما.
   ومديرُ المجمّع أُخرج منه بقرار الإدارة: يُنشئ مدراءَ مساجده ويعدّلهم.
   وحدُّه أنه لا يُنشئ إلا في مجمّعه ولا يمنح دوراً أعلى من دوره —
   يحرسه canGrantRole أدناه، وقواعدُ Firestore تحرسه على الخادم. */
const ADMIN_ONLY = [
  "users",          /* المستخدمون والحسابات */
  "supervisors",    /* حسابات مدراء المساجد والداعمين */
  "settings-core"   /* الإعدادات الجوهرية */
];

/* =========================================================================
   من يمنح أيَّ دور
   -------------------------------------------------------------------------
   الحدُّ الذي لا يُتجاوز: لا أحدَ يمنح دوراً أعلى من دوره، ولا أحدَ يمنح
   دورَه نفسَه لغيره إن لم يكن فوقه. وإلّا فمديرُ مجمّعٍ يُنشئ مديرَ نظامٍ
   ثمّ يدخل به — فتسقط كلُّ الحدود دفعةً واحدة.
   ========================================================================= */
const GRANTABLE = {
  owner:          ["owner", "admin", "complexManager", "mosqueManager", "supervisor",
                   "teacher", "parent", "student", "donor"],
  admin:          ["admin", "complexManager", "mosqueManager", "supervisor",
                   "teacher", "parent", "student", "donor"],
  /* مطابقٌ لـ grantableRoles() في firestore.rules حرفاً بحرف: أيُّ تغييرٍ
     هنا يُنقل إليها معاً، وإلّا أُنشئ حسابُ الدخول ورُدّ ملفُّه فبقي يتيماً.
     «مشرف» و«داعم» لمدير المجمّع و«مشرف» لمدير المسجد أُعيدت (٤٤٢) بعد أن
     أُجيزت في القواعد، داخل منشأة المانح وحدها. */
  complexManager: ["mosqueManager", "supervisor", "teacher", "parent", "student", "donor"],
  /* مديرُ المسجد يعيّن مشرفَ مسجده — وهو أعرفُ بمن يشرف عنده */
  mosqueManager:  ["supervisor", "teacher", "parent", "student"],
  supervisor:     ["teacher", "parent", "student"]
};

function canGrantRole(target, actor) {
  const a = actor || (STATE && STATE.user) || {};
  const list = GRANTABLE[String(a.role || "")] || [];
  return list.indexOf(String(target || "")) > -1;
}

/* =========================================================================
   من يُنشئ المجمّعات ومن يعدّلها (٤٥٤ — P-1 في FAILED_TESTS.md)
   -------------------------------------------------------------------------
   كانت صفحةُ المجمّعات تُفتح لمدير المسجد والمشرف بالرابط المباشر (القائمةُ
   تُخفيها، وتعليقُ shell.js يقول «الحمايةُ في canDo» ولم تكن تُفحص هنا)،
   فيعدّل مجمّعَه ويُنشئ مجمّعات — والخادمُ يقبل لأنّ سجلّ المجمّع بلا نطاق.
   الإنشاءُ والحذفُ للمدير والمالك، والتعديلُ لهما ولمدير ذلك المجمّع نفسِه.
   ========================================================================= */
function myComplexIds() {
  const u = (STATE && STATE.user) || {};
  return [u.complexId].concat(u.complexIds || [], (u.scopeIds || [])
    .filter(k => String(k).indexOf("complex:") === 0).map(k => String(k).split(":")[1]))
    .filter(x => x != null && x !== "").map(String);
}
function mayCreateComplex() { return isTopAdmin(); }
function mayEditComplex(cx) {
  if (isTopAdmin()) return true;
  return isComplexMgr(myRoleNow()) && !!cx && myComplexIds().indexOf(String(cx.id)) > -1;
}
function canDo(area) {
  const r = ((STATE && STATE.user) || {}).role || "";

  /* «المستخدمون والحسابات» لمدير المسجد بقرار الإدارة. استثناءٌ صريحٌ
     هنا لا حذفٌ من القائمتين أدناه: حذفُ "users" من COMPLEX_ONLY يفتحها
     للداعم ولكلّ من هو على مستوى المسجد، وهو غيرُ المقصود.
     والكتابةُ تبقى للمدير وحده — قواعدُ Firestore تحرسها على الخادم. */
  if (r === "mosqueManager" && area === "users") return true;

  /* إدارةُ الحسابات: مديرُ المجمّع يملكها في مجمّعه بقرار الإدارة،
     ومديرُ المسجد والداعمُ ممنوعان منها مهما اتّسع نطاقُهما.
     والإعداداتُ الجوهريةُ تبقى ممنوعةً على الجميع دون المالك والمدير. */
  if (isComplexMgr(r)) {
    if (SYSTEM_ONLY.indexOf(area) > -1) return false;
  } else if ((isMgrRole(r) || r === "donor") && ADMIN_ONLY.indexOf(area) > -1) {
    return false;
  }

  const lvl = scopeLevel();
  if (lvl === "system") return true;
  if (SYSTEM_ONLY.indexOf(area) > -1) return false;
  if (lvl === "complex") return true;
  /* مستوى المسجد: يُمنع ما هو للمجمّع */
  return COMPLEX_ONLY.indexOf(area) === -1;
}

/* المسجد الذي يعمل فيه المستخدم — يُحصر به كلّ ما يراه ويكتبه */
function myMosqueId() {
  const u = (STATE && STATE.user) || {};
  return String(u.mosqueId || "");
}

/* ترشيح قائمةٍ بنطاق المستخدم: يُنادى قبل عرض أيّ بيانات */
function scoped(list, opts) {
  const arr = Array.isArray(list) ? list : [];
  const lvl = scopeLevel();
  if (lvl === "system" || isTopAdmin()) return arr;

  const cx = String(((STATE && STATE.user) || {}).complexId || "");
  const mq = myMosqueId();
  const o = opts || {};

  return arr.filter(x => {
    if (!x) return false;

    /* بيانات قديمة بلا نطاق: تبقى مرئيّة لئلّا تختفي عن أصحابها */
    if (cx && x.complexId && String(x.complexId) !== cx) return false;

    if (lvl === "mosque" && mq) {
      if (x.mosqueId) return String(x.mosqueId) === mq;
      /* ما لا mosqueId له: يُنسب عبر حلقته */
      if (o.viaCircle && x.circleId) {
        const c = (cur("circles") || []).find(y => String(y.id) === String(x.circleId));
        return c ? String(c.mosqueId || "") === mq : true;
      }
    }
    return true;
  });
}

/* حلقات نطاقه — أساسٌ لأكثر الشاشات */






/* =========================================================================
   إخفاء ما لا يُتاح
   -------------------------------------------------------------------------
   إخفاء البند خيرٌ من عرضه ثمّ رفضه: من رأى زرّاً ثمّ مُنع ظنّ العطل، ومن لم
   يره لم يطلبه.
   ========================================================================= */
/* =========================================================================
   ما يراه كلُّ دورٍ في القائمة
   -------------------------------------------------------------------------
   القائمةُ كانت واحدةً للجميع، والمنعُ لا يظهر إلا بعد الضغط: يرى المرءُ
   عشرين باباً ويُردّ عن نصفها. هذه أبوابُ كلٍّ بحسب دوره.

   وهي زينةٌ لا حماية: canDo يحرس الشاشة، وقواعدُ Firestore تحرس البيانات.
   ========================================================================= */
const NAV_ROLE = {
  complexManager: ["dashboard", "complexes", "supervisors", "admissions",
                   "programs", "reports", "stats", "exams", "transport",
                   "move", "worktime", "duty", "finance", "payroll", "settings"],
  mosqueManager:  ["dashboard", "students", "circles", "managers", "teachers",
                   "programs", "reports", "stats", "exams", "transport",
                   "move", "worktime", "duty", "procs", "motivation", "points",
                   "finance", "payroll", "settings"]
};

function navFor(iface) {
  const list = (NAV && NAV[iface]) || [];
  if (iface !== "admin") return list;

  const AREA = {
    complexes: "complexes", mosques: "mosques",
    supervisors: "supervisors", managers: "supervisors",
    users: "users", settings: "settings"
  };

  /* بنودٌ مالية: تُخفى عمّن لا يرى المال */
  /* المالية مفصولةٌ عن التحفيز: مجموعتان تُخفيان معاً عمّن لا يرى المال،
     ولكلٍّ بابُها في القائمة. */
  const FIN = ["payroll", "finance"];              /* مالٌ خالص */
  const MOT = ["points", "motivation"];            /* تحفيزٌ تربويّ */

  return list.filter(it => {
    if (!it) return false;
    if (FIN.indexOf(it.id) > -1 || FIN.indexOf(it.group) > -1) {
      if (!canSeeFinance()) return false;
    }
    if (MOT.indexOf(it.id) > -1 || MOT.indexOf(it.group) > -1) {
      if (!canSeeMotivation()) return false;
    }
    const area = AREA[it.id];
    if (area && !canDo(area)) return false;

    /* أبوابُ الدور: من له قائمةٌ خاصّة لا يرى غيرها */
    const allow = NAV_ROLE[((STATE && STATE.user) || {}).role || ""];
    if (allow && allow.indexOf(it.id) === -1 &&
        (!it.group || allow.indexOf(it.group) === -1)) return false;

    return true;
  });
}

function allowedIface() {
  const r = ((STATE && STATE.user) || {}).role || "";
  if (!r) return null;                                   /* لا جلسة: بلا قيد */
  if (r === "admin" || isMgrRole(r)) return "admin";
  if (r === "teacher") return "teacher";
  /* وليُّ الأمر كان يُوجَّه إلى واجهة الطالب، فيرى شاشاتٍ تخاطب ابنه لا
     تخاطبه، ولا يجد شريطَ الأبناء ولا مراسلةَ المعلّم. */
  if (r === "parent") return "parent";
  if (r === "student") return "student";
  if (r === "donor") return "donor";
  return null;
}

function setIface(iface) {
  if (!NAV[iface]) return;
  /* كان بالإمكان استدعاء setIface("admin") من وحدة التحكم فتُفتح واجهة
     الإدارة لأي حساب. الآن الدور هو الحكم، وإخفاء الأزرار لم يعد الحماية. */
  const allow = allowedIface();
  if (allow && iface !== allow) {
    if (typeof showToast === "function") showToast("لا تملك صلاحية هذه الواجهة", "warn");
    return;
  }
  STATE.iface = iface;
  STATE.page = NAV[iface][0].id;
  STATE.tab = {};
  STATE.planId = null;
  $$(".iface-btn").forEach(b => b.classList.toggle("active", b.dataset.iface === iface));
  const un = $("#userName"); if (un) un.textContent = USER_NAME[iface];
  const ur = $("#userRole"); if (ur) ur.textContent = ROLE_LABEL[iface];
  const av = $(".avatar"); if (av) av.textContent = initials(USER_NAME[iface]);
  renderNav();
  mount();
}

function go(page) {
  /* =====================================================================
     SHELL_MODE لصفحات الإدارة وحدها
     ---------------------------------------------------------------------
     admin/shell.js يفعّله في كلّ صفحةٍ يُحمَّل فيها، والمعلّمُ قد يدخل من
     إحداها فيبقى مفعّلاً في جلسته. فيُبحث لشاشاته عن ملفّ HTML مستقلّ —
     ولا ملفّ لها، فيقف الزرُّ بصمتٍ أو يقول «لم يُعثر على شاشة».

     شاشاتُ المعلّم والطالب ووليّ الأمر تُرسم في مكانها لا في ملفّات.
     ===================================================================== */
  const inShell = window.SHELL_MODE && STATE.iface === "admin";

  if (inShell && page !== STATE.page) {
    var files = window.__adminFiles || {};

    /* المفاتيح تُنادى بصيغتين: "exams-record" و "admin/exams-record"،
       والخريطة تحفظها بلا بادئة. تجربة الصيغتين أأمن من توحيد النداءات
       المتفرّقة في الملف. */
    var key = String(page || "");
    var bare = key.indexOf("/") > -1 ? key.slice(key.lastIndexOf("/") + 1) : key;
    var f = files[key] || files[bare];

    if (!f) {
      /* لا ملف ولا مفتاح: الانتقال إلى صفحة غير موجودة يقف بلا خطأ في
         الطرفية، فيبدو الزرّ معطّلاً. يُقال السبب بدل الصمت. */
      if (typeof showToast === "function") {
        showToast("لم يُعثر على شاشة «" + bare + "»", "warn");
        return;
      }
      f = bare + ".html";
    }
    /* مسارٌ مطلق: أسماءُ الملفات في الخريطة نسبيّة (complexes.html)، فإن
       نُودي go من صفحةٍ خارج مجلّد admin — كصفحة الجذر — حُلَّ الاسمُ إلى
       /complexes.html ولا ملفَّ هناك، فتظهر صفحةُ Firebase «Page Not
       Found». الصفحاتُ كلُّها في /admin/ فيُصرَّح بالمجلّد. */
    location.href = /^(\/|https?:)/.test(f) ? f : "/admin/" + f;
    return;
  }
  /* القائمةُ الجانبية ظاهرةٌ بجوار بطاقة الطالب، فالانتقالُ منها يُغلقها —
     وإلا بقيت البطاقةُ فوق صفحةٍ أخرى. */
  try { if (document.body.classList.contains("panel-open")) closePanel(); } catch (e) {}
  STATE.page = page;
  STATE.planId = null;
  STATE.facilityView = null;   /* مغادرة الصفحة تُغلق عرض التفاصيل */
  renderNav();
  mount();
  const sb = $("#sidebar"); if (sb) sb.classList.remove("open");
  const ov = $("#overlay"); if (ov) ov.classList.remove("show");
}

/* عنوان تبويب المتصفح يتبع الصفحة المعروضة */
function setDocTitle(t) {
  const base = "لوحة الإدارة | " + (complexName(STATE.complexId) || "ذات القرآنية");
  document.title = t ? t + " — " + base : base;
}

/* =========================================================================
   الفحوص الدورية — لا مع كلّ رسم
   -------------------------------------------------------------------------
   كانت سبعةُ فحوصٍ تجري في mount: مسحُ التنبيهات ونقصِ البيانات وانقطاعِ
   الحلقات وترحيلِ الواجبات ومزامنةِ النطاق. وكلٌّ منها يمرّ على آلاف
   السجلات.

   و mount تُنادى مع كلّ ضغطةِ زرّ وكلّ تبديلِ تبويب — فتُعاد الفحوص كلّها
   عشراتِ المرّات في الدقيقة، والنتيجة واحدة في كلّ مرة.

   تجري الآن كلّ دقيقتين، وعند أوّل رسمٍ بعد تحميل البيانات. والفرقُ
   محسوس: الرسم يصير عرضاً محضاً لا فحصاً.
   ========================================================================= */
let SCAN_AT = 0;
const SCAN_EVERY = 120000;          /* دقيقتان */

/* =========================================================================
   صيانةُ النظام لا تجري من جلسة معلّم
   -------------------------------------------------------------------------
   «تعذّر الحفظ — دورُك «teacher» لا يملك حفظَ هذا السجلّ» أربعَ مرّاتٍ مع
   كلّ فتحةٍ وكلّ تحديث: فحوصُ الإقلاع تجري لكلّ دورٍ سواء، وفيها كتاباتٌ
   إداريّةٌ عامّة — ترحيلُ واجبات أمس (planRules) ورصدُ إجازات الحلقات
   (workflow). فالخادمُ يردُّها لأنّ المعلّمَ لا يملكها، ويُرفع لصاحبها
   تنبيهٌ عن كتابةٍ لم يطلبها أصلاً.

   وهي صيانةٌ تخصُّ النظامَ كلَّه لا طالباً ولا حلقة، فتجري من جلسة من
   يملكها: المالك والمدير ومديرو المنشآت. والدوالُّ باقيةٌ كما هي لم
   تُمسّ، وتُنفَّذ كما كانت متى فتح مخوَّلٌ النظام.
   ========================================================================= */
function maySysWrite() {
  const r = ((STATE && STATE.user) || {}).role || "";
  if (!r) return true;                       /* لا جلسة: وضعُ التطوير */
  return r === "admin" || r === "owner" ||
         (typeof isMgrRole === "function" && isMgrRole(r));
}

function runPeriodicScans(force) {
  const now = Date.now();
  if (!force && now - SCAN_AT < SCAN_EVERY) return;
  SCAN_AT = now;
  /* الفحوصُ الدوريةُ كلُّها تلقائية: كانت مزامنةُ النطاق وحدَها محاطةً بـ
     linkAuto، والبقيّةُ تمرّ من حارس الارتباط إن جرت خلال ثوانٍ من نقرةٍ
     عابرة. فتُحاط كلُّها: لا يمسّ فحصٌ دوريٌّ ارتباطاً أبداً (٤٣٠). */
  return linkAuto(function () { runPeriodicScansBody(); });
}
function runPeriodicScansBody() {
  try { if (typeof scanAlerts === "function") scanAlerts(); } catch (e) {}

  try {
    if (typeof fetchPrayerTimes === "function" && prayerCfg().on && !prayerTimes()) {
      fetchPrayerTimes().then(t => { if (t) mount(); });
    }
    if (typeof autoHolidayScan === "function" && FB_LOADED && maySysWrite()) autoHolidayScan();
  } catch (e) {}

  /* مزامنةُ النطاق تلقائيةٌ تجري كلّ دقيقتين: تُحاط بـ linkAuto فلا تمسّ
     ارتباطاً — وإنما تكتب circleIds التي تقوم عليها قواعدُ الخادم. */
  try { if (typeof syncMyScope === "function" && FB_LOADED) linkAuto(syncMyScope); } catch (e) {}
  try { if (typeof runDailyRoll === "function" && maySysWrite()) runDailyRoll(); } catch (e) {}

  try {
    if (typeof scanNotifications === "function") scanNotifications();
    if (typeof scanDataGaps === "function" && FB_LOADED) scanDataGaps();
  } catch (e) {}
}

/* =========================================================================
   زرُّ الرجوع يرجع داخل النظام لا خارجَه
   -------------------------------------------------------------------------
   «أكون داخل الطالب وأرجع للخلف إلى الصفحة الرئيسية، فتظهر صورةُ تسجيل
   الدخول ثوانيَ ثمّ يرجع».

   والسببُ أنّ النظامَ كلَّه صفحةٌ واحدة: الانتقالُ بين شاشاته يُبدّل
   STATE.page ويُعيد الرسمَ، ولا يُسجَّل في تاريخ المتصفّح. فزرُّ الرجوع
   لا يجد شاشةً سابقةً يعود إليها داخل الصفحة، فيُغادر الوثيقةَ كلَّها إلى
   ما قبلها — وهي صفحةُ الدخول — فتُحمَّل وتُعرض بنموذجها حتى تتحقّق
   الهويّةُ فتُعيده. تلك الثواني هي «صورةُ تسجيل الدخول».

   فكلُّ شاشةٍ تُرسم تُسجَّل قيداً في التاريخ، والرجوعُ يستعيدها في مكانها
   بلا مغادرةٍ ولا تحميل. والعنوانُ لا يتغيّر (pushState بلا رابط)، فلا
   مسارَ جديدٌ يُطلب من الخادم ولا يُربك عاملَ الخدمة.

   والمسجَّلُ ثلاثةٌ لا غير: الشاشةُ، والطالبُ المفتوح، والحلقةُ المفتوحة.
   فتبديلُ تبويبٍ داخل البطاقة أو إعادةُ رسمٍ لتحديث شارةٍ لا يُسجَّل،
   وإلّا احتاج الرجوعُ ضغطاتٍ بعدد ما لمس المستخدم.
   ========================================================================= */
let NAV_LAST = null;      /* آخرُ ما سُجّل — فلا يتكرّر القيدُ نفسُه */
let NAV_BACK = false;     /* داخلَ استعادةِ رجوعٍ: لا يُسجَّل شيء */

function navSnap() {
  return {
    zat: 1,
    page: String(((typeof STATE !== "undefined" && STATE) || {}).page || ""),
    tstu: String(((typeof TSTU !== "undefined" && TSTU) || {}).id || ""),
    tcrc: String(((typeof TCRC !== "undefined" && TCRC) || {}).id || "")
  };
}

function navSame(a, b) {
  return !!a && !!b && a.page === b.page && a.tstu === b.tstu && a.tcrc === b.tcrc;
}

function navPush() {
  if (NAV_BACK) return;
  if (typeof history === "undefined" || !history.pushState) return;
  const s = navSnap();
  if (navSame(s, NAV_LAST)) return;
  /* أوّلُ شاشةٍ تحلّ محلَّ القيد القائم، وما بعدها يُضاف — فلا يُزاد قيدٌ
     بلا سببٍ عند أوّل رسم */
  if (NAV_LAST === null) history.replaceState(s, ""); else history.pushState(s, "");
  NAV_LAST = s;
}

if (typeof window !== "undefined" && window.addEventListener) {
  window.addEventListener("popstate", function (e) {
    const s = e && e.state;
    /* قيدٌ ليس من شاشاتنا (ما قبل دخولِ النظام): يمضي كما كان */
    if (!s || !s.zat) return;
    NAV_BACK = true;
    try {
      if (typeof STATE !== "undefined" && STATE) STATE.page = s.page;
      if (typeof TSTU !== "undefined" && TSTU) TSTU.id = s.tstu;
      if (typeof TCRC !== "undefined" && TCRC) TCRC.id = s.tcrc;
      NAV_LAST = s;
      try { renderNav(); } catch (x) {}
      mount();
    } catch (x) { console.warn("popstate:", x); }
    finally { NAV_BACK = false; }
  });
}

/* =========================================================================
   الشاشةُ تُرسم أوّلاً، وما حولها يلحق
   -------------------------------------------------------------------------
   «أيُّ زرٍّ أو نافذةٍ تكون معمولةً باستخدام رياكت» — والذي تُعطيه رياكت
   هنا هو الاستجابةُ الفوريّة، وسبيلُه أقصرُ من إطار عمل: كلُّ نقرةٍ كانت
   تدفع — قبل أن تُرسم الشاشة — شعارَ المنشأة والفحوصَ الدوريّة والشاراتِ
   وصورةَ الشريط والشريطَ السفليَّ والجانبيَّ ومقاسَ المصحف. فيقف الإصبعُ
   على الزرّ ريثما تتمّ هذه كلُّها ثمّ تظهر الشاشة.

   وهذه كلُّها زينةُ ما حول الشاشة لا الشاشةَ نفسَها: لا يتوقّف عليها ما
   يُرسم. فصارت تُؤجَّل إلى ما بعد الرسم، فتظهر الشاشةُ في اللحظة ثمّ تلحق
   هي في الإطار التالي. ولم يُحذف منها شيء.

   واثنتان منها كانتا تُنادَيان قبل الرسم فتعملان على شاشةٍ ذهبت: ملءُ
   صندوق المراسلة ومنتقي الأبناء، ومقاسُ أسطر المصحف الذي يُقاس بالعرض.
   موضعُهما الصحيح بعد الرسم — وهو ما صرن إليه.
   ========================================================================= */
function mountChrome() {
  /* شعارُ المنشأة في القائمة الجانبية — يتبع ما نحن داخله */
  try { brandLogoSync(); } catch (e) {}
  /* الفحوص الثقيلة كلّ دقيقتين — والشارات مع كلّ رسم لأنها خفيفة */
  try { runPeriodicScans(); } catch (e) {}
  try { if (typeof offqBadge === "function") offqBadge(); } catch (e) {}
  /* منتقيات ما بعد الرسم: عناصرُها تُبنى مع الصفحة فتُملأ بعدها */
  try {
    if (document.getElementById("tmsgBox") && typeof tmsgRender === "function") tmsgRender();
    if (document.getElementById("usKidBox") && typeof usKidRender === "function") usKidRender();
  } catch (e) {}
  try { if (typeof updateNotifBadge === "function") updateNotifBadge(); } catch (e) {}
  /* صورة الشريط تُحدَّث مع كل رسم، فتظهر فور الحفظ بلا إعادة تحميل */
  try { if (window.refreshTopbarPhoto) window.refreshTopbarPhoto(); } catch (e) {}
  try { renderTabBar(); } catch (e) {}
  try { tchTopCheckBtn(); } catch (e) {}
  try { tchTopbarTrim(); } catch (e) {}
  try { hideSideNavFor(STATE.iface); } catch (e) {}
  /* وأسطرُ المصحف تُضبط على عرض الورقة بعد الرسم — القياسُ لا يصحّ قبله */
  try { if (typeof musFit === "function") musFit(); } catch (e) {}
  /* قوائمُ السور: الفهرسُ يُجلب من الشبكة فقد لا يكون حاضراً وقت الرسم */
  try { if (window.plFillSurahs) window.plFillSurahs(); } catch (e) {}
}
window.mountChrome = mountChrome;

function mount() {
  /* مغادرةُ المصحف تُغلق مستمعَه اللحظيّ */
  try { if (STATE.page !== "mushaf" && typeof musLiveStop === "function" && MUS_LIVE.off) musLiveStop(); } catch (e) {}
  /* الواجهة تُصحَّح عند كل رسم، فلا يكفي تعديل STATE.iface يدوياً للتحايل */
  const allow = allowedIface();
  if (allow && STATE.iface !== allow) {
    STATE.iface = allow;
    if (!NAV[allow].some(x => x.id === STATE.page)) STATE.page = NAV[allow][0].id;
    /* والقائمةُ الجانبيةُ تُعاد مع التصحيح: كانت تُرسم عند الإقلاع بواجهة
       الإدارة قبل وصول دور الحساب، ثمّ يُصحَّح الدورُ فتُرسم شاشةُ المعلّم
       وتبقى قائمةُ الإدارة كما هي — فيرى المعلّمُ المنشآتِ والمساجدَ
       والتقاريرَ وهي ليست من عمله، ولا يُخفى الشريطُ عنه. */
    try { renderNav(); } catch (e) {}
  }

  /* الشاشةُ المعروضة تُسجَّل في تاريخ المتصفّح — بعد تصحيح الواجهة، فلا
     يُسجَّل ما سيُبدَّل. وشرحُ ذلك عند navPush أعلاه. */
  try { navPush(); } catch (e) {}

  if (scopeDenied()) {
    const root0 = $("#pageContent");
    if (root0) {
      root0.innerHTML = `<div class="page">${pageHead("حسابك غير مرتبط بمنشأة", "")}
        <div class="card">${emptyState("لا توجد بيانات لعرضها",
          "حسابك لم يُربط بمسجد أو مجمع بعد، فلا يمكن عرض أي بيانات. راجع إدارة النظام لربط حسابك بالمنشأة التي تعمل بها.")}</div>
      </div>`;
      runAnimations(root0);
    }
    return;
  }

  /* =======================================================================
     الشاشةُ البيضاء تقول سببَها
     -----------------------------------------------------------------------
     «فُتحت الواجهةُ والمحتوى فارغ»: كانت نتيجةُ الشاشة تُكتب كما هي، فإن
     سقطت الدالّةُ بخطأٍ أو ردّت فراغاً بقي الموضعُ أبيضَ بلا كلمة — ولا
     كونسولَ في يد صاحب الهاتف. وثلاثةُ أسبابٍ تُنتج البياضَ نفسَه:
     مفتاحُ شاشةٍ لا وجودَ له · خطأٌ أثناء الرسم · ردٌّ فارغ.
     تُسمّى كلُّها الآن في بطاقةٍ واحدةٍ مع ما يلزم لتشخيصها.
     ======================================================================= */
  const fnKey = `${STATE.iface}/${STATE.page}`;
  const fn = PAGES[fnKey];
  function mountCard(ttl, why) {
    const u = (STATE && STATE.user) || {};
    return `<div class="page">${pageHead(ttl, "")}
      <div class="card">${emptyState(ttl, why)}
        <div class="muted" style="font-size:12px;line-height:2;margin-top:10px;direction:ltr;text-align:left">
          iface=${esc(String(STATE.iface || "—"))} · page=${esc(String(STATE.page || "—"))}<br>
          role=${esc(String(u.role || "—"))} · mosqueId=${esc(String(u.mosqueId || "—"))}
          · complexId=${esc(String(u.complexId || "—"))}<br>
          scopeIds=${esc(String((u.scopeIds || []).length))} · screen=${fn ? "found" : "MISSING"}
        </div>
      </div></div>`;
  }

  let html = "";
  if (!fn) {
    html = mountCard("الصفحة غير متاحة", "لا توجد شاشةٌ بهذا المفتاح. ارجع للوحة التحكم.");
  } else {
    try {
      CUR_MEMO = {};             /* حفظُ القراءة أثناء بناء الشاشة (٤٢٥) */
      html = fn() || "";
    } catch (e) {
      console.error("mount:" + fnKey, e);
      html = mountCard("تعذّر رسم الصفحة",
        "وقع خطأٌ أثناء بناء هذه الشاشة: " + esc(String((e && e.message) || e)));
    } finally {
      CUR_MEMO = null;
    }
    if (!String(html).trim()) {
      html = mountCard("الصفحة فارغة",
        "بُنيت الشاشةُ ولم تُنتج محتوى. غالباً لا بياناتٍ في نطاق حسابك لهذا اليوم.");
    }
  }
  const root = $("#pageContent");
  /* عنوان التبويب من عنوان الصفحة المعروضة */
  setTimeout(function () {
    const h = document.querySelector("#pageContent .page-head h2");
    if (h) setDocTitle(h.textContent.trim());
  }, 0);
  if (!root) return;
  root.innerHTML = (typeof trmViewBanner === "function" ? trmViewBanner() : "") +
    (typeof alertLateBanner === "function" ? alertLateBanner() : "") + html;
  root.scrollTop = 0;
  try { if (typeof window.tbPeriodSync === "function") window.tbPeriodSync(); } catch (e) {}
  runAnimations(root);
  try { fabRender(); } catch (e) { console.warn("fab:", e); }
  try { updateMsgBadge(); } catch (e) { /* الشريط غير موجود بعد */ }
  /* صفحةُ المحادثة بعد رسم محتواها: التمريرُ إلى الأحدث، وتبديلُ زرّ
     الصوت بالإرسال — ولا بدّ أن يكون بعد innerHTML لا قبله. */
  try { tchatAfterMount(); } catch (e) {}
  /* مشغّلُ القرآن المسموع: يُركَّب مرّةً ويبقى خارج #pageContent، فيستمرّ
     الصوتُ عند التنقّل بين الشاشات ولا يُعاد تحميله. */
  try { if (QA.rid) qaBarMount(); } catch (e) {}

  /* وزينةُ ما حول الشاشة تلحق بعد أن ظهرت الشاشةُ للعين */
  if (typeof requestAnimationFrame === "function") {
    requestAnimationFrame(function () { try { mountChrome(); } catch (e) {} });
  } else {
    setTimeout(function () { try { mountChrome(); } catch (e) {} }, 0);
  }
}

/* =========================================================================
   نداءُ الرسم المكرَّرُ في الدورة الواحدة يُرسم مرّةً واحدة
   -------------------------------------------------------------------------
   النقرةُ الواحدةُ تستدعي mount أكثرَ من مرّةٍ أحياناً: الدالّةُ تُغلق
   الواجبَ فترسم، ثمّ تكتب التنبيهَ فترسم، ثمّ يرسم المستمعُ بعدها. وكلُّ
   رسمٍ يُعيد بناءَ الشاشة كاملةً — والنتيجةُ واحدة.

   فصار الأوّلُ يُرسم في حينه كما كان (فمن يقرأ الشاشةَ بعد النداء مباشرةً
   يجدها)، وما تلاه في الدورة نفسِها يُطوى في رسمٍ واحدٍ في الإطار التالي
   — فيُرى آخرُ حالٍ ولا يُبنى الشيءُ ثلاثاً. ولا يسقط رسمٌ ألبتّة.
   ========================================================================= */
(function () {
  var inTick = false, queued = 0;
  var raw = mount;
  window.mount = function () {
    if (inTick) {
      if (!queued && typeof requestAnimationFrame === "function") {
        queued = requestAnimationFrame(function () { queued = 0; raw(); });
      } else if (!queued) {
        queued = setTimeout(function () { queued = 0; raw(); }, 0);
      }
      return;
    }
    inTick = true;
    try { raw(); } finally { setTimeout(function () { inTick = false; }, 0); }
  };
})();

/* =========================================================
   ANIMATIONS
   ========================================================= */
function runAnimations(root) {
  if (!root) return;
  $$("[data-count]", root).forEach(el => {
    const target = parseFloat(el.dataset.count);
    const suffix = el.dataset.suffix || "";
    if (Number.isNaN(target)) { el.textContent = "0" + suffix; return; }
    const dur = 900, start = performance.now();
    function step(now) {
      const t = Math.min((now - start) / dur, 1);
      const eased = 1 - Math.pow(1 - t, 3);
      el.textContent = Math.round(target * eased) + suffix;
      if (t < 1) requestAnimationFrame(step);
      else el.textContent = target + suffix;
    }
    requestAnimationFrame(step);
  });
  requestAnimationFrame(() => requestAnimationFrame(() => {
    $$(".progress > span[data-pct]", root).forEach(sp => { sp.style.width = sp.dataset.pct + "%"; });
  }));
}

/* =========================================================
   COMPONENTS — modals, panels, toasts
   ========================================================= */
function openModal(title, sub, body, foot) {
  const root = $("#modalRoot");
  if (!root) return;
  /* نافذةٌ تُفتح فوق شاشةٍ مستثناةٍ من التحويل الهجريّ ترث استثناءها —
     فنوافذُ «دوام الموظفين» في duty-plus.js تبقى ميلاديةً بلا تعديلٍ فيه. */
  const greg = (typeof hijGregHere === "function" && hijGregHere()) ? ' data-greg="1"' : "";
  root.removeAttribute("data-dirty");
  if (!root.querySelector(".modal")) {
    const ae = document.activeElement;
    MODAL_RETURN = ae && ae !== document.body ? ae : null;
  }
  root.innerHTML = `<div class="modal-back"${greg} data-action="close-modal">
    <div class="modal" data-stop role="dialog" aria-modal="true" aria-labelledby="modalTitle" tabindex="-1">
      <div class="modal-head"><div><h3 id="modalTitle">${esc(title)}</h3>${sub ? `<div class="mh-sub">${esc(sub)}</div>` : ""}</div>
        <button class="modal-close" data-action="close-modal" aria-label="إغلاق">${ic("x", 18)}</button></div>
      <div class="modal-body">${body}</div>
      ${foot ? `<div class="modal-foot">${foot}</div>` : ""}
    </div></div>`;
  modalA11y(root);
}

/* =========================================================================
   الوصوليةُ في النوافذ (٤٣٢)
   -------------------------------------------------------------------------
   كان Esc يُغلق النافذة، لكنّ التركيزَ يبقى في الصفحة خلفها، وأغلبُ الحقول
   بلا ربطٍ برمجيٍّ بتسميتها — فقارئُ الشاشة يقرأ «حقلُ نص» بلا اسم. الآن:
     • كلُّ تسميةٍ في خانة (.field) تُربط بحقلها (for/id) ما لم تُربط.
     • ما بلا تسمية يأخذ placeholder اسماً له (aria-label).
     • التركيزُ ينتقل إلى أوّل حقلٍ في النافذة (أو إليها)، ويبقى داخلها
       بـ Tab، ويعود إلى ما كان عليه بعد إغلاقها.
   لا يتغيّر شكلٌ ولا سلوكٌ مرئيّ.
   ========================================================================= */
var MODAL_RETURN = null, MODAL_UID = 0;
var MODAL_FOCUSABLE = 'a[href], button:not([disabled]), input:not([disabled]):not([type="hidden"]), ' +
                        'select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';
function modalA11y(root) {
  try {
    const m = root.querySelector(".modal");
    if (!m) return;
    m.querySelectorAll("label").forEach(lb => {
      if (lb.htmlFor || lb.querySelector("input,select,textarea")) return;
      const box = lb.closest(".field, .form-row, .tsd-row") || lb.parentElement;
      const f = box && box.querySelector("input:not([type=hidden]),select,textarea");
      if (!f) return;
      if (!f.id) f.id = "mf" + (++MODAL_UID);
      if (!document.querySelector('label[for="' + f.id + '"]')) lb.htmlFor = f.id;
    });
    m.querySelectorAll("input:not([type=hidden]),select,textarea").forEach(f => {
      if (f.getAttribute("aria-label") || f.labels && f.labels.length) return;
      const ph = f.getAttribute("placeholder");
      if (ph) f.setAttribute("aria-label", ph);
    });
    const first = [...m.querySelectorAll(".modal-body " + MODAL_FOCUSABLE.split(", ").join(", .modal-body "))]
      .find(el => el.offsetParent !== null && !el.readOnly &&
                  /^(INPUT|SELECT|TEXTAREA)$/.test(el.tagName));
    setTimeout(() => {
      try {
        if (!document.body.contains(m)) return;
        if (m.contains(document.activeElement)) return;
        /* على اللمس يُركَّز على النافذة لا الحقل: الحقلُ يفتح لوحةَ المفاتيح
           فتغطّي النافذةَ قبل أن يقرأها صاحبُها */
        const touch = window.matchMedia && window.matchMedia("(pointer: coarse)").matches;
        (!touch && first ? first : m).focus({ preventScroll: true });
      } catch (e) {}
    }, 30);
  } catch (e) {}
}
/* Tab يدور داخل النافذة المفتوحة ولا يخرج إلى الصفحة خلفها */
document.addEventListener("keydown", function (e) {
  if (e.key !== "Tab") return;
  const m = document.querySelector("#modalRoot .modal");
  if (!m) return;
  const els = [...m.querySelectorAll(MODAL_FOCUSABLE)].filter(el => el.offsetParent !== null);
  if (!els.length) return;
  const a = els[0], z = els[els.length - 1];
  if (!m.contains(document.activeElement)) { e.preventDefault(); a.focus(); return; }
  if (e.shiftKey && document.activeElement === a) { e.preventDefault(); z.focus(); }
  else if (!e.shiftKey && document.activeElement === z) { e.preventDefault(); a.focus(); }
}, true);
function closeModal() {
  const r = $("#modalRoot");
  if (r) { r.innerHTML = ""; r.removeAttribute("data-dirty"); }
  const back = MODAL_RETURN; MODAL_RETURN = null;
  try { if (back && document.body.contains(back) && typeof back.focus === "function") back.focus({ preventScroll: true }); } catch (e) {}
}

/* تعديلاتٌ لم تُحفظ في النافذة المفتوحة (٤٢٩): تُوسَم النافذةُ عند أوّل
   كتابةٍ أو اختيارٍ من يد المستخدم (isTrusted)، لا ممّا يملؤه الكود.
   ويُسأل عنها قبل الإغلاق العارض (النقر على الخلفية أو Esc) وقبل استبدال
   النافذة بنافذة تأكيد — أمّا × و«إلغاء» فقرارٌ صريحٌ يُنفَّذ كما هو. */
function modalDirty() {
  const r = $("#modalRoot");
  return !!(r && r.querySelector(".modal") && r.getAttribute("data-dirty") === "1");
}
function modalDirtyWarn() {
  showToast("في النافذة تعديلاتٌ لم تُحفظ — احفظها، أو اضغط «إلغاء» أو × للخروج دون حفظ", "warn");
}
(function () {
  const mark = function (e) {
    if (!e || !e.isTrusted || !e.target || !e.target.closest) return;
    const r = e.target.closest("#modalRoot");
    if (r && e.target.closest(".modal") && /^(INPUT|SELECT|TEXTAREA)$/.test(e.target.tagName)) r.setAttribute("data-dirty", "1");
  };
  document.addEventListener("input", mark, true);
  document.addEventListener("change", mark, true);
})();

function openPanel(html) {
  const r = $("#panelRoot");
  if (!r) return;
  /* واللوحةُ كذلك ترث استثناءَ الشاشة التي فُتحت فوقها */
  try {
    if (typeof hijGregHere === "function" && hijGregHere()) r.setAttribute("data-greg", "1");
    else r.removeAttribute("data-greg");
  } catch (e) {}
  r.innerHTML = html;
  /* الصفحةُ خلف البطاقة تُقفل: كانت تُمرَّر تحتها ويظهر طرفُها من حولها،
     فتبدو البطاقةُ نافذةً على صفحةٍ لا صفحةً قائمةً بنفسها. */
  document.body.classList.add("panel-open");
  /* أشرطةُ التقدّم تُملأ بعرضٍ يُضبط بعد الرسم — كانت تُملأ في mount()
     وحدها، واللوحةُ تُفتح خارجه فيبقى الشريطُ فارغاً وإن كانت النسبةُ
     مكتوبةً بجانبه. */
  requestAnimationFrame(() => requestAnimationFrame(() => {
    r.querySelectorAll(".progress > span[data-pct]").forEach(sp => {
      sp.style.width = (sp.dataset.pct || 0) + "%";
    });
  }));
}
function closePanel() {
  const r = $("#panelRoot");
  if (r) r.innerHTML = "";
  document.body.classList.remove("panel-open");
  /* مسوّدةُ بطاقة الطالب تعيش ما دامت البطاقةُ مفتوحة */
  try { if (typeof stuDraftReset === "function") stuDraftReset(""); } catch (e) {}
}

function showToast(msg, type) {
  type = type || "success";
  const icons = { success: "checkCircle", info: "info", warn: "alert" };
  const titles = { success: "تم بنجاح", info: "معلومة", warn: "تنبيه" };
  const root = $("#toastRoot");
  if (!root) return;
  const el = document.createElement("div");
  el.className = `toast ${type}`;
  el.innerHTML = `<div class="toast-ico">${ic(icons[type] || "info", 18)}</div><div class="toast-text"><strong>${esc(titles[type] || "")}</strong><small>${esc(msg)}</small></div>`;
  root.appendChild(el);
  setTimeout(() => { el.classList.add("out"); setTimeout(() => el.remove(), 350); }, 3200);
}

function formField(label, type, opts, id) {
  const idAttr = id ? ` id="${id}"` : "";
  if (type === "select") return `<div class="field"><label>${esc(label)}</label><select${idAttr}>${opts.map(o => `<option>${esc(o)}</option>`).join("")}</select></div>`;
  if (type === "full") return `<div class="field full"><label>${esc(label)}</label><input${idAttr} placeholder="${esc(opts || "")}"></div>`;
  if (type === "tel") return `<div class="field"><label>${esc(label)}</label><input${idAttr} type="tel" inputmode="numeric" placeholder="${esc(opts || "")}" oninput="this.value=this.value.replace(/[^0-9]/g,'')"></div>`;
  if (type === "time") return `<div class="field"><label>${esc(label)}</label><input${idAttr} inputmode="numeric" maxlength="5" placeholder="${esc(opts || "")}" oninput="window.clockMask(this)" onblur="window.clockMask(this, true)"></div>`;
  return `<div class="field"><label>${esc(label)}</label><input${idAttr} placeholder="${esc(opts || "")}"></div>`;
}

