function openFacEdit(item, coll) {
  const single = coll === "mosques" ? "mosque" : "complex";
  window.__editTypes = Array.isArray(item.circleTypes) ? item.circleTypes.slice() : (item.circleTypes ? [item.circleTypes] : ["حلقة قرآنية"]);
  window.__editPhoto = item.photo || "";

  const facTypes = ["حلقات رجالية", "حلقات نسائية", "حلقات مختلطة"];
  const facClasses = ["مدرسة قرآنية", "جامع", "مسجد", "مجمع تعليمي"];
  const circleTypeOpts = ["حلقة قرآنية", "حلقة تحفيظ", "حلقة تجويد", "حلقة مراجعة"];
  const optList = (arr, cur) => ['<option value="">اختر…</option>'].concat(arr.map(o => `<option ${o === cur ? "selected" : ""}>${o}</option>`)).join("");
  const nameLabel = coll === "mosques" ? "اسم المسجد" : "اسم المنشأة";
  const mosqueSVG = '<svg viewBox="0 0 64 64" width="70" height="70" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M32 6c-3 4-3 7 0 10 3-3 3-6 0-10zM12 30c0-8 9-12 20-12s20 4 20 12M8 56V30M56 56V30M8 34h48M20 56V44a12 12 0 0124 0v12M4 56h56"/></svg>';
  const camSVG = '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M23 19a2 2 0 01-2 2H3a2 2 0 01-2-2V8a2 2 0 012-2h4l2-3h6l2 3h4a2 2 0 012 2z"/><circle cx="12" cy="13" r="4"/></svg>';
  const avatarInner = window.__editPhoto ? `<img src="${esc(window.__editPhoto)}" alt="">` : mosqueSVG;

  openModal(coll === "mosques" ? "تعديل مسجد" : "تعديل منشأة", "",
    `<div class="edit-fac">
      <div class="ef-avatar-wrap">
        <div class="ef-avatar" id="ecx_avatar">${avatarInner}</div>
        <button type="button" class="ef-cam" onclick="document.getElementById('ecx_photo_input').click()" aria-label="تغيير الصورة">${camSVG}</button>
        <input type="file" id="ecx_photo_input" accept="image/*" style="display:none" onchange="window.efPhoto(this)">
      </div>
      <div class="ef-grid">
        <div class="ef-field"><label>${nameLabel}</label><input id="ecx_name" value="${esc(item.name)}" placeholder="${nameLabel}"></div>
        <div class="ef-field"><label>اسم المدير</label><input id="ecx_manager" value="${esc(item.manager || "")}" placeholder="اسم المدير"></div>
        <div class="ef-field"><label>نوع المنشأة</label><select id="ecx_factype">${optList(facTypes, item.facType)}</select></div>
        <div class="ef-field"><label>تصنيف المنشأة</label><select id="ecx_facclass">${optList(facClasses, item.facClass)}</select></div>
        <div class="ef-field ef-multi"><label>نوع الحلقات</label>
          <div class="ef-tags" id="ecx_ctypes"></div>
          <select class="ef-add" onchange="window.efAddType(this)"><option value="">إضافة نوع…</option>${circleTypeOpts.map(o => `<option>${o}</option>`).join("")}</select>
        </div>
        ${(() => {
          /* المنطقةُ والجوالُ والحالة (٤٣١): كان الحفظُ يقرؤها من حقولٍ لا
             وجودَ لها في النموذج، فيُبقي القديمَ ولا سبيلَ إلى تعديلها من
             هنا. وقيمةُ الإيقاف تختلف: المجمّعُ «متوقف» والمسجدُ «متوقف
             مؤقت» كما في زرّ التشغيل — والقيمةُ المحفوظةُ تُضاف إن خرجت عنهما. */
          const stOpts = ["نشط", coll === "mosques" ? "متوقف مؤقت" : "متوقف"];
          if (item.status && stOpts.indexOf(item.status) === -1) stOpts.push(item.status);
          const curSt = item.status || "نشط";
          const clean = v => (v && v !== "—") ? v : "";
          return `<div class="ef-field"><label>المنطقة</label><input id="ecx_region" value="${esc(clean(item.region))}" placeholder="المنطقة"></div>
        <div class="ef-field"><label>رقم الجوال</label><input id="ecx_phone" type="tel" dir="ltr" inputmode="tel" value="${esc(clean(item.phone))}" placeholder="05xxxxxxxx"></div>
        <div class="ef-field"><label>الحالة</label><select id="ecx_status">${stOpts.map(o =>
          `<option ${o === curSt ? "selected" : ""}>${esc(o)}</option>`).join("")}</select></div>`;
        })()}
      </div>
    </div>`,
    `<button class="btn btn-primary ef-submit" data-action="save-edit-${single}" data-id="${item.id}">تعديل</button>`);

  const mm = document.querySelector("#modalRoot .modal");
  if (mm) mm.classList.add("wide");
  window.efRenderTypes();
}

