/* ---- مساعدات فورم تعديل المنشأة (tags + صورة) ---- */
window.efRenderTypes = function () {
  var box = document.getElementById("ecx_ctypes");
  if (!box) return;
  var arr = window.__editTypes || [];
  box.innerHTML = arr.map(function (t, i) {
    return '<span class="ef-tag">' + esc(t) + '<button type="button" onclick="window.efDelType(' + i + ')" aria-label="حذف">&times;</button></span>';
  }).join("");
};
window.efAddType = function (sel) {
  var v = sel.value; sel.value = "";
  if (!v) return;
  window.__editTypes = window.__editTypes || [];
  if (window.__editTypes.indexOf(v) === -1) { window.__editTypes.push(v); window.efRenderTypes(); }
};
window.efDelType = function (i) {
  if (!window.__editTypes) return;
  window.__editTypes.splice(i, 1);
  window.efRenderTypes();
};
window.efPhoto = function (input) {
  var f = input.files && input.files[0];
  if (!f) return;
  /* الصورة تُخزَّن base64 داخل مستند Firestore وحدّ المستند ميغابايت واحد،
     فبلا هذين الفحصين يفشل الحفظ لاحقاً بلا أي رسالة للمستخدم. */
  if (!/^image\//.test(f.type)) { showToast("اختر ملف صورة صالحاً", "warn"); input.value = ""; return; }
  if (f.size > 4 * 1024 * 1024) { showToast("حجم الصورة كبير — أقصى 4 ميغابايت", "warn"); input.value = ""; return; }
  var reader = new FileReader();
  reader.onerror = function () { showToast("تعذّرت قراءة الصورة", "warn"); };
  reader.onload = function (e) {
    var img = new Image();
    img.onerror = function () { showToast("الملف ليس صورة صالحة", "warn"); };
    img.onload = function () {
      var max = 256, w = img.width, h = img.height;
      if (w > h && w > max) { h = Math.round(h * max / w); w = max; }
      else if (h > max) { w = Math.round(w * max / h); h = max; }
      var cv = document.createElement("canvas"); cv.width = w; cv.height = h;
      cv.getContext("2d").drawImage(img, 0, 0, w, h);
      window.__editPhoto = cv.toDataURL("image/jpeg", 0.82);
      var av = document.getElementById("ecx_avatar");
      if (av) av.innerHTML = '<img src="' + window.__editPhoto + '" alt="">';
    };
    img.src = e.target.result;
  };
  reader.readAsDataURL(f);
};
function modalEditMosque(id) {
  const m = DB.mosques.find(x => x.id == id);
  if (!m) { showToast("المسجد غير موجود", "warn"); return; }
  openFacEdit(m, "mosques");
}
/* =========================================================================
   اختيار المنشأة — مسجد أو مجمع
   -------------------------------------------------------------------------
   كانت قائمة «المسجد» في نموذجي الحلقة والطالب تعرض DB.mosques وحدها،
   فإن لم يكن للمجمع مساجد بعد تعذّرت إضافة أي حلقة إليه. صارت القائمة
   تجمع المجمعات والمساجد معاً ويميّز كلاً منها لاحقتُه، فقد يتشابه الاسم
   بين مجمع ومسجد ولا يصح الاعتماد على الاسم وحده.
   ========================================================================= */
const FAC_SEP = " — ";



/* يفكّ الوسم المختار إلى { mosque, mosqueId, complexId } جاهزة للحفظ */


/* المجمع يُشتقّ من المسجد المختار لا من المجمع النشط في الشريط العلوي.
   كان الاثنان يفترقان: تختار مسجداً تابعاً لمجمع «ب» بينما النشط «أ»،
   فيُحفظ السجل بـ complexId = أ و mosqueId يتبع ب — نطاقان متناقضان
   يكسران أي حصر بالمنشأة لاحقاً. */


/* =========================================================================
   الحلقة: أيام منظّمة · أنواع من المنشأة · عدّاد حيّ · سعة · فترة
   -------------------------------------------------------------------------
   كانت أيام الحلقة نصّاً حرّاً:  days: val("#c_days", "الأحد، الثلاثاء")
   فـ«الأحد، الثلاثاء» و«الاحد والثلاثاء» و«أحد-ثلاثاء» ثلاث قيم لمعنى
   واحد. ولأن الطالب يرث أيام حلقته، تنتقل الفوضى إليه. ولا يُحسب معها
   شيء: «كم حلقة تعمل الخميس؟» بلا إجابة. وجدولة الواجبات في المواصفات
   تُبنى على هذه الأيام.
   ========================================================================= */

const WEEK_DAYS = ["السبت", "الأحد", "الاثنين", "الثلاثاء", "الأربعاء", "الخميس", "الجمعة"];

/* الأيام مصفوفة دائماً — والنصوص القديمة تُقرأ بلا فقدان */
function daysToArray(v) {
  if (Array.isArray(v)) return v.filter(d => WEEK_DAYS.indexOf(d) > -1);
  const t = String(v == null ? "" : v).trim();
  if (!t) return [];
  if (/^يومي/.test(t)) return WEEK_DAYS.slice();
  /* المطابقة بعد تجريد الهمزات وأل التعريف: «الاحد» بلا همزة كُتبت
     كثيراً، وكانت لا تطابق «الأحد» فيضيع اليوم بصمت. */
  const bare = x => String(x).trim()
    .replace(/[أإآ]/g, "ا").replace(/ة$/, "ه")
    .replace(/^ال/, "").replace(/\s+/g, "");

  /* يفصل على الفاصلة والشرطة والمسافة، والواو حين تبدأ كلمة */
  return t.split(/[،,\-\/]+|\s+و?|(?<=\S)و(?=ال)/)
    .map(x => bare(x)).filter(Boolean)
    .map(x => WEEK_DAYS.find(d => bare(d) === x))
    .filter(Boolean)
    .filter((d, i, a) => a.indexOf(d) === i);
}



/* مربّعات اختيار الأيام */
function daysPicker(id, current) {
  const sel = daysToArray(current);
  return `<div class="field full"><label>أيام الحلقة</label>
    <div class="day-picker" id="${id}">
      ${WEEK_DAYS.map(d => `<label class="day-chip${sel.indexOf(d) > -1 ? " on" : ""}">
        <input type="checkbox" value="${esc(d)}"${sel.indexOf(d) > -1 ? " checked" : ""}
          onchange="this.closest('.day-chip').classList.toggle('on', this.checked)">
        <span>${esc(d)}</span></label>`).join("")}
    </div>
    <small style="font-size:11px;color:var(--text-faint)">يرثها طلاب الحلقة، وتُبنى عليها جدولة الواجبات</small>
  </div>`;
}

function daysValue(id) {
  const box = document.getElementById(id);
  if (!box) return [];
  return [...box.querySelectorAll("input:checked")].map(x => x.value);
}

/* أنواع الحلقات من المنشأة — كانت خمسة نصوص محفورة في الكود بينما
   المنشأة تحمل circleTypes قابلة للتخصيص */
function circleTypeOptions(mosqueId, complexId) {
  const pick = (list, id) => (list || []).find(x => String(x.id) === String(id));
  const m = pick(cur("mosques"), mosqueId);
  const c = pick(cur("complexes"), complexId || (m && m.complexId));
  const t = (m && m.circleTypes && m.circleTypes.length) ? m.circleTypes
          : (c && c.circleTypes && c.circleTypes.length) ? c.circleTypes : null;
  return (t && t.length) ? t : ["أشبال", "مبتدئين", "تميز", "مراجعة", "حفظ"];
}

/* عدد طلاب الحلقة محسوباً — الحقل students كان يُكتب صفراً ولا يُحدَّث */
/* =========================================================================
   فهرسُ المساجد العلنيّ — لصفحة التسجيل وحدَها
   -------------------------------------------------------------------------
   «عند تسجيل الطالب لأوّل مرّة تكون خانةٌ يتبع لأيّ مسجد… يرى كلّ المساجد
   ويختار منهم».

   وصفحةُ التسجيل يفتحها من لا حسابَ له، ولا يقرأ مجموعةَ المساجد إلّا
   حسابٌ فعّال. ولم تُفتح المجموعةُ للعامّة: مستندُ المسجد يحمل رابطَ
   مقرأته ورقمَ مشرفه. فيُكتب مستندٌ واحدٌ لا يحمل إلّا المعرّفَ والاسمَ
   وتبعيّةَ المجمّع — قدرَ ما تحتاجه القائمةُ المنسدلة ولا حرفَ زيادة.

   ويُعاد بناؤه عند كلّ حفظِ مسجد، فلا يحتاج صيانةً ولا زرّاً.
   ========================================================================= */
function pubMosqueIndexBuild() {
  const items = (Array.isArray(DB.mosques) ? DB.mosques : [])
    /* «متوقف» و«متوقف مؤقت» كلاهما خارجَ صفحة التسجيل (٤٣٢): كان يُستبعد
       الأوّلُ وحدَه، وزرُّ الإيقاف يكتب الثاني فيبقى المسجدُ الموقوفُ ظاهراً */
    .filter(m => m && !/^متوقف/.test(String(m.status || "")) && String(m.name || "").trim())
    .map(m => {
      /* اسمُ المجمّع معه: مسجدان باسمٍ واحدٍ في مجمّعين يلتبسان على
         المسجِّل بلا هذا. واسمُ المجمّع علنيٌّ كاسم المسجد — لا سرَّ فيه. */
      const cx = (Array.isArray(DB.complexes) ? DB.complexes : [])
        .find(c => c && String(c.id) === String(m.complexId || ""));
      return { id: String(m.id), name: String(m.name),
               cx: String(m.complexId || ""),
               cxName: String((cx && cx.name) || "") };
    })
    .sort((a, b) => String(a.name).localeCompare(String(b.name), "ar"));
  return { id: "mosques", items: items, ts: Date.now() };
}

window.pubMosqueIndexSync = function () {
  try {
    const db = typeof FDB === "function" ? FDB() : null;
    if (!db) return Promise.resolve(false);
    /* لا تمرُّ بـ persistSet: ليست من مجموعات النظام ولا تُحمَّل معها،
       وهي فهرسُ عرضٍ لا سجلُّ بيانات. */
    return db.collection("publicIndex").doc("mosques")
      .set(pubMosqueIndexBuild()).then(() => true).catch(e => sideFail("publicIndex", e));
  } catch (e) { return Promise.resolve(false); }
};

function circleCount(c) {
  if (!c) return 0;
  return (cur("students") || []).filter(s =>
    s && s.status !== "متوقف" &&
    (String(s.circleId) === String(c.id) ||
     (!s.circleId && String(s.circle) === String(c.name)))).length;
}

/* السعة: يُحذّر قبل التجاوز لا بعده */
function circleFull(c) {
  const cap = Number(c && c.capacity) || 0;
  return cap > 0 && circleCount(c) >= cap;
}

/* =========================================================================
   سعةُ الحلقة تُحترم في كلّ بابٍ يُدخل طالباً إليها
   -------------------------------------------------------------------------
   «وضعتُ الحدَّ الأقصى ١١ وأضفتُ أكثرَ من ١١ وقَبِل»: الحارسُ كان في
   نموذج «إضافة طالب» وحدَه، وأبوابُ الدخول أكثرُ — تعديلُ بطاقة الطالب
   ينقله إلى حلقةٍ أخرى، والنقلُ الجماعيُّ يُدخل عشرةً دفعةً — فتمتلئ
   الحلقةُ من حيث لا يمرّ الحارس.

   وهذه تُسأل من كلّ باب: تردُّ true إن كانت الحلقةُ ممتلئةً ولم يكن
   الطالبُ فيها أصلاً — فلا تُمنع إعادةُ حفظ من هو فيها، ولا تُمسّ بياناتُ
   ارتباطٍ قائمة.
   ========================================================================= */
function circleCapBlock(circleId, studentId, silent) {
  const cid = String(circleId || "");
  if (!cid) return false;
  const c = (cur("circles") || []).find(x => String(x.id) === cid) ||
            (Array.isArray(DB.circles) ? DB.circles.find(x => String(x.id) === cid) : null);
  if (!c) return false;
  const st = (cur("students") || []).find(x => String(x.id) === String(studentId || "")) ||
             (Array.isArray(DB.students)
               ? DB.students.find(x => String(x.id) === String(studentId || "")) : null);
  if (st && String(st.circleId || "") === cid) return false;   /* فيها أصلاً */
  if (!circleFull(c)) return false;
  if (!silent && typeof showToast === "function") {
    showToast("حلقة " + (c.name || "") + " مكتملة (" +
      toArabicDigits(Number(c.capacity) || 0) + " طالباً) — ارفع الحدَّ أو اختر حلقةً أخرى",
      "warn");
  }
  return true;
}

/* =========================================================================
   مواقيت الصلاة
   -------------------------------------------------------------------------
   المواصفات: «بما أنه لا توجد أجهزة بصمة، يُحتسب حضور المعلّم ذكياً... يُربط
   النظام بواجهة برمجة تطبيقات خاصة بمواقيت الأذان حسب المدينة. إذا كانت
   الحلقة (بعد صلاة العصر بـ١٥ دقيقة)، يقرأ النظام وقت أذان العصر ووقت أذان
   المغرب، ويقارن وقت تحضير المعلّم لاحتساب: هل حضر في الوقت، أم متأخراً،
   أم مبكراً؟»

   وكان وقت الحلقة رقماً ثابتاً (16:00) بينما العصر يزحف على مدار السنة
   نحو ساعةٍ كاملة، فيُحتسب على المعلّم تأخّرٌ لم يقع أو يُغفَل تأخّرٌ وقع.

   المصدر: AlAdhan — مفتوحٌ بلا مفتاح. والنتيجة تُخزَّن ليومها فلا تُطلب
   الشبكة مع كل رسم، ويعمل النظام بلا إنترنت على آخر ما حُفظ.
   ========================================================================= */

const PRAYERS = [
  { k: "Fajr",    h: "الفجر" },
  { k: "Dhuhr",   h: "الظهر" },
  { k: "Asr",     h: "العصر" },
  { k: "Maghrib", h: "المغرب" },
  { k: "Isha",    h: "العشاء" }
];

function prayerAr(k) { return (PRAYERS.find(p => p.k === k) || {}).h || k; }

function prayerCfg() {
  const s = DB.settings || {};
  return {
    on: s.prayerOn === true,
    city: String(s.prayerCity || "").trim(),
    country: String(s.prayerCountry || "SA").trim(),
    method: Number(s.prayerMethod) || 4     /* ٤ = أم القرى */
  };
}

/* مواقيت يومٍ من الذاكرة أو التخزين المحلي */
const PRAYER_MEM = {};

function prayerKey(dateISO) {
  const c = prayerCfg();
  return "pt_" + c.city + "_" + c.country + "_" + dateISO;
}

function prayerTimes(dateISO) {
  const d = dateISO || todayISO();
  const k = prayerKey(d);
  if (PRAYER_MEM[k]) return PRAYER_MEM[k];
  try {
    const raw = localStorage.getItem(k);
    if (raw) { PRAYER_MEM[k] = JSON.parse(raw); return PRAYER_MEM[k]; }
  } catch (e) {}
  return null;
}

/* الجلب — مرةً لكل يوم */
let PRAYER_BUSY = false;

window.fetchPrayerTimes = function (dateISO, force) {
  const c = prayerCfg();
  if (!c.on || !c.city) return Promise.resolve(null);

  const d = dateISO || todayISO();
  const k = prayerKey(d);
  if (!force && prayerTimes(d)) return Promise.resolve(prayerTimes(d));
  if (PRAYER_BUSY) return Promise.resolve(null);

  PRAYER_BUSY = true;
  const dd = d.split("-");
  const url = "https://api.aladhan.com/v1/timingsByCity/" +
    dd[2] + "-" + dd[1] + "-" + dd[0] +
    "?city=" + encodeURIComponent(c.city) +
    "&country=" + encodeURIComponent(c.country) +
    "&method=" + c.method;

  return fetch(url)
    .then(r => r.ok ? r.json() : null)
    .then(j => {
      PRAYER_BUSY = false;
      const t = j && j.data && j.data.timings;
      if (!t) return null;

      /* الوقت يأتي «16:24 (+03)» أحياناً — يُقتطع منه HH:MM */
      const clean = {};
      PRAYERS.forEach(p => {
        const m = String(t[p.k] || "").match(/(\d{1,2}):(\d{2})/);
        if (m) clean[p.k] = m[1].padStart(2, "0") + ":" + m[2];
      });
      clean.date = d;
      clean.city = c.city;

      PRAYER_MEM[k] = clean;
      try { localStorage.setItem(k, JSON.stringify(clean)); } catch (e) {}
      return clean;
    })
    .catch(() => { PRAYER_BUSY = false; return null; });
};

/* دقائق من "HH:MM" */
/* =========================================================================
   وقتُ الساعة المنطقيّ — «حدّد الوقت المنطقيّ للساعة»
   -------------------------------------------------------------------------
   خانتا وقت البداية والنهاية كانتا تقبلان أيَّ أربعة أرقام، فكُتب «51:56».
   فصارت الساعةُ من 00 إلى 23 والدقيقةُ من 00 إلى 59 أثناء الكتابة:
   رقمُ ساعةٍ لا يصحّ بعده رقمٌ ثانٍ (3 فما فوق، أو 24 فما فوق) يُفهم ساعةً
   من رقمٍ واحد (5 ← 05)، ورقمُ دقيقةٍ أوّلُه فوق 5 لا يُقبل. وعند مغادرة
   الخانة يُكمَل الوقتُ بصيغة HH:MM.
   ========================================================================= */
window.clockMask = function (el, done) {
  if (!el) return;
  const d = String(el.value || "").replace(/[^0-9]/g, "");
  let h = "", rest = "";
  if (d.length) {
    if (Number(d[0]) > 2) { h = "0" + d[0]; rest = d.slice(1); }
    /* «25» ساعةٌ لا تصحّ: يُرفض الرقمُ الثاني ويبقى «2» حتى يُكتب صحيحٌ بعده —
       كانت تُقرأ «02» ويصير الخامسُ دقيقةً فيُكتب «25:70» «02:57» (٤٤٠) */
    else if (d.length >= 2 && Number(d.slice(0, 2)) > 23) { h = d[0]; rest = ""; }
    else { h = d.slice(0, 2); rest = d.slice(2); }
  }
  if (rest && Number(rest[0]) > 5) rest = rest.slice(1);
  const m = rest.slice(0, 2);
  let v = h.length === 2 && (m.length || d.length > 2) ? h + ":" + m : h;
  if (done && h) v = ("0" + Number(h)).slice(-2) + ":" + ("0" + (Number(m) || 0)).slice(-2);
  el.value = v;
};
function clockValid(t) { return /^([01]\d|2[0-3]):[0-5]\d$/.test(String(t || "")); }

function hhmmToMin(t) {
  const m = String(t || "").match(/^(\d{1,2}):(\d{2})/);
  return m ? Number(m[1]) * 60 + Number(m[2]) : null;
}
function minToHhmm(n) {
  const v = Math.max(0, Math.min(1439, Math.round(n)));
  return String(Math.floor(v / 60)).padStart(2, "0") + ":" + String(v % 60).padStart(2, "0");
}

/* =========================================================================
   وقت الحلقة: ثابتٌ أو محسوبٌ من أذان
   -------------------------------------------------------------------------
   الحلقة تحمل إمّا start ثابتاً، وإمّا anchor (اسم الصلاة) و offset (دقائق
   بعدها). المحسوب يتغيّر مع الأذان يوماً بيوم.
   ========================================================================= */
/* تبديل وضع التوقيت في النموذج — الحقول تظهر بحسب الاختيار */
window.circleTimeMode = function (pre, mode) {
  const on = mode === "anchor";
  ["A", "B"].forEach(x => {
    const el = document.getElementById(pre + "_fixed" + x);
    if (el) el.style.display = on ? "none" : "";
  });
  ["A", "B", "C"].forEach(x => {
    const el = document.getElementById(pre + "_anch" + x);
    if (el) el.style.display = on ? "" : "none";
  });
};

function circleStartAt(c, dateISO) {
  if (!c) return null;

  if (c.anchor) {
    const t = prayerTimes(dateISO);
    const base = t && t[c.anchor] ? hhmmToMin(t[c.anchor]) : null;
    if (base != null) return minToHhmm(base + (Number(c.offset) || 0));
    /* لا مواقيت بعد: يُرجَع الثابت إن وُجد بدل الامتناع */
    return c.start || null;
  }
  return c.start || null;
}

/* نهاية الحلقة: صلاةُ الختام إن حُدّدت، وإلا end الثابت */
function circleEndAt(c, dateISO) {
  if (!c) return null;
  if (c.endAnchor) {
    const t = prayerTimes(dateISO);
    const base = t && t[c.endAnchor] ? hhmmToMin(t[c.endAnchor]) : null;
    if (base != null) return minToHhmm(base + (Number(c.endOffset) || 0));
  }
  return c.end || null;
}

/* وصفٌ مقروء: «بعد العصر بـ١٥ دقيقة (١٦:٣٩)» */
function circleTimeText(c, dateISO) {
  if (!c) return "—";
  if (!c.anchor) return c.start || "—";
  const off = Number(c.offset) || 0;
  const at = circleStartAt(c, dateISO);
  return "بعد " + prayerAr(c.anchor) +
    (off ? " بـ" + toArabicDigits(off) + " دقيقة" : "") +
    (at ? " (" + at + ")" : "");
}

/* =========================================================================
   الإجازة التلقائية
   -------------------------------------------------------------------------
   المواصفات: «إذا انتهى وقت الحلقة ولم يحضّر المعلّم نفسه ولم يسجّل حضوراً
   لطلابه، يتعرّف النظام أن اليوم إجازة، ويحوّل حالة اليوم إلى (إجازة) لكي
   لا يتأثّر الطلاب ولا تُحسب عليهم متأخّرات تعويضية».
   ========================================================================= */
function autoHolidayScan(dateISO) {
  const d = dateISO || todayISO();
  if (d !== todayISO()) return 0;          /* الماضي لا يُحكم عليه هنا */

  const now = new Date();
  const nowMin = now.getHours() * 60 + now.getMinutes();

  let made = 0;

  (cur("circles") || []).forEach(c => {
    if (!c || c.status === "متوقف") return;

    /* يوم ليس من أيام الحلقة أصلاً: ليس إجازةً طارئة */
    const days = daysToArray(c.days);
    const day = dayNameOf(d);
    if (days.length && day && days.indexOf(day) === -1) return;

    const endT = circleEndAt(c, d);
    const endMin = hhmmToMin(endT);
    if (endMin == null || nowMin < endMin) return;   /* لم ينتهِ وقتها بعد */

    /* هل سُجّل شيء؟ حضور المعلّم أو أحد طلابه */
    const cids = String(c.id);
    const anyStaff = (cur("attendance") || []).some(a =>
      a && a.staffId && String(a.date) === d &&
      (String(a.circleId) === cids || String(a.staffId) === String(c.teacherId)));
    const anyStu = (cur("attendance") || []).some(a =>
      a && !a.staffId && String(a.date) === d && String(a.circleId) === cids);

    if (anyStaff || anyStu) return;

    /* لا شيء: يُعلَّم اليوم إجازةً اضطرارية */
    const id = "hol_" + d + "__" + c.id;
    if ((cur("workflow") || []).some(x => String(x.id) === id)) return;

    const rec = {
      id, type: "holiday", date: d,
      circleId: String(c.id), circle: c.name || "",
      mosqueId: c.mosqueId || "", complexId: c.complexId || STATE.complexId || "",
      reason: "لم يُسجَّل حضور المعلّم ولا الطلاب حتى انتهاء وقت الحلقة",
      auto: true, ts: Date.now(),
      termId: typeof activeTermId === "function" ? activeTermId() : ""
    };

    if (!Array.isArray(DB.workflow)) DB.workflow = [];
    DB.workflow.push(rec);
    persistSet("workflow", rec);
    made++;
  });

  return made;
}

/* هل اليوم إجازة لحلقة؟ يُقرأ في التحضير والتعويض */
function isHoliday(circleId, dateISO) {
  const id = "hol_" + (dateISO || todayISO()) + "__" + circleId;
  return (cur("workflow") || []).some(x => x && String(x.id) === id);
}

/* رفع الإجازة يدوياً — قد يكون التأخّر عذراً لا انقطاعاً */
window.holidayClear = function (circleId, dateISO) {
  const id = "hol_" + (dateISO || todayISO()) + "__" + circleId;
  const i = (DB.workflow || []).findIndex(x => String(x.id) === id);
  if (i < 0) return;
  DB.workflow.splice(i, 1);
  persistDelete("workflow", id);
  showToast("رُفعت الإجازة عن الحلقة", "success");
  mount();
};

/* =========================================================================
   المعلّم المساعد
   -------------------------------------------------------------------------
   المواصفات تعدّه في «أمور أخرى مهمة» بلا شرح. والمعنى العملي: معلّمٌ ثانٍ
   في الحلقة يعمل فيها كالأصيل — يحضّر ويسمّع ويرصد — دون أن يكون مسؤولها.

   الفارق بينه وبين الأصيل ثلاثة:
     • لا يرث طلابُ الحلقة اسمَه، فهم منسوبون إلى معلّمها.
     • لا يُحتسب دوامه على هذه الحلقة إن كان له حلقته الأصلية.
     • لا يظهر في التقارير معلّماً للحلقة.

   والصلاحية تُقرأ من myCircles — بوّابة كلّ ما يراه المعلّم.
   ========================================================================= */

/* معلّمو المسجد المتاحون للمساعدة — عدا معلّم الحلقة نفسه */
function assistantPool(c) {
  const mine = String((c && c.teacherId) || "");
  return (cur("teachers") || []).filter(t =>
    t && t.active !== false && String(t.id) !== mine);
}

function assistantsOf(c) {
  const ids = Array.isArray(c && c.assistants) ? c.assistants : [];
  return ids.map(id => (cur("teachers") || []).find(t => String(t.id) === String(id)))
            .filter(Boolean);
}

/* الحلقات التي أُسند إليها معلّمٌ مساعداً — تُعرض في ملفّه */
function assistIn(teacherId) {
  return (cur("circles") || []).filter(c =>
    Array.isArray(c.assistants) && c.assistants.indexOf(String(teacherId)) > -1);
}

window.asstOpen = function (circleId) {
  const c = (cur("circles") || []).find(x => String(x.id) === String(circleId));
  if (!c) return;

  const pool = assistantPool(c);
  const on = new Set((c.assistants || []).map(String));

  if (!pool.length) {
    openModal("المعلّمون المساعدون", c.name || "",
      noteCard("لا معلّمين آخرين في النظام لإسنادهم مساعدين."),
      `<button class="btn btn-ghost" data-action="close-modal">إغلاق</button>`);
    return;
  }

  openModal("المعلّمون المساعدون", c.name || "",
    `<input type="hidden" id="as_cid" value="${esc(c.id)}">
     ${noteCard(`المساعد يعمل في الحلقة كالأصيل: يحضّر ويسمّع ويرصد الواجبات.
       <br>لكنّ طلابها يبقَون منسوبين إلى <strong>${esc(c.teacher || "معلّمها")}</strong>،
       ولا يُحتسب دوامه عليها.`)}

     <div class="asst-list">
       ${pool.map(t => `<label class="asst-row${on.has(String(t.id)) ? " on" : ""}">
         <input type="checkbox" value="${esc(t.id)}"${on.has(String(t.id)) ? " checked" : ""}
           onchange="this.closest('.asst-row').classList.toggle('on',this.checked)">
         <div class="mini-avatar">${initials(t.name)}</div>
         <div class="asst-info"><strong>${esc(t.name || "—")}</strong>
           <small>${esc(t.circle || t.mosque || "—")}</small></div>
       </label>`).join("")}
     </div>`,
    `<button class="btn btn-primary" onclick="window.asstSave()">حفظ</button>
     <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
};

window.asstSave = function () {
  const id = val("#as_cid");
  const c = (cur("circles") || []).find(x => String(x.id) === String(id));
  if (!c) return;

  const box = document.querySelector(".asst-list");
  const picked = box ? [...box.querySelectorAll("input:checked")].map(x => String(x.value)) : [];

  const before = (c.assistants || []).length;
  const wasList = (c.assistants || []).slice();
  c.assistants = picked;
  persistSet("circles", c);

  /* نطاق كلّ من أُضيف أو أُزيل: المساعد يكتب في الحلقة كالأصيل */
  try {
    if (typeof syncTeacherScope === "function") {
      [...new Set(wasList.concat(picked))].forEach(id => syncTeacherScope(id));
    }
  } catch (e) {}

  closeModal();
  showToast(picked.length
    ? "أُسند " + toArabicDigits(picked.length) + " معلّماً مساعداً"
    : (before ? "أُلغي المساعدون" : "لم يُسند أحد"), "success");
  mount();
};

/* =========================================================================
   القبول والتسجيل — طالب الانتظار
   -------------------------------------------------------------------------
   المواصفات: «استقبال طلبات الالتحاق الجديدة بالمسجد من الطلاب المستجدّين،
   فرزها، إجراء المقابلات الأوّلية لهم، وقبولهم أو رفضهم تحضيراً لتوزيعهم
   على الحلقات».

   وكان الطالب يُضاف مباشرةً إلى الحلقة: لا طابور ولا فرز ولا مقابلة، ومن
   لم تسعه حلقةٌ لم يبقَ له أثر — يُنسى أو يُدوَّن في ورقة خارج النظام.

   الطلب يمرّ بأربع حالات: جديد ← مقابلة ← مقبول ← موزَّع. والمرفوض يبقى
   في السجل، فمن اعتُذر له مرةً قد يُقبل لاحقاً وتُعرف قصّته.
   ========================================================================= */

const ADM_STATES = [
  { k: "new",       h: "طلب جديد",        tint: "b-amber" },
  { k: "interview", h: "بانتظار مقابلة",  tint: "b-blue"  },
  { k: "accepted",  h: "مقبول — بانتظار حلقة", tint: "b-teal" },
  { k: "enrolled",  h: "التحق بحلقة",     tint: "b-green" },
  { k: "rejected",  h: "معتذَر عنه",      tint: "b-gray"  }
];

function admStateAr(k) { return (ADM_STATES.find(x => x.k === k) || {}).h || k; }


const ADM = { tab: "new", q: "" };
window.admTab = function (t) { ADM.tab = t; mount(); };
window.admSearch = function (v) { ADM.q = String(v || "").trim(); mount(); };

function admList(state) {
  let l = (cur("admissions") || []).filter(a => a && (!state || a.state === state));
  if (ADM.q) l = l.filter(a => String(a.name || "").indexOf(ADM.q) > -1 ||
                               String(a.phone || "").indexOf(ADM.q) > -1);
  return l.sort((a, b) => (a.ts || 0) - (b.ts || 0));
}

function admCount(state) {
  return (cur("admissions") || []).filter(a => a && a.state === state).length;
}

/* =========================================================================
   الطلب
   ========================================================================= */
window.admForm = function (id) {
  const a = id ? (cur("admissions") || []).find(x => String(x.id) === String(id)) : null;
  const mosques = cur("mosques") || [];

  openModal(a ? "تعديل الطلب" : "طلب التحاق جديد", a ? (a.name || "") : "",
    `<input type="hidden" id="ad_id" value="${a ? esc(a.id) : ""}">
     <div class="form-grid">
       <div class="field full"><label>اسم الطالب <span class="req">*</span></label>
         <input id="ad_name" value="${a ? esc(a.name || "") : ""}"></div>

       <div class="field"><label>تاريخ الميلاد</label>
         <input id="ad_birth" type="date" value="${a ? esc(a.birth || "") : ""}"></div>

       <div class="field"><label>جوال ولي الأمر <span class="req">*</span></label>
         <input id="ad_phone" dir="ltr" value="${a ? esc(a.phone || "") : ""}"
           placeholder="05xxxxxxxx"></div>

       <div class="field"><label>اسم ولي الأمر</label>
         <input id="ad_parent" value="${a ? esc(a.parent || "") : ""}"></div>

       <div class="field"><label>المسجد المطلوب</label>
         <select id="ad_mosque">
           <option value="">— أيّ مسجد —</option>
           ${mosques.map(m => `<option value="${esc(m.id)}"${
             a && String(a.mosqueId) === String(m.id) ? " selected" : ""}>${esc(m.name)}</option>`).join("")}
         </select></div>

       <div class="field"><label>المحفوظ السابق</label>
         <input id="ad_prev" value="${a ? esc(a.prev || "") : ""}"
           placeholder="مثال: جزء عمّ"></div>

       <div class="field full"><label>ملاحظة</label>
         <input id="ad_note" value="${a ? esc(a.note || "") : ""}"
           placeholder="ما يُذكر عند التسجيل"></div>
     </div>`,
    `<button class="btn btn-primary" onclick="window.admSave()">${a ? "حفظ" : "تسجيل الطلب"}</button>
     <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
};

window.admSave = function () {
  const id = val("#ad_id");
  const name = (val("#ad_name") || "").trim();
  if (!name) { showToast("اسم الطالب مطلوب", "warn"); return; }

  const phone = (val("#ad_phone") || "").trim();
  if (!phone) { showToast("جوال ولي الأمر مطلوب — به يُبلَّغ بالقبول", "warn"); return; }

  const old = id ? (cur("admissions") || []).find(x => String(x.id) === String(id)) : null;

  /* اسمٌ وجوالٌ مكرّران: طلبٌ ثانٍ لطالبٍ مسجَّل — يُنبَّه ولا يُمنع */
  if (!old) {
    const dup = (cur("admissions") || []).find(x =>
      x && String(x.phone) === phone && nameKey(x.name) === nameKey(name) &&
      x.state !== "rejected");
    if (dup) { showToast("له طلبٌ قائم بالفعل — حالته: " + admStateAr(dup.state), "warn"); return; }
  }

  const m = (cur("mosques") || []).find(x => String(x.id) === String(val("#ad_mosque")));

  const rec = Object.assign({}, old || {}, {
    id: id || "ad" + Date.now(),
    name, phone,
    birth: val("#ad_birth") || "",
    parent: val("#ad_parent") || "",
    mosqueId: val("#ad_mosque") || "",
    mosque: m ? m.name : "",
    prev: val("#ad_prev") || "",
    note: val("#ad_note") || "",
    state: old ? old.state : "new",
    complexId: STATE.complexId || "",
    termId: typeof activeTermId === "function" ? activeTermId() : "",
    ts: old ? old.ts : Date.now()
  });

  if (!Array.isArray(DB.admissions)) DB.admissions = [];
  const i = DB.admissions.findIndex(x => String(x.id) === String(rec.id));
  if (i > -1) DB.admissions[i] = rec; else DB.admissions.push(rec);
  persistSet("admissions", rec);

  closeModal();
  showToast(id ? "حُدّث الطلب" : "سُجّل الطلب — في طابور الانتظار", "success");
  mount();
};

/* =========================================================================
   المقابلة
   ========================================================================= */
window.admInterview = function (id) {
  const a = (cur("admissions") || []).find(x => String(x.id) === String(id));
  if (!a) return;

  openModal("المقابلة الأوّلية", a.name || "",
    `<input type="hidden" id="iv_id" value="${esc(a.id)}">
     ${noteCard(`ما يُرصد هنا يُنقل إلى ملفّ الطالب عند قبوله، فلا يُعاد سؤاله.`)}
     <div class="form-grid">
       <div class="field"><label>مستوى الحفظ</label>
         <input id="iv_level" value="${esc(a.ivLevel || a.prev || "")}"
           placeholder="ما يحفظه فعلاً"></div>
       <div class="field"><label>جودة التلاوة</label>
         <select id="iv_read">
           ${["ممتازة", "جيدة", "تحتاج تحسيناً", "مبتدئ"].map(x =>
             `<option${a.ivRead === x ? " selected" : ""}>${x}</option>`).join("")}</select></div>
       <div class="field full"><label>ملاحظات المقابلة</label>
         <input id="iv_note" value="${esc(a.ivNote || "")}"
           placeholder="ما لوحظ — يظهر لمن يوزّعه على الحلقات"></div>
     </div>`,
    `<button class="btn btn-primary" onclick="window.admInterviewDo('accepted')">
       أُجريت — قبول</button>
     <button class="btn btn-danger" onclick="window.admInterviewDo('rejected')">اعتذار</button>
     <button class="btn btn-ghost" data-action="close-modal">إغلاق</button>`);
};

window.admInterviewDo = function (state) {
  const a = (cur("admissions") || []).find(x => String(x.id) === String(val("#iv_id")));
  if (!a) return;

  a.ivLevel = val("#iv_level") || "";
  a.ivRead = val("#iv_read") || "";
  a.ivNote = val("#iv_note") || "";
  a.ivAt = Date.now();
  a.ivBy = ((STATE && STATE.user) || {}).name || "";
  a.state = state;
  if (state === "rejected") a.rejectedAt = Date.now();
  persistSet("admissions", a);

  /* القبول يُبلَّغ به وليّ الأمر — الطلب الصامت يُنسي صاحبه */
  try {
    if (state === "accepted" && typeof msgFire === "function") {
      msgFire("accepted", { student: { id: a.id, name: a.name, parent: a.phone },
                            name: a.name, date: todayISO() });
    }
  } catch (e) {}

  closeModal();
  showToast(state === "accepted" ? "قُبل — بانتظار توزيعه على حلقة" : "اعتُذر عنه", "success");
  mount();
};

window.admState = function (id, state) {
  const a = (cur("admissions") || []).find(x => String(x.id) === String(id));
  if (!a) return;
  a.state = state;
  persistSet("admissions", a);
  showToast("نُقل إلى: " + admStateAr(state), "success");
  mount();
};

/* =========================================================================
   الالتحاق بحلقة — يصير طالباً
   ========================================================================= */
window.admEnroll = function (id) {
  const a = (cur("admissions") || []).find(x => String(x.id) === String(id));
  if (!a) return;

  /* الحلقات المتاحة: غير المكتملة، ومن المسجد المطلوب إن حُدّد */
  let circles = (cur("circles") || []).filter(c => c && c.status !== "متوقف");
  if (a.mosqueId) {
    const inM = circles.filter(c => String(c.mosqueId) === String(a.mosqueId));
    if (inM.length) circles = inM;
  }

  const rows = circles.map(c => {
    const n = typeof circleCount === "function" ? circleCount(c) : 0;
    const full = typeof circleFull === "function" ? circleFull(c) : false;
    return `<label class="asst-row${full ? " off" : ""}">
      <input type="radio" name="enCircle" value="${esc(c.id)}"${full ? " disabled" : ""}>
      <div class="asst-info"><strong>${esc(c.name)}</strong>
        <small>${esc(c.teacher || "بلا معلّم")} · ${toArabicDigits(n)}${
          c.capacity ? " من " + toArabicDigits(c.capacity) : ""} طالباً${
          full ? " — مكتملة" : ""}</small></div>
    </label>`;
  }).join("");

  openModal("توزيعه على حلقة", a.name || "",
    `<input type="hidden" id="en_id" value="${esc(a.id)}">
     ${a.ivNote ? noteCard(`<strong>من المقابلة:</strong> ${esc(a.ivNote)}${
       a.ivLevel ? " · يحفظ: " + esc(a.ivLevel) : ""}`) : ""}
     ${circles.length
       ? `<div class="asst-list">${rows}</div>`
       : noteCard("لا حلقات متاحة. أنشئ حلقةً أو ارفع سعة القائمة.")}`,
    (circles.length
      ? `<button class="btn btn-primary" onclick="window.admEnrollDo()">إلحاقه</button>` : "") +
    `<button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
};

window.admEnrollDo = function () {
  const a = (cur("admissions") || []).find(x => String(x.id) === String(val("#en_id")));
  if (!a) return;

  const el = document.querySelector('input[name="enCircle"]:checked');
  if (!el) { showToast("اختر الحلقة", "warn"); return; }

  const c = (cur("circles") || []).find(x => String(x.id) === String(el.value));
  if (!c) return;

  if (typeof circleFull === "function" && circleFull(c)) {
    showToast("الحلقة مكتملة — اختر غيرها", "warn"); return;
  }

  /* ما رُصد في المقابلة يُنقل إلى ملفّه فلا يُعاد سؤاله */
  const st = {
    id: "st" + Date.now(),
    name: a.name, phone: a.phone, parent: a.phone,
    birth: a.birth || "",
    age: (typeof ageFromBirth === "function" && a.birth)
      ? String(ageFromBirth(a.birth) ?? "—") : "—",
    circle: c.name, circleId: String(c.id),
    teacher: c.teacher || "", teacherId: c.teacherId || "",
    mosque: c.mosque || a.mosque || "", mosqueId: c.mosqueId || a.mosqueId || "",
    complexId: c.complexId || STATE.complexId || "",
    days: typeof circleDaysOf === "function" ? circleDaysOf(c.name) : "",
    attType: "دوام كامل",
    note: [a.ivNote, a.note].filter(Boolean).join(" · "),
    prev: a.ivLevel || a.prev || "",
    status: "نشط",
    admissionId: String(a.id),
    joinedAt: Date.now(),
    termId: typeof activeTermId === "function" ? activeTermId() : "",
    points: 0, balance: 0
  };

  if (!Array.isArray(DB.students)) DB.students = [];
  DB.students.push(st);
  persistSet("students", st);

  a.state = "enrolled";
  a.studentId = st.id;
  a.enrolledAt = Date.now();
  persistSet("admissions", a);

  closeModal();
  showToast("التحق " + a.name + " بحلقة " + c.name, "success");
  mount();
};

window.admDelete = function (id) {
  const a = (cur("admissions") || []).find(x => String(x.id) === String(id));
  if (!a) return;

  openModal("حذف الطلب", a.name || "",
    noteCard(`سيُحذف الطلب نهائياً.` + (a.state === "enrolled"
      ? " <strong>وقد التحق بحلقة</strong> — ملفّه كطالب لا يُحذف." : "")),
    `<button class="btn btn-danger" onclick="window.admDeleteDo('${jsAttr(id)}')">حذف</button>
     <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
};

window.admDeleteDo = function (id) {
  const i = (DB.admissions || []).findIndex(x => String(x.id) === String(id));
  if (i > -1) { DB.admissions.splice(i, 1); persistDelete("admissions", id); }
  closeModal();
  showToast("حُذف الطلب", "success");
  mount();
};

/* =========================================================================
   الشاشة
   ========================================================================= */
function adminAdmissions() {
  const tabs = ADM_STATES.map(x => [x.k, x.h, admCount(x.k)]);
  const list = admList(ADM.tab);

  const since = ts => {
    const d = Math.floor((Date.now() - (ts || Date.now())) / 86400000);
    return d < 1 ? "اليوم" : "منذ " + toArabicDigits(d) + " يوم";
  };

  const rows = list.length ? list.map(a => `<tr>
    <td><strong>${esc(a.name || "—")}</strong>
      ${a.birth && typeof ageFromBirth === "function"
        ? `<div class="muted" style="font-size:11px">${
            toArabicDigits(ageFromBirth(a.birth) ?? "—")} سنة</div>` : ""}</td>
    <td dir="ltr" class="pt-num" style="font-size:12px">${esc(a.phone || "—")}</td>
    <td class="muted">${esc(a.mosque || "أيّ مسجد")}</td>
    <td class="muted" style="font-size:12px">${esc(a.ivLevel || a.prev || "—")}</td>
    <td class="muted" style="font-size:12px">${esc(since(a.ts))}</td>
    <td class="pt-actions">
      ${a.state === "new"
        ? `<button class="btn btn-ghost btn-sm"
            onclick="window.admState('${jsAttr(a.id)}','interview')">لمقابلة</button>` : ""}
      ${a.state === "interview"
        ? `<button class="btn btn-primary btn-sm"
            onclick="window.admInterview('${jsAttr(a.id)}')">إجراء المقابلة</button>` : ""}
      ${a.state === "accepted"
        ? `<button class="btn btn-primary btn-sm"
            onclick="window.admEnroll('${jsAttr(a.id)}')">توزيعه على حلقة</button>` : ""}
      ${a.state === "rejected"
        ? `<button class="btn btn-ghost btn-sm"
            onclick="window.admState('${jsAttr(a.id)}','new')">إعادة فتحه</button>` : ""}
      <button class="row-btn" onclick="window.admForm('${jsAttr(a.id)}')"
        title="تعديل">${ic("edit", 14)}</button>
      <button class="row-btn cp-danger" onclick="window.admDelete('${jsAttr(a.id)}')"
        title="حذف">${ic("trash", 14)}</button>
    </td>
  </tr>`).join("")
    : `<tr><td colspan="6" style="text-align:center;padding:28px" class="muted">
        ${ADM.q ? "لا نتائج للبحث."
          : ADM.tab === "new" ? "لا طلبات جديدة — سجّل طلباً بالزرّ أعلاه."
          : "لا طلبات في هذه المرحلة."}</td></tr>`;

  const waiting = admCount("new") + admCount("interview") + admCount("accepted");

  return `<div class="page">
    ${pageHead("القبول والتسجيل",
      "طلبات الالتحاق: فرزها ومقابلتها وتوزيعها على الحلقات")}

    <div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px;align-items:center">
      <button class="btn btn-primary btn-sm" onclick="window.admForm()">
        ${ic("plus", 15)} طلب التحاق جديد</button>
      ${waiting ? `<span class="adm-wait">${toArabicDigits(waiting)} في طابور الانتظار</span>` : ""}
      <!-- كان الصنف fac-search وهو غير معرَّف: الاسم الصحيح fac-searchbox،
           فظهر الحقل بلا تنسيق كمربّع عارٍ -->
      <div class="fac-searchbox" style="margin-inline-start:auto">
        ${ic("search", 17)}
        <input placeholder="ابحث بالاسم أو الجوال" value="${esc(ADM.q)}"
          oninput="window.admSearch(this.value)"></div>
    </div>

    <div class="fx-tabs">${tabs.map(t =>
      `<button class="fx-tab${ADM.tab === t[0] ? " on" : ""}"
        onclick="window.admTab('${t[0]}')"><span>${esc(t[1])}</span>
        <b>${toArabicDigits(t[2])}</b></button>`).join("")}</div>

    <div class="card">
      <div class="pt-wrap"><div class="pt-scroll"><table class="ptable">
        <thead><tr><th>الطالب</th><th>الجوال</th><th>المسجد</th>
          <th>المحفوظ</th><th>منذ</th><th></th></tr></thead>
        <tbody>${rows}</tbody>
      </table></div></div>
    </div>
  </div>`;
}

/* =========================================================================
   سجلّ الطالب
   -------------------------------------------------------------------------
   المواصفات: «سجل الطالب في ملفه (تواريخ انتقاله — انضمامه — الإنذارات إلخ)».

   وكل هذه الأحداث مسجَّلة بالفعل ومتفرّقة في ستّ مجموعات: القبول في
   admissions، والانضمام في joinedAt، والانتقال في moveLog، والإنذارات في
   procLog، والترقيات في الخطة، والنقاط في pointsLog. فما ينقص ليس بياناتٍ
   تُجمع بل خطٌّ زمنيٌّ يُقرأ.

   ولذلك لا مجموعة جديدة هنا: تُشتقّ من مصادرها فلا تتناقض نسختان، ولا
   يحتاج ماضي الطلاب ترحيلاً.
   ========================================================================= */

const LOG_ICONS = {
  join: "user", admission: "check", move: "swap", promote: "trophy",
  warn: "alert", points: "star", exam: "exam", stop: "pause",
  plan: "plan", freeze: "freeze", message: "chat"
};

const LOG_TINT = {
  join: "t-green", admission: "t-teal", move: "t-blue", promote: "t-gold",
  warn: "t-red", points: "t-purple", exam: "t-blue", stop: "t-red",
  plan: "t-teal", freeze: "t-amber", message: "t-blue"
};

function stuTimeline(studentId) {
  const st = (cur("students") || []).find(x => String(x.id) === String(studentId));
  if (!st) return [];

  const out = [];
  const add = (ts, kind, title, text, by) => {
    if (!ts) return;
    out.push({ ts: Number(ts), kind, title, text: text || "", by: by || "" });
  };

  /* ---------- القبول والالتحاق ---------- */
  const adm = (cur("admissions") || []).find(a =>
    String(a.studentId) === String(st.id) || String(a.id) === String(st.admissionId));
  if (adm) {
    add(adm.ts, "admission", "سُجّل طلب التحاقه",
      adm.mosque ? "المسجد المطلوب: " + adm.mosque : "");
    if (adm.ivAt) {
      add(adm.ivAt, "admission", "أُجريت مقابلته",
        [adm.ivLevel && "يحفظ: " + adm.ivLevel, adm.ivRead && "التلاوة: " + adm.ivRead,
         adm.ivNote].filter(Boolean).join(" · "), adm.ivBy);
    }
    if (adm.rejectedAt) add(adm.rejectedAt, "stop", "اعتُذر عن طلبه", "");
  }

  add(st.joinedAt, "join", "التحق بالحلقة",
    st.circle ? "حلقة " + st.circle + (st.teacher ? " — " + st.teacher : "") : "");

  /* لا joinedAt للطلاب القدامى: يُنسب انضمامه إلى أوّل أثرٍ له */
  if (!st.joinedAt) {
    const first = (cur("attendance") || [])
      .filter(a => a && !a.staffId && String(a.studentId) === String(st.id))
      .map(a => a.date).sort()[0];
    if (first) {
      add(new Date(first + "T08:00:00").getTime(), "join", "أوّل حضورٍ مسجَّل له",
        "لا تاريخ انضمامٍ موثَّق — هذا أقدم أثرٍ في سجلّه");
    }
  }

  /* ---------- الانتقال بين الحلقات ---------- */
  (cur("moveLog") || []).forEach(m => {
    if (String(m.studentId) !== String(st.id)) return;
    add(m.ts || (m.date ? new Date(m.date).getTime() : 0), "move",
      "نُقل بين الحلقات",
      [m.from && "من " + m.from, m.to && "إلى " + m.to, m.reason].filter(Boolean).join(" · "),
      m.by);
  });

  /* ---------- الإنذارات والإجراءات ---------- */
  (cur("procLog") || []).forEach(p => {
    if (String(p.studentId) !== String(st.id)) return;
    add(p.ts, "warn",
      "إجراء " + (p.track === "edu" ? "تعليمي" : "إداري") + " — الخطوة " +
        toArabicDigits(p.step || 1),
      [p.title, p.note].filter(Boolean).join(" · "), p.by);
  });

  /* ---------- الخطة: إنشاؤها وترقيتها وتجميدها ---------- */
  (cur("plans") || []).forEach(p => {
    if (String(p.studentId) !== String(st.id)) return;
    add(p.ts, "plan", "أُسندت له خطة",
      [p.program, p.level].filter(Boolean).join(" — "));
    if (p.promotedAt) {
      add(p.promotedAt, "promote", "رُقّي إلى " + (p.level || "مستوى جديد"),
        p.promotedFrom ? "من " + p.promotedFrom : "", p.promotedBy);
    }
    if (p.frozenAt) add(p.frozenAt, "freeze", "جُمّدت خطته",
      p.freezeReason || "", p.frozenBy);
    if (p.unfrozenAt) add(p.unfrozenAt, "plan", "فُكّ تجميد خطته", "");
  });

  /* ---------- الاختبارات ---------- */
  (cur("exams") || []).forEach(e => {
    if (String(e.studentId) !== String(st.id)) return;
    if (e.stage !== "approved" && !e.approvedAt) return;
    add(e.approvedAt || e.ts, "exam", "اجتاز اختباراً",
      [e.level, e.score != null ? toArabicDigits(e.score) + "٪" : ""].filter(Boolean).join(" · "));
  });

  /* ---------- النقاط: الكبيرة منها فقط ---------- */
  (cur("pointsLog") || []).forEach(p => {
    if (String(p.studentId) !== String(st.id)) return;
    /* الصغيرة اليومية تُغرق الخطّ الزمني — تُعرض المؤثّرة وحدها */
    if (Math.abs(Number(p.n) || 0) < 20) return;
    add(p.ts, "points", (p.n > 0 ? "مُنح " : "خُصم ") + toArabicDigits(Math.abs(p.n)) + " نقطة",
      p.why || "", p.by);
  });

  /* ---------- الإيقاف ---------- */
  add(st.stoppedAt, "stop", "أُوقف قيده", st.stoppedReason || "");

  return out.sort((a, b) => b.ts - a.ts);
}

/* عرض السجلّ */
window.stuLog = function (studentId) {
  const st = (cur("students") || []).find(x => String(x.id) === String(studentId));
  if (!st) { showToast("لم يُعثر على الطالب", "warn"); return; }

  const items = stuTimeline(studentId);

  const when = ts => {
    const d = new Date(ts);
    return d.toLocaleDateString("ar-EG", { year: "numeric", month: "long", day: "numeric" });
  };

  const body = items.length
    ? `<div class="tl">${items.map(x => `<div class="tl-item">
        <span class="tl-dot ${esc(LOG_TINT[x.kind] || "t-teal")}">${
          ic(LOG_ICONS[x.kind] || "info", 14)}</span>
        <div class="tl-body">
          <div class="tl-head"><strong>${esc(x.title)}</strong>
            <small>${esc(when(x.ts))}</small></div>
          ${x.text ? `<div class="tl-text">${esc(x.text)}</div>` : ""}
          ${x.by ? `<div class="tl-by">${esc(x.by)}</div>` : ""}
        </div>
      </div>`).join("")}</div>`
    : emptyState("لا أحداث مسجَّلة",
        "يُبنى السجلّ من أحداث الطالب: التحاقه وانتقاله وترقياته وإجراءاته.");

  openModal("سجلّ " + (st.name || "الطالب"),
    items.length ? toArabicDigits(items.length) + " حدثاً" : "",
    body,
    `<button class="btn btn-ghost" data-action="close-modal">إغلاق</button>`);
};

/* =========================================================================
   لوحة شرف الطلاب — واجهة الداعم
   -------------------------------------------------------------------------
   المواصفات: «داعم المسجد — الصلاحية: [قراءة فقط]. العمليات: الاطّلاع على
   لوحة شرف الطلاب، تقارير الحضور والإنجاز الخاصة بطلاب هذا المسجد تحديداً،
   وتقارير صرف الدعم المالي (إن وجد) دون صلاحية للتعديل».

   والدور لم يكن موجوداً أصلاً في USER_ROLES، فلا حساب يُنشأ به ولا واجهة
   يراها. ومن أنفق على مسجدٍ من حقّه أن يرى ثمرة إنفاقه.

   والقراءة هنا محضة: لا زرّ يعدّل ولا يحذف، والنطاق محصورٌ بمسجده — فلا
   يرى طلاب غيره.
   ========================================================================= */

/* مسجد الداعم: من ملفّه، وإلا كلّ ما يتبع مجمّعه */
function donorMosques() {
  const u = (STATE && STATE.user) || {};
  const all = cur("mosques") || [];

  if (u.mosqueId) return all.filter(m => String(m.id) === String(u.mosqueId));
  if (Array.isArray(u.mosqueIds) && u.mosqueIds.length) {
    return all.filter(m => u.mosqueIds.indexOf(String(m.id)) > -1);
  }
  if (u.complexId) return all.filter(m => String(m.complexId) === String(u.complexId));
  return all;
}

/* طلاب نطاقه — مباشرةً أو عبر حلقات مساجده */
function donorStudents() {
  const ids = donorMosques().map(m => String(m.id));
  if (!ids.length) return [];

  const cids = (cur("circles") || [])
    .filter(c => ids.indexOf(String(c.mosqueId)) > -1)
    .map(c => String(c.id));

  return (cur("students") || []).filter(s =>
    s && s.status !== "متوقف" &&
    (ids.indexOf(String(s.mosqueId)) > -1 || cids.indexOf(String(s.circleId)) > -1));
}

/* =========================================================================
   الترتيب
   -------------------------------------------------------------------------
   لا يُرتَّبون بالنقاط وحدها: النقاط تُمنح يدوياً فقد تتحيّز. الترتيب من
   ثلاثة يقيسها النظام نفسه: الحفظ المنجز، والمواظبة، وجودة التسميع.
   ========================================================================= */
const HONOR_SORTS = [
  { k: "score",   h: "الأفضل عموماً" },
  { k: "hifz",    h: "الأكثر حفظاً" },
  { k: "attend",  h: "الأكثر مواظبة" },
  { k: "quality", h: "الأعلى تقييماً" },
  { k: "points",  h: "الأكثر نقاطاً" }
];

const HONOR = { sort: "score", days: 30, mosque: "" };
window.honorSet = function (k, v) {
  HONOR[k] = (k === "days") ? (Number(v) || 30) : String(v || "");
  mount();
};

function honorRows() {
  const since = new Date(Date.now() - HONOR.days * 86400000).toISOString().slice(0, 10);
  let studs = donorStudents();

  if (HONOR.mosque) {
    const cids = (cur("circles") || [])
      .filter(c => String(c.mosqueId) === String(HONOR.mosque)).map(c => String(c.id));
    studs = studs.filter(s => String(s.mosqueId) === String(HONOR.mosque) ||
                              cids.indexOf(String(s.circleId)) > -1);
  }

  const rows = studs.map(s => {
    const recs = (cur("recitations") || []).filter(r =>
      String(r.studentId) === String(s.id) && String(r.date) >= since);

    const faces = recs.reduce((n, r) => n + (Number(r.faces) || 0), 0);

    const scored = recs.map(r => typeof reciteScore === "function" ? reciteScore(r) : null)
                       .filter(v => v != null);
    const quality = scored.length
      ? Math.round(scored.reduce((a, b) => a + b, 0) / scored.length) : 0;

    const att = (cur("attendance") || []).filter(a =>
      a && !a.staffId && String(a.studentId) === String(s.id) && String(a.date) >= since);
    const present = att.filter(a => a.status === "حاضر" || a.status === "متأخر").length;
    const attend = att.length ? Math.round(present * 100 / att.length) : 0;

    /* الدرجة العامّة: الحفظ نصفها، والمواظبة والجودة ربعان.
       الحفظ يُقاس بالأوجه، ويُسقَف عند الثلاثين وجهاً في الشهر لئلّا يطغى
       من سمّع كثيراً على من أتقن. */
    const hifzPct = Math.min(100, Math.round((faces / 30) * 100));
    const score = Math.round(hifzPct * 0.5 + attend * 0.25 + quality * 0.25);

    return {
      st: s, faces, quality, attend, score,
      points: Number(s.balance) || Number(s.points) || 0,
      sessions: recs.length
    };
  }).filter(r => r.faces || r.sessions || r.points);

  const key = HONOR.sort === "hifz" ? "faces"
            : HONOR.sort === "attend" ? "attend"
            : HONOR.sort === "quality" ? "quality"
            : HONOR.sort === "points" ? "points" : "score";

  return rows.sort((a, b) => (b[key] || 0) - (a[key] || 0));
}

function donorHonor() {
  /* قواعدُ الخادم لا تُجيز للداعم قراءةَ بيانات الطلاب بعد — يُقال ذلك صراحةً (٤٢٩) */
  if ((window.__READ_DENIED || []).indexOf("students") > -1 && !(cur("students") || []).length)
    return `<div class="page">${pageHead("لوحة الشرف", "")}<div class="card">${emptyState("لا تتوفّر البيانات لحسابك بعد",
      "صلاحيةُ الداعم لقراءة بيانات الطلاب لم تُفعَّل في قواعد النظام. راجع الإدارة لتفعيلها.")}</div></div>`;
  const rows = honorRows();
  const mosques = donorMosques();
  const top = rows.slice(0, 3);
  const rest = rows.slice(3, 30);

  const medal = i => ["🥇", "🥈", "🥉"][i] || "";

  const card = (r, i) => `<div class="hn-top hn-${i + 1}">
    <div class="hn-medal">${medal(i)}</div>
    <div class="hn-avatar">${initials(r.st.name)}</div>
    <strong>${esc(r.st.name || "—")}</strong>
    <small>${esc(r.st.circle || "—")}</small>
    <div class="hn-score">${toArabicDigits(r.score)}</div>
    <div class="hn-meta">
      <span>${toArabicDigits(r.faces)} وجه</span>
      <span>${toArabicDigits(r.attend)}٪ حضور</span>
      ${r.quality ? `<span>${toArabicDigits(r.quality)}٪ تقييم</span>` : ""}
    </div>
  </div>`;

  return `<div class="page">
    ${pageHead("لوحة شرف الطلاب",
      "المتميّزون في الحفظ والمواظبة وجودة التسميع")}

    <div class="hn-bar">
      ${mosques.length > 1 ? `<select class="filter-sel"
        onchange="window.honorSet('mosque',this.value)">
        <option value="">كلّ المساجد</option>
        ${mosques.map(m => `<option value="${esc(m.id)}"${
          HONOR.mosque === String(m.id) ? " selected" : ""}>${esc(m.name)}</option>`).join("")}
      </select>` : ""}

      <select class="filter-sel" onchange="window.honorSet('sort',this.value)">
        ${HONOR_SORTS.map(x => `<option value="${esc(x.k)}"${
          HONOR.sort === x.k ? " selected" : ""}>${esc(x.h)}</option>`).join("")}
      </select>

      <select class="filter-sel" onchange="window.honorSet('days',this.value)">
        ${[[7, "آخر أسبوع"], [30, "آخر شهر"], [90, "آخر ثلاثة أشهر"], [365, "آخر سنة"]]
          .map(d => `<option value="${d[0]}"${HONOR.days === d[0] ? " selected" : ""}>${
            esc(d[1])}</option>`).join("")}
      </select>
    </div>

    ${top.length
      ? `<div class="hn-podium">${top.map(card).join("")}</div>`
      : `<div class="card">${emptyState("لا بيانات بعد",
          "تظهر اللوحة حين يُرصد تسميع الطلاب وحضورهم.")}</div>`}

    ${rest.length ? `<div class="card">
      <div class="pt-wrap"><div class="pt-scroll"><table class="ptable">
        <thead><tr><th style="width:52px">#</th><th>الطالب</th><th>الحلقة</th>
          <th>الأوجه</th><th>الحضور</th><th>التقييم</th><th>الدرجة</th></tr></thead>
        <tbody>${rest.map((r, i) => `<tr>
          <td class="pt-num">${toArabicDigits(i + 4)}</td>
          <td><div class="td-name"><div class="mini-avatar">${initials(r.st.name)}</div>
            <div class="td-strong">${esc(r.st.name || "—")}</div></div></td>
          <td class="muted">${esc(r.st.circle || "—")}</td>
          <td class="pt-num">${toArabicDigits(r.faces)}</td>
          <td class="pt-num">${toArabicDigits(r.attend)}٪</td>
          <td class="pt-num">${r.quality ? toArabicDigits(r.quality) + "٪" : "—"}</td>
          <td class="pt-num"><strong>${toArabicDigits(r.score)}</strong></td>
        </tr>`).join("")}</tbody>
      </table></div></div>
    </div>` : ""}
  </div>`;
}

/* =========================================================================
   لوحة الداعم — نظرةٌ عامة على ثمرة إنفاقه
   ========================================================================= */
function donorDashboard() {
  /* قواعدُ الخادم لا تُجيز للداعم قراءةَ بيانات الطلاب بعد — يُقال ذلك صراحةً (٤٢٩) */
  if ((window.__READ_DENIED || []).indexOf("students") > -1 && !(cur("students") || []).length)
    return `<div class="page">${pageHead("لوحة الداعم", "")}<div class="card">${emptyState("لا تتوفّر البيانات لحسابك بعد",
      "صلاحيةُ الداعم لقراءة بيانات الطلاب لم تُفعَّل في قواعد النظام. راجع الإدارة لتفعيلها.")}</div></div>`;
  const studs = donorStudents();
  const mosques = donorMosques();
  const since = new Date(Date.now() - 30 * 86400000).toISOString().slice(0, 10);

  const sids = studs.map(s => String(s.id));
  const recs = (cur("recitations") || []).filter(r =>
    sids.indexOf(String(r.studentId)) > -1 && String(r.date) >= since);
  const faces = recs.reduce((n, r) => n + (Number(r.faces) || 0), 0);

  const att = (cur("attendance") || []).filter(a =>
    a && !a.staffId && sids.indexOf(String(a.studentId)) > -1 && String(a.date) >= since);
  const present = att.filter(a => a.status === "حاضر" || a.status === "متأخر").length;
  const attPct = att.length ? Math.round(present * 100 / att.length) : 0;

  const circles = (cur("circles") || []).filter(c =>
    mosques.some(m => String(m.id) === String(c.mosqueId)));
  const teachers = new Set(circles.map(c => String(c.teacherId)).filter(Boolean)).size;

  const kpis = [
    { tint: "t-teal",  icon: "users",  num: studs.length,  label: "طالب" },
    { tint: "t-green", icon: "book",   num: faces,         label: "وجه في الشهر" },
    { tint: "t-blue",  icon: "check",  num: attPct,        label: "٪ حضور" },
    { tint: "t-gold",  icon: "teacher", num: teachers,     label: "معلّم" },
    { tint: "t-purple", icon: "grid",  num: circles.length, label: "حلقة" },
    { tint: "t-amber", icon: "mosque", num: mosques.length, label: "مسجد" }
  ].map(k => Object.assign(k, { dir: "flat", trend: "" }));

  const topThree = honorRows().slice(0, 3);

  return `<div class="page">
    ${pageHead("لوحة الداعم",
      mosques.length === 1 ? mosques[0].name : "نظرةٌ على أثر دعمك")}

    <div class="section"><div class="grid g-3 stagger">${kpis.map(kpiCard).join("")}</div></div>

    ${topThree.length ? `<div class="section">
      <div class="section-head"><h3>المتصدّرون هذا الشهر</h3></div>
      <div class="list-card">${topThree.map((r, i) => `<div class="list-row">
        <div class="hn-rank">${toArabicDigits(i + 1)}</div>
        <div style="flex:1"><strong style="font-size:13.5px">${esc(r.st.name)}</strong>
          <div class="muted" style="font-size:11.5px">${esc(r.st.circle || "—")} · ${
            toArabicDigits(r.faces)} وجه</div></div>
        <span class="badge b-teal">${toArabicDigits(r.score)}</span>
      </div>`).join("")}</div>
    </div>` : ""}

    ${noteCard(`ما تراه هنا للقراءة فقط — بيانات طلاب ${
      mosques.length === 1 ? "مسجدك" : "مساجدك"} وحدهم.`)}
  </div>`;
}

