/* =========================================================================
   أجر المعلّم
   -------------------------------------------------------------------------
   المسيّرات تقرأ ثلاثة حقول: salary شهرياً، و wage يومياً، و hourRate
   للساعة — ولم يكن في النظام حقلٌ يكتبها، فيحسب المسيّر أصفاراً مهما عمل
   المعلّم. وكان الاستنتاج من مبلغٍ واحدٍ غامضاً: أهو شهريّ أم يوميّ؟

   هنا يُصرَّح بنوع الأجر، فيُكتب في حقله ويُمحى ما سواه — فلا يجتمع
   راتبان لموظّفٍ واحد ويختلف حسابه باختلاف ما يُقرأ أوّلاً.
   ========================================================================= */
function payFields(type, amount) {
  const n = Number(amount) || 0;
  const out = { payType: String(type || "monthly"),
                salary: 0, wage: 0, hourRate: 0 };

  if (out.payType === "volunteer" || n <= 0) return out;
  if (out.payType === "daily") out.wage = n;
  else if (out.payType === "hourly") out.hourRate = n;
  else out.salary = n;
  return out;
}

/* حقل المبلغ يُخفى للمتطوّع: مبلغٌ لمتطوّعٍ تناقض */
