/* ---- تصدير التقارير كملف CSV ---- */
function exportReportCSV(name) {
  if (!cur("students").length) { showToast("لا توجد بيانات للتصدير", "warn"); return; }

  const headers = ["المجمع", "الطالب", "العمر", "المسجد", "الحلقة", "المعلم", "نوع الدوام", "البرنامج", "المستوى", "تقدم الخطة", "المتأخرات", "الحالة"];
  const rows = cur("students").map(s => [
    complexName(s.complexId), s.name, s.age, s.mosque, s.circle, s.teacher,
    s.attType, s.program, s.level, (s.progress || 0) + "%", s.delays || 0, s.status
  ]);

  const cell = (v) => `"${String(v == null ? "" : v).replace(/"/g, '""')}"`;
  const csv = [headers, ...rows].map(r => r.map(cell).join(",")).join("\r\n");

  const blob = new Blob(["\uFEFF" + csv], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = (name || "تقرير") + ".csv";
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);

  showToast("تم تصدير التقرير بنجاح");
}

