/* =========================================================================
   الحضور اليومي — نموذج البيانات والدوال المساعدة
   -------------------------------------------------------------------------
   لم يكن في المشروع أي كتابة لمجموعة attendance؛ صفحة الإدارة نفسها كانت
   تعلن ذلك في ملاحظتها. فهذا هو النموذج المعتمَد من الآن:

     مجموعة: attendance
     معرّف المستند: "<التاريخ>__<معرّف الطالب>"   مثال: 2026-07-30__1712
     الحقول:
       id         نفس معرّف المستند (يلزم لأن persistSet يستخدم obj.id)
       date       "YYYY-MM-DD" ميلادي — نفس ما تستعمله بقية الصفحات
       studentId  معرّف الطالب
       student    اسم الطالب      (النموذج مزدوج: معرّفات وأسماء معاً)
       circleId   معرّف الحلقة
       circle     اسم الحلقة
       complexId  معرّف المجمع
       status     حاضر · غائب · متأخر · مستأذن
       by         بريد المعلم الذي سجّل
       ts         ختم زمني

   المعرّف مركّب من التاريخ والطالب عمداً: تسجيل نفس اليوم مرتين يستبدل
   السجل ولا ينشئ ثانياً، فلا تتكرر السجلات مهما ضغط المعلم.
   ========================================================================= */

const ATT_STATES = ["حاضر", "متأخر", "مستأذن", "غائب"];
const ATT_TINT   = { "حاضر": "t-green", "متأخر": "t-amber", "مستأذن": "t-blue", "غائب": "t-red" };

/* حالاتُ الاختيار في شاشة التحضير: «غائب» ليست منها بطلبٍ صريح — لا أحدَ
   يجلس يختار الغيابَ طالباً طالباً. المعلّمُ يسجّل من حضر، ومن بقي بلا
   حالةٍ يُعلَّم غائباً دفعةً واحدةً بزرّ «الباقي غائب».

   والقيمةُ «غائب» نفسُها باقيةٌ في ATT_STATES كما هي ولم تُحذف: العدّاداتُ
   والتقاريرُ ورسائلُ أولياء الأمور وشاشاتُ الإدارة لم يتغيّر فيها شيء. */
const ATT_PICK = ATT_STATES.filter(x => x !== "غائب");

/* =========================================================================
   إعدادات التحضير — جهةُ التحضير · مهلةُ التعديل · تسميةُ الحالات
   -------------------------------------------------------------------------
   المواصفات:
     • «يتيح النظام خياراً في إعدادات كل حلقة لتحديد من يملك صلاحية تحضير
       الطلاب: المعلم فقط، أم المشرف/الإدارة فقط، أم كلا الطرفين».
     • «بعد حفظ المعلم للتحضير يمنحه النظام مهلة يحددها مدير النظام (٣٠
       دقيقة أو ساعة)، بعدها تُقفل شاشة التحضير ولا يعدّل إلا عن طريق الإدارة».
     • «إضافة أو تعديل أو إعادة تسمية حالات الحضور، وربط كل مسمّى بحالته
       التقنية الأساسية — مثلاً: حاضر ولم يسمّع = [حاضر] في الدوام، ويترتّب
       عليه [عجز وتأخّر] في الخطط».

   الحالةُ المحفوظة تبقى إحدى الأربع (قاعدة attendance لا تقبل غيرها، وكلُّ
   التقارير تقرؤها)، ويُضاف إليها kind حين تكون مسمّىً مخصّصاً.
   ========================================================================= */
const ATT_WHO = [
  { k: "both",    h: "المعلم والمشرف معاً" },
  { k: "teacher", h: "المعلم فقط" },
  { k: "staff",   h: "المشرف / الإدارة فقط" }
];
const ATT_EFFECTS = [
  { k: "base",    h: "كالحالة الأساسية" },
  { k: "deficit", h: "يُحسب عجزاً ويُعوَّض غداً" },
  { k: "exempt",  h: "يُعفى من واجب اليوم" }
];

function attCfg(mid) {
  const s = typeof cfgFor === "function" ? cfgFor(mid) : (DB.settings || {});
  return {
    who: ATT_WHO.some(x => x.k === s.attWho) ? s.attWho : "both",
    editMin: Math.max(0, Number(s.attEditMin) || 0),
    labels: s.attLabels || {},
    custom: Array.isArray(s.attCustom) ? s.attCustom.filter(x => x && x.k) : []
  };
}

function attCustomOf(kind) {
  if (!kind) return null;
  return attCfg().custom.find(x => String(x.k) === String(kind)) || null;
}

/* الاسمُ المعروض: المسمّى المخصّص، وإلا ما سُمّيت به الحالة، وإلا اسمُها */
function attLabel(status, kind) {
  const c = attCustomOf(kind);
  if (c) return c.h;
  const l = attCfg().labels[String(status || "")];
  return l ? String(l) : String(status || "");
}
window.attLabel = attLabel;

/* جهةُ التحضير: إعدادُ الحلقة، وإلا الإعدادُ العام */
function attWhoOf(circleId) {
  const c = (cur("circles") || []).find(x => String(x.id) === String(circleId || "")) ||
            (DB.circles || []).find(x => String(x.id) === String(circleId || ""));
  const v = c && c.attWho;
  return ATT_WHO.some(x => x.k === v) ? v : attCfg(c && c.mosqueId).who;
}

/* =========================================================================
   حالةُ حضور الطالب في يومٍ — ومنها يُعرف أغائبٌ هو
   -------------------------------------------------------------------------
   «عندما يضع المعلّمُ أنّ الطالب غائبٌ لا يُسمِّع له، ويكون على اسمه علامةٌ
   تبيّن أنّه غائبٌ أو مستأذن». فتُقرأ الحالةُ من سجلّ الحضور مرّةً واحدةً
   وتُستعمل في الحارس وفي العلامات — قراءةٌ محضة.
   ========================================================================= */
function attStatusOf(studentId, dateISO) {
  const d = String(dateISO || (typeof attDate === "function" ? attDate() : todayISO()));
  const r = (Array.isArray(DB.attendance) ? DB.attendance : [])
    .filter(x => x && String(x.studentId) === String(studentId) && String(x.date) === d)
    .sort((a, b) => (Number(b.ts) || 0) - (Number(a.ts) || 0))[0];
  return r ? { status: String(r.status || ""), kind: r.kind || "", rec: r } : null;
}

/* الغيابُ وأخواتُه: ما لا يكون الطالبُ فيه حاضراً في الحلقة */
function attIsAbsent(status) {
  const v = String(status || "");
  return v === "غائب" || v === "مستأذن" || v === "معذور";
}

/* علامةُ الغياب: شريطٌ ظاهرٌ على بطاقة الطالب وفي صفحته هو */
function attAbsentBar(studentId, dateISO, forStudent) {
  const a = attStatusOf(studentId, dateISO);
  if (!a || !attIsAbsent(a.status)) return "";
  const lbl = (typeof attLabel === "function") ? attLabel(a.status, a.kind) : a.status;
  const ico = (typeof attStateIcon === "function") ? attStateIcon(a.status) : "alert";
  return `<div class="att-bar ${esc((typeof ATT_TINT !== "undefined" &&
      ATT_TINT[a.status]) || "t-amber")}">
    ${ic(ico, 16)}<strong>${esc(forStudent ? ("سُجِّلتَ اليومَ: " + lbl)
      : ("مُسجَّلٌ اليومَ: " + lbl))}</strong>
    <small>${esc(forStudent ? "لا تسميعَ لك اليوم — راجع معلّمك إن حضرت"
      : "لا تسميعَ له اليوم حتى يُبدَّل تحضيرُه")}</small></div>`;
}

/* هل يُسمَّع لهذا الطالب اليوم؟ الغائبُ لا يُسمَّع له */
function attBlocksRecite(studentId, dateISO, silent) {
  const a = attStatusOf(studentId, dateISO);
  if (!a || !attIsAbsent(a.status)) return false;
  if (!silent && typeof showToast === "function") {
    showToast("الطالبُ مُسجَّلٌ اليومَ «" +
      (typeof attLabel === "function" ? attLabel(a.status, a.kind) : a.status) +
      "» — لا تسميعَ له. غيّر تحضيرَه إن حضر.", "warn");
  }
  return true;
}

/* هل يحضّر هذا المستخدم في هذه الحلقة؟ المالكُ يبقى مخرجاً للطوارئ */
function attMayTake(circleId, silent) {
  const r = ((STATE && STATE.user) || {}).role || "";
  if (r === "owner") return true;
  const mode = attWhoOf(circleId);
  const isT = r === "teacher";
  const ok = mode === "both" || (mode === "teacher" ? isT : !isT);
  if (!ok && !silent) {
    showToast(mode === "teacher" ? "تحضير هذه الحلقة للمعلم وحده"
                                 : "تحضير هذه الحلقة للمشرف والإدارة وحدهم", "warn");
  }
  return ok;
}

/* مهلةُ التعديل: للمعلّم وحده، من أوّل حفظٍ للسجلّ — والإدارةُ تعدّل بعدها */
function attEditOpen(rec, silent) {
  if (!rec) return true;
  const r = ((STATE && STATE.user) || {}).role || "";
  if (r !== "teacher") return true;
  /* صلاحيةُ البطاقة «تعديل التحضير بعد اعتماد الحلقة» (attEdit) — كانت
     تُعرض في بطاقة المعلّم ولا يقرؤها شيء، فيعدّل من أطفأتها الإدارة (٤٣٢).
     والقاعدةُ على الخادم تقرأ المفتاحَ نفسَه. */
  if (typeof teacherCan === "function" && !teacherCan("attEdit")) {
    if (!silent) showToast("تعديلُ التحضير المحفوظ غيرُ متاحٍ في صلاحياتك — التعديل من الإدارة", "warn");
    return false;
  }
  const m = attCfg().editMin;
  if (!m) return true;
  const t0 = Number(rec.firstTs || rec.ts) || 0;
  const open = !t0 || (Date.now() - t0) <= m * 60000;
  if (!open && !silent) {
    showToast("انتهت مهلة التعديل (" + toArabicDigits(m) + " دقيقة) — التعديل من الإدارة", "warn");
  }
  return open;
}

/* ---------------- الضبط ---------------- */
function attCfgPersist(msg) {
  const s = DB.settings || (DB.settings = {});
  Promise.resolve(persistSet("settings", Object.assign({ id: "general" }, s)))
    .then(ok => { showToast(ok === false ? "تعذّر الحفظ" : (msg || "حُفظت إعدادات التحضير"),
                            ok === false ? "warn" : "success"); mount(); });
}
window.attCfgSave = function () {
  if (!cfgCanEdit()) { showToast("إعدادات التحضير للإدارة العليا ومدير المسجد", "warn"); return; }
  const s = DB.settings || (DB.settings = {});
  const who = val("#ac_who");
  if (ATT_WHO.some(x => x.k === who)) s.attWho = who;
  const m = Number(val("#ac_min"));
  s.attEditMin = isFinite(m) && m >= 0 ? Math.round(m) : 0;
  const labels = {};
  ATT_STATES.forEach((st, i) => {
    const v = String(val("#ac_l" + i) || "").trim();
    if (v && v !== st) labels[st] = v;
  });
  s.attLabels = labels;
  /* المسمّياتُ المخصّصة: الاسمُ مطلوب، والأساسيةُ من الأربع */
  const rows = [...document.querySelectorAll(".ac-custom")];
  const out = [];
  for (const row of rows) {
    const h = String((row.querySelector(".ac-h") || {}).value || "").trim();
    const b = (row.querySelector(".ac-b") || {}).value;
    const e = (row.querySelector(".ac-e") || {}).value;
    if (!h) { showToast("اكتب اسم كلّ حالةٍ مخصّصة أو احذفها", "warn"); return; }
    if (ATT_STATES.indexOf(b) < 0) return;
    out.push({ k: row.dataset.k, h, base: b, effect: ATT_EFFECTS.some(x => x.k === e) ? e : "base" });
  }
  s.attCustom = out;
  attCfgPersist();
};
window.attCustomAdd = function () {
  if (!cfgCanEdit()) return;
  const s = DB.settings || (DB.settings = {});
  const list = Array.isArray(s.attCustom) ? s.attCustom.slice() : [];
  list.push({ k: "c" + Date.now(), h: "", base: "حاضر", effect: "deficit" });
  s.attCustom = list;
  mount();
};
window.attCustomDel = function (k) {
  if (!needDelOk("هذه الحالة", function () { window.attCustomDel(k); })) return;
  if (!cfgCanEdit()) return;
  const s = DB.settings || (DB.settings = {});
  s.attCustom = (s.attCustom || []).filter(x => String(x.k) !== String(k));
  mount();
};

function setPanelAttCfg() {
  const c = attCfg();
  const ro = !cfgCanEdit();
  return `<div class="card" style="margin-top:18px">
    <div class="fac-toolbar">
      <div><strong style="font-size:15px">إعدادات التحضير</strong>
        <div class="muted" style="font-size:11.5px;margin-top:2px">
          من يحضّر، ومهلةُ تعديل المعلّم، وأسماءُ حالات الحضور</div></div>
    </div>
    <div class="form-grid" style="padding:0 16px 12px">
      <div class="field"><label>جهة التحضير (افتراضياً)</label>
        <select id="ac_who"${ro ? " disabled" : ""}>${ATT_WHO.map(x =>
          `<option value="${x.k}"${x.k === c.who ? " selected" : ""}>${esc(x.h)}</option>`).join("")}</select>
        <small style="font-size:11px;color:var(--text-faint)">ويُخصَّص لكلّ حلقةٍ من تعديل بياناتها</small></div>
      <div class="field"><label>مهلة تعديل المعلّم (دقيقة)</label>
        <input id="ac_min" type="number" min="0" dir="ltr" value="${esc(c.editMin)}"${ro ? " disabled" : ""}>
        <small style="font-size:11px;color:var(--text-faint)">٠ = بلا حدّ · تبدأ من أوّل حفظ، وبعدها التعديل للإدارة</small></div>
    </div>
    <div style="padding:0 16px 6px"><strong style="font-size:13px">أسماء الحالات الأساسية</strong></div>
    <div class="form-grid" style="padding:0 16px 10px">
      ${ATT_STATES.map((st, i) => `<div class="field"><label>${esc(st)}</label>
        <input id="ac_l${i}" value="${esc(c.labels[st] || st)}"${ro ? " disabled" : ""}></div>`).join("")}
    </div>
    <div style="padding:0 16px 6px;display:flex;align-items:center;gap:8px">
      <strong style="font-size:13px">حالات مخصّصة</strong>
      <small class="muted">مثال: «حاضر ولم يسمّع» ← أساسيّتها «حاضر» · أثرها «عجز يُعوَّض»</small>
      ${ro ? "" : `<button class="fac-tbtn add" onclick="window.attCustomAdd()" title="إضافة حالة"
        style="margin-inline-start:auto">+</button>`}
    </div>
    <div style="padding:0 16px 12px">
      ${c.custom.length ? c.custom.map(x => `<div class="ac-custom proc-edit" data-k="${esc(x.k)}">
        <input class="ac-h" value="${esc(x.h)}" placeholder="اسم الحالة"${ro ? " disabled" : ""}>
        <select class="ac-b"${ro ? " disabled" : ""}>${ATT_STATES.map(b =>
          `<option${b === x.base ? " selected" : ""}>${esc(b)}</option>`).join("")}</select>
        <select class="ac-e"${ro ? " disabled" : ""}>${ATT_EFFECTS.map(e =>
          `<option value="${e.k}"${e.k === (x.effect || "base") ? " selected" : ""}>${esc(e.h)}</option>`).join("")}</select>
        ${ro ? "" : `<button class="row-btn cp-danger" onclick="window.attCustomDel('${jsAttr(x.k)}')" title="حذف">${ic("trash", 14)}</button>`}
      </div>`).join("") : `<div class="muted" style="font-size:12.5px">لا حالات مخصّصة.</div>`}
    </div>
    ${ro ? "" : `<div style="padding:0 16px 16px">
      <button class="btn btn-primary btn-sm" onclick="window.attCfgSave()">حفظ إعدادات التحضير</button></div>`}
  </div>`;
}

/* =========================================================================
   القرآنُ الكريم المسموع — أربعةُ قرّاءٍ بأصواتهم
   -------------------------------------------------------------------------
   المواصفات: «أريد إضافة نظام متكامل للقرآن الكريم المسموع… المنشاوي ←
   ١١٤ سورة بصوته وحدَه… لا تخلط أصوات القرّاء… لا تكتب ٤٥٦ رابطاً يدوياً».

   • مصدرُ الصوت: المكتبة الصوتية للقرآن الكريم (MP3Quran.net). تحقّقتُ من
     صفحات القرّاء الأربعة: كلٌّ منهم ١١٤ سورةً كاملة، والملفُّ باسمٍ من
     ثلاثة أرقامٍ بأصفارٍ بادئة. والموقعُ ينشر API للمطوّرين فالبثُّ منه
     مقصودٌ مأذونٌ به — ولا ينشر ترخيصاً يبيح إعادةَ الاستضافة، فلا تُنسخ
     ملفاتُه إلى Firebase Storage ولا يُعرض زرُّ تحميل. والمفتاحُ
     allowDownload يفتحه في سطرٍ متى حصلت الإدارةُ على إذنٍ خطّيّ.

   • الصور: لم يُوجد مصدرٌ بترخيصٍ واضحٍ لصور المشايخ، فالبطاقةُ بهويّة
     المشروع — حرفُ الاسم في إطارٍ مزخرف. وحقلُ image يقبل صورةً مرخَّصةً
     متى وُجدت بلا تغييرٍ آخر.

   • السور: تُقرأ من quran/surahs.json القائم (QSURAHS) — لا قائمةَ ثانية.
     ولا يُولَّد رابطٌ إلا عند الحاجة، ولا يُحمَّل صوتٌ إلا عند الضغط على
     «تشغيل».
   ========================================================================= */
const QA_RECITERS = [
  { id: "minshawi", name: "محمد صديق المنشاوي", nameEn: "Al-Minshawi",
    riwaya: "حفص عن عاصم — مرتَّل", letter: "م",
    desc: "من أعلام التلاوة المصرية، صاحبُ الصوت الخاشع والأداء المتمهّل.",
    base: "https://cdn.mp3quran.net/download/audio/muhammad-minshawi/r1/", image: "",
    /* التلاوةُ آيةً آية من everyayah.com — تحقّقتُ من مجلَّد كلِّ قارئٍ
       بعينه. ومعرّفُ Quran.com (ayahApi) باقٍ مسلكاً احتياطياً لمن لا
       مجلَّدَ له، ولا يُستعمل ما دام للقارئ ayahBase. */
    ayahApi: 9, ayahBase: "https://everyayah.com/data/Minshawy_Murattal_128kbps/" },
  { id: "husary", name: "محمود خليل الحصري", nameEn: "Al-Husary",
    riwaya: "حفص عن عاصم — مرتَّل", letter: "ح",
    desc: "شيخُ عموم المقارئ المصرية، وأضبطُ التلاوات المسجَّلة أداءً للتجويد.",
    /* نقل المصدرُ ملفَّاته إلى cdn.mp3quran.net، فسقط server13 القديم.
       الرابطُ أدناه هو ما تعرضه صفحةُ القارئ في mp3quran.net نفسِها. */
    base: "https://cdn.mp3quran.net/download/audio/mahmoud-husary/r1/",
    image: "", ayahApi: 6,
    ayahBase: "https://everyayah.com/data/Husary_128kbps/" },
  { id: "hudhaify", name: "علي بن عبدالرحمن الحذيفي", nameEn: "Al-Hudhaify",
    riwaya: "حفص عن عاصم", letter: "ع",
    desc: "إمامُ المسجد النبويّ، تلاوةٌ هادئةٌ واضحةُ المخارج.",
    base: "https://cdn.mp3quran.net/download/audio/ali-hudhaifi/r1/", image: "",
    /* لا تلاوةَ له آيةً آية في Quran.com — تحقّقتُ من فهرس التلاواتِ هناك
       فوجدتُه بالسورة وحدَها. وله في everyayah.com ملفُّ كلِّ آيةٍ على حدة،
       فيُبثّ منه بثّاً ولا يُنسخ إلى خوادمنا. واسمُ الملفّ: سورةٌ ثلاثُ
       خاناتٍ ثمّ آيةٌ ثلاثُ خانات. */
    ayahApi: 0, ayahBase: "https://everyayah.com/data/Hudhaify_128kbps/" },
  { id: "tunaiji", name: "خليفة الطنيجي", nameEn: "Al-Tunaiji",
    riwaya: "حفص عن عاصم", letter: "خ",
    desc: "قارئٌ إماراتيٌّ معاصر، تلاوةٌ نديّةٌ مطمئنّة.",
    base: "https://cdn.mp3quran.net/download/audio/khalifa-tunaiji/r1/", image: "",
    ayahApi: 161, ayahBase: "https://everyayah.com/data/khalefa_al_tunaiji_64kbps/" }
];
/* زرُّ التحميل: أذنت به الإدارةُ صراحةً. والرابطُ هو رابطُ التحميل الذي
   يعرضه المصدرُ نفسُه لزوّاره — لا نسخةَ في خوادمنا ولا إعادةَ استضافة. */
const QA_ALLOW_DOWNLOAD = true;

/* أسماءُ السور بالإنجليزية — ما ينقص surahs.json وحدَه، بلا تكرارِ سواه */
const QA_EN = ("Al-Fatihah,Al-Baqarah,Aal-Imran,An-Nisa,Al-Ma'idah,Al-An'am,Al-A'raf,Al-Anfal," +
"At-Tawbah,Yunus,Hud,Yusuf,Ar-Ra'd,Ibrahim,Al-Hijr,An-Nahl,Al-Isra,Al-Kahf,Maryam,Ta-Ha," +
"Al-Anbiya,Al-Hajj,Al-Mu'minun,An-Nur,Al-Furqan,Ash-Shu'ara,An-Naml,Al-Qasas,Al-Ankabut," +
"Ar-Rum,Luqman,As-Sajdah,Al-Ahzab,Saba,Fatir,Ya-Sin,As-Saffat,Sad,Az-Zumar,Ghafir,Fussilat," +
"Ash-Shura,Az-Zukhruf,Ad-Dukhan,Al-Jathiyah,Al-Ahqaf,Muhammad,Al-Fath,Al-Hujurat,Qaf," +
"Adh-Dhariyat,At-Tur,An-Najm,Al-Qamar,Ar-Rahman,Al-Waqi'ah,Al-Hadid,Al-Mujadilah,Al-Hashr," +
"Al-Mumtahanah,As-Saff,Al-Jumu'ah,Al-Munafiqun,At-Taghabun,At-Talaq,At-Tahrim,Al-Mulk," +
"Al-Qalam,Al-Haqqah,Al-Ma'arij,Nuh,Al-Jinn,Al-Muzzammil,Al-Muddaththir,Al-Qiyamah,Al-Insan," +
"Al-Mursalat,An-Naba,An-Nazi'at,Abasa,At-Takwir,Al-Infitar,Al-Mutaffifin,Al-Inshiqaq," +
"Al-Buruj,At-Tariq,Al-A'la,Al-Ghashiyah,Al-Fajr,Al-Balad,Ash-Shams,Al-Layl,Ad-Duha," +
"Ash-Sharh,At-Tin,Al-Alaq,Al-Qadr,Al-Bayyinah,Az-Zalzalah,Al-Adiyat,Al-Qari'ah,At-Takathur," +
"Al-Asr,Al-Humazah,Al-Fil,Quraysh,Al-Ma'un,Al-Kawthar,Al-Kafirun,An-Nasr,Al-Masad," +
"Al-Ikhlas,Al-Falaq,An-Nas").split(",");

/* صورُ المشايخ: لا يُشحن مع النظام شيءٌ منها — ترخيصُها غيرُ معلوم.
   وتضبطها الإدارةُ بروابطَ تملكها، فتُحفظ في settings/general وتعلو
   الفارغَ في التعريف. */
function qaImages() {
  const s = (DB.settings || {}).qaImages;
  return s && typeof s === "object" ? s : {};
}
function qaReciter(id) {
  const r = QA_RECITERS.find(x => x.id === String(id));
  if (!r) return null;
  const img = qaImages()[r.id];
  return img ? Object.assign({}, r, { image: String(img) }) : r;
}

/* رقمُ السورة ← اسمُ الملفّ: ثلاثةُ أرقامٍ بأصفارٍ بادئة */
function qaPad3(n) {
  const v = Math.max(1, Math.min(114, Number(n) || 0));
  return (v < 10 ? "00" : v < 100 ? "0" : "") + v;
}

/* ترقيمُ الآية ثلاثَ خانات — بلا حدِّ السور (١١٤)، فأطولُ سورةٍ ٢٨٦ آية.
   قياسُه على qaPad3 كان يقصُّ كلَّ آيةٍ بعد الرابعةَ عشرةَ بعد المئة. */
function qaPad3a(n) {
  const v = Math.max(1, Math.min(999, Number(n) || 0));
  return (v < 10 ? "00" : v < 100 ? "0" : "") + v;
}

/* الرابطُ يُولَّد ولا يُكتب: ٤٥٦ رابطاً من أربعة تعريفات */
function qaUrl(reciterId, surahNumber) {
  const r = qaReciter(reciterId);
  if (!r) return "";
  const n = Number(surahNumber);
  if (!(n >= 1 && n <= 114)) return "";
  return r.base + qaPad3(n) + ".mp3";
}
window.qaUrl = qaUrl;

/* سورُ قارئٍ بعينه — من فهرس المشروع نفسِه لا من قائمةٍ ثانية */
function getReciterSurahs(reciterId) {
  const r = qaReciter(reciterId);
  if (!r) return [];
  const list = (typeof QSURAHS !== "undefined" && QSURAHS) ? QSURAHS : [];
  if (!list.length) return [];
  return list.map(s => ({
    reciterId: r.id,
    surahNumber: Number(s.i),
    name: s.n,
    englishName: QA_EN[Number(s.i) - 1] || "",
    ayahs: Number(s.a) || 0,
    page: Number(s.p) || 0,
    audioUrl: qaUrl(r.id, s.i),
    status: "ok"
  }));
}
window.getReciterSurahs = getReciterSurahs;

/* =========================================================================
   التلاوةُ آيةً آية داخل المصحف التفاعليّ
   -------------------------------------------------------------------------
   المواصفات: «أريد أن يستطيع المستخدم فتح المصحف واختيار القارئ وتشغيل
   التلاوة والاستماع أثناء قراءة الآيات… تحديدُ الآية الحالية وتمييزُها
   والانتقالُ إليها وتكرارُها».

   المصدر: واجهةُ Quran.com (`/recitations/{id}/by_chapter/{n}`) وهي توثّق
   ناتجَها `{ audio_files: [{ verse_key, url }] }`. ولا يُخمَّن شيء: ما
   يعود مطلقاً يُستعمل كما هو، وما يعود نسبياً يُسبق بمضيف الملفّات. ومن
   لا تلاوةَ آيةٍ له عند المصدر (الحذيفي) لا يُشغَّل بالآية ويُقال ذلك
   صراحةً، ولا يُصطنع له مصدر.

   وتمييزُ الآية بسمة data-k التي تحمل «سورة:آية:كلمة» في كلّ كلمة.
   ========================================================================= */
const QA_AYAH_API  = "https://api.quran.com/api/v4/recitations/";
const QA_AYAH_HOST = "https://verses.quran.com/";
const QA_AYAH_CACHE = {};          /* "rid|surah" → [{s,a,url}] */

/* هل لهذا القارئ تلاوةٌ آيةً آية؟ مصدران: فهرسُ Quran.com (ayahApi)،
   وملفّاتُ everyayah.com (ayahBase). ومن لا مصدرَ له لا يُشغَّل بالآية. */
function qaHasAyah(r) { return !!(r && (r.ayahApi || r.ayahBase)); }
window.qaHasAyah = qaHasAyah;

/* عددُ آيات سورةٍ من قائمة السور القائمة — لا جدولَ ثانٍ.
   وقد يُفتح المصحفُ قبل تحميل الفهرس، فيُحمَّل هنا مرّةً ويُنتظر. */
async function qaAyahCount(surah) {
  const n = Number(surah) || 0;
  if (!n) return 0;
  if (!QSURAHS && typeof window.Quran !== "undefined" && window.Quran.surahs) {
    try { QSURAHS = await window.Quran.surahs(); } catch (e) { return 0; }
  }
  if (!QSURAHS) return 0;
  const x = QSURAHS.find(y => Number(y.i) === n);
  return x ? Number(x.a) || 0 : 0;
}

function qaAyahAbs(u) {
  const s = String(u || "");
  if (!s) return "";
  if (/^https?:\/\//i.test(s)) return s;
  return QA_AYAH_HOST + s.replace(/^\/+/, "");
}

/* آياتُ سورةٍ بصوت قارئ — تُجلب مرّةً وتُحفظ، ولا تُجلب قبل الطلب */
async function qaAyahLoad(rid, surah) {
  const r = qaReciter(rid);
  if (!qaHasAyah(r)) return null;
  const key = rid + "|" + surah;
  if (QA_AYAH_CACHE[key]) return QA_AYAH_CACHE[key];

  /* مصدرٌ باسمِ ملفٍّ منتظم: تُبنى الروابطُ من عدد آيات السورة، فلا طلبَ
     شبكةٍ لفهرسٍ ولا انتظار. ولا يُنسخ ملفٌّ — البثُّ من المصدر نفسِه. */
  if (r.ayahBase) {
    const cnt = await qaAyahCount(surah);
    if (!cnt) return null;
    const out = [];
    for (let a = 1; a <= cnt; a++) {
      out.push({ s: Number(surah), a: a,
                 url: r.ayahBase + qaPad3(surah) + qaPad3a(a) + ".mp3" });
    }
    QA_AYAH_CACHE[key] = out;
    return out;
  }

  const url = QA_AYAH_API + r.ayahApi + "/by_chapter/" + Number(surah) +
              "?per_page=300";
  try {
    const res = await fetch(url);
    if (!res.ok) throw new Error("HTTP " + res.status);
    const j = await res.json();
    const arr = (j && j.audio_files ? j.audio_files : []).map(function (f) {
      const vk = String(f.verse_key || "").split(":");
      return { s: Number(vk[0]) || Number(surah), a: Number(vk[1]) || 0,
               url: qaAyahAbs(f.url || f.audio_url) };
    }).filter(x => x.a > 0 && x.url);
    if (!arr.length) throw new Error("لا آياتٍ في الناتج");
    QA_AYAH_CACHE[key] = arr;
    return arr;
  } catch (e) {
    console.warn("تلاوةُ الآيات:", rid, surah, e);
    return null;
  }
}
window.qaAyahLoad = qaAyahLoad;

/* حالُ الاستماع داخل المصحف */
/* panel: لوحةُ الاستماع مفتوحةٌ داخلَ شريطِ القارئ السفليّ */
const MUSA = { on: false, rid: "", s: 0, a: 0, list: null, i: -1, repeat: false,
               busy: false, lim: null, panel: false };
window.MUSA = MUSA;

function qaAyahHi(s, a) {
  try {
    document.querySelectorAll(".mus-w.mus-now").forEach(e => e.classList.remove("mus-now"));
    if (!s || !a) return;
    const sel = '.mus-w[data-k^="' + s + ':' + a + ':"]';
    const els = document.querySelectorAll(sel);
    els.forEach(e => e.classList.add("mus-now"));
    if (els[0] && els[0].scrollIntoView) {
      els[0].scrollIntoView({ block: "center", behavior: "smooth" });
    }
  } catch (e) {}
}

/* تشغيلُ آيةٍ بعينها ثمّ ما بعدها — أو تكرارُها إن طُلب */
window.qaAyahPlay = async function (s, a) {
  if (!MUSA.rid) { showToast("اختر القارئ أولاً", "warn"); return; }
  const r = qaReciter(MUSA.rid);
  if (!qaHasAyah(r)) {
    showToast("هذا القارئ لا تتوفّر له تلاوةٌ بالآية — استمع إليه بالسورة من «المسموع»", "warn");
    return;
  }
  if (MUSA.busy) return;
  MUSA.busy = true;
  try {
    if (MUSA.s !== Number(s) || !MUSA.list) {
      const list = await qaAyahLoad(MUSA.rid, s);
      if (!list) {
        showToast("تعذّر جلبُ تلاوة الآيات — تحقّق من اتصالك", "warn");
        MUSA.busy = false; return;
      }
      MUSA.list = list; MUSA.s = Number(s);
    }
  } finally { MUSA.busy = false; }

  const i = MUSA.list.findIndex(x => Number(x.a) === Number(a));
  if (i < 0) { showToast("لم تُوجد هذه الآية عند هذا القارئ", "warn"); return; }
  MUSA.i = i; MUSA.a = Number(a);

  const au = qaAudio();
  au.src = MUSA.list[i].url;
  au.playbackRate = qaPrefs().rate;
  au.volume = qaPrefs().vol;
  QA.rid = ""; QA.n = 0;              /* وضعُ الآية لا وضعُ السورة */
  const pr = au.play();
  if (pr && pr.catch) pr.catch(function () {
    showToast("المتصفّح منع التشغيل — اضغط «استماع» مرّةً أخرى", "warn");
  });
  qaAyahHi(MUSA.s, MUSA.a);
  musaBarSync();
};

/* نهايةُ الآية: تُكرَّر أو تُتبع بالتي بعدها — وبصوت القارئ نفسِه */
function qaAyahEnded() {
  if (!MUSA.on || !MUSA.list || MUSA.i < 0) return false;
  if (MUSA.repeat) { window.qaAyahPlay(MUSA.s, MUSA.a); return true; }

  /* حدُّ الواجب: يقف عند آخر آيةٍ منه لا عند آخر السورة */
  const lim = MUSA.lim;
  if (lim && lim.a && Number(MUSA.s) === Number(lim.s) && Number(MUSA.a) >= Number(lim.a)) {
    MUSA.i = -1; MUSA.lim = null; qaAyahHi(0, 0); musaBarSync();
    try { showToast("انتهى واجبك — أحسنت", "success"); } catch (e) {}
    return true;
  }

  const nx = MUSA.list[MUSA.i + 1];
  if (!nx) {
    /* واجبٌ يمتدّ إلى السورة التالية: تُجلب ويُستأنف منها */
    if (lim && Number(lim.s) > Number(MUSA.s)) {
      const ns = Number(MUSA.s) + 1;
      MUSA.list = null;
      window.qaAyahPlay(ns, 1);
      return true;
    }
    MUSA.i = -1; qaAyahHi(0, 0); musaBarSync();
    return true;
  }
  window.qaAyahPlay(MUSA.s, nx.a);
  return true;
}

window.musaPick = function (rid) {
  MUSA.rid = String(rid || "");
  MUSA.list = null; MUSA.s = 0; MUSA.i = -1;
  musaBarSync();
};
window.musaToggleOn = function () {
  MUSA.on = !MUSA.on;
  if (!MUSA.on) { try { qaAudio().pause(); } catch (e) {} qaAyahHi(0, 0); }
  showToast(MUSA.on ? "اضغط على أيّ آيةٍ لتبدأ التلاوةُ منها" : "أُغلق وضعُ الاستماع", "info");
  mount();
};
window.musaRepeat = function (on) { MUSA.repeat = !!on; musaBarSync(); };
window.musaStop = function () {
  try { qaAudio().pause(); } catch (e) {}
  MUSA.i = -1; MUSA.lim = null; qaAyahHi(0, 0); musaBarSync();
};
/* من أوّل آيةٍ في الصفحة المعروضة */
window.musaFromPage = function () {
  const m = mushaf();
  const rows = MUSHAF_CACHE[m.page] || [];
  const first = rows.find(v => v && v.s && v.a);
  if (!first) { showToast("انتظر حتى تُحمَّل الصفحة", "warn"); return; }
  MUSA.on = true;
  window.qaAyahPlay(first.s, first.a);
};
function musaBarSync() {
  try {
    const b = document.querySelector(".musa-state");
    if (b) b.textContent = MUSA.a
      ? "الآية " + toArabicDigits(MUSA.a) : (MUSA.on ? "اختر آية" : "");
  } catch (e) {}
}

/* شريطُ الاستماع في المصحف — يُدرج داخلَ شريطِ القارئ السفليّ فوقَ أزراره،
   يفتحه زرُّ التشغيل هناك (window.musaPanel) */
function musaBar() {
  if (!stuAppOn("show.audio")) return "";
  const r = MUSA.rid ? qaReciter(MUSA.rid) : null;
  const noAyah = r && !qaHasAyah(r);
  return `<div class="musa-bar${MUSA.on ? " on" : ""}">
    <button type="button" class="musa-btn${MUSA.on ? " on" : ""}" onclick="window.musaToggleOn()">
      ${ic(MUSA.on ? "pause" : "play", 15)} ${MUSA.on ? "إغلاق الاستماع" : "استماع بالآية"}</button>
    <select class="musa-sel" onchange="window.musaPick(this.value)">
      <option value="">— اختر القارئ —</option>
      ${QA_RECITERS.map(x => `<option value="${esc(x.id)}"${
        MUSA.rid === x.id ? " selected" : ""}>${esc(x.name)}${
        qaHasAyah(x) ? "" : " (بالسورة فقط)"}</option>`).join("")}
    </select>
    ${MUSA.on ? `<button type="button" class="musa-btn" onclick="window.musaFromPage()">
        ${ic("book", 14)} من أول الصفحة</button>
      <label class="musa-rep"><input type="checkbox" ${MUSA.repeat ? "checked" : ""}
        onchange="window.musaRepeat(this.checked)"> تكرار الآية</label>
      <button type="button" class="musa-btn" onclick="window.musaStop()">${ic("x", 14)} إيقاف</button>
      <span class="musa-state"></span>` : ""}
    ${noAyah ? `<span class="musa-note">${ic("info", 13)}
      لا تتوفّر تلاوةٌ بالآية لهذا القارئ — استمع إليه بالسورة من «المسموع».</span>` : ""}
  </div>`;
}

/* =========================================================================
   تفضيلاتُ الاستماع — آخرُ موضعٍ والمفضَّلة
   -------------------------------------------------------------------------
   في localStorage كتفضيلات المصحف (mus_prefs): كتابةُ الطالب في فايرستور
   يردّها الخادمُ بقواعده، فلا تُحفظ هناك.
   ========================================================================= */
const QA_PREFS_KEY = "qa_prefs";
let QA_PREFS = null;
function qaPrefs() {
  if (QA_PREFS) return QA_PREFS;
  let o = {};
  try { o = JSON.parse(localStorage.getItem(QA_PREFS_KEY) || "{}") || {}; } catch (e) {}
  QA_PREFS = { last: o.last || null, fav: Array.isArray(o.fav) ? o.fav : [],
               rate: Number(o.rate) || 1, vol: o.vol == null ? 1 : Number(o.vol),
               auto: o.auto !== false };
  return QA_PREFS;
}
function qaPrefsSave() {
  try { localStorage.setItem(QA_PREFS_KEY, JSON.stringify(qaPrefs())); } catch (e) {}
}
function qaFavKey(rid, n) { return rid + ":" + n; }
function qaIsFav(rid, n) { return qaPrefs().fav.indexOf(qaFavKey(rid, n)) > -1; }
window.qaFavToggle = function (rid, n) {
  const p = qaPrefs(), k = qaFavKey(rid, String(n)), i = p.fav.indexOf(k);
  if (i > -1) p.fav.splice(i, 1); else p.fav.push(k);
  qaPrefsSave();
  showToast(i > -1 ? "أُزيلت من المفضّلة" : "أُضيفت إلى المفضّلة", "success");
  mount();
};

/* =========================================================================
   المشغّل — عنصرُ صوتٍ واحدٌ للنظام كلِّه
   -------------------------------------------------------------------------
   واحدٌ لا أكثر: فلا يختلط صوتُ قارئٍ بآخر مهما تنقّل المستخدم، لأن
   الثاني يوقف الأول بالضرورة. وكلُّ تشغيلٍ يحمل reciterId صاحبَه.
   ========================================================================= */
const QA = { el: null, rid: "", n: 0, playing: false, dur: 0, pos: 0, ready: false };

function qaAudio() {
  if (QA.el) return QA.el;
  const a = new Audio();
  a.preload = "none";                 /* لا يُحمَّل شيءٌ قبل الضغط على تشغيل */
  a.addEventListener("timeupdate", function () {
    QA.pos = a.currentTime || 0; qaBarSync();
    /* آخرُ موضعٍ يُحفظ كلَّ خمس ثوانٍ لا مع كلّ إطار */
    if (Math.floor(QA.pos) % 5 === 0) qaRemember();
  });
  a.addEventListener("loadedmetadata", function () {
    QA.dur = a.duration || 0; QA.ready = true; qaBarSync();
  });
  a.addEventListener("ended", function () {
    try { if (qaAyahEnded()) return; } catch (e) {}
    qaEnded();
  });
  a.addEventListener("error", function () {
    QA.playing = false;
    /* قولُ ما سقط بعينه: سقط مرّتين ولم يُعرف أهو ملفُّ السورة أم الآية.
       واسمُ القارئ معه لأنّ مصدرَ كلِّ قارئٍ على حدة. */
    const inAyah = typeof MUSA !== "undefined" && MUSA.rid && MUSA.a;
    const r = inAyah ? qaReciter(MUSA.rid) : (QA.rid ? qaReciter(QA.rid) : null);
    const who = r ? (r.name || "") : "";
    showToast(inAyah
      ? "تعذّر تشغيل الآية" + (who ? " بصوت " + who : "") + " — تحقّقْ من اتصالك"
      : "تعذّر تشغيل السورة" + (who ? " بصوت " + who : "") + " — تحقّقْ من اتصالك",
      "warn");
    try { console.warn("تعذّر الصوت:", a.src); } catch (e) {}
    qaBarSync();
  });
  a.addEventListener("play",  function () { QA.playing = true;  qaBarSync(); });
  a.addEventListener("pause", function () { QA.playing = false; qaBarSync(); });
  QA.el = a;
  return a;
}

function qaRemember() {
  if (!QA.rid || !QA.n) return;
  const p = qaPrefs();
  p.last = { rid: QA.rid, n: QA.n, t: Math.floor(QA.pos || 0) };
  qaPrefsSave();
}

window.qaPlay = function (rid, n, seek) {
  const url = qaUrl(rid, n);
  if (!url) { showToast("لم يُعثر على هذه السورة", "warn"); return; }
  const a = qaAudio();
  const same = QA.rid === String(rid) && Number(QA.n) === Number(n);
  if (!same) {
    QA.rid = String(rid); QA.n = Number(n);
    QA.dur = 0; QA.pos = 0; QA.ready = false;
    a.src = url;                      /* المصدرُ يُسند الآن لا قبلُ */
  }
  const p = qaPrefs();
  a.playbackRate = p.rate; a.volume = p.vol;
  if (seek != null) { try { a.currentTime = Number(seek) || 0; } catch (e) {} }
  qaBarMount();
  const pr = a.play();
  if (pr && pr.catch) pr.catch(function () {
    showToast("المتصفّح منع التشغيل التلقائيّ — اضغط «تشغيل» مرّةً أخرى", "warn");
  });
  qaRemember();
  qaBarSync();
};
window.qaPause = function () { if (QA.el) QA.el.pause(); };
window.qaToggle = function () {
  if (!QA.el || !QA.rid) return;
  if (QA.playing) QA.el.pause(); else window.qaPlay(QA.rid, QA.n);
};
window.qaStop = function () {
  if (!QA.el) return;
  QA.el.pause();
  try { QA.el.currentTime = 0; } catch (e) {}
  QA.pos = 0; qaBarSync();
};
/* التالي والسابق — داخل القارئ نفسِه لا غير */
window.qaStep = function (d) {
  if (!QA.rid) return;
  const n = Number(QA.n) + Number(d);
  if (n < 1 || n > 114) { showToast(n < 1 ? "هذه أولى السور" : "هذه آخر السور", "info"); return; }
  window.qaPlay(QA.rid, n);
  mount();
};
window.qaSeek = function (v) {
  if (!QA.el || !QA.dur) return;
  try { QA.el.currentTime = (Number(v) / 100) * QA.dur; } catch (e) {}
};
window.qaRate = function (v) {
  const p = qaPrefs(); p.rate = Number(v) || 1; qaPrefsSave();
  if (QA.el) QA.el.playbackRate = p.rate;
  qaBarSync();
};
window.qaVol = function (v) {
  const p = qaPrefs(); p.vol = Math.max(0, Math.min(1, Number(v) / 100)); qaPrefsSave();
  if (QA.el) QA.el.volume = p.vol;
};
window.qaAuto = function (on) {
  const p = qaPrefs(); p.auto = !!on; qaPrefsSave();
  showToast(p.auto ? "سيتابع إلى السورة التالية" : "سيتوقّف عند نهاية السورة", "info");
};
function qaEnded() {
  QA.playing = false;
  const p = qaPrefs();
  if (p.auto && QA.n < 114) { window.qaPlay(QA.rid, Number(QA.n) + 1); mount(); return; }
  qaBarSync();
}
window.qaResume = function () {
  const l = qaPrefs().last;
  if (!l) return;
  window.qaPlay(l.rid, l.n, l.t);
  QAV.rid = l.rid; mount();
};

function qaClock(s) {
  const t = Math.max(0, Math.floor(Number(s) || 0));
  const m = Math.floor(t / 60), x = t % 60;
  return toArabicDigits((m < 10 ? "0" : "") + m + ":" + (x < 10 ? "0" : "") + x);
}

/* ارتفاعُ الشريط السفليّ يُقاس ولا يُقدَّر: ارتفاعُه من محتواه ومن
   safe-area-inset في الهواتف، فأيُّ رقمٍ ثابتٍ يجعل المشغّلَ يحجبه. */
function qaLift() {
  try {
    const tb = document.querySelector(".tabbar");
    if (!tb) return 0;
    if (getComputedStyle(tb).display === "none") return 0;
    return Math.round(tb.getBoundingClientRect().height || 0);
  } catch (e) { return 0; }
}

/* وعرضُ الشريط الجانبيّ كذلك: في الشاشات العريضة يبدأ المشغّلُ بعده فلا
   يغطّي قائمةَ التنقّل — والقياسُ لا التقدير، فعرضُه متغيّرٌ في المتغيّرات. */
function qaSideGap() {
  try {
    const sb = document.querySelector(".sidebar");
    if (!sb) return 0;
    const st = getComputedStyle(sb);
    if (st.display === "none" || st.position !== "fixed") return 0;
    const r = sb.getBoundingClientRect();
    /* المثبَّتُ خارجَ الشاشة (قائمةُ الهاتف المنزلقة) لا يُزاح له */
    if (r.right <= 0 || r.left >= window.innerWidth) return 0;
    return Math.round(r.width || 0);
  } catch (e) { return 0; }
}

/* شريطُ المشغّل يُحدَّث في مكانه لا بإعادة رسم الصفحة — وإلا انقطع الصوت */
function qaBarSync() {
  try {
    const bar = document.getElementById("qaBar");
    if (!bar) return;
    bar.style.bottom = qaLift() + "px";
    bar.style.insetInlineStart = qaSideGap() + "px";
    const r = qaReciter(QA.rid);
    const nm = (typeof QSURAHS !== "undefined" && QSURAHS)
      ? ((QSURAHS.find(x => Number(x.i) === Number(QA.n)) || {}).n || "") : "";
    bar.classList.toggle("on", !!QA.rid);
    const t = bar.querySelector(".qab-title");
    if (t) t.textContent = nm ? nm + " — " + (r ? r.name : "") : "";
    const pb = bar.querySelector(".qab-range");
    if (pb) pb.value = QA.dur ? String(Math.round(QA.pos / QA.dur * 100)) : "0";
    const tm = bar.querySelector(".qab-time");
    if (tm) tm.textContent = qaClock(QA.pos) + " / " + qaClock(QA.dur);
    const pl = bar.querySelector(".qab-play");
    if (pl) pl.innerHTML = ic(QA.playing ? "pause" : "play", 20);
  } catch (e) {}
}
window.qaBarSync = qaBarSync;

/* =========================================================================
   الواجهة — بطاقاتُ القرّاء ثمّ صفحةُ القارئ
   ========================================================================= */
const QAV = { rid: "", q: "", fav: false };
window.qaOpen = function (rid) { QAV.rid = String(rid || ""); QAV.q = ""; QAV.fav = false; mount(); };
window.qaBack = function () { QAV.rid = ""; QAV.fav = false; mount(); };
window.qaSearch = function (v) {
  QAV.q = String(v || "").trim();
  const box = document.getElementById("qaList");
  if (box) qaPaintList(box);
};
window.qaFavView = function (on) { QAV.fav = !!on; mount(); };

function qaNorm(s) {
  return String(s || "").replace(/[ً-ْٰ]/g, "")
    .replace(/[أإآ]/g, "ا").replace(/ى/g, "ي").replace(/ة/g, "ه")
    .replace(/\s+/g, " ").trim();
}

function qaRowsHTML(rid) {
  const all = getReciterSurahs(rid);
  const q = qaNorm(QAV.q);
  const rows = all.filter(s => {
    if (QAV.fav && !qaIsFav(rid, s.surahNumber)) return false;
    if (!q) return true;
    return qaNorm(s.name).indexOf(q) > -1 ||
           String(s.surahNumber) === QAV.q ||
           qaNorm(s.englishName).toLowerCase().indexOf(q.toLowerCase()) > -1;
  });
  if (!rows.length) {
    return `<div class="qa-empty">${ic("search", 22)}
      <span>${QAV.fav ? "لا سورةَ في مفضّلتك بعد" : "لا سورةَ بهذا الاسم"}</span></div>`;
  }
  return rows.map(s => {
    const on = Number(QA.n) === s.surahNumber && QA.rid === rid;
    return `<div class="qa-row${on ? " on" : ""}">
      <button type="button" class="qa-rplay" title="تشغيل"
        onclick="window.qaPlay('${jsAttr(rid)}',${s.surahNumber}); window.qaBarSync();">
        ${ic(on && QA.playing ? "pause" : "play", 16)}</button>
      <span class="qa-rnum">${toArabicDigits(s.surahNumber)}</span>
      <span class="qa-rname">${esc(s.name)}<small>${esc(s.englishName)}</small></span>
      <span class="qa-rayat">${toArabicDigits(s.ayahs)} آية</span>
      <button type="button" class="qa-rfav${qaIsFav(rid, s.surahNumber) ? " on" : ""}"
        title="المفضّلة" onclick="window.qaFavToggle('${jsAttr(rid)}',${s.surahNumber})">
        ${ic("star", 15)}</button>
      ${QA_ALLOW_DOWNLOAD ? `<a class="qa-rdl" title="تحميل" download
        href="${esc(safeUrl(s.audioUrl))}">${ic("download", 15)}</a>` : ""}
    </div>`;
  }).join("");
}
function qaPaintList(box) { box.innerHTML = qaRowsHTML(QAV.rid); }

/* بطاقةُ القارئ — بهويّة المشروع، بلا صورةٍ مجهولةِ الترخيص */
function qaCard(r) {
  return `<button type="button" class="qa-card" onclick="window.qaOpen('${jsAttr(r.id)}')">
    <span class="qa-ava">${r.image
      ? `<img src="${esc(r.image)}" alt="${esc(r.name)}">`
      : `<i>${esc(r.letter)}</i>`}</span>
    <strong class="qa-cname">${esc(r.name)}</strong>
    <small class="qa-cen">${esc(r.nameEn)}</small>
    <span class="qa-criw">${esc(r.riwaya)}</span>
    <span class="qa-clisten">${ic("play", 14)} استماع</span>
  </button>`;
}

function qaudioPage() {
  reciteLoadSurahs();
  const ready = typeof QSURAHS !== "undefined" && QSURAHS && QSURAHS.length;

  /* ---- صفحةُ قارئٍ بعينه ---- */
  if (QAV.rid) {
    const r = qaReciter(QAV.rid);
    if (!r) { QAV.rid = ""; return qaudioPage(); }
    return `<div class="page qa-page">
      ${pageHead("القرآن الكريم المسموع", r.name, backArrow())}
      <div class="card qa-hero">
        <span class="qa-ava big">${r.image
          ? `<img src="${esc(r.image)}" alt="${esc(r.name)}">` : `<i>${esc(r.letter)}</i>`}</span>
        <div class="qa-hero-t">
          <strong>${esc(r.name)}</strong>
          <small>${esc(r.nameEn)} · ${esc(r.riwaya)}</small>
          <p>${esc(r.desc)}</p>
        </div>
      </div>

      <div class="qa-tools">
        <div class="qa-search">${ic("search", 16)}
          <input placeholder="ابحث عن سورة" oninput="window.qaSearch(this.value)"
            value="${esc(QAV.q)}"></div>
        <button type="button" class="qa-chip${QAV.fav ? " on" : ""}"
          onclick="window.qaFavView(${QAV.fav ? "false" : "true"})">
          ${ic("star", 14)} المفضّلة</button>
        <label class="qa-chip qa-auto"><input type="checkbox" ${qaPrefs().auto ? "checked" : ""}
          onchange="window.qaAuto(this.checked)"> تشغيلٌ تلقائيٌّ للتالية</label>
      </div>

      ${ready ? `<div class="card qa-list" id="qaList">${qaRowsHTML(r.id)}</div>`
              : `<div class="card"><div class="qa-empty">${ic("book", 22)}
                   <span>يُحمَّل فهرسُ السور…</span></div></div>`}
    </div>`;
  }

  /* ---- شبكةُ القرّاء ---- */
  const last = qaPrefs().last;
  const lastR = last ? qaReciter(last.rid) : null;
  const lastN = last && typeof QSURAHS !== "undefined" && QSURAHS
    ? ((QSURAHS.find(x => Number(x.i) === Number(last.n)) || {}).n || "") : "";

  return `<div class="page qa-page">
    ${pageHead("القرآن الكريم المسموع", "اختر القارئ ثمّ السورة")}
    ${qaDutyBox()}
    ${lastR && lastN ? `<button type="button" class="card qa-resume" onclick="window.qaResume()">
      <span class="qa-res-ico">${ic("play", 18)}</span>
      <span class="qa-res-t"><strong>متابعة الاستماع</strong>
        <small>${esc(lastN)} — ${esc(lastR.name)} · ${qaClock(last.t)}</small></span>
    </button>` : ""}
    <div class="qa-grid">${QA_RECITERS.map(x => qaCard(qaReciter(x.id))).join("")}</div>
    <div class="qa-note">${ic("info", 14)}
      <span>التلاواتُ تُبثّ من المكتبة الصوتية للقرآن الكريم (MP3Quran.net)،
      ولا تُنسخ إلى خوادم النظام.</span></div>
    ${(typeof isTopAdmin === "function" && isTopAdmin()) ? `<div class="qa-admin">
      <button type="button" class="btn btn-ghost btn-sm" onclick="window.qaCheckRun()">
        ${ic("check", 15)} فحصُ روابط القرّاء الأربعة</button>
      <span class="muted" style="font-size:11.5px">٤٥٦ رابطاً — يُفحص عند الطلب وحدَه</span>
      <div id="qaCheckOut" class="qa-chk"></div></div>` : ""}
  </div>`;
}

/* =========================================================================
   الاستماعُ إلى الواجب مباشرةً — بلا بحثٍ عن السورة
   -------------------------------------------------------------------------
   المواصفات: «إذا وُجّه إلى الطالب واجبُ سورة آل عمران مثلاً أو تثبيت،
   يدخل على الاستماع فيذهب مباشرةً إلى الواجب المطلوب لسماعه دون البحث عنه».

   الواجباتُ من محرّك الخطط نفسِه الذي يراه المعلّم (generateAssignments)،
   لا من قائمةٍ ثانية. والاستماعُ بالآية متى توفّر للقارئ — من أوّل آيةٍ
   في الواجب إلى آخرها ثمّ يقف، لا إلى آخر السورة. وإن لم تتوفّر تلاوةُ
   آيةٍ لذلك القارئ شُغّلت السورةُ كاملةً وقيل له ذلك.
   ========================================================================= */
function qaDuties(st) {
  if (!st) return [];
  let list = [];
  try { list = generateAssignments(st.id, todayISO()) || []; } catch (e) { list = []; }
  return list.filter(a => a && a.fromS).map(a => {
    const fromS = Number(a.fromS), fromA = Math.max(1, Number(a.fromA) || 1);
    const toS = Number(a.toS) || fromS, toA = Number(a.toA) || 0;
    const nm = i => (typeof surahName === "function" ? surahName(i) : "");
    /* اسمُ السورة مرّةً واحدةً إن لم يتغيّر: «آل عمران ١ — ١٠» لا
       «آل عمران ١ — آل عمران ١٠» */
    const range = !(toS && toA)
      ? nm(fromS) + " " + toArabicDigits(fromA) + " فما بعدها"
      : (toS === fromS
          ? nm(fromS) + " " + toArabicDigits(fromA) + " — " + toArabicDigits(toA)
          : nm(fromS) + " " + toArabicDigits(fromA) + " — " + nm(toS) + " " + toArabicDigits(toA));
    return { kind: String(a.kind).replace("_makeup", ""),
             kindName: a.kindName || a.kind, fromS, fromA, toS, toA,
             range, done: a.status === "done" };
  });
}

/* القارئُ المختار: آخرُ مَن استُمع إليه، وإلا أوّلُ من له تلاوةُ آية */
function qaDutyReciter() {
  if (MUSA.rid) return MUSA.rid;
  const l = qaPrefs().last;
  if (l && l.rid && qaReciter(l.rid)) return l.rid;
  const r = QA_RECITERS.find(qaHasAyah);
  return r ? r.id : QA_RECITERS[0].id;
}

window.qaDutyPick = function (rid) {
  MUSA.rid = String(rid || "");
  const p = qaPrefs();
  p.last = Object.assign({ n: 1, t: 0 }, p.last || {}, { rid: MUSA.rid });
  qaPrefsSave();
  mount();
};

/* تشغيلُ الواجب: من أوّل آيةٍ فيه، ويقف عند آخرها */
window.qaPlayDuty = async function (fromS, fromA, toS, toA) {
  const rid = qaDutyReciter();
  MUSA.rid = rid;
  const r = qaReciter(rid);
  const s = Number(fromS), a = Math.max(1, Number(fromA) || 1);

  if (qaHasAyah(r)) {
    MUSA.on = true;
    MUSA.lim = { s: Number(toS) || s, a: Number(toA) || 0 };
    await window.qaAyahPlay(s, a);
    showToast("تلاوةُ واجبك — " + (r.name || ""), "success");
    mount();
    return;
  }
  /* بلا تلاوةِ آية: السورةُ كاملةً وقولُ السبب — لا تخمين */
  MUSA.lim = null;
  window.qaPlay(rid, s);
  showToast((r ? r.name : "") + ": لا تتوفّر تلاوةٌ بالآية — شُغّلت السورةُ كاملة", "info");
  QAV.rid = rid; mount();
};

/* بطاقةُ «استمع إلى واجبك» في أعلى شاشة المسموع */
function qaDutyBox() {
  const u = (STATE && STATE.user) || {};
  if (u.role !== "student" && u.role !== "parent") return "";
  const st = typeof activeStudent === "function" ? activeStudent() : null;
  if (!st) return "";
  const duties = qaDuties(st);
  if (!duties.length) return "";

  const rid = qaDutyReciter();
  const ICON = { hifz: "book", fix: "refresh", rev: "list", tilawah: "book" };

  return `<div class="card qa-duty">
    <div class="qa-duty-head">${ic("target", 17)}
      <strong>استمع إلى واجبك اليوم</strong>
      <select class="musa-sel" onchange="window.qaDutyPick(this.value)">
        ${QA_RECITERS.map(x => `<option value="${esc(x.id)}"${
          rid === x.id ? " selected" : ""}>${esc(x.name)}${
          qaHasAyah(x) ? "" : " (بالسورة)"}</option>`).join("")}
      </select>
    </div>
    <div class="qa-duty-list">${duties.map(d => `<button type="button"
      class="qa-duty-row${d.done ? " done" : ""}"
      onclick="window.qaPlayDuty(${d.fromS},${d.fromA},${d.toS},${d.toA})">
      <span class="qa-duty-ico">${ic(ICON[d.kind] || "book", 16)}</span>
      <span class="qa-duty-t"><strong>${esc(d.kindName)}</strong>
        <small>${esc(d.range)}</small></span>
      <span class="qa-duty-go">${ic("play", 15)} استماع</span>
    </button>`).join("")}</div>
  </div>`;
}

/* شريطُ المشغّل الثابت — يُركَّب مرّةً فوق الشريط السفليّ ولا يحجبه */
function qaBarMount() {
  try {
    if (document.getElementById("qaBar")) { qaBarSync(); return; }
    const p = qaPrefs();
    const bar = document.createElement("div");
    bar.id = "qaBar";
    bar.className = "qa-bar";
    bar.innerHTML =
      `<div class="qab-head">
         <strong class="qab-title"></strong>
         <button type="button" class="qab-x" title="إغلاق المشغّل"
           onclick="window.qaStop(); document.getElementById('qaBar').classList.remove('on');">
           ${ic("x", 15)}</button>
       </div>
       <input class="qab-range" type="range" min="0" max="100" value="0"
         oninput="window.qaSeek(this.value)">
       <div class="qab-row">
         <span class="qab-time">٠٠:٠٠ / ٠٠:٠٠</span>
         <div class="qab-ctrl">
           <button type="button" class="qab-b qab-prev" title="السابقة" onclick="window.qaStep(-1)">${ic("arrowLeft", 17)}</button>
           <button type="button" class="qab-b qab-play" title="تشغيل / إيقاف مؤقت" onclick="window.qaToggle()">${ic("play", 20)}</button>
           <button type="button" class="qab-b" title="إيقاف" onclick="window.qaStop()">${ic("x", 17)}</button>
           <button type="button" class="qab-b" title="التالية" onclick="window.qaStep(1)">${ic("arrowLeft", 17)}</button>
         </div>
         <div class="qab-more">
           <select class="qab-rate" title="سرعة التشغيل" onchange="window.qaRate(this.value)">
             ${[0.75, 1, 1.25, 1.5, 2].map(v =>
               `<option value="${v}"${v === p.rate ? " selected" : ""}>${toArabicDigits(v)}×</option>`).join("")}
           </select>
           <span class="qab-vol">${ic("mic", 14)}
             <input type="range" min="0" max="100" value="${Math.round(p.vol * 100)}"
               oninput="window.qaVol(this.value)" title="الصوت"></span>
         </div>
       </div>`;
    document.body.appendChild(bar);
    /* ويُعاد القياسُ عند تغيّر العرض: الشريطُ السفليُّ يظهر ويختفي بالمقاس */
    if (!window.__qaResize) {
      window.__qaResize = true;
      window.addEventListener("resize", function () { qaBarSync(); });
    }
    qaBarSync();
  } catch (e) {}
}
window.qaBarMount = qaBarMount;

/* =========================================================================
   التحقّقُ من الروابط — أداةُ تطوير، لا تعمل عند فتح الصفحة
   -------------------------------------------------------------------------
   المواصفات: «لا تجعل التطبيق يفحص ٤٥٦ ملفاً عند كل فتح». تُنادى من
   الطرفية عند تجهيز المصادر وحدَها. والفحصُ بـ HEAD لا يُنزّل الملف.
   ========================================================================= */
/* الفحصُ من زرٍّ في الشاشة — لمدير النظام وحدَه، وبطلبه لا تلقائياً */
window.qaCheckRun = async function () {
  if (!(typeof isTopAdmin === "function" && isTopAdmin())) {
    showToast("الفحصُ من صلاحية مدير النظام", "warn"); return;
  }
  const box = document.getElementById("qaCheckOut");
  if (box) box.innerHTML = `<div class="qa-chk-run">${ic("refresh", 14)} جارٍ فحصُ ٤٥٦ رابطاً…</div>`;
  const rows = await window.validateReciterAudioSources();
  const by = {};
  rows.forEach(function (r) {
    by[r.reciterId] = by[r.reciterId] || { name: r.reciter, ok: 0, bad: 0, unk: 0, first: "" };
    if (r.status === "ok") by[r.reciterId].ok++;
    else if (r.status === "unknown") { by[r.reciterId].unk++; if (!by[r.reciterId].first) by[r.reciterId].first = r.error || ""; }
    else { by[r.reciterId].bad++; if (!by[r.reciterId].first) by[r.reciterId].first = "سورة " + r.surah + " — " + (r.error || ""); }
  });
  if (!box) return;
  box.innerHTML = `<table class="ptable"><thead><tr>
      <th>القارئ</th><th>السور</th><th>المتاح</th><th>غير المتاح</th><th>مجهول</th><th>النتيجة</th>
    </tr></thead><tbody>${Object.keys(by).map(function (k) {
      const v = by[k];
      const good = v.ok === 114;
      return `<tr><td class="pt-name">${esc(v.name)}</td>
        <td class="pt-num">${toArabicDigits(v.ok + v.bad + v.unk)}</td>
        <td class="pt-num">${toArabicDigits(v.ok)}</td>
        <td class="pt-num">${toArabicDigits(v.bad)}</td>
        <td class="pt-num">${toArabicDigits(v.unk)}</td>
        <td>${good ? '<span class="pt-badge on">سليم</span>'
                   : `<span class="pt-badge off">${esc(v.first || "راجع الطرفية")}</span>`}</td></tr>`;
    }).join("")}</tbody></table>
    <div class="muted" style="font-size:11.5px;margin-top:6px">
      «مجهول» يعني أنّ المصدر منع الطلبَ الآليَّ أو حجب CORS — ولا يعني أنّ الرابط معطوب.
      التفصيلُ الكامل في الطرفية عبر <code>window.__qaValidation</code>.</div>`;
};

window.validateReciterAudioSources = async function (opts) {
  opts = opts || {};
  const only = opts.reciter ? [opts.reciter] : QA_RECITERS.map(r => r.id);
  const nums = opts.surahs || Array.from({ length: 114 }, (_, i) => i + 1);
  const out = [];
  for (const rid of only) {
    const r = qaReciter(rid);
    for (const n of nums) {
      const url = qaUrl(rid, n);
      const row = { reciter: r ? r.name : rid, reciterId: rid, surah: n, url: url, status: "" };
      if (!url) { row.status = "unavailable"; row.error = "تعذّر توليد الرابط"; out.push(row); continue; }
      try {
        const res = await fetch(url, { method: "HEAD", mode: "cors" });
        row.status = res.ok ? "ok" : "unavailable";
        if (!res.ok) row.error = "HTTP " + res.status;
      } catch (e) {
        /* المصدرُ قد يمنع الطلبَ الآليَّ أو يحجب CORS — لا يُتحايل عليه */
        row.status = "unknown"; row.error = String(e && e.message || e);
      }
      out.push(row);
    }
  }
  /* ومصدرُ التلاوة بالآية: أوّلُ آيةٍ من أوّل سورةٍ تكفي للحكم على المصدر */
  for (const rid of only) {
    const r = qaReciter(rid);
    if (!qaHasAyah(r)) continue;
    const row = { reciter: (r ? r.name : rid) + " — بالآية", reciterId: rid,
                  surah: 1, url: "", status: "" };
    try {
      const list = await qaAyahLoad(rid, 1);
      row.url = (list && list[0] && list[0].url) || "";
      if (!row.url) { row.status = "unavailable"; row.error = "لا رابطَ للآية"; }
      else {
        const res = await fetch(row.url, { method: "HEAD", mode: "cors" });
        row.status = res.ok ? "ok" : "unavailable";
        if (!res.ok) row.error = "HTTP " + res.status;
      }
    } catch (e) {
      row.status = "unknown"; row.error = String(e && e.message || e);
    }
    out.push(row);
  }

  const bad = out.filter(x => x.status !== "ok");
  console.table(out.slice(0, 20));
  console.log("المجموع: " + out.length + " · سليم: " + (out.length - bad.length) +
              " · غير متاح/مجهول: " + bad.length);
  if (bad.length) console.table(bad.slice(0, 40));
  window.__qaValidation = out;
  return out;
};

function todayISO() {
  const d = new Date();
  return new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
}

/* =========================================================================
   التواريخُ الهجرية — طبقةُ عرضٍ لا طبقةُ تخزين
   -------------------------------------------------------------------------
   المواصفات: «أريد جعل التواريخ كلها بالهجري، ما عدا مسيّرات الرواتب في
   موقع الإدارة وما يتعلق بتحضير المعلمين».
   المخزونُ في فايرستور يبقى ميلادياً كما هو — لا يُمسّ منه حرفٌ، فالفلاترُ
   والمقارناتُ والمسيّراتُ كلُّها تقرأ ISO — وإنما يُحوَّل ما يُعرض على
   الشاشة وحدَه. ولذلك جُعل التحويلُ بعد الرسم لا داخلَه: فالتواريخُ تُطبع
   في المشروع بعشرات الصيغ (ISO خاماً، وtoArabicDigits، وtoLocaleDateString)
   في مئات الموضعِ، فتعديلُها موضعاً موضعاً يمسّ ما لا علاقة له بالطلب.
   والاستثناءُ يُؤشَّر بـ data-greg على جذر الشاشة، فيمرّ المحوّلُ عنها
   ولا يلمس شيئاً في داخلها — ونوافذُها ولوحاتُها ترث تأشيرَها.
   ========================================================================= */
const HIJ_MONTHS = ["محرم", "صفر", "ربيع الأول", "ربيع الآخر", "جمادى الأولى",
  "جمادى الآخرة", "رجب", "شعبان", "رمضان", "شوال", "ذو القعدة", "ذو الحجة"];
/* أسماءُ الشهور الميلادية كما يطبعها المتصفّحُ بالعربية — بها نتعرّف عليها */
const GRG_MONTHS_AR = ["يناير", "فبراير", "مارس", "أبريل", "مايو", "يونيو",
  "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"];

/* ميلادي → هجري: تقويمُ أمّ القرى من المتصفّح، وإن تعذّر فحسابٌ تقويميّ */
function hijriParts(y, m, d) {
  try {
    const f = new Intl.DateTimeFormat("en-US-u-ca-islamic-umalqura",
      { day: "numeric", month: "numeric", year: "numeric", timeZone: "UTC" });
    const p = {};
    f.formatToParts(new Date(Date.UTC(y, m - 1, d, 12))).forEach(x => { p[x.type] = x.value; });
    const hy = parseInt(p.year, 10), hm = parseInt(p.month, 10), hd = parseInt(p.day, 10);
    if (hy > 1200 && hy < 1700 && hm >= 1 && hm <= 12 && hd >= 1 && hd <= 30) {
      return { y: hy, m: hm, d: hd };
    }
  } catch (e) {}
  return hijriCivil(y, m, d);
}

/* البديلُ عند غياب التقويم من المتصفّح — الحسابيُّ عبر اليوم اليوليانيّ */
function hijriCivil(y, m, d) {
  const a = Math.floor((14 - m) / 12), y2 = y + 4800 - a, m2 = m + 12 * a - 3;
  const jd = d + Math.floor((153 * m2 + 2) / 5) + 365 * y2 + Math.floor(y2 / 4)
    - Math.floor(y2 / 100) + Math.floor(y2 / 400) - 32045;
  let l = jd - 1948440 + 10632;
  const n = Math.floor((l - 1) / 10631);
  l = l - 10631 * n + 354;
  const j = Math.floor((10985 - l) / 5316) * Math.floor(50 * l / 17719)
    + Math.floor(l / 5670) * Math.floor(43 * l / 15238);
  l = l - Math.floor((30 - j) / 15) * Math.floor(17719 * j / 50)
    - Math.floor(j / 16) * Math.floor(15238 * j / 43) + 29;
  const hm = Math.floor(24 * l / 709);
  return { y: 30 * n + j - 30, m: hm, d: l - Math.floor(709 * hm / 24) };
}

/* ١٤/٠٤/١٤٤٨هـ */
function hijriShort(y, m, d) {
  const h = hijriParts(y, m, d), p = n => (n < 10 ? "0" : "") + n;
  return toArabicDigits(p(h.d) + "/" + p(h.m) + "/" + h.y) + "هـ";
}
/* ١٤ ربيع الآخر ١٤٤٨هـ */
function hijriLong(y, m, d) {
  const h = hijriParts(y, m, d);
  return toArabicDigits(h.d) + " " + HIJ_MONTHS[h.m - 1] + " " + toArabicDigits(h.y) + "هـ";
}
/* شهرٌ ميلاديٌّ كاملٌ بلا يوم: لا يقابله شهرٌ هجريٌّ واحدٌ غالباً، فيُكتب
   مدى الشهور التي يقع فيها — «ربيع الأول – ربيع الآخر ١٤٤٨هـ» — ولا يُنسب
   إلى أحدهما فيُوهم أنّ الصفحةَ شهرٌ هجريٌّ كامل. */
function hijriMonthName(y, m) {
  const days = new Date(y, m, 0).getDate();
  const a = hijriParts(y, m, 1), b = hijriParts(y, m, days);
  if (a.m === b.m && a.y === b.y) return HIJ_MONTHS[a.m - 1] + " " + toArabicDigits(a.y) + "هـ";
  if (a.y === b.y) {
    return HIJ_MONTHS[a.m - 1] + " – " + HIJ_MONTHS[b.m - 1] + " " + toArabicDigits(a.y) + "هـ";
  }
  return HIJ_MONTHS[a.m - 1] + " " + toArabicDigits(a.y) + "هـ – " +
         HIJ_MONTHS[b.m - 1] + " " + toArabicDigits(b.y) + "هـ";
}

/* تاريخٌ مخزَّنٌ (ISO أو طابعٌ زمنيّ) → نصٌّ هجريٌّ للعرض */
function hijriOf(v, long) {
  if (v == null || v === "") return "";
  const s = String(v), iso = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  let y, m, d;
  if (iso) { y = +iso[1]; m = +iso[2]; d = +iso[3]; }
  else {
    const n = Number(v), dt = new Date(s === String(n) ? n : s);
    if (isNaN(dt.getTime())) return "";
    y = dt.getFullYear(); m = dt.getMonth() + 1; d = dt.getDate();
  }
  if (!(y > 1900 && y < 2200 && m >= 1 && m <= 12 && d >= 1 && d <= 31)) return "";
  return long ? hijriLong(y, m, d) : hijriShort(y, m, d);
}
window.hijriOf = hijriOf;
window.hijriMonthName = hijriMonthName;
window.hijriParts = hijriParts;

/* ---- التعرّفُ على التواريخ في النصّ المعروض ---- */
const HIJ_D = "[0-9٠-٩]";               /* رقمٌ لاتينيٌّ أو عربيّ */
const HIJ_W = "[0-9٠-٩A-Za-z_]";        /* ما لا يصحّ أن يحدّ تاريخاً */
/* علامةُ الاتجاه التي يحشرها المتصفّحُ بين أجزاء التاريخ العربيّ */
const HIJ_RL = "[\\u200f\\u200e]?";
function hijLatin(s) {
  return String(s).replace(/[٠-٩]/g, c => String(c.charCodeAt(0) - 0x660));
}
/* والشَّرطةُ قبلَه أو بعدَه تُخرجه: «ref-2026-10-06» معرِّفٌ لا تاريخ */
const HIJ_RE_ISO = new RegExp(
  "(^|[^" + HIJ_W.slice(1, -1) + "-])(" + HIJ_D + "{4})-(" + HIJ_D + "{1,2})-(" + HIJ_D +
  "{1,2})(?![" + HIJ_W.slice(1, -1) + "-])", "g");
const HIJ_RE_SLASH = new RegExp(
  "(^|[^" + HIJ_W.slice(1) + ")(" + HIJ_D + "{1,4})" + HIJ_RL + "/" + HIJ_RL +
  "(" + HIJ_D + "{1,2})" + HIJ_RL + "/" + HIJ_RL + "(" + HIJ_D + "{1,4})(?!" + HIJ_W + ")", "g");
const HIJ_RE_LONG = new RegExp(
  "(^|[^" + HIJ_W.slice(1) + ")(" + HIJ_D + "{1,2})\\s+(" + GRG_MONTHS_AR.join("|") +
  ")\\s+(" + HIJ_D + "{4})(?!" + HIJ_W + ")", "g");
const HIJ_RE_MONTH = new RegExp(
  "(^|[^\\u0621-\\u064aA-Za-z])(" + GRG_MONTHS_AR.join("|") + ")\\s+(" + HIJ_D +
  "{4})(?!" + HIJ_W + ")", "g");

function hijValid(y, m, d) {
  return y > 1900 && y < 2200 && m >= 1 && m <= 12 && d >= 1 && d <= 31;
}

/* يُبدّل كلَّ تاريخٍ ميلاديٍّ في النصّ بمقابله الهجريّ، ويترك ما ليس تاريخاً.
   والنتيجةُ لا تُطابق هذه الأنماطَ من جديد (سنتُها هجريةٌ ومختومةٌ بـ هـ)،
   فإعادةُ التمرير على النصّ نفسه لا تُغيّره. */
function hijriText(s) {
  let t = String(s);
  if (!/[0-9٠-٩]/.test(t)) return t;
  t = t.replace(HIJ_RE_ISO, function (all, pre, a, b, c) {
    const y = +hijLatin(a), m = +hijLatin(b), d = +hijLatin(c);
    return hijValid(y, m, d) ? pre + hijriShort(y, m, d) : all;
  });
  t = t.replace(HIJ_RE_LONG, function (all, pre, a, mon, c) {
    const d = +hijLatin(a), y = +hijLatin(c), m = GRG_MONTHS_AR.indexOf(mon) + 1;
    return hijValid(y, m, d) ? pre + hijriLong(y, m, d) : all;
  });
  t = t.replace(HIJ_RE_SLASH, function (all, pre, a, b, c) {
    const x = +hijLatin(a), m = +hijLatin(b), z = +hijLatin(c);
    /* السنةُ هي الجزءُ رباعيُّ الأرقام: ٢٠٢٦/١٠/٠٦ أو ٠٦/١٠/٢٠٢٦ */
    if (String(hijLatin(c)).length === 4 && hijValid(z, m, x)) return pre + hijriShort(z, m, x);
    if (String(hijLatin(a)).length === 4 && hijValid(x, m, z)) return pre + hijriShort(x, m, z);
    return all;
  });
  t = t.replace(HIJ_RE_MONTH, function (all, pre, mon, c) {
    const y = +hijLatin(c), m = GRG_MONTHS_AR.indexOf(mon) + 1;
    return y > 1900 && y < 2200 ? pre + hijriMonthName(y, m) : all;
  });
  return t;
}
window.hijriText = hijriText;

/* ---- المرورُ على الشاشة بعد رسمها ---- */
const HIJ_SKIP_TAGS = {
  INPUT: 1, TEXTAREA: 1, SELECT: 1, OPTION: 1, OPTGROUP: 1,
  SCRIPT: 1, STYLE: 1, CODE: 1, PRE: 1, TEXT: 1, TSPAN: 1
};

/* هل هذا الموضعُ من المستثنى؟ مسيّراتُ الرواتب وشاشاتُ دوام الموظفين
   تُؤشَّر بـ data-greg، وشريطُ الفلاتر الأعلى هجريٌّ أصلاً. */
function hijExcluded(el) {
  for (let n = el; n && n.nodeType === 1; n = n.parentElement) {
    if (n.hasAttribute && n.hasAttribute("data-greg")) return true;
    if (n.id === "topFilters") return true;
    if (n.classList && n.classList.contains("topbar-filters")) return true;
  }
  return false;
}
/* نافذةٌ تُفتح فوق شاشةٍ مستثناةٍ ترث استثناءها — فنوافذُ «دوام الموظفين»
   في duty-plus.js تبقى ميلاديةً بلا تعديلٍ في ملفّها. */
function hijGregHere() {
  try {
    const r = document.getElementById("pageContent");
    return !!(r && (r.hasAttribute("data-greg") || r.querySelector("[data-greg]")));
  } catch (e) { return false; }
}
window.hijGregHere = hijGregHere;

function hijriSweep(root) {
  if (!root || !window.__hijOn) return;
  try {
    if (root.nodeType === 3) {
      const v = root.nodeValue, p0 = root.parentElement;
      if (!v || v.length < 5 || !p0 || HIJ_SKIP_TAGS[p0.tagName]) return;
      if (!hijExcluded(p0)) {
        const o = hijriText(v);
        if (o !== v) root.nodeValue = o;
      }
      return;
    }
    if (root.nodeType !== 1) return;
    if (HIJ_SKIP_TAGS[root.tagName] || hijExcluded(root)) return;
    const hits = [];
    const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null);
    for (let t = w.nextNode(); t; t = w.nextNode()) {
      const v = t.nodeValue;
      if (!v || v.length < 5 || !/[0-9٠-٩]/.test(v)) continue;
      const p = t.parentElement;
      if (!p || HIJ_SKIP_TAGS[p.tagName] || p.isContentEditable) continue;
      if (p.ownerSVGElement || p.tagName === "svg") continue;
      if (hijExcluded(p)) continue;
      hits.push(t);
    }
    hits.forEach(function (t) {
      const o = hijriText(t.nodeValue);
      if (o !== t.nodeValue) t.nodeValue = o;
    });
  } catch (e) {}
}
window.hijriSweep = hijriSweep;

/* المراقبُ: يمرّ على ما يُضاف إلى الصفحة وحدَه لا على الصفحة كلّها، فيلحق
   كلَّ مسارات الرسم — mount والنوافذ واللوحات وملفّات الإدارة المستقلّة —
   بلا تعديلٍ في أيٍّ منها. وتغييرُنا نصَّ عقدةٍ قائمةٍ لا يُشعله: هو لا
   يراقب characterData. */
function hijriWatch() {
  if (window.__hijMo || !document.body) return;
  window.__hijOn = true;
  try {
    const mo = new MutationObserver(function (recs) {
      for (let i = 0; i < recs.length; i++) {
        const a = recs[i].addedNodes;
        for (let j = 0; j < a.length; j++) hijriSweep(a[j]);
      }
    });
    mo.observe(document.body, { childList: true, subtree: true });
    window.__hijMo = mo;
  } catch (e) {}
  hijriSweep(document.body);
}
window.hijriWatch = hijriWatch;
if (typeof window !== "undefined" && typeof document !== "undefined") {
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", function () { hijriWatch(); });
  } else setTimeout(hijriWatch, 0);
}

/* =========================================================================
   الطالبُ في أكثر من حلقة
   -------------------------------------------------------------------------
   المواصفات: «الطالب قد يكون في أكثر من حلقة — الفجر والعصر — وتحضيرُه
   مستقلٌّ في كلٍّ منهما، وخطتُه القرآنية واحدةٌ ومصحفُه واحد».
   حقلُ circleId مفردٌ لا يسع إلا واحدة، فأُضيف circleIds ويُقرآن معاً.
   ========================================================================= */
function studentCircleIds(st) {
  if (!st) return [];
  const out = [];
  if (Array.isArray(st.circleIds)) st.circleIds.forEach(x => {
    if (x && out.indexOf(String(x)) < 0) out.push(String(x));
  });
  if (st.circleId && out.indexOf(String(st.circleId)) < 0) out.push(String(st.circleId));
  return out;
}
window.studentCircleIds = studentCircleIds;

/* طلابُ حلقةٍ بعينها — يشمل من كانت إحدى حلقاته */
function circleStudents(circleId) {
  const cid = String(circleId || "");
  if (!cid) return [];
  return (cur("students") || []).filter(x => studentCircleIds(x).indexOf(cid) > -1);
}
window.circleStudents = circleStudents;

/* مفتاحُ سجلّ الحضور: بالحلقة إن حُدِّدت، وإلا كما كان — فسجلّاتُ ما مضى
   تبقى مقروءةً ولا يُكسر ما بُني عليها. */
function attId(dateISO, studentId, circleId) {
  const base = String(dateISO) + "__" + String(studentId);
  return circleId ? base + "__" + String(circleId) : base;
}

/* حضورُ طالبٍ في يومٍ وحلقةٍ بعينها — وإلا فأيُّ سجلٍّ له في ذلك اليوم */
function attOf(studentId, dateISO, circleId) {
  const all = (cur("attendance") || []).filter(r =>
    String(r.studentId) === String(studentId) && String(r.date) === String(dateISO));
  if (!circleId) return all[0] || null;
  return all.find(r => String(r.circleId || "") === String(circleId)) || null;
}
window.attOf = attOf;

/* سجلات يوم واحد لطلاب النطاق الحالي، على هيئة خريطة studentId -> سجل */
/* الحلقةُ المعروضة في شاشة التحضير — الفجرُ أو العصر، ولكلٍّ سجلُّه */
function attCircle() {
  if (STATE.attCircle === undefined && typeof workCircleInit === "function") workCircleInit();
  return String(STATE.attCircle || "");
}
window.attCircleSet = function (cid) {
  /* تحضيرٌ لم يُحفظ يُحفظ في حلقته قبل الانتقال — وإلا كُتب على الأخرى */
  if (Object.keys(STATE.attDraft || {}).length) {
    showToast("احفظ التحضير أولاً قبل الانتقال إلى حلقة أخرى", "warn"); return;
  }
  STATE.attCircle = String(cid || "");
  const u = (STATE && STATE.user) || {};
  try { localStorage.setItem(ATT_CIRCLE_KEY + ":" + (u.uid || u.email || ""), STATE.attCircle || "*"); } catch (e) {}
  mount();
};
/* =========================================================================
   حلقةُ العمل للمعلّم — يختارها فتتبعها الشاشات كلُّها
   -------------------------------------------------------------------------
   المواصفات: «عند تسجيل المعلم دخوله تظهر له قائمة بجميع الحلقات المسندة
   إليه، وبمجرد اختيار الحلقة تتغير شاشة التحضير وقائمة الطلاب فوراً».
   كان الاختيارُ في شاشة التحضير وحدها، ويضيع مع كلّ تحميل، والتسميعُ يعرض
   طلاب الحلقات كلّها ويُسجَّل على الحلقة الأولى للطالب أيّاً كانت الجلسة.
   ========================================================================= */
const ATT_CIRCLE_KEY = "mirath_att_circle";

/* حلقاتُ طلاب النطاق (للمعلّم: حلقاتُه) — [معرّف، اسم] */
function workCircles() {
  const set = new Map();
  (cur("students") || []).forEach(s2 => studentCircleIds(s2).forEach(cid => {
    if (!cid || set.has(cid)) return;
    const c = (cur("circles") || []).find(x => String(x.id) === cid);
    set.set(cid, (c && c.name) || s2.circle || cid);
  }));
  return [...set.entries()];
}

/* الحلقةُ الأقربُ وقتاً الآن — اختيارٌ أوّل حين يدخل المعلّم ولم يختر */
function workCircleByTime(list) {
  const toMin = t => { const m = String(t || "").match(/^(\d{1,2}):(\d{2})/); return m ? +m[1] * 60 + +m[2] : null; };
  const now = toMin(nowHHMM());
  let best = null, bestGap = Infinity;
  list.forEach(([cid]) => {
    const c = (cur("circles") || []).find(x => String(x.id) === cid);
    const st = c ? toMin(typeof circleStartAt === "function" ? circleStartAt(c, todayISO()) : c.start) : null;
    if (st == null || now == null) return;
    const gap = Math.abs(now - st);
    if (gap < bestGap) { bestGap = gap; best = cid; }
  });
  return best || (list[0] ? list[0][0] : "");
}

/* يُضبط مرّةً عند أوّل رسم: المحفوظُ إن بقي صالحاً، وإلا الأقربُ وقتاً */
function workCircleInit() {
  if (STATE.attCircle !== undefined) return;
  const u = (STATE && STATE.user) || {};
  const list = workCircles();
  let saved = "";
  try { saved = localStorage.getItem(ATT_CIRCLE_KEY + ":" + (u.uid || u.email || "")) || ""; } catch (e) {}
  if (saved === "*" ) { STATE.attCircle = ""; return; }
  if (saved && list.some(([cid]) => cid === saved)) { STATE.attCircle = saved; return; }
  STATE.attCircle = (u.role === "teacher" && list.length > 1) ? workCircleByTime(list) : "";
}

/* شريطُ الحلقات — واحدٌ تتقاسمه الشاشات */
function workCircleBar(withAll) {
  const list = workCircles();
  if (list.length < 2) return "";
  return `<div class="amount-preview" style="margin-bottom:10px">
    ${withAll ? `<button class="chip${attCircle() ? "" : " day-on"}"
      style="border:none" onclick="window.attCircleSet('')">كل الحلقات</button>` : ""}
    ${list.map(([cid, nm]) => `<button class="chip${attCircle() === cid ? " day-on" : ""}"
      style="border:none" onclick="window.attCircleSet('${jsAttr(cid)}')">${esc(nm)}</button>`).join("")}
  </div>`;
}

/* طلابُ الحلقة المختارة — ومنهم من له حلقةٌ أخرى */
function inWorkCircle(list) {
  const cid = attCircle();
  if (!cid) return list;
  return list.filter(s2 => studentCircleIds(s2).indexOf(cid) > -1);
}

/* معرّفُ سجلّ اليوم إن وُجد — يُعاد استعماله فلا يتكرّر سجلٌّ لليوم نفسه
   بمفتاحين (قديمٍ بلا حلقة وجديدٍ بها). ذو الحلقة الواحدة سجلٌّ واحدٌ ليومه،
   وذو الحلقتين سجلٌّ لكلّ حلقة. */
function attExistingId(dateISO, sid, cid, multi) {
  const r = (DB.attendance || []).find(x => x && !x.staffId &&
    String(x.date) === String(dateISO) && String(x.studentId) === String(sid) &&
    (!multi || String(x.circleId || "") === String(cid)));
  return r ? String(r.id) : "";
}

/* حلقةُ السجلّ: المختارةُ إن كان الطالب فيها، وإلا أولى حلقاته */
function recCircleOf(st, preferred) {
  const cids = studentCircleIds(st);
  const p = String(preferred || "");
  if (p && cids.indexOf(p) > -1) return p;
  return cids[0] || (st && st.circleId != null ? String(st.circleId) : "");
}


function attMap(dateISO, circleId) {
  const m = {};
  const cid = circleId != null ? String(circleId) : "";
  cur("attendance").forEach(function (r) {
    if (r && r.staffId) return;              /* حضورُ المعلّم ليس سجلَّ طالب */
    if (String(r.date) !== String(dateISO)) return;
    /* بحلقةٍ محدَّدة: سجلُّها وحدَه — وإلا خلط تحضيرُ الفجر بالعصر.
       والسجلُّ القديم بلا حلقةٍ يُقبل فلا يضيع ما سُجّل قبل الفصل. */
    if (cid) {
      const rc = String(r.circleId || "");
      if (rc && rc !== cid) return;
      /* سجلٌّ قديمٌ بلا حلقة لطالبٍ في حلقتين لا يُنسب لإحداهما — وإلا
         سرى غيابُ الفجر على العصر */
      if (!rc) {
        const st0 = (DB.students || []).find(x => String(x.id) === String(r.studentId));
        if (st0 && studentCircleIds(st0).length > 1) return;
      }
    } else if (m[String(r.studentId)]) {
      /* «كل الحلقات»: سجلُّ الحلقة الأولى للطالب يُقدَّم */
      const st0 = (DB.students || []).find(x => String(x.id) === String(r.studentId));
      const first = st0 ? studentCircleIds(st0)[0] : "";
      if (String(m[String(r.studentId)].circleId || "") === String(first)) return;
    }
    m[String(r.studentId)] = r;
  });
  return m;
}

/* التاريخ المعروض في صفحة التحضير — يبدأ باليوم ويتغيّر بأسهم التنقل */
function attDate() {
  if (!STATE.attDate) STATE.attDate = todayISO();
  return STATE.attDate;
}

function attShift(days) {
  const d = new Date(attDate() + "T12:00:00");
  d.setDate(d.getDate() + Number(days || 0));
  const iso = new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
  /* لا تسجيل للمستقبل */
  STATE.attDate = iso > todayISO() ? todayISO() : iso;
  mount();
}


/* =========================================================================
   مسوّدة التحضير — التسجيل يُجمَّع ثم يُحفظ بضغطة واحدة
   -------------------------------------------------------------------------
   كان كل ضغط على حالة يكتب في Firestore فوراً: عشرون طالباً = عشرون كتابة،
   وأي خطأ يحتاج كتابة أخرى لتصحيحه. صار التغيير يُجمَّع في STATE.attDraft
   ثم يُكتب دفعة واحدة عند «حفظ التحضير»، فيرى المعلّم ما سجّله قبل أن
   يلتزم به، ويقدر يعدّل بلا أثر.
   ========================================================================= */

function attDraft() {
  if (!STATE.attDraft) STATE.attDraft = {};
  return STATE.attDraft;
}
function attSel() {
  if (!STATE.attSel) STATE.attSel = {};
  return STATE.attSel;
}

/* الحالة المعروضة لطالب: المسوّدة أولاً ثم المحفوظ */
function attCurrent(studentId, saved) {
  const d = attDraft()[String(studentId)];
  if (d) return d;
  const r = saved[String(studentId)];
  return r ? { status: r.status, reason: r.reason || "", kind: r.kind || "" } : null;
}

function attDraftCount() { return Object.keys(attDraft()).length; }

/* attDraftSet حُذفت: نسخةٌ يتيمة لم يكن يناديها شيء، والمستعمَل attSet
   وهي تحفظ مباشرةً فيمسكها حارس persistSet. وبقاؤها يوهم أن القفل فيها. */

/* «مستأذن» يلزمه سبب — تُفتح نافذة صغيرة قبل التسجيل */
function attExcuseAsk(studentId, forSelected) {
  const ids = forSelected ? Object.keys(attSel()).filter(k => attSel()[k]) : [String(studentId)];
  if (!ids.length) return;

  const names = ids.map(id => {
    const st = DB.students.find(x => String(x.id) === String(id));
    return st ? st.name : id;
  });
  const prev = (attDraft()[ids[0]] || {}).reason || "";

  openModal("سبب الاستئذان", names.length === 1 ? names[0] : names.length + " طلاب",
    `<div class="form-grid">
      <div class="field full"><label>السبب <span class="req">*</span></label>
        <input id="attReason" value="${esc(prev)}" placeholder="مثال: ظرف عائلي · مراجعة طبية"></div>
      <div class="field full"><div class="chip-list">
        ${["ظرف عائلي", "مراجعة طبية", "سفر", "عذر دراسي"].map(r =>
          `<button type="button" class="chip" onclick="document.getElementById('attReason').value='${jsAttr(r)}'">${esc(r)}</button>`).join("")}
      </div></div>
    </div>`,
    `<button class="btn btn-primary" data-action="att-excuse-save" data-ids="${esc(ids.join(","))}">${ic("check", 16)} تسجيل الاستئذان</button>
     <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
  setTimeout(() => { const el = document.getElementById("attReason"); if (el) el.focus(); }, 60);
}

function attExcuseSave(idsCsv) {
  const reason = (val("#attReason") || "").trim();
  if (!reason) { showToast("اكتب سبب الاستئذان", "warn"); return; }
  String(idsCsv || "").split(",").filter(Boolean).forEach(id => {
    attDraft()[String(id)] = { status: "مستأذن", reason: reason };
  });
  closeModal(); mount();
}

/* تعيين حالة لكل المحدَّدين دفعة واحدة */
function attBulk(status) {
  const ids = Object.keys(attSel()).filter(k => attSel()[k]);
  if (!ids.length) { showToast("حدّد طلاباً أولاً", "warn"); return; }
  if (status === "مستأذن") { attExcuseAsk(null, true); return; }
  ids.forEach(id => { attDraft()[String(id)] = { status: status, reason: "" }; });
  mount();
}

window.attToggleSel = function (id) {
  const s = attSel(); const k = String(id);
  if (s[k]) delete s[k]; else s[k] = 1;
  mount();
};
window.attToggleAll = function () {
  const list = cur("students");
  const s = attSel();
  const allOn = list.length && list.every(x => s[String(x.id)]);
  STATE.attSel = {};
  if (!allOn) list.forEach(x => { STATE.attSel[String(x.id)] = 1; });
  mount();
};

/* الحفظ النهائي — كتابة واحدة لكل طالب تغيّرت حالته */
function attSaveAll() {
  const draft = attDraft();
  const ids = Object.keys(draft);
  if (!ids.length) { showToast("لا يوجد تغيير لحفظه", "warn"); return; }

  const dateISO = attDate();
  const u = (STATE && STATE.user) || {};
  if (!Array.isArray(DB.attendance)) DB.attendance = [];

  let n = 0, blocked = 0;
  const touched = [];      /* حلقاتُ ما حُضّر — تُفحص للاعتماد التلقائيّ */
  ids.forEach(sid => {
    const st = DB.students.find(x => String(x.id) === String(sid));
    if (!st) return;
    const d = draft[sid];
    /* حلقةُ التحضير المختارة، كما في attSet — كان المفتاحُ بلا حلقة فيمحو
       حفظُ المسوّدة في العصر تحضيرَ الفجر */
    const cid = recCircleOf(st, attCircle());
    const multi = studentCircleIds(st).length > 1;
    const id = attExistingId(dateISO, sid, cid, multi) || attId(dateISO, sid, multi ? cid : "");
    const cRec = (cur("circles") || []).find(x => String(x.id) === String(cid));
    /* جهةُ التحضير ومهلةُ التعديل: يُتخطّى الممنوعُ ويُذكر عددُه */
    const prevRec = (DB.attendance || []).find(r => String(r.id) === id);
    if (!attMayTake(cid, true) || (prevRec && !attEditOpen(prevRec, true))) { blocked++; return; }
    const rec = {
      id: id, date: dateISO,
      kind: prevRec && prevRec.status === d.status ? (prevRec.kind || "") : "",
      firstTs: prevRec ? (Number(prevRec.firstTs || prevRec.ts) || Date.now()) : Date.now(),
      studentId: String(st.id), student: st.name || "",
      circleId: cid,
      circle: (cRec && cRec.name) || st.circle || "",
      complexId: st.complexId != null ? st.complexId : STATE.complexId,
      status: d.status, reason: d.reason || "",
      /* وقت وصول الطالب لا وقت الحفظ: كان ts وحده، فحالة «متأخر» بلا
         مقدار — خمس دقائق أم ساعة؟ ولا تُقاس بوقت بداية الحلقة. */
      inTime: (d.status === "حاضر" || d.status === "متأخر") ? (d.inTime || nowHHMM()) : "",
      lateMin: d.status === "متأخر" ? lateMinutesOf(st, d.inTime || nowHHMM(), dateISO) : 0,
      /* اليوم من أيام دوامه؟ يُحفظ ليُقرأ في التقارير بلا إعادة حساب */
      onDuty: isDutyDay(st, dateISO),
      /* وسم الفترة: بدونه لا يُعرف السجل من أي دورة، ولا تُفرَز التقارير
         بينها، ولا تُؤرشف فترة دون أن تختلط ببقيّتها. */
      termId: activeTermId() || termOfDate(dateISO),
      by: u.email || "", ts: Date.now()
    };

    /* رسالة ولي الأمر عند الاعتماد — «تخرج الرسالة فوراً» */
    try {
      if (d.status === "غائب" && !d.reason) {
        msgFire("absent", { student: st, date: dateISO });
      } else if (d.status === "متأخر") {
        msgFire("late", { student: st, date: dateISO, minutes: rec.lateMin || 0 });
      }
    } catch (e) {}
    const i = DB.attendance.findIndex(r => String(r.id) === id);
    if (i > -1) DB.attendance[i] = rec; else DB.attendance.push(rec);
    persistSet("attendance", rec);
    if (rec.circleId) touched.push(String(rec.circleId));
    n++;
  });

  STATE.attDraft = {};
  STATE.attSel = {};

  /* حضورُ المعلّم في كلّ حلقةٍ حُضّر طلابُها */
  try { [...new Set(touched)].forEach(cid => staffAutoIn(cid, dateISO)); } catch (e) {}

  /* حلقاتُ ما حُضّر: تُفحص كلُّها فقد يشمل الحفظُ أكثرَ من حلقة */
  try {
    if (typeof autoApproveCheck === "function") {
      [...new Set(touched)].forEach(cid => autoApproveCheck(cid));
    }
  } catch (e) {}

  mount();
  showToast("حُفظ تحضير " + n + " طالباً" + (blocked
    ? " · تُخطّي " + toArabicDigits(blocked) + " (خارج صلاحيتك أو بعد مهلة التعديل)" : ""),
    blocked ? "warn" : "success");
}

/* حذف سجل حضور — كان يُعدَّل ولا يُحذف، فسجلٌ سُجّل بالخطأ لطالب
   ليس في الحلقة يبقى في تقاريره أبداً. */
window.attClear = function (studentId) {
  /* كان يحذف تحضيرَ اليوم بنقرة — يمرّ الآن ببوابة التأكيد (٤٢٨) */
  if (!needDelOk("تحضير هذا الطالب لهذا اليوم", function () { window.attClear(studentId); })) return;
  const dateISO = attDate();
  const stC = (DB.students || []).find(x => String(x.id) === String(studentId));
  const multiC = stC && studentCircleIds(stC).length > 1;
  const cidC = stC ? recCircleOf(stC, attCircle()) : "";
  const id = attExistingId(dateISO, studentId, cidC, multiC) || attId(dateISO, studentId, multiC ? cidC : "");
  const i = (DB.attendance || []).findIndex(r => String(r.id) === id);
  if (i < 0) { showToast("لا سجل لهذا اليوم", "info"); return; }

  const st = (DB.students || []).find(x => String(x.id) === String(studentId));
  DB.attendance.splice(i, 1);
  try { persistDelete("attendance", id); } catch (e) { console.warn("persistDelete:", e); }

  /* المسودّة تُنظَّف أيضاً وإلا أُعيد السجل عند أول حفظ */
  const d = attDraft();
  if (d && d[String(studentId)]) delete d[String(studentId)];

  showToast("حُذف تحضير " + ((st && st.name) || "الطالب") + " لهذا اليوم", "success");
  mount();
};

/* تسجيل حالة طالب — يكتب محلياً ثم في Firestore */
/* =========================================================================
   الحضور الجزئي — المغادرة قبل انتهاء الحلقة
   -------------------------------------------------------------------------
   كان الطالب يُسجَّل حاضراً أو غائباً لا ثالث: فمن حضر نصف ساعةً ثمّ انصرف
   يُحسب حاضراً كاملاً، فتُحتسب له جلسةٌ لم يتمّها، ولا يُعرف من ينصرف
   مبكراً باستمرار.

   يُرصد وقت المغادرة، وتُحسب منه نسبةُ ما حضر من الحلقة. وأثرُه على
   الواجبات بحسب المدّة: من غادر بعد الحدّ يُعفى ممّا لم يُسمّعه، ومن غادر
   قبله يُحتسب عليه كالغياب — إذ لا يُعفى من انصرف في أوّلها.
   ========================================================================= */

/* حدّ الإعفاء: نسبةُ ما يجب حضوره ليُعفى ممّا لم يُسمَّع */
window.partialPctSet = function (v) {
  const s = DB.settings || (DB.settings = {});
  s.partialExemptPct = Math.max(1, Math.min(100, Number(v) || 50));
  Promise.resolve(persistSet("settings", Object.assign({ id: "general" }, s)))
    .then(() => showToast("حُفظ حدّ الإعفاء", "success"));
};

function leaveCfg() {
  const s = DB.settings || {};
  const n = Number(s.partialExemptPct);
  return { pct: isFinite(n) && n > 0 ? n : 50 };
}

/* ما حضره الطالب من الحلقة — نسبةً ودقائق */
function attendedShare(st, rec, dateISO) {
  if (!rec || !rec.leftAt) return null;

  const c = (cur("circles") || []).find(x =>
    String(x.id) === String(st && st.circleId) ||
    String(x.name) === String(st && st.circle));
  if (!c) return null;

  const startT = typeof circleStartAt === "function"
    ? circleStartAt(c, dateISO) : c.start;
  const endT = typeof circleEndAt === "function"
    ? circleEndAt(c, dateISO) : c.end;

  const s0 = hhmmToMin(startT), e0 = hhmmToMin(endT);
  const inM = hhmmToMin(rec.inTime) , outM = hhmmToMin(rec.leftAt);
  if (s0 == null || e0 == null || outM == null || e0 <= s0) return null;

  const from = inM != null && inM > s0 ? inM : s0;    /* المتأخّر يُحسب من حضوره */
  const total = e0 - s0;
  const был = Math.max(0, Math.min(total, outM - from));

  return {
    minutes: был, total,
    pct: Math.round(был * 100 / total),
    exempt: (был * 100 / total) >= leaveCfg().pct
  };
}

/* رصد المغادرة */
window.attLeave = function (studentId) {
  const st = (cur("students") || []).find(x => String(x.id) === String(studentId));
  if (!st) return;

  const rec = (cur("attendance") || []).find(a =>
    !a.staffId && String(a.studentId) === String(studentId) &&
    String(a.date) === String(attDate()));

  if (!rec || (rec.status !== "حاضر" && rec.status !== "متأخر")) {
    showToast("يُرصد لمن حضر — حضّره أولاً", "warn"); return;
  }

  const cfg = leaveCfg();

  openModal("مغادرة قبل انتهاء الحلقة", st.name || "",
    `<input type="hidden" id="lv_sid" value="${jsAttr(studentId)}">
     <div class="form-grid">
       <div class="field"><label>وقت المغادرة</label>
         <input id="lv_time" type="time" value="${esc(nowHHMM())}"></div>
       <div class="field full"><label>السبب</label>
         <input id="lv_why" placeholder="اختياري — يظهر في سجلّه"></div>
     </div>
     ${noteCard(`من حضر <strong>${toArabicDigits(cfg.pct)}٪</strong> من الحلقة فأكثر
       يُعفى ممّا لم يُسمَّع له، ومن غادر قبل ذلك تُرحَّل واجباته تعويضاً.
       <br>الحدّ يُضبط من الإعدادات.`)}`,
    `<button class="btn btn-primary" onclick="window.attLeaveDo()">رصد المغادرة</button>
     ${rec.leftAt ? `<button class="btn btn-ghost" onclick="window.attLeaveClear('${jsAttr(studentId)}')">
       إلغاء المغادرة</button>` : ""}
     <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
};

window.attLeaveDo = function () {
  const sid = val("#lv_sid");
  const t = val("#lv_time");
  if (!t) { showToast("وقت المغادرة مطلوب", "warn"); return; }

  const st = (cur("students") || []).find(x => String(x.id) === String(sid));
  const rec = (cur("attendance") || []).find(a =>
    !a.staffId && String(a.studentId) === String(sid) &&
    String(a.date) === String(attDate()));
  if (!rec) return;

  rec.leftAt = t;
  rec.leaveReason = val("#lv_why") || "";

  const sh = attendedShare(st, rec, attDate());
  if (sh) { rec.attendedPct = sh.pct; rec.attendedMin = sh.minutes; }

  persistSet("attendance", rec);
  closeModal();

  showToast(sh
    ? "حضر " + toArabicDigits(sh.pct) + "٪ من الحلقة — " +
      (sh.exempt ? "يُعفى ممّا لم يُسمَّع" : "تُرحَّل واجباته تعويضاً")
    : "رُصدت المغادرة", "success");
  mount();
};

window.attLeaveClear = function (studentId) {
  const rec = (cur("attendance") || []).find(a =>
    !a.staffId && String(a.studentId) === String(studentId) &&
    String(a.date) === String(attDate()));
  if (!rec) return;
  delete rec.leftAt; delete rec.leaveReason;
  delete rec.attendedPct; delete rec.attendedMin;
  persistSet("attendance", rec);
  closeModal();
  showToast("أُلغيت المغادرة — حضورٌ كامل", "success");
  mount();
};

function attSet(studentId, status, circleId, kind) {
  const dateISO = attDate();
  const st = DB.students.find(function (s) { return String(s.id) === String(studentId); });
  if (!st) return;

  const u = (STATE && STATE.user) || {};
  /* الحالةُ المخصّصة تُحفظ على أساسيّتها — والأساسيّةُ وحدها تقبلها القاعدة */
  const cst = attCustomOf(kind);
  if (cst) status = cst.base;
  if (ATT_STATES.indexOf(status) < 0) return;
  /* جهةُ التحضير ومهلةُ التعديل — في الدالة لا في الزرّ */
  if (!attMayTake(recCircleOf(st, circleId || attCircle()))) return;
  /* حلقةُ التحضير: المحدَّدةُ في الشاشة، وإلا أولى حلقات الطالب. وبها
     يُبنى المفتاح، فتحضيرُ الفجر لا يمحو تحضيرَ العصر. */
  const cids = studentCircleIds(st);
  const cid = recCircleOf(st, circleId || attCircle());
  const id = attExistingId(dateISO, studentId, cid, cids.length > 1) ||
             attId(dateISO, studentId, cids.length > 1 ? cid : "");
  const prevRec = (DB.attendance || []).find(function (r) { return String(r.id) === id; });
  if (prevRec && !attEditOpen(prevRec)) return;
  const rec = {
    id: id,
    date: dateISO,
    kind: cst ? String(cst.k) : "",
    firstTs: prevRec ? (Number(prevRec.firstTs || prevRec.ts) || Date.now()) : Date.now(),
    studentId: String(st.id),
    student: st.name || "",
    circleId: cid || (st.circleId != null ? String(st.circleId) : ""),
    circle: (function () {
      const c = (cur("circles") || []).find(x => String(x.id) === String(cid));
      return (c && c.name) || st.circle || "";
    })(),
    complexId: st.complexId != null ? st.complexId : STATE.complexId,
    status: status,
    inTime: (status === "حاضر" || status === "متأخر") ? nowHHMM() : "",
    lateMin: status === "متأخر" ? lateMinutesOf(st, nowHHMM(), dateISO) : 0,
    onDuty: isDutyDay(st, dateISO),
    termId: activeTermId() || termOfDate(dateISO),
    by: u.email || "",
    ts: Date.now()
  };

  if (!Array.isArray(DB.attendance)) DB.attendance = [];
  const i = DB.attendance.findIndex(function (r) { return String(r.id) === id; });
  if (i > -1) DB.attendance[i] = rec; else DB.attendance.push(rec);

  persistSet("attendance", rec);

  /* اكتمالُ التحضير يعتمد الجلسةَ من تلقائه للمشرف — بلا زرٍّ يُضغط */
  /* أوّلُ طالبٍ يُحضَّر يُثبت حضورَ معلّمه في الحلقة */
  try { if (rec.circleId) staffAutoIn(rec.circleId, dateISO); } catch (e) {}
  try { if (typeof autoApproveCheck === "function") autoApproveCheck(rec.circleId); } catch (e) {}

  mount();
}

/* تعليم كل من لم يُسجَّل بعد حاضراً — أكثر الحالات شيوعاً */
function attMarkRest() {
  const saved = attMap(attDate(), attCircle());
  const rest = inWorkCircle(cur("students")).filter(s => !attCurrent(s.id, saved));
  if (!rest.length) { showToast("كل الطلاب لهم حالة"); return; }
  rest.forEach(s => { attDraft()[String(s.id)] = { status: "حاضر", reason: "" }; });
  mount();
  /* بالأرقام العربية كنظيرتها «الباقي غائب» (٤٥٣) */
  showToast("عُلّم " + toArabicDigits(rest.length) + " طالباً حاضراً — اضغط حفظ التحضير");
}

/* «الباقي غائب» — نظيرةُ «الباقي حاضر»: من بقي بلا حالةٍ يُعلَّم غائباً
   دفعةً واحدة، فلا يختار المعلّمُ الغيابَ طالباً طالباً.

   وتُحصر في أهل دوام اليوم وحدَهم، خلافاً لـ attMarkRest: الحضورُ لا يَظلم
   أحداً، أمّا الغيابُ فيُحتسب على الطالب — ومن ليس اليوم يومَ دوامه لا
   يُسجَّل عليه غياب. */
function attMarkRestAbsent() {
  const d0 = attDate();
  const saved = attMap(d0, attCircle());
  const rest = inWorkCircle(cur("students")).filter(s =>
    !attCurrent(s.id, saved) && isDutyDay(s, d0));
  if (!rest.length) { showToast("لا يوجد طالبٌ بلا حالةٍ في دوام اليوم"); return; }
  rest.forEach(s => { attDraft()[String(s.id)] = { status: "غائب", reason: "" }; });
  mount();
  showToast("عُلّم " + toArabicDigits(rest.length) + " طالباً غائباً — اضغط حفظ التحضير", "warn");
}
window.attMarkRestAbsent = attMarkRestAbsent;

/* =========================================================================
   شاشةُ الحلقة بالتصميم المطلوب
   -------------------------------------------------------------------------
   الشكلُ المطلوب: شريطٌ أخضرُ باسم الحلقة ومسجدها ورجوعٌ و«+»، ثمّ
   «إحصائيات الحضور» أربعَ بطاقاتٍ في صفّ، ثمّ «مؤشّر الإنجاز» بشريطه
   وتحته «حُضِّروا كذا من كذا»، ثمّ بطاقتا «النقاط المتاحة» و«واجبات
   متبقية»، ثمّ «الطلاب/ات» بصورةٍ واسمٍ وعلاماتِ واجباتٍ وحالةِ حضور،
   وشريطُ «اعتماد التحضير» و«إضافة طالب» ثابتٌ في الأسفل.

   ولم يسقط رقمٌ كان ظاهراً في الشكل القديم: عددُ الطلاب صار في عنوان
   قائمتهم، و«حُضِّروا» سطراً تحت مؤشّر الإنجاز، و«إنجاز الحلقة» هو
   المؤشّرُ نفسُه بشريطه.

   وكلُّ ما تناديه هذه الدالّةُ مَحميٌّ بـ typeof: إن غابت دالّةٌ مساعدةٌ
   في نسخةٍ ما لم تنكسر الشاشةُ ولم تُفرَّغ، بل سقط ذلك الجزءُ وحدَه.
   ========================================================================= */
function tcrcView() {
  const c = (typeof tcrcCircle === "function") ? tcrcCircle() : null;
  if (!c) {
    return `<div class="page">${pageHead("الحلقة", "")}
      <div class="card">${emptyState("لا حلقةَ مفتوحة", "اختر حلقةً من لوحتك.")}</div></div>`;
  }

  const studs = (typeof tcrcStudents === "function") ? (tcrcStudents(c) || [])
    : (cur("students") || []).filter(s => s &&
        String(s.circleId || "") === String(c.id || "") && s.status !== "متوقف");

  const d = (typeof attDate === "function") ? attDate() : todayISO();
  const map = attMap(d, String(c.id));

  const asg = (cur("assignments") || []).filter(a => a && String(a.date) === String(d) &&
    studs.some(s => String(s.id) === String(a.studentId)));
  const left = asg.filter(a => a.status !== "done").length;
  const pct = asg.length ? Math.round((asg.length - left) / asg.length * 100) : 0;
  const marked = studs.filter(s => map[String(s.id)]).length;

  const attCount = st => studs.filter(s => {
    const r = map[String(s.id)];
    return !!r && String(r.status) === st;
  }).length;

  const nPresent = attCount("حاضر"), nLate = attCount("متأخر");
  const nExcused = attCount("مستأذن"), nAbsent = attCount("غائب");

  const ptsOn = (typeof canDo === "function") ? canDo("points") : false;
  const pts = ptsOn ? (cur("pointsLog") || []).filter(p => p &&
    studs.some(s => String(s.id) === String(p.studentId)))
    .reduce((n, p) => n + (Number(p.n) || 0), 0) : 0;

  const mayAdd = (typeof teacherCan === "function") ? teacherCan("addStudent") : true;

  const attCards = [
    ["حضور",      nPresent, "tcl-g"],
    ["تأخّر",      nLate,    "tcl-a"],
    ["غياب بعذر", nExcused, "tcl-b"],
    ["غياب",      nAbsent,  "tcl-r"]
  ].map(([h, n, t]) => `<div class="tcl-stat ${t}">
      <span class="tcl-slbl">${esc(h)}</span>
      <b class="tcl-snum">${toArabicDigits(n)}</b>
    </div>`).join("");

  const twoCards = `<div class="tcl-two">
    ${ptsOn ? `<div class="tcl-card">
      <span class="tcl-ico">${ic("star", 16)}</span>
      <span class="tcl-clbl">النقاط المتاحة</span>
      <b class="tcl-cnum">${toArabicDigits(pts)}</b>
    </div>` : ""}
    <div class="tcl-card">
      <span class="tcl-ico">${ic("book", 16)}</span>
      <span class="tcl-clbl">واجبات متبقية</span>
      <b class="tcl-cnum">${toArabicDigits(left)}</b>
    </div>
  </div>`;

  /* «وعندما لا يكون يومه يكون أسفل القائمة ومكتوبٌ عليه (ليس يومه)
     باللون الأصفر»: الترتيبُ الأبجديُّ يبقى داخل كلّ مجموعة، ومن ليس
     يومُه يُؤخَّر إلى آخرها جميعاً. */
  const _noDay = {};
  studs.forEach(s => { _noDay[String(s.id)] = tcrcNotHisDay(s.id, d); });
  const studsOrd = studs.slice().sort((a2, b2) => {
    const x = _noDay[String(a2.id)] ? 1 : 0, y = _noDay[String(b2.id)] ? 1 : 0;
    return x !== y ? x - y : 0;        /* الأبجديُّ محفوظٌ داخل المجموعة */
  });

  const rows = studsOrd.map(s => {
    const off = _noDay[String(s.id)];
    return `<div class="tq-row tq-click${off ? " tq-off" : ""}"
      onclick="window.tcrcOpenStudent && window.tcrcOpenStudent('${jsAttr(s.id)}')">
      <div class="mini-avatar">${initials(s.name)}</div>
      <div class="tq-name"><strong>${esc(s.name || "—")}</strong>
        ${tcrcSubLine(s)}</div>
      ${off ? `<span class="tq-noday">ليس يومه</span>` : ""}
      <div class="tq-marks">${(typeof tcrcMarks === "function") ? tcrcMarks(s.id) : ""}</div>
      ${/* شارةُ حالة الحضور («لم يُسجَّل» / «حاضر» …) رُفعت بطلب صاحب
            المشروع. حالُ التحضير يبقى في بطاقات الإحصاء أعلى الشاشة
            («حُضِّروا كذا من كذا») وفي «اعتماد التحضير» أسفلها. */""}
      ${/* أيقونتا يسار الصفّ (السهم وزرُّ تعديل الحالة) رُفعتا بطلب صاحب
            المشروع. الصفُّ كلُّه يبقى مضغوطاً يفتح صفحةَ الطالب، وتعديلُ
            حالةِ طالبٍ بعينه يبقى من «اعتماد التحضير» أسفل الشاشة —
            ودالّتُه tcrcAttOne باقيةٌ في مكانها لم تُحذف. */""}
    </div>`;
  }).join("");

  return `<div class="page tcl-page">
    ${(typeof tcrcDayBar === "function") ? tcrcDayBar(studs, d) : ""}
    <div class="tcl-hero">
      <button type="button" class="tcl-back" data-action="nav" data-page="dashboard"
        title="رجوع">${ic("arrowLeft", 20)}</button>
      <span class="tcl-who">
        <strong>${esc(c.name || "الحلقة")}</strong>
        <small>${esc(c.mosque || ((typeof complexName === "function")
          ? complexName(c.complexId) : "") || "")}</small>
      </span>
      ${mayAdd ? `<button type="button" class="tcl-plus"
        onclick="window.tcrcAddOpen && window.tcrcAddOpen()"
        title="إضافة طالب">${ic("plus", 20)}</button>` : ""}
    </div>

    <h3 class="tcl-h">إحصائيات الحضور</h3>
    <div class="tcl-stats">${attCards}</div>

    <h3 class="tcl-h">مؤشّر الإنجاز</h3>
    <div class="tcl-prog">
      <div class="tcl-bar"><i style="width:${Math.max(0, Math.min(100, pct))}%"></i></div>
      <div class="tcl-prow">
        <span>${toArabicDigits(pct)}٪</span>
        <span class="muted">حُضِّروا ${toArabicDigits(marked)} من ${toArabicDigits(studs.length)}</span>
      </div>
    </div>

    ${twoCards}

    ${/* شارةُ الاعتماد: تظهر متى سُجّلت حالاتُ الطلاب كلِّهم في هذا اليوم */""}
    ${(studs.length && marked >= studs.length)
      ? `<div class="tcl-ok">${ic("checkCircle", 17)} تمّ اعتماد تحضير اليوم</div>` : ""}

    <h3 class="tcl-h">الطلاب/ات <span class="tcl-cnt">${toArabicDigits(studs.length)}</span></h3>
    <div class="tq-list">${rows || `<div class="ntf-empty">لا طلابَ في هذه الحلقة</div>`}</div>

    ${/* زرّان في الأسفل كما في الصورة. و«إضافة طالب» لم يُحذف — هو زرُّ «+»
          في الشريط الأخضر أعلى الشاشة. */""}
    <div class="tcl-act">
      <button type="button" class="btn btn-primary tcl-main"
        onclick="window.tcrcAttOpen && window.tcrcAttOpen()">
        ${ic("attend", 16)} اعتماد التحضير</button>
      <button type="button" class="btn btn-soft tcl-sec"
        onclick="window.tcrcAttLater && window.tcrcAttLater()">
        ${ic("clock", 16)} التحضير لاحقاً</button>
      ${/* =================================================================
           «رابطُ قوقل ميت لا يظهر للمعلّم الخاصّ بالحلقة»
           -----------------------------------------------------------------
           وُضع الزرُّ في teacherCircle، وهي ليست الشاشةَ المعروضة: مفتاحُ
           PAGES["teacher/circle"] مستبدَلٌ بـ tcrcView الأحدث. فالزرُّ
           كان يُبنى في شاشةٍ لا تُرسم. وموضعُه الصحيحُ هنا — مع زرّي
           التحضير اللذين يراهما المعلّم.
           ================================================================= */
        (typeof maqraahBtn === "function" ? maqraahBtn(c) : "")}
    </div>
  </div>`;
}
window.tcrcView = tcrcView;

/* ربطُ الشاشة بمفتاحها في PAGES — ومفتاحُها يُعرَف بمحتواه لا باسمه وحدَه،
   لأنّ اسمَ الدالّة القديمة قد يختلف بين النسخ. يُجرَّب المفتاحُ المعروف
   أوّلاً، وإلا بُحث في شاشات المعلّم عمّا فيه زرُّ «اعتماد التحضير» مع
   أثرٍ من الشكل القديم. ولا يُمسّ غيرُ شاشةٍ واحدة. */
(function () {
  try {
    if (typeof PAGES !== "object" || !PAGES) return;
    if (typeof PAGES["teacher/circle"] === "function") {
      PAGES["teacher/circle"] = tcrcView; return;
    }
    let hit = "";
    Object.keys(PAGES).forEach(k => {
      if (hit || String(k).indexOf("teacher/") !== 0) return;
      const f = PAGES[k];
      if (typeof f !== "function") return;
      const src = String(f);
      if (src.indexOf("اعتماد التحضير") > -1 &&
          (src.indexOf("حُضّروا") > -1 || src.indexOf("إنجاز الحلقة") > -1 ||
           src.indexOf("إحصائيات الحضور") > -1)) hit = k;
    });
    if (hit) PAGES[hit] = tcrcView;
  } catch (e) {}
})();

/* =========================================================
   EVENT DELEGATION
   ========================================================= */
document.addEventListener("click", (e) => {
  const t = e.target.closest("[data-action]");
  if (!t) return;
  const a = t.dataset.action;
  if ((a === "close-modal" || a === "close-panel") &&
      (t.classList.contains("modal-back") || t.classList.contains("panel-back")) &&
      e.target !== t) {
    return;
  }
  switch (a) {
    case "nav": {
      /* فرزُ المساجد يُمرَّر مع الانتقال: بطاقةُ «مساجد تابعة» كانت تفتح
         الصفحة بكلّ المساجد، فيبدو الرقمُ غيرَ مطابقٍ لما فُتح. الفرزُ
         يُحفظ في الجلسة لأن STATE يبدأ من جديد مع كلّ صفحة. */
      if (t.dataset.mq) { try { sessionStorage.setItem("__mqFilter", t.dataset.mq); } catch (e) {} }
      go(t.dataset.page);
      break;
    }
    case "fac-open": {
      var _fcoll = t.dataset.coll || "complexes";
      var _fid   = t.dataset.id;
      /* كلُّ دخولٍ يبدأ من الطلاب: التبويبُ حالةُ عرضٍ لا تُورَّث بين منشأتين */
      STATE.facTab = "students"; STATE.facStuQ = "";
      /* البطاقةُ قد تكون في لوحة التحكم، وهي لا ترسم تفاصيل المنشأة.
         كان الزرُّ يضبط الحالة ثمّ يعيد الرسم فلا يتغيّر شيء ويبدو معطّلاً.
         الآن ينتقل إلى صفحة المنشآت أو المساجد حاملاً المنشأة المطلوبة. */
      /* سياقُ المنشأة يُحفظ في الجلسة لا في STATE وحده: القائمةُ الجانبية
         تُبنى في كلّ صفحة، و STATE يبدأ من جديد مع كلّ انتقال — فلولا
         الجلسةُ لعادت قائمةُ النظام أوّلَ ما ينتقل داخل المنشأة. */
      try { sessionStorage.setItem("__facCtx", JSON.stringify({ coll: _fcoll, id: _fid })); } catch (e) {}
      if (STATE.page !== "complexes" && STATE.page !== "mosques") {
        try { sessionStorage.setItem("__facView", JSON.stringify({ coll: _fcoll, id: _fid })); } catch (e) {}
        closePanel(); go(_fcoll === "mosques" ? "mosques" : "complexes");
        break;
      }
      STATE.facilityView = { coll: _fcoll, id: _fid };
      STATE.facTab = "dashboard";
      closePanel(); mount();
      /* القائمةُ الجانبية تُبدَّل بنافذة المنشأة */
      if (typeof window.__adminBuildNav === "function") window.__adminBuildNav();
      break;
    }
    case "fac-back": {
      STATE.facilityView = null; STATE.facTab = "dashboard";
      try { sessionStorage.removeItem("__facCtx"); } catch (e) {}
      /* الرجوع من صفحةٍ أخرى داخل المنشأة يعود إلى صفحة المنشآت نفسها */
      if (STATE.page !== "complexes" && STATE.page !== "mosques") { go("complexes"); break; }
      mount();
      /* وتعود القائمةُ العامّة مكانَ قائمة المنشأة */
      if (typeof window.__adminBuildNav === "function") window.__adminBuildNav();
      break;
    }
    case "notif-read":     notifRead(t.dataset.id); break;
    case "msg-open":     msgOpen(t.dataset.id); break;
    case "msg-new":      closeModal(); window.msgCompose(); break;
    case "msg-inbox":    closeModal(); window.openMsgPanel(); break;
    case "contacts":     window.openContacts(); break;
    case "wa-open": {
      /* الرابط داخل نافذة منبثقة قد يُحجَب فتحه، فيُفتح برمجياً مع
         بديل يستبدل الصفحة إن مُنع، ورسالة تشرح السبب عند الفشل. */
      const url = t.dataset.url;
      if (!url) { showToast("لا يوجد رقم واتساب لهذه الجهة", "warn"); break; }
      let w = null;
      try { w = window.open(url, "_blank", "noopener"); } catch (e) {}
      if (!w) {
        showToast("سُمح بفتح واتساب — إن لم يفتح فالمتصفح يحجب النوافذ", "info");
        location.href = url;
      }
      break;
    }
    case "msg-to":       window.msgCompose(t.dataset.id, t.dataset.name); break;
    case "msg-send":     msgSend(); break;
    case "msg-back":     closeModal(); window.openMsgPanel(); break;
    case "msg-reply":    msgReply(); break;
    case "msg-read-all": msgReadAll(); break;
    case "notif-read-all": notifReadAll(); break;
    case "mq-filter": {
      const f = mqFilter();
      f.kind = t.dataset.kind || "all";
      f.complexId = f.kind === "one" ? (t.dataset.id || "") : "";
      const pan = document.getElementById("mqFilterPanel");
      if (pan) pan.style.display = "none";
      mount();
      break;
    }
    case "att-set":  attSet(t.dataset.student, t.dataset.status, t.dataset.circle || "", t.dataset.kind || ""); break;
    case "att-shift": attShift(t.dataset.days); break;
    case "att-rest": attMarkRest(); break;
    case "att-rest-absent": attMarkRestAbsent(); break;
    case "att-excuse": attExcuseAsk(t.dataset.student, false); break;
    case "att-excuse-save": attExcuseSave(t.dataset.ids); break;
    case "att-bulk": attBulk(t.dataset.status); break;
    case "att-save": attSaveAll(); break;
    case "modal-student-duty": modalDuty(t.dataset.id, t.dataset.focus || ""); break;
    case "fab-duty":   fabDuty(); break;
    case "fab-pick":   closeModal(); modalDuty(t.dataset.id); break;
    case "save-student-duty": saveDuty(); break;
    case "bulk-duty":       modalBulkDuty(); break;
    case "bulk-tomorrow":   STATE.dutyDay = "tomorrow"; modalBulkDuty(); break;
    case "tomorrow-duty":   STATE.dutyDay = "tomorrow"; modalDuty(t.dataset.id); break;
    case "save-bulk-duty":  saveBulkDuty(); break;
    case "link-plans":      modalLinkPlan(); break;
    case "save-link-plans": saveLinkPlans(); break;
    case "fix-plan-links": {
      /* يربط كل خطة بلا معرّف بالطالب صاحب الاسم نفسه */
      const studs = cur("students");
      let n2 = 0;
      (DB.plans || []).forEach(pl => {
        if (pl.studentId) return;
        const stx = studs.find(x => nameKey(x.name) === nameKey(pl.student));
        if (stx) { pl.studentId = String(stx.id); persistSet("plans", pl); n2++; }
      });
      mount();
      showToast(n2 ? "رُبطت " + toArabicDigits(n2) + " خطة بأصحابها" : "لا توجد خطة يمكن ربطها — الأسماء غير متطابقة", n2 ? "success" : "warn");
      break;
    }
    case "duty-approve": decideDuty(t.dataset.id, true); break;
    case "duty-reject":  decideDuty(t.dataset.id, false); break;
    case "sess-approve": approveSession(t.dataset.id); break;
    case "sess-open":    unapproveSession(t.dataset.id); break;
    case "recite-kind": {
      reciteForm().kind = t.dataset.kind;
      /* السردُ يبدأ من حيث انتهى أمس: يُملأ الموضعُ ولا يُسأل عنه.
         وفي أوّل يومٍ لا موضعَ سابق، فيُترك للمعلّم يُدخله. */
      if (t.dataset.kind === SARD_ID_KIND()) {
        const sid = val("#r_student", "");
        const st = sardStart(sid);
        if (st && st.s) {
          const fS = document.getElementById("r_fromS");
          const fA = document.getElementById("r_fromA");
          if (fS) fS.value = st.s;
          if (fA) fA.value = Math.max(1, Number(st.a) || 1);
          if (typeof window.reciteMeasure === "function") window.reciteMeasure();
        }
      }
      mount(); break;
    }
    case "recite-grade": reciteForm().grade = t.dataset.grade; mount(); break;
    case "recite-save":  reciteSave(); break;
    case "recite-again": reciteAgain(); break;
    case "recite-del":   reciteDelete(t.dataset.id); break;
    case "mus-go":    mushafGo(t.dataset.page); break;
    case "mus-clear": mushafClear(); break;
    case "modal-user": window.userForm(t.dataset.id || "", t.dataset.role || "mosqueManager"); break;
    case "user-save":  window.userSave(); break;
    case "iface": setIface(t.dataset.iface); break;
    case "tab": {
      STATE.tab[t.dataset.group] = t.dataset.tab;
      if (t.dataset.group === "plans") {
        $$(".tabs .tab").forEach(x => x.classList.toggle("active", x.dataset.tab === t.dataset.tab));
        const panel = $("#plansPanel");
        if (panel) { panel.innerHTML = plansTab(t.dataset.tab); runAnimations(panel); }
      }
      break;
    }

    /* ---- إجراءات جدول الأشخاص ---- */
    case "mvs-run-do":      window.mvsRunDo();       break;
    case "mvc-run-do":      window.mvcRunDo();       break;
    case "trm-save":        window.trmSave();        break;
    case "trm-del":         window.trmDelete(t.dataset.id); break;
    case "sct-save":        window.sctSave();        break;
    case "sct-supers-save": window.sctSupersSave();  break;
    case "sct-del-do":      window.sctDeleteDo();    break;
    case "prg-save":        window.prgSave();        break;
    case "del-ask-yes":     window.delAskYes();      break;
    case "prg-del-do":      window.prgDeleteDo();    break;
    case "xct-save":        window.xctSave();        break;
    case "xsup-save":       window.xsupSave();       break;
    case "xs-path-save":    window.xsPathSave();     break;
    case "xs-path-del-do":  window.xsPathDeleteDo();  break;
    case "sheet-send-do":   window.sheetSendDo();   break;
    case "rec-save":        window.recSave();       break;
    case "rec-transfer-do": window.recTransferDo(); break;
    case "rec-delete-do":   window.recDeleteDo();   break;
    case "pt-send-msg":  window.ptSend("msg");  break;
    case "pt-send-bell": window.ptSend("bell"); break;
    case "pt-delete":    window.ptDelete();     break;
    case "pt-set-pwd":   window.ptPwdSave();    break;
    case "pt-pwd-link":  window.ptPwdLink();    break;

    /* ---- المجمعات ---- */
    case "panel-complex": panelComplex(t.dataset.id); break;
    case "modal-complex":
      if (!mayCreateComplex()) { showToast("إنشاءُ المجمّعات لمدير النظام", "warn"); break; }
      modalComplex(); break;
    case "save-complex": {
      if (!mayCreateComplex()) { showToast("إنشاءُ المجمّعات لمدير النظام", "warn"); break; }
      const name = val("#cx_name");
      if (!name) { showToast("اسم المجمع مطلوب", "warn"); break; }
      const o = {
        id: Date.now(), name,
        region: val("#cx_region", "—"),
        manager: val("#cx_manager", "—"),
        phone: val("#cx_phone", "—"),
        status: val("#cx_status", "نشط")
      };
      DB.complexes.push(o); persistSet("complexes", o);
      if (!STATE.complexId) STATE.complexId = o.id;
      closeModal(); renderComplexSelect(); renderNav(); mount();
      showToast("تمت إضافة المجمع وحفظه في قاعدة البيانات");
      break;
    }
    case "edit-complex": {
      if (!mayEditComplex(DB.complexes.find(x => x.id == t.dataset.id))) { showToast("تعديلُ المجمّع لمدير النظام ومدير المجمّع", "warn"); break; }
      modalEditComplex(t.dataset.id); break;
    }
    case "save-edit-complex": {
      const cx = DB.complexes.find(x => x.id == t.dataset.id);
      if (!cx) { showToast("المجمع غير موجود", "warn"); break; }
      if (!mayEditComplex(cx)) { showToast("تعديلُ المجمّع لمدير النظام ومدير المجمّع", "warn"); break; }
      const name = val("#ecx_name", cx.name);
      if (!name) { showToast("اسم المجمع مطلوب", "warn"); break; }
      cx.name = name;
      cx.manager = val("#ecx_manager", cx.manager || "");
      cx.facType = val("#ecx_factype", cx.facType || "");
      cx.facClass = val("#ecx_facclass", cx.facClass || "");
      cx.circleTypes = Array.isArray(window.__editTypes) ? window.__editTypes.slice() : (cx.circleTypes || []);
      if (window.__editPhoto) cx.photo = window.__editPhoto;
      cx.region = val("#ecx_region", cx.region || "");
      cx.phone = val("#ecx_phone", cx.phone || "");
      cx.status = val("#ecx_status", cx.status);
      persistSet("complexes", cx);
      closeModal(); renderComplexSelect(); mount();
      showToast("تم حفظ تعديلات المجمع");
      break;
    }
    case "toggle-complex": {
      const cx = DB.complexes.find(x => x.id == t.dataset.id);
      if (!cx) { showToast("المجمع غير موجود", "warn"); break; }
      if (!mayEditComplex(cx)) { showToast("تعديلُ المجمّع لمدير النظام ومدير المجمّع", "warn"); break; }
      cx.status = cx.status === "نشط" ? "متوقف" : "نشط";
      persistSet("complexes", cx);
      mount();
      showToast(cx.status === "نشط" ? "تم تشغيل المجمع" : "تم إيقاف المجمع");
      break;
    }
    case "switch-complex": {
      STATE.complexId = t.dataset.id;
      STATE.planId = null;
      renderComplexSelect(); renderNav(); mount();
      closePanel();
      showToast("المجمع النشط الآن: " + complexName(STATE.complexId), "info");
      break;
    }
    case "delete-complex": {
      const cx = DB.complexes.find(x => x.id == t.dataset.id);
      if (!cx) { showToast("المجمع غير موجود", "warn"); break; }
      if (!mayCreateComplex()) { showToast("حذفُ المجمّعات لمدير النظام", "warn"); break; }
      openModal("حذف المجمع", "تأكيد الحذف",
        `${noteCard("سيتم حذف مجمع <strong>" + esc(cx.name) + "</strong> نهائياً من قاعدة البيانات. <strong>لن تُحذف</strong> بياناته (المساجد والطلاب) تلقائياً، لكنها ستصبح بلا مجمع. لا يمكن التراجع.")}`,
        `<button class="btn btn-danger" data-action="delete-complex-confirm" data-id="${cx.id}">${ic("x", 16)} نعم، احذف المجمع</button>
         <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
      break;
    }
    case "delete-complex-confirm": {
      if (!mayCreateComplex()) { showToast("حذفُ المجمّعات لمدير النظام", "warn"); break; }
      const id = t.dataset.id;
      DB.complexes = DB.complexes.filter(x => x.id != id);
      persistDelete("complexes", id);
      if (STATE.complexId == id) STATE.complexId = DB.complexes[0] ? DB.complexes[0].id : null;
      closeModal(); renderComplexSelect(); renderNav(); mount();
      showToast("تم حذف المجمع");
      break;
    }

    /* ---- المساجد ---- */
    case "delete-mosque": {
      const mq = DB.mosques.find(x => x.id == t.dataset.id);
      if (!mq) { showToast("المسجد غير موجود", "warn"); break; }
      const nC = DB.circles.filter(c => String(c.mosqueId || "") === String(mq.id)).length;
      const nS = DB.students.filter(x => String(x.mosqueId || "") === String(mq.id)).length;
      openModal("حذف المسجد", "تأكيد الحذف",
        `${noteCard("سيتم حذف مسجد <strong>" + esc(mq.name) + "</strong> نهائياً من قاعدة البيانات." +
          (nC || nS ? " ويتبعه <strong>" + nC + "</strong> حلقة و<strong>" + nS + "</strong> طالباً — <strong>لن تُحذف</strong> معه لكنها ستصبح بلا مسجد." : "") +
          " لا يمكن التراجع.")}`,
        `<button class="btn btn-danger" data-action="delete-mosque-confirm" data-id="${mq.id}">${ic("x", 16)} نعم، احذف المسجد</button>
         <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
      break;
    }
    case "delete-mosque-confirm": {
      const id = t.dataset.id;
      DB.mosques = DB.mosques.filter(x => x.id != id);
      persistDelete("mosques", id);
      closeModal(); renderNav(); mount();
      showToast("تم حذف المسجد");
      break;
    }
    case "panel-mosque": panelMosque(t.dataset.id); break;
    case "toggle-mosque": {
      const m = DB.mosques.find(x => x.id == t.dataset.id);
      if (!m) { showToast("المسجد غير موجود", "warn"); break; }
      m.status = m.status === "نشط" ? "متوقف مؤقت" : "نشط";
      persistSet("mosques", m);
      /* الفهرسُ العلنيّ يتبع الحالة فوراً (٤٣٢) — كان لا يُحدَّث إلا مع حفظ النموذج */
      if (typeof window.pubMosqueIndexSync === "function") window.pubMosqueIndexSync();
      mount();
      showToast(m.status === "نشط" ? "تم تشغيل المسجد" : "تم إيقاف المسجد مؤقتاً");
      break;
    }
    case "edit-mosque": modalEditMosque(t.dataset.id); break;
    case "save-edit-mosque": {
      const m = DB.mosques.find(x => x.id == t.dataset.id);
      if (!m) { showToast("المسجد غير موجود", "warn"); break; }
      const name = val("#ecx_name", m.name);
      if (!name) { showToast("اسم المسجد مطلوب", "warn"); break; }
      const emOldName = m.name;
      m.name = name;
      m.manager = val("#ecx_manager", m.manager || "");
      m.facType = val("#ecx_factype", m.facType || "");
      m.facClass = val("#ecx_facclass", m.facClass || "");
      m.circleTypes = Array.isArray(window.__editTypes) ? window.__editTypes.slice() : (m.circleTypes || []);
      if (window.__editPhoto) m.photo = window.__editPhoto;
      m.region = val("#ecx_region", m.region || "");
      m.phone = val("#ecx_phone", m.phone || "");
      m.status = val("#ecx_status", m.status);
      persistSet("mosques", m);
      /* =================================================================
         الاسمُ المكرَّرُ يتبع الأصل (٤٣٠)
         -----------------------------------------------------------------
         الحلقاتُ والطلابُ والمعلّمون يحملون اسمَ مسجدهم نصّاً بجوار
         معرّفه، وكان تغييرُ الاسم يُبقيه قديماً فيها — وبعضُ اللوحات تطابق
         بالاسم. فيُحدَّث النصُّ وحدَه لمن ارتبط بهذا المسجد بمعرّفه وكان
         يحمل اسمَه القديم بعينه؛ والمعرّفُ mosqueId لا يُمسّ — كما في
         تغيير اسم الحلقة.
         ================================================================= */
      if (String(emOldName || "") !== String(m.name || "")) {
        ["circles", "students", "teachers"].forEach(cl => {
          (DB[cl] || []).forEach(r => {
            if (!r || String(r.mosqueId || "") !== String(m.id)) return;
            if (String(r.mosque || "") !== String(emOldName || "")) return;
            r.mosque = m.name;
            persistSet(cl, r);
          });
        });
      }
      /* وفهرسُ صفحة التسجيل يتبع الاسمَ والحالة */
      try { if (window.pubMosqueIndexSync) window.pubMosqueIndexSync(); } catch (e) {}
      closeModal(); mount();
      showToast("تم حفظ تعديلات المسجد");
      break;
    }

    case "panel-circle": panelCircle(t.dataset.id); break;
    case "panel-student": panelStudent(t.dataset.id); break;
    case "panel-program": panelProgram(t.dataset.id); break;
    case "panel-teacher": panelTeacher(t.dataset.id); break;

    case "modal-mosque": modalMosque(); break;
    case "modal-circle": modalCircle(); break;
    case "modal-student": modalStudent(); break;
    case "modal-teacher": modalTeacher(); break;
    case "modal-program": modalProgram(); break;
    case "modal-level": modalLevel(); break;
    case "modal-duty": modalDutyType(); break;
    case "modal-daily-duties": modalDailyDuties(t.dataset.id); break;
    case "modal-report": modalReport(t.dataset.name); break;
    case "export-report": exportReportCSV(t.dataset.name); break;
    case "modal-edit-path": modalEditPath(t.dataset.id); break;
    case "modal-freeze": modalFreeze(t.dataset.id); break;
    case "modal-add-comp": modalAddComp(t.dataset.id); break;
    case "modal-promote": modalPromote(t.dataset.id); break;
    case "plan-open": { const _op = planOfDs(t.dataset.id); STATE.planId = _op ? _op.id : t.dataset.id; mount(); break; }
    case "plan-back": STATE.planId = null; mount(); break;
    case "close-modal":
      /* النقرُ على الخلفية وحدها لا يُسقط تعديلاتٍ لم تُحفظ (٤٢٩) */
      if (t.classList.contains("modal-back") && e.target === t && modalDirty()) { modalDirtyWarn(); break; }
      closeModal(); break;
    case "close-panel": closePanel(); break;
    case "toast": showToast(t.dataset.msg || "تم التنفيذ", t.dataset.type || "success"); break;

    /* ---- الحلقات ---- */
    case "edit-circle": modalEditCircle(t.dataset.id); break;
    case "save-edit-circle": {
      const c = DB.circles.find(x => x.id == t.dataset.id);
      if (!c) { showToast("الحلقة غير موجودة", "warn"); break; }
      const name = val("#ec_name", c.name);
      if (!name) { showToast("اسم الحلقة مطلوب", "warn"); break; }
      /* الوقتُ الثابت ساعةٌ صحيحة: 00:00 إلى 23:59 */
      if (val("#ec_mode", c.anchor ? "anchor" : "fixed") !== "anchor") {
        const _s = val("#ec_start", ""), _e = val("#ec_end", "");
        if ((_s && !clockValid(_s)) || (_e && !clockValid(_e))) {
          showToast("الوقت غير صحيح — الساعة من 00 إلى 23 والدقائق من 00 إلى 59", "warn"); break;
        }
      }
      const ecOldName = c.name;
      c.name = name;
      c.photo = photoVal("ec_photo", c.photo || "");   /* شعارُ الحلقة */
      photoReset("ec_photo");
      c.type = val("#ec_type", c.type);
      c.days = daysValue("ec_days");
      c.start = val("#ec_start", c.start);
      c.end = val("#ec_end", c.end);
      const ecMode = val("#ec_mode", c.anchor ? "anchor" : "fixed");
      c.anchor = ecMode === "anchor" ? val("#ec_anchor", "Asr") : "";
      c.offset = ecMode === "anchor" ? (Number(val("#ec_offset")) || 0) : 0;
      c.endAnchor = ecMode === "anchor" ? val("#ec_endAnchor", "") : "";
      c.status = val("#ec_status", c.status);
      c.capacity = Number(val("#ec_cap")) || 0;
      c.termId = val("#ec_term", c.termId || "");
      /* =================================================================
         «إذا أضفتُ رابطاً لجوجل ميت وأردتُ أن أُزيله بعد ذلك يُزال معي»
         -----------------------------------------------------------------
         val تردُّ القيمةَ القديمة حين يكون الحقلُ فارغاً، وهو حارسٌ في
         محلِّه: حقلٌ غائبٌ عن النموذج لا يُمحى بفراغ. لكنّ هذا الحقل
         مرسومٌ أمام صاحبه، وإفراغُه قصدٌ لا سهو — فكان الرابطُ لا يُمحى
         أبداً، ومقرأةُ الحلقة تُفتَّح بوجوده وحدَه فلا سبيلَ إلى إطفائها.

         فيُقرأ من الحقل نفسِه متى كان مرسوماً، فإن غاب بقي ما في السجلّ
         كما هو. ولا يُمسّ حقلٌ آخر.
         ================================================================= */
      { const elMaq = document.getElementById("ec_maq");
        if (elMaq) c.maqraahUrl = String(elMaq.value || "").trim();
        else c.maqraahUrl = c.maqraahUrl || ""; }
      { const aw = val("#ec_attwho", ""); if (ATT_WHO.some(x => x.k === aw)) c.attWho = aw; else delete c.attWho; }

      const ecFac = facTwoValue("ec_cx", "ec_mosque");
      if (ecFac.complexId) { c.complexId = ecFac.complexId; c.mosque = ecFac.mosque; c.mosqueId = ecFac.mosqueId; }

      /* تغيير معلّم الحلقة يسري على طلابها: الطالب يرث معلّمه منها،
         وتركه بلا مزامنة يُبقيهم منسوبين لمعلّم غادر. */
      /* يُغيَّر المعلّمُ إن غيّره المستخدمُ في القائمة وحدَه، ولمعلّمٍ بعينه (٤٣١) */
      const ecTEl = document.getElementById("ec_teacher");
      const ecTId = ecTEl ? String(ecTEl.value || "") : "";
      const ecTRec = ecTId ? (DB.teachers || []).find(t2 => String(t2.id) === ecTId) : null;
      const ecT = ecTRec ? ecTRec.name : "";
      let synced = 0;
      const oldTeacherId = c.teacherId || "";
      if (ecTEl && ecTRec && ecTId !== String(ecTEl.dataset.orig || "")) {
        c.teacher = ecT;
        c.teacherId = String(ecTRec.id);
        /* المعلّم الجديد لا يبقى مساعداً لنفسه */
        if (Array.isArray(c.assistants) && c.teacherId) {
          c.assistants = c.assistants.filter(x => String(x) !== String(c.teacherId));
        }

        /* نطاق المعلّمَين يتغيّر: القديم يفقد الحلقة والجديد يكسبها.
           بدونه يبقى القديم قادراً على الكتابة فيها والجديد ممنوعاً. */
        try {
          if (typeof syncTeacherScope === "function") {
            if (oldTeacherId) syncTeacherScope(oldTeacherId);
            if (c.teacherId) syncTeacherScope(c.teacherId);
          }
        } catch (e) {}

        /* تنبيهُ المعلّمَين: «تم نقلك إلى حلقة أخرى» في وثيقة المتطلبات */
        try {
          if (oldTeacherId) notifyUser(oldTeacherId, "circleMoved",
            "لم تعد حلقةُ «" + (c.name || "") + "» مسنَدةً إليك.");
          if (c.teacherId) notifyUser(c.teacherId, "circleMoved",
            "أُسنِدت إليك حلقةُ «" + (c.name || "") + "».");
        } catch (e) {}
        (DB.students || []).forEach(st => {
          /* طالبُ الحلقة بمعرّفها؛ والاسمُ لمن لا معرّفَ له وحدَه — فلا يُمسّ
             طالبٌ في حلقةٍ أخرى تحمل الاسمَ نفسَه في مسجدٍ آخر (٤٣١) */
          const inIt = st.circleId ? String(st.circleId) === String(c.id)
                                   : String(st.circle) === String(c.name);
          if (!inIt) return;
          st.teacher = c.teacher; st.teacherId = c.teacherId;
          persistSet("students", st); synced++;
        });
      }

      /* =================================================================
         اسمُ الحلقة الجديدُ يظهر عند الجميع
         -----------------------------------------------------------------
         سجلُّ الطالب والمعلّم يحمل اسمَ حلقته نصّاً (circle) تقرؤه جداولُ
         الإدارة وتقاريرُها، فكان تغييرُ اسم الحلقة يظهر للمعلّم ويبقى
         الاسمُ القديمُ في جدول الطلاب. يُحدَّث النصُّ وحدَه لمن هم فيها
         بمعرّفها — والمعرّفُ circleId لا يُمسّ، فلا نقلَ ولا تبديلَ حلقة.
         ================================================================= */
      if (String(ecOldName || "") !== String(c.name || "")) {
        ["students", "teachers"].forEach(cl => {
          (DB[cl] || []).forEach(r => {
            if (!r || String(r.circleId || "") !== String(c.id)) return;
            if (String(r.circle || "") !== String(ecOldName || "")) return;
            r.circle = c.name;
            persistSet(cl, r);
          });
        });
      }

      persistSet("circles", c);
      /* «تم تعديل أو تحديث بيانات الحلقة» — تنبيهٌ لمعلّمها الحاليّ */
      try {
        if (c.teacherId) notifyUser(c.teacherId, "circleEdited",
          "حُدِّثت بياناتُ حلقة «" + (c.name || "") + "».");
      } catch (e) {}
      if (synced) showToast("نُقل " + toArabicDigits(synced) + " طالباً إلى المعلّم الجديد", "info");
      closeModal(); mount();
      showToast("تم حفظ تعديلات الحلقة");
      break;
    }
    case "delete-circle": {
      const c = DB.circles.find(x => x.id == t.dataset.id);
      if (!c) { showToast("الحلقة غير موجودة", "warn"); break; }
      if (circleDelBlocked(c.id)) break;
      openModal("حذف الحلقة", "تأكيد الحذف",
        `${noteCard("سيتم حذف حلقة <strong>" + esc(c.name) + "</strong> نهائياً من قاعدة البيانات. لا يمكن التراجع.")}`,
        `<button class="btn btn-danger" data-action="delete-circle-confirm" data-id="${c.id}">${ic("x", 16)} نعم، احذف الحلقة</button>
         <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
      break;
    }
    case "delete-circle-confirm": {
      const id = t.dataset.id;
      if (circleDelBlocked(id)) { closeModal(); break; }
      DB.circles = DB.circles.filter(x => x.id != id);
      persistDelete("circles", id);
      closeModal(); renderNav(); mount();
      showToast("تم حذف الحلقة");
      break;
    }

    /* ---- الطلاب ---- */
    /* «تعديل» يفتح بطاقةَ الطالب: هي الشاشةُ الكاملة بتبويبَيها، والنموذجُ
       القديم كان يعرض نصفَ الحقول في قائمةٍ طويلة. وما كان فيه وحدَه —
       الصورةُ والمنشأةُ والحلقةُ والحلقاتُ الإضافية ووضعُ التسجيل
       والملاحظاتُ الصحية ووضعُ كبار السن — أُضيف إلى البطاقة فلا يضيع. */
    case "edit-student": panelStudent(t.dataset.id); break;
    case "save-edit-student": {
      const s = DB.students.find(x => x.id == t.dataset.id);
      if (!s) { showToast("الطالب غير موجود", "warn"); break; }
      const name = val("#es_name", s.name);
      if (!name) { showToast("اسم الطالب مطلوب", "warn"); break; }
      s.name = name;
      s.photo = photoVal("es_photo", s.photo || "");
      /* العمر محسوب من الميلاد: القيمة المكتوبة كانت تشيخ مع الطالب ولا تتغيّر */
      s.birth = val("#es_birth", s.birth || "");
      const esAge = ageFromBirth(s.birth);
      if (esAge != null) s.age = String(esAge);
      /* الرقمُ بمفتاحه، والمفتاحُ يُحفظ ليُقرأ الحقلُ صحيحاً في كلّ نموذج */
      const _ep = typeof phoneRead === "function" ? phoneRead("es_parent") : null;
      if (_ep) { s.parent = _ep.full; s.parentCC = _ep.cc; }
      else s.parent = val("#es_parent", s.parent || "");
      const esFac = facTwoValue("es_cx", "es_mosque");
      s.mosque    = esFac.mosque;
      s.mosqueId  = esFac.mosqueId;
      s.complexId = esFac.complexId;
      /* والسعةُ تُحترم هنا كما في نموذج الإضافة: من ينتقل إلى حلقةٍ
         ممتلئةٍ يُردّ، ومن هو فيها أصلاً يُحفظ كما كان */
      {
        const _newCir = val("#es_circle", s.circle);
        const _esRec0 = stuCircleRec(s, _newCir);
        const _newId  = _esRec0 ? String(_esRec0.id) : "";
        if (_newId && String(_newId) !== String(s.circleId || "") &&
            typeof circleCapBlock === "function" && circleCapBlock(_newId, s.id)) break;
      }
      const esCircleRec = stuCircleRec(s, val("#es_circle", s.circle));
      s.circle = val("#es_circle", s.circle);
      /* مزامنة معرّف الحلقة مع الاسم الجديد — بدونها يتناقض الاثنان */
      s.circleId = esCircleRec ? String(esCircleRec.id) : (s.circleId || "");
      if (esCircleRec) {
        if (esCircleRec.teacher)   s.teacher   = esCircleRec.teacher;
        if (esCircleRec.teacherId) s.teacherId = String(esCircleRec.teacherId);
        else s.teacherId = idByName("teachers", s.teacher) || s.teacherId || "";
      }
      s.attType = val("#es_attType", s.attType);
      /* «تحضير فقط»: يُحضَّر ويُتابَع حضورُه ولا خطةَ له ولا واجب — وضعٌ
         مقصودٌ لا نقصٌ في البيانات، فلا يُعدّ في «طلاب بلا خطة». */
      s.attOnly = val("#es_mode", "") === "att";
      try {
        const selEl = document.querySelector("#es_circles");
        if (selEl) s.circleIds = [].slice.call(selEl.selectedOptions).map(o => String(o.value));
      } catch (e) {}
      s.days = val("#es_days", "") || circleDaysOf(s.circle) || s.days;
      const esPrg0 = String(s.program || ""), esLv0 = String(s.levelId || "");
      { const _pv = val("#es_program", s.program);
        /* «—» لمن لا برنامجَ له يُبقي الحقلَ كما كان، فلا يُعدّ تغييراً (٤٣١) */
        s.program = (_pv === "—" && (!esPrg0 || esPrg0 === "—")) ? esPrg0 : _pv; }
      /* المستوى بمعرّفه: تغيير اسمه لاحقاً يصل الطالب */
      const esLv = val("#es_level", "");
      if (esLv) { s.levelId = esLv; s.level = lvNameById(esLv) || s.level; }
      const esChg = String(s.program || "") !== esPrg0 || String(s.levelId || "") !== esLv0;
      s.status = val("#es_status", s.status);

      /* البيانات الشخصية */
      { const eIdErr = stuIdNoError(val("#es_idno", s.idNo || ""), s.id);
        if (eIdErr && String(val("#es_idno", "") || "") !== String(s.idNo || "")) { showToast(eIdErr, "warn"); break; } }
      s.idNo = toLatinDigitsSafe(val("#es_idno", s.idNo || "")).trim();
      s.nationality = val("#es_nat", s.nationality || "");
      s.school = val("#es_school", s.school || "");
      s.grade = val("#es_grade", s.grade || "");
      s.phone = val("#es_phone", s.phone || "");
      s.parentRel = val("#es_rel", s.parentRel || "");
      s.address = val("#es_addr", s.address || "");
      s.health = val("#es_health", s.health || "");

      persistSet("students", s);
      /* برنامجٌ أو مستوىً أُسند هنا: منهجُه الذي يمشي عليه */
      if (esChg && typeof stuAdoptLevel === "function") stuAdoptLevel(s);
      closeModal(); mount();
      showToast("تم حفظ تعديلات الطالب");
      break;
    }
    /* زرُّ الحالة يتبدّل بحالة الطالب: إيقافٌ للفعّال وتفعيلٌ للموقوف */
    case "toggle-student": {
      const st = DB.students.find(x => String(x.id) === String(t.dataset.id));
      if (!st) break;
      const wasOn = st.active !== false && st.status !== "متوقف";
      st.active = !wasOn;
      st.status = wasOn ? "متوقف" : "نشط";
      persistSet("students", st);
      showToast(wasOn ? "أُوقف " + (st.name || "الطالب") : "فُعّل " + (st.name || "الطالب"), "success");
      mount();
      break;
    }

    case "delete-student": {
      const s = DB.students.find(x => x.id == t.dataset.id);
      if (!s) { showToast("الطالب غير موجود", "warn"); break; }
      /* ما يبقى بعد الحذف يُقال قبله (٤٣٠): سجلُّ الطالب وحدَه يُحذف، وخططُه
         وحضورُه وتسميعُه تبقى سجلّاً تاريخياً، وحسابُ دخوله يبقى — فكانت
         تبقى يتيمةً ولا يعلم بها الحاذف. والحذفُ الجماعيُّ لها لا يُفعل
         تلقائياً. والإيقافُ بديلٌ يحفظ كلَّ شيء. */
      const sLinks = delLinkedCounts("studentId", s.id);
      const sAcc = (DB.users || []).filter(u => u && (String(u.studentId || "") === String(s.id) ||
                     (s.uid && String(u.uid || u.id) === String(s.uid)))).length;
      openModal("حذف الطالب", "تأكيد الحذف",
        `${noteCard("سيتم حذف الطالب <strong>" + esc(s.name) + "</strong> نهائياً من قاعدة البيانات. لا يمكن التراجع.")}
         ${delLinkedNote(sLinks, sAcc)}`,
        `<button class="btn btn-danger" data-action="delete-student-confirm" data-id="${s.id}">${ic("trash", 16)} نعم، احذف الطالب</button>
         <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
      break;
    }
    case "delete-student-confirm": {
      const id = t.dataset.id;
      DB.students = DB.students.filter(x => x.id != id);
      persistDelete("students", id);
      closeModal(); renderNav(); mount();
      showToast("تم حذف الطالب");
      break;
    }

    /* ---- المعلمون ---- */
    case "edit-teacher": modalEditTeacher(t.dataset.id); break;
    case "save-edit-teacher": {
      const tc = DB.teachers.find(x => x.id == t.dataset.id);
      if (!tc) { showToast("المعلم غير موجود", "warn"); break; }
      const name = val("#et_name", tc.name);
      if (!name) { showToast("اسم المعلم مطلوب", "warn"); break; }
      const gmailUser = val("#et_user", "");
      /* بلا جيميل: يبقى البريدُ المحفوظ (غيرُ الجيميل أو بريدُ رقم الهوية)،
         ولا يُمنع تعديلُ بقيّة البيانات بسببه (٤٣١). */
      const keepMail = String(tc.username || "");
      if (!gmailUser && (!keepMail || keepMail === "—")) { showToast("البريد الإلكتروني مطلوب", "warn"); break; }
      tc.name = name;
      tc.photo = photoVal("et_photo", tc.photo || "");
      tc.phone = val("#et_phone", tc.phone || "");
      const etFac  = facTwoValue("et_cx", "et_mosque");
      tc.mosque    = etFac.mosque;
      tc.mosqueId  = etFac.mosqueId;
      tc.complexId = etFac.complexId || tc.complexId || "";
      /* الحلقةُ بمعرّفها من القائمة، و«—» يرفع الإسناد صراحةً (٤٣١) */
      /* ولا يُكتب إلّا إن غُيّر فعلاً: الحقلُ الذي لم يُلمس لا يُعيد كتابةَ ما في السجلّ */
      { const elC = document.getElementById("et_circle");
        if (elC && String(elC.value || "") !== String(elC.dataset.orig || "")) {
          const cid = String(elC.value || "");
          const cc = cid ? (DB.circles || []).find(x => String(x.id) === cid) : null;
          tc.circleId = cc ? String(cc.id) : "";
          tc.circle = cc ? (cc.name || "—") : "—";
        } }
      if (gmailUser) tc.username = gmailUser + "@gmail.com";
      tc.status = val("#et_status", tc.status);
      tc.active = tc.status === "نشط";

      tc.staffRole = val("#et_staffrole", tc.staffRole || "teacher");
      tc.qual = val("#et_qual", tc.qual || "");
      tc.spec = val("#et_spec", tc.spec || "");
      tc.startDate = val("#et_start", tc.startDate || "");
      tc.idNo = val("#et_idno", tc.idNo || "");

      /* الأجر في حقله وحده: تغيير النوع يمحو ما سواه فلا يجتمع راتبان */
      Object.assign(tc, payFields(val("#et_payType", tc.payType || "monthly"),
                                  val("#et_pay")));

      persistSet("teachers", tc);

      /* نطاق المعلّم قد يتغيّر بتغيّر حلقته أو مسجده */
      try { if (typeof syncTeacherScope === "function") syncTeacherScope(tc.id); } catch (e) {}

      closeModal(); mount();
      showToast("تم حفظ تعديلات المعلم");
      break;
    }
    case "delete-teacher": {
      const tc = DB.teachers.find(x => x.id == t.dataset.id);
      if (!tc) { showToast("المعلم غير موجود", "warn"); break; }
      /* معلّمٌ له حلقاتٌ لا يُحذف حتى تُسند لغيره (٤٣٠): كان يُحذف فتبقى
         حلقاتُه تشير إلى معلّمٍ لا وجود له، ويرث طلابُها معلّماً محذوفاً.
         ولا تُفرَّغ الحلقاتُ تلقائياً — فذاك تغييرُ ارتباطٍ بلا قصد. */
      const tCircles = (DB.circles || []).filter(c => c && c.teacherId != null && c.teacherId !== "" &&
                         String(c.teacherId) === String(tc.id));
      if (tCircles.length) {
        openModal("حذف المعلم", "لا يمكن الحذف الآن",
          noteCard("المعلم <strong>" + esc(tc.name) + "</strong> مسؤولٌ عن " +
            toArabicDigits(tCircles.length) + " حلقة: <strong>" +
            tCircles.map(c => esc(c.name || "—")).join("، ") +
            "</strong>. أسنِد هذه الحلقات إلى معلّمٍ آخر من صفحة الحلقات أولاً، ثمّ احذفه — أو أوقِفه بدل حذفه."),
          `<button class="btn btn-ghost" data-action="close-modal">حسناً</button>`);
        break;
      }
      const tLinks = delLinkedCounts("teacherId", tc.id);
      const tAcc = (DB.users || []).filter(u => u && (String(u.teacherId || "") === String(tc.id) ||
                     (tc.uid && String(u.uid || u.id) === String(tc.uid)))).length;
      openModal("حذف المعلم", "تأكيد الحذف",
        `${noteCard("سيتم حذف المعلم <strong>" + esc(tc.name) + "</strong> نهائياً من قاعدة البيانات. لا يمكن التراجع.")}
         ${delLinkedNote(tLinks, tAcc)}`,
        `<button class="btn btn-danger" data-action="delete-teacher-confirm" data-id="${tc.id}">${ic("x", 16)} نعم، احذف المعلم</button>
         <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
      break;
    }
    case "delete-teacher-confirm": {
      const id = t.dataset.id;
      DB.teachers = DB.teachers.filter(x => x.id != id);
      persistDelete("teachers", id);
      closeModal(); renderNav(); mount();
      showToast("تم حذف المعلم");
      break;
    }

    /* ---- البرامج ---- */
    case "edit-program": modalEditProgram(t.dataset.id); break;
    case "toggle-program": {
      const p = DB.programs.find(x => x.id == t.dataset.id);
      if (!p) { showToast("البرنامج غير موجود", "warn"); break; }
      p.status = p.status === "نشط" ? "متوقف" : "نشط";
      persistSet("programs", p);
      closePanel(); mount();
      showToast(p.status === "نشط" ? "تم تشغيل البرنامج" : "تم إيقاف البرنامج");
      break;
    }
    case "delete-program": {
      const p = DB.programs.find(x => x.id == t.dataset.id);
      if (!p) { showToast("البرنامج غير موجود", "warn"); break; }
      openModal("حذف البرنامج", "تأكيد الحذف",
        `${noteCard("سيتم حذف برنامج <strong>" + esc(p.name) + "</strong> نهائياً من قاعدة البيانات. لا يمكن التراجع.")}`,
        `<button class="btn btn-danger" data-action="delete-program-confirm" data-id="${p.id}">${ic("x", 16)} نعم، احذف البرنامج</button>
         <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
      break;
    }
    case "delete-program-confirm": {
      const id = t.dataset.id;
      DB.programs = DB.programs.filter(x => x.id != id);
      persistDelete("programs", id);
      closeModal(); renderNav(); mount();
      showToast("تم حذف البرنامج");
      break;
    }

    /* ---- Data management ---- */
    case "reload-data": {
      showToast("جارٍ إعادة التحميل من قاعدة البيانات…", "info");
      reloadAndRender().then(() => showToast("تم تحديث البيانات")).catch(err => { console.warn(err); showToast("تعذّر التحميل", "warn"); });
      break;
    }
    /* =====================================================================
       «حذف كل البيانات» بتأكيدٍ مزدوج ولمدير النظام وحدَه (٤٣٢)
       ---------------------------------------------------------------------
       كان نقرٌ واحدٌ على «نعم» يمحو المجموعاتِ كلَّها، ولا يُفحص الدورُ في
       clearAllData نفسِها. الآن: الأوّلُ كتابةُ العبارة حرفاً بحرف، والثاني
       تأكيدٌ أخيرٌ يذكر عددَ ما سيُحذف — ثمّ الحذف.
       ===================================================================== */
    case "clear-data": {
      if (!isTopAdmin()) { showToast("حذفُ كل البيانات لمدير النظام وحدَه", "warn"); break; }
      openModal("حذف كل البيانات", "الخطوة ١ من ٢ — سيُحذف كل المحتوى من قاعدة البيانات",
        `${noteCard("سيتم حذف <strong>جميع المجمعات</strong> والمساجد والحلقات والطلاب والمعلمين والبرامج والخطط نهائياً. لا يمكن التراجع.")}
         <div class="field full" style="margin-top:12px"><label for="clr_phrase">اكتب: <strong>${CLEAR_PHRASE}</strong></label>
           <input id="clr_phrase" autocomplete="off" placeholder="${CLEAR_PHRASE}"></div>`,
        `<button class="btn btn-danger" data-action="clear-confirm">${ic("x", 16)} متابعة</button>
         <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
      break;
    }
    case "clear-confirm": {
      if (!isTopAdmin()) { closeModal(); showToast("حذفُ كل البيانات لمدير النظام وحدَه", "warn"); break; }
      if (String(val("#clr_phrase", "") || "").trim() !== CLEAR_PHRASE) {
        showToast("اكتب العبارة كما هي للمتابعة", "warn"); break;
      }
      const nAll = COLLECTIONS.filter(c => CLEAR_KEEP.indexOf(c) === -1)
        .reduce((n, c) => n + (Array.isArray(DB[c]) ? DB[c].length : 0), 0);
      closeModal();
      openModal("تأكيد أخير", "الخطوة ٢ من ٢",
        noteCard("سيُحذف <strong>" + toArabicDigits(nAll) + "</strong> سجلاً من " +
                 toArabicDigits(COLLECTIONS.length - CLEAR_KEEP.length) +
                 " مجموعة نهائياً، وتبقى حساباتُ المستخدمين. هل أنت متأكد؟"),
        `<button class="btn btn-danger" data-action="clear-final">${ic("x", 16)} نعم، احذف نهائياً</button>
         <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
      break;
    }
    case "clear-final": {
      if (!isTopAdmin()) { closeModal(); showToast("حذفُ كل البيانات لمدير النظام وحدَه", "warn"); break; }
      closeModal();
      showToast("جارٍ حذف البيانات…", "info");
      clearAllData().then(() => {
        STATE.planId = null; STATE.complexId = null;
        renderComplexSelect(); renderNav(); updateConnBadge(); mount();
        showToast("تم حذف كل البيانات");
      }).catch(err => { console.warn(err); showToast("تعذّر حذف البيانات", "warn"); });
      break;
    }

    /* ---- Save handlers ---- */
    case "save-mosque": {
      const name = val("#m_name");
      if (!name) { showToast("اسم المسجد مطلوب", "warn"); break; }

      /* كان المسجد يُجبَر على تبعية المجمع النشط، فيتعذّر إنشاء مسجد مستقل
         رغم أن الوثيقة تنص على وجوده. التبعية الآن اختيار صريح. */
      /* داخل مجمّع: الحقلُ غيرُ معروض، فالتبعيةُ من السياق لا من النموذج */
      const _ctxCx = facCtxComplexId();
      let mCx = "";
      if (_ctxCx) {
        mCx = _ctxCx;
      } else {
        const parent = val("#m_parent", "");
        if (parent && parent !== MOSQUE_INDEP) {
          const c = recByName("complexes", parent);
          mCx = c ? c.id : "";
        }
      }

      const o = { id: Date.now(), complexId: mCx, name, region: val("#m_region", "—"),
        manager: val("#m_manager", "—"), phone: val("#m_phone", "—"),
        /* لا تُخزَّن أعداد: كانت أصفاراً جامدة تُفضَّل على الحساب فتحجبه */
        status: val("#m_status", "نشط"), attendance: 0, plan: 0 };
      DB.mosques.push(o); persistSet("mosques", o);
      try { if (window.pubMosqueIndexSync) window.pubMosqueIndexSync(); } catch (e) {}
      closeModal(); renderNav(); mount();
      showToast(mCx ? "أُضيف المسجد إلى " + complexName(mCx) : "أُضيف المسجد كمسجد مستقل");
      break;
    }
    case "save-circle": {
      const name = val("#c_name");
      if (!name) { showToast("اسم الحلقة مطلوب", "warn"); break; }
      if (!STATE.complexId) { showToast("أضف مجمعاً أولاً من صفحة المجمعات", "warn"); break; }
      const cFac     = facTwoValue("c_cx", "c_mosque");
      const cTeacher = val("#c_teacher", (DB.teachers[0] || {}).name || "—");
      if (!cFac.complexId) { showToast("اختر مسجداً أو مجمعاً للحلقة", "warn"); break; }
      if (val("#c_mode") !== "anchor") {
        const _s = val("#c_start", ""), _e = val("#c_end", "");
        if ((_s && !clockValid(_s)) || (_e && !clockValid(_e))) {
          showToast("الوقت غير صحيح — الساعة من 00 إلى 23 والدقائق من 00 إلى 59", "warn"); break;
        }
      }
      const o = { id: Date.now(), complexId: cFac.complexId, name,
        mosque: cFac.mosque, mosqueId: cFac.mosqueId,
        teacher: cTeacher, teacherId: idByName("teachers", cTeacher),
        type: val("#c_type", "مبتدئين"),
        /* مصفوفة لا نصّ: يُحسب عليها ويرثها الطلاب بلا لبس */
        days: daysValue("c_days"),
        start: val("#c_start", "16:30"), end: val("#c_end", "18:00"),
        /* المرتبطة بأذان: يُحسب وقتها يومياً من المواقيت */
        anchor: val("#c_mode") === "anchor" ? val("#c_anchor", "Asr") : "",
        offset: val("#c_mode") === "anchor" ? (Number(val("#c_offset")) || 0) : 0,
        endAnchor: val("#c_mode") === "anchor" ? val("#c_endAnchor", "") : "",
        capacity: Number(val("#c_cap")) || 0,
        termId: val("#c_term", ""),
        /* شعارُ الحلقة — يظهر على بطاقتها في تطبيق المعلّم */
        photo: photoVal("c_photo", ""),
        status: "لم تعتمد", last: "—" };
      photoReset("c_photo");
      /* students لم يعد يُخزَّن: كان يُكتب صفراً ولا يُحدَّث أبداً بينما
         الطلاب مرتبطون بـ circleId — يُحسب الآن بـ circleCount. */
      DB.circles.push(o); persistSet("circles", o);
      closeModal(); renderNav(); mount(); showToast("تمت إضافة الحلقة"); break;
    }
    case "save-student": {
      const name = val("#s_name");
      if (!name) { showToast("اسم الطالب مطلوب", "warn"); break; }
      /* الاختيارُ إلزاميّ: إمّا خطّةٌ يُتابَع عليها، وإمّا تحضيرٌ وحده */
      const sEnroll = val("#s_enroll", "");
      if (!sEnroll) { showToast("اختر نوع التسجيل: تُنسب لخطة أم تحضير فقط", "warn"); break; }
      const sIdErr = stuIdNoError(val("#s_idno", ""), null);
      if (sIdErr) { showToast(sIdErr, "warn"); break; }

      /* كان الشرطُ STATE.complexId، وهو فارغٌ عند مدير المسجد المستقلّ:
         لا مجمّعَ في نطاقه فتُردّ إضافةُ الطالب ويُقال له «أضف مجمعاً» —
         وليس ذلك من عمله. المطلوبُ منشأةٌ يُنسب إليها الطالب: مسجدٌ أو
         مجمّع، أيُّهما كان. والمسجدُ المستقلُّ يكفي وحده. */
      const sFac    = facTwoValue("s_cx", "s_mosque");
      if (!sFac.mosqueId && !sFac.complexId && !STATE.complexId) {
        showToast("اختر المسجد أو المجمع الذي يُنسب إليه الطالب", "warn"); break;
      }
      const sCircle = val("#s_circle", (DB.circles[0] || {}).name || "—");
      /* نموذج الطالب لا يحوي حقل معلم، وكان الكود يسند «أول معلم في النظام»
         أياً كانت الحلقة. المعلم الصحيح هو معلم الحلقة المختارة. */
      const sCircleRec = recByName("circles", sCircle);
      /* السعة كانت بلا أثر: الحلقة تقبل بلا سقف مهما حُدّد لها */
      if (sCircleRec && circleFull(sCircleRec)) {
        showToast("حلقة " + sCircle + " مكتملة (" +
          toArabicDigits(sCircleRec.capacity) + " طالباً) — اختر حلقة أخرى أو ارفع الحد", "warn");
        break;
      }
      const sTeacher   = sCircleRec && sCircleRec.teacher ? sCircleRec.teacher : ((DB.teachers[0] || {}).name || "—");
      const sTeacherId = sCircleRec && sCircleRec.teacherId ? String(sCircleRec.teacherId) : idByName("teachers", sTeacher);
      /* المجمّعُ من المسجد إن وُجد، وإلا من المجمّع الحالي — والمسجدُ
         المستقلُّ يبقى بلا مجمّع، وهو صحيحٌ لا نقص. */
      const o = { id: Date.now(), complexId: sFac.complexId || STATE.complexId || "", name,
        photo: photoVal("s_photo", ""),
        mosque: sFac.mosque, mosqueId: sFac.mosqueId,
        circle: sCircle,   circleId:  idByName("circles", sCircle),
        teacher: sTeacher, teacherId: sTeacherId,
        parent: (function () { const r = phoneRead("s_parent"); return r ? (r.full || "—") : val("#s_parent", "—"); })(),
        parentCC: (function () { const r = phoneRead("s_parent"); return r ? r.cc : ""; })(),
        attType: val("#s_attType", "دوام كامل"),
        /* الأيام تُرَث من الحلقة إن تُركت فارغة بدل نصّ "يومياً" الافتراضي */
        days: val("#s_days", "") || circleDaysOf(sCircle) || "يومياً",
        birth: val("#s_birth", ""),
        age: (function () {
          /* يبقى age لأن التقارير تقرؤه، لكنه محسوب لا مكتوب */
          const a = ageFromBirth(val("#s_birth", ""));
          return a == null ? "—" : String(a);
        })(),
        /* «تحضير فقط» بلا برنامجٍ ولا مستوى (٤٣٢): حقلاهما مخفيّان عنده،
           وكانت تُقرأ قيمتاهما الافتراضيتان فيُنسب إلى أوّل برنامجٍ ومستوى */
        program: sEnroll === "attend" ? "" : val("#s_program", (DB.programs[0] || {}).name || "—"),
        /* المعرّف للربط والاسم ليبقى مقروءاً في التقارير */
        levelId: sEnroll === "attend" ? "" : val("#s_level", ""),
        level: sEnroll === "attend" ? "" : lvNameById(val("#s_level", "")),
        /* نوعُ التسجيل يُحفظ في السجلّ: التقاريرُ تحتاج تمييزَ من يُتابَع
           على خطّةٍ ممّن سُجّل للتحضير وحده. */
        enrollType: sEnroll,
        progress: 0, delays: 0, status: val("#s_status", "نشط"),

        /* البيانات الشخصية: تُحفظ في ملفّه لا على ورقةٍ خارجه */
        idNo: toLatinDigitsSafe(val("#s_idno", "")).trim(), nationality: val("#s_nat", ""),
        school: val("#s_school", ""), grade: val("#s_grade", ""),
        phone: val("#s_phone", ""), parentRel: val("#s_rel", "الأب"),
        address: val("#s_addr", ""), health: val("#s_health", ""),
        joinedAt: Date.now() };
      DB.students.push(o); persistSet("students", o); photoReset("s_photo");
      /* «تم إضافة طالب جديد إلى الحلقة» — تنبيهٌ لمعلّمها */
      try {
        const _c = (DB.circles || []).find(x => String(x.id) === String(o.circleId || ""));
        if (_c && _c.teacherId) notifyUser(_c.teacherId, "studentAdded",
          "أُضيف الطالبُ «" + (o.name || "") + "» إلى حلقة «" + (_c.name || "") + "».");
      } catch (e) {}
      closeModal(); renderNav(); mount(); showToast("تمت إضافة الطالب"); break;
    }
    case "save-teacher": {
      const name = val("#t_name");
      if (!name) { showToast("اسم المعلم مطلوب", "warn"); break; }
      const gmailUser = val("#t_user");
      if (!gmailUser) { showToast("البريد الإلكتروني مطلوب", "warn"); break; }
      if (!STATE.complexId) { showToast("أضف مجمعاً أولاً من صفحة المجمعات", "warn"); break; }
      const email = gmailUser + "@gmail.com";
      const tFac    = facTwoValue("t_cx", "t_mosque");
      /* فُتح النموذجُ من مجمّع: المسجدُ لازمٌ وإلّا عُلّق المعلّمُ بلا موضع */
      if (window.__facTeacherNeedsMosque && !tFac.mosqueId) {
        showToast("اختر المسجد الذي سيعمل فيه المعلم", "warn"); break;
      }
      /* «—» أوّلُ الخيارات: لا يُسند المعلّمُ الجديدُ إلى أوّل حلقةٍ تلقائياً (٤٣١) */
      const tCircle = val("#t_circle", "—");
      const o = { id: Date.now(), complexId: tFac.complexId || STATE.complexId, name, phone: val("#t_phone", "—"),
        photo: photoVal("t_photo", ""),
        mosque: tFac.mosque, mosqueId: tFac.mosqueId,
        circle: tCircle, circleId: tCircle === "—" ? "" : (idByName("circles", tCircle) || ""),
        username: email, students: 0, session: "لم تعتمد", attDone: false, recite: 0, late: 0,
        status: val("#t_status", "نشط"),
        staffRole: val("#t_staffrole", "teacher"),
        qual: val("#t_qual", ""), spec: val("#t_spec", ""),
        startDate: val("#t_start", ""), idNo: val("#t_idno", ""),
        active: val("#t_status", "نشط") === "نشط" };

      /* الأجر في حقله وحده — المسيّر يقرؤه منه */
      Object.assign(o, payFields(val("#t_payType", "monthly"), val("#t_pay")));
      DB.teachers.push(o); persistSet("teachers", o); photoReset("t_photo");
      window.__facTeacherNeedsMosque = false;
      closeModal(); renderNav(); mount(); showToast("تمت إضافة المعلم"); break;
    }
    /* save-program و save-edit-program صارا ميتين: النموذجان يُحيلان إلى
       prgForm/prgSave. تُركا مُحيلَين لا محذوفَين، لأن نداءً قديماً من
       شاشةٍ لم تُحدَّث سيقع عليهما فيصمت بلا أثر لو حُذفا. */
    case "save-program":
    case "save-edit-program":
      if (typeof window.prgSave === "function") window.prgSave();
      break;

    case "save-level": closeModal(); showToast("تمت إضافة المستوى للبرنامج"); break;
    case "save-duty": {
      const name = val("#d_name");
      if (!name) { showToast("اسم الواجب مطلوب", "warn"); break; }
      const colorMap = { "تركوازي": "var(--brand-main)", "ذهبي": "var(--gold)", "أحمر": "var(--danger)", "أزرق": "var(--info)", "بنفسجي": "var(--purple)" };
      const o = { id: Date.now(), complexId: STATE.complexId, name, color: colorMap[val("#d_color", "تركوازي")] || "var(--brand-main)", active: val("#d_active", "مفعّل") === "مفعّل", required: val("#d_req", "إلزامي") === "إلزامي", blocks: val("#d_blocks", "لا") === "نعم",
        order: Number(val("#d_order")) || (DB.dutyTypes.length + 1),
        needsId: val("#d_needs", ""),
        _o: DB.dutyTypes.length };
      DB.dutyTypes.push(o); persistSet("dutyTypes", o);
      closeModal(); mount(); showToast("تمت إضافة نوع الواجب"); break;
    }

    /* ---- Plan Builder ---- */
    case "b-scope": {
      const k = t.dataset.scope || "student";

      /* الرجوعُ إلى «طالب واحد» يحفظ النطاقَ المختار: من اختار مسجداً ثمّ
         عدل إلى طالبٍ منه لا يبحث عنه بين طلاب النظام كلِّهم. */
      if (k === "student") {
        if (builderState.scope !== "student" && builderState.scopeId) {
          builderState.scopeKind = builderState.scope;
        }
      } else {
        builderState.scopeKind = "";
        if (builderState.scope !== k) builderState.scopeId = "";
      }

      builderState.scope = k;
      builderState.student = "";
      mount();
      break;
    }

    case "b-scope-pick": {
      builderState.scopeId = String(t.dataset.id || "");
      mount();
      break;
    }

    case "builder-next": {
      readBuilderStep(builderState.step);
      if (builderState.step === 0) {
        const B0 = builderState;
        if (B0.scope === "student" && !B0.student) {
          showToast("اختر الطالب أولاً", "warn"); break;
        }
        if (B0.scope !== "student" && !B0.scopeId) {
          showToast("اختر " + (B0.scope === "mosque" ? "المسجد" : "المجمّع") + " أولاً", "warn"); break;
        }
        if (B0.scope !== "student") {
          const kids0 = facilityStudents(B0.scope, B0.scopeId);
          if (!kids0.length) { showToast("لا طلاب في هذا النطاق", "warn"); break; }
        }
      }
      if (builderState.step === 1 && !builderState.program) { showToast("اختر البرنامج أولاً", "warn"); break; }
      builderState.step = Math.min(builderState.step + 1, BUILDER_STEPS.length - 1);
      rerenderPlansPanel(); break;
    }
    case "builder-prev": {
      readBuilderStep(builderState.step);
      builderState.step = Math.max(builderState.step - 1, 0);
      rerenderPlansPanel(); break;
    }
    case "builder-goto": {
      const target = +t.dataset.step;
      if (target <= builderState.step) { readBuilderStep(builderState.step); builderState.step = target; rerenderPlansPanel(); }
      break;
    }
    case "builder-pick": {
      readBuilderStep(builderState.step);
      builderState[t.dataset.key] = t.dataset.val;
      rerenderPlansPanel(); break;
    }
    case "builder-sched": {
      const dt = t.dataset.duty, day = t.dataset.day;
      const arr = builderState.sched[dt] || (builderState.sched[dt] = []);
      const idx = arr.indexOf(day);
      if (idx >= 0) arr.splice(idx, 1); else arr.push(day);
      rerenderPlansPanel(); break;
    }
    case "builder-create": {
      const B = builderState;
      if (!B.program) { showToast("أكمل اختيار البرنامج", "warn"); break; }

      /* =================================================================
         الاعتماد — واحدٌ أو نطاقٌ كامل
         -----------------------------------------------------------------
         الخطةُ تُنسَخ لكلّ طالبٍ في النطاق: لكلٍّ سجلُّه وتقدّمُه
         ومتأخّراتُه. ومن له خطّةٌ قائمةٌ تُترك — لا تُستبدل خطّةُ طالبٍ
         بلا قصدٍ من صاحبها.
         ================================================================= */
      let targets = [];
      if (B.scope === "student") {
        if (!B.student) { showToast("أكمل اختيار الطالب", "warn"); break; }
        const one = DB.students.find(x => x.name === B.student);
        if (one) targets = [one];
      } else {
        if (!B.scopeId) { showToast("اختر النطاق أوّلاً", "warn"); break; }
        targets = facilityStudents(B.scope, B.scopeId);
      }

      if (!targets.length) { showToast("لا طلاب في هذا النطاق", "warn"); break; }

      const skipped = [];
      let made = 0, lastId = null;

      targets.forEach((st, k) => {
        /* من له خطّةٌ قائمة يُترك */
        const has = (DB.plans || []).some(p =>
          String(p.studentId || "") === String(st.id) ||
          (p.student && p.student === st.name));
        if (has && B.scope !== "student") { skipped.push(st.name); return; }

        const preview = builderToPlan(st);
        const id = Date.now() + k;
        lastId = id;

        DB.plans.unshift({
          id, complexId: STATE.complexId,
          studentId: String(st.id), student: st.name,
          circle: preview.circle, program: B.program, level: B.level,
          start: preview.start, current: preview.current, end: preview.end,
          amount: B.amount, unit: B.unit,
          fixLessons: Math.max(1, Number(B.fixLessons) || 5),
          progress: 0, delays: 0, status: "نشطة"
        });

        PLAN_EXTRA[id] = {
          health: "healthy", healthReason: "خطة جديدة أُنشئت عبر باني الخطط.",
          healthAction: "تابع أول جلسة تسميع.",
          sched: preview.ext.sched, rules: B.rules,
          /* قواعدُ البرنامج تُنسخ إلى planRules عند الإنشاء: البرنامجُ يضبط
             البداية، والخطةُ تملك تعديلَها بعد ذلك. */
          transition: { mode: B.transition === "تلقائي" ? "automatic" : "supervisor",
                        test: false, noDelays: true, minScore: 7 },
          history: [{ by: USER_NAME[STATE.iface] || "الإدارة", role: "مدير النظام",
                      dt: "الآن", field: "إنشاء الخطة", before: "—",
                      after: preview.start + " ← " + preview.end,
                      reason: B.scope === "student" ? "إنشاء عبر باني الخطط"
                            : "إنشاءٌ جماعيّ لنطاق " + (B.scope === "mosque" ? "مسجد" : "مجمّع") }],
          requests: [], today: preview.ext.today, tomorrow: preview.ext.tomorrow
        };

        /* الخطةُ الجديدةُ منهجُه، والقديمةُ تُستبدل */
        try { builderAdopt(st, DB.plans.find(x => x.id === id), B); } catch (e) { console.warn("builderAdopt:", e); }
        persistPlan(id);
        prgSeedPlanRules(id, B.program);
        /* توجيلاتُ الباني تعلو افتراضيَّ البرنامج: كانت تُحفظ في الذاكرة
           (PLAN_EXTRA) ولا تبلغ planRules، فيُطفئ المشرف قاعدةً وتبقى. */
        try { planRulesSeedFrom(id, B.rules); } catch (e) {}
        made++;
      });

      builderState.step = 0; builderState.student = "";
      builderState.program = ""; builderState.scopeId = "";
      STATE.tab.plans = "active";
      STATE.planId = (B.scope === "student") ? lastId : null;
      renderNav(); mount();

      showToast(made === 1 ? "تم إنشاء الخطة وحفظها"
        : "أُنشئت " + toArabicDigits(made) + " خطة" +
          (skipped.length ? " · تُركت " + toArabicDigits(skipped.length) + " خطّةً قائمة" : ""),
        "success");
      break;
    }

    /* ---- Plan actions ---- */
    case "edit-path-save": {
      const p = planOfDs(t.dataset.id), id = p ? p.id : t.dataset.id, pl = p ? getPlan(id) : null;
      if (!p || !pl) { showToast("الخطة غير موجودة", "warn"); break; }
      const reason = val("#ep_reason", "تعديل يدوي");
      const newCurrent = val("#ep_current", p.current), newAmount = val("#ep_amount", p.amount), newUnit = val("#ep_unit", p.unit), newEnd = val("#ep_end", p.end);
      const ext = PLAN_EXTRA[id] || (PLAN_EXTRA[id] = pl.ext);
      if (newAmount && newAmount !== p.amount) ext.history.unshift({ by: USER_NAME[STATE.iface], role: "مدير النظام", dt: "الآن", field: "المقدار اليومي", before: p.amount, after: newAmount, reason });
      if (newCurrent && newCurrent !== p.current) ext.history.unshift({ by: USER_NAME[STATE.iface], role: "مدير النظام", dt: "الآن", field: "الموضع الحالي", before: p.current, after: newCurrent, reason });
      p.current = newCurrent || p.current; p.amount = newAmount || p.amount; p.unit = newUnit || p.unit; p.end = newEnd || p.end;
      persistPlan(id); closeModal(); mount(); showToast("تم حفظ تعديل المسار");
      break;
    }
    case "freeze-confirm": {
      const p = planOfDs(t.dataset.id), id = p ? p.id : t.dataset.id, pl = p ? getPlan(id) : null;
      if (!p || !pl) { showToast("الخطة غير موجودة", "warn"); break; }
      const ext = PLAN_EXTRA[id] || (PLAN_EXTRA[id] = pl.ext);
      const reason = val("#fz_reason", "—");
      const wasFrozen = ext.health === "frozen";
      ext.health = wasFrozen ? "healthy" : "frozen";
      ext.healthReason = wasFrozen ? "أُعيد تفعيل الخطة." : "الخطة مجمّدة بقرار إداري.";
      ext.healthAction = wasFrozen ? "تابع أول جلسة بعد العودة." : "أعد التفعيل عند جاهزية الطالب.";
      p.status = wasFrozen ? "نشطة" : "متوقفة";
      /* الحقل المحفوظ هو ما يقرؤه محرّك الواجبات: بدونه يُجمَّد في الشاشة
         ويظلّ المحرّك يولّد له واجبات كل يوم. */
      p.frozen = !wasFrozen;
      if (!wasFrozen) { p.frozenAt = Date.now(); p.freezeReason = reason; }
      else { p.unfrozenAt = Date.now(); }
      persistSet("plans", p);
      ext.history.unshift({ by: USER_NAME[STATE.iface], role: "مدير النظام", dt: "الآن", field: "حالة الخطة", before: wasFrozen ? "مجمدة" : "نشطة", after: wasFrozen ? "نشطة" : "مجمدة", reason });
      persistPlan(id); closeModal(); mount(); showToast(wasFrozen ? "تم إعادة تفعيل الخطة" : "تم تجميد الخطة");
      break;
    }
    case "comp-save": {
      const p = planOfDs(t.dataset.id), id = p ? p.id : t.dataset.id, pl = p ? getPlan(id) : null;
      if (!p || !pl) { showToast("الخطة غير موجودة", "warn"); break; }
      const ext = PLAN_EXTRA[id] || (PLAN_EXTRA[id] = pl.ext);
      const reason = val("#ac_reason", "غياب");
      const duty = val("#ac_duty", "حفظ جديد");
      const from = val("#ac_from", ""), to = val("#ac_to", "");
      const blocksEl = document.querySelector('[data-toggle="ac_blocks"]');
      const blocks = blocksEl ? blocksEl.checked : true;
      p.delays = (p.delays || 0) + 1;
      const dly = { id: Date.now(), complexId: STATE.complexId, student: p.student, circle: p.circle, reason, duty: `${duty}${from ? " (" + from + (to ? " → " + to : "") + ")" : ""}`, date: val("#ac_date", "اليوم"), blocks, status: "مفتوح" };
      DB.delays.unshift(dly); persistSet("delays", dly);
      ext.history.unshift({ by: USER_NAME[STATE.iface], role: "مدير النظام", dt: "الآن", field: "تعويض", before: "—", after: "تعويض مفتوح", reason: "إضافة تعويض يدوي" });
      persistPlan(id); closeModal(); mount(); showToast("تمت إضافة التعويض");
      break;
    }
    case "promote-confirm": {
      const p = planOfDs(t.dataset.id), id = p ? p.id : t.dataset.id, pl = p ? getPlan(id) : null;
      if (!p || !pl) { showToast("الخطة غير موجودة", "warn"); break; }
      /* =================================================================
         الترقيةُ إلى المستوى التالي فعلاً (٤٣٢)
         -----------------------------------------------------------------
         كانت تبدّل كلمةَ «الأول» بـ«الثاني» في نصّ المستوى وحده: levelId
         باقٍ، ومستوى الطالب لا يتغيّر، ومحرّكُ الواجبات يمضي على القديم.
         الآن تمرّ بالمسار نفسِه الذي في صفحة الخطة (planPromoteDo): المستوى
         التالي في برنامجه بترتيبه، وشرطُ الانتقال، وسجلُّ الطالب معه.
         ================================================================= */
      const ext = PLAN_EXTRA[id] || (PLAN_EXTRA[id] = pl.ext);
      const nextLv = typeof nextLevelOf === "function" ? nextLevelOf(p) : null;
      if (!nextLv) { showToast("لا مستوى تالٍ في برنامج الطالب — أضِفه من الإعدادات ← البرامج والمستويات أولاً", "warn"); break; }
      const fromLv = p.level || "";
      window.linkChange(() => window.planPromoteDo(p.id, nextLv.id));
      if (String(p.levelId) === String(nextLv.id)) {
        ext.history.unshift({ by: USER_NAME[STATE.iface], role: "مدير النظام", dt: "الآن", field: "المستوى", before: fromLv, after: nextLv.name, reason: "اعتماد ترقية" });
        ext.health = "healthy";
        persistPlan(id);
      }
      closeModal(); mount();
      break;
    }
    case "req-approve":
    case "req-reject": {
      const _rp = planOfDs(t.dataset.id), id = _rp ? _rp.id : t.dataset.id, i = +t.dataset.i, pl = _rp ? getPlan(id) : null;
      if (!pl) { showToast("الخطة غير موجودة", "warn"); break; }
      const ext = PLAN_EXTRA[id] || (PLAN_EXTRA[id] = pl.ext);
      const req = ext.requests[i];
      if (!req) break;
      req.status = a === "req-approve" ? "approved" : "rejected";
      persistPlan(id); mount(); showToast(a === "req-approve" ? "تمت الموافقة" : "تم الرفض", a === "req-approve" ? "success" : "warn");
      break;
    }

    case "set-att": {
      const wrap = t.parentElement;
      $$(".chip", wrap).forEach(c => c.classList.remove("day-on"));
      t.classList.add("day-on");
      break;
    }
  }
});

/* =========================================================
   FIRESTORE DATA LAYER
   ========================================================= */
function FDB() { return (typeof window !== "undefined" && window.__db) ? window.__db : null; }

/* إعدادات النظام مخزّنة كمستندات (general · exams) يحمل كلٌّ منها الكتلة كاملة،
   والكود يتعامل معها ككائن واحد. لذلك تُدمج هنا بدل تحويلها إلى مصفوفة. */
async function loadSettings(db, source) {
  const merged = {};
  try {
    const snap = await db.collection("settings").get(source ? { source: source } : undefined);
    snap.forEach(d => Object.assign(merged, d.data() || {}));
    delete merged.id;
    delete merged._o;
  } catch (err) {
    console.warn("loadSettings", err);
  }
  DB.settings = merged;
  /* طبقةُ المسجد: المساجدُ حُمّلت قبلها في المجموعات الأساسية */
  try { if (typeof cfgApplyOverlay === "function") cfgApplyOverlay(true); } catch (e) {}
}

async function loadAllData(source) {
  const db = FDB();
  if (!db) { FB_READY = false; FB_LOADED = true; return false; }

  /* قراءة متسامحة: رفض مجموعة واحدة (صلاحيات أو شبكة) كان يُسقط التحميل كلّه
     لأن Promise.all يرفض عند أول خطأ. الآن تُعزل كل مجموعة على حدة. */
  /* source = "cache" يقرأ من IndexedDB بلا شبكة، و"server" يفرض الشبكة،
     و undefined يترك القرار لـ Firestore (سلوكه الأصلي). */
  const opts = source ? { source: source } : undefined;

  /* مجموعات إدارية بحتة: قواعد Firestore تمنع سردها لغير الإدارة، فمحاولة
     تحميلها تفشل بالضرورة وتملأ الكونسول بأخطاء صلاحيات لا حيلة فيها.
     تُستثنى لغير الإداريين بدل أن تُطلب ثم تُرفض. */
  const _r = ((STATE && STATE.user) || {}).role || "";
  const _adminOnly = ["users", "userRequests", "dutyTypes", "certTemplates",
                      "examSupervisors", "examCommittees", "examRouting", "rewardRules"];
  /* سجلُّ العمليات لا يُنزَّل مع الباقي (٤٢٥): يكبر مع كلّ حفظٍ ولا يقرؤه
     إلّا صفحتُه، فكان يُنزَّل كاملاً مع كلّ فتحةٍ لأيّ صفحة. يُحمَّل عند
     فتح صفحته وحدَها — انظر audLazyLoad. */
  /* وما تحجبه القواعدُ عن الدور (٤٤٠ — hiddenFrom في firestore.rules):
     لا تقرؤه شاشةٌ من شاشاته، فلا يُطلب ولا يُنزَّل إلى جهازه. */
  const _hidden = ({
    teacher: ["paySheets", "admissions"],
    student: ["paySheets", "admissions", "msgOutbox", "moveLog", "procLog", "sysAlerts"],
    parent:  ["paySheets", "admissions", "msgOutbox", "moveLog", "procLog", "sysAlerts"]
  })[_r] || [];
  const _cols = ((_r && _r !== "admin" && !isMgrRole(_r))
    ? COLLECTIONS.filter(c => _adminOnly.indexOf(c) === -1 && _hidden.indexOf(c) === -1)
    : COLLECTIONS).filter(c => c !== "auditLog");

  /* =====================================================================
     مستندُ صاحب الجلسة
     ---------------------------------------------------------------------
     سردُ users ممنوعٌ على غير الإدارة، فتبقى DB.users فارغةً عند الطالب
     والمعلّم ووليّ الأمر — ولا يجد أحدُهم ملفَّه فيُقال له «حسابك غير
     مرتبط بسجل» وهو مرتبط.

     والقواعدُ تُتيح له قراءةَ مستندِه وحدَه: يُجلب مباشرةً فيُعرف ملفُّه
     ويُقرأ ما فيه من ربطٍ بطالبٍ أو معلّم. */
  if (_r && _r !== "admin" && !isMgrRole(_r)) {
    const _me = String(((STATE && STATE.user) || {}).uid ||
                       ((STATE && STATE.user) || {}).id || "");
    /* قراءةٌ واحدةٌ بدل اثنتين (٤٢٥): بوّابةُ الدخول قرأت هذا المستندَ
       نفسَه للتوّ، فكان يُقرأ مرّةً ثانيةً هنا (وثالثةً مع جولة الخادم).
       يُؤخذ ما قرأته البوّابةُ إن لم يمضِ عليه دقيقة، وإلّا قُرئ كما كان. */
    const _pf = (typeof window !== "undefined") ? window.__ZAT_PROFILE : null;
    if (_me && _pf && String(_pf.uid) === _me && _pf.d && (Date.now() - Number(_pf.t || 0)) < 60000) {
      DB.users = [Object.assign({ id: _me }, _pf.d)];
    } else if (_me) {
      try {
        const snap = await db.collection("users").doc(_me).get(opts);
        if (snap && snap.exists) {
          const d = snap.data() || {};
          DB.users = [Object.assign({ id: snap.id }, d)];
        }
      } catch (e) { /* مرفوضٌ أو غير موجود: تبقى فارغةً كما كانت */ }
    }
  }

  /* =====================================================================
     التحميل على دفعتين
     ---------------------------------------------------------------------
     كانت إحدى وأربعون مجموعةً تُقرأ دفعةً واحدة، والشاشة تنتظرها كلّها —
     فمن أراد التحضير انتظر تحميلَ الاختبارات والشهادات وسجلّ العمليات
     ومسيّرات الرواتب، وهي مما لا يحتاجه في تلك اللحظة.

     الأساسيُّ يُقرأ أوّلاً وتُعرض الشاشة، والباقي يلحق في الخلفية ويُعاد
     الرسم عند وصوله. فيرى المستخدم نظامَه في ثانيةٍ بدل عشر.
     ===================================================================== */
  const CORE = ["students", "circles", "teachers", "plans", "assignments",
                "attendance", "levels", "programs", "terms", "mosques",
                "complexes", "users", "recitations"];

  const core = _cols.filter(c => CORE.indexOf(c) > -1);
  const rest = _cols.filter(c => CORE.indexOf(c) === -1);

  /* =====================================================================
     رسائلُ صاحب الجلسة وحدَها (٤٣٢)
     ---------------------------------------------------------------------
     القواعدُ لا تُجيز لغير الإدارة سردَ site_messages كلِّها — كان ذلك
     ثغرةً يقرأ بها الطالبُ رسائلَ غيره. فيُقرأ ما أُرسل إليه وما أرسله هو،
     باستعلامين تمرّهما القاعدة، ويُدمجان في شكل اللقطة نفسِه.
     ===================================================================== */
  const _mgrRead = !_r || _r === "admin" || _r === "owner" || isMgrRole(_r);
  const _myMail = String(((STATE && STATE.user) || {}).email || "").toLowerCase();
  const readMine = c => {
    if (!_myMail) return Promise.resolve({ c, snap: { forEach() {} } });
    const qs = ["toEmail", "fromEmail"].map(f => db.collection(c).where(f, "==", _myMail).get(opts));
    return Promise.all(qs).then(snaps => {
      const seen = {}, docs = [];
      snaps.forEach(sn => sn.forEach(d => { if (!seen[d.id]) { seen[d.id] = 1; docs.push(d); } }));
      return { c, snap: { forEach: fn => docs.forEach(fn) } };
    });
  };
  /* =====================================================================
     الطالبُ ووليُّ أمره: سجلّاتُ أبنائه وحدَها (٤٤٤)
     ---------------------------------------------------------------------
     القواعدُ تقصر قراءتَهما في هذه المجموعات على ما يحمل studentId من
     أبنائهما (kidOwn في firestore.rules)، وفي students على سجلّاتهم بأعيانها.
     وقواعدُ Firestore لا تُصفّي: استعلامُ المجموعة كلِّها يُردّ كلُّه. فيُقرأ
     لكلّ ابنٍ استعلامُه (where studentId ==) ويُدمج في شكل اللقطة نفسِه.
     ===================================================================== */
  const _kid = _r === "student" || _r === "parent";
  const _kidIds = _kid ? [...new Set([((STATE && STATE.user) || {}).studentId]
      .concat(((STATE && STATE.user) || {}).studentIds || [])
      .filter(x => x != null && x !== "").map(String))] : [];
  const KID_COLLS = ["assignments", "attendance", "recitations", "mushafMarks", "plans",
                     "pointsLog", "exams", "storeOrders", "delays"];
  const readKid = c => {
    const qs = c === "students"
      ? _kidIds.map(id => db.collection(c).doc(id).get(opts).then(d => (d && d.exists ? [d] : []), () => []))
      : _kidIds.map(id => db.collection(c).where("studentId", "==", id).get(opts).then(sn => sn.docs));
    return Promise.all(qs).then(arrs => {
      const seen = {}, docs = [];
      arrs.forEach(a => a.forEach(d => { if (!seen[d.id]) { seen[d.id] = 1; docs.push(d); } }));
      return { c, snap: { forEach: fn => docs.forEach(fn) } };
    });
  };
  /* =====================================================================
     المعلّمُ ومديرُ المسجد والمشرف: سجلّاتُ مسجدهم وحدَها (٤٤٧)
     ---------------------------------------------------------------------
     القواعدُ تقصر قراءتَهم في هذه المجموعات على ما يحمل mosqueId من
     مساجدهم (mqOwn في firestore.rules)، فيُقرأ لكلّ مسجدٍ استعلامُه.
     ومن لا مسجدَ في ملفّه يُقرأ له كما كان — والقاعدةُ تُبقيه كذلك.
     ===================================================================== */
  const _su = (STATE && STATE.user) || {};
  const _mqIds = ["teacher", "mosqueManager", "supervisor"].indexOf(_r) > -1
    ? [...new Set([_su.mosqueId].concat((_su.scopeIds || [])
        .filter(k => String(k).indexOf("mosque:") === 0).map(k => String(k).split(":")[1]))
        .concat(_su.mosqueIds || []).filter(x => x != null && x !== "").map(String))]
    : [];
  const MQ_COLLS = ["students", "teachers", "plans", "assignments", "attendance", "recitations",
                    "mushafMarks", "exams", "delays", "pointsLog", "storeOrders"];
  const readMq = c => Promise.all(_mqIds.map(m =>
      db.collection(c).where("mosqueId", "==", m).get(opts).then(sn => sn.docs, e => {
        console.warn("تعذّرت قراءة المجموعة:", c, "مسجد", m, e && e.code); return []; })))
    .then(arrs => {
      const seen = {}, docs = [];
      arrs.forEach(a => a.forEach(d => { if (!seen[d.id]) { seen[d.id] = 1; docs.push(d); } }));
      return { c, snap: { forEach: fn => docs.forEach(fn) } };
    });
  /* =====================================================================
     ومديرُ المجمّع: سجلّاتُ مجمّعه وحدَها (٤٥٢)
     ---------------------------------------------------------------------
     القواعدُ تقصر قراءتَه في هذه المجموعات على ما يحمل complexId من
     مجمّعاته (cxOwn في firestore.rules)، فيُقرأ لكلّ مجمّعٍ استعلامُه.
     ومن لا مجمّعَ في ملفّه يُقرأ له كما كان.
     ===================================================================== */
  const _cxIds = _r === "complexManager"
    ? [...new Set([_su.complexId].concat((_su.scopeIds || [])
        .filter(k => String(k).indexOf("complex:") === 0).map(k => String(k).split(":")[1]))
        .concat(_su.complexIds || []).filter(x => x != null && x !== "").map(String))]
    : [];
  const readCx = c => Promise.all(_cxIds.map(k =>
      db.collection(c).where("complexId", "==", k).get(opts).then(sn => sn.docs, e => {
        console.warn("تعذّرت قراءة المجموعة:", c, "مجمّع", k, e && e.code); return []; })))
    .then(arrs => {
      const seen = {}, docs = [];
      arrs.forEach(a => a.forEach(d => { if (!seen[d.id]) { seen[d.id] = 1; docs.push(d); } }));
      return { c, snap: { forEach: fn => docs.forEach(fn) } };
    });
  const readOne = c => (c === "site_messages" && !_mgrRead ? readMine(c)
    : (_kid && (c === "students" || KID_COLLS.indexOf(c) > -1)) ? readKid(c)
    : (_mqIds.length && MQ_COLLS.indexOf(c) > -1) ? readMq(c)
    : (_cxIds.length && MQ_COLLS.indexOf(c) > -1) ? readCx(c)
    : db.collection(c).get(opts)
    .then(snap => ({ c, snap }))).then(
    r => r,
    err => { console.warn("تعذّرت قراءة المجموعة:", c, err); return { c, snap: null }; }
  );

  const results = await Promise.all(core.map(readOne));

  /* الباقي بلا انتظار: يُقرأ ويُدمج ثمّ يُعاد الرسم مرّةً واحدة */
  if (rest.length) {
    Promise.all(rest.map(readOne)).then(more => {
      more.forEach(({ c, snap }) => {
        if (!snap) { if (!Array.isArray(DB[c])) DB[c] = []; return; }
        const arr = [];
        snap.forEach(d => {
          const data = d.data() || {};
          arr.push(Object.assign({ id: docIdOf(d.id) }, data));
        });
        arr.sort((a, b) => (a._o != null ? a._o : 0) - (b._o != null ? b._o : 0));
        DB[c] = arr;
      });
      try { if (typeof mount === "function") mount(); } catch (e) {}
    }).catch(() => {});
  }

  const denied = [];
  results.forEach(({ c, snap }) => {
    if (!snap) { denied.push(c); if (!Array.isArray(DB[c])) DB[c] = []; return; }
    const arr = [];
    snap.forEach(d => {
      const data = d.data() || {};
      arr.push(Object.assign({ id: docIdOf(d.id) }, data));
    });
    arr.sort((a, b) => (a._o != null ? a._o : 0) - (b._o != null ? b._o : 0));
    DB[c] = arr;
  });

  /* وقتُ آخر تنزيلٍ ناجحٍ من الخادم لهذا الحساب — يقرؤه loadDataFast
     فلا يُعيد التنزيلَ عند التنقّل بين الصفحات خلال دقيقة (٤٢٥).
     لا يُسجَّل إن فشلت المجموعاتُ كلُّها (انقطاع الشبكة). */
  if (source === "server" && results.some(r => r.snap)) {
    try {
      const _u = String(((STATE && STATE.user) || {}).uid || "");
      if (_u) localStorage.setItem("zat.srvAt." + _u, String(Date.now()));
      /* وعددُ المجموعات غير الفارغة في ذلك التنزيل (٤٣٨): يُقارَن به المخزنُ
         المحلّيّ، فلا يُكتفى بمخزنٍ ناقص (فيه ما كُتب محلّياً وحده) */
      if (_u) localStorage.setItem("zat.srvN." + _u,
        String(COLLECTIONS.filter(c => Array.isArray(DB[c]) && DB[c].length).length));
    } catch (e) {}
  }

  await loadSettings(db, source);

  PLAN_EXTRA = {};
  DB.plans.forEach(p => { if (p.ext) { PLAN_EXTRA[p.id] = p.ext; delete p.ext; } });
  FB_READY = true; FB_LOADED = true;

  /* ظلّ ما جاء من السحابة: بدونه يظهر أول تعديل على سجلٍّ قديم كأنه
     «إضافة» لا «تعديل»، ولا يُعرف ما تغيّر فيه.
     ويُؤخذ قبل الفحص الدوريّ لا بعده: الفحصُ يكتب، فلو سبق الظلَّ لم يجد
     الحارسُ قيمةً سابقةً يردّ إليها — وهو أوّلُ ما يحتاجه. */
  try {
    if (typeof auditKeep === "function") {
      Object.keys(LOG_COLLS).forEach(c => {
        if (Array.isArray(DB[c])) DB[c].forEach(x => { if (x && x.id != null) auditKeep(c, x); });
      });
    }
  } catch (e) {}

  /* فحصةٌ أولى فور وصول البيانات: بدونها تتأخّر التنبيهات دقيقتين */
  try { if (typeof runPeriodicScans === "function") runPeriodicScans(true); } catch (e) {}
  if (denied.length) console.warn("مجموعات لم تُقرأ:", denied.join("، "));
  /* ما رُفضت قراءتُه تقرؤه الشاشاتُ لتقول السببَ بدل أصفارٍ مضلِّلة (٤٢٩) */
  window.__READ_DENIED = source === "cache" ? (window.__READ_DENIED || []) : denied.slice();
  return true;
}

/* =========================================================================
   تحميل سريع — الكاش المحلي أولاً ثم السيرفر في الخلفية
   -------------------------------------------------------------------------
   enablePersistence مفعّل في firebase-config.js، فتحفظ Firestore نسخة من
   المستندات في IndexedDB. القراءة بـ source:"cache" لا تلمس الشبكة إطلاقاً،
   فترسم الشاشة فوراً عند الريفريش، ثم نجلب من السيرفر ونعيد الرسم بهدوء.
   أول تحميل على الجهاز لا كاش له فيمضي إلى السيرفر مباشرة.

   onData(fromCache) تُستدعى مرتين في الحالة العادية: مرة بعد رسم الكاش،
   ومرة أخيرة بعد وصول بيانات السيرفر.
   ========================================================================= */
async function loadDataFast(onData) {
  let painted = false;

  try {
    await loadAllData("cache");
    if (!dataIsEmpty()) {
      painted = true;
      if (onData) { try { onData(true); } catch (e) { console.warn(e); } }
    }
  } catch (err) {
    /* لا كاش على هذا الجهاز بعد — نمضي إلى السيرفر */
  }

  /* لا إعادةَ تنزيلٍ من الخادم خلال دقيقة (٤٢٥): صفحاتُ الإدارة ملفّاتٌ
     منفصلة، فكلُّ نقرةٍ في القائمة كانت تُنزّل المجموعاتِ كلَّها من الخادم
     من جديد. إن رُسمت الشاشةُ من المخزن المحلّيّ وكان آخرُ تنزيلٍ لهذا
     الحساب قبل أقلّ من دقيقة اكتُفي بالمخزن. وما يكتبه المستخدمُ نفسُه
     في المخزن أصلاً، وزرُّ «تحديث» يتجاوز هذا ويقرأ من الخادم دائماً. */
  let fresh = false;
  try {
    const _u = String(((STATE && STATE.user) || {}).uid || "");
    const _t = _u ? Number(localStorage.getItem("zat.srvAt." + _u) || 0) : 0;
    const _age = Date.now() - _t;
    /* المخزنُ الناقص ليس طازجاً (٤٣٨): صفحةٌ بلا مخزنٍ دائم يكون فيها ما
       كُتب محلّياً وحده (إشعارٌ واحد مثلاً)، فيُحسب «مرسوماً» ويُترك الخادم
       فتبقى الشاشةُ فارغةً دقيقةً كاملة. فيُشترط أن يحوي من المجموعات غيرِ
       الفارغة ما حواه آخرُ تنزيلٍ من الخادم. */
    const _n = _u ? Number(localStorage.getItem("zat.srvN." + _u) || 0) : 0;
    const _has = COLLECTIONS.filter(c => Array.isArray(DB[c]) && DB[c].length).length;
    fresh = painted && _t > 0 && _age >= 0 && _age < 60000 && _n > 0 && _has >= _n;
  } catch (e) { fresh = false; }

  if (!fresh) {
    try {
      await loadAllData("server");
    } catch (err) {
      console.warn("Firestore load failed:", err);
      if (!painted) { FB_READY = false; FB_LOADED = true; }
    }
  }

  /* تطبيق الواجبات التي عَلِقت في طابور الاعتماد قبل إلغائه — وإلا بقيت
     معلَّقة إلى الأبد ولا يراها الطالب. */
  /* تُطبَّق في الذاكرة ولا تُكتب: الكتابةُ عند التحميل هي عينُ ما مُنع —
     كانت تكتب program و level و موضعَ الخطة لكلّ سجلٍّ عالقٍ مع كلّ فتحةٍ
     للموقع ولأيّ دور. والعرضُ صحيحٌ بالتطبيق في الذاكرة، والكتابةُ تلحق
     أوّلَ مرّةٍ يحفظ فيها مخوَّلٌ تلك الخطة. */
  try {
    const stuck = (Array.isArray(DB.plans) ? DB.plans : []).filter(x => x && x.pending);
    stuck.forEach(x => {
      const d = x.pending;
      ["current","hFromS","hFromA","hToS","hToA","hFaces","start","rFromS","rFromA",
       "rToS","rToA","rFaces","amount","unit","rAmount","rUnit","program","level","progress","note"]
        .forEach(k => { if (d[k] !== undefined) x[k] = d[k]; });
      x.pending = null;
      x.status = "نشطة";
    });
    if (stuck.length) console.log("طُبّق في الذاكرة " + stuck.length + " واجباً كان عالقاً في الاعتماد");
  } catch (e) { console.warn("stuck duties:", e); }

  /* «شيل كلمة فارق» — واللاحقةُ مكتوبةٌ في سجلّات قديمةٍ كثيرة.
     تُنزع عند العرض في الذاكرة فتختفي من الشاشات كلِّها بموضعٍ واحد،
     ولا تُكتب: تعديلٌ جماعيٌّ على بيانات الإنتاج ممنوع. وتستقرّ في
     السجلّ أوّلَ مرّةٍ يحفظه فيها مخوَّلٌ بنفسه. */
  try {
    let fixed = 0;
    (Array.isArray(DB.assignments) ? DB.assignments : []).forEach(x => {
      if (!x || !x.kindName) return;
      const clean = String(x.kindName).replace(/\s*\(فارق\)\s*$/, "");
      if (clean !== x.kindName) { x.kindName = clean; fixed++; }
    });
    if (fixed) console.log("نُزعت لاحقةُ (فارق) من " + fixed + " واجباً في العرض");
  } catch (e) { console.warn("kindName (فارق):", e); }

  /* استدراك الحسابات القديمة: معلّمون في users بلا سجل في teachers.
     للإداريين وحدهم لأنهم من يملك صلاحية الكتابة. */
  try {
    const role = ((STATE && STATE.user) || {}).role;
    /* ومن يُقرأ له مسجدُه وحدَه لا يُزامِن (٤٤٧): لا يرى معلّمي المساجد الأخرى
       ولا طلابَها، فكانت المزامنةُ تحسب حساباتِهم «بلا سجلّ» فتُنشئ لهم سجلّاتٍ
       مكرّرة. تجري من جلسةٍ تقرأ المنشآتِ كلَّها: المدير والمالك ومدير المجمّع. */
    const _u0 = (STATE && STATE.user) || {};
    const mqScoped = (["mosqueManager", "supervisor"].indexOf(role) > -1 &&
      (_u0.mosqueId || (_u0.scopeIds || []).some(k => String(k).indexOf("mosque:") === 0) ||
       (_u0.mosqueIds || []).length)) ||
      /* ومديرُ المجمّع منذ ٤٥٢ يُقرأ له مجمّعُه وحدَه: لا يُزامِن للسبب نفسه */
      (role === "complexManager" &&
       (_u0.complexId || (_u0.scopeIds || []).some(k => String(k).indexOf("complex:") === 0) ||
        (_u0.complexIds || []).length));
    if ((role === "admin" || isMgrRole(role)) && !mqScoped) {
      /* تلقائيةٌ بالتعريف: تجري بلا طلبٍ من أحدٍ عقب كلّ تحميل، فتُحاط
         بـ linkAuto ليمنعها الحارسُ من مسّ أيّ ارتباط. */
      const n = linkAuto(syncAllTeachers);
      if (n) console.log("أُنشئ سجل معلم لـ " + n + " حساباً كان بلا سجل");
    }
  } catch (e) { console.warn("syncAllTeachers:", e); }

  /* فهرسُ المساجد العلنيُّ يُبنى من نفسه عقب كلّ تحميلٍ لمخوَّلٍ بالكتابة.
     كان يحتاج أمراً يُكتب في الطرفيّة مرّةً واحدة، فإن لم يُكتب بقيت
     خانةُ المسجد في صفحة التسجيل تقول «لا مساجد متاحة» وإن كان في
     النظام مساجد — وهو ما وقع. والكتابةُ لا تقع إلّا إن اختلف الفهرسُ
     عمّا في النظام، فلا كتابةَ مع كلّ فتحةٍ للموقع. */
  try {
    const role2 = ((STATE && STATE.user) || {}).role;
    if ((role2 === "admin" || isMgrRole(role2)) &&
        typeof pubMosqueIndexBuild === "function" &&
        (Array.isArray(DB.mosques) ? DB.mosques.length : 0) > 0) {
      const db2 = typeof FDB === "function" ? FDB() : null;
      if (db2) {
        const want = pubMosqueIndexBuild();
        const key  = JSON.stringify(want.items);
        db2.collection("publicIndex").doc("mosques").get().then(function (sn) {
          const got = (sn && sn.exists ? (sn.data() || {}) : {});
          const had = JSON.stringify(Array.isArray(got.items) ? got.items : null);
          if (had === key) return;                 /* الفهرسُ مطابقٌ — لا كتابة */
          return db2.collection("publicIndex").doc("mosques").set(want)
            .then(function () {
              console.log("حُدّث فهرسُ المساجد العلنيّ (" + want.items.length + " مسجداً)");
            });
        }).catch(function (e) { console.warn("pubMosqueIndex:", e && e.code); });
      }
    }
  } catch (e) { console.warn("pubMosqueIndex:", e); }

  if (onData) { try { onData(false); } catch (e) { console.warn(e); } }
  return painted;
}

const CLEAR_PHRASE = "احذف كل البيانات";
async function clearAllData() {
  /* الحارسُ في الدالّة لا في الزرّ وحدَه: الأزرارُ تُخفى والدوالُّ تُنادى */
  if (!isTopAdmin()) throw new Error("clearAllData: لمدير النظام وحدَه");
  const db = FDB();
  if (db) {
    for (const c of COLLECTIONS) {
      if (CLEAR_KEEP.indexOf(c) > -1) continue;   /* حسابات المستخدمين لا تُمسح */
      const snap = await db.collection(c).get();
      let batch = db.batch(), n = 0;
      for (const d of snap.docs) { batch.delete(d.ref); if (++n >= 400) { await batch.commit(); batch = db.batch(); n = 0; } }
      if (n) await batch.commit();
    }
  }
  COLLECTIONS.forEach(c => { if (CLEAR_KEEP.indexOf(c) === -1) DB[c] = []; });
  PLAN_EXTRA = {};
}

/* فشل الحفظ كان صامتاً (console.warn فقط) فيرى المستخدم «تم الحفظ» ولو لم يُحفظ. */
/* =========================================================================
   سببُ الرفض بعينه
   -------------------------------------------------------------------------
   «راجع الإدارة» لا تقول شيئاً لمن هو الإدارة. تُقارَن هنا صلاحيةُ الحساب
   ونطاقُه بالسجلّ المرفوض — بالقواعد نفسِها التي في firestore.rules — فيُقال
   السببُ وما العمل. وإن بدا كلُّ شيءٍ سليماً في المتصفّح فالرفضُ من الخادم،
   وأرجحُ أسبابه أنّ القواعد لم تُنشر بعد.
   ========================================================================= */
function denyReason(coll, u, rec) {
  const role = String((u && u.role) || "");
  if (!role) return "حسابُك بلا دورٍ معرَّف في سجلّ المستخدمين";
  if (u.active === false) return "حسابُك موقوف";
  const may = role === "admin" || role === "owner" ||
              (typeof isMgrRole === "function" && isMgrRole(role));
  if (!may) return "دورُك «" + role + "» لا يملك حفظَ هذا السجلّ";

  /* النطاق: حسابٌ بلا نطاقٍ يكتب في كلّ شيء، وسجلٌّ بلا منشأةٍ لا يُحجب */
  const ids = [];
  ["mosqueId", "complexId"].forEach(k => { if (u[k]) ids.push(String(u[k])); });
  ["mosqueIds", "complexIds"].forEach(k => {
    if (Array.isArray(u[k])) u[k].forEach(x => ids.push(String(x)));
  });
  if (!ids.length) return "";
  const rm = String((rec && rec.mosqueId) || "");
  const rc = String((rec && rec.complexId) || "");
  if (!rm && !rc) return "";
  if (ids.indexOf(rm) > -1 || ids.indexOf(rc) > -1) return "";

  const nm = n => {
    if (!n) return "";
    const f = (typeof cur === "function"
      ? (cur("mosques") || []).concat(cur("complexes") || []) : [])
      .find(x => String(x.id) === String(n));
    return f ? f.name : n;
  };
  return "السجلُّ خارج نطاقك — منشأتُه «" + (nm(rm) || nm(rc)) +
         "» ليست ضمن ما أُسند إلى حسابك";
}

/* =========================================================================
   نطاقٌ عالق في حساب المدير — إصلاحُه
   -------------------------------------------------------------------------
   المتصفّحُ والخادمُ كانا يختلفان في معنى «حسابٌ بلا نطاق»:
     • app.js: المالكُ والمديرُ بلا نطاقٍ ما لم يُسنَد إليهما scopeIds قصداً،
       فحقلا mosqueId/complexId المفردان أثرُ مزامنةٍ لا اختيار — فيريان
       كلَّ الطلاب.
     • firestore.rules: أيُّ قيمةٍ في الحقلين المفردين تحصر الحساب، فيُرفض
       حفظُ كلِّ سجلٍّ خارجها.
   فيرى المديرُ الطالبَ ويفتحه ويحرّره، ثمّ يُردّ عند الحفظ.

   العلاجُ محوُ الحقلين العالقين من سجلّه هو — ولا يُمنح بذلك شيءٌ جديد:
   المتصفّحُ يعامله أصلاً معاملةَ غير المحصور. ومشروطٌ بألّا يكون له
   scopeIds، فالحصرُ المقصودُ لا يُمَسّ، وبأن يكون دورُه admin أو owner.
   ========================================================================= */
let SCOPE_FIX_TRIED = false;

/* =========================================================================
   إصلاحُ نطاق الحسابات القائمة — مرّةً واحدة
   -------------------------------------------------------------------------
   الحساباتُ المحفوظةُ قبل هذا التصحيح تحمل scopeIds بلا القائمتين
   الجمعيّتين، فيرى صاحبُها منشآتِه كلَّها ولا يكتب إلا في الأولى. تُشتقّ
   القائمتان من scopeIds نفسِه ويُعاد حفظُ ما نقص. لا يُغيَّر إسنادٌ ولا
   يُمنح نطاقٌ جديد. للمالك والمدير وحدَهما — فهما من يملك الكتابة في users.
   يُنادى من الكونسول: fixAllScopes()
   ========================================================================= */
window.fixAllScopes = function () {
  const me = (STATE && STATE.user) || {};
  const role = String(me.role || "");
  if (role !== "admin" && role !== "owner") {
    showToast("هذا الإصلاح لمدير النظام وحده", "warn"); return 0;
  }
  let n = 0;
  (Array.isArray(DB.users) ? DB.users : []).forEach(u => {
    if (!u || !Array.isArray(u.scopeIds) || !u.scopeIds.length) return;
    const mq = u.scopeIds.filter(k => String(k).indexOf("mosque:")  === 0).map(k => String(k).split(":")[1]);
    const cx = u.scopeIds.filter(k => String(k).indexOf("complex:") === 0).map(k => String(k).split(":")[1]);
    const same = a => Array.isArray(a) ? a.map(String).slice().sort().join(",") : null;
    if (same(u.mosqueIds) === mq.slice().sort().join(",") &&
        same(u.complexIds) === cx.slice().sort().join(",")) return;
    u.mosqueIds = mq; u.complexIds = cx;
    persistSet("users", u); n++;
  });
  showToast(n ? ("صُحّح نطاقُ " + toArabicDigits(n) + " حساباً — اطلب منهم إعادة تحميل الصفحة")
              : "لا حساب يحتاج تصحيحاً", n ? "success" : "info");
  return n;
};

window.fixMyScope = function () {
  const u = (STATE && STATE.user) || {};
  const role = String(u.role || "");
  if (role !== "admin" && role !== "owner") return false;
  if (Array.isArray(u.scopeIds) && u.scopeIds.length) return false;   /* حصرٌ مقصود */

  const rec = (Array.isArray(DB.users) ? DB.users : [])
    .find(x => String(x.uid || x.id) === String(u.uid || u.id));
  if (!rec) return false;
  if (!rec.mosqueId && !rec.complexId) return false;

  rec.mosqueId = ""; rec.complexId = "";
  u.mosqueId = ""; u.complexId = "";
  persistSet("users", rec);
  return true;
};

/* =========================================================================
   رفضُ الكتابات الجانبية — لا يُبتلع صامتاً (٤٣٢)
   -------------------------------------------------------------------------
   سجلُّ العمليات وفهرسُ المساجد العلنيّ وتعليمُ «مقروء» تُكتب مباشرةً لا عبر
   persistSet، وكان رفضُها يُبتلع بلا أثر: يظنّ المديرُ أنّ صفحةَ التسجيل
   حُدّثت أو أنّ العمليةَ وُثّقت ولم يحدث شيء. فيُسجَّل السببُ في الكونسول
   دائماً، ويُبلَّغ المستخدمُ مرّةً واحدةً في الجلسة لكلّ نوع — لا عند كلّ
   كتابة — لأنّ هذه الكتابات تتكرّر بلا طلبٍ منه.
   ========================================================================= */
const SIDE_FAIL_SEEN = {};
const SIDE_FAIL_MSG = {
  auditLog:    "لم يُوثَّق آخرُ تعديلٍ في سجلّ العمليات — رفضه الخادم",
  publicIndex: "لم تُحدَّث قائمةُ المساجد في صفحة التسجيل — رفضها الخادم",
  read:        "تعذّر تعليمُ الرسالة مقروءةً على الخادم — ستظهر غيرَ مقروءةٍ في جهازٍ آخر"
};
function sideFail(kind, err) {
  const code = (err && err.code) || String(err || "");
  console.warn("[" + kind + "] رُفضت الكتابة:", code, err);
  if (SIDE_FAIL_SEEN[kind]) return false;
  SIDE_FAIL_SEEN[kind] = 1;
  const off = code === "unavailable" || (typeof isOnline === "function" && !isOnline());
  try {
    if (typeof showToast === "function") {
      showToast((SIDE_FAIL_MSG[kind] || "تعذّرت كتابةٌ جانبية") +
                (off ? " (لا اتصال)" : code ? " [" + code + "]" : ""), "warn");
    }
  } catch (e) {}
  return false;
}
window.sideFail = sideFail;

function persistFail(where, coll, err, rec) {
  console.warn(where, coll, err);
  const denied = err && (err.code === "permission-denied" || err.code === "unauthenticated");

  /* كتابة في مجموعة إدارية من حساب غير إداري: لا تعني خطأً من المستخدم،
     ولا فائدة من إزعاجه برسالة عن شيء لم يطلبه. */
  const role = ((STATE && STATE.user) || {}).role || "";
  const adminColl = ["users", "userRequests", "dutyTypes", "certTemplates",
                     "examSupervisors", "examCommittees", "examRouting", "rewardRules"];
  if (denied && role && role !== "admin" && !isMgrRole(role)
      && adminColl.indexOf(coll) > -1) return;
  /* الرفض يُشخَّص لا يُعمَّم: «راجع الإدارة» لا تُعين المدير نفسه حين
     يُرفض. فيُقال أيّ سجلٍّ رُفض، ولمَ يُرجَّح، وما العمل. */
  if (denied) {
    const u = (STATE && STATE.user) || {};

    /* التفصيلُ التقنيّ في الكونسول لا في وجه المستخدم: أسماءُ المجموعات
       ومعرّفاتُ المجمّعات لا تعني له شيئاً، وإنما تعني من يصلح الخلل. */
    console.warn("رُفضت الكتابة:", {
      المجموعة: coll,
      الدور: u.role || "—",
      المجمّع: String(u.complexId || "—"),
      المسجد: String(u.mosqueId || "—"),
      الحلّ: "امسح complexId/mosqueId من مستندك في users، أو انشر القواعد " +
             "بأمر firebase deploy --only firestore:rules"
    });

    /* نطاقٌ عالقٌ في حساب المدير: يُصلَح مرّةً ثمّ يُطلَب إعادةُ الحفظ */
    if (!SCOPE_FIX_TRIED && coll !== "users") {
      SCOPE_FIX_TRIED = true;
      let fixed = false;
      try { fixed = window.fixMyScope(); } catch (e) { fixed = false; }
      if (fixed) {
        if (typeof showToast === "function") {
          showToast("كان في حسابك حصرٌ بمنشأةٍ من أثر مزامنةٍ قديمة — أُزيل الآن. " +
                    "اضغط «حفظ التعديلات» مرّةً أخرى.", "warn");
        }
        return;
      }
    }

    const why = denyReason(coll, u, rec);
    if (typeof showToast === "function") {
      showToast(why
        ? "تعذّر الحفظ — " + why
        : "تعذّر الحفظ — الخادم رفض الكتابة رغم أنّ صلاحيتك تبدو سليمة. " +
          "أرجحُ سببٍ أنّ قواعد Firestore لم تُنشر: نفّذ " +
          "firebase deploy --only firestore:rules",
        "warn");
    }
    return;
  }

  const msg = denied
    ? "لا تملك صلاحية حفظ هذا التغيير — راجع الإدارة"
    : "تعذّر الحفظ في قاعدة البيانات — تحقّق من الاتصال ثم أعِد المحاولة";
  if (typeof showToast === "function") showToast(msg, "warn");
}

/* =========================================================================
   العمل بلا إنترنت
   -------------------------------------------------------------------------
   المواصفات تسأل صراحةً: «ماذا يحدث عند انقطاع الإنترنت أو عدم وجوده؟»
   والإجابة قبل هذا كانت: يضيع العمل. persistSet تكتب في السحابة مباشرةً،
   فإن انقطع الاتصال فشلت الكتابة بصمت — معلّمٌ في مسجدٍ بلا شبكة يحضّر
   عشرين طالباً ويسمّع، ثم يجد سجلّه فارغاً.

   الحلّ: طابورٌ محليّ. ما يُكتب حين الانقطاع يُحفظ في المتصفح ويُرفَع حين
   يعود الاتصال — بترتيبه، ومع إعادة محاولةٍ لما فشل.

   والبيانات تبقى مقروءة لأن Firestore يخزّن نسخةً محليةً أصلاً؛ الناقص
   كان الكتابة لا القراءة.
   ========================================================================= */

/* =========================================================================
   تسجيل عامل الخدمة
   -------------------------------------------------------------------------
   بدونه لا تُفتح الصفحة أصلاً دون شبكة، ولو كانت البيانات محفوظة كلّها:
   المتصفح يطلب app.js من الشبكة فلا يجده فلا يعمل شيء.

   ويحتاج اتصالاً آمناً (https) — وهو متحقّق على Firebase Hosting. وفي
   التطوير المحلي لا يُسجَّل، فلا يعترض تحديثات الملفات.
   ========================================================================= */
(function registerSW() {
  if (typeof navigator === "undefined" || !navigator.serviceWorker) return;

  const host = location.hostname;
  const secure = location.protocol === "https:" || host === "localhost" || host === "127.0.0.1";
  if (!secure) return;

  /* المسار من الجذر: صفحات admin/ في مجلّدٍ فرعيّ فلا يصلح النسبيّ */
  const base = location.pathname.indexOf("/admin/") > -1 ? "../" : "./";

  window.addEventListener("load", function () {
    navigator.serviceWorker.register(base + "sw.js")
      .then(function (reg) {
        /* عاملٌ منتظرٌ من نشرةٍ سابقة: `updatefound` لا يُطلق له — فقد وقع
           قبل فتح الصفحة. والتطبيقُ المثبَّت يبقى على عاملٍ منتظرٍ أياماً
           فلا يُعرض لصاحبه شريط. فيُفتَّش عليه حالاً لا بالحدث وحده. */
        if (!reg) return;   /* التسجيلُ قد يعود بلا عامل (متصفّحٌ يحجبه) */
        if (reg.waiting && navigator.serviceWorker.controller) swUpdateBar(reg);

        /* نسخةٌ جديدة تنتظر: تُعرض دعوةٌ للتحديث بدل فرضه على عملٍ جارٍ */
        reg.addEventListener("updatefound", function () {
          const sw = reg.installing;
          if (!sw) return;
          sw.addEventListener("statechange", function () {
            if (sw.state === "installed" && navigator.serviceWorker.controller) {
              swUpdateBar(reg);
            }
          });
        });
      })
      .catch(function (e) { console.warn("تعذّر تسجيل عامل الخدمة:", e); });

    /* =====================================================================
       تبديلُ عامل الخدمة كان يُعيد التحميل من تلقائه
       ---------------------------------------------------------------------
       والحارسُ (reloaded) لا ينفع: يُصفَّر مع كلّ تحميلٍ جديد. فإن تبدّل
       العاملُ ثانيةً بعد الإعادة أعادها، ودارت الصفحةُ بلا توقّف — يفقد
       المستخدمُ ما كتبه في كلّ دورة.

       يُعرض شريطُ التحديث بدلاً منها: المستخدمُ يُحدّث متى فرغ.
       ===================================================================== */
    navigator.serviceWorker.addEventListener("controllerchange", function () {
      try {
        if (typeof swUpdateBar === "function") swUpdateBar();
        else if (typeof showToast === "function") {
          showToast("صدر تحديثٌ — أعد التحميل لتراه", "info");
        }
      } catch (e) {}
    });
  });
})();

function swUpdateBar(reg) {
  if (document.getElementById("swBar")) return;

  const el = document.createElement("div");
  el.id = "swBar";
  el.className = "sw-bar";
  el.innerHTML =
    '<span>تحديثٌ جديد للنظام جاهز</span>' +
    '<button type="button" id="swGo">تحديث الآن</button>' +
    '<button type="button" id="swLater">لاحقاً</button>';
  document.body.appendChild(el);

  document.getElementById("swGo").onclick = function () {
    if (reg && reg.waiting) reg.waiting.postMessage("skipWaiting");
    el.remove();
    /* كان يكتفي بالتبديل فتبقى الصفحةُ على الكود القديم حتى يُعيدها صاحبُها */
    if (typeof window.mirathHardUpdate === "function") window.mirathHardUpdate();
    else location.reload();
  };
  document.getElementById("swLater").onclick = function () { el.remove(); };
}

const OFFQ_KEY = "mirath_offq";
let OFFQ_BUSY = false;

/* =========================================================================
   الطابورُ لصاحبه (٤٣٠)
   -------------------------------------------------------------------------
   كان الطابورُ واحداً للجهاز كلّه ولا يُمسح عند الخروج: فإن كتب معلّمٌ بلا
   اتصالٍ ثمّ خرج ودخل غيرُه على الجهاز نفسِه، رُفعت تغييراتُ الأوّل بحساب
   الثاني وصلاحياته. فصار كلُّ قيدٍ يحمل uid كاتبِه، ولا يُرفع ولا يُعَدّ
   إلّا لصاحبه — ويبقى قيدُ غيره محفوظاً حتى يعود.
   والقيدُ القديم بلا uid (من قبل هذا الإصدار) يتبنّاه أوّلُ من يرفع.

   وكان الحدُّ ٥٠٠ يُسقط الأقدمَ بصمت؛ فرُفع، ويُنبَّه المستخدمُ إن بلغه.
   ========================================================================= */
const OFFQ_MAX = 2000;
const OFFQ_REJ_KEY = "mirath_offq_rejected";

function offqUid() {
  try {
    const a = typeof firebase !== "undefined" && firebase.auth ? firebase.auth().currentUser : null;
    if (a && a.uid) return String(a.uid);
  } catch (e) {}
  const u = (typeof STATE !== "undefined" && STATE && STATE.user) || {};
  return String(u.uid || "");
}

function offqRead() {
  try {
    const l = JSON.parse(localStorage.getItem(OFFQ_KEY) || "[]");
    return Array.isArray(l) ? l : [];
  }
  catch (e) { return []; }
}

/* قيودُ صاحب الجلسة — ومعها القديمُ بلا uid */
function offqIsMine(x, uid) {
  return !!x && (!x.uid || String(x.uid) === String(uid || ""));
}

let OFFQ_FULL_WARNED = false;
function offqWrite(list) {
  let l = list;
  if (l.length > OFFQ_MAX) {
    l = l.slice(-OFFQ_MAX);
    if (!OFFQ_FULL_WARNED) {
      OFFQ_FULL_WARNED = true;
      try { showToast("الطابورُ المحليّ بلغ حدَّه — صِل بالإنترنت ليُرفع ما حُفظ قبل أن يضيع الأقدم", "warn"); } catch (e) {}
    }
  }
  try { localStorage.setItem(OFFQ_KEY, JSON.stringify(l)); return true; }
  catch (e) {
    /* امتلأ التخزين: لا يُخفى — فالمستخدمُ يظنّ عمله محفوظاً */
    try { showToast("تعذّر حفظ التغيير على الجهاز — المساحةُ ممتلئة. صِل بالإنترنت ثمّ أعد الحفظ", "warn"); } catch (e2) {}
    return false;
  }
}

function offqCount() {
  const uid = offqUid();
  return offqRead().filter(x => offqIsMine(x, uid)).length;
}

/* ما رفضه الخادمُ رفضاً دائماً يُحفظ للاطّلاع لا لإعادة المحاولة */
function offqReject(items) {
  if (!items.length) return;
  try {
    const old = JSON.parse(localStorage.getItem(OFFQ_REJ_KEY) || "[]");
    const l = (Array.isArray(old) ? old : []).concat(items.map(x => ({
      coll: x.coll, id: x.id, op: x.op, uid: x.uid || "", ts: x.ts, at: Date.now(), code: x._code || ""
    })));
    localStorage.setItem(OFFQ_REJ_KEY, JSON.stringify(l.slice(-100)));
  } catch (e) {}
}
window.offqRejected = function () {
  try { return JSON.parse(localStorage.getItem(OFFQ_REJ_KEY) || "[]"); } catch (e) { return []; }
};

/* هل نحن متصلون؟ navigator.onLine يكذب أحياناً، فيُعتمد مع نتيجة الكتابة */
function isOnline() {
  return typeof navigator === "undefined" || navigator.onLine !== false;
}

/* يُنادى حين تفشل كتابة أو ينقطع الاتصال */
function offqPush(op, coll, obj) {
  const list = offqRead();
  const uid = offqUid();

  /* آخر عمليةٍ على المستند نفسه تكفي: الحالة الأخيرة هي المرادة —
     لكاتبها نفسِه، فلا يمحو قيدُ مستخدمٍ قيدَ غيره */
  const id = String((obj && obj.id) || obj || "");
  const i = list.findIndex(x => x.coll === coll && String(x.id) === id && offqIsMine(x, uid));
  /* قيدٌ سابقٌ معلَّقٌ للمستند نفسِه يُدمج فيه الجديد لا يُستبدل به: حفظُ
     حقلٍ واحد (persistPatch) لا يمحو تعديلاً كاملاً لم يُرفع بعد (٤٣٠) */
  const prevSet = i > -1 && list[i].op === "set" && op === "set" ? list[i].data : null;
  const rec = { op, coll, id, data: op === "set" ? (prevSet ? Object.assign({}, prevSet, obj) : obj) : null,
                ts: Date.now(), uid };

  if (i > -1) list[i] = rec; else list.push(rec);
  offqWrite(list);

  try { offqBadge(); } catch (e) {}
  return true;
}

/* الرفع — بالترتيب، وما فشل يبقى للمحاولة التالية */
window.offqFlush = function () {
  if (OFFQ_BUSY) return Promise.resolve(0);
  const list = offqRead();
  if (!list.length) return Promise.resolve(0);

  const db = typeof FDB === "function" ? FDB() : null;
  if (!db || !isOnline()) return Promise.resolve(0);

  const uid = offqUid();
  if (!uid) return Promise.resolve(0);          /* لا يُرفع شيءٌ قبل معرفة صاحب الجلسة */
  const mine = list.filter(x => offqIsMine(x, uid));
  if (!mine.length) return Promise.resolve(0);

  OFFQ_BUSY = true;
  const left = [];
  const rejected = [];
  let done = 0;

  /* الرفضُ الدائم لا يُعاد أبداً: كان يبقى في الطابور يُحاوَل بلا نهاية */
  const PERMANENT = ["permission-denied", "invalid-argument", "failed-precondition", "not-found"];

  const step = i => {
    if (i >= mine.length) {
      /* يُعاد بناءُ الطابور من الحالة الراهنة: ما أُضيف أثناء الرفع لا يضيع،
         وقيودُ المستخدمين الآخرين تبقى كما هي */
      const handled = mine.filter(x => left.indexOf(x) === -1);
      const same = (a, b) => a.coll === b.coll && String(a.id) === String(b.id) && a.ts === b.ts;
      const now = offqRead()
        .filter(x => !(offqIsMine(x, uid) && handled.some(h => same(h, x))))
        .map(x => (!x.uid ? Object.assign({}, x, { uid }) : x));
      offqWrite(now);
      offqReject(rejected);
      OFFQ_BUSY = false;
      try { offqBadge(); } catch (e) {}
      if (done) {
        showToast("رُفع " + toArabicDigits(done) + " تغييراً كان معلَّقاً", "success");
        mount();
      }
      if (rejected.length) {
        showToast("رفض الخادمُ " + toArabicDigits(rejected.length) +
                  " تغييراً محفوظاً على الجهاز (صلاحيةٌ أو بياناتٌ غير مقبولة) — أُزيلت من الطابور", "warn");
      }
      return Promise.resolve(done);
    }

    const x = mine[i];
    const ref = db.collection(x.coll).doc(String(x.id));
    /* الدمجُ لا الاستبدال: النسخةُ المحفوظةُ قديمة، والاستبدالُ بها يمحو ما
       أضافه غيرُك إلى المستند في أثناء الانقطاع من حقولٍ لم تلمسها. */
    let body = x.data;
    if (body && body.__patch) { body = Object.assign({}, body); delete body.__patch; delete body.id; }
    const p = x.op === "delete" ? ref.delete() : ref.set(body, { merge: true });

    return p.then(() => { done++; })
            .catch(err => {
              const code = String((err && err.code) || "").replace(/^firestore\//, "");
              if (PERMANENT.indexOf(code) > -1) { x._code = code; rejected.push(x); }
              else left.push(x);              /* انقطاعٌ أو مهلة: يبقى للمحاولة التالية */
            })
            .then(() => step(i + 1));
  };

  return step(0);
};

/* =========================================================================
   طابور الرفع — في الجرس لا على الشاشة
   -------------------------------------------------------------------------
   كانت شارةٌ عائمةٌ أسفل الشاشة تقول «٢٤ تغيير بانتظار الرفع»، تغطّي ما
   تحتها وتلازم كلَّ شاشة.

   صارت تنبيهاً في الجرس: يُعرف بالنظر إليه، ويُرفع بالضغط عليه. ولا يُنسى
   لأنه يبقى ما بقي الطابور — بخلاف رسالةٍ عابرة.
   ========================================================================= */
function offqBadge() {
  /* الشارةُ القديمة تُنزع إن كانت من جلسةٍ سابقة */
  const old = document.getElementById("offqBadge");
  if (old) old.remove();

  const n = offqCount();

  if (!n) {
    /* فرغ الطابور: يُمحى تنبيهُه فلا يبقى خبرٌ مضى */
    try {
      if (Array.isArray(DB.notifications)) {
        const i = DB.notifications.findIndex(x => x && x.key === "offq");
        if (i > -1) {
          /* تنبيهُ الطابور في الذاكرة وحدَها — لم يُكتب على الخادم قطّ، فلا يُحذف
             منه (٤٤١): كان حذفُه يُرسَل فيردّه الخادمُ للطالب ويُسجَّل حذفاً */
          DB.notifications.splice(i, 1);
        }
      }
    } catch (e) {}
    return;
  }

  /* تنبيهٌ واحدٌ يُحدَّث لا تنبيهٌ لكلّ تغيير */
  try {
    if (!Array.isArray(DB.notifications)) DB.notifications = [];
    const on = isOnline();
    const u = (STATE && STATE.user) || {};

    const text = on
      ? toArabicDigits(n) + " تغييراً محفوظاً محلياً — اضغط لرفعها الآن"
      : toArabicDigits(n) + " تغييراً محفوظاً محلياً — تُرفع تلقائياً عند عودة الاتصال";

    const found = DB.notifications.find(x => x && x.key === "offq");
    if (found) {
      found.text = text; found.ts = Date.now(); found.read = false;
    } else {
      DB.notifications.push({
        id: "offq" + Date.now(),
        key: "offq",
        toUid: String(u.uid || u.id || ""),
        title: "تغييراتٌ لم تُرفع بعد",
        text, type: "warn", label: "المزامنة",
        action: "offq",              /* الضغطُ يرفعها */
        ts: Date.now(), read: false
      });
    }

    if (typeof updateNotifBadge === "function") updateNotifBadge();
  } catch (e) {}
}

/* المراقبة: عودة الاتصال ترفع الطابور، وكل رسمٍ يحدّث الشارة */
(function offqWatch() {
  if (typeof window === "undefined") return;

  window.addEventListener("online", function () {
    showToast("عاد الاتصال — يُرفع ما حُفظ محلياً", "info");
    setTimeout(function () { window.offqFlush(); }, 800);
  });

  window.addEventListener("offline", function () {
    showToast("انقطع الاتصال — يُحفظ عملك محلياً ويُرفع عند عودته", "warn");
    try { offqBadge(); } catch (e) {}
  });

  /* محاولةٌ دوريةٌ: قد يعود الاتصال دون أن يُطلق الحدث */
  setInterval(function () {
    if (offqCount() && isOnline()) window.offqFlush();
  }, 45000);
})();

/* =========================================================================
   حرمة الدورة المؤرشفة
   -------------------------------------------------------------------------
   المواصفات: «الدورات المؤرشفة: دورات مغلقة للقراءة فقط. لا يمكن التعديل
   عليها، ولكن تستطيع الإدارة الرجوع إليها لطباعة شهادة قديمة أو مراجعة
   حضور طالب سابقاً».

   وكانت الأرشفة وسماً يُعرض ولا يحرس: من فتح سجلاً قديماً عدّله، وشهادةٌ
   طُبعت من دورةٍ مؤرشفة قد تخالف ما فيها اليوم. فالسجل الذي يُعدَّل بعد
   إغلاقه ليس سجلّاً.

   المنع هنا في نقطة الحفظ نفسها — لا في الأزرار — لأن الأزرار تُخفى
   والدوال تُنادى.
   ========================================================================= */

/* المجموعات التي تخصّ دورةً بعينها. غيرها (المستخدمون، الإعدادات،
   المساجد) مستمرٌّ عبر الدورات فلا يُحرس بها. */
const TERM_BOUND = [
  "attendance", "recitations", "assignments", "mushafMarks",
  "exams", "pointsLog", "storeOrders", "workflow", "procLog", "sysAlerts"
];

/* هل هذا السجل يقع في دورةٍ مؤرشفة؟ */
function inArchivedTerm(coll, obj) {
  if (!obj || TERM_BOUND.indexOf(coll) === -1) return null;

  const tid = obj.termId || (typeof termOfDate === "function" ? termOfDate(obj.date) : "");
  if (!tid) return null;                     /* بلا نسبة: لا يُحرس */

  const t = (cur("terms") || []).find(x => String(x.id) === String(tid));
  if (!t || t.archived !== true) return null;

  return t;
}

/* الحارس — يُنادى قبل كلّ حفظٍ وحذف */
/* =========================================================================
   حرمة الجلسة المعتمدة
   -------------------------------------------------------------------------
   كان القفل في attDraftSet وحدها — أي في المسوّدة لا في الحفظ. فمن استدعى
   الحفظ من موضعٍ آخر كتب في جلسةٍ معتمدة. والتسميع لم يكن مقفولاً أصلاً،
   فتصير لقطة الاعتماد كاذبة: تقول «سُمّع لخمسة» وقد صاروا ثمانيةً بعدها.

   الحرمة هنا في نقطة الحفظ نفسها — كحرمة الدورة المؤرشفة سواءً بسواء.
   ========================================================================= */
const SESSION_BOUND = ["attendance", "recitations", "assignments", "mushafMarks"];

function guardSession(coll, obj, silent) {
  if (!obj || SESSION_BOUND.indexOf(coll) === -1) return false;

  const d = String(obj.date || "");
  if (!d) return false;

  let cid = String(obj.circleId || "");
  if (!cid) {
    /* بلا حلقة: تُلتمس من الطالب — سجلٌّ قديمٌ قد لا يحملها */
    const st = (cur("students") || []).find(x => String(x.id) === String(obj.studentId));
    cid = st ? String(st.circleId || "") : "";
    if (!cid) return false;
  }

  const sess = typeof sessionOf === "function" ? sessionOf(d, cid) : null;
  if (!sess) return false;

  /* الإدارة تعدّل بعد الاعتماد — وتعديلها يُرصد في سجل العمليات */
  if (typeof canReopenSession === "function" && canReopenSession()) return false;

  if (!silent) {
    showToast("جلسة «" + (sess.circle || "") + "» معتمدة — اطلب فتحها من مشرفك", "warn");
  }
  return true;
}

/* ما يُمنع حفظه حين تُعرض فترةٌ غيرُ فترة العمل */
const TERM_VIEW_LOCK = TERM_BOUND.concat(["students", "circles", "plans", "teachers", "planRules"]);

function guardArchived(coll, obj, silent) {
  if (TERM_VIEW_LOCK.indexOf(coll) > -1 && typeof viewReadOnly === "function" && viewReadOnly() &&
      !(isTopAdmin() && DB.__archiveOverride === true)) {
    /* تنبيهٌ واحد كل بضع ثوانٍ: الفحوص الدورية تحاول الكتابة كذلك فتُردّ صامتة */
    if (!silent && Date.now() - (guardArchived._ro || 0) > 4000) {
      guardArchived._ro = Date.now();
      showToast("تعرض فترةً للقراءة فقط — ارجع إلى الفترة النشطة لحفظ التعديل", "warn");
    }
    return true;
  }

  const t = inArchivedTerm(coll, obj);
  if (!t) return false;

  /* المالك يفتحها عند الضرورة: تصحيحُ خطأٍ في شهادةٍ صدرت قد يلزم، ولا
     يُترك النظام بلا مخرج. وكلّ فتحةٍ تُرصد في سجل العمليات. */
  const r = ((STATE && STATE.user) || {}).role || "";
  if (isTopAdmin() && DB.__archiveOverride === true) return false;

  if (!silent) {
    showToast("دورة «" + (t.name || "") + "» مؤرشفة — سجلّاتها للقراءة فقط", "warn");
  }
  return true;
}

/* فتحٌ مؤقّت للمالك — لجلسةٍ واحدة لا دائماً */
window.archiveOverride = function (on) {
  if (!isTopAdmin()) { showToast("فتح الدورات المؤرشفة للإدارة العليا", "warn"); return; }

  if (on) {
    openModal("فتح الدورات المؤرشفة", "",
      noteCard(`ستصير سجلّات الدورات المؤرشفة قابلةً للتعديل في هذه الجلسة وحدها.
        <br>كلّ تعديلٍ يُرصد في سجل العمليات باسمك.
        <br><strong>يُغلق تلقائياً عند إعادة تحميل الصفحة.</strong>`),
      `<button class="btn btn-danger" onclick="window.archiveOverrideDo(true)">فتح مؤقّت</button>
       <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
    return;
  }
  window.archiveOverrideDo(false);
};

window.archiveOverrideDo = function (on) {
  if (!isTopAdmin()) return;
  DB.__archiveOverride = !!on;

  /* فتح المؤرشف يُرصد: من فتحه ومتى — فالتعديل عليه يُقرأ في سياقه */
  if (on) {
    try {
      const me = (STATE && STATE.user) || {};
      const rec = {
        id: "lg" + Date.now() + "-arc",
        ts: Date.now(), byUid: String(((STATE && STATE.user) || {}).uid || ""), act: "update", coll: "terms", collAr: "الفترات",
        docId: "", subject: "",
        by: me.name || me.email || "—", role: logRoleAr(me.role), changes: [],
        text: "فتح " + (logRoleAr(me.role) || "") + " (" + (me.name || "—") +
              ") الدوراتِ المؤرشفة للتعديل"
      };
      if (!Array.isArray(DB.auditLog)) DB.auditLog = [];
      DB.auditLog.push(rec);
      const db = typeof FDB === "function" ? FDB() : null;
      if (db) db.collection("auditLog").doc(rec.id).set(rec).catch(e => sideFail("auditLog", e));
    } catch (e) {}
  }
  closeModal();
  showToast(on ? "فُتحت الدورات المؤرشفة لهذه الجلسة" : "أُغلقت الدورات المؤرشفة", on ? "warn" : "success");
  mount();
};

/* =========================================================================
   بصمُ النطاق على كلّ كتابة
   -------------------------------------------------------------------------
   قواعدُ Firestore صارت تشترط أن يحمل المستندُ نطاقَ كاتبه: مسجدَه أو
   مجمّعَه. و persistSet كانت تكتب ما يُعطى لها كما هو، فمستندٌ بلا نطاقٍ
   يُرفض على الخادم — والمستخدمُ يرى «حُفظ» ولا شيءَ يُحفظ.

   يُبصَم النطاقُ هنا مرّةً واحدة: أضيقُ نطاقٍ للكاتب، ولا يُداس على نطاقٍ
   مكتوبٍ سلفاً — فنقلُ مستندٍ من مسجدٍ إلى آخر عملٌ مقصودٌ لا أثرٌ جانبيّ.
   ========================================================================= */
const SCOPE_FREE = ["settings", "users", "auditLog", "sysAlerts", "msgOutbox"];
/* =========================================================================
   المنشأةُ لا تُبصَم بنطاق من كتبها
   -------------------------------------------------------------------------
   كان المسجدُ والمجمّعُ يمرّان على البصم كأيّ مستند: فمسجدٌ بلا مجمّع
   (وهي الحالُ الطبيعيةُ للمسجد المستقلّ) يُكتب فيه complexId من مجمّعِ
   من حفظه — فينتقل المسجدُ إلى مجمّعٍ لم ينقله إليه أحد. ومن حفظه من
   جهازٍ آخر بحسابٍ آخر نقله إلى مجمّعٍ ثالث. وهذا سببُ «المساجد تتغير
   من مجمّع إلى آخر وحدها».
   موضعُ المنشأة في الشجرة يُحدَّد بالنقل المقصود وحدَه (mvcApply)، ولا
   يُستنتج من حافظها.
   ========================================================================= */
const SCOPE_SELF = ["mosques", "complexes"];

/* دورُ صاحب الجلسة — كان الكودُ ينادي myRole() وهي معرّفةٌ في auth.js
   و shell.js لا في app.js، فترمي ReferenceError عند أوّل استدعاء. */
function myRoleNow() {
  return String(((STATE && STATE.user) || {}).role || "");
}

/* =========================================================================
   مسجدُ السجلّ من حلقته ثمّ طالبه — لكلّ كاتب (٤٤٩)
   -------------------------------------------------------------------------
   منذ ٤٤٧ يقرأ المعلّمُ ومديرُ المسجد في هذه المجموعات ما يحمل mosqueId
   مسجدهم وحدَه. وكان الختمُ لمدير المسجد وحدَه: فالواجبُ الذي يولّده
   المعلّمُ والحضورُ الذي يسجّله المديرُ أو مديرُ المجمّع يُكتبان بلا مسجد،
   فلا يراهما المعلّم — بل يولّد المعلّمُ الواجبَ نفسَه من جديد فيكتب
   «pending» فوق «done» (فحصُ القبول ACC-18 و ACC-19).
   فصار المسجدُ يُؤخذ من حلقة السجلّ ثمّ من طالبه، لا من الكاتب — فلا
   يُختم سجلُّ طالبٍ بمسجدٍ غير مسجده. والمكتوبُ سلفاً لا يُداس.
   ========================================================================= */
const SCOPE_MQ_COLLS = ["students", "teachers", "plans", "assignments", "attendance", "recitations",
                        "mushafMarks", "exams", "delays", "pointsLog", "storeOrders"];
function scopeMosqueOf(data) {
  const find = (c, id) => (Array.isArray(DB[c]) ? DB[c] : [])
    .find(x => x && String(x.id) === String(id));
  if (data.circleId != null && data.circleId !== "") {
    const c = find("circles", data.circleId);
    if (c && c.mosqueId) return String(c.mosqueId);
  }
  if (data.studentId != null && data.studentId !== "") {
    const s = find("students", data.studentId);
    if (s && s.mosqueId) return String(s.mosqueId);
  }
  return "";
}

function scopeStamp(coll, data) {
  if (!data || SCOPE_FREE.indexOf(String(coll)) > -1) return data;
  if (SCOPE_SELF.indexOf(String(coll)) > -1) return data;

  const u = (STATE && STATE.user) || {};
  if (!data.mosqueId && SCOPE_MQ_COLLS.indexOf(String(coll)) > -1) {
    const m0 = scopeMosqueOf(data);
    if (m0) {
      data.mosqueId = m0;
      if (!data.complexId) {
        const m = (Array.isArray(DB.mosques) ? DB.mosques : []).find(x => x && String(x.id) === m0);
        if (m && m.complexId) data.complexId = String(m.complexId);
      }
    }
  }
  if (isTopAdmin(u)) return data;              /* المالكُ والمديرُ بلا نطاق */

  const mq = String(u.mosqueId || "");
  const cx = String(u.complexId || "");

  /* ولا حلقةَ ولا طالبَ يدلّان: من يعمل في مسجدٍ يكتب لمسجده (٤٤٩) */
  if (!data.mosqueId && mq && (isMosqueMgr(u.role) ||
      (u.role === "teacher" && SCOPE_MQ_COLLS.indexOf(String(coll)) > -1))) data.mosqueId = mq;
  if (!data.complexId) {
    if (cx) data.complexId = cx;
    else if (data.mosqueId) {
      const m = (Array.isArray(DB.mosques) ? DB.mosques : [])
        .find(x => x && String(x.id) === String(data.mosqueId));
      if (m && m.complexId) data.complexId = String(m.complexId);
    }
  }
  return data;
}

/* =========================================================================
   حارسُ الارتباطات — «بياناتُ الارتباط لا تتغيّر تلقائياً»
   -------------------------------------------------------------------------
   المواصفات: «الطالب أحمد ← مسجد النور ← حلقة الأشبال ← برنامج الحفظ ←
   الخطة الحالية. يجب أن تظل هذه البيانات كما هي… ولا تتغيّر إلا بواسطة
   مسؤولٍ مخوَّل + إجراءٍ واضح + تأكيد + صلاحيةِ Firestore».

   الدواءُ هنا في بوّابة الكتابة الوحيدة (persistSet) لا في الأزرار: الأزرارُ
   تُخفى والدوالُّ تُنادى، وقد كان ثلاثةٌ منها تكتب أثناء القراءة. فأيُّ
   كتابةٍ تمسّ حقلَ ارتباطٍ خارجَ إجراءٍ صريحٍ من مستخدم تُردّ إلى قيمتها
   السابقة قبل أن تغادر الجهاز — وبقيّةُ الحقول في الكتابة نفسِها تمضي،
   فلا يضيع عملٌ مشروع.

   وما يميّز الإجراءَ الصريحَ من التلقائيّ:
     • لمسةُ مستخدمٍ حديثةٌ (نقرة أو إرسالُ نموذج) — تُختم في مرحلة الالتقاط.
     • أو إجراءٌ معلَّمٌ بـ linkChange(fn) — للنقل الذي يمتدّ بعد النقرة.
     • والمزامناتُ التلقائية تُعلن نفسَها بـ linkAuto(fn) فتُمنع ولو جرت
       عقب نقرةٍ مباشرة — فهي ليست من النقرة في شيء.
   ========================================================================= */
const LINK_FIELDS = ["mosqueId", "complexId", "circleId", "programId",
                     "planId", "levelId", "studentId", "teacherId"];
const LINK_COLLS  = { students: 1, teachers: 1, plans: 1, circles: 1, users: 1 };
/* والطالبُ يحمل برنامجَه ومستواه اسماً لا معرّفاً في سجلّاتٍ كثيرة — فالاسمُ
   عنده هو الارتباطُ نفسُه، ويُحرس كما تُحرس المعرّفات (٤٣٠). */
const LINK_TEXT_FIELDS = { students: ["program", "level"] };

let LINK_ACT = 0;      /* وقتُ آخر لمسةٍ من المستخدم */
let LINK_OPEN = 0;     /* إجراءُ ارتباطٍ صريحٌ مفتوح */
let LINK_AUTO = 0;     /* مزامنةٌ تلقائيةٌ جارية */

/* يُحيط الإجراءَ الصريح: نقلُ طالبٍ أو حلقةٍ أو تغييرُ برنامجٍ أو مستوى */
window.linkChange = function (fn) {
  LINK_OPEN++;
  try { return fn(); } finally { LINK_OPEN--; }
};
/* يُحيط كلَّ مزامنةٍ تعمل من تلقائها — فلا تمسّ ارتباطاً أبداً */
function linkAuto(fn) {
  LINK_AUTO++;
  try { return fn(); } finally { LINK_AUTO--; }
}
window.linkAuto = linkAuto;

function linkAllowed() {
  if (LINK_AUTO > 0) return false;
  if (LINK_OPEN > 0) return true;
  return Date.now() - LINK_ACT < 8000;
}

/* ختمُ اللمسة في مرحلة الالتقاط: لا يفوتها شيءٌ ولو أوقف المعالِجُ الحدث */
if (typeof document !== "undefined" && document.addEventListener) {
  ["click", "submit", "change", "keydown"].forEach(function (ev) {
    document.addEventListener(ev, function () { LINK_ACT = Date.now(); }, true);
  });
}

/* ما مُنع من التغيير في هذه الجلسة — يُعرض لصاحب النظام عند الطلب */
const LINK_BLOCKED = [];
window.linkBlocked = function () { return LINK_BLOCKED.slice(); };

function linkGuard(coll, obj) {
  if (!LINK_COLLS[coll] || !obj || obj.id == null) return 0;
  if (linkAllowed()) return 0;
  const before = typeof auditShadow === "function" ? auditShadow(coll, obj.id) : null;
  if (!before) return 0;          /* سجلٌّ جديدٌ لا ارتباطَ سابقَ له يُحرس */

  let n = 0;
  LINK_FIELDS.concat(LINK_TEXT_FIELDS[coll] || []).forEach(function (k) {
    const a = before[k], b = obj[k];
    if (a === undefined && b === undefined) return;
    const sa = String(a == null ? "" : a), sb = String(b == null ? "" : b);
    if (sa === sb) return;
    /* يُردّ إلى ما كان — ولا يُحذف الحقل، فالكتابةُ set تمحو الغائب */
    if (a === undefined) delete obj[k]; else obj[k] = a;
    n++;
    LINK_BLOCKED.push({ ts: Date.now(), coll: coll, id: String(obj.id),
                        field: k, from: sa, to: sb });
    if (LINK_BLOCKED.length > 200) LINK_BLOCKED.shift();
  });
  if (n) {
    console.warn("[حارس الارتباط] مُنع تغييرٌ تلقائيٌّ في " + coll + "/" + obj.id +
                 " — " + n + " حقلاً. اطبع linkBlocked() لتفصيله.");
  }
  return n;
}

function persistSet(coll, obj) {
  if (CUR_MEMO) CUR_MEMO = {};   /* الحفظُ يُبطل ما حُفظ من قراءات الرسم (٤٢٥) */
  const db = FDB(); if (!db || obj == null) return Promise.resolve(false);

  /* حفظُ مدير المسجد للإعدادات يُكتب في طبقة مسجده لا في العامّ */
  if (coll === "settings" && typeof cfgRouteSave === "function") {
    const routed = cfgRouteSave(obj);
    if (routed) return routed;
  }

  /* الدورة المؤرشفة لا تُكتب: المنع هنا لا في الأزرار — الأزرار تُخفى
     والدوال تُنادى. */
  if (typeof guardArchived === "function" && guardArchived(coll, obj)) {
    return Promise.resolve(false);
  }

  /* والجلسة المعتمدة كذلك: يُغلق يومها فلا يُبدَّل بعد توثيقه */
  if (typeof guardSession === "function" && guardSession(coll, obj)) {
    return Promise.resolve(false);
  }

  /* الرصد: أكثر التعديلات تُغيّر السجل في مكانه ثم تُنادي persistSet،
     فالقديم قد ضاع من الذاكرة. لذلك يُحفظ «ظلّ» لآخر حالة كُتبت، وتُقارن
     به. بدونه يقول السجل «عُدّل» ولا يقول ماذا تغيّر — وهو لبّ الرقابة. */
  /* الحارسُ قبل الرصد: يُسجَّل ما استقرّ عليه السجلّ لا ما طُلب له */
  try { linkGuard(coll, obj); } catch (e) {}

  try {
    if (typeof auditWrite === "function") {
      const before = auditShadow(coll, obj.id);
      auditWrite(coll, obj, before ? "update" : "create", before);
      auditKeep(coll, obj);
    }
  } catch (e) {}

  /* وسمُ الفترة التي تبدأ خالية: ما يُسجَّل وهي فترةُ العمل يُنسب إليها،
     وإلّا كُتب بلا وسمٍ فلم يظهر فيها — وهي لا تعرض إلا الموسوم بها.
     والسجلُّ غيرُ الموسوم الواصلُ إلى هنا جديدٌ بالضرورة: القديمُ غيرُ
     الموسوم لا يُعرض في الفترة الخالية فلا سبيل إلى تعديله منها. */
  try {
    if (typeof TERM_FRESH_COLLS !== "undefined" &&
        TERM_FRESH_COLLS.indexOf(coll) > -1 && !obj.termId) {
      const _t = typeof activeTerm === "function" ? activeTerm() : null;
      if (typeof termIsFresh === "function" && termIsFresh(_t)) obj.termId = String(_t.id);
    }
  } catch (e) {}

  const data = scopeStamp(coll, Object.assign({}, obj));
  /* ما ختمه scopeStamp على المكتوب يُختم على السجلّ في الذاكرة كذلك (٤٣٢):
     كان الخادمُ يحمل المسجدَ والمجمّعَ والذاكرةُ فارغةً منهما، فيحجب حصرُ
     النطاق السجلَّ عن منشئه حتى يُعاد التحميل (طلبُ القبول والجائزة «للجميع») */
  let _stamped = 0;
  ["mosqueId", "complexId"].forEach(k => {
    if ((obj[k] == null || obj[k] === "") && data[k] != null && data[k] !== "") { obj[k] = data[k]; _stamped++; }
  });
  /* والظلُّ يتبعه، فلا يحسب حارسُ الارتباط الختمَ تغييراً في الحفظ التالي */
  if (_stamped) { try { if (typeof auditKeep === "function") auditKeep(coll, obj); } catch (e) {} }
  if (data._o == null) data._o = Date.now();
  /* امتداداتُ الخطة (الحالةُ الصحية · التجميدُ وسببُه · الطلبات) تُنزع من
     السجلّ عند التحميل إلى PLAN_EXTRA، والكتابةُ هنا set بلا دمج — فكان
     كلُّ حفظٍ للخطة من غير persistPlan يمحوها من الخادم بصمت (٤٣٠).
     تُعاد إلى الكتابة ما دام السجلُّ لا يحمل ext بنفسه. */
  if (coll === "plans" && !Object.prototype.hasOwnProperty.call(obj, "ext") &&
      typeof PLAN_EXTRA !== "undefined" && PLAN_EXTRA && PLAN_EXTRA[obj.id] != null) {
    data.ext = PLAN_EXTRA[obj.id];
  }
  /* تُرجِع وعداً ليتمكّن النداء من انتظار نتيجة الكتابة قبل إعلان النجاح.
     كانت الكتابة تُطلق ويُعلَن الحفظ فوراً، فيرى المعلّم «حُفظ» ولو فشلت. */
  /* بلا اتصال: يُحفظ محلياً ويُرفع حين يعود — لا يُترك المستخدم يكتب في
     الفراغ. والنجاح يُعلَن لأن العمل حُفظ فعلاً، وإن لم يبلغ السحابة بعد. */
  if (!isOnline()) { offqPush("set", coll, data); return Promise.resolve(true); }

  return db.collection(coll).doc(String(obj.id)).set(data)
    .then(() => true)
    .catch(err => {
      persistFail("persistSet", coll, err, data);
      /* رفضُ القواعد ليس انقطاعاً: طابورُ الرفع يعيد المحاولة أبداً بلا
         طائل، والمستخدم يُبلَّغ بالنجاح. يُعاد false ليعلم النداء. */
      const denied = err && (err.code === "permission-denied" || err.code === "unauthenticated");
      if (denied) return false;
      /* الفشل قد يكون انقطاعاً لا رفضاً: يُحفظ ويُعاد رفعه */
      offqPush("set", coll, data);
      return true;
    });
}
function persistPlan(id) {
  const db = FDB(); if (!db) return;
  const p = DB.plans.find(x => x.id == id); if (!p) return;
  if (typeof guardArchived === "function" && guardArchived("plans", p)) return;
  const data = Object.assign({}, p, { ext: PLAN_EXTRA[id] || null });
  if (data._o == null) data._o = Date.now();
  db.collection("plans").doc(String(id)).set(data)
    .catch(err => persistFail("persistPlan", "plans", err));
}
/* ما يرتبط بالسجلّ المحذوف ويبقى بعده — عدٌّ للعرض فقط، لا يُكتب شيء (٤٣٠) */
const DEL_LINKED = [["plans", "خطة"], ["assignments", "واجب"], ["attendance", "سجل حضور"],
                    ["recitations", "تسميع"], ["students", "طالب"]];
function delLinkedCounts(key, id) {
  const out = [];
  DEL_LINKED.forEach(([cl, h]) => {
    if (key === "studentId" && cl === "students") return;
    const n = (DB[cl] || []).filter(r => r && r[key] != null && r[key] !== "" &&
                                         String(r[key]) === String(id)).length;
    if (n) out.push(toArabicDigits(n) + " " + h);
  });
  return out;
}
function delLinkedNote(links, accounts) {
  const bits = links.slice();
  if (accounts) bits.push("حساب الدخول");
  if (!bits.length) return "";
  return noteCard("تبقى بعد الحذف ولا تُحذف معه: <strong>" + bits.join("، ") + "</strong>" +
    (accounts ? " — ويُحذف الحساب من صفحة المستخدمين." : ".") +
    " إن أردتَ حفظَ كلِّ شيء فأوقِفه بدل حذفه.");
}

/* =========================================================================
   حفظُ حقولٍ بعينها (٤٣٠)
   -------------------------------------------------------------------------
   persistSet يكتب السجلَّ كلَّه ويختمه بالنطاق والفترة. وهذا صوابٌ للإدارة،
   لكنّ الطالبَ ووليَّه والمعلّمَ لا تجيز لهم القواعدُ إلّا حقولاً بعينها في
   سجلّاتهم (البريدُ والصورةُ وشروطُ الشارات) — فأيُّ حقلٍ يُضاف معها، ولو
   ختمُ نطاقٍ تلقائيّ، يُسقط الكتابةَ كلَّها.
   فيُكتب هنا ما سُمّي من الحقول وحدَه، دمجاً لا استبدالاً، ويُرصد في السجلّ
   كما يُرصد غيرُه، ويُحفظ محلياً إن انقطع الاتصال.
   ========================================================================= */
function persistPatch(coll, obj, keys) {
  if (CUR_MEMO) CUR_MEMO = {};
  const db = FDB(); if (!db || !obj || obj.id == null) return Promise.resolve(false);
  if (typeof guardArchived === "function" && guardArchived(coll, obj)) return Promise.resolve(false);

  /* حارسُ الارتباط هنا كما في persistSet (٤٤٠): كانت الكتابةُ بحقولٍ بعينها
     تتجاوزه، فحقلُ ارتباطٍ يُمرَّر هنا يُكتب بلا لمسة. ما يردّه الحارس يُعاد
     إلى قيمته في obj قبل بناء الرقعة. */
  try { linkGuard(coll, obj); } catch (e) {}

  const patch = {};
  (keys || []).forEach(k => { patch[k] = obj[k] === undefined ? null : obj[k]; });

  try {
    if (typeof auditWrite === "function") {
      const before = auditShadow(coll, obj.id);
      auditWrite(coll, obj, "update", before);
      auditKeep(coll, obj);
    }
  } catch (e) {}

  /* __patch: حقولٌ بعينها — يُرفع دمجاً بلا id، فقواعدُ الحقول المحصورة
     (البريد والصورة · النقاط) لا تراه حقلاً زائداً فتردّه (٤٣٥) */
  const queued = Object.assign({ id: obj.id, __patch: 1 }, patch);
  if (!isOnline()) { offqPush("set", coll, queued); return Promise.resolve(true); }

  return db.collection(coll).doc(String(obj.id)).set(patch, { merge: true })
    .then(() => true)
    .catch(err => {
      persistFail("persistPatch", coll, err, patch);
      const denied = err && (err.code === "permission-denied" || err.code === "unauthenticated");
      if (denied) return false;
      offqPush("set", coll, queued);
      return true;
    });
}

function persistDelete(coll, id) {
  if (CUR_MEMO) CUR_MEMO = {};   /* والحذفُ كذلك (٤٢٥) */
  const db = FDB(); if (!db) return;

  try {
    if (typeof auditWrite === "function") {
      const gone = auditShadow(coll, id) ||
        (Array.isArray(DB[coll]) ? DB[coll].find(x => x && String(x.id) === String(id)) : null);
      auditWrite(coll, gone || { id }, "delete", null);
      auditDrop(coll, id);
    }
  } catch (e) {}

  /* الحذف من دورةٍ مؤرشفة أو جلسةٍ معتمدة ممنوعٌ كالتعديل — بل هو أشدّ */
  try {
    const gone = (Array.isArray(DB[coll]) ? DB[coll] : [])
      .find(x => x && String(x.id) === String(id));
    if (gone) {
      if (typeof guardArchived === "function" && guardArchived(coll, gone)) return;
      if (typeof guardSession === "function" && guardSession(coll, gone)) return;
    }
  } catch (e) {}

  if (!isOnline()) { offqPush("delete", coll, { id }); return; }

  db.collection(coll).doc(String(id)).delete()
    .catch(err => {
      /* رفضُ القواعد ليس انقطاعاً (٤٣٢): كان يُدفع إلى طابور الرفع فيُعاد
         أبداً بلا طائل. يُعاد إلى الطابور الانقطاعُ وحده، كما في persistSet. */
      const denied = err && (err.code === "permission-denied" || err.code === "unauthenticated");
      if (!denied) offqPush("delete", coll, { id });
      persistFail("persistDelete", coll, err);
    });
}

async function reloadAndRender() {
  await loadAllData();
  renderComplexSelect(); renderNav(); updateConnBadge(); mount();
}

/* =========================================================
   DATA STATUS UI
   ========================================================= */
function dataIsEmpty() { return COLLECTIONS.every(c => !DB[c] || DB[c].length === 0); }

function updateConnBadge() {
  const el = document.querySelector("#connBadge");
  if (!el) return;
  const online = FB_READY;
  el.className = "conn-badge " + (online ? "online" : "offline");
  el.innerHTML = `<span class="conn-dot"></span>${online ? "متصل بقاعدة البيانات" : "غير متصل — وضع محلي"}`;
}

function showLoading(on) {
  let el = document.querySelector("#loadingVeil");
  if (on) {
    if (!el) {
      el = document.createElement("div");
      el.id = "loadingVeil"; el.className = "loading-veil";
      el.innerHTML = `<div class="loading-card">${archMark()}<div class="spinner"></div><strong>جار التحميل </strong></div>`;
      document.body.appendChild(el);
    }
  } else if (el) { el.remove(); }
}

function dataBanner() {
  if (!FB_LOADED) return "";
  if (!cur("complexes").length) {
    return `<div class="data-banner">
      <div class="db-ico">${ic("layers", 22)}</div>
      <div class="db-text"><strong>ابدأ بإضافة أول مجمع</strong>
        <small>النظام يدير عدة مجمعات. أضف مجمعاً من صفحة «المجمعات»، ثم أضف إليه المساجد والمعلمين والبرامج والحلقات والطلاب.</small></div>
    </div>`;
  }
  return "";
}


/* =========================================================
   واجهة عامة (Public API)
   ---------------------------------------------------------
   الثوابت المعرّفة بـ const/let لا تُضاف تلقائياً إلى window،
   فكانت الملفات الأخرى (shell.js / topbar-dates.js) لا تراها.
   هذا القسم يعرّضها صراحةً — لا يغيّر أي منطق.
   ========================================================= */
/* =========================================================================
   نطاق الرؤية — المشرف المرتبط بمنشأة لا يرى بيانات غيرها
   يُطبَّق في cur() لأنها البوابة الوحيدة لقراءة البيانات في كل الصفحات.
   ========================================================================= */
/* =========================================================================
   حصر المنشأة — الفشل مغلقاً لا مفتوحاً
   -------------------------------------------------------------------------
   كان السطر «if (!mid && !cid) return null;» يعني أن أي معلّم أو مشرف
   حسابه غير مرتبط بمسجد أو مجمع يُعامَل معاملة المدير العام فيرى منشآت
   النظام كلها. وهذا عكس المطلوب تماماً: نقص البيانات كان يوسّع الصلاحية
   بدل أن يضيّقها. الآن غياب الارتباط يعني لا شيء، وتظهر رسالة صريحة.
   ========================================================================= */
/* كانت تُسمّى scopeOf كسابقتها في نطاق السور، والثانيةُ تغلب الأولى في
   JavaScript — فيفقد النطاقُ القرآنيّ دالّته ويأخذ حدودَ المنشآت. */
function userScopeOf() {
  const u = (STATE && STATE.user) || {};
  const role = u.role || "";

  /* =====================================================================
     الدخولُ إلى منشأةٍ يحصر الرؤيةَ فيها
     ---------------------------------------------------------------------
     من دخل مجمّعاً فهو داخلَه: معلّموه وطلابه وحلقاته هي التي تُعرض، لا
     معلّمو النظام كلِّه. وكان الحصرُ في صفحة المنشأة وحدها، فإذا انتقل
     إلى «المعلمين» من قائمتها رأى الجميع.

     الموضعُ هنا مقصود: cur() هي البوابةُ الوحيدة لقراءة البيانات، وهي
     تستدعي facilityFilter التي تقرأ هذه الدالّة — فيُحصر كلُّ ما يُقرأ
     في النظام بلا تعديل شاشةً شاشة.

     ويُمحى السياقُ بزرّ «رجوع للقائمة»، فتعود الرؤيةُ كما كانت.
     ===================================================================== */
  const _fc = facCtx();
  if (_fc && _fc.id) {
    return _fc.coll === "complexes"
      ? { complexIds: [String(_fc.id)], mosqueIds: [], complexId: String(_fc.id), mosqueId: "" }
      : { mosqueIds: [String(_fc.id)], complexIds: [], mosqueId: String(_fc.id), complexId: "" };
  }

  /* أماكن الإشراف المتعدّدة، مع الرجوع للحقلين المفردين في السجلات القديمة */
  const ids = userScopeIds(u);
  const mosqueIds  = ids.filter(k => k.indexOf("mosque:")  === 0).map(k => k.split(":")[1]);
  const complexIds = ids.filter(k => k.indexOf("complex:") === 0).map(k => k.split(":")[1]);

  const mid = mosqueIds[0]  || "";
  const cid = complexIds[0] || "";

  /* =====================================================================
     المالك والمدير: بلا حدّ إلا أن يُسنَد إليهما نطاقٌ قصداً
     ---------------------------------------------------------------------
     كان الاستثناء مشروطاً بألّا يكون له نطاقٌ أصلاً (!ids.length)، وحقلُ
     complexId يُكتب في حساب المدير من مزامنةٍ سابقة — فيولّد نطاقاً بلا
     قصدٍ منه، ويُحصر في مجمّعٍ لا يملك مساجدَه فتختفي عنه المنشآت كلُّها.

     الحصرُ الآن بـ scopeIds وحدها: هي ما يُسنَد قصداً من صفحة المستخدمين.
     أما الحقلان المفردان فأثرُ مزامنةٍ لا اختيار. */
  const chosen = Array.isArray(u.scopeIds) && u.scopeIds.length;
  if ((role === "admin" || role === "owner") && !chosen) return null;

  if (!ids.length) {
    /* غير الإداريين بلا ارتباط: صفر بيانات */
    if (role === "teacher" || isMgrRole(role) || role === "parent" || role === "student")
      return { mosqueId: "", complexId: "", mosqueIds: [], complexIds: [], deny: true };
    return null;                                          /* لا جلسة — وضع التطوير */
  }
  return {
    mosqueId: String(mid), complexId: String(cid),
    mosqueIds: mosqueIds.map(String), complexIds: complexIds.map(String),
    deny: false
  };
}

/* هل الحساب الحالي محروم لعدم ارتباطه بمنشأة؟ */
function scopeDenied() {
  const sc = userScopeOf();
  return !!(sc && sc.deny);
}
function scopeCircleIds(sc) {
  const all = Array.isArray(DB.circles) ? DB.circles : [];
  return all.filter(c => (sc.mosqueId && String(c.mosqueId) === sc.mosqueId) ||
                         (sc.complexId && String(c.complexId) === sc.complexId))
            .map(c => String(c.id));
}
/* حصر المنشأة: المجمع أو المسجد المرتبط به المستخدم */
/* مجموعاتٌ مشتركةٌ بطبعها: يضعها النظام مرّةً وتُستعمل في كلّ منشأة،
   فلا تُحجب عمّن لم تُبصَم باسمه. وما عداها يلزمه نطاق. */
const SCOPE_SHARED = [
  "settings", "levels", "dutyTypes", "supCats", "certTemplates",
  "questions", "questionGroups", "examPaths", "rewardRules",
  "planRules", "terms", "programs"
];

/* =========================================================================
   حصرُ المنشأة
   -------------------------------------------------------------------------
   كانت تُرشّح تسعَ مجموعاتٍ وتُمرّر الباقيَ كما هو — والباقي فيه المستخدمون
   والبرامجُ والقبولُ والمسيّراتُ وسجلُّ الإجراءات. فمديرُ المسجد يرى مسجدَه
   في شاشة الطلاب، ويرى النظامَ كلَّه في سائر الشاشات.

   القاعدة الآن واحدة تعمّ: ما حمل نطاقاً رُشّح به، وما لم يحمله بقي مرئياً
   — لأنه كُتب قبل البصم، وإخفاؤه يُفقد أصحابَه عملَهم. و migrate-roles.js
   يبصم القديمَ فيكتمل العزلُ ولا يبقى مستندٌ بلا نطاق.

   ومساجدُ المجمّع تدخل نطاقَ مديره: كان يُقارَن بـ complexId وحده، فحلقةٌ
   بُصمت بمسجدها دون مجمّعها تختفي عن مدير مجمّعها وهي في مساجده.
   ========================================================================= */
/* =========================================================================
   قارئٌ مرشَّحٌ للإضافات
   -------------------------------------------------------------------------
   الإضافات (mirath-plus وأخواتها) تقرأ DB رأساً، فتتجاوز حصر المنشأة
   كلَّه: مديرُ مسجدٍ يرى مجمّعات النظام ومساجدَها ومستخدميه في شاشاتها.
   وهي في ملفّاتٍ مستقلّةٍ لكلٍّ نطاقُه، فتُنشر الدالةُ على window ليصل
   إليها الجميعُ من موضعٍ واحد.

   الكتابةُ تبقى على DB نفسه: من كتب فوق DB بقائمةٍ مرشَّحةٍ محا ما لا
   يراه وهو قائم.
   ========================================================================= */
window.SCOPED = function (coll, fallback) {
  try { if (typeof cur === "function") return cur(coll) || []; } catch (e) {}
  return Array.isArray(fallback) ? fallback : [];
};

function facilityFilter(coll, raw) {
  const sc = userScopeOf();
  if (!sc) return raw;
  if (sc.deny) return [];          /* حساب بلا منشأة: لا يرى شيئاً */

  const mqs = sc.mosqueIds  && sc.mosqueIds.length  ? sc.mosqueIds  : (sc.mosqueId  ? [sc.mosqueId]  : []);
  const cxs = sc.complexIds && sc.complexIds.length ? sc.complexIds : (sc.complexId ? [sc.complexId] : []);

  /* =======================================================================
     مديرُ المسجد لا يتّسع نطاقُه إلى مجمّعه
     -----------------------------------------------------------------------
     كان المجمّعُ يُوسّع الرؤيةَ دائماً: فمن أُسنِد إلى مسجدٍ وحمل حسابُه
     معرّفَ مجمّعه — وهو يُكتب تلقائياً أو يُشتقّ من سجلّه — رأى كلَّ ما في
     المجمّع: طلابَ المساجد الأخرى ومعلّميها وحلقاتها. ومديرُ المسجد
     مسؤولٌ عن مسجده وحدَه.
     التوسيعُ بالمجمّع يبقى لمن المجمّعُ نطاقُه أصلاً: مديرُ المجمّع،
     والمالكُ والمديرُ إن أُسنِد إليهما.
     ======================================================================= */
  const uRole = ((STATE && STATE.user) || {}).role || "";
  const cxWide = (mqs.length && !isComplexMgr(uRole) && !isTopAdmin()) ? [] : cxs;

  /* مساجدُ المجمّعات المُسنَدة تُضاف إلى المساجد المُسنَدة مباشرةً */
  const mqAll = mqs.slice();
  (Array.isArray(DB.mosques) ? DB.mosques : []).forEach(m => {
    if (!m) return;
    if (cxWide.indexOf(String(m.complexId || "")) > -1 &&
        mqAll.indexOf(String(m.id)) < 0) mqAll.push(String(m.id));
  });

  const inScope = x => mqAll.indexOf(String(x.mosqueId  || "")) > -1 ||
                       cxWide.indexOf(String(x.complexId || "")) > -1;

  /* حلقاتُ النطاق — تُحسب مرّةً ويُنسب بها ما لا مسجدَ له */
  const cids = (Array.isArray(DB.circles) ? DB.circles : [])
    .filter(c => c && inScope(c)).map(c => String(c.id));

  if (coll === "mosques")   return raw.filter(m => mqAll.length ? mqAll.indexOf(String(m.id)) > -1 : inScope(m));
  if (coll === "complexes") return raw.filter(c => {
    if (cxs.indexOf(String(c.id)) > -1) return true;
    /* مشرف على مساجد فقط: يرى المجمعات التي تتبعها تلك المساجد */
    return mqs.some(mid => {
      const m = (DB.mosques || []).find(x => String(x.id) === String(mid));
      return m && String(m.complexId || "") === String(c.id);
    });
  });

  /* حساباتُ المستخدمين: من كان نطاقُه داخل نطاقي، وحسابي أنا.
     ولا يُرى منها ما لا نطاق له — تلك حساباتُ المالك والمدير، ولا شأن
     لمدير مجمّعٍ بها. وهي الوحيدة التي يُشدَّد فيها على غياب النطاق،
     لأن الحسابَ بلا نطاقٍ حسابٌ أعلى لا سجلٌّ قديم. */
  if (coll === "users") {
    const me = String(((STATE && STATE.user) || {}).id ||
                      ((STATE && STATE.user) || {}).uid || "");
    return raw.filter(u => {
      if (!u) return false;
      if (me && (String(u.id) === me || String(u.uid || "") === me)) return true;

      /* =====================================================================
         طلبُ الانضمام المعلَّق يُرى وإن لم يكن له نطاق
         ---------------------------------------------------------------------
         من سجّل نفسَه في signup.html لا منشأةَ له: الشاشةُ لا تسأل عنها،
         والإدارةُ هي من يُسندها عند الاعتماد. وقاعدةُ «ما لا نطاق له لا
         يُرى» كانت تُسقطه، فتبقى شاشةُ «طلبات إضافة مستخدم» فارغةً عند
         مدير المسجد ومدير المجمّع مهما سجّل أحد — ولا يُعتمد طلبٌ أبداً.

         والاستثناءُ أضيقُ ما يكون: الحسابُ الموقوفُ المسجَّلُ ذاتياً وحدَه،
         وهو لا يحمل بياناتِ منشأةٍ أخرى ولا صلاحيةً — فلا يُعيد التسرّبَ
         الذي أُغلق. وبمجرّد اعتماده يُسنَد إلى منشأةٍ فيخضع للنطاق كغيره
         (urqDecide يحذف selfSignup بعد البتّ). */
      /* ومن اختار مسجداً بعينه لا يَعمّ: يُوجَّه إلى مديره وحدَه — انظر
         الفقرة التالية. فالاستثناءُ لمن لم يختر، وهو الحالُ قبل هذه الرقعة. */
      if (u.selfSignup === true && u.active === false && !userScopeIds(u).length
          && !String(u.requestedMosqueId || "")) return true;

      /* =====================================================================
         طلبُ الانضمام يصل من اختاره المسجّل
         ---------------------------------------------------------------------
         «ولمّا يختار أيّ مسجد يتحوّل طلبُ انضمامه إلى مدير المسجد أو مدير
         المجمّع».

         والمسجدُ المختارُ يُكتب في requestedMosqueId لا في mosqueId: الأوّلُ
         طلبٌ، والثاني انتماءٌ لا يُكتب إلّا بيد مخوَّلٍ عند الاعتماد — وهي
         قاعدةُ المشروع في بيانات الارتباط.

         فيُقرأ هنا للمعلَّقين وحدَهم (موقوفٌ بانتظار البتّ): يراه مديرُ
         ذلك المسجد، ومديرُ المجمّع الذي يتبعه المسجد. ولا يمنحه الطلبُ
         شيئاً: الحسابُ موقوفٌ حتى يُعتمد.
         ===================================================================== */
      if (u.active === false && (u.selfSignup === true || u.pending === true)) {
        const rq = String(u.requestedMosqueId || "");
        if (rq) {
          if (mqAll.indexOf(rq) > -1) return true;
          const mq0 = (Array.isArray(DB.mosques) ? DB.mosques : [])
            .find(x => x && String(x.id) === rq);
          if (mq0 && cxWide.indexOf(String(mq0.complexId || "")) > -1) return true;
        }
      }

      return userScopeIds(u).some(k => {
        const p = String(k).split(":");
        return p[0] === "mosque"  ? mqAll.indexOf(p[1]) > -1
             : p[0] === "complex" ? cxWide.indexOf(p[1]) > -1 : false;
      });
    });
  }

  if (coll === "circles" || coll === "teachers") {
    return raw.filter(x => inScope(x) || cids.indexOf(String(x.id)) > -1);
  }

  /* =======================================================================
     الفترةُ المتزامنةُ بلا نطاقٍ تتبع نطاقَ شريكتها (٤٥١)
     -----------------------------------------------------------------------
     المديرُ لا يُبصَم، فالفترةُ التي ينشئها تُكتب بلا نطاق — وما لا نطاق
     له من الفترات مشتركٌ للنظام كلِّه. فأنشأ فترةً «تبدأ خالية» متزامنةً مع
     فترةِ «ميراث»، فصارت فترةَ عملِ مجمّعٍ آخر لا شأن له بها، وأخفت عنه
     طلابَه ومعلّميه وحلقاتِه وخططَه كلَّها (فحصُ مدير المجمّع على الإنتاج).
     المتزامنةُ تخصّ منشأةَ الفترة التي تزامنت معها، فتأخذ نطاقَها. والفترةُ
     بلا نطاقٍ ولا شريكةٍ تبقى مشتركةً كما كانت.
     ======================================================================= */
  if (coll === "terms") {
    const all = Array.isArray(DB.terms) ? DB.terms : [];
    return raw.filter(t => {
      if (!t) return false;
      let x = t;
      if (!x.mosqueId && !x.complexId && x.syncWith) {
        const p = all.find(y => y && String(y.id) === String(t.syncWith));
        if (p && (p.mosqueId || p.complexId)) x = p;
      }
      if (x.mosqueId || x.complexId) return inScope(x);
      return true;
    });
  }

  /* =======================================================================
     ما لا نطاق له: لا يُرى
     -----------------------------------------------------------------------
     كانت القاعدة «ما لم يحمل نطاقاً يبقى مرئياً» حفاظاً على البيانات التي
     كُتبت قبل البصم. وهي في الأثر تُبطل العزلَ كلَّه: أكثرُ السجلات القديمة
     بلا نطاق، والإشعاراتُ تُكتب بلا نطاق أصلاً — فيراها مديرُ المسجد كما
     يراها مديرُ النظام.

     من أُسنِد إلى منشأةٍ فما ليس لمنشأته ليس له. والسجلُّ بلا نطاقٍ لا
     يُعرف لمن هو، فلا يُنسب إليه.

     ⚠ أثرُ ذلك: السجلاتُ القديمة بلا نطاقٍ تختفي عن المدراء حتى تُبصَم.
        شغّل migrate-roles.js --apply فيُبصَم القديمُ ويعود لأصحابه.
        وتبقى للمالك والمدير في كلّ حال.
     ======================================================================= */
  /* ما وُجِّه إليّ بعينه (toUid أو toEmail) لي أيّاً كان نطاقُه (٤٣٢): تنبيهُ
     «تغييراتٌ لم تُرفع بعد» يُكتب لصاحب الجلسة بلا منشأة، فكان حصرُ النطاق
     يحجبه عنه — وهو وحدَه المعنيُّ به. */
  const _me = (STATE && STATE.user) || {};
  const _meId = String(_me.uid || _me.id || ""), _meMail = String(_me.email || "").toLowerCase();
  const toMe = x => (coll === "notifications" || coll === "site_messages") &&
    ((_meId && String(x.toUid || "") === _meId) ||
     (_meMail && String(x.toEmail || "").toLowerCase() === _meMail));
  return raw.filter(x => {
    if (!x) return false;
    if (toMe(x)) return true;
    if (x.mosqueId || x.complexId) return inScope(x);
    if (x.circleId) return cids.indexOf(String(x.circleId)) > -1;
    /* جائزةُ المتجر بلا منشأةٍ «للجميع» كما يحفظها rwdSave (٤٥٥): كانت تسقط
       هنا فلا يراها طالبٌ ولا وليُّ أمر، ويُردّ استبدالُها صامتاً (storeBuy لا
       يجدها). تُرى لهما وحدَهما، والاستحقاقُ بعدها في rwdEligible؛ والقواعدُ
       تُجيز لهما قراءةَ rewards أصلاً. ولا تتّسع بها رؤيةُ المدراء. */
    if (coll === "rewards" && (_me.role === "student" || _me.role === "parent")) return true;
    /* المشتركُ بطبعه: مناهجُ ومستوياتٌ وقوالبُ يضعها النظام للجميع */
    return SCOPE_SHARED.indexOf(String(coll)) > -1;
  });
}

/* =========================================================================
   الحصر الشخصي — المعلم يرى حلقاته، وولي الأمر/الطالب يرى أبناءه وحدهم
   -------------------------------------------------------------------------
   نموذج البيانات في هذا المشروع مزدوج، وهذا ما يفرض المطابقة بالاثنين معاً:
     • الصفحات الحديثة (الاختبارات · النقل · الدوام) تربط بالمعرّفات:
       circleId · studentId · teacherId
     • النماذج الأساسية (save-circle · save-student · save-teacher) لا تكتب
       هذه المعرّفات أصلاً، بل تربط بالأسماء: circle · teacher · parent
   لذلك كل دالة أدناه تجمع مجموعتَي معرّفات وأسماء، ويكفي تطابق إحداهما.

   ملاحظة: تُرجع null لـ admin و supervisor، فلا يتغيّر شيء في لوحة الإدارة.
   ========================================================================= */

/* سجل المعلم في مجموعة teachers المطابق للحساب الحالي */
/* =========================================================================
   تحضيرُ المعلّم التلقائيّ — وقتُه وتأخّرُه من وقت الحلقة والأذان
   -------------------------------------------------------------------------
   المواصفات: «يرصد النظام وقت حضور المعلم الفعلي ويسجّله تلقائياً بمجرّد
   تحضير أوّل طالب، أو بزرٍّ يحضّر به نفسه قبل أي إجراء»، و«تُقرأ الحلقة
   المرتبطة بالأذان فيُقارن وقت التحضير بوقت بدايتها». وحضورُه في كلّ حلقةٍ
   منفصل، ويُجمع آخر الشهر في مسيّره.

   كانت شاشاتُ الدوام والمسيّر تقرأ سجلاتٍ بحقل staffId لا يكتبها شيءٌ في
   الصفحات المحمَّلة (duty-plus.js غير مُدرَج)، فالمسيّر أصفارٌ بنيوية.
   السجلّ هنا بالشكل الذي يقرؤه المسيّر نفسُه، ويحمل studentId فارغاً
   والحالة من القائمة المسموحة لأن قاعدة attendance تشترطهما.
   ========================================================================= */
function staffInId(dateISO, teacherId, circleId) {
  return "sa__" + dateISO + "__" + teacherId + "__" + circleId;
}

/* سجلُّ حضور المعلّم في حلقةٍ ويوم — إن وُجد */
function staffInOf(dateISO, teacherId, circleId) {
  const id = staffInId(dateISO, teacherId, circleId);
  return (DB.attendance || []).find(x => x && String(x.id) === id) || null;
}

/* دقائق التأخّر عن بداية الحلقة — والبداية من الأذان إن رُبطت به */
function staffLateMin(c, dateISO, inT) {
  const startT = typeof circleStartAt === "function" ? circleStartAt(c, dateISO) : c.start;
  const toMin = t => { const m = String(t || "").match(/^(\d{1,2}):(\d{2})/); return m ? +m[1] * 60 + +m[2] : null; };
  const s0 = toMin(startT), t0 = toMin(inT);
  return { startT: startT || "", late: (s0 == null || t0 == null) ? 0 : Math.max(0, t0 - s0) };
}

/* يُسجَّل للمعلّم الأصيل وحده — المساعدُ لا يُحتسب دوامه على الحلقة —
   وفي يومه الجاري فقط: تحضيرُ يومٍ مضى لا يعني أنه حضر الآن. */
function staffAutoIn(circleId, dateISO, manual) {
  const u = (STATE && STATE.user) || {};
  if (u.role !== "teacher") return null;
  const t = typeof myTeacherRecord === "function" ? myTeacherRecord() : null;
  if (!t) return null;
  const c = (cur("circles") || []).find(x => String(x.id) === String(circleId));
  if (!c) return null;
  const mine = c.teacherId ? String(c.teacherId) === String(t.id)
                           : String(c.teacher || "") === String(t.name || "");
  if (!mine) return null;
  const d = String(dateISO || todayISO());
  if (d !== todayISO()) return null;
  if (staffInOf(d, t.id, c.id)) return null;

  const inT = nowHHMM();
  const lt = staffLateMin(c, d, inT);
  const rec = {
    id: staffInId(d, t.id, c.id), date: d,
    staffId: String(t.id), staffUid: String(u.uid || ""), staffName: t.name || "",
    staffRole: "معلم", studentId: "",
    circleId: String(c.id), circle: c.name || "",
    mosqueId: c.mosqueId || t.mosqueId || "", complexId: c.complexId || t.complexId || "",
    status: lt.late > 0 ? "متأخر" : "حاضر",
    inTime: inT, startAt: lt.startT, lateMin: lt.late,
    auto: !manual,
    termId: activeTermId() || termOfDate(d),
    by: u.email || "", ts: Date.now()
  };
  if (!Array.isArray(DB.attendance)) DB.attendance = [];
  DB.attendance.push(rec);
  persistSet("attendance", rec);
  return rec;
}

/* زرُّ «تسجيل حضوري» — قبل تحضير أيّ طالب */
window.staffSelfIn = function (circleId) {
  const rec = staffAutoIn(circleId, todayISO(), true);
  if (!rec) { showToast("حضورك مسجَّلٌ في هذه الحلقة اليوم، أو ليست حلقتك الأصيلة", "info"); return; }
  showToast("سُجّل حضورك " + rec.inTime + (rec.lateMin ? " — تأخّر " + toArabicDigits(rec.lateMin) + " د" : ""),
            rec.lateMin ? "warn" : "success");
  mount();
};

/* شريطُ حضور المعلّم في شاشة التحضير */
function staffSelfBar(circleId) {
  const u = (STATE && STATE.user) || {};
  if (u.role !== "teacher" || !circleId) return "";
  const t = typeof myTeacherRecord === "function" ? myTeacherRecord() : null;
  const c = (cur("circles") || []).find(x => String(x.id) === String(circleId));
  if (!t || !c) return "";
  const mine = c.teacherId ? String(c.teacherId) === String(t.id)
                           : String(c.teacher || "") === String(t.name || "");
  if (!mine) return "";
  const r = staffInOf(todayISO(), t.id, c.id);
  return `<div class="chip-list" style="margin-bottom:10px">
    ${r ? `<span class="chip ${r.lateMin ? "t-amber" : "t-green"}">حضورك في «${esc(c.name || "")}»: ${esc(r.inTime)}${
            r.lateMin ? " · تأخّر " + toArabicDigits(r.lateMin) + " د" : ""}</span>`
        : `<button type="button" class="chip t-blue" style="border:none;cursor:pointer"
             onclick="window.staffSelfIn('${jsAttr(c.id)}')">${ic("clock", 13)} تسجيل حضوري في «${esc(c.name || "")}»</button>`}
  </div>`;
}

function myTeacherRecord() {
  const u = (STATE && STATE.user) || {};
  const list = Array.isArray(DB.teachers) ? DB.teachers : [];
  const mail = String(u.email || "").toLowerCase();
  return list.find(t =>
       (u.uid  && String(t.uid || "") === String(u.uid))
    || (mail   && String(t.username || "").toLowerCase() === mail)
    || (mail   && String(t.email || "").toLowerCase() === mail)
    || (u.name && String(t.name || "") === String(u.name))
  ) || null;
}

/* حلقات المعلم — بالمعرّف أو بالاسم */
/* =========================================================================
   مزامنة نطاق المستخدم إلى ملفّه
   -------------------------------------------------------------------------
   قواعد Firestore تحصر كتابة المعلّم في حلقاته عبر circleIds، وتحصر المدير
   في مجمّعه عبر complexId — وكلاهما يُقرأ من مستند users لا من الذاكرة،
   لأن القواعد لا ترى إلا قاعدة البيانات.

   وكان circleIds يُقرأ في myCircles ولا يكتبه شيء، فيبقى الحصر نائماً:
   القاعدة تسمح للجميع لأن المصفوفة فارغة دائماً.

   تُزامَن هنا عند الإقلاع وعند كلّ تغييرٍ في إسناد الحلقات.
   ========================================================================= */
window.syncMyScope = function (force) {
  const u = (STATE && STATE.user) || {};
  if (!u.uid) return Promise.resolve(false);

  /* القراءةُ هنا من مرايا DB لا من cur: cur مصفّاةٌ بالنطاق، وهذه الدالّةُ
     هي التي تُنشئ النطاق. فالحسابُ بلا نطاقٍ كان لا يرى مستندَه ولا سجلَّ
     معلّمه، فلا يُحسب له نطاقٌ فيبقى بلا نطاق — قفلٌ على نفسه لا يُفكّ إلا
     بالقراءة غيرِ المصفّاة. وهذا الاستثناءُ الوحيدُ من عرف cur. */
  const rec = (Array.isArray(DB.users) ? DB.users : []).find(x =>
    String(x.uid || x.id) === String(u.uid));
  if (!rec) return Promise.resolve(false);

  const patch = {};

  /* حلقات المعلّم: ما أُسند إليه أصالةً أو مساعداً */
  if (rec.role === "teacher") {
    /* بالمعرّف وحدَه: المطابقةُ بالاسم كانت تنسخ منشأةَ معلّمٍ آخرَ
       يشاركه الاسمَ إلى مستند هذا الحساب، ومنه تعود إلى سجلّه. */
    const t = (Array.isArray(DB.teachers) ? DB.teachers : []).find(x =>
      String(x.uid) === String(u.uid));

    const ids = (Array.isArray(DB.circles) ? DB.circles : []).filter(c => {
      if (!c) return false;
      if (t && String(c.teacherId) === String(t.id)) return true;
      if (u.uid && String(c.teacherId) === String(u.uid)) return true;
      if (t && c.teacher && nameKey(c.teacher) === nameKey(t.name)) return true;
      if (Array.isArray(c.assistants)) {
        if (u.uid && c.assistants.indexOf(String(u.uid)) > -1) return true;
        if (t && c.assistants.indexOf(String(t.id)) > -1) return true;
      }
      return false;
    }).map(c => String(c.id));

    const before = Array.isArray(rec.circleIds) ? rec.circleIds.slice().sort().join(",") : "";
    if (before !== ids.slice().sort().join(",")) patch.circleIds = ids;

    /* المسجد والمجمّع من سجلّه، فيُحصر بهما */
    if (t) {
      if (t.mosqueId && rec.mosqueId !== t.mosqueId) patch.mosqueId = String(t.mosqueId);
      if (t.complexId && rec.complexId !== t.complexId) patch.complexId = String(t.complexId);
    }
  }

  /* لا يُكتب complexId استنتاجاً البتّة: STATE.complexId هو المجمّعُ
     المفتوحُ في الشاشة، ويختلف من جهازٍ لآخر ومن جلسةٍ لأخرى. فكتابتُه
     كانت تحصر الحسابَ في أوّل مجمّعٍ فُتح على ذلك الجهاز، فيرى صاحبُه
     على الحاسوب غيرَ ما يرى على الهاتف. الحصرُ يُسند من صفحة المستخدمين
     قصداً — وقد كان التعليقُ يقول هذا والكودُ يفعل خلافَه. */

  if (!Object.keys(patch).length && !force) return Promise.resolve(false);

  Object.assign(rec, patch);
  /* حقولُ النطاق لا يكتبها صاحبُ الحساب في ملفّه (٤٤١): القاعدةُ تُجيز له
     خمسةَ حقولٍ فحسب، فكان كلُّ فحصٍ دوريٍّ في جلسة المعلّم يُردّ على الخادم.
     تبقى في الذاكرة لجلسته، وتُكتب على الخادم من جلسة الإدارة — نطاقُ
     المعلّم يُزامَن هناك عند إسناد الحلقة أو تغيير معلّمها. */
  if (typeof maySysWrite === "function" && !maySysWrite()) return Promise.resolve(false);
  return Promise.resolve(persistSet("users", rec)).then(() => true);
};

/* نطاق معلّمٍ بعينه — يُنادى عند إسناد حلقة أو تغيير معلّمها */
/* =========================================================================
   تقريرُ النطاق — يُقارَن بين جهازٍ وآخر
   -------------------------------------------------------------------------
   حين تختلف البياناتُ بين الحاسوب والهاتف فالسببُ نطاقُ الحساب أو المجمّعُ
   المفتوح، لا البياناتُ نفسُها. يُطبع هنا ما يحدّد ما يراه هذا الجهاز:
   يُنادى من الطرفية بـ scopeReport() في الجهازين ويُقارَن الناتجان.
   ========================================================================= */
window.scopeReport = function () {
  const u = (STATE && STATE.user) || {};
  const mos = (Array.isArray(DB.mosques) ? DB.mosques : []);
  const cxs = (Array.isArray(DB.complexes) ? DB.complexes : []);
  const nameOf = id => (cxs.find(c => String(c.id) === String(id)) || {}).name || "—";
  const out = {
    الحساب: { المعرّف: u.uid || u.id || "", الاسم: u.name || "", الدور: u.role || "",
              مسجده: u.mosqueId || "", مجمّعه: u.complexId || "",
              مساجده: u.mosqueIds || [], مجمّعاته: u.complexIds || [] },
    "المجمّع المفتوح في هذه الشاشة": STATE.complexId || "",
    الأعداد: {}, "المساجد ومجمّعاتها": []
  };
  ["complexes", "mosques", "circles", "students", "teachers",
   "programs", "levels", "plans"].forEach(function (k) {
    out.الأعداد[k] = {
      "في الذاكرة": (Array.isArray(DB[k]) ? DB[k].length : 0),
      "بعد التصفية": (typeof cur === "function" ? (cur(k) || []).length : 0)
    };
  });
  mos.forEach(function (m) {
    out["المساجد ومجمّعاتها"].push({
      المسجد: m.name || "", المعرّف: m.id,
      complexId: m.complexId || "(بلا مجمّع)", المجمّع: m.complexId ? nameOf(m.complexId) : "—"
    });
  });
  try { console.table(out["المساجد ومجمّعاتها"]); } catch (e) {}
  try { console.log(JSON.stringify(out, null, 2)); } catch (e) {}
  return out;
};

window.syncTeacherScope = function (teacherId) {
  const t = (cur("teachers") || []).find(x => String(x.id) === String(teacherId));
  if (!t) return;

  const rec = (cur("users") || []).find(x =>
    (t.uid && String(x.uid || x.id) === String(t.uid)) ||
    (x.name && nameKey(x.name) === nameKey(t.name)));
  if (!rec) return;                  /* لا حساب له بعد: يُزامَن عند دخوله */

  const ids = (cur("circles") || []).filter(c =>
    c && (String(c.teacherId) === String(t.id) ||
          (c.teacher && nameKey(c.teacher) === nameKey(t.name)) ||
          (Array.isArray(c.assistants) && c.assistants.indexOf(String(t.id)) > -1))
  ).map(c => String(c.id));

  const before = Array.isArray(rec.circleIds) ? rec.circleIds.slice().sort().join(",") : "";
  if (before === ids.slice().sort().join(",")) return;

  rec.circleIds = ids;
  if (t.mosqueId) rec.mosqueId = String(t.mosqueId);
  if (t.complexId) rec.complexId = String(t.complexId);
  persistSet("users", rec);
};

function myCircles() {
  const u = (STATE && STATE.user) || {};
  const ids = new Set(), names = new Set();
  (Array.isArray(u.circleIds) ? u.circleIds : []).forEach(x => ids.add(String(x)));

  const rec = myTeacherRecord();
  if (rec && rec.circle) names.add(String(rec.circle));

  (Array.isArray(DB.circles) ? DB.circles : []).forEach(c => {
    const mine =
         ids.has(String(c.id))
      || names.has(String(c.name || ""))
      || (u.uid  && String(c.teacherId || "") === String(u.uid))
      || (rec    && String(c.teacherId || "") === String(rec.id))
      || (u.name && String(c.teacher   || "") === String(u.name))
      || (rec    && String(c.teacher   || "") === String(rec.name || ""))

      /* المعلّم المساعد: معلّمٌ ثانٍ في الحلقة يعمل فيها كالأصيل.
         تُقاس صلاحياته من هنا لأنها بوّابة كلّ ما يراه المعلّم — تحضيراً
         وتسميعاً وواجبات. */
      || (Array.isArray(c.assistants) && (
           (u.uid && c.assistants.indexOf(String(u.uid)) > -1) ||
           (rec   && c.assistants.indexOf(String(rec.id)) > -1)));
    if (mine) { ids.add(String(c.id)); if (c.name) names.add(String(c.name)); }
  });
  return { ids, names };
}

/* أبناء ولي الأمر، أو الطالب نفسه */
/* تسوية الاسم للمطابقة: المسافات والهمزات والتاء المربوطة والتطويل.
   المطابقة الحرفية كانت تقطع الصلة بين «أدهم» و«ادهم»، وبين اسمٍ فيه
   مسافة زائدة ومثيله — بصمت وبلا أي رسالة. */
function nameKey(v) {
  return String(v == null ? "" : v)
    .replace(/[\u0640\u064B-\u0652]/g, "")   /* تطويل وتشكيل */
    .replace(/[أإآٱ]/g, "ا")
    .replace(/ى/g, "ي")
    .replace(/ة/g, "ه")
    .replace(/\s+/g, " ")
    .trim();
}

/* =========================================================================
   صندوق الرسائل
   -------------------------------------------------------------------------
   كان زر الرسائل ينادي openMsgPanel وهي غير معرَّفة، فيقع على رسالة
   احتياطية ولا يفتح شيئاً. وكانت site_messages تُكتب عند الإرسال ولم تكن
   في COLLECTIONS أصلاً — فالرسائل تُرسَل ولا تُحمَّل أبداً.

   الرسالة تُوجَّه بـ toId أو toEmail، ويُميَّز المقروء بـ read.
   والردّ يُنشئ رسالة جديدة في الاتجاه المعاكس بـ replyTo.
   ========================================================================= */

/* =========================================================================
   إنشاء رسالة جديدة
   -------------------------------------------------------------------------
   كان الصندوق يعرض الوارد فقط بلا أي وسيلة لبدء محادثة، فلا يستطيع المعلّم
   مراسلة طالبه ولا الطالب سؤال معلّمه. المراسلات الوحيدة كانت من الإدارة
   عبر صفحة المستخدمين.

   المستقبَلون يُشتقّون من الدور: المعلّم يراسل طلاب حلقاته وإدارته،
   والطالب وولي الأمر يراسلان معلّمه، والإدارة تراسل الجميع.
   ========================================================================= */

/* من يستطيع هذا الحساب مراسلته */
function msgContacts() {
  const u = (STATE && STATE.user) || {};
  const role = u.role || "";
  const out = [];
  const seen = new Set();

  const push = (id, name, sub, mail) => {
    const k = String(id || mail || name);
    if (!k || seen.has(k)) return;
    seen.add(k);
    out.push({ id: String(id || ""), name: name || "—", sub: sub || "", email: String(mail || "").toLowerCase() });
  };

  if (role === "student" || role === "parent") {
    /* معلّمو حلقات الطالب */
    const studs = (Array.isArray(DB.students) ? DB.students : [])
      .filter(x => myStudents().ids.has(String(x.id)));
    studs.forEach(st => {
      const t = (DB.teachers || []).find(x =>
        String(x.id) === String(st.teacherId) || nameKey(x.name) === nameKey(st.teacher));
      if (t) push(t.uid || t.id, t.name, "معلّم " + (st.circle || ""), t.username);
    });
    /* وإدارة المسجد */
    (DB.users || []).filter(x => (x.role === "admin" || isMgrRole(x.role)) && x.active !== false)
      .forEach(x => push(x.uid || x.id, x.name, x.role === "admin" ? "الإدارة" : "مشرف", x.email));

  } else if (role === "teacher") {
    const kids = cur("students");
    kids.forEach(st => push(st.uid || st.id, st.name, st.circle || "طالب", st.email));

    /* أولياءُ أمور طلابه: كان يراسل الطالبَ ولا يجد وليَّه، وأكثرُ ما
       يُبلَّغ به — الغيابُ والتأخّر — إنّما يُبلَّغ الوليُّ لا الطالب. */
    (DB.users || []).forEach(x => {
      if (!x || x.role !== "parent" || x.active === false) return;
      const linked = kids.some(st =>
        String(x.studentId || "") === String(st.id) ||
        (Array.isArray(x.studentIds) && x.studentIds.indexOf(String(st.id)) > -1));
      if (!linked) return;

      const kid = kids.find(st =>
        String(x.studentId || "") === String(st.id) ||
        (Array.isArray(x.studentIds) && x.studentIds.indexOf(String(st.id)) > -1));
      push(x.uid || x.id, x.name, "وليّ أمر " + ((kid && kid.name) || ""), x.email);
    });

    (DB.users || []).filter(x => (x.role === "admin" || isMgrRole(x.role)) && x.active !== false)
      .forEach(x => push(x.uid || x.id, x.name, x.role === "admin" ? "الإدارة" : "مشرف", x.email));

  } else {
    /* الإدارة: الجميع */
    (DB.users || []).filter(x => x && x.active !== false)
      .forEach(x => push(x.uid || x.id, x.name, ROLE_AR(x.role), x.email));
    cur("students").forEach(st => push(st.uid || st.id, st.name, st.circle || "طالب", st.email));
  }

  /* لا يراسل المرء نفسه */
  const me = String(u.uid || u.id || "");
  const myMail = String(u.email || "").toLowerCase();
  return out.filter(x => x.id !== me && (!myMail || x.email !== myMail));
}

function ROLE_AR(r) {
  return r === "admin" ? "مدير"
    : r === "complexManager" ? "مدير مجمّع" : r === "mosqueManager" ? "مدير مسجد"
    : r === "supervisor" ? "مشرف"
    : r === "teacher" ? "معلّم" : r === "parent" ? "ولي أمر" : "طالب";
}

window.msgCompose = function (toId, toName) {
  const people = msgContacts();
  if (!people.length) {
    showToast("لا توجد جهات يمكنك مراسلتها", "warn");
    return;
  }

  openModal("رسالة جديدة", "اختر المستقبِل واكتب رسالتك",
    `<div class="form-grid">
      <div class="field full"><label>إلى <span class="req">*</span></label>
        <select id="mc_to">
          ${people.map(p => `<option value="${esc(p.id)}|${esc(p.email)}|${esc(p.name)}"
            ${toId && String(p.id) === String(toId) ? "selected" : ""}>${esc(p.name)}${p.sub ? " — " + esc(p.sub) : ""}</option>`).join("")}
        </select></div>

      <div class="field full"><label>الموضوع <span class="req">*</span></label>
        <input id="mc_title" placeholder="مثال: استفسار عن الواجب"></div>

      <div class="field full"><label>الرسالة <span class="req">*</span></label>
        <textarea id="mc_text" rows="5" placeholder="اكتب رسالتك هنا…"></textarea></div>
     </div>`,
    `<button class="btn btn-primary" data-action="msg-send">${ic("send", 16)} إرسال</button>
     <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
};

function msgSend() {
  const raw = val("#mc_to", "");
  const title = (val("#mc_title") || "").trim();
  const text = (val("#mc_text") || "").trim();

  if (!raw)   { showToast("اختر المستقبِل", "warn"); return; }
  if (!title) { showToast("الموضوع مطلوب", "warn"); return; }
  if (!text)  { showToast("نص الرسالة مطلوب", "warn"); return; }

  const parts = String(raw).split("|");
  const u = (STATE && STATE.user) || {};

  /* يُرسَل بالمعرّفين معاً — معرّف السجل ومعرّف الحساب — فأيّهما طابق وصلت */
  const toId = parts[0] || "";
  const alt = (DB.students || []).find(x => String(x.id) === toId) ||
              (DB.teachers || []).find(x => String(x.id) === toId) ||
              (DB.users || []).find(x => String(x.id) === toId || String(x.uid) === toId);

  const rec = {
    id: "m" + Date.now(),
    title: title, text: text, ts: Date.now(),
    toId: toId,
    toUid: alt ? String(alt.uid || alt.id || "") : toId,
    toEmail: (parts[1] || (alt && (alt.email || alt.username)) || "").toLowerCase(),
    toName: parts[2] || (alt && alt.name) || "",
    fromId: String(u.uid || u.id || ""),
    fromEmail: String(u.email || "").toLowerCase(),
    fromName: u.name || "",
    read: false, type: "info"
  };

  const btn = document.querySelector('[data-action="msg-send"]');
  if (btn) { btn.disabled = true; btn.textContent = "جارٍ الإرسال…"; }

  if (!Array.isArray(DB.site_messages)) DB.site_messages = [];
  DB.site_messages.push(rec);

  Promise.resolve(persistSet("site_messages", rec)).then(function (ok) {
    if (ok) {
      closeModal(); mount();
      showToast("أُرسلت رسالتك إلى " + (rec.toName || ""), "success");
    } else {
      if (btn) { btn.disabled = false; btn.innerHTML = ic("send", 16) + " إعادة المحاولة"; }
      showToast("لم تصل الرسالة — تحقّق من الاتصال", "warn");
    }
  });
}

/* =========================================================================
   التواصل — عبر الموقع أو واتساب
   -------------------------------------------------------------------------
   رسالة الموقع تُخزَّن في site_messages فيقرؤها المستقبِل داخل النظام،
   وواتساب يفتح المحادثة في تطبيقه برقمه المسجَّل.

   الرقم يُطبَّع قبل الاستعمال: تُنزع المسافات والرموز، ويُحوَّل الصفر
   البادئ إلى رمز الدولة — فرقم «05xxxxxxxx» لا يعمل في wa.me كما هو.
   ========================================================================= */

/* رمز الدولة يُضبط من إعدادات النظام، وإلا السعودية. الأرقام المحلية
   تبدأ بصفر ولا يقبلها واتساب، فيُستبدل الصفر برمز الدولة. */
function waCC() {
  const st = (DB.settings || {});
  const cc = String(st.waCountryCode || st.countryCode || "").replace(/[^\d]/g, "");
  return cc || "966";
}

function waNumber(raw) {
  let n = String(raw == null ? "" : raw).replace(/[^\d+]/g, "");
  if (!n) return "";
  if (n.indexOf("+") === 0)  return n.slice(1);      /* دولي صريح */
  if (n.indexOf("00") === 0) return n.slice(2);      /* دولي بصيغة 00 */
  if (n.indexOf("0") === 0)  return waCC() + n.slice(1);
  /* الأرقام الطويلة تُترك كما هي فهي دولية غالباً */
  return n.length >= 12 ? n : waCC() + n;
}

function waLink(raw, text) {
  const n = waNumber(raw);
  if (!n) return "";
  return "https://wa.me/" + n + (text ? "?text=" + encodeURIComponent(text) : "");
}

/* جهات التواصل مصنَّفةً بأدوارها */
function contactGroups() {
  const u = (STATE && STATE.user) || {};
  const role = u.role || "";
  const me = String(u.uid || u.id || "");
  const myMail = String(u.email || "").toLowerCase();

  const seen = new Set();
  const mk = (id, name, sub, phone, mail) => {
    const k = String(id || mail || name);
    if (!k || seen.has(k)) return null;
    if (String(id) === me || (myMail && String(mail || "").toLowerCase() === myMail)) return null;
    seen.add(k);
    return { id: String(id || ""), name: name || "—", sub: sub || "",
             phone: String(phone || ""), email: String(mail || "").toLowerCase() };
  };

  const groups = [];

  if (role === "student" || role === "parent") {
    const ids = myStudents().ids;
    const studs = (DB.students || []).filter(x => ids.has(String(x.id)));
    const ts = [];
    studs.forEach(st => {
      const t = (DB.teachers || []).find(x =>
        String(x.id) === String(st.teacherId) || nameKey(x.name) === nameKey(st.teacher));
      if (t) { const r = mk(t.uid || t.id, t.name, st.circle || "معلّم", t.phone, t.username); if (r) ts.push(r); }
    });
    if (ts.length) groups.push({ t: "المعلمون", icon: "teacher", list: ts });

    /* زملاء الحلقة: كان الطالب وولي الأمر لا يريان غير المعلّمين،
       فيبدو الأمر كأن قائمة التواصل ناقصة. تُحصر الحلقة بحلقات
       أبنائه فلا تنكشف حلقات المنشأة كلها. */
    const myCirIds = new Set(), myCirNames = new Set();
    studs.forEach(st => {
      if (st.circleId) myCirIds.add(String(st.circleId));
      if (st.circle)   myCirNames.add(String(st.circle));
    });

    const mates = (DB.students || [])
      .filter(x => !ids.has(String(x.id)) &&
        (myCirIds.has(String(x.circleId || "")) || myCirNames.has(String(x.circle || ""))))
      .map(x => mk(x.uid || x.id, x.name, x.circle || "زميل",
                   x.parentPhone || x.phone, x.email))
      .filter(Boolean);
    if (mates.length) groups.push({ t: "زملاء الحلقة", icon: "users", list: mates });

  } else if (role === "teacher") {
    const st = cur("students").map(x =>
      mk(x.uid || x.id, x.name, x.circle || "طالب", x.parentPhone || x.phone, x.email)).filter(Boolean);
    if (st.length) groups.push({ t: "الطلاب", icon: "users", list: st });

    /* زملاء المهنة: المعلّم كان يرى طلابه وحدهم */
    const co = cur("teachers").map(x =>
      mk(x.uid || x.id, x.name, x.mosque || x.circle || "معلّم", x.phone, x.username))
      .filter(Boolean);
    if (co.length) groups.push({ t: "المعلمون", icon: "teacher", list: co });

  } else {
    const te = cur("teachers").map(x =>
      mk(x.uid || x.id, x.name, x.mosque || "معلّم", x.phone, x.username)).filter(Boolean);
    if (te.length) groups.push({ t: "المعلمون", icon: "teacher", list: te });

    const st = cur("students").map(x =>
      mk(x.uid || x.id, x.name, x.circle || "طالب", x.parentPhone || x.phone, x.email)).filter(Boolean);
    if (st.length) groups.push({ t: "الطلاب", icon: "users", list: st });
  }

  /* الإدارة متاحة للجميع عدا الإدارة نفسها */
  if (role !== "admin" && !isMgrRole(role)) {
    const ad = (DB.users || [])
      .filter(x => x && x.active !== false && (x.role === "admin" || isMgrRole(x.role)))
      .map(x => mk(x.uid || x.id, x.name, x.role === "admin" ? "مدير" : "مشرف", x.phone, x.email))
      .filter(Boolean);
    if (ad.length) groups.push({ t: "الإدارة", icon: "shield", list: ad });
  }

  return groups;
}

window.openContacts = function () {
  const groups = contactGroups();

  if (!groups.length) {
    openModal("التواصل", "",
      `<div style="padding:30px;text-align:center">
        <strong style="display:block;margin-bottom:6px">لا توجد جهات للتواصل</strong>
        <span class="muted" style="font-size:13px">حسابك غير مرتبط بحلقة أو منشأة بعد.</span>
      </div>`, "");
    return;
  }

  const body = groups.map(g => `
    <div class="ct-group">
      <div class="ct-head">${ic(g.icon, 17)}<span>${esc(g.t)}</span></div>
      ${g.list.map(p => {
        const wa = waLink(p.phone, "السلام عليكم");
        return `<div class="ct-row">
          <span class="mini-avatar">${initials(p.name)}</span>
          <span class="ct-name">${esc(p.name)}<span class="ct-sub">${esc(p.sub)}</span></span>
          <span class="ct-acts">
            <button type="button" class="ct-b site" data-action="msg-to"
              data-id="${esc(p.id)}" data-name="${esc(p.name)}"
              title="رسالة داخل الموقع">${ic("chat", 15)} الموقع</button>
            ${wa
              ? `<button type="button" class="ct-b wa" data-action="wa-open"
                   data-url="${esc(wa)}" data-num="${esc(waNumber(p.phone))}"
                   title="واتساب: ${esc(waNumber(p.phone))}">${WA_ICON} واتساب</button>`
              : `<span class="ct-b off" title="لا يوجد رقم مسجَّل لهذه الجهة">${WA_ICON} لا رقم</span>`}
          </span>
        </div>`;
      }).join("")}
    </div>`).join("");

  /* التنسيق مضمَّن مع النافذة لا في styles.css:
     أي نسخة قديمة أو ناقصة من ملف التنسيق كانت تُسقط قواعد ct-* فتُعرض
     الصفوف block — كل عنصر تحت الآخر والأزرار مكوّمة. الإدراج هنا يجعل
     الشكل مستقلاً عن حال ملف التنسيق. */
  const CT_CSS = `<style>
    .ct-list { display: grid; gap: 18px; max-height: 460px; overflow-y: auto; padding: 2px; }
    .ct-group { display: grid; gap: 8px; }
    .ct-head { display: flex; align-items: center; gap: 7px;
      font-size: 13px; font-weight: 800; color: var(--brand-dark, #177578);
      padding-bottom: 6px; border-bottom: 1px solid var(--border-soft, #88a0a1); }
    .ct-row { display: flex !important; align-items: center; gap: 12px;
      padding: 11px 13px; border-radius: 14px;
      border: 1px solid var(--border-soft, #88a0a1); background: var(--surface, #fff); }
    .ct-row:hover { background: var(--border-soft, #85a9ab); }
    .ct-name { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 2px;
      font-size: 14px; font-weight: 700; }
    .ct-sub { font-size: 11.5px; font-weight: 500; color: var(--text-faint, #516969); }
    .ct-acts { display: flex; gap: 8px; flex: 0 0 auto; }
    .ct-b { display: inline-flex; align-items: center; justify-content: center; gap: 7px;
      padding: 9px 16px; border-radius: 99px; font: inherit; font-size: 13px; font-weight: 700;
      border: 1px solid transparent; cursor: pointer; white-space: nowrap; }
    .ct-b.site { background: linear-gradient(140deg, #15a2a7, #177578); color: #fff; }
    .ct-b.wa { background: linear-gradient(140deg, #118589, #0b5557); color: #fff; }
    .ct-b.off { background: var(--border-soft, #88a0a1); color: var(--text-faint, #516969); cursor: default; }
    .ct-b:hover { filter: brightness(1.07); }
    .mini-avatar { width: 38px; height: 38px; flex: 0 0 auto; border-radius: 12px;
      display: grid; place-items: center; font-weight: 800; font-size: 14px;
      background: var(--brand-soft, #67bdc0); color: var(--brand-dark, #177578); }
    @media (max-width: 520px) {
      .ct-row { flex-wrap: wrap; }
      .ct-acts { width: 100%; }
      .ct-b { flex: 1; }
    }
  </style>`;

  openModal("التواصل", "راسل عبر الموقع أو واتساب", CT_CSS + `<div class="ct-list">${body}</div>`,
    `<button class="btn btn-ghost" data-action="msg-inbox">${ic("chat", 16)} صندوق الرسائل</button>`);
};

const WA_ICON = '<svg viewBox="0 0 24 24" width="15" height="15" fill="currentColor"><path d="M17.5 14.4c-.3-.2-1.7-.9-2-1-.3-.1-.5-.2-.7.1-.2.3-.7 1-.9 1.2-.2.2-.3.2-.6.1-.3-.2-1.2-.5-2.3-1.4-.9-.8-1.4-1.7-1.6-2-.2-.3 0-.5.1-.6l.5-.5c.1-.2.2-.3.3-.5v-.5c-.1-.2-.7-1.6-.9-2.2-.2-.5-.5-.5-.7-.5h-.6c-.2 0-.5.1-.8.4-.3.3-1 1-1 2.5s1.1 2.9 1.2 3.1c.2.2 2.1 3.2 5.1 4.5.7.3 1.3.5 1.7.6.7.2 1.4.2 1.9.1.6-.1 1.7-.7 2-1.4.2-.7.2-1.3.2-1.4-.1-.1-.3-.2-.6-.3M12 2a10 10 0 0 0-8.6 15L2 22l5.2-1.4A10 10 0 1 0 12 2m0 1.8a8.2 8.2 0 0 1 6.7 12.9l-.2.3.6 2.2-2.3-.6-.3.2A8.2 8.2 0 1 1 12 3.8"/></svg>';

/* كل ما يمكن أن يُعنوَن به هذا الحساب.
   سجل الطالب ومستند المستخدم كيانان بمعرّفين مختلفين، والمرسِل قد يعنون
   بأيّهما — فإن طوبق بواحد فقط ضاعت الرسالة بين الاثنين. */
function myAddresses() {
  const u = (STATE && STATE.user) || {};
  const ids = new Set(), mails = new Set();

  [u.uid, u.id, u.studentId].forEach(v => { if (v) ids.add(String(v)); });
  if (u.email) mails.add(String(u.email).toLowerCase());
  if (u.loginEmail) mails.add(String(u.loginEmail).toLowerCase());
  if (u.username) mails.add(String(u.username).toLowerCase());

  /* سجلات الطلاب المرتبطة بالحساب */
  try {
    myStudents().ids.forEach(id => ids.add(String(id)));
    (DB.students || []).forEach(st => {
      if (!ids.has(String(st.id))) return;
      if (st.uid) ids.add(String(st.uid));
      if (st.email) mails.add(String(st.email).toLowerCase());
    });
  } catch (e) {}

  /* سجل المعلم المرتبط بالحساب */
  try {
    const t = myTeacherRecord && myTeacherRecord();
    if (t) {
      ids.add(String(t.id));
      if (t.uid) ids.add(String(t.uid));
      if (t.username) mails.add(String(t.username).toLowerCase());
    }
  } catch (e) {}

  return { ids, mails };
}

function myMessages() {
  const { ids, mails } = myAddresses();
  const u = (STATE && STATE.user) || {};
  const role = String(u.role || "");
  const isAdminSide = role === "admin" || role === "owner" || isMgrRole(role);

  /* سجلُّ المعلّم: رسائلُ أولياء الأمور تُوجَّه بمعرّفه في teachers لا
     بمعرّف حسابه، وهما قد يختلفان. */
  let tid = "";
  try {
    const t = typeof myTeacherRecord === "function" ? myTeacherRecord() : null;
    if (t) tid = String(t.id);
  } catch (e) {}

  return (Array.isArray(DB.site_messages) ? DB.site_messages : [])
    .filter(m => {
      if (!m) return false;

      if (ids.has(String(m.toId || ""))) return true;
      if (ids.has(String(m.toUid || ""))) return true;
      if (m.toEmail && mails.has(String(m.toEmail).toLowerCase())) return true;

      /* موجَّهةٌ إلى معلّمٍ بمعرّف سجلّه */
      if (tid && String(m.toId || "") === tid) return true;

      /* موجَّهةٌ إلى الإدارة: كانت لا تصل أحداً لأنّ toId فيها فارغ */
      if (m.toRole) {
        if (String(m.toRole) === role) return true;
        if (m.toRole === "admin" && isAdminSide) return true;
      }

      return false;
    })
    .sort((a, b) => (b.ts || 0) - (a.ts || 0));
}

function msgUnread() { return myMessages().filter(m => !m.read).length; }

window.openMsgPanel = function () {
  const list = myMessages();
  const unread = list.filter(m => !m.read).length;

  const items = list.length ? list.map(m => `<button type="button"
      class="alert-item nt ${m.read ? "read" : ""}"
      data-action="msg-open" data-id="${esc(String(m.id))}">
      <div class="alert-ico ${m.type === "warn" ? "t-amber" : "t-blue"}">${ic("chat", 18)}</div>
      <div class="at">
        <strong>${esc(m.title || "رسالة")}</strong>
        <small>${esc(String(m.text || "").slice(0, 90))}${String(m.text || "").length > 90 ? "…" : ""}</small>
        <span class="nt-time">${esc(timeAgo(m.ts))}${m.fromName ? " — " + esc(m.fromName) : ""}</span>
      </div>
      ${!m.read ? `<span class="nt-dot"></span>` : ""}
    </button>`).join("")
    : `<div style="padding:34px 16px;text-align:center">
        <div class="empty-mark" style="width:56px;height:56px">${ic("chat", 40)}</div>
        <strong style="display:block;margin-bottom:6px">لا توجد رسائل</strong>
        <span class="muted" style="font-size:13px">لم تصلك أي رسائل بعد.</span>
      </div>`;

  openModal("الرسائل", unread ? toArabicDigits(unread) + " غير مقروءة" : "كل الرسائل مقروءة",
    `<div class="nt-list">${items}</div>`,
    `<button class="btn btn-primary" data-action="msg-new">${ic("send", 16)} رسالة جديدة</button>
     ${unread ? `<button class="btn btn-ghost" data-action="msg-read-all">${ic("check", 16)} تعليم الكل كمقروء</button>` : ""}`);
};

/* =========================================================================
   تعليمُ الرسالة مقروءةً — حقلُ read وحدَه (٤٣٢)
   -------------------------------------------------------------------------
   كان يُكتب السجلُّ كلُّه عبر persistSet (ومعه _o والنطاق)، والقاعدةُ لا
   تُجيز للمستلِم إلّا تغييرَ read — فتُردّ الكتابة ويبقى غيرَ مقروءٍ على
   الخادم. فيُرسَل read وحدَه دمجاً، ومن المستلِم نفسِه (أو الإدارة) فقط:
   رسالةٌ ليست له لا يُطلب تعليمُها فيُرفض.
   ========================================================================= */
function msgMarkRead(m) {
  if (!m || m.read) return;
  m.read = true;
  const u = (STATE && STATE.user) || {};
  const me = String(u.email || "").toLowerCase();
  const mine = me && String(m.toEmail || "").toLowerCase() === me;
  const admin = u.role === "admin" || u.role === "owner" || (typeof isMgrRole === "function" && isMgrRole(u.role));
  if (!mine && !admin) return;
  /* الرفضُ يُبلَّغ من persistFail داخل persistPatch */
  Promise.resolve(persistPatch("site_messages", m, ["read"])).catch(e => sideFail("read", e));
}
window.msgMarkRead = msgMarkRead;

function msgOpen(id) {
  const m = (DB.site_messages || []).find(x => String(x.id) === String(id));
  if (!m) return;
  if (!m.read) msgMarkRead(m);

  openModal(m.title || "رسالة",
    (m.fromName ? "من " + m.fromName + " — " : "") + timeAgo(m.ts),
    `<div class="msg-body">${esc(m.text || "")}</div>
     ${msgMediaHTML(m)}
     ${m.fromId || m.fromEmail ? `<div class="field full" style="margin-top:16px">
       <label>الرد</label>
       <input id="msg_reply" placeholder="اكتب ردّك…">
       <input type="hidden" id="msg_to" value="${esc(String(m.fromId || ""))}">
       <input type="hidden" id="msg_toMail" value="${esc(String(m.fromEmail || ""))}">
       <input type="hidden" id="msg_subj" value="${esc(String(m.title || ""))}">
     </div>` : ""}`,
    `${m.fromId || m.fromEmail ? `<button class="btn btn-primary" data-action="msg-reply">${ic("send", 16)} إرسال الرد</button>` : ""}
     <button class="btn btn-ghost" data-action="msg-back">← الرسائل</button>`);
}

function msgReply() {
  const text = (val("#msg_reply") || "").trim();
  if (!text) { showToast("اكتب نص الرد", "warn"); return; }

  const u = (STATE && STATE.user) || {};
  const rec = {
    id: "m" + Date.now(),
    title: "رد: " + (val("#msg_subj") || "رسالة"),
    text: text,
    ts: Date.now(),
    toId: val("#msg_to", ""),
    toEmail: String(val("#msg_toMail", "")).toLowerCase(),
    fromId: String(u.uid || u.id || ""),
    fromEmail: String(u.email || "").toLowerCase(),
    fromName: u.name || "",
    read: false, type: "info"
  };
  if (!Array.isArray(DB.site_messages)) DB.site_messages = [];
  DB.site_messages.push(rec);

  Promise.resolve(persistSet("site_messages", rec)).then(function (ok) {
    closeModal();
    showToast(ok ? "أُرسل ردّك" : "تعذّر إرسال الرد — تحقّق من الاتصال", ok ? "success" : "warn");
  });
}

function msgReadAll() {
  const list = myMessages().filter(m => !m.read);
  if (!list.length) { showToast("لا توجد رسائل غير مقروءة"); return; }
  list.forEach(m => msgMarkRead(m));
  window.openMsgPanel();
  showToast("عُلّمت " + toArabicDigits(list.length) + " رسالة كمقروءة");
}

/* شارة العدد على زر الرسائل في الشريط العلوي */
let MSG_SEEN = null;

function updateMsgBadge() {
  const btn = document.getElementById("btnMsg");
  if (!btn) return;
  const n = msgUnread();

  /* تنبيه عند وصول رسالة جديدة بعد أول رسم — لا عند فتح النظام،
     وإلا نبّه المستخدم بكل رسالة قديمة غير مقروءة في كل مرة. */
  if (MSG_SEEN === null) {
    MSG_SEEN = n;
  } else if (n > MSG_SEEN) {
    const fresh = myMessages().filter(m => !m.read)[0];
    showToast("رسالة جديدة" + (fresh && fresh.fromName ? " من " + fresh.fromName : ""), "info");
    MSG_SEEN = n;
  } else if (n < MSG_SEEN) {
    MSG_SEEN = n;
  }
  let b = btn.querySelector(".tb-badge");
  if (!n) { if (b) b.remove(); return; }
  if (!b) {
    b = document.createElement("span");
    b.className = "tb-badge";
    btn.appendChild(b);
  }
  b.textContent = n > 99 ? "٩٩+" : toArabicDigits(n);
}

function myStudents() {
  const u = (STATE && STATE.user) || {};
  const ids = new Set(), names = new Set();
  if (u.studentId) ids.add(String(u.studentId));

  /* أبناءٌ كُثُر: studentId مفردٌ لا يسع إلا واحداً، ووليُّ الأمر قد يكون
     له ثلاثةٌ في ثلاث حلقات. */
  if (Array.isArray(u.studentIds)) u.studentIds.forEach(x => x && ids.add(String(x)));
  const mail = String(u.email || "").toLowerCase();
  const uname = nameKey(u.name);

  (Array.isArray(DB.students) ? DB.students : []).forEach(s => {
    const mine =
         ids.has(String(s.id))
      || (u.uid  && String(s.uid || "") === String(u.uid))
      || (mail   && String(s.email || "").toLowerCase() === mail)
      || (mail   && String(s.guardianEmail || "").toLowerCase() === mail)
      || (u.role === "parent"  && uname && nameKey(s.parent) === uname)
      || (u.role === "student" && uname && nameKey(s.name)   === uname);
    if (mine) { ids.add(String(s.id)); if (s.name) names.add(String(s.name)); }
  });
  return { ids, names };
}

/* النطاق الشخصي الكامل: حلقاتي وطلابي */
function personScope() {
  const u = (STATE && STATE.user) || {};
  const role = u.role;
  const students = Array.isArray(DB.students) ? DB.students : [];

  if (role === "teacher") {
    const circles = myCircles();
    const st = { ids: new Set(), names: new Set() };
    students.forEach(s => {
      const myIds = typeof studentCircleIds === "function"
        ? studentCircleIds(s) : [String(s.circleId || "")];
      if (myIds.some(cid => circles.ids.has(cid)) || circles.names.has(String(s.circle || ""))) {
        st.ids.add(String(s.id));
        if (s.name) st.names.add(String(s.name));
      }
    });
    return { role, circles, students: st };
  }

  if (role === "parent" || role === "student") {
    const st = myStudents();
    const circles = { ids: new Set(), names: new Set() };
    students.forEach(s => {
      if (!st.ids.has(String(s.id))) return;
      if (s.circleId) circles.ids.add(String(s.circleId));
      if (s.circle)   circles.names.add(String(s.circle));
    });
    return { role, circles, students: st };
  }

  return null;   /* admin · supervisor — بلا حصر شخصي */
}

function personFilter(coll, rows) {
  const ps = personScope();
  if (!ps) return rows;
  const S = ps.students, C = ps.circles;
  const u = (STATE && STATE.user) || {};

  const mineByStudent = x => S.ids.has(String(x.studentId || "")) || S.names.has(String(x.student || ""));
  const mineByCircle  = x => C.ids.has(String(x.circleId  || "")) || C.names.has(String(x.circle  || ""));

  if (coll === "students") return rows.filter(s => S.ids.has(String(s.id)) || S.names.has(String(s.name || "")));
  if (coll === "circles")  return rows.filter(c => C.ids.has(String(c.id)) || C.names.has(String(c.name || "")));

  /* الجوائزُ قائمةُ متجرٍ لا سجلٌّ شخصيّ: جائزةُ المسجد لا studentId فيها
     ولا circleId، فكان الحصرُ الشخصيُّ يُسقطها كلَّها — ويُفتح متجرُ الطالب
     فارغاً أبداً وإن امتلأت لوحةُ الإدارة بالجوائز. تمرّ هنا، وrwdEligible
     وحدَها تحكم استحقاقَه (المسجدُ · الحلقةُ · المستوى · العمرُ · المرّات). */
  if (coll === "rewards") {
    return rows.filter(x => !x || mineByStudent(x) || mineByCircle(x) ||
      (!x.studentId && !x.student && !x.circleId && !x.circle));
  }

  if (coll === "plans" || coll === "delays" || coll === "recitations" ||
      coll === "exams" || coll === "attendance" || coll === "reviews") {
    /* تقييمُ الإدارة للمعلّم يسكن reviews بلا طالبٍ ولا حلقة، فيُنسب إلى
       صاحبه بـ teacherId — وإلا حجبه الحصرُ الشخصيُّ عن المعلّم نفسِه
       فلا يرى تقييمَه. ولا يرى بهذا تقييمَ غيره: المطابقةُ بسجلّه هو. */
    const myTid = ps.role === "teacher" && typeof myTeacherRecord === "function"
      ? String((myTeacherRecord() || {}).id || "") : "";
    const mineByTeacher = x => !!myTid && x && x.kind === "teacherRating" &&
      String(x.teacherId || "") === myTid;
    return rows.filter(x => mineByStudent(x) || mineByCircle(x) || mineByTeacher(x));
  }

  if (coll === "teachers") {
    const rec = myTeacherRecord();
    if (ps.role === "teacher") return rows.filter(t => rec && String(t.id) === String(rec.id));
    /* ولي الأمر يرى معلمي أبنائه فقط */
    const teacherNames = new Set();
    (Array.isArray(DB.students) ? DB.students : []).forEach(s => {
      if (S.ids.has(String(s.id)) && s.teacher) teacherNames.add(String(s.teacher));
    });
    (Array.isArray(DB.circles) ? DB.circles : []).forEach(c => {
      if (C.ids.has(String(c.id)) && c.teacher) teacherNames.add(String(c.teacher));
    });
    return rows.filter(t => teacherNames.has(String(t.name || "")));
  }

  if (coll === "notifications" || coll === "site_messages") {
    const mail = String(u.email || "").toLowerCase();
    return rows.filter(n => {
      const targeted = (n.toId != null && n.toId !== "") || n.toEmail;
      if (!targeted) return true;                       /* إشعار عام للجميع */
      if (n.toEmail && mail && String(n.toEmail).toLowerCase() === mail) return true;
      return S.ids.has(String(n.toId || "")) || (u.uid && String(n.toId) === String(u.uid));
    });
  }

  /* بيانات مرجعية (المجمعات · المساجد · البرامج · المستويات …) تبقى مرئية
     لأن الواجهة تعرض أسماءها داخل بطاقات الطالب والخطة. */
  return rows;
}

/* =========================================================================
   مرشّح المستوى
   -------------------------------------------------------------------------
   cur هي بوّابة القراءة: مئةٌ وثمانية عشر موضعاً تمرّ بها. فحصرُ النطاق
   هنا يسري على النظام كلّه بلا تعديل شاشةٍ واحدة.

   ومن كان على مستوى المسجد لا يرى إلا ما يخصّه — لا لأن الشاشة تُخفيه بل
   لأن البيانات لم تصله. */
const LEVEL_SCOPED = {
  circles: "direct", students: "circle", teachers: "direct",
  attendance: "circle", recitations: "circle", assignments: "circle",
  plans: "circle", mushafMarks: "circle", exams: "circle",
  admissions: "direct", storeOrders: "direct", sysAlerts: "circle",

  /* المنشآت نفسُها: كانت خارج الحصر، فيرى المشرفُ على مسجدٍ قائمةَ
     المساجد كلِّها وإن لم يُشرف عليها. */
  mosques: "self", complexes: "self"
};

/* =========================================================================
   levelFilter — تُحيل إلى facilityFilter
   -------------------------------------------------------------------------
   كان في النظام مرشّحان متوازيان يحسبان النطاق كلٌّ بطريقته: هذا يقرأ
   myScope، وذاك يقرأ userScopeOf. ويجريان معاً في cur، فما نجا من أحدهما
   أوقعه الآخر — واختفت المساجدُ الأربعة وإن ظهر عددُها في التبويب.

   facilityFilter أقدمُ وأشمل: تعرف الحلقاتِ والخططَ والحضورَ والتسميع.
   فتُترك وحدها، وهذه تُحيل إليها لئلّا تنكسر مواضعُ تناديها.
   ========================================================================= */
function levelFilter(coll, list) {
  return list;                 /* الحصرُ كلُّه في facilityFilter */
}

/* المؤرشَفُ يخرج من القوائم العاملة ولا يخرج من قاعدة البيانات: سجلُّه
   قائمٌ وخططُه وواجباتُه موصولةٌ به، ويُقرأ من قسم الأرشيف في الإعدادات
   ويُعاد منه. والاستثناءُ للأرشيف نفسِه وإلّا لم يرَ ما يعرضه.

   التصريحُ قبل cur لا بعدها: let لا تُرفع قيمتُها، فقراءتُها قبل سطرها
   ترمي خطأً لو استُدعيت cur أثناء تحميل الملف. */
var ARCHIVE_VIEW = false;

/* حفظُ نتائج القراءة أثناء الرسم (٤٢٥): الشاشةُ الواحدةُ تستدعي cur على
   المجموعة نفسِها مئاتِ المرّات، وكلُّ نداءٍ يُعيد الترشيحَ كلَّه.
   يُفعَّل أثناء بناء الشاشة في mount وحدَه، ويُفرَّغ مع كلّ حفظٍ أو حذف،
   ويُعاد الحسابُ إن تبدّلت المجموعةُ أو طولُها أو وضعُ الأرشيف.
   ويُردّ نسخةً لا الأصل، فلا يُفسد نداءٌ يرتّب نتيجتَه ما يأخذه غيرُه. */
var CUR_MEMO = null;

function cur(coll) {
  const raw = Array.isArray(DB[coll]) ? DB[coll] : [];
  if (CUR_MEMO) {
    const m = CUR_MEMO[coll];
    if (m && m.raw === raw && m.n === raw.length && m.av === ARCHIVE_VIEW) {
      return m.same ? raw : m.copy.slice();
    }
  }
  /* termViewFilter: الحضور والتسميع بالفترة المعروضة — لا تختلط الفترات */
  const out = personFilter(coll, facilityFilter(coll, levelFilter(coll, archiveFilter(coll,
    typeof termViewFilter === "function" ? termViewFilter(coll, raw) : raw))));
  if (CUR_MEMO && Array.isArray(out)) {
    const same = out === raw;
    CUR_MEMO[coll] = { raw, n: raw.length, av: ARCHIVE_VIEW, same, copy: same ? null : out.slice() };
  }
  return out;
}

function archiveFilter(coll, list) {
  if (ARCHIVE_VIEW) return list;
  /* الخطةُ المستبدَلة بخطةٍ أُسندت بعدها لا تُقرأ — تبقى في السجلّ ولا تُحذف */
  if (coll === "plans") return list.filter(x => !x || x.superseded !== true);
  if (coll !== "students" && coll !== "teachers") return list;
  return list.filter(x => !x || x.archived !== true);
}

/* لوحة التنبيهات — كانت مفقودة فكان زر الجرس بلا وظيفة */
/* =========================================================================
   مولّد التنبيهات
   -------------------------------------------------------------------------
   لوحة التنبيهات كانت تعمل وتفتح فارغة أبداً: مجموعة notifications يكتبها
   أربعة مواضع إدارية يدوية فقط، ولا حدث في النظام يولّد تنبيهاً.

   الفحص هنا يجري عند فتح الصفحة لا بمستمعات دائمة، لأن النظام كلّه يقرأ
   البيانات مرة واحدة عند التحميل — ومستمع دائم لكل حدث يضاعف القراءات
   بلا داعٍ.

   ولئلا يتكرّر التنبيه كل مرة، لكلّ حدث مفتاح ثابت (key) يُبنى من نوعه
   وموضوعه وتاريخه، فيُكتب مرة واحدة مهما أُعيد الفحص.
   ========================================================================= */

/* التنبيه يخصّ شخصاً بعينه: toId معرّفه، أو toRole دورٌ كامل */
function notifyKey(k) {
  return (DB.notifications || []).some(n => String(n.key || "") === String(k));
}

function pushNotif(rec) {
  if (!rec || !rec.key || notifyKey(rec.key)) return false;
  if (!Array.isArray(DB.notifications)) DB.notifications = [];

  const full = Object.assign({
    id: "nt" + Date.now() + "-" + Math.random().toString(36).slice(2, 6),
    ts: Date.now(), read: false, type: "info", auto: true
  }, rec);

  DB.notifications.push(full);
  /* =======================================================================
     تنبيهُ النظام التلقائيّ لا يُكتب من جلسةٍ لا تملك كتابتَه
     -----------------------------------------------------------------------
     «تعذّر الحفظ — دورُك «teacher» لا يملك حفظَ هذا السجلّ» مع كلّ فتحةٍ
     وكلّ تحديث: فحوصُ الإقلاع تولّد تنبيهاتٍ تلقائيّةً (auto) وتكتبها في
     notifications. وهي تنبيهاتُ نظامٍ لم يطلبها المعلّم، فيردُّها الخادمُ
     ويُرفع في وجهه تحذيرٌ عن كتابةٍ ليست من عمله — ويتكرّر مع كلّ رسم.

     فالتنبيهُ يبقى في الذاكرة فيراه صاحبُه في جلسته كما كان، ولا تُحاوَل
     كتابتُه إلّا ممّن يملكها. ورقعةُ ٢٠٩ حصرت ترحيلَ الأمس ورصدَ الإجازات
     وأغفلت هذا الموضعَ، وهو مصدرُ التكرار الذي بقي.
     ======================================================================= */
  /* وتنبيهُ إجراءٍ صريحٍ من المستخدم (byUser) يُكتب ولو كانت الجلسةُ جلسةَ
     معلّم: هو من عمله اليوميّ لا من فحوص النظام — كبلوغ الطالبِ سورةً
     جديدةً بعد اعتماد تسميعه — والقواعدُ تُجيز للمعلّم كتابتَه. ولولا هذا
     لبقي التنبيهُ في جهازه ولم يصل الإدارةَ أبداً. */
  if (!full.byUser && typeof maySysWrite === "function" && !maySysWrite()) return true;
  persistSet("notifications", full);
  return true;
}

/* اليوم بصيغة السجلات */
function notifToday() {
  try { return attDate(); } catch (e) { return new Date().toISOString().slice(0, 10); }
}

/* معرّفات الإدارة — التنبيهات الموجَّهة إليهم تُكتب بدورٍ لا بمعرّف،
   فلا تتكرّر بعدد المدراء */
function isAdminRole(r) { return r === "admin" || r === "owner"; }

/* =========================================================================
   الأحداث السبعة
   ========================================================================= */
/* =========================================================================
   تنبيهات البيانات الناقصة
   -------------------------------------------------------------------------
   كانت الملاحظات محشورةً في صفحاتها: «طالبٌ بلا حلقة» في صفحة الخطط،
   و«معلّمٌ بلا أجر» في صفحة المعلّمين، و«خطةٌ غير مرتبطة» في الخطط. فمن لم
   يفتح تلك الصفحة بعينها لم يعلم بالنقص، وقد يمضي الشهر والطالب لا يُحضَّر
   ولا يُسمَّع لأن أحداً لم يمرّ على الصفحة التي تشكو.

   الجرس يجمعها: يُفحص النقص مرّةً ويُبلَّغ به حيث يُنظر.

   ولا تتكرّر: المفتاح ثابتٌ لكلّ حالةٍ في يومها، فيُبلَّغ مرّةً حتى يُصلَح
   أو يبدأ يومٌ جديد.
   ========================================================================= */

/* الأعداد تُختصر في نصٍّ مقروء: خمسة أسماء ثم «وغيرهم» */
function nmList(arr, n) {
  const k = n || 4;
  const names = arr.slice(0, k).map(x => x.name || "—").join(" · ");
  return arr.length > k
    ? names + " و" + toArabicDigits(arr.length - k) + " غيرهم"
    : names;
}

function scanDataGaps() {
  if (typeof pushNotif !== "function") return 0;

  const day = typeof notifToday === "function" ? notifToday() : todayISO();
  let made = 0;
  const fire = (key, title, text, type) => {
    /* نقصُ البيانات شأنٌ إداريّ: كان toRole فارغاً، والفراغُ يُعدّ «بلا
       وجهة» فتصل الطالبَ ووليَّه تنبيهاتُ «معلّمون بلا أجر». */
    if (pushNotif({ key: key + "|" + day, toRole: "admin", title, text,
                    type: type || "warn", label: "نقص بيانات" })) made++;
  };

  /* ---------- الطلاب ---------- */
  const studs = (cur("students") || []).filter(s => s && s.status !== "متوقف");

  const noCircle = studs.filter(s => !s.circleId && (!s.circle || s.circle === "—"));
  if (noCircle.length) {
    fire("gap-stu-circle", "طلابٌ بلا حلقة",
      toArabicDigits(noCircle.length) + " طالباً بلا حلقة: " + nmList(noCircle) +
      " — لا يظهرون في تحضير أحد ولا يُسمَّع لهم.");
  }

  const noPlan = studs.filter(s => {
    if (!s.circleId) return false;             /* بلا حلقة: نُبّه به أعلاه */
    return !(cur("plans") || []).some(p =>
      String(p.studentId) === String(s.id) ||
      (p.student && typeof nameKey === "function" && nameKey(p.student) === nameKey(s.name)));
  });
  if (noPlan.length) {
    fire("gap-stu-plan", "طلابٌ بلا خطة",
      toArabicDigits(noPlan.length) + " طالباً بلا خطة قرآنية: " + nmList(noPlan) +
      " — لا يُولَّد لهم واجب.");
  }

  const noParent = studs.filter(s => !s.parent && !s.phone);
  if (noParent.length) {
    fire("gap-stu-phone", "طلابٌ بلا رقم تواصل",
      toArabicDigits(noParent.length) + " طالباً بلا جوال وليّ أمر: " + nmList(noParent) +
      " — لا تصلهم رسائل الغياب.", "info");
  }

  /* ---------- المعلّمون ---------- */
  const teachers = (cur("teachers") || []).filter(t => t && t.active !== false);

  const noPay = teachers.filter(t =>
    t.payType !== "volunteer" &&
    !(Number(t.salary) || Number(t.wage) || Number(t.hourRate)));
  if (noPay.length) {
    fire("gap-tch-pay", "معلّمون بلا أجر مسجَّل",
      toArabicDigits(noPay.length) + " معلّماً بلا أجر: " + nmList(noPay) +
      " — يُحسب مسيّرهم صفراً.");
  }

  const noTchCircle = teachers.filter(t => {
    if (t.circleId || (t.circle && t.circle !== "—")) return false;
    /* المساعد له حلقةٌ يعمل فيها وإن لم تكن باسمه */
    return !(cur("circles") || []).some(c =>
      Array.isArray(c.assistants) && c.assistants.indexOf(String(t.id)) > -1);
  });
  if (noTchCircle.length) {
    fire("gap-tch-circle", "معلّمون بلا حلقة",
      toArabicDigits(noTchCircle.length) + " معلّماً بلا حلقة: " + nmList(noTchCircle) + ".", "info");
  }

  /* ---------- الحلقات ---------- */
  const circles = (cur("circles") || []).filter(c => c && c.status !== "متوقف");

  const noTeacher = circles.filter(c => !c.teacherId && (!c.teacher || c.teacher === "—"));
  if (noTeacher.length) {
    fire("gap-cir-teacher", "حلقاتٌ بلا معلّم",
      toArabicDigits(noTeacher.length) + " حلقةً بلا معلّم: " + nmList(noTeacher) +
      " — لا يُحضَّر طلابها.");
  }

  const noDays = circles.filter(c => {
    const d = typeof daysToArray === "function" ? daysToArray(c.days) : [];
    return !d.length;
  });
  if (noDays.length) {
    fire("gap-cir-days", "حلقاتٌ بلا أيام",
      toArabicDigits(noDays.length) + " حلقةً بلا أيام محدَّدة: " + nmList(noDays) +
      " — لا تُولَّد لطلابها واجبات.");
  }

  /* ---------- الخطط ---------- */
  const orphan = (cur("plans") || []).filter(p => p && !p.studentId && p.student);
  if (orphan.length) {
    fire("gap-plan-link", "خططٌ غير مرتبطة بطالب",
      toArabicDigits(orphan.length) + " خطةً باسم طالبٍ بلا معرّف — أعِد حفظها لتُربط.");
  }

  const noLevel = (cur("plans") || []).filter(p => p && p.studentId && !p.levelId);
  if (noLevel.length) {
    fire("gap-plan-level", "خططٌ بلا مستوى",
      toArabicDigits(noLevel.length) + " خطةً بلا مستوى مرتبط — لا يُقاس تقدّمها ولا تُرقّى.", "info");
  }

  /* ---------- المستويات والبرامج ---------- */
  const noQty = (cur("levels") || []).filter(l => l && l.status !== "موقوف" && !Number(l.qty));
  if (noQty.length) {
    fire("gap-lv-qty", "مستوياتٌ بلا مقدار",
      toArabicDigits(noQty.length) + " مستوىً بلا مقدار مطلوب: " + nmList(noQty) +
      " — لا يُعرف متى يُتمّه الطالب.", "info");
  }

  /* ---------- الإعدادات ---------- */
  if (!(cur("terms") || []).length) {
    fire("gap-no-term", "لا فترة دراسية",
      "لم تُنشأ فترةٌ بعد — السجلات تُحفظ بلا نسبةٍ إلى دورة، فلا تُفرز التقارير بينها.");
  } else if (typeof activeTerm === "function" && !activeTerm()) {
    fire("gap-no-active-term", "لا فترة نشطة",
      "لا فترةَ مفعَّلة — فعّل واحدةً لتُوسم بها السجلات الجديدة.");
  }

  return made;
}

function scanNotifications() {
  try {
    const today = notifToday();
    let made = 0;

    /* ---------- ١) حساب جديد ينتظر الاعتماد → الإدارة ---------- */
    (DB.users || []).forEach(u => {
      if (!u) return;
      const pending = u.pending === true || (u.active === false && !u.approvedAt);
      if (!pending) return;
      made += pushNotif({
        key: "pending|" + u.id,
        toRole: "admin",
        title: "حساب ينتظر الاعتماد",
        text: (u.name || u.email || "حساب جديد") + " سجّل دخوله ولم يُعتمد بعد.",
        type: "warn", label: "اعتماد"
      }) ? 1 : 0;
    });

    /* ---------- ٢) رسالة جديدة → المستقبِل ---------- */
    (DB.site_messages || []).forEach(m => {
      if (!m || m.read) return;
      const to = String(m.toId || m.toUid || "");
      if (!to) return;
      made += pushNotif({
        key: "msg|" + m.id,
        toId: to,
        title: "رسالة جديدة",
        text: (m.fromName ? "من " + m.fromName + ": " : "") +
              String(m.text || m.title || "").slice(0, 90),
        type: "info", label: "رسالة"
      }) ? 1 : 0;
    });

    /* ---------- ٣) طالب غاب اليوم → المعلم وولي الأمر ---------- */
    (DB.attendance || []).forEach(a => {
      if (!a || a.staffId) return;                 /* سجل دوام موظف لا طالب */
      if (String(a.date) !== String(today)) return;
      if (a.status !== "غائب") return;

      const st = (DB.students || []).find(x => String(x.id) === String(a.studentId));
      if (!st) return;

      /* المعلم */
      if (st.teacherId) {
        made += pushNotif({
          key: "absent|" + a.studentId + "|" + a.date,
          toId: String(st.teacherId),
          title: "غياب اليوم",
          text: (st.name || "طالب") + " غائب اليوم في " + (st.circle || "حلقته") + ".",
          type: "danger", label: "غياب"
        }) ? 1 : 0;
      }

      /* ولي الأمر: حسابه مرتبط بالطالب عبر studentId */
      const guardian = (DB.users || []).find(x =>
        x && x.role === "parent" && String(x.studentId || "") === String(st.id));
      if (guardian) {
        made += pushNotif({
          key: "absentP|" + a.studentId + "|" + a.date,
          toId: String(guardian.uid || guardian.id),
          title: "غياب ابنك اليوم",
          text: (st.name || "الطالب") + " لم يحضر حلقة اليوم.",
          type: "danger", label: "غياب"
        }) ? 1 : 0;
      }
    });

    /* ---------- ٤) ثلاث مرات تأخير في أسبوع → المشرف ---------- */
    const weekAgo = new Date(Date.now() - 7 * 86400000).toISOString().slice(0, 10);
    const lateBy = {};
    (DB.attendance || []).forEach(a => {
      if (!a || a.staffId || a.status !== "متأخر") return;
      if (String(a.date || "") < weekAgo) return;
      const k = String(a.studentId || "");
      if (!k) return;
      (lateBy[k] = lateBy[k] || []).push(a.date);
    });

    Object.keys(lateBy).forEach(sid => {
      if (lateBy[sid].length < 3) return;
      const st = (DB.students || []).find(x => String(x.id) === String(sid));
      if (!st) return;

      /* المفتاح بأحدث تاريخ: يتجدّد التنبيه إن تكرّر التأخّر لاحقاً */
      const last = lateBy[sid].slice().sort().pop();
      made += pushNotif({
        key: "late3|" + sid + "|" + last,
        toRole: "supervisor",
        title: "تأخّر متكرّر",
        text: (st.name || "طالب") + " تأخّر " + lateBy[sid].length +
              " مرات خلال أسبوع في " + (st.circle || "حلقته") + ".",
        type: "warn", label: "متابعة"
      }) ? 1 : 0;
    });

    /* ---------- ٥) خطة متأخرة عن جدولها → المعلم ---------- */
    (DB.plans || []).forEach(p => {
      if (!p) return;
      const total = Number(p.hifzTotal) || 0;
      const done = Number(p.hifzDone) || 0;
      if (!total) return;

      /* التأخّر: مضى من المدة أكثر ممّا أُنجز بفارق الربع فأكثر */
      const start = Number(p.startTs) || Number(p.ts) || 0;
      const weeks = Number(p.weeks) || 0;
      if (!start || !weeks) return;

      const elapsed = (Date.now() - start) / (7 * 86400000);
      const expected = Math.min(1, elapsed / weeks);
      const actual = done / total;
      if (expected - actual < 0.25) return;

      const st = (DB.students || []).find(x => String(x.id) === String(p.studentId));
      const tid = (st && st.teacherId) || p.teacherId;
      if (!tid) return;

      /* أسبوعياً لا يومياً: مفتاح بأسبوع السنة */
      const wk = Math.floor(Date.now() / (7 * 86400000));
      made += pushNotif({
        key: "planLate|" + p.id + "|" + wk,
        toId: String(tid),
        title: "خطة متأخرة",
        text: (p.student || (st && st.name) || "طالب") + ": أُنجز " +
              Math.round(actual * 100) + "٪ والمتوقّع " +
              Math.round(expected * 100) + "٪.",
        type: "warn", label: "خطة"
      }) ? 1 : 0;
    });

    /* ---------- ٦) اختبار ينتظر الاعتماد → الإدارة ---------- */
    (DB.exams || []).forEach(e => {
      if (!e || (e.stage || "") !== "await-ok") return;
      made += pushNotif({
        key: "examOk|" + e.id,
        toRole: "admin",
        title: "اختبار ينتظر الاعتماد",
        text: (e.student || "طالب") + " رُصدت درجاته وينتظر اعتماد الإدارة.",
        type: "info", label: "اختبار"
      }) ? 1 : 0;
    });

    /* ---------- ٧) معلّم لم يسجّل حضوره → الإدارة ---------- */
    const punched = {};
    (DB.attendance || []).forEach(a => {
      if (a && a.staffId && String(a.date) === String(today)) punched[String(a.staffId)] = 1;
    });

    (DB.teachers || []).forEach(t => {
      if (!t || t.active === false) return;
      if (!t.unitId) return;              /* بلا وحدة دوام: لا دوام يُنتظر */
      if (punched[String(t.id)]) return;

      made += pushNotif({
        key: "noPunch|" + t.id + "|" + today,
        toRole: "admin",
        title: "لم يسجّل حضوره",
        text: (t.name || "معلّم") + " لم يسجّل حضوره اليوم.",
        type: "warn", label: "دوام"
      }) ? 1 : 0;
    });

    return made;
  } catch (e) {
    console.warn("scanNotifications:", e);
    return 0;
  }
}

/* =========================================================================
   تنبيهاتي — دالّةٌ واحدة لكلّ الشاشات
   -------------------------------------------------------------------------
   كانت هنا نسخةٌ ثانية تُرجع كلَّ تنبيهٍ بلا وجهةٍ لأيّ داخل: فتنبيهُ
   الإدارة «حساب ينتظر الاعتماد» يصل الطالبَ ووليَّ أمره. ولا تفرز بالطالب،
   فيرى وليُّ الأمر ما يخصّ أبناءَ غيره.

   وُحّدت على myNotifs: تفرز بالمعرّف والدور والطالب، والعامُّ فيها للطالب
   ووليّه وحدهما.
   ========================================================================= */
/* تنبيهُ «تحضير اليوم لم يكتمل» — كان شريطاً في لوحة المعلّم فنُقل إلى
   جرس التنبيهات بطلبٍ صريح. وهو تنبيهٌ محسوبٌ لا مخزَّن: يُبنى من حال
   اليوم عند كلّ فتحٍ ولا يُكتب في قاعدة البيانات، فيختفي وحدَه متى اكتمل
   التحضير. ويُعلَّم بـ virtual ليتخطّاه ما يكتب في السجلّ. */
function tchAttNotif() {
  try {
    if (!STATE || STATE.iface !== "teacher") return null;
    const students = inWorkCircle(cur("students"));
    const total = students.length;
    if (!total) return null;

    const map = attMap(todayISO(), attCircle());
    const left = total - students.filter(s => map[String(s.id)]).length;
    if (left <= 0) return null;

    return {
      id: "virt-tch-att", virtual: true, read: false,
      key: "tch-att", kind: "info", type: "info",
      title: "تحضير اليوم لم يكتمل",
      text: "باقي " + toArabicDigits(left) + " من " + toArabicDigits(total) + " طالباً.",
      ts: Date.now()
    };
  } catch (e) { return null; }
}

function myNotifications() {
  const list = typeof myNotifs === "function" ? myNotifs() : [];
  const v = tchAttNotif();
  return v ? [v].concat(list) : list;
}

/* شارة العدد على زر الجرس */
function updateNotifBadge() {
  const btn = document.getElementById("btnNotif");
  if (!btn) return;
  const n = myNotifications().filter(x => !x.read).length;

  let dot = btn.querySelector(".dot-badge");
  if (!n) { if (dot) dot.remove(); return; }
  if (!dot) {
    dot = document.createElement("span");
    dot.className = "dot-badge";
    btn.appendChild(dot);
  }
  dot.textContent = n > 99 ? "99+" : n;
}

window.notifMarkAllRead = function () {
  let n = 0;
  myNotifications().forEach(x => {
    if (x.read) return;
    /* المحسوبُ لا يُكتب في السجلّ: ليس سجلّاً أصلاً */
    if (x.virtual) return;
    x.read = true;
    notifPersistRead(x);
    n++;
  });
  updateNotifBadge();
  showToast(n ? "عُلّمت " + n + " تنبيهاً كمقروء" : "لا تنبيهات غير مقروءة", "success");
  if (typeof openNotifPanel === "function") openNotifPanel();
};

/* =========================================================================
   وجهة التنبيه
   -------------------------------------------------------------------------
   التنبيه يصف مشكلة ولا يوصّل إليها: «حساب ينتظر الاعتماد» و«اختبار ينتظر
   الاعتماد» و«لم يسجّل حضوره» — كلها تُقرأ ثم يبحث المستخدم بنفسه.
   المفتاح (key) يحمل نوع الحدث ومعرّف صاحبه، فمنه تُشتقّ الوجهة.
   ========================================================================= */
function notifTarget(n) {
  if (!n) return null;

  /* طابورُ الرفع يُنقر ليُرفع: يُعدّ هدفاً ليكون قابلاً للنقر */
  if (n.action === "offq") return { kind: "offq" };

  const key = String(n.key || "");
  const kind = key.split("|")[0];
  const id = key.split("|")[1] || "";

  const T = {
    /* تنبيهات النقص تُوصِّل إلى موضع إصلاحه: القولُ بلا سبيلٍ إليه لا ينفع */
    "gap-stu-circle":     { page: "students", label: "فتح الطلاب" },
    "gap-stu-plan":       { page: "plans",    label: "فتح الخطط" },
    "gap-stu-phone":      { page: "students", label: "فتح الطلاب" },
    "gap-tch-pay":        { page: "teachers", label: "فتح المعلّمين" },
    "gap-tch-circle":     { page: "teachers", label: "فتح المعلّمين" },
    "gap-cir-teacher":    { page: "circles",  label: "فتح الحلقات" },
    "gap-cir-days":       { page: "circles",  label: "فتح الحلقات" },
    "gap-plan-link":      { page: "plans",    label: "فتح الخطط" },
    "gap-plan-level":     { page: "plans",    label: "فتح الخطط" },
    "gap-lv-qty":         { page: "settings", label: "فتح الإعدادات" },
    "gap-no-term":        { page: "settings", label: "فتح الإعدادات" },
    "gap-no-active-term": { page: "settings", label: "فتح الإعدادات" },

    pending:  { page: "admin/users",         label: "فتح الحساب" },
    examOk:   { page: "admin/exams-record",  label: "فتح الاختبار" },
    noPunch:  { page: "admin/duty",          label: "فتح الدوام" },
    "tch-att": { page: "teacher/attendance", label: "فتح التحضير" },
    absent:   { page: "teacher/attendance",  label: "فتح التحضير" },
    absentP:  { page: "teacher/attendance",  label: "فتح التحضير" },
    late3:    { page: "teacher/attendance",  label: "فتح التحضير" },
    planLate: { page: "teacher/plans",       label: "فتح الخطة" },
    msg:      { page: "",                    label: "فتح الرسالة" }
  };

  const t = T[kind];
  return t ? { kind, id, page: t.page, label: t.label } : null;
}

window.notifOpen = function (notifId) {
  /* التنبيهُ المحسوب ليس في DB، فيُفتح من حسابه مباشرةً */
  if (String(notifId).indexOf("virt-") === 0) {
    const v = (typeof tchAttNotif === "function") ? tchAttNotif() : null;
    const tv = v && typeof notifTarget === "function" ? notifTarget(v) : null;
    closePanel();
    if (tv && tv.page) go(tv.page);
    return;
  }

  const n = (DB.notifications || []).find(x => String(x.id) === String(notifId));
  if (!n) return;

  /* طابورُ الرفع: الضغطُ عليه يرفعه — لا يُعلَّم مقروءاً ولا يُفتح شاشةً،
     فهو حالةٌ قائمةٌ لا خبرٌ مضى. */
  if (n.action === "offq") {
    closePanel();
    try { window.offqFlush(); } catch (e) {}
    return;
  }

  /* يُعلَّم مقروءاً بمجرّد فتحه: النقر عليه هو الاطّلاع */
  if (!n.read) { n.read = true; persistSet("notifications", n); }

  const t = notifTarget(n);
  if (!t) { closePanel(); return; }

  closePanel();
  try { if (typeof updateNotifBadge === "function") updateNotifBadge(); } catch (e) {}

  /* الرسالة تُفتح في صندوقها لا في صفحة */
  if (t.kind === "msg") {
    if (typeof window.openMsgPanel === "function") window.openMsgPanel();
    return;
  }

  /* الحساب المعلّق: تُفتح بطاقته مباشرةً بدل البحث عنه في القائمة */
  if (t.kind === "pending" && t.id && typeof window.userView === "function") {
    go(t.page);
    setTimeout(() => { try { window.userView(t.id); } catch (e) {} }, 260);
    return;
  }

  if (t.page) go(t.page);
};

function openNotifPanel() {
  const tint = { success: "b-green", warn: "b-amber", info: "b-blue", danger: "b-red" };
  /* كانت تعرض كل التنبيهات لكل مستخدم — بما فيها الموجَّهة لغيره */
  const list = myNotifications().slice().sort((a, b) => (b.ts || 0) - (a.ts || 0));
  const unread = list.filter(x => !x.read).length;
  const body = list.length
    ? list.map(n => {
        /* كانت البطاقة عرضاً جامداً: تقول «حساب ينتظر الاعتماد» ولا
           تُوصِّل إليه، فيبحث عنه المستخدم بنفسه. */
        const go = notifTarget(n);
        return `<div class="alert-item${go ? " alert-go" : ""}${n.read ? " read" : ""}"
          ${go ? `onclick="window.notifOpen('${jsAttr(n.id)}')" role="button" tabindex="0"` : ""}>
        <div class="alert-ico">${ic("info", 17)}</div>
        <div class="at"><strong>${esc(n.title || "تنبيه")}</strong><small>${esc(n.text || "")}</small>
          ${go ? `<span class="alert-cta">${esc(go.label)}</span>` : ""}</div>
        ${n.type ? badge(n.label || "", tint[n.type] || "b-gray") : ""}
        ${n.ts ? `<span class="alert-time">${new Date(n.ts).toLocaleDateString("ar")}</span>` : ""}
      </div>`; }).join("")
    : `<div class="empty"><div class="empty-mark">${ic("bell", 42)}</div>
        <h4>لا توجد تنبيهات</h4><p>ستظهر التنبيهات هنا فور صدورها.</p></div>`;

  openPanel(`<div class="panel-back" data-action="close-panel"></div>
    <aside class="side-panel" data-stop>
      <div class="panel-head">
        <h3>التنبيهات</h3>
        <div class="ph-sub">${list.length ? list.length + " تنبيهاً" + (unread ? " · " + unread + " غير مقروء" : "") : "لا جديد"}</div>
        ${unread ? `<button class="btn btn-ghost btn-sm" onclick="window.notifMarkAllRead()"
          style="margin-top:8px">تعليم الكل كمقروء</button>` : ""}
        <button class="modal-close" data-action="close-panel">${ic("x", 18)}</button>
      </div>
      <div class="panel-body">${body}</div>
    </aside>`);
  requestAnimationFrame(() => runAnimations($("#panelRoot")));
}

if (typeof window !== "undefined") {
  window.XR               = XR;
  window.XT               = XT;
  window.QB               = QB;
  window.QG               = QG;
  window.XSUP             = XSUP;
  window.XCM              = XCM;
  window.XAU              = XAU;
  window.XCT              = XCT;
  window.MVS              = MVS;
  window.MVC              = MVC;
  window.URQ              = URQ;
  window.DTY              = DTY;
  window.DRP              = DRP;
  window.SRP              = SRP;
  window.ORP              = ORP;
  window.USER_ROLES       = USER_ROLES;
  /* دالة إنشاء حساب الدخول الموحّدة — يستدعيها admin/users.js أيضاً */
  window.createAuthUser   = createAuthUser;
  window.randomPassword   = randomPassword;
  window.authErrMsg       = authErrMsg;
  window.showCredentials  = showCredentials;
  window.scopeOf          = scopeOf;
  window.SET              = SET;
  window.PRG              = PRG;
  window.LVL              = LVL;
  window.SCT              = SCT;
  window.DB               = DB;
  window.STATE            = STATE;
  window.COLLECTIONS      = COLLECTIONS;
  window.PAGES            = PAGES;
  /* قائمةُ المنشأة في shell.js تُبنى من هذين — والملفّان منفصلان */
  window.FAC_SECTIONS     = FAC_SECTIONS;
  window.FAC_KEYS         = FAC_KEYS;
  /* shell.js تعدّ المدراء في شارة القائمة، فتحتاج التمييز نفسه */
  window.isStaffManager   = isStaffManager;
  /* شارةُ بند الكادر في القائمة الجانبية تعدّ ما تعرضه صفحتُه بالضبط:
     خارج المنشآت يرى مديرُ النظام حساباتِ المدراء وحدها، وداخلها يرى
     المعلّمين والمدراءَ معاً — فيُجمعان. وكان العدّادُ يقرأ مجموعةً
     واحدةً في الحالتين فيخالف ما تحته. */
  window.scopeManagersCount = function () {
    try { return scopeSupervisors().length; } catch (e) { return null; }
  };

  window.staffNavCount = function () {
    try {
      /* الشارةُ تعدّ ما يعرضه تبويبا الصفحة: المعلّمون والمشرفون.
         كانت تضمّ مديري المساجد والمجمّعات — وهم في صفحةٍ أخرى — فتقول
         أربعةً والصفحةُ تحتها ثلاثة. */
      const tchs = cur("teachers").filter(x => !isStaffManager(x)).length;
      const sups = scopeSupervisors().filter(u => String(u.role) === "supervisor").length;
      return tchs + sups;
    } catch (e) { return null; }
  };
  window.facDetailCurTab  = facDetailCurTab;
  window.NAV              = NAV;
  window.initials         = initials;
  window.cur              = cur;
  window.currentComplex   = currentComplex;
  window.complexName      = complexName;
  window.openNotifPanel   = openNotifPanel;
  window.renderComplexSelect = renderComplexSelect;
  window.reloadAndRender  = reloadAndRender;
  window.loadAllData      = loadAllData;
  window.loadDataFast     = loadDataFast;
  window.syncTeacherRecord = syncTeacherRecord;
  window.syncStudentRecord = syncStudentRecord;

  /* تشخيص ربط الواجب بالطالب — يُنادى من الكونسول: فحصWaجب() */
  window.فحص = function () {
    const studs = Array.isArray(DB.students) ? DB.students : [];
    const plans = Array.isArray(DB.plans) ? DB.plans : [];
    console.log("=== الطلاب ===");
    console.table(studs.map(s2 => ({ المعرّف: String(s2.id), الاسم: s2.name, الحلقة: s2.circle })));
    console.log("=== الخطط ===");
    console.table(plans.map(p2 => ({ studentId: String(p2.studentId || "—"), الاسم: p2.student, الواجب: p2.current || "—" })));
    console.log("=== الربط ===");
    console.table(studs.map(s2 => {
      const p2 = planOfStudent(s2);
      return { الطالب: s2.name, "له خطة": p2 ? "نعم" : "لا", الواجب: p2 ? (p2.current || "بلا موضع") : "—" };
    }));
    return "تم";
  };

  /* ربط إجباري: يكتب معرّف الطالب في خطته حسب الاسم — للحالات العالقة */
  window.اصلحالربط = function () {
    const studs = Array.isArray(DB.students) ? DB.students : [];
    const plans = Array.isArray(DB.plans) ? DB.plans : [];
    const norm = v => String(v == null ? "" : v).replace(/\s+/g, " ").trim();
    let n = 0;
    plans.forEach(p2 => {
      if (p2.studentId) return;
      const st = studs.find(x => norm(x.name) === norm(p2.student));
      if (st) { p2.studentId = String(st.id); persistSet("plans", p2); n++; }
    });
    mount();
    return "رُبطت " + n + " خطة";
  };
  window.syncAllTeachers   = syncAllTeachers;
  window.mount            = mount;
  window.go               = go;
  window.esc              = esc;
  window.ic               = ic;
  window.badge            = badge;
  window.showToast        = showToast;
  window.openModal        = openModal;
  window.closeModal       = closeModal;
  window.openPanel        = openPanel;
  window.closePanel       = closePanel;
  window.updateConnBadge  = updateConnBadge;
}


/* =========================================================================
   الرجوعُ إلى الخلف لا يعيد صفحةً ميّتة
   -------------------------------------------------------------------------
   «عند الرجوع للخلف تظهر لي قائمةُ تسجيل الدخول، وأيضاً الشريطُ العلويُّ
   الذي أزلناه».

   والسببُ أنّ المتصفّحَ يحفظ الصفحةَ المغادَرةَ كما هي (bfcache) ويعيدها
   عند الرجوع بلا تحميلٍ ولا تشغيلِ كود: فلا يُعاد تنفيذُ ما يُهيّئها.
     • صفحةُ الدخول تُعاد بنموذجها، و onAuthStateChanged لا يُطلق ثانيةً
       فلا تُحوّلك إلى التطبيق كما تفعل عند التحميل الحقيقيّ.
     • وصفحةُ التطبيق تُعاد قبل أن يعرف النظامُ أنّ الواجهةَ واجهةُ معلّم،
       و tchTopbarTrim هي من يُخفي عناصرَ الشريط العلويّ عند المعلّم —
       إخفاءٌ يجري في التشغيل لا في صفحةِ HTML، فالعناصرُ تعود ظاهرة.

   فالصفحةُ المستعادةُ من هذا المخزون تُعاد تحميلاً مرّةً واحدة: فتُهيّأ
   من جديد، فتُحوِّل صفحةُ الدخول، ويُقلَّم الشريطُ كما قُلِّم. ولا دورة:
   الحدثُ بعد الإعادة يأتي بـ persisted = false.
   ========================================================================= */
(function () {
  "use strict";
  if (typeof window === "undefined" || !window.addEventListener) return;
  window.addEventListener("pageshow", function (e) {
    if (e && e.persisted) { try { location.reload(); } catch (x) {} }
  });
})();

/* =========================================================
   فحص التحديثات — يخطر المستخدم فور نشر نسخة جديدة
   ---------------------------------------------------------
   يقرأ version.json كل دقيقة وعند العودة إلى التبويب.
   إن تغيّر رقم النسخة ظهر شريط بزر «تحديث الآن».
   لا يعتمد على الكاش إطلاقاً (cache: no-store).
   ========================================================= */
(function () {
  "use strict";
  if (typeof window === "undefined" || typeof fetch !== "function") return;

  /* =======================================================================
     رقمُ البناء المدفون في هذا الملفّ — يُرفع مع version.json في كلّ نشر
     -----------------------------------------------------------------------
     كان الأساسُ يُقرأ من الخادم في أوّل فحص: `if (CURRENT === null)
     { CURRENT = d.build; return; }` — فيُسجَّل رقمُ الخادم أساساً أيّاً كان
     الملفُّ العاملُ في المتصفّح. فعميلٌ يُشغّل بناءً قديماً يُقارن رقمَ
     الخادم برقم الخادم نفسِه فيجدهما متساويين، فلا يظهر له شريطُ التحديث
     أبداً مهما نُشر — وهو سببُ أن يرى الناشرُ التعديلَ ولا يراه العميل:
     تطبيقٌ مثبَّتٌ لا يُغلق فلا تُعاد الصفحةُ، ولا شريطَ يدعوه لإعادتها.

     والمقارنةُ الآن بين البناء العاملِ فعلاً ورقمِ الخادم، فيصل التنبيهُ
     إلى من حُبس على القديم من أوّل فحص.
     ======================================================================= */
  /* الرقمُ يُقرأ من ?v= في وسم هذا الملفّ: النشرُ يكتب الرقمَ نفسَه في
     ?v= وفي version.json معاً. وكان مكتوباً هنا باليد فقط، فإذا نُشر بناءٌ
     ولم يُرفع هذا السطرُ بقي البناءُ العاملُ أقدمَ من version.json أبداً —
     فيعود الشريطُ بعد كلّ «تحديث الآن» ولا يختفي. والمكتوبُ هنا احتياطٌ
     لوسمٍ بلا ?v= بصيغة البناء. */
  var APP_BUILD = (function () {
    var re = /[?&]v=(\d{8}-\d{4})(?:&|$)/;
    try {
      var s = document.currentScript, m = s && re.exec(s.src || "");
      if (m) return m[1];
      var all = document.getElementsByTagName("script");
      for (var i = 0; i < all.length; i++) {
        var src = all[i].src || "";
        if (/\/js\/app\.js(\?|$)/.test(src) && (m = re.exec(src))) return m[1];
      }
    } catch (e) {}
    return "20261024-0200";
  })();

  var CURRENT = APP_BUILD, SHOWN = false;
  window.APP_BUILD = APP_BUILD;      /* لتشخيصٍ سريع من الطرفيّة عند العميل */

  function verUrl() {
    var base = location.pathname.indexOf("/admin/") > -1 ? "../" : "";
    return base + "version.json?t=" + Date.now();
  }

  function banner() {
    if (SHOWN || document.getElementById("updBar")) return;
    SHOWN = true;
    var el = document.createElement("div");
    el.id = "updBar";
    el.className = "upd-bar";
    el.innerHTML =
      '<span>تم نشر نسخة جديدة من النظام.</span>' +
      '<button type="button" id="updNow">تحديث الآن</button>' +
      '<button type="button" id="updLater" aria-label="لاحقاً">&times;</button>';
    document.body.appendChild(el);
    document.getElementById("updNow").onclick = function () { hardUpdate(); };
    document.getElementById("updLater").onclick = function () { el.remove(); SHOWN = false; };
  }

  /* إعادةُ التحميل وحدَها لا تكفي حين يتحكّم عاملُ الخدمة: إن تعثّرت الشبكة
     ردَّ من مخزونه، فيبقى العميلُ على نسخةٍ قديمة وقد ضغط «تحديث الآن».
     فيُمحى المخزونُ ويُبدَّل العاملُ المنتظر ثمّ تُعاد الصفحة — فلا يبقى
     مصدرٌ للملفات إلا الشبكة. */
  function hardUpdate() {
    var done = function () { location.reload(); };
    var jobs = [];
    try {
      if (window.caches && caches.keys) {
        jobs.push(caches.keys().then(function (ks) {
          return Promise.all(ks.map(function (k) { return caches.delete(k); }));
        }));
      }
      if (navigator.serviceWorker && navigator.serviceWorker.getRegistration) {
        jobs.push(navigator.serviceWorker.getRegistration().then(function (r) {
          if (r && r.waiting) r.waiting.postMessage("skipWaiting");
        }));
      }
    } catch (e) {}
    Promise.all(jobs).catch(function () {}).then(done, done);
  }
  window.mirathHardUpdate = hardUpdate;

  /* =======================================================================
     رقمُ البناء العاملُ ظاهرٌ للعين
     -----------------------------------------------------------------------
     «ما السرُّ في عدم ظهور تعديلاتي؟»: ثلاثةُ احتمالاتٍ تُنتج الشكوى
     نفسَها ولا يُفرَّق بينها إلا بالرقم:
       • لم يصل النشرُ إلى الخادم.
       • وصل الخادمَ ولم يصل الجهاز — عاملُ الخدمة يردّ من مخزونه حين
         تتعثّر الشبكة، والتطبيقُ المثبَّت لا يُغلق فلا تُعاد الصفحة.
       • وصل الجهازَ والتعديلُ في موضعٍ آخرَ غيرِ الذي يُنظر فيه.
     وكان الرقمُ لا يُعرف إلا من كونسولٍ لا يُفتح على هاتف. فصار في ذيل
     القائمة الجانبية: نظرةٌ تقول أيُّ بناءٍ يعمل الآن.

     وإن كان على الخادم أحدثُ منه، قال ذلك وتلوّن — وبضغطِه يُمحى المخزونُ
     ويُبدَّل عاملُ الخدمة وتُعاد الصفحة، وهو عينُ ما يفعله «تحديث الآن».
     ======================================================================= */
  function arD(x) {
    return typeof toArabicDigits === "function" ? toArabicDigits(String(x)) : String(x);
  }

  var SRV = "";                      /* آخرُ بناءٍ أعلنه الخادم */

  function buildChip(srv) {
    var foot = document.querySelector(".sidebar-foot");
    if (!foot) return;
    var el = document.getElementById("bldChip");
    if (!el) {
      el = document.createElement("button");
      el.id = "bldChip";
      el.type = "button";
      el.className = "bld-chip";
      el.title = "رقمُ النسخة العاملة على هذا الجهاز — اضغط لجلب آخر نسخة";
      el.addEventListener("click", function () { hardUpdate(); });
      foot.appendChild(el);
    }
    var mine = String(APP_BUILD).split("-")[1] || String(APP_BUILD);
    var they = srv ? (String(srv).split("-")[1] || "") : "";
    var stale = !!(they && they !== mine);
    el.classList.toggle("old", stale);
    el.textContent = stale
      ? "نسخة " + arD(mine) + " ← " + arD(they) + " جاهزة"
      : "نسخة " + arD(mine);
  }

  function check() {
    /* عاملُ الخدمة لا يُفتَّش عليه من تلقائه في تطبيقٍ مثبَّتٍ لا يُغلق:
       يُطلب فحصُه مع كلّ فحصِ نسخة، فيصل تعديلُ sw.js نفسه. */
    try {
      if (navigator.serviceWorker && navigator.serviceWorker.getRegistration) {
        navigator.serviceWorker.getRegistration()
          .then(function (r) { if (r) r.update(); })
          .catch(function () {});
      }
    } catch (e) {}

    /* يُرسم ولو تعذّر الاتصال: الرقمُ العاملُ معروفٌ بلا خادم */
    buildChip(SRV);

    fetch(verUrl(), { cache: "no-store" })
      .then(function (r) { return r.ok ? r.json() : null; })
      .then(function (d) {
        if (!d || !d.build) return;
        SRV = d.build;
        buildChip(SRV);
        if (d.build !== CURRENT) { CURRENT = d.build; banner(); }
      })
      .catch(function () { /* بلا اتصال — نتجاهل بهدوء */ });
  }

  check();
  setInterval(check, 60000);
  /* القائمةُ الجانبيةُ يبنيها auth.js بعد وصول الحساب، فلا موضعَ للرقم
     لحظةَ أوّل فحص. يُعاد رسمُه في أوّل ثوانٍ حتى يجد ذيلَها. */
  [600, 1500, 3000, 6000].forEach(function (ms) {
    setTimeout(function () { try { buildChip(SRV); } catch (e) {} }, ms);
  });
  document.addEventListener("visibilitychange", function () {
    if (!document.hidden) check();
  });
})();

/* =========================================================================
   رابطُ الطالب — السهمُ يفتح موقعَ الطالب وحسابَه لا صفحةً عشوائية
   -------------------------------------------------------------------------
   كان زرُّ الفتح يذهب إلى index.html?s=<id> ولا أحدَ يقرأ ?s= في النظام،
   فيُفتح التطبيقُ على صفحته الافتراضية أيّاً كان الطالب. يُقرأ الوسمُ الآن
   عند الإقلاع فتُفتح بطاقةُ الطالب نفسِه.

   والمعرّفُ يُقرأ كما هو بعد فكّ الترميز — لا [\w-] وحدَها — فلا ينكسر
   معرّفٌ فيه نقطةٌ أو مسافةٌ أو حروفٌ عربية، ويُبحث باسم المستخدم أيضاً.
   ========================================================================= */
function spUrlStudentId() {
  try {
    const m = (location.search || "").match(/[?&]s=([^&#]*)/);
    return m ? decodeURIComponent(m[1]) : "";
  } catch (e) { return ""; }
}

function spFindStudent(key) {
  const k = String(key || "").trim();
  if (!k) return null;
  const list = Array.isArray(DB.students) ? DB.students : [];
  return list.find(x => x && String(x.id) === k) ||
         list.find(x => x && String(x.idNo || "") === k) ||
         list.find(x => x && String(x.username || "") === k) || null;
}

/* فتحُ موقع الطالب وحسابه داخل النظام */
/* حسابُ الطالب: الملفُّ المرتبط به في «المستخدمون والحسابات».
   يُبحث عنه بمعرّف الطالب أوّلاً — وهو الرباط الرسميّ — ثمّ باسم
   المستخدم، فبعضُ الحسابات القديمة رُبطت به وحدَه. */
function spAccountOf(st) {
  if (!st) return null;
  const users = (Array.isArray(DB.users) ? DB.users : []);
  const sid = String(st.id);
  const eq = (a, b) => a && b && String(a).trim() === String(b).trim();
  const eqi = (a, b) => a && b && String(a).trim().toLowerCase() === String(b).trim().toLowerCase();
  /* الرباطُ الرسميّ أوّلاً، ثمّ ما تربطه المزامنة فعلاً: uid والبريد.
     وأخيراً الاسمُ — وهو ما تبحث به syncStudentRecord نفسُها، فما تجده
     هي يجب أن تجده هذه وإلا قيل «لا حساب» لطالبٍ اعتُمد حسابُه. */
  return users.find(u => u && eq(u.studentId, sid)) ||
         users.find(u => u && Array.isArray(u.studentIds) && u.studentIds.some(x => eq(x, sid))) ||
         users.find(u => u && u.role === "student" && eq(u.uid, st.uid)) ||
         users.find(u => u && u.role === "student" && eqi(u.email, st.email)) ||
         (st.idNo ? users.find(u => u && (eq(u.username, st.idNo) || eq(u.idNo, st.idNo))) : null) ||
         users.find(u => u && u.role === "student" && eq(u.name, st.name)) ||
         null;
}

/* لوحةُ موقع الطالب وحسابه: أين هو في شجرة المنشآت، ومن يحمل حسابه.
   كان الزرُّ يعيد فتحَ البطاقة نفسِها، فإن كانت مفتوحةً لم يتغيّر شيء
   فبدا معطَّلاً — ولم يكن يعرض الحساب أصلاً. */
window.spPlacePanel = function (id) {
  const st = spFindStudent(id);
  if (!st) { showToast("تعذّر العثور على الطالب", "warn"); return; }

  const circle = (cur("circles") || []).find(c =>
    String(c.id) === String(st.circleId) || (st.circle && c.name === st.circle)) || null;
  const mosque = (cur("mosques") || []).find(m =>
    String(m.id) === String(st.mosqueId) || (st.mosque && m.name === st.mosque)) || null;
  const cxId = st.complexId || (mosque && mosque.complexId) || "";
  const complex = (cur("complexes") || []).find(x => String(x.id) === String(cxId)) || null;
  const teacher = (cur("teachers") || []).find(t =>
    String(t.id) === String((circle || {}).teacherId) ||
    (st.teacher && t.name === st.teacher)) || null;

  const acc = spAccountOf(st);
  const row = (label, value, note) => `<div class="sp-place-row">
    <span class="sp-place-lbl">${esc(label)}</span>
    <span class="sp-place-val">${value == null || value === "" ? "—" : esc(String(value))}</span>
    ${note ? `<small>${esc(note)}</small>` : ""}
  </div>`;

  const accBlock = acc
    ? `<div class="sp-place-acc ok">
         ${row("اسم الحساب", acc.name || acc.email || "—")}
         ${row("اسم المستخدم", acc.username || acc.idNo || st.idNo || "—")}
         ${row("البريد", acc.email || "—")}
         ${row("الحالة", acc.active === false ? "موقوف" : "مفعَّل")}
       </div>`
    : !(Array.isArray(DB.users) && DB.users.length)
      ? `<div class="sp-place-acc none">
           ${noteCard(`قائمةُ الحسابات لم تُحمَّل في هذه الصفحة، فلا يمكن بيانُ
             حساب الطالب هنا. افتح «المستخدمون والحسابات» لمعرفة حالته.`)}
         </div>`
    : `<div class="sp-place-acc none">
         ${noteCard(`لا حسابَ مرتبطاً بهذا الطالب بعد — يُنشأ من «المستخدمون
           والحسابات» ويُربط بمعرّفه ليدخل بنفسه ويرى واجباته.`)}
       </div>`;

  openModal("موقع الطالب وحسابه", st.name || "",
    `<div class="sp-place">
      <div class="sp-place-head">${ic("layers", 16)} <strong>الموقع</strong></div>
      ${row("المجمّع", (complex || {}).name || st.complex || "")}
      ${row("المسجد", (mosque || {}).name || st.mosque || "")}
      ${row("الحلقة", (circle || {}).name || st.circle || "")}
      ${row("المعلّم", (teacher || {}).name || st.teacher || "")}
      <div class="sp-place-head">${ic("user", 16)} <strong>الحساب</strong></div>
      ${accBlock}
    </div>`,
    `<button class="btn btn-primary" onclick="window.spPlaceGo('${jsAttr(st.id)}')">
       ${ic("user", 16)} فتح بطاقة الطالب</button>
     ${canDo && canDo("users") ? `<button class="btn btn-ghost"
       onclick="closeModal(); window.go('admin/users')">${ic("users", 16)} الحسابات</button>` : ""}
     <button class="btn btn-ghost" data-action="close-modal">إغلاق</button>`);
};

/* من اللوحة إلى البطاقة: تُضبط الصفحةُ أوّلاً ثمّ تُفتح البطاقة */
window.spPlaceGo = function (id) {
  const st = spFindStudent(id);
  closeModal();
  if (!st) return;
  const iface = typeof allowedIface === "function" ? (allowedIface() || STATE.iface) : STATE.iface;
  if (iface) STATE.iface = iface;
  /* صفحةُ الطلاب مسجَّلةٌ في PAGES ولا تظهر في القائمة الجانبية — فلو
     سُئلت القائمةُ وحدَها لبقي المستخدم حيث هو وانفتحت البطاقةُ فوق
     صفحةٍ لا علاقةَ لها بالطالب. */
  if (PAGES[STATE.iface + "/students"] && STATE.page !== "students") {
    STATE.page = "students";
    mount();
  }
  panelStudent(st.id);
};

window.spLocate = function (id) {
  const st = spFindStudent(id);
  if (!st) { showToast("تعذّر العثور على الطالب", "warn"); return; }
  const r = ((STATE && STATE.user) || {}).role || "";
  if (r === "student" || r === "parent") {
    /* الطالبُ ووليُّ أمره يريان لوحتَهما — ولوليّ الأمر يُختار الابن المقصود */
    if (r === "parent" && typeof window.pickKid === "function") {
      try { window.pickKid(st.id); return; } catch (e) {}
    }
    STATE.page = "dashboard";
    mount();
    return;
  }
  window.spPlacePanel(st.id);
};

let SP_URL_DONE = false;
function spOpenFromUrl() {
  if (SP_URL_DONE) return true;
  const key = spUrlStudentId();
  if (!key) return true;                       /* لا وسمَ في الرابط: لا شأنَ لنا */
  if (!Array.isArray(DB.students) || !DB.students.length) return false;  /* البيانات لم تصل بعد */
  SP_URL_DONE = true;
  const st = spFindStudent(key);
  if (!st) { showToast("الرابط لا يطابق أي طالب", "warn"); return true; }
  const r = ((STATE && STATE.user) || {}).role || "";
  if (r === "student" || r === "parent") { window.spLocate(st.id); return true; }
  /* الرابطُ يفتح بطاقةَ الطالب ثمّ لوحةَ موقعه وحسابه فوقها: إغلاقُ
     اللوحة يترك فاتحَ الرابط على الطالب المقصود لا على صفحةٍ أخرى. */
  try { window.spPlaceGo(st.id); } catch (e) {}
  try { window.spPlacePanel(st.id); } catch (e) {}
  return true;
}

/* =========================================================================
   قارئُ الرابط يعمل أيّاً كان المشغّل
   -------------------------------------------------------------------------
   init() في app.js ليست المدخلَ الوحيد: index.html يشغّل auth.js وصفحاتُ
   الإدارة تشغّل shell.js، وكلاهما يبني الصفحة بنفسه ولا ينادي init. فكان
   قارئُ ?s= الموضوعُ داخلها لا يعمل إلا نظريّاً — ومن نسخ رابطَ الطالب
   ولصقه رأى لوحةَ حسابه هو لا الطالب. يُستأنَف هنا مستقلاً عن المشغّل:
   يفحص كلَّ ثلث ثانية حتى تصل البيانات، ثمّ ينصرف. و SP_URL_DONE يمنع
   التكرارَ إن نودي من init أيضاً.
   ========================================================================= */
(function () {
  if (typeof window === "undefined" || typeof document === "undefined") return;
  let tries = 0;
  const timer = setInterval(function () {
    let done = false;
    try { done = spOpenFromUrl(); } catch (e) { done = true; }
    if (done || ++tries > 40) clearInterval(timer);   /* اثنتا عشرة ثانيةً حدّاً */
  }, 300);
})();

/* =========================================================
   INIT
   ========================================================= */
function on(sel, evt, handler) {
  const el = $(sel);
  if (el) el.addEventListener(evt, handler);
}

async function init() {
  $$(".iface-btn").forEach(b => b.addEventListener("click", () => setIface(b.dataset.iface)));

  on("#btnNotif", "click", () => { if (typeof openNotifPanel === "function") openNotifPanel(); else if (typeof window.openNotifPanel === "function") window.openNotifPanel(); else showToast("لا توجد إشعارات جديدة", "info"); });
  /* زرُّ الرسائل عند المعلّم يفتح شاشةَ المحادثات بفلاترها لا نافذةَ
     «التواصل»: على الشاشات العريضة لا شريطَ سفليَّ يصلها، وقائمتُه
     الجانبيةُ خمسةُ بنودٍ بطلبِه — فكانت الشاشةُ لا تُفتح أصلاً. */
  on("#btnMsg", "click", () => {
    try {
      const r = String((((STATE || {}).user) || {}).role || "");
      if (r === "teacher" && PAGES["teacher/messages"]) { go("messages"); return; }
    } catch (e) {}
    if (typeof openMsgPanel === "function") openMsgPanel(); else if (typeof window.openMsgPanel === "function") window.openMsgPanel(); else showToast("صندوق الرسائل", "info"); });
  on("#btnRefresh", "click", async () => { showToast("جارٍ تحديث البيانات…", "info"); await reloadAndRender(); showToast("تم تحديث البيانات"); });

  on("#menuToggle", "click", () => {
    const sb = $("#sidebar"), ov = $("#overlay");
    if (sb) sb.classList.toggle("open");
    if (ov) ov.classList.toggle("show");
  });
  on("#overlay", "click", () => {
    const sb = $("#sidebar"), ov = $("#overlay");
    if (sb) sb.classList.remove("open");
    if (ov) ov.classList.remove("show");
  });

  document.addEventListener("keydown", (e) => { if (e.key === "Escape") { closeModal(); closePanel(); } });

  renderNav();
  showLoading(true);

  /* الرسم لا ينتظر الشبكة: نرسم من الكاش إن وُجد، ثم نحدّث من السيرفر. */
  await loadDataFast(function (fromCache) {
    if (fromCache) showLoading(false);
    updateConnBadge();
    renderComplexSelect();
    renderNav();
    mount();
    /* رابطُ الطالب ?s= — بعد وصول البيانات، وإلا لم يُوجد الطالب */
    try { if (!fromCache) spOpenFromUrl(); } catch (e) { console.warn("spOpenFromUrl:", e); }
  });

  showLoading(false);
}

if (typeof window !== "undefined") {
  window.initApp = init;
  if (!window.__DEFER_INIT) {
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", init);
    } else {
      init();
    }
  }
}